#==============================================================================
# V198e88 Final Override Layer
# 目标：保持 e81/e80 三协议主体不变，将热更新默认 tcp_notsent_lowat 调整为 26214，并增加 26214/32768/65536/131072 档位。
#==============================================================================

readonly E82_NOTSENT_LOWAT_FILE="$CONFIG_DIR/tcp_notsent_lowat.txt"

_e82_install_self_entrypoint() {
    mkdir -p "$SCRIPT_DIR" "$CONFIG_DIR" 2>/dev/null || true
    if test -f "$SCRIPT_PATH"; then
        cp -f "$SCRIPT_PATH" "$SYMLINK" 2>/dev/null || true
        chmod +x "$SYMLINK" 2>/dev/null || true
        cp -f "$SCRIPT_PATH" "$SCRIPT_DIR/ex198e88.sh" 2>/dev/null || true
        cp -f "$SCRIPT_PATH" "$SCRIPT_DIR/ex198e_latest.sh" 2>/dev/null || true
        chmod +x "$SCRIPT_DIR/ex198e88.sh" "$SCRIPT_DIR/ex198e_latest.sh" 2>/dev/null || true
    fi
    echo "198e88" > "$SCRIPT_VERSION_FILE" 2>/dev/null || true
    hash -r 2>/dev/null || true
    info "V198e88 已安装/刷新快捷入口：$SYMLINK"
}
# 兼容旧流程里仍调用 e77_install_self_entrypoint 的位置。
e77_install_self_entrypoint() { _e82_install_self_entrypoint "$@"; }

_e82_current_notsent_lowat() {
    sysctl -n net.ipv4.tcp_notsent_lowat 2>/dev/null | awk '{$1=$1; print}' || echo "unknown"
}

_e82_persistent_notsent_lowat() {
    if test -f "$NETWORK_OPT_CONF"; then
        awk -F= '/^[[:space:]]*net\.ipv4\.tcp_notsent_lowat[[:space:]]*=/{gsub(/[[:space:]]/,"",$2); v=$2} END{if(v!="") print v; else print "未写入"}' "$NETWORK_OPT_CONF" 2>/dev/null || echo "未写入"
    else
        echo "文件不存在"
    fi
}

_e82_validate_notsent_lowat() {
    local v="${1:-}"
    [[ "$v" =~ ^[0-9]+$ ]] || return 1
    # 允许 0 作为内核默认/禁用式测试值；常用测试档：26214 / 32768 / 65536 / 131072。
    if test "$v" -eq 0 2>/dev/null; then return 0; fi
    test "$v" -ge 4096 2>/dev/null && test "$v" -le 4194304 2>/dev/null
}

_e82_backup_and_strip_notsent_conflicts() {
    mkdir -p "$BACKUP_DIR/sysctl" 2>/dev/null || true
    local f
    for f in /etc/sysctl.conf /etc/sysctl.d/*.conf; do
        test -f "$f" || continue
        if test "$(readlink -f "$f" 2>/dev/null || echo "$f")" = "$(readlink -f "$NETWORK_OPT_CONF" 2>/dev/null || echo "$NETWORK_OPT_CONF")"; then
            continue
        fi
        if grep -Eq '^[[:space:]]*net\.ipv4\.tcp_notsent_lowat[[:space:]]*=' "$f" 2>/dev/null; then
            cp -af "$f" "$BACKUP_DIR/sysctl/$(basename "$f").notsent.e82.$(date +%Y%m%d_%H%M%S).bak" 2>/dev/null || true
            sed -i -E '/^[[:space:]]*net\.ipv4\.tcp_notsent_lowat[[:space:]]*=/d' "$f" 2>/dev/null || true
            warn "已从冲突文件中移除 tcp_notsent_lowat：$f"
        fi
    done
}

_e82_set_tcp_notsent_lowat() {
    local val="${1:-}" label="${2:-手动}"
    if ! _e82_validate_notsent_lowat "$val"; then
        error "tcp_notsent_lowat 数值非法：$val；允许 0 或 4096~4194304。"
        return 1
    fi

    mkdir -p /etc/sysctl.d "$CONFIG_DIR" "$BACKUP_DIR/sysctl" 2>/dev/null || true
    _e82_backup_and_strip_notsent_conflicts

    if test -f "$NETWORK_OPT_CONF"; then
        cp -af "$NETWORK_OPT_CONF" "$BACKUP_DIR/sysctl/99-network-optimized.conf.notsent.e82.$(date +%Y%m%d_%H%M%S).bak" 2>/dev/null || true
    else
        touch "$NETWORK_OPT_CONF" 2>/dev/null || true
    fi

    sed -i -E '/^[[:space:]]*net\.ipv4\.tcp_notsent_lowat[[:space:]]*=/d' "$NETWORK_OPT_CONF" 2>/dev/null || true
    cat >> "$NETWORK_OPT_CONF" <<EOF_E82_NOTSENT

# V198e88 ${label}: TCP unsent write queue low watermark. 常用：26214=极低排队；32768=低延迟；65536=均衡；131072=高吞吐。
# E135: legacy dynamic tcp_notsent_lowat owner disabled.
EOF_E82_NOTSENT

    echo "$val" > "$E82_NOTSENT_LOWAT_FILE" 2>/dev/null || true

    if sysctl -w "net.ipv4.tcp_notsent_lowat=${val}" >/tmp/xray-notsent-e82.log 2>&1; then
        info "运行态已应用：net.ipv4.tcp_notsent_lowat=${val}"
    else
        warn "当前内核可能不支持该值或被云厂商限制；永久配置已写入，详情：/tmp/xray-notsent-e82.log"
        sed 's/^/    /' /tmp/xray-notsent-e82.log 2>/dev/null || true
    fi

    # 只加载目标文件，避免其它 sysctl.d 文件把刚写入的值覆盖。
    if declare -F _e65_apply_sysctl_file_line_by_line >/dev/null 2>&1; then
        _e65_apply_sysctl_file_line_by_line "$NETWORK_OPT_CONF" >/dev/null 2>&1 || true
        sysctl -w "net.ipv4.tcp_notsent_lowat=${val}" >/dev/null 2>&1 || true
    else
        sysctl -p "$NETWORK_OPT_CONF" >/dev/null 2>&1 || true
        sysctl -w "net.ipv4.tcp_notsent_lowat=${val}" >/dev/null 2>&1 || true
    fi

    info "永久配置已写入：$NETWORK_OPT_CONF"
    _e82_show_tcp_notsent_lowat_state
}

_e82_show_tcp_notsent_lowat_state() {
    local run perm saved
    run=$(_e82_current_notsent_lowat)
    perm=$(_e82_persistent_notsent_lowat)
    saved=$(cat "$E82_NOTSENT_LOWAT_FILE" 2>/dev/null || echo "未记录")
    echo ""
    echo -e "  ${cyan}tcp_notsent_lowat 状态：${none}"
    printf "    %-22s %s\n" "运行态(sysctl):" "$run"
    printf "    %-22s %s\n" "永久配置($NETWORK_OPT_CONF):" "$perm"
    printf "    %-22s %s\n" "e82记录:" "$saved"
    echo ""
    echo "    26214  = 极低排队/极低 notsent：网页响应优先，可能限制高 RTT 大吞吐。"
    echo "    32768  = 低延迟倾向：小包交互更灵敏，吞吐比 26214 更稳。"
    echo "    65536  = 均衡倾向：日常翻墙、网页、视频、下载混合使用。"
    echo "    131072 = 高吞吐倾向：高 RTT、大文件、测速更激进。"
}

_e82_show_notsent_conflicts() {
    echo ""
    echo -e "  ${cyan}tcp_notsent_lowat 定义来源扫描：${none}"
    grep -R "^[[:space:]]*net\.ipv4\.tcp_notsent_lowat[[:space:]]*=" \
      /etc/sysctl.conf /etc/sysctl.d /usr/lib/sysctl.d /lib/sysctl.d 2>/dev/null | sed 's/^/    /' || true
}

_e82_manual_tcp_notsent_lowat() {
    local v=""
    echo ""
    warn "手动值建议在 26214 / 32768 / 65536 / 131072 中测试；过大可能增加排队延迟，过小可能限制高 RTT 吞吐。"
    read -rp "请输入 tcp_notsent_lowat 数值（0 或 4096~4194304，默认 26214）: " v || true
    v=${v:-26214}
    _e82_set_tcp_notsent_lowat "$v" "手动输入"
}

# 覆盖 13) 网络参数菜单：新增 tcp_notsent_lowat 显示、26214/32768/65536/131072 切换和手动永久应用。
do_network_params_menu_e56() {
    while true; do
        clear
        title "网络参数应用中心（V198e88：均衡/高吞吐/手动 + notsent_lowat 永久管理；热更新默认26214）"
        show_network_buffer_params_e56
        _e82_show_tcp_notsent_lowat_state
        show_network_sysctl_conflicts_e58
        _e82_show_notsent_conflicts
        echo ""
        echo "  1) 应用默认高吞吐档：7990577 / 97108868（默认 tcp_notsent_lowat=131072）"
        echo "  2) 应用均衡稳态档：3990577 / 57108868"
        echo "  3) 手动输入 rmem/wmem/tcp_rmem/tcp_wmem 参数（保留完整协议栈其它项）"
        echo "  4) 重新加载 $NETWORK_OPT_CONF"
        echo "  5) 查看该永久配置文件完整内容"
        echo "  6) 清理所有关键网络冲突定义并重新应用默认高吞吐档"
        echo "  7) 切换 tcp_notsent_lowat = 26214（极低排队/网页响应优先，永久应用）"
        echo "  8) 切换 tcp_notsent_lowat = 32768（低延迟响应档，永久应用）"
        echo "  9) 切换 tcp_notsent_lowat = 65536（均衡推荐档，永久应用）"
        echo "  10) 切换 tcp_notsent_lowat = 131072（稳态/高吞吐档，永久应用）"
        echo "  11) 手动输入 tcp_notsent_lowat 数值并永久应用"
        echo "  12) 仅查看 tcp_notsent_lowat 当前值与定义来源"
        echo "  0) 返回主菜单"
        hr
        local opt=""; read -rp "请选择操作: " opt || true
        case "${opt:-}" in
            1) apply_default_full_sysctl_profile_e60; _e82_set_tcp_notsent_lowat 131072 "默认高吞吐档"; _e52_pause ;;
            2) apply_balanced_network_buffer_params_e63; _e52_pause ;;
            3) manual_network_buffer_params_e56; _e52_pause ;;
            4) remove_legacy_hotupdate_sysctl_e61; if test -f "$NETWORK_OPT_CONF"; then if declare -F _e65_apply_sysctl_file_line_by_line >/dev/null 2>&1; then _e65_apply_sysctl_file_line_by_line "$NETWORK_OPT_CONF" || true; else sysctl -p "$NETWORK_OPT_CONF" || true; fi; _e63_force_runtime_key_values 1 31 2>/dev/null || true; else warn "文件不存在：$NETWORK_OPT_CONF"; fi; _e52_pause ;;
            5) if test -f "$NETWORK_OPT_CONF"; then sed 's/^/    /' "$NETWORK_OPT_CONF"; else warn "文件不存在：$NETWORK_OPT_CONF"; fi; _e52_pause ;;
            6) cleanup_network_sysctl_conflicts_e58; apply_default_full_sysctl_profile_e60; _e82_set_tcp_notsent_lowat 131072 "冲突清理后默认高吞吐档"; _e52_pause ;;
            7) _e82_set_tcp_notsent_lowat 26214 "极低排队响应档"; _e52_pause ;;
            8) _e82_set_tcp_notsent_lowat 32768 "低延迟响应档"; _e52_pause ;;
            9) _e82_set_tcp_notsent_lowat 65536 "均衡推荐档"; _e52_pause ;;
            10) _e82_set_tcp_notsent_lowat 131072 "稳态高吞吐档"; _e52_pause ;;
            11) _e82_manual_tcp_notsent_lowat; _e52_pause ;;
            12) _e82_show_tcp_notsent_lowat_state; _e82_show_notsent_conflicts; _e52_pause ;;
            0) return ;;
            *) warn "无效操作。"; sleep 1 ;;
        esac
    done
}

# e80 热更新：保留 e79 三协议，不重构节点，只刷新入口与 tcp_notsent_lowat 管理能力。
hot_update_from_legacy() {
    title "V198e88：稳态热更新（保留 e81 能力 + 默认 tcp_notsent_lowat=26214）"
    set +e
    trap - ERR

    mkdir -p "$CONFIG_DIR" "$SCRIPT_DIR" "$BACKUP_DIR" 2>/dev/null || true
    _e82_install_self_entrypoint || true
    local bdir
    if declare -F e76_state_snapshot >/dev/null 2>&1; then
        bdir=$(e76_state_snapshot "hotupdate_e82")
    else
        bdir="$BACKUP_DIR/hotupdate_e82_$(date +%Y%m%d_%H%M%S)"; mkdir -p "$bdir" 2>/dev/null || true
        cp -a "$CONFIG" "$bdir/config.json.bak" 2>/dev/null || true
        cp -a "$NETWORK_OPT_CONF" "$bdir/99-network-optimized.conf.bak" 2>/dev/null || true
    fi
    info "已创建热更新快照：$bdir"

    repair_dns_if_broken || true
    install_update_dat || true
    fix_xray_systemd_limits || true
    apply_hotupdate_fast_sysctl || true
    remove_xray_env_buffer || true

    # e82 热更新默认极低排队/响应档：26214。用户仍可在 13 里切换 32768 / 65536 / 131072 或手动值。
    _e82_set_tcp_notsent_lowat 26214 "热更新默认极低排队响应值" || true

    if declare -F e76_config_semantic_ok >/dev/null 2>&1 && e76_config_semantic_ok "$CONFIG"; then
        force_apply_xray_core_defaults_e52 >/dev/null 2>&1 || true
        harden_xray_reality_profile >/dev/null 2>&1 || true
        fix_permissions || true
        systemctl daemon-reload >/dev/null 2>&1 || true
        if systemctl restart xray >/dev/null 2>&1; then
            info "Xray 已基于有效现网配置重启。"
        else
            warn "Xray 重启失败；可执行：journalctl -u xray --no-pager -n 80"
        fi
    else
        warn "未发现有效现网节点配置。V198e88 已安装为 xrv；请执行 xrv → 1 重新搭建。"
    fi

    echo "198e88" > "$SCRIPT_VERSION_FILE" 2>/dev/null || true
    _e82_show_tcp_notsent_lowat_state || true
    if declare -F e77_audit_runtime_state >/dev/null 2>&1; then e77_audit_runtime_state || true; fi
    set -e
    trap '_err_handler $? $LINENO "$BASH_COMMAND"' ERR
    info "V198e88 热更新完成。现在可输入：xrv；热更新默认 tcp_notsent_lowat=26214；进入 13 可切换 26214/32768/65536/131072/手动。"
    return 0
}

