        if declare -F show_network_buffer_params_e56 >/dev/null 2>&1; then show_network_buffer_params_e56; fi
        _e88_show_tcp_notsent_lowat_state
        _e88_show_core_network_state
        _e88_show_menu13_manual_notes
        if declare -F show_network_sysctl_conflicts_e58 >/dev/null 2>&1; then show_network_sysctl_conflicts_e58; fi
        _e88_show_notsent_conflicts
        echo ""
        echo "  1) 应用默认高吞吐档：7990577 / 97108868（并切 notsent=131072）"
        echo "  2) 应用均衡稳态档：3990577 / 57108868（保留当前 notsent）"
        echo "  3) 手动输入 rmem/wmem/tcp_rmem/tcp_wmem 参数（保留完整协议栈其它项）"
        echo "  4) 重新加载 $NETWORK_OPT_CONF"
        echo "  5) 查看该永久配置文件完整内容"
        echo "  6) 清理所有关键网络冲突定义并重新应用默认高吞吐档（并切 notsent=131072）"
        echo "  7) 切换 tcp_notsent_lowat = 26214（极低排队/网页响应优先，永久应用）"
        echo "  8) 切换 tcp_notsent_lowat = 32768（低延迟响应档，永久应用）"
        echo "  9) 切换 tcp_notsent_lowat = 65536（均衡推荐档，永久应用）"
        echo "  10) 切换 tcp_notsent_lowat = 131072（稳态/高吞吐档，永久应用）"
        echo "  11) 手动输入 tcp_notsent_lowat 数值并永久应用"
        echo "  12) 仅查看 tcp_notsent_lowat 当前值与定义来源"
        echo "  13) 查看影响翻墙网络速度的参数说明"
