        echo "  18) 切换 tcp_adv_win_scale=2 + tcp_app_win=31（高 RTT 实验）"
        echo "  19) 手动输入 tcp_adv_win_scale / tcp_app_win（组合输入）"
        echo "  20) 设置 txqueuelen = 1000（低排队实验）"
        echo "  21) 设置 txqueuelen = 3000（推荐稳态）"
