_e89_perl_replace_define() {
    local file="$1" name="$2" value="$3"
    NAME="$name" VALUE="$value" perl -0pi -e 'my $n=$ENV{NAME}; my $v=$ENV{VALUE}; s/^#define\s+\Q$n\E\s+[^\n]*/#define $n $v/mg' "$file" 2>/dev/null || true
}

_e89_perl_replace_const() {
    local file="$1" name="$2" value="$3"
    if ! grep -q "$name" "$file" 2>/dev/null; then warn "源码无参数 $name，跳过。"; return 0; fi
    NAME="$name" VALUE="$value" perl -0pi -e 'my $n=$ENV{NAME}; my $v=$ENV{VALUE}; s/static\s+const\s+([A-Za-z0-9_]+)\s+\Q$n\E\s*=\s*[^;]+;/static const $1 $n = $v;/sg' "$file" 2>/dev/null || true
}

_e89_perl_replace_array() {
    local file="$1" body="$2"
    BODY="$body" perl -0pi -e 'my $b=$ENV{BODY}; s/static\s+const\s+int\s+bbr_pacing_gain\[\]\s*=\s*\{.*?\};/static const int bbr_pacing_gain[] = {\n$b\n};/sg' "$file" 2>/dev/null || true
}

_e89_bool_c() { if test "${1:-0}" = "1"; then echo "true"; else echo "false"; fi; }

_e89_patch_bbr_source_from_conf() {
    local src="$1" conf="$2" kind="$3"
    # shellcheck disable=SC1090
    source "$conf"
    if test "$kind" = "bbr3"; then
        _e89_perl_replace_define "$src" "BBR_VERSION" "$BBR_VERSION"
        _e89_perl_replace_define "$src" "BW_SCALE" "$BW_SCALE"
        _e89_perl_replace_define "$src" "BBR_SCALE" "$BBR_SCALE"
        _e89_perl_replace_const "$src" "bbr_min_rtt_win_sec" "$BBR_MIN_RTT_WIN_SEC"
        _e89_perl_replace_const "$src" "bbr_probe_rtt_mode_ms" "$BBR_PROBE_RTT_MODE_MS"
        _e89_perl_replace_const "$src" "bbr_probe_rtt_win_ms" "$BBR_PROBE_RTT_WIN_MS"
        _e89_perl_replace_const "$src" "bbr_probe_rtt_cwnd_gain" "BBR_UNIT * $BBR_PROBE_RTT_CWND_GAIN / 100"
        _e89_perl_replace_const "$src" "bbr_tso_rtt_shift" "$BBR_TSO_RTT_SHIFT"
        _e89_perl_replace_const "$src" "bbr_pacing_margin_percent" "$BBR_PACING_MARGIN_PERCENT"
        _e89_perl_replace_const "$src" "bbr_startup_pacing_gain" "BBR_UNIT * $BBR_STARTUP_PACING_GAIN / 100 + 1"
        _e89_perl_replace_const "$src" "bbr_startup_cwnd_gain" "BBR_UNIT * $BBR_STARTUP_CWND_GAIN / 100"
        if test "${BBR_DRAIN_GAIN_MODE:-auto}" = "manual"; then _e89_perl_replace_const "$src" "bbr_drain_gain" "BBR_UNIT * $BBR_DRAIN_GAIN / 100"; else _e89_perl_replace_const "$src" "bbr_drain_gain" "BBR_UNIT * 100 / $BBR_STARTUP_PACING_GAIN"; fi
        _e89_perl_replace_const "$src" "bbr_cwnd_gain" "BBR_UNIT * $BBR_CWND_GAIN / 100"
        _e89_perl_replace_array "$src" "    BBR_UNIT * $BBR_PACING_GAIN_UP / 100, /* UP */\n    BBR_UNIT * $BBR_PACING_GAIN_DOWN / 100, /* DOWN */\n    BBR_UNIT * $BBR_PACING_GAIN_CRUISE / 100, /* CRUISE */\n    BBR_UNIT * $BBR_PACING_GAIN_REFILL / 100, /* REFILL */"
        _e89_perl_replace_const "$src" "bbr_cwnd_min_target" "$BBR_CWND_MIN_TARGET"
        _e89_perl_replace_const "$src" "bbr_full_bw_thresh" "BBR_UNIT * $BBR_FULL_BW_THRESH / 100"
        _e89_perl_replace_const "$src" "bbr_full_bw_cnt" "$BBR_FULL_BW_CNT"
        _e89_perl_replace_const "$src" "bbr_extra_acked_gain" "BBR_UNIT * $BBR_EXTRA_ACKED_GAIN / 100"
        _e89_perl_replace_const "$src" "bbr_extra_acked_win_rtts" "$BBR_EXTRA_ACKED_WIN_RTTS"
        _e89_perl_replace_const "$src" "bbr_ack_epoch_acked_reset_thresh" "$BBR_ACK_EPOCH_ACKED_RESET_THRESH"
        _e89_perl_replace_const "$src" "bbr_extra_acked_max_us" "$BBR_EXTRA_ACKED_MAX_US"
        _e89_perl_replace_const "$src" "bbr_precise_ece_ack" "$(_e89_bool_c "$BBR_PRECISE_ECE_ACK")"
        _e89_perl_replace_const "$src" "bbr_ecn_max_rtt_us" "$BBR_ECN_MAX_RTT_US"
        _e89_perl_replace_const "$src" "bbr_beta" "BBR_UNIT * $BBR_BETA / 100"
        _e89_perl_replace_const "$src" "bbr_ecn_alpha_gain" "BBR_UNIT * 1 / $BBR_ECN_ALPHA_GAIN_DIV"
        _e89_perl_replace_const "$src" "bbr_ecn_alpha_init" "BBR_UNIT * $BBR_ECN_ALPHA_INIT / 100"
        _e89_perl_replace_const "$src" "bbr_ecn_factor" "BBR_UNIT * $BBR_ECN_FACTOR_NUM / $BBR_ECN_FACTOR_DIV"
        _e89_perl_replace_const "$src" "bbr_ecn_thresh" "BBR_UNIT * $BBR_ECN_THRESH / 100"
        _e89_perl_replace_const "$src" "bbr_ecn_reprobe_gain" "BBR_UNIT * $BBR_ECN_REPROBE_GAIN / 100"
        _e89_perl_replace_const "$src" "bbr_loss_thresh" "BBR_UNIT * $BBR_LOSS_THRESH_PERMILLE / 1000"
        _e89_perl_replace_const "$src" "bbr_loss_probe_recovery" "$(_e89_bool_c "$BBR_LOSS_PROBE_RECOVERY")"
        _e89_perl_replace_const "$src" "bbr_full_loss_cnt" "$BBR_FULL_LOSS_CNT"
        _e89_perl_replace_const "$src" "bbr_full_ecn_cnt" "$BBR_FULL_ECN_CNT"
        _e89_perl_replace_const "$src" "bbr_inflight_headroom" "BBR_UNIT * $BBR_INFLIGHT_HEADROOM / 100"
        _e89_perl_replace_const "$src" "bbr_bw_probe_cwnd_gain" "$BBR_BW_PROBE_CWND_GAIN"
        _e89_perl_replace_const "$src" "bbr_bw_probe_max_rounds" "$BBR_BW_PROBE_MAX_ROUNDS"
        _e89_perl_replace_const "$src" "bbr_bw_probe_rand_rounds" "$BBR_BW_PROBE_RAND_ROUNDS"
        _e89_perl_replace_const "$src" "bbr_bw_probe_base_us" "$BBR_BW_PROBE_BASE_US"
        _e89_perl_replace_const "$src" "bbr_bw_probe_rand_us" "$BBR_BW_PROBE_RAND_US"
        _e89_perl_replace_const "$src" "bbr_fast_path" "$(_e89_bool_c "$BBR_FAST_PATH")"
        _e89_perl_replace_const "$src" "bbr_fast_ack_mode" "$(_e89_bool_c "$BBR_FAST_ACK_MODE")"
    else
        _e89_perl_replace_define "$src" "BW_SCALE" "$BW_SCALE"
        _e89_perl_replace_define "$src" "BBR_SCALE" "$BBR_SCALE"
        NAME="CYCLE_LEN" VALUE="$CYCLE_LEN" perl -0pi -e 'my $v=$ENV{VALUE}; s/(CYCLE_LEN\s*=\s*)[0-9]+/$1$v/sg' "$src" 2>/dev/null || true
        _e89_perl_replace_const "$src" "bbr_min_rtt_win_sec" "$BBR_MIN_RTT_WIN_SEC"
        _e89_perl_replace_const "$src" "bbr_probe_rtt_mode_ms" "$BBR_PROBE_RTT_MODE_MS"
        _e89_perl_replace_const "$src" "bbr_min_tso_rate" "$BBR_MIN_TSO_RATE"
        _e89_perl_replace_const "$src" "bbr_pacing_margin_percent" "$BBR_PACING_MARGIN_PERCENT"
        _e89_perl_replace_const "$src" "bbr_high_gain" "BBR_UNIT * $BBR_HIGH_GAIN / 100 + 1"
        if test "${BBR_DRAIN_GAIN_MODE:-auto}" = "manual"; then _e89_perl_replace_const "$src" "bbr_drain_gain" "BBR_UNIT * $BBR_DRAIN_GAIN / 100"; else _e89_perl_replace_const "$src" "bbr_drain_gain" "BBR_UNIT * 100 / $BBR_HIGH_GAIN"; fi
        _e89_perl_replace_const "$src" "bbr_cwnd_gain" "BBR_UNIT * $BBR_CWND_GAIN / 100"
        _e89_perl_replace_array "$src" "    BBR_UNIT * $BBR_PACING_GAIN_0 / 100,\n    BBR_UNIT * $BBR_PACING_GAIN_1 / 100,\n    BBR_UNIT * $BBR_PACING_GAIN_2 / 100,\n    BBR_UNIT * $BBR_PACING_GAIN_3 / 100,\n    BBR_UNIT * $BBR_PACING_GAIN_4 / 100,\n    BBR_UNIT * $BBR_PACING_GAIN_5 / 100,\n    BBR_UNIT * $BBR_PACING_GAIN_6 / 100,\n    BBR_UNIT * $BBR_PACING_GAIN_7 / 100,"
        _e89_perl_replace_const "$src" "bbr_cycle_rand" "$BBR_CYCLE_RAND"
        _e89_perl_replace_const "$src" "bbr_cwnd_min_target" "$BBR_CWND_MIN_TARGET"
        _e89_perl_replace_const "$src" "bbr_full_bw_thresh" "BBR_UNIT * $BBR_FULL_BW_THRESH / 100"
        _e89_perl_replace_const "$src" "bbr_full_bw_cnt" "$BBR_FULL_BW_CNT"
        _e89_perl_replace_const "$src" "bbr_lt_intvl_min_rtts" "$BBR_LT_INTVL_MIN_RTTS"
        _e89_perl_replace_const "$src" "bbr_lt_loss_thresh" "$BBR_LT_LOSS_THRESH"
        _e89_perl_replace_const "$src" "bbr_lt_bw_ratio" "BBR_UNIT / $BBR_LT_BW_RATIO_DIV"
        _e89_perl_replace_const "$src" "bbr_lt_bw_diff" "$BBR_LT_BW_DIFF_NUM / $BBR_LT_BW_DIFF_DIV"
        _e89_perl_replace_const "$src" "bbr_lt_bw_max_rtts" "$BBR_LT_BW_MAX_RTTS"
        _e89_perl_replace_const "$src" "bbr_extra_acked_gain" "BBR_UNIT * $BBR_EXTRA_ACKED_GAIN / 100"
        _e89_perl_replace_const "$src" "bbr_extra_acked_win_rtts" "$BBR_EXTRA_ACKED_WIN_RTTS"
        _e89_perl_replace_const "$src" "bbr_ack_epoch_acked_reset_thresh" "$BBR_ACK_EPOCH_ACKED_RESET_THRESH"
        _e89_perl_replace_const "$src" "bbr_extra_acked_max_us" "$BBR_EXTRA_ACKED_MAX_US"
    fi
    # 替换模式保持算法名为 bbr，不改成 bbrx；确保 MODULE_ALIAS 也仍指向 bbr。
    perl -0pi -e 's/\.name\s*=\s*"bbrx3?"/.name = "bbr"/g; s/MODULE_ALIAS_TCP_CONGESTION\("bbrx3?"\)/MODULE_ALIAS_TCP_CONGESTION("bbr")/g' "$src" 2>/dev/null || true
}

_e89_install_new_ko_to_original_path() {
    local newko="$1" orig="$2"
    test -f "$newko" || return 1
    test -n "$orig" || return 1
    mkdir -p "$(dirname "$orig")" 2>/dev/null || true
    case "$orig" in
        *.ko.xz) xz -T0 -f -c "$newko" > "$orig" ;;
        *.ko.zst) zstd -q -f -c "$newko" > "$orig" ;;
        *.ko.gz) gzip -c "$newko" > "$orig" ;;
        *) cp -af "$newko" "$orig" ;;
    esac
}

_e89_build_replace_bbr() {
    local kind="$1" conf="$2" cfgv modp src work newko bdir release_now
    title "V198e89：编译并同名替换 tcp_bbr.ko（算法名仍为 bbr）"
    _e89_bbr_prepare_dirs
    cfgv="$(_e89_bbr_kconfig_value)"
    modp="$(_e89_bbr_mod_path)"
    src="$(_e89_bbr_find_source 2>/dev/null || true)"
    if test "$cfgv" != "m"; then
        error "当前 CONFIG_TCP_CONG_BBR=$cfgv，不是模块型 m；为避免破坏内核，拒绝同名替换。"
        warn "如需内置型 BBR 真替换，请走完整内核源码编译路线。"
        return 1
    fi
    if test -z "$modp" || test ! -f "$modp"; then error "未找到原版 tcp_bbr.ko 路径，拒绝替换。"; return 1; fi
    if test -z "$src" || test ! -f "$src"; then
        error "未找到与当前内核匹配的 tcp_bbr.c 源码。"
        warn "可安装 linux-headers/linux-source，或导出 BBR_SOURCE=/path/to/tcp_bbr.c 后重试。"
        return 1
    fi
    if test ! -d "/lib/modules/$(uname -r)/build"; then
        error "缺少 /lib/modules/$(uname -r)/build，无法编译外部模块。请安装当前内核 headers。"
        return 1
    fi
    bdir="$(_e89_bbr_backup_state)" || { error "备份失败，拒绝继续。"; return 1; }
    _e89_bbr_write_original_param_note "$bdir" "$kind"
    cp -af "$conf" "$bdir/generated_new_params.conf" 2>/dev/null || true
    info "已创建替换前完整备份：$bdir"
    work="$E89_BBRX_BUILD_ROOT/build_$(date +%Y%m%d_%H%M%S)_$kind"
    mkdir -p "$work" || return 1
    cp -af "$src" "$work/tcp_bbr.c"
    cp -af "$work/tcp_bbr.c" "$bdir/tcp_bbr.c.new.before_patch" 2>/dev/null || true
    _e89_patch_bbr_source_from_conf "$work/tcp_bbr.c" "$conf" "$kind"
    cp -af "$work/tcp_bbr.c" "$bdir/tcp_bbr.c.new" 2>/dev/null || true
    cat > "$work/Makefile" <<'EOF_MAKE'
obj-m += tcp_bbr.o
all:
	$(MAKE) -C /lib/modules/$(shell uname -r)/build M=$(PWD) modules
clean:
	$(MAKE) -C /lib/modules/$(shell uname -r)/build M=$(PWD) clean
EOF_MAKE
    info "开始编译 tcp_bbr.ko：$work"
    if ! make -C "/lib/modules/$(uname -r)/build" M="$work" modules; then
        error "编译失败，原系统未替换。工作目录：$work"
        return 1
    fi
    newko="$work/tcp_bbr.ko"
    if test ! -f "$newko"; then error "编译后未发现 $newko，拒绝替换。"; return 1; fi
    cp -af "$newko" "$bdir/tcp_bbr.ko.new" 2>/dev/null || true
    sha256sum "$newko" > "$bdir/tcp_bbr.ko.new.sha256" 2>/dev/null || true
    cat > "$bdir/rollback.sh" <<EOF_ROLLBACK
#!/usr/bin/env bash
set -e
ORIG_KO="$modp"
BACKUP_DIR="$bdir"
sysctl -w net.ipv4.tcp_congestion_control=cubic >/dev/null 2>&1 || true
modprobe -r tcp_bbr 2>/dev/null || rmmod tcp_bbr 2>/dev/null || true
if test -f "\$BACKUP_DIR/tcp_bbr.ko.orig"; then cp -af "\$BACKUP_DIR/tcp_bbr.ko.orig" "\$ORIG_KO"; fi
depmod -a
modprobe tcp_bbr || true
sysctl -w net.ipv4.tcp_congestion_control=bbr >/dev/null 2>&1 || true
sysctl --system >/dev/null 2>&1 || true
echo "已回滚到备份：\$BACKUP_DIR"
EOF_ROLLBACK
    chmod +x "$bdir/rollback.sh" 2>/dev/null || true
    echo ""
    read -rp "是否临时切到 cubic 并尝试卸载旧 tcp_bbr 后立即热替换？[Y/n]: " release_now || true
    if ! [[ "$release_now" =~ ^[nN]$ ]]; then
        sysctl -w net.ipv4.tcp_congestion_control=cubic >/dev/null 2>&1 || true
        modprobe -r tcp_bbr 2>/dev/null || rmmod tcp_bbr 2>/dev/null || warn "旧 tcp_bbr 当前仍被引用，磁盘替换仍会执行；可能需重启后才完全生效。"
    fi
    if ! _e89_install_new_ko_to_original_path "$newko" "$modp"; then
        error "写入新模块失败，尝试保持原状态。"
        return 1
    fi
    depmod -a >/dev/null 2>&1 || true
    modprobe tcp_bbr 2>/dev/null || warn "modprobe tcp_bbr 未立即成功；如果旧模块仍在内存中，请重启后验证。"
    cat > "$E89_BBRX_SYSCTL" <<'EOF_SYSCTL'
net.core.default_qdisc = fq
net.ipv4.tcp_congestion_control = bbr
EOF_SYSCTL
    echo "tcp_bbr" > "$E89_BBRX_MODULES_LOAD"
    sysctl -p "$E89_BBRX_SYSCTL" >/dev/null 2>&1 || true
    info "替换完成。永久配置：$E89_BBRX_SYSCTL / $E89_BBRX_MODULES_LOAD"
    info "回滚脚本：$bdir/rollback.sh"
    sysctl net.ipv4.tcp_congestion_control 2>/dev/null || true
    sysctl net.ipv4.tcp_available_congestion_control 2>/dev/null || true
    modinfo tcp_bbr 2>/dev/null | sed -n '1,8p' || true
}

_e89_bbrv1_flow() {
    local m conf go
    while true; do
        title "V198e89：普通 Linux 主线 BBR v1 → bbrx_v1 参数中心"
        echo "  1) 查看参数表：参数 / 原版 BBR / bbrx_v1 建议 / 说明"
        echo "  2) 使用 bbrx_v1 推荐参数生成配置"
        echo "  3) 自定义全部参数并生成配置"
        echo "  4) 使用当前配置编译并替换 bbr"
        echo "  0) 返回"
        read -rp "请选择: " m || true
        case "${m:-}" in
            1) _e89_show_bbrv1_table; _e89_bbr_pause ;;
            2) _e89_collect_bbrv1_params recommended || return; conf="$(_e89_write_bbrv1_conf)"; info "已写入：$conf"; read -rp "是否立即编译并替换 bbr？[y/N]: " go || true; [[ "$go" =~ ^[yY]$ ]] && _e89_build_replace_bbr bbrv1 "$conf"; _e89_bbr_pause ;;
            3) _e89_collect_bbrv1_params custom || return; conf="$(_e89_write_bbrv1_conf)"; info "已写入：$conf"; read -rp "是否立即编译并替换 bbr？[y/N]: " go || true; [[ "$go" =~ ^[yY]$ ]] && _e89_build_replace_bbr bbrv1 "$conf"; _e89_bbr_pause ;;
            4) conf="$E89_BBRX_CURRENT/bbrv1_replace.conf"; if test -f "$conf"; then _e89_build_replace_bbr bbrv1 "$conf"; else warn "配置不存在，请先执行 2 或 3。"; fi; _e89_bbr_pause ;;
            0) return ;;
            *) warn "无效操作。"; sleep 1 ;;
        esac
    done
}

_e89_bbr3_flow() {
    local m conf go
    while true; do
        title "V198e89：BBR3 / XanMod → bbrx3_v1 参数中心"
        echo "  1) 查看参数表：参数 / 原版 BBR3 / bbrx3_v1 建议 / 说明"
        echo "  2) 使用 bbrx3_v1 推荐参数生成配置"
        echo "  3) 自定义全部参数并生成配置"
        echo "  4) 使用当前配置编译并替换 bbr"
        echo "  0) 返回"
        read -rp "请选择: " m || true
        case "${m:-}" in
            1) _e89_show_bbr3_table; _e89_bbr_pause ;;
            2) _e89_collect_bbr3_params recommended || return; conf="$(_e89_write_bbr3_conf)"; info "已写入：$conf"; read -rp "是否立即编译并替换 bbr？[y/N]: " go || true; [[ "$go" =~ ^[yY]$ ]] && _e89_build_replace_bbr bbr3 "$conf"; _e89_bbr_pause ;;
            3) _e89_collect_bbr3_params custom || return; conf="$(_e89_write_bbr3_conf)"; info "已写入：$conf"; read -rp "是否立即编译并替换 bbr？[y/N]: " go || true; [[ "$go" =~ ^[yY]$ ]] && _e89_build_replace_bbr bbr3 "$conf"; _e89_bbr_pause ;;
            4) conf="$E89_BBRX_CURRENT/bbr3_replace.conf"; if test -f "$conf"; then _e89_build_replace_bbr bbr3 "$conf"; else warn "配置不存在，请先执行 2 或 3。"; fi; _e89_bbr_pause ;;
            0) return ;;
            *) warn "无效操作。"; sleep 1 ;;
        esac
    done
}

_e89_bbr_show_backups() {
    title "V198e89：BBR 替换备份列表"
    ls -1dt "$E89_BBRX_BACKUP_ROOT"/* 2>/dev/null | head -n 20 | nl -w2 -s') ' || echo "  暂无备份。"
}

_e89_bbr_rollback_latest() {
    local bdir rb
    bdir=$(ls -1dt "$E89_BBRX_BACKUP_ROOT"/* 2>/dev/null | head -n1 || true)
    if test -z "$bdir" || test ! -d "$bdir"; then error "未找到可回滚备份。"; return 1; fi
    rb="$bdir/rollback.sh"
    if test -x "$rb"; then bash "$rb"; else error "备份中没有 rollback.sh：$bdir"; return 1; fi
}

_e89_bbr_status() {
    title "V198e89：当前 BBR / qdisc / 模块状态"
    echo "  内核：$(uname -r 2>/dev/null || true)"
    echo "  CONFIG_TCP_CONG_BBR：$(_e89_bbr_kconfig_value)"
    sysctl net.ipv4.tcp_congestion_control 2>/dev/null || true
    sysctl net.ipv4.tcp_available_congestion_control 2>/dev/null || true
    sysctl net.core.default_qdisc 2>/dev/null || true
    echo ""
    echo "  tcp_bbr 模块路径：$(_e89_bbr_mod_path)"
    modinfo tcp_bbr 2>/dev/null | sed -n '1,14p' || true
    echo ""
    echo "  活跃连接 BBR 摘要："
    ss -tin 2>/dev/null | grep -i 'bbr' | head -n 20 || echo "    未发现 ss -tin 中的 bbr 连接样本。"
}

do_bbr_body_replace_menu_e89() {
    _e89_bbr_prepare_dirs
    local opt rec
    while true; do
        rec="$(_e89_bbr_recommend_kind)"
        title "V198e89：BBR 本体替换 / 自定义编译中心"
        echo "  自动建议：$(test "$rec" = "bbr3" && echo "BBR3 / XanMod → bbrx3_v1" || echo "普通 Linux 主线 BBR v1 → bbrx_v1")"
        echo ""
        echo "  1) 自动检测当前 BBR 类型，并推荐编译方案"
        echo "  2) 普通 Linux 主线 BBR v1 → 自定义全部参数 → 替换 bbr"
        echo "  3) BBR3 / XanMod → 自定义全部参数 → 替换 bbr"
        echo "  4) 查看已备份的原版 BBR / 系统 TCP 设置"
        echo "  5) 无损切换回最近一次编译前 BBR"
        echo "  6) 查看当前拥塞控制 / qdisc / BBR 状态"
        echo "  0) 返回主菜单"
        read -rp "请选择: " opt || true
        case "${opt:-}" in
            1) _e89_bbr_detect; _e89_bbr_pause ;;
            2) _e89_bbrv1_flow ;;
            3) _e89_bbr3_flow ;;
            4) _e89_bbr_show_backups; _e89_bbr_pause ;;
            5) _e89_bbr_rollback_latest; _e89_bbr_pause ;;
            6) _e89_bbr_status; _e89_bbr_pause ;;
            0) return ;;
            *) warn "无效操作。"; sleep 1 ;;
        esac
    done
}

hot_update_from_legacy() {
    title "V198e89：稳态热更新（e88 基线 + BBR 本体替换中心）"
    set +e
    trap - ERR

    mkdir -p "$CONFIG_DIR" "$SCRIPT_DIR" "$BACKUP_DIR" "$E89_BBRX_ROOT" "$E89_BBRX_CURRENT" "$E89_BBRX_BACKUP_ROOT" 2>/dev/null || true
    _e88_install_self_entrypoint || true
    local bdir
    if declare -F e76_state_snapshot >/dev/null 2>&1; then
        bdir=$(e76_state_snapshot "hotupdate_e89")
    else
        bdir="$BACKUP_DIR/hotupdate_e89_$(date +%Y%m%d_%H%M%S)"; mkdir -p "$bdir" 2>/dev/null || true
        cp -a "$CONFIG" "$bdir/config.json.bak" 2>/dev/null || true
        cp -a "$NETWORK_OPT_CONF" "$bdir/99-network-optimized.conf.bak" 2>/dev/null || true
    fi
    info "已创建热更新快照：$bdir"

    repair_dns_if_broken || true
    install_update_dat || true
    fix_xray_systemd_limits || true
    apply_hotupdate_fast_sysctl || true
    remove_xray_env_buffer || true

    _e88_set_sysctl_key net.ipv4.tcp_fastopen 0 "V198e89 热更新：保持 tcp_fastopen=0，不默认启用 TFO=3" || true
    _e88_set_tcp_notsent_lowat 26214 "热更新默认极低排队响应值" || true
    _e88_apply_menu13_defaults || true
    _e88_apply_rps_rfs || true
    _e88_set_init_window 21 21 "hotupdate-default21" || true
    _e89_bbr_prepare_dirs || true

    if declare -F e76_config_semantic_ok >/dev/null 2>&1 && e76_config_semantic_ok "$CONFIG"; then
        force_apply_xray_core_defaults_e52 >/dev/null 2>&1 || true
        harden_xray_reality_profile >/dev/null 2>&1 || true
        fix_permissions || true
        systemctl daemon-reload >/dev/null 2>&1 || true
        if systemctl restart xray >/dev/null 2>&1; then
            info "Xray 已基于有效现网配置重启。"
        else
            warn "Xray 重启失败；可执行：journalctl -u xray --no-pager -n 80"
        fi
    else
        warn "未发现有效现网节点配置。V198e89 已安装为 xrv；请执行 xrv → 1 重新搭建。"
    fi

    echo "198e89" > "$SCRIPT_VERSION_FILE" 2>/dev/null || true
    _e88_show_tcp_notsent_lowat_state || true
    _e88_show_menu13_manual_notes || true
    _e88_show_core_network_state || true
    _e88_show_rps_rfs_state || true
    _e88_show_init_window_state || true
    if declare -F e77_audit_runtime_state >/dev/null 2>&1; then e77_audit_runtime_state || true; fi
    set -e
    trap '_err_handler $? $LINENO "$BASH_COMMAND"' ERR
    info "V198e89 热更新完成。主菜单新增：17) BBR 本体替换 / 自定义编译中心。"
    info "BBR 中心目录：$E89_BBRX_ROOT；备份目录：$E89_BBRX_BACKUP_ROOT。"
    return 0
}

main_menu() {
    while true; do
        clear
        echo -e "${blue}======================================================================${none}"
        echo -e "  ${magenta}Xray System Advanced Management V198e89 - (Reality / VLESSENC / SS2022 / BBR本体替换中心)${none}"
        local svc sys_ver arch_level dns_mode tz_line notsent_now notsent_perm qdisc cc adv app bbr_cfg
        svc=$(systemctl is-active xray 2>/dev/null || echo "inactive")
        if test "$svc" = "active"; then svc="${green}平稳在线 (Running)${none}"; else svc="${red}离线静默 (Stopped)${none}"; fi
        sys_ver=$(uname -r 2>/dev/null || echo "未探测到数据")
        if declare -F detect_x86_64_level >/dev/null 2>&1; then arch_level="$(detect_x86_64_level 2>/dev/null || echo '?')"; else arch_level="?"; fi
        dns_mode=$(cat "${E67_DNS_MODE_FILE:-/usr/local/etc/xray/dns_mode.txt}" 2>/dev/null || echo auto)
        tz_line=$(date '+%Z %z' 2>/dev/null || echo unknown)
        notsent_now=$(_e88_current_notsent_lowat)
        notsent_perm=$(_e88_persistent_notsent_lowat)
        qdisc=$(_e88_sysctl_get net.core.default_qdisc)
        cc=$(_e88_sysctl_get net.ipv4.tcp_congestion_control)
        adv=$(_e88_sysctl_get net.ipv4.tcp_adv_win_scale)
        app=$(_e88_sysctl_get net.ipv4.tcp_app_win)
        bbr_cfg=$(_e89_bbr_kconfig_value 2>/dev/null || echo unknown)
        echo -e "  引擎态势: $svc | 全局快捷指令: ${cyan}xrv${none} | 外部识别 IP: ${yellow}$(_get_ip 2>/dev/null || echo "探测异常")${none}"
        echo -e "  系统装配内核: ${cyan}${sys_ver}${none} | 微架构侦测: x64-v${yellow}${arch_level}${none} | qdisc/cc: ${yellow}${qdisc}/${cc}${none} | BBR配置:${yellow}${bbr_cfg}${none}"
        echo -e "  DNS模式: ${cyan}${dns_mode}${none} | 时间轴: ${cyan}${tz_line}${none} | notsent: ${yellow}${notsent_now}${none}/${cyan}${notsent_perm}${none} | adv/app: ${yellow}${adv}/${app}${none}"
        echo -e "${blue}======================================================================${none}"
        echo "  1) 创建/重构协议节点：Reality Vision / VLESSENC 自选 / SS2022"
        echo "  2) 用户凭证生命周期与独立参数化管理控制"
        echo "  3) 节点链接与多维信息输出聚合中心"
        echo "  4) 人工发起数据强联，执行路由解析规则库强制覆盖更新"
        echo "  5) Xray Core 手动更新/修复（不设置自动更新）"
        echo "  6) 修改或全自动剔除被拦截的防封伪装特征矩阵域名"
        echo "  7) 系统防火墙策略配置 (阻止内网 BT 滥用及第三方广告请求)"
        echo "  8) Reality Fallback 底层限速沙盒分析器"
        echo "  9) 全景网络连接审计日志与商用级别网络流量记账本"
        echo "  10) 高级发烧：内核双轨编译(APT/源码)/网络/应用层 60余项极限全控板"
        echo -e "  ${cyan}11) 从旧 ex198e 环境稳态热更新到 V198e89${none}"
        echo -e "  ${cyan}12) 清理空间（安全释放 / 快照收敛 / 显示硬盘与 Swap）${none}"
        echo -e "  ${cyan}13) 应用网络参数（缓冲/notsent/adv_win/app_win/txqueue/OOOX/MSS）${none}"
        echo -e "  ${cyan}14) TCP 重传 / 单连接诊断中心（只读排障）${none}"
        echo -e "  ${cyan}15) 检查现有配置并重新输出节点${none}"
        echo -e "  ${cyan}16) 状态隔离审计 + VLESSENC 能力检查${none}"
        echo -e "  ${magenta}17) BBR 本体替换 / 自定义编译中心（bbrx_v1 / bbrx3_v1）${none}"
        echo "  0) 折叠命令控制台，返回底层终端"
        echo -e "  ${red}88) 物理不可逆自毁！撤销环境安全防线与系统配置设定${none}"
        hr
        local num=""
        read -rp "请输入操作代码指令: " num || true
        case "${num:-}" in
            1) do_install ;;
            2) do_user_manager ;;
            3) do_summary; while true; do local rb=""; read -rp "输出完毕，按 Enter 退出或者按 b 发起特征替换: " rb || true; if test "$rb" = "b" || test "$rb" = "B"; then if choose_sni; then _update_matrix; do_summary; else break; fi; else break; fi; done ;;
            4) print_magenta ">>> 初始化云网络联通..."; bash "$UPDATE_DAT_SCRIPT" >/dev/null 2>&1 || true; ensure_xray_is_alive; info "配置已穿透替换系统！当前路由库完成热加载！"; local _p=""; read -rp "按 Enter 退回..." _p || true ;;
            5) do_update_core ;;
            6) if choose_sni; then _update_matrix; do_summary; while true; do local rb=""; read -rp "任务完毕，按 Enter 返回，或按 b 连续变更: " rb || true; if test "$rb" = "b" || test "$rb" = "B"; then if choose_sni; then _update_matrix; do_summary; else break; fi; else break; fi; done; fi ;;
            7) _global_block_rules ;;
            8) do_fallback_probe ;;
            9) do_status_menu ;;
            10) do_sys_init_menu ;;
            11) hot_update_from_legacy ;;
            12) do_space_cleanup_menu ;;
            13) do_network_params_menu_e56 ;;
            14) do_tcp_diag_menu_e63 ;;
            15) do_install_repair_e77 ;;
            16) e77_audit_runtime_state; _e52_pause ;;
            17) do_bbr_body_replace_menu_e89 ;;
            88) do_uninstall ;;
            0) exit 0 ;;
            *) echo -e "${red}错误拦截：代码解析为空值！${none}"; sleep 1 ;;
        esac
    done
}



#==============================================================================
# V198e90 FINAL OVERRIDE LAYER
# 目标：
#   1) 修复 CONFIG_TCP_CONG_BBR=y 内置型 BBR 两套参数都无法替换的问题：
#      - 模块型 m：继续使用 e89 的 tcp_bbr.ko 同名替换路线。
#      - 内置型 y：转入“补丁 tcp_bbr.c + 完整源码内核编译”路线，重启后生效。
#   2) 自定义参数输入时同步展示“参数 / 原版 / 推荐 / 说明”，并支持 ? 随时查看完整参数表。
#   3) 11 热更新升级为 V198e90，保留 e88/e89 稳态网络参数与 BBRX 工作目录。
#==============================================================================

# 保存 e89 的关键函数，e90 在外层接管。
if declare -F _e89_build_replace_bbr >/dev/null 2>&1; then
    eval "$(declare -f _e89_build_replace_bbr | sed '1s/_e89_build_replace_bbr/_e90_build_replace_bbr_module_base/')"
fi
if declare -F _execute_compilation >/dev/null 2>&1; then
    eval "$(declare -f _execute_compilation | sed '1s/_execute_compilation/_e90_execute_compilation_base/')"
fi
if declare -F hot_update_from_legacy >/dev/null 2>&1; then
    eval "$(declare -f hot_update_from_legacy | sed '1s/hot_update_from_legacy/hot_update_from_legacy_e89_base/')"
fi

_e90_bbr_compile_mode_text() {
    local cfgv
    cfgv="$(_e89_bbr_kconfig_value 2>/dev/null || echo unknown)"
    case "$cfgv" in
        m) echo "模块型 m：可热替换 tcp_bbr.ko" ;;
        y) echo "内置型 y：需补丁源码并完整编译内核，重启后生效" ;;
        *) echo "未知：需先自动检测" ;;
    esac
}

_e90_show_param_input_banner() {
    local kind="$1"
    echo ""
    if test "$kind" = "bbr3"; then
        print_yellow "下面进入 BBR3 / XanMod 全参数自定义。每一项都会显示：参数 / 原版 BBR3 / bbrx3_v1 建议 / 说明。"
        print_yellow "输入 ? 可随时查看完整参数表；回车=推荐值；r=原版值；q=退出。"
        _e89_show_bbr3_table
    else
        print_yellow "下面进入普通 Linux 主线 BBR v1 全参数自定义。每一项都会显示：参数 / 原版 BBR / bbrx_v1 建议 / 说明。"
        print_yellow "输入 ? 可随时查看完整参数表；回车=推荐值；r=原版值；q=退出。"
        _e89_show_bbrv1_table
    fi
}

_e90_show_table_by_current_kind() {
    case "${E90_PARAM_KIND:-}" in
        bbr3) _e89_show_bbr3_table ;;
        *) _e89_show_bbrv1_table ;;
    esac
}

# 覆盖 e89 的参数输入函数：不再只显示三行，而是用表格式提示。
_e89_param_int() {
    local __var="$1" orig="$2" rec="$3" min="$4" max="$5" label="$6" desc="$7" val orig_clean rec_clean
    while true; do
        echo ""
        echo -e "${blue}--------------------------------------------------------------------------${none}"
        printf "  %-32s | %-18s | %-18s | %s\n" "参数" "原版" "bbrx_v1/bbrx3_v1建议" "说明"
        echo "  ------------------------------------------------------------------------"
        printf "  %-32s | %-18s | %-18s | %s\n" "$label" "$orig" "$rec" "$desc"
        echo -e "${blue}--------------------------------------------------------------------------${none}"
        read -rp "  请输入 [$min-$max]，回车=$rec，r=原版，?=完整表，q=退出: " val || true
        if [[ "$val" =~ ^[qQ]$ ]]; then return 1; fi
        if test "$val" = "?"; then _e90_show_table_by_current_kind; continue; fi
        if [[ "$val" =~ ^[rR]$ ]]; then val="$orig"; fi
        val="${val:-$rec}"
        # 支持用户从说明里复制“2.65x/2.0%”一类展示值：只取第一个整数片段。
        val="${val%% *}"; val="${val%%x}"; val="${val%%%}"
        val="$(echo "$val" | sed -E 's/[^0-9].*$//' 2>/dev/null || echo "$val")"
        if [[ "$val" =~ ^[0-9]+$ ]] && test "$val" -ge "$min" 2>/dev/null && test "$val" -le "$max" 2>/dev/null; then
            printf -v "$__var" '%s' "$val"
            return 0
        fi
        error "输入非法：$val"
    done
}

_e89_param_bool() {
    local __var="$1" orig="$2" rec="$3" label="$4" desc="$5" val
    while true; do
        echo ""
        echo -e "${blue}--------------------------------------------------------------------------${none}"
        printf "  %-32s | %-18s | %-18s | %s\n" "参数" "原版" "bbrx3_v1建议" "说明"
        echo "  ------------------------------------------------------------------------"
        printf "  %-32s | %-18s | %-18s | %s\n" "$label" "$orig" "$rec" "$desc"
        echo -e "${blue}--------------------------------------------------------------------------${none}"
        read -rp "  请输入 1=true / 0=false，回车=$rec，r=原版，?=完整表，q=退出: " val || true
        if [[ "$val" =~ ^[qQ]$ ]]; then return 1; fi
        if test "$val" = "?"; then _e90_show_table_by_current_kind; continue; fi
        if [[ "$val" =~ ^[rR]$ ]]; then val="$orig"; fi
        val="${val:-$rec}"
        if test "$val" = "1" || test "$val" = "0"; then printf -v "$__var" '%s' "$val"; return 0; fi
        error "输入非法：$val"
    done
}

_e89_param_expr() {
    local __var="$1" orig="$2" rec="$3" label="$4" desc="$5" val
    while true; do
        echo ""
        echo -e "${blue}--------------------------------------------------------------------------${none}"
        printf "  %-32s | %-18s | %-18s | %s\n" "参数" "原版" "建议" "说明"
        echo "  ------------------------------------------------------------------------"
        printf "  %-32s | %-18s | %-18s | %s\n" "$label" "$orig" "$rec" "$desc"
        echo -e "${blue}--------------------------------------------------------------------------${none}"
        read -rp "  请输入 C 表达式，回车=$rec，r=原版，?=完整表，q=退出: " val || true
        if [[ "$val" =~ ^[qQ]$ ]]; then return 1; fi
        if test "$val" = "?"; then _e90_show_table_by_current_kind; continue; fi
        if [[ "$val" =~ ^[rR]$ ]]; then val="$orig"; fi
        val="${val:-$rec}"
        if ! echo "$val" | grep -Eq '^[A-Za-z0-9_[:space:]<</+*()-]+$'; then
            error "表达式含不安全字符，已拒绝。"
            continue
        fi
        printf -v "$__var" '%s' "$val"
        return 0
    done
}

# 覆盖采集函数：自定义模式先显示完整表，避免必须退出查看说明。
_e89_collect_bbrv1_params() {
    local mode="${1:-recommended}" drain_mode
    E90_PARAM_KIND="bbrv1"
    _e89_bbrv1_defaults
    if test "$mode" = "custom"; then
        _e90_show_param_input_banner bbrv1
        _e89_param_int BW_SCALE 24 24 20 28 "BW_SCALE" "带宽估算缩放位数；普通用户不建议改。" || return 1
        _e89_param_int BBR_SCALE 8 8 6 10 "BBR_SCALE" "gain 缩放位数；普通用户不建议改。" || return 1
        _e89_param_int CYCLE_LEN 8 8 4 12 "CYCLE_LEN" "PROBE_BW 增益周期长度；改动会影响数组长度语义。" || return 1
        _e89_param_int BBR_MIN_RTT_WIN_SEC 10 15 8 30 "bbr_min_rtt_win_sec" "最小 RTT 采样窗口；高 RTT 线路略放大。" || return 1
        _e89_param_int BBR_PROBE_RTT_MODE_MS 200 160 100 300 "bbr_probe_rtt_mode_ms" "ProbeRTT 持续时间；缩短可减少体感卡顿。" || return 1
        _e89_param_int BBR_MIN_TSO_RATE 1200000 1200000 600000 3000000 "bbr_min_tso_rate" "低速 TSO 阈值。" || return 1
        _e89_param_int BBR_PACING_MARGIN_PERCENT 1 1 0 5 "bbr_pacing_margin_percent" "pacing 余量；0 更激进，1 更稳。" || return 1
        _e89_param_int BBR_HIGH_GAIN 288 265 220 320 "bbr_high_gain" "STARTUP 提速增益；265 表示 2.65x。" || return 1
