    sed -i 's/^TC_ENABLE=.*/TC_ENABLE=0/' "$E93_TC_CONF" 2>/dev/null || true

    e92_boot_kernel_safety_audit >/dev/null 2>&1 || true

    echo "198e93" > "$SCRIPT_VERSION_FILE" 2>/dev/null || true
    if test -f "${SCRIPT_PATH:-$0}"; then
