            9) do_traffic_monitor ;;
            10) do_sys_init_menu || true ;;
            11) hot_update_from_legacy; _e135_pause ;;
            12) do_space_cleanup_menu || true ;;
            13|21) _e135_network_menu ;;
            14) do_tcp_diag_menu_e63 || true ;;
            15) _e118_xray_test_config "$CONFIG" 1 && fix_xray_systemd_limits && do_summary; _e135_pause ;;
            16) e77_audit_runtime_state || true; _e135_pause ;;
            17) _e135_xanmod_menu ;;
            18) _e135_ssh_menu ;;
            19) if declare -F do_xray_speed_diag_menu_e95 >/dev/null 2>&1; then do_xray_speed_diag_menu_e95; else warn "诊断模块缺失。"; fi ;;
            20) if declare -F do_tc_bandwidth_menu_e95 >/dev/null 2>&1; then do_tc_bandwidth_menu_e95; else warn "TC模块缺失。"; fi ;;
            88) do_uninstall ;;
            0) return 0 ;;
            *) warn "无效操作。"; sleep 1 ;;
        esac
    done
}

