#==============================================================================
# V199e141 FINAL OVERRIDE: key-only aware SSH guard + truthful package install
#==============================================================================
readonly E141_VERSION="199e141"
readonly E141_DIR="$CONFIG_DIR/e141"
readonly E141_LOG_DIR="$LOG_DIR/e141"
readonly E141_F2B_INSTALL_LOG="$E141_LOG_DIR/fail2ban-install.log"
readonly E141_SSH_AUTH_STATE="$E141_DIR/ssh-auth-mode.env"

_e141_prepare() {
    install -d -m 0700 "$E141_DIR" || return 1
    install -d -m 0750 "$E141_LOG_DIR" || return 1
}

_e141_sshd_effective_dump() {
    local user host addr
    user="${SUDO_USER:-${USER:-root}}"; test "$user" = root || id "$user" >/dev/null 2>&1 || user=root
    host="$(hostname -f 2>/dev/null || hostname 2>/dev/null || echo localhost)"
    addr="${SSH_CONNECTION%% *}"; [[ "$addr" =~ ^[0-9a-fA-F:.]+$ ]] || addr=127.0.0.1
    if command -v sshd >/dev/null 2>&1; then
        sshd -T -C "user=$user,host=$host,addr=$addr" 2>/dev/null || sshd -T 2>/dev/null
    else
        return 1
    fi
}

_e141_sshd_auth_profile() {
    local dump password kbd challenge methods pubkey permitroot mode
    dump="$(_e141_sshd_effective_dump)" || return 1
    password="$(awk '$1=="passwordauthentication"{print $2;exit}' <<<"$dump")"
    kbd="$(awk '$1=="kbdinteractiveauthentication"{print $2;exit}' <<<"$dump")"
    challenge="$(awk '$1=="challengeresponseauthentication"{print $2;exit}' <<<"$dump")"
    methods="$(awk '$1=="authenticationmethods"{$1="";sub(/^ /,"");print;exit}' <<<"$dump")"
    pubkey="$(awk '$1=="pubkeyauthentication"{print $2;exit}' <<<"$dump")"
    permitroot="$(awk '$1=="permitrootlogin"{print $2;exit}' <<<"$dump")"
    password=${password:-yes}; kbd=${kbd:-yes}; challenge=${challenge:-$kbd}; pubkey=${pubkey:-yes}; methods=${methods:-any}
    mode="password-capable"
    if test "$password" = no && test "$kbd" = no && test "$challenge" = no; then
        case "$methods" in
            any|publickey|publickey,*|*,publickey) mode="key-only" ;;
            *) mode="non-password" ;;
        esac
    fi
    printf 'mode=%s\npasswordauthentication=%s\nkbdinteractiveauthentication=%s\nchallengeresponseauthentication=%s\nauthenticationmethods=%s\npubkeyauthentication=%s\npermitrootlogin=%s\n' \
      "$mode" "$password" "$kbd" "$challenge" "$methods" "$pubkey" "${permitroot:-unknown}"
}

_e141_wait_apt_locks() {
    local i holder
    for i in $(seq 1 60); do
        holder=""
        for f in /var/lib/dpkg/lock-frontend /var/lib/dpkg/lock /var/cache/apt/archives/lock /var/lib/apt/lists/lock; do
            test -e "$f" || continue
            if command -v fuser >/dev/null 2>&1 && fuser "$f" >/dev/null 2>&1; then holder=1; break; fi
        done
        test -z "$holder" && return 0
        sleep 2
    done
    return 1
}

_e141_install_fail2ban_package() {
    local os rc=0
    _e141_prepare || return 1
    : > "$E141_F2B_INSTALL_LOG" || return 1
    exec 8>>"$E141_F2B_INSTALL_LOG"
    printf '[%s] fail2ban install start\n' "$(date -Is)" >&8
    if command -v fail2ban-client >/dev/null 2>&1; then
        fail2ban-client --version >&8 2>&1 || true
        exec 8>&-
        return 0
    fi
    os="$(detect_os)"
    case "$os" in
      debian|ubuntu)
        export DEBIAN_FRONTEND=noninteractive
        _e141_wait_apt_locks || { echo 'APT/DPKG lock timeout' >&8; exec 8>&-; return 1; }
        dpkg --configure -a >&8 2>&1 || true
        apt-get -f install -y >&8 2>&1 || true
        apt-get update >&8 2>&1 || rc=$?
        if test "$rc" -ne 0; then
            echo "apt-get update rc=$rc; attempting cached install" >&8
        fi
        rc=0
        apt-get install -y --no-install-recommends fail2ban python3-systemd >&8 2>&1 || rc=$?
        if test "$rc" -ne 0; then
            echo "first install rc=$rc; retry after dpkg repair" >&8
            dpkg --configure -a >&8 2>&1 || true
            apt-get -f install -y >&8 2>&1 || true
            apt-get install -y fail2ban >&8 2>&1 || rc=$?
        fi
        ;;
      centos|rhel|rocky|almalinux|fedora)
        rc=0
        if command -v dnf >/dev/null 2>&1; then
            dnf install -y epel-release >&8 2>&1 || true
            dnf install -y fail2ban fail2ban-systemd >&8 2>&1 || rc=$?
        else
            yum install -y epel-release >&8 2>&1 || true
            yum install -y fail2ban fail2ban-systemd >&8 2>&1 || rc=$?
        fi
        ;;
      *) echo "unsupported os=$os" >&8; rc=1 ;;
    esac
    hash -r 2>/dev/null || true
    if ! command -v fail2ban-client >/dev/null 2>&1; then
        echo "fail2ban-client still missing, rc=$rc" >&8
        exec 8>&-
        return 1
    fi
    systemctl daemon-reload >&8 2>&1 || true
    fail2ban-client --version >&8 2>&1 || { exec 8>&-; return 1; }
    exec 8>&-
    return 0
}

# Preserve the existing configuration/runtime implementation. Package bootstrap is handled first.
if declare -F _e121_install_fail2ban_guard >/dev/null 2>&1; then
    eval "$(declare -f _e121_install_fail2ban_guard | sed '1s/_e121_install_fail2ban_guard/_e141_fail2ban_guard_original/')"
fi
_e121_install_fail2ban_guard() {
    if ! command -v fail2ban-client >/dev/null 2>&1; then
        info "未检测到fail2ban，正在执行可诊断安装。"
        if ! _e141_install_fail2ban_package; then
            error "fail2ban安装失败，原始日志：$E141_F2B_INSTALL_LOG"
            tail -n 60 "$E141_F2B_INSTALL_LOG" 2>/dev/null | sed 's/^/    /' || true
            return 1
        fi
    fi
    _e141_fail2ban_guard_original
}

_e141_install_key_only_ssh_guard() {
    local firewall_backup="" tool
    title "V199e141：Key-only SSH端口自适应防锁"
    command -v sshd >/dev/null 2>&1 || { error "未检测到OpenSSH sshd。"; return 1; }
    sshd -t >"$E118_TMPDIR/sshd-test.log" 2>&1 || { error "sshd -t未通过。"; sed 's/^/    /' "$E118_TMPDIR/sshd-test.log"; return 1; }
    if command -v iptables-save >/dev/null 2>&1; then
        firewall_backup="$E118_BACKUP_DIR/iptables_before_ssh_e141_$(date +%Y%m%d_%H%M%S)_$$.rules"
        iptables-save > "$firewall_backup" 2>/dev/null || firewall_backup=""
    fi
    _e121_write_ssh_port_guard || return 1
    _e121_apply_ssh_port_guard || { error "SSH端口守护首次应用失败。"; return 1; }
    _e121_verify_ssh_port_guard || { error "SSH端口/防火墙守护复检失败。"; return 1; }
    # Existing fail2ban is left untouched; no package installation on an effective key-only host.
    info "检测到有效Key-only认证：不强制安装fail2ban。"
    info "SSH端口已自动识别、当前会话IP已保护，开机及每5分钟复检已启用。"
    test -z "$firewall_backup" || info "防火墙变更前快照：$firewall_backup"
}

_e141_install_ssh_guard() {
    local profile mode ip tmp
    _e141_prepare || return 1
    profile="$(_e141_sshd_auth_profile)" || { error "无法读取sshd有效认证配置。"; return 1; }
    mode="$(sed -n 's/^mode=//p' <<<"$profile" | head -n1)"
    ip="$(_e135_current_ssh_ip 2>/dev/null || true)"
    tmp="${E141_SSH_AUTH_STATE}.tmp.$$"
    { printf '%s\n' "$profile"; printf 'current_ssh_ip=%s\nchecked_at=%s\n' "$ip" "$(date -Is)"; } > "$tmp" || return 1
    install -m 0600 "$tmp" "$E141_SSH_AUTH_STATE" || { rm -f "$tmp"; return 1; }
    rm -f "$tmp"
    case "$mode" in
      key-only|non-password)
        _e141_install_key_only_ssh_guard
        ;;
      *)
        info "检测到SSH仍允许密码/交互式认证：必须启用fail2ban。"
        _e137_ssh_backend_supported || return 1
        _e137_ssh_guard_base
        ;;
    esac
}
_e135_install_ssh_guard() { _e141_install_ssh_guard; }
_e121_install_ssh_guard() { _e141_install_ssh_guard; }
_e116_install_ssh_guard() { _e141_install_ssh_guard; }

# Hot update: key-only hosts treat absent fail2ban as an intentional secure state,
# while password-capable hosts still require a fully verified fail2ban jail.
if declare -F hot_update_from_legacy >/dev/null 2>&1; then
    eval "$(declare -f hot_update_from_legacy | sed '1s/hot_update_from_legacy/_e141_hot_update_base/' | sed 's/E140_VERSION/E141_VERSION/g' | sed 's/V199e140/V199e141/g')"
fi
hot_update_from_legacy() { _e141_hot_update_base; }

_e141_ssh_guard_status() {
    local profile
    profile="$(_e141_sshd_auth_profile 2>/dev/null || true)"
    echo "SSH有效认证配置："
    test -n "$profile" && sed 's/^/  /' <<<"$profile" || echo "  unavailable"
    test -s "$E141_SSH_AUTH_STATE" && { echo "最近应用状态："; sed 's/^/  /' "$E141_SSH_AUTH_STATE"; }
    if command -v fail2ban-client >/dev/null 2>&1; then
        echo "fail2ban：$(fail2ban-client --version 2>/dev/null | head -n1)"
        fail2ban-client status "$E121_F2B_JAIL_NAME" 2>/dev/null | sed 's/^/  /' || true
    else
        echo "fail2ban：未安装（Key-only时允许）"
    fi
}

#------------------------------------------------------------------------------
# Three-day logging, DAT updater ownership, and network module preparation
#------------------------------------------------------------------------------
if declare -F _e121_install_log_retention >/dev/null 2>&1; then
    eval "$(declare -f _e121_install_log_retention | sed '1s/_e121_install_log_retention/_e142_log_retention_base/')"
fi
_e121_install_log_retention() {
    local script_tmp dropin_tmp rc=0 had_logrotate=0
    _e135_pkg_present logrotate && had_logrotate=1 || true
    _e142_log_retention_base || rc=$?
    if test "$had_logrotate" -eq 0 && _e135_pkg_present logrotate; then
        E135_NEW_PACKAGES+=(logrotate)
    fi
    test "$rc" -eq 0 || return "$rc"
    script_tmp=$(_e118_mktemp log-retention-extra-e142.sh) || return 1
    dropin_tmp=$(_e118_mktemp log-retention-extra-e142.conf) || return 1
    cat > "$script_tmp" <<'EOF_E142_LOG_EXTRA'
#!/usr/bin/env bash
set -u
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
# Base logrotate covers current top-level and nested *.log files.  Only remove
# old rotated archives here; deleting a quiet current log unlinks the file
# while a daemon may still hold its descriptor and is not a real rotation.
if test -d /var/log/xray; then
    find /var/log/xray -mindepth 2 -type f -mmin +4320 \
        \( -name '*.log.[0-9]*' -o -name '*.log-*.gz' -o -name '*.log.*.gz' \) \
        -delete 2>/dev/null || true
    find /var/log/xray -mindepth 2 -type d -empty -mmin +4320 -delete 2>/dev/null || true
fi
# GNU find -mtime +3 rounds in 24-hour units and can retain nearly four days.
# Use 4320 minutes for the security archives that are not owned by logrotate.
find /var/log -maxdepth 1 -type f -mmin +4320 \
    \( -name 'auth.log.*' -o -name 'secure-*' -o -name 'fail2ban.log.*' \
       -o -name 'fail2ban.log-*' -o -name 'xray-fail2ban.log.*' -o -name 'xray-fail2ban.log-*' \
       -o -name 'xray-sshd-auth.log.*' -o -name 'xray-sshd-auth.log-*' \) \
    -delete 2>/dev/null || true
exit 0
EOF_E142_LOG_EXTRA
    cat > "$dropin_tmp" <<EOF_E142_LOG_DROPIN
[Service]
ExecStartPost=$E142_LOG_EXTRA_SCRIPT
EOF_E142_LOG_DROPIN
    bash -n "$script_tmp" || return 1
    _e121_atomic_install "$script_tmp" "$E142_LOG_EXTRA_SCRIPT" 0755 || return 1
    install -d -m 0755 "$E142_LOG_DROPIN_DIR" || return 1
    _e121_atomic_install "$dropin_tmp" "$E142_LOG_DROPIN" 0644 || return 1
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    systemctl start xray-log-retention-e121.service >/dev/null 2>&1 || return 1
    systemctl is-enabled --quiet xray-log-retention-e121.timer 2>/dev/null || return 1
    info "嵌套WARP/fail2ban安装日志也已纳入3天清理。"
}

_e142_patch_dat_updater() {
    local tmp
    test -x "$UPDATE_DAT_SCRIPT" || return 1
    grep -q 'E142 exact MainPID socket ownership v2' "$UPDATE_DAT_SCRIPT" 2>/dev/null && return 0
    tmp=$(_e118_mktemp update-dat-e142.sh) || return 1
    awk '
      /^ok=0$/ && !done {
        print "# E142 exact MainPID socket ownership v2"
        print "pid_owns_port() {"
        print "    local proto=\"$1\" port=\"$2\" pid=\"$3\" want state table inode fd target"
        print "    case \"$port\" in \"\"|*[!0-9]*) return 1;; esac"
        print "    test \"$port\" -ge 1 && test \"$port\" -le 65535 || return 1"
        print "    case \"$pid\" in \"\"|0|*[!0-9]*) return 1;; esac"
        print "    want=$(printf '''%04X''' \"$port\")"
        print "    if test \"$proto\" = tcp; then state=0A; set -- /proc/net/tcp /proc/net/tcp6"
        print "    elif test \"$proto\" = udp; then state=07; set -- /proc/net/udp /proc/net/udp6; else return 1; fi"
        print "    for table in \"$@\"; do"
        print "        test -r \"$table\" || continue"
        print "        while IFS= read -r inode; do"
        print "            case \"$inode\" in \"\"|*[!0-9]*) continue;; esac"
        print "            for fd in \"/proc/$pid/fd/\"*; do"
        print "                test -L \"$fd\" || continue"
        print "                target=$(readlink -- \"$fd\" 2>/dev/null || true)"
        print "                test \"$target\" = \"socket:[$inode]\" && return 0"
        print "            done"
        print "        done < <(awk -v p=\"$want\" -v s=\"$state\" '\''NR>1{split($2,a,\":\"); if(toupper(a[2])==p && toupper($4)==s) print $10}'\'' \"$table\")"
        print "    done"
        print "    return 1"
        print "}"
        print "socket_ready() {"
        print "    local proto=\"$1\" port=\"$2\" pid=\"$3\" line out"
        print "    if test \"$proto\" = tcp; then out=$(ss -H -ltnp 2>/dev/null || true); else out=$(ss -H -lunp 2>/dev/null || true); fi"
        print "    while IFS= read -r line; do"
        print "        test -n \"$line\" || continue"
        print "        awk -v p=\":$port\" '\''$4 ~ p\"$\"{ok=1} END{exit !ok}'\'' <<< \"$line\" || continue"
        print "        if [[ \"$line\" == *\"users:\"* ]]; then [[ \"$line\" == *\"pid=$pid,\"* ]] && return 0; fi"
        print "    done <<< \"$out\""
        print "    pid_owns_port \"$proto\" \"$port\" \"$pid\""
        print "}"
        done=1
      }
      {print}
      END{if(!done) exit 42}
    ' "$UPDATE_DAT_SCRIPT" > "$tmp" || return 1
    bash -n "$tmp" || return 1
    _e118_atomic_install "$tmp" "$UPDATE_DAT_SCRIPT" 0755
}

if declare -F install_update_dat >/dev/null 2>&1; then
    eval "$(declare -f install_update_dat | sed '1s/install_update_dat/_e142_install_update_dat_base/')"
fi
install_update_dat() {
    local rc=0
    _e142_install_update_dat_base || rc=$?
    if test -x "$UPDATE_DAT_SCRIPT"; then
        _e142_patch_dat_updater || { error "DAT更新器MainPID探针加固失败。"; return 1; }
    fi
    return "$rc"
}

# Load optional in-tree modules before selecting the candidate.  This lets a
# modular BBR kernel expose bbr instead of silently falling back to cubic.
if declare -F _e139_network_apply >/dev/null 2>&1; then
    eval "$(declare -f _e139_network_apply | sed '1s/_e139_network_apply/_e142_network_apply_base/')"
fi
_e139_network_apply() {
    command -v modprobe >/dev/null 2>&1 && {
        modprobe tcp_bbr >/dev/null 2>&1 || true
        modprobe sch_fq >/dev/null 2>&1 || true
    }
    _e142_network_apply_base "$@"
}
_e138_network_apply() { _e139_network_apply "$@"; }
_e136_network_apply() { _e139_network_apply "$@"; }
_e135_network_apply() { _e139_network_apply "$@"; }

#------------------------------------------------------------------------------
# Cloudflare host-full: authenticated snapshot and race-free confirmation
#------------------------------------------------------------------------------
if declare -F _e140_full_snapshot >/dev/null 2>&1; then
    eval "$(declare -f _e140_full_snapshot | sed '1s/_e140_full_snapshot/_e142_full_snapshot_base/')"
fi
if declare -F _e140_full_restore_files >/dev/null 2>&1; then
    eval "$(declare -f _e140_full_restore_files | sed '1s/_e140_full_restore_files/_e142_full_restore_legacy/')"
fi

_e142_full_tx_ok() {
    local d="$1" real root
    test -d "$d" || return 1
    real=$(readlink -f -- "$d" 2>/dev/null || true); test -n "$real" || return 1
    for root in "$E142_TX_ROOT" "$E140_TX_ROOT"; do
        root=$(readlink -f -- "$root" 2>/dev/null || true); test -n "$root" || continue
        case "$real" in "$root"/*) return 0 ;; esac
    done
    return 1
}

_e140_full_snapshot() {
    local tx="$1" svc f rel
    _e142_full_tx_ok "$tx" || return 1
    _e142_full_snapshot_base "$tx" || return 1
    {
        echo "xray_was_active=$(systemctl is-active --quiet xray.service 2>/dev/null && echo 1 || echo 0)"
        echo "xray_was_enabled=$(systemctl is-enabled --quiet xray.service 2>/dev/null && echo 1 || echo 0)"
    } > "$tx/e142-runtime.env" || return 1
    : > "$tx/e142-services.env" || return 1
    for svc in xray-warp-full-e140-route.service xray-warp-full-e140-health.service \
      xray-warp-full-e140-health.timer xray-warp-full-e140-rollback.service \
      xray-warp-full-e140-rollback.timer; do
        printf '%s|%s|%s\n' "$svc" \
          "$(systemctl is-enabled "$svc" 2>/dev/null || true)" \
          "$(systemctl is-active "$svc" 2>/dev/null || true)" >> "$tx/e142-services.env" || return 1
    done
    : > "$tx/e142-snapshot.sha256" || return 1
    while IFS= read -r f; do
        rel=${f#"$tx"/}
        (cd "$tx" && sha256sum -- "$rel") >> "$tx/e142-snapshot.sha256" || return 1
    done < <(find "$tx" -maxdepth 1 -type f ! -name e142-snapshot.sha256 -print 2>/dev/null | sort)
    test -s "$tx/e142-snapshot.sha256"
}

_e142_full_snapshot_verify() {
    local tx="$1"
    _e142_full_tx_ok "$tx" || return 1
    test -s "$tx/e142-snapshot.sha256" || return 2
    (cd "$tx" && sha256sum -c e142-snapshot.sha256 >/dev/null 2>&1)
}

_e140_full_restore_files() {
    local tx="$1" p svc enabled active was_active=0 was_enabled=0 rc=0
    _e142_full_snapshot_verify "$tx" || return 1
    for p in "$CONFIG" "$E139_WARP_STATE" "$E140_FULL_ROUTE_SCRIPT" \
      "$E140_FULL_ROUTE_SERVICE" "$E140_FULL_HEALTH_SERVICE" "$E140_FULL_HEALTH_TIMER" \
      "$E140_FULL_ROLLBACK_SERVICE" "$E140_FULL_ROLLBACK_TIMER"; do
        _e135_restore_file "$p" "$tx/$(printf '%s' "$p" | sha256sum | awk '{print $1}')" || rc=1
    done
    systemctl daemon-reload >/dev/null 2>&1 || rc=1
    if test -s "$tx/e142-services.env"; then
        while IFS='|' read -r svc enabled active; do
            test -n "$svc" || continue
            if test "$enabled" = enabled; then systemctl enable "$svc" >/dev/null 2>&1 || rc=1
            else systemctl disable "$svc" >/dev/null 2>&1 || true; fi
            if test "$active" = active; then systemctl restart "$svc" >/dev/null 2>&1 || rc=1
            else systemctl stop "$svc" >/dev/null 2>&1 || true; fi
        done < "$tx/e142-services.env"
    fi
    was_active=$(sed -n 's/^xray_was_active=//p' "$tx/e142-runtime.env" | tail -n1); was_active=${was_active:-0}
    was_enabled=$(sed -n 's/^xray_was_enabled=//p' "$tx/e142-runtime.env" | tail -n1); was_enabled=${was_enabled:-0}
    fix_permissions
    if test "$was_enabled" = 1; then systemctl enable xray.service >/dev/null 2>&1 || rc=1
    else systemctl disable xray.service >/dev/null 2>&1 || true; fi
    if test "$was_active" = 1; then
        test -x "$XRAY_BIN" && "$XRAY_BIN" version >/dev/null 2>&1 || rc=1
        _e118_xray_test_config "$CONFIG" 1 || rc=1
        systemctl restart xray.service >/dev/null 2>&1 || rc=1
        test "$rc" -ne 0 || _e127_verify_xray_runtime "$CONFIG" 12 || rc=1
    else
        systemctl stop xray.service >/dev/null 2>&1 || true
    fi
    return "$rc"
}

_e140_full_rollback_tx() {
    local tx="$1" old_enabled=0 old_mode=disabled rc=0 verify_rc=0
    _e142_full_tx_ok "$tx" || { error "拒绝回滚事务根目录之外的路径：$tx"; return 1; }
    _e142_full_snapshot_verify "$tx" || verify_rc=$?
    _e140_warp_cli disconnect >/dev/null 2>&1 || true
    _e140_full_route_cleanup
    rm -f "$E140_FULL_PENDING" 2>/dev/null || true
    systemctl disable --now xray-warp-full-e140-rollback.timer >/dev/null 2>&1 || true
    if test "$verify_rc" -eq 0; then
        _e140_full_restore_files "$tx" || rc=1
    elif test "$verify_rc" -eq 2; then
        warn "检测到旧E140无校验快照，执行兼容回滚并强制复检Xray。"
        _e142_full_restore_legacy "$tx" || rc=1
        if test -s "$CONFIG" && systemctl is-active --quiet xray.service 2>/dev/null; then
            _e127_verify_xray_runtime "$CONFIG" 12 || rc=1
        fi
    else
        error "Cloudflare全隧道快照校验失败，拒绝使用损坏载荷。"
        rc=1
    fi
    old_enabled=$(sed -n 's/^old_enabled=//p' "$tx/old-state.env" 2>/dev/null | tail -n1); old_enabled=${old_enabled:-0}
    old_mode=$(sed -n 's/^old_mode=//p' "$tx/old-state.env" 2>/dev/null | tail -n1); old_mode=${old_mode:-disabled}
    if test "$rc" -eq 0 && test "$old_enabled" = 1 && [[ "$old_mode" =~ ^(selective|global)$ ]]; then
        _e139_local_warp_reconcile_base >/dev/null 2>&1 || rc=1
    fi
    if test "$old_mode" != host-full; then
        ip -4 rule show 2>/dev/null | grep -Eq "^${E140_FULL_RULE_PRIORITY}:" && rc=1 || true
        ip -4 route show table "$E140_FULL_TABLE" 2>/dev/null | grep -q . && rc=1 || true
    fi
    if test "$rc" -ne 0; then
        install -d -m 0700 "$E142_DIR" 2>/dev/null || true
        { echo "time=$(date -Is 2>/dev/null || date)"; echo "operation=warp-full-rollback"; echo "transaction=$tx"; } \
          > "${E142_CRITICAL_MARKER}.new.$$" 2>/dev/null \
          && chmod 0600 "${E142_CRITICAL_MARKER}.new.$$" 2>/dev/null \
          && mv -f -- "${E142_CRITICAL_MARKER}.new.$$" "$E142_CRITICAL_MARKER" 2>/dev/null || true
        error "全隧道回滚未能完整验证；恢复材料：$tx"
        return 1
    fi
    rm -f "$E142_CRITICAL_MARKER" 2>/dev/null || true
}

_e140_warp_full_enable() {
    local service_mode="${1:-traffic-only}" protocol="${2:-MASQUE}" token tx failed=0 confirm=""
    title "V199e142：Cloudflare系统全隧道（确认竞态修复版）"
    if _e140_full_mode_active; then
        error "系统全隧道已处于启用状态；拒绝叠加第二个启用事务，请使用修复/关闭入口。"
        return 1
    fi
    warn "将接管VPS新建出站；必须有网页控制台/VNC，并用第二SSH会话确认。"
    read -rp "输入 ENABLE-CLOUDFLARE-FULL-TUNNEL 确认: " token || true
    test "$token" = ENABLE-CLOUDFLARE-FULL-TUNNEL || return 0
    _e140_prepare || return 1
    _e138_warp_migrate_state >/dev/null 2>&1 || true
    tx=$(_e142_new_tx warp-full-enable) || return 1
    E140_ACTIVE_LOG="$E140_FULL_LOG_DIR/enable-$(date +%Y%m%d_%H%M%S)-$$.log"
    : > "$E140_ACTIVE_LOG" || return 1
    _e140_full_snapshot "$tx" || return 1

    _e140_set_stage package
    _e136_warp_install_package "$tx" || { E140_LAST_ERROR="cloudflare-warp安装/服务启用失败"; failed=1; }
    test "$failed" -ne 0 || { _e140_set_stage service-ipc; _e140_warp_service_wait || failed=1; }
    test "$failed" -ne 0 || { _e140_set_stage clear-xray-local-warp; _e139_clear_xray_warp_rules || failed=1; }
    test "$failed" -ne 0 || systemctl disable --now xray-warp-e136-health.timer xray-warp-e137-health.timer xray-warp-e138-health.timer >/dev/null 2>&1 || true
    test "$failed" -ne 0 || { _e140_set_stage capture-direct-route; _e140_capture_direct_route || { E140_LAST_ERROR="无法捕获原IPv4默认路由/源地址"; failed=1; }; }
    test "$failed" -ne 0 || _e139_state_set_fields route_enabled 1 route_mode host-full profile host-full \
      full_service_mode "$service_mode" full_protocol "$protocol" full_strict_loc non-cn managed_by e142 || failed=1
    test "$failed" -ne 0 || { _e140_set_stage install-units; _e140_full_install_units || failed=1; }
    test "$failed" -ne 0 || { _e140_set_stage reply-route; _e140_full_route_apply || { E140_LAST_ERROR="原IPv4回程策略路由建立失败"; failed=1; }; }
    if test "$failed" = 0; then
        printf '%s\n' "$tx" > "$E140_FULL_PENDING" || failed=1
        systemctl enable --now xray-warp-full-e140-rollback.timer >> "$E140_ACTIVE_LOG" 2>&1 || failed=1
    fi
    test "$failed" -ne 0 || { _e140_set_stage registration; _e140_warp_register || failed=1; }
    test "$failed" -ne 0 || { _e140_set_stage protocol; _e140_warp_set_protocol "$protocol" || failed=1; }
    test "$failed" -ne 0 || { _e140_set_stage mode; _e140_warp_set_mode "$service_mode" || failed=1; }
    test "$failed" -ne 0 || { _e140_set_stage connect; _e140_warp_connect_wait || failed=1; }
    test "$failed" -ne 0 || { _e140_set_stage final-verify; _e140_full_verify "$service_mode" "$protocol" || failed=1; }
    if test "$failed" -ne 0; then
        _e140_capture_diagnostics "$E140_ACTIVE_LOG"
        error "Cloudflare全隧道失败阶段：${E140_LAST_STAGE:-unknown} ${E140_LAST_ERROR:-}"
        _e140_full_rollback_tx "$tx" || true
        return 1
    fi
    warn "请在110秒内另开一个SSH窗口登录；成功后输入 KEEP-FULL-TUNNEL。"
    if read -r -t 110 -p "确认: " confirm && test "$confirm" = KEEP-FULL-TUNNEL; then
        # Reset the guard before the final checks.  Stopping it here would open
        # an unprotected kill/crash window; leaving the old deadline could race
        # the verification because confirmation may arrive near second 110.
        systemctl restart xray-warp-full-e140-rollback.timer >/dev/null 2>&1 || failed=1
        test "$failed" -ne 0 || systemctl is-active --quiet xray-warp-full-e140-rollback.timer 2>/dev/null || failed=1
        test "$failed" -ne 0 || _e140_full_verify "$service_mode" "$protocol" || failed=1
        test "$failed" -ne 0 || systemctl enable --now xray-warp-full-e140-route.service xray-warp-full-e140-health.timer >/dev/null 2>&1 || failed=1
        test "$failed" -ne 0 || systemctl is-enabled --quiet xray-warp-full-e140-health.timer 2>/dev/null || failed=1
        if test "$failed" -eq 0; then
            rm -f "$E140_FULL_PENDING" || failed=1
        fi
        if test "$failed" -eq 0; then
            systemctl disable --now xray-warp-full-e140-rollback.timer >/dev/null 2>&1 || failed=1
            systemctl is-active --quiet xray-warp-full-e140-rollback.timer 2>/dev/null && failed=1 || true
        fi
        if test "$failed" -eq 0; then
            info "Cloudflare系统全隧道已启用、复检并解除自动回滚。日志：$E140_ACTIVE_LOG"
            _e140_warp_status
            return 0
        fi
        error "确认后的最终固化失败，执行显式回滚。"
        _e140_full_rollback_tx "$tx" || true
        return 1
    fi
    warn "未完成第二SSH会话确认，执行安全回滚。"
    _e140_full_rollback_tx "$tx"
    return 1
}

# Never disable TLS verification for the trace fallback.
_e140_full_trace() {
    local out
    out=$(curl -4 -fsS --noproxy '*' --connect-timeout 5 --max-time 15 https://www.cloudflare.com/cdn-cgi/trace 2>/dev/null || true)
    test -n "$out" || out=$(curl -4 -fsS --noproxy '*' --connect-timeout 5 --max-time 15 https://1.1.1.1/cdn-cgi/trace 2>/dev/null || true)
    printf '%s' "$out"
}

#------------------------------------------------------------------------------
# Full hot-update transaction
#------------------------------------------------------------------------------
_e142_hot_update() {
    local protect sysbackup rc=0 rollback_rc=0 was_active=0 enabled=0 mode=disabled profile=disabled
    local e140_dir_preexisting=0 e142_dir_preexisting=0
    E135_NEW_PACKAGES=()
    test -e "$E140_DIR" && e140_dir_preexisting=1 || true
    test -e "$E142_DIR" && e142_dir_preexisting=1 || true
    _e140_prepare || return 1
    _e142_prepare || return 1
    _e138_warp_migrate_state >/dev/null 2>&1 || true
    enabled=$(_e138_state_get route_enabled 0)
    mode=$(_e138_state_get route_mode disabled)
    profile=$(_e138_state_get profile disabled)
    protect=$(_e116_backup_state before_hot_update_e142) || return 1
    _e118_save_core_payload "$protect" || return 1
    was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2>/dev/null | tail -n1); was_active=${was_active:-0}
    sysbackup=$(_e142_new_tx hot-update) || return 1
    _e140_system_snapshot "$sysbackup" || { error "E142系统快照失败。"; return 1; }

    _e135_require_runtime_tools || rc=1
    test "$rc" -ne 0 || _e135_disable_legacy_optimizers || rc=1
    test "$rc" -ne 0 || _e140_install_self || rc=1
    test "$rc" -ne 0 || install_update_dat || rc=1
    test "$rc" -ne 0 || systemctl enable --now xray-dat-update.timer >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || _e105_disable_xray_core_auto_update || rc=1
    test "$rc" -ne 0 || _e137_apply_init_window_default30 || rc=1
    test "$rc" -ne 0 || _e139_network_apply balanced force || rc=1
    test "$rc" -ne 0 || _e121_install_log_retention || rc=1
    test "$rc" -ne 0 || _e141_install_ssh_guard || rc=1
    test "$rc" -ne 0 || fix_xray_systemd_limits || rc=1
    if test "$rc" = 0 && test "$enabled" = 1; then
        if test "$mode" = host-full; then
            _e140_full_install_units || rc=1
            test "$rc" -ne 0 || _e140_warp_full_reconcile || rc=1
        else
            _e137_warp_connect_local_proxy || rc=1
            test "$rc" -ne 0 || _e138_xray_apply_warp "$mode" "$profile" true || rc=1
            test "$rc" -ne 0 || _e138_warp_health_install || rc=1
        fi
    fi
    test "$rc" -ne 0 || _e142_write_version || rc=1

    # Xray survival gate applies even when the service was intentionally
    # stopped: the binary and current configuration must still parse.
    test "$rc" -ne 0 || { test -x "$XRAY_BIN" && "$XRAY_BIN" version >/dev/null 2>&1; } || rc=1
    if test "$rc" = 0 && test -s "$CONFIG"; then _e118_xray_test_config "$CONFIG" 1 || rc=1; fi
    if test "$rc" = 0 && test "$was_active" = 1; then
        _e127_verify_xray_runtime "$CONFIG" 12 || rc=1
        test "$rc" -ne 0 || _e131_verify_nice_runtime || rc=1
    elif test "$rc" = 0 && systemctl is-active --quiet xray.service 2>/dev/null; then
        error "热更新意外启动了原本停止的Xray服务。"
        rc=1
    fi

    test "$rc" -ne 0 || test "$(sysctl -n net.ipv4.tcp_notsent_lowat 2>/dev/null)" = 131072 || rc=1
    test "$rc" -ne 0 || test "$(sysctl -n net.ipv6.conf.all.disable_ipv6 2>/dev/null)" = 1 || rc=1
    test "$rc" -ne 0 || grep -Eq 'initcwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1
    test "$rc" -ne 0 || grep -Eq 'initrwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1
    test "$rc" -ne 0 || systemctl is-enabled --quiet xray-dat-update.timer 2>/dev/null || rc=1
    test "$rc" -ne 0 || systemctl is-enabled --quiet xray-log-retention-e121.timer 2>/dev/null || rc=1
    test "$rc" -ne 0 || systemctl is-enabled --quiet xray-ssh-auth-audit-e142.timer 2>/dev/null || rc=1
    test "$rc" -ne 0 || test -x "$E142_LOG_EXTRA_SCRIPT" || rc=1
    test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$SYMLINK" || rc=1
    test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$E142_SELF_PATH" || rc=1

    if test "$rc" -ne 0; then
        error "E142热更新失败，恢复系统文件、Core、Xray、WARP、防火墙和服务状态。"
        _e140_system_restore "$sysbackup" || rollback_rc=1
        _e118_restore_core_payload "$protect" >/dev/null 2>&1 || rollback_rc=1
        _e118_restore_state "$protect" >/dev/null 2>&1 || rollback_rc=1
        _e135_remove_new_runtime_tools || true
        test "$e142_dir_preexisting" = 1 || rmdir "$E142_DIR" 2>/dev/null || true
        test "$e140_dir_preexisting" = 1 || rmdir "$E140_DIR" 2>/dev/null || true
        if test "$was_active" = 1; then _e127_verify_xray_runtime "$CONFIG" 12 >/dev/null 2>&1 || rollback_rc=1; fi
        if test "$rollback_rc" -ne 0; then
            install -d -m 0700 "$E142_DIR" 2>/dev/null || true
            { echo "time=$(date -Is 2>/dev/null || date)"; echo "operation=hot-update"; echo "system_backup=$sysbackup"; echo "core_backup=$protect"; } \
              > "${E142_CRITICAL_MARKER}.new.$$" 2>/dev/null \
              && chmod 0600 "${E142_CRITICAL_MARKER}.new.$$" 2>/dev/null \
              && mv -f -- "${E142_CRITICAL_MARKER}.new.$$" "$E142_CRITICAL_MARKER" 2>/dev/null || true
            error "严重：热更新回滚未通过复检。系统快照：$sysbackup；Core快照：$protect"
        fi
        return 1
    fi
    rm -f "$E142_CRITICAL_MARKER" 2>/dev/null || true
    _e142_prune_transactions "$sysbackup" "$protect" \
      || warn "旧系统事务快照收敛未完成；当前热更新结果不受影响。"
    info "V199e142热更新完成。系统快照：$sysbackup"
    info "已验证：Xray Core/配置/运行态、init30、notsent=131072、IPv6关闭、3天日志、SSH认证策略；WARP mode=$mode。"
}
hot_update_from_legacy() { _e142_hot_update; }

#------------------------------------------------------------------------------
# Controlled uninstall: verified archive, WARP teardown and sysctl ownership
#------------------------------------------------------------------------------
_e142_restore_network_tx() {
    local tx="$1" kind="$2" src hash digest expect actual key old rc=0 dir_preexisting=1
    test -d "$tx" && test -s "$tx/runtime.env" || return 1
    _e142_verify_network_tx_seal "$tx" || return 1
    if test -s "$tx/manifest.tsv"; then
        while IFS=$'\t' read -r src hash digest; do
            test -n "$src" && [[ "$hash" =~ ^[0-9a-f]{64}$ ]] || return 1
            case "$src" in /etc/sysctl.conf|/etc/sysctl.d/*.conf) ;; *) error "拒绝恢复非sysctl路径：$src"; return 1 ;; esac
            expect=$(printf '%s' "$src" | sha256sum | awk '{print $1}')
            test "$expect" = "$hash" && test -f "$tx/files/$hash" || return 1
            if test -n "$digest"; then
                [[ "$digest" =~ ^[0-9a-f]{64}$ ]] || return 1
                actual=$(sha256sum "$tx/files/$hash" 2>/dev/null | awk '{print $1}')
                test "$actual" = "$digest" || return 1
            fi
        done < "$tx/manifest.tsv"
    fi
    case "$kind" in
      e139)
        _e135_restore_file "$E139_NETWORK_CONF" "$tx/e139-conf" || rc=1
        _e135_restore_file "$E138_NETWORK_CONF" "$tx/e138-conf" || rc=1
        _e135_restore_file "$E136_NETWORK_CONF" "$tx/e136-conf" || rc=1
        _e135_restore_file "$E135_NETWORK_CONF" "$tx/e135-conf" || rc=1
        ;;
      e138)
        _e135_restore_file "$E138_NETWORK_CONF" "$tx/e138-conf" || rc=1
        _e135_restore_file "$E136_NETWORK_CONF" "$tx/e136-conf" || rc=1
        _e135_restore_file "$E135_NETWORK_CONF" "$tx/e135-conf" || rc=1
        ;;
      *) return 1 ;;
    esac
    _e138_network_restore_files "$tx" || rc=1
    while IFS='|' read -r key old; do
        test -n "$key" || continue
        test -z "$old" || sysctl -w "$key=$old" >/dev/null 2>&1 || rc=1
    done < "$tx/runtime.env"
    if test "$kind" = e139 && test -s "$tx/meta.env"; then
        dir_preexisting=$(sed -n 's/^dir_preexisting=//p' "$tx/meta.env" | tail -n1); dir_preexisting=${dir_preexisting:-1}
        test "$dir_preexisting" = 1 || rmdir /etc/sysctl.d 2>/dev/null || true
    fi
    return "$rc"
}

_e142_restore_network_baseline() {
    local row name tx kind root real rc=0
    local listing
    listing=$(_e118_mktemp network-uninstall-list) || return 1
    : > "$listing" || return 1
    for kind in e139 e138; do
        if test "$kind" = e139; then root=$E139_TX_ROOT; else root=$E138_TX_ROOT; fi
        test -d "$root" || continue
        while IFS= read -r tx; do
            test -n "$tx" || continue
            name=$(basename -- "$tx")
            printf '%s|%s|%s\n' "$name" "$kind" "$tx" >> "$listing"
        done < <(find "$root" -mindepth 1 -maxdepth 1 -type d -name 'network-*' -print 2>/dev/null)
    done
    while IFS='|' read -r name kind tx; do
        test -n "$tx" || continue
        if test "$kind" = e139; then root=$E139_TX_ROOT; else root=$E138_TX_ROOT; fi
        real=$(readlink -f -- "$tx" 2>/dev/null || true)
        case "$real" in "$root"/*) ;; *) error "非法网络事务路径：$tx"; return 1 ;; esac
        _e142_restore_network_tx "$tx" "$kind" || { error "网络基线事务恢复失败：$tx"; rc=1; break; }
    done < <(sort -r "$listing")
    return "$rc"
}

_e142_create_uninstall_archive() {
    local archive="$1" list p
    list=$(_e118_mktemp uninstall-files-e142) || return 1
    : > "$list" || return 1
    for p in "$CONFIG_DIR" "$SCRIPT_DIR" "$DAT_DIR" "$LOG_DIR" "$XRAY_BIN" "$SYMLINK"; do
        if test -e "$p" || test -L "$p"; then printf '%s\n' "${p#/}" >> "$list"; fi
    done
    find /etc/systemd/system -maxdepth 2 \( -type f -o -type d -o -type l \) -name 'xray*' -printf '%p\n' 2>/dev/null \
      | sed 's#^/##' >> "$list" || true
    find /etc/sysctl.d /etc/fail2ban /etc/rsyslog.d -maxdepth 3 -type f \
      \( -name '*xray*' -o -name '99-xray-*' -o -name 'zz-xray-*' \) -printf '%p\n' 2>/dev/null \
      | sed 's#^/##' >> "$list" || true
    awk 'NF&&!seen[$0]++' "$list" > "${list}.unique" || return 1
    test -s "${list}.unique" || return 1
    tar -C / -czf "$archive" -T "${list}.unique" 2>/dev/null || return 1
    chmod 0600 "$archive" || return 1
    test -s "$archive" && tar -tzf "$archive" >/dev/null 2>&1
}

_e142_restore_preexisting_journal_policy() {
    local dir="$E118_BACKUP_DIR/log-retention-e121" src="" target="/etc/systemd/journald.conf.d/99-xray-volatile.conf"
    test -d "$dir" || return 0
    src=$(find "$dir" -maxdepth 1 -type f -name '99-xray-volatile.conf.*.bak' -printf '%T@\t%p\n' 2>/dev/null \
      | sort -nr | awk -F '\t' 'NR==1{print $2}')
    test -n "$src" && test -f "$src" || return 0
    # A policy recreated by the administrator after installation wins.
    if test -e "$target" || test -L "$target"; then return 0; fi
    _e214_ensure_parent_dir "$target" || return 1
    _e142_atomic_text "$src" "$target" 0644 || return 1
    if grep -Eqi '^[[:space:]]*Storage[[:space:]]*=[[:space:]]*volatile([[:space:]]|$)' "$src"; then
        rm -rf -- /var/log/journal 2>/dev/null || return 1
    fi
    info "已恢复安装前journald策略：$target"
}

do_uninstall() {
    local confirm="" archive
    local enabled mode
    archive="/root/xray-before-uninstall-e142-$(date +%Y%m%d_%H%M%S)-$$.tgz"
    title "V199e142：受控卸载 Xray 环境"
    warn "先创建可读回归档，再关闭脚本管理的WARP、恢复网络基线，最后移除Xray。"
    warn "cloudflare-warp软件包不会被删除，但脚本管理的连接和策略路由会关闭。"
    read -rp "请输入 DELETE-XRAY 确认: " confirm || true
    test "$confirm" = DELETE-XRAY || { info "已取消，系统未修改。"; return 0; }
    _e142_create_uninstall_archive "$archive" \
      || { error "卸载前归档创建或读回失败；拒绝执行删除。"; return 1; }
    info "已验证卸载前归档：$archive"

    _e138_warp_migrate_state >/dev/null 2>&1 || true
    enabled=$(_e138_state_get route_enabled 0); mode=$(_e138_state_get route_mode disabled)
    if test "$enabled" = 1; then
        _e138_warp_disable || { error "WARP关闭失败，拒绝继续卸载。"; return 1; }
    fi
    _e140_full_route_cleanup
    ip -4 rule show 2>/dev/null | grep -Eq "^(${E140_FULL_RULE_PRIORITY}|${E139_FULL_RULE_PRIORITY}):" \
      && { error "仍存在脚本管理的全隧道策略规则，拒绝删除恢复材料。"; return 1; } || true

    _e142_restore_network_baseline || return 1
    _e126_remove_layer uninstall || return 1
    rm -f -- "$E135_NETWORK_CONF" "$E136_NETWORK_CONF" "$E138_NETWORK_CONF" "$E139_NETWORK_CONF" 2>/dev/null || true
    sysctl --system >/dev/null 2>&1 || warn "其它系统sysctl文件存在加载错误；已恢复的逐项运行基线仍保留。"
    systemctl disable --now xray-log-retention-e121.timer xray-log-retention-e121.service >/dev/null 2>&1 || true
    rm -rf -- "$E142_LOG_DROPIN_DIR" 2>/dev/null || true
    rm -f -- "$E142_LOG_EXTRA_SCRIPT" 2>/dev/null || true
    systemctl daemon-reload >/dev/null 2>&1 || true
    _e142_restore_preexisting_journal_policy \
      || { error "安装前journald策略恢复失败，拒绝删除其备份。"; return 1; }
    _e121_do_uninstall <<< 'DELETE-XRAY'
}

_e141_self_test() {
    local rc=0 body sample mode
    echo "V199e141 release gate:"
    test "$SCRIPT_VERSION" = 199e141 && echo "  [PASS] version" || { echo "  [FAIL] version=$SCRIPT_VERSION"; rc=1; }
    body="$(declare -f _e141_sshd_auth_profile)$(declare -f _e141_install_fail2ban_package)$(declare -f _e141_install_ssh_guard)"
    [[ "$body" == *'passwordauthentication'* && "$body" == *'kbdinteractiveauthentication'* && "$body" == *'dpkg --configure -a'* && "$body" == *'_e141_wait_apt_locks'* ]] && echo "  [PASS] key-only detection and truthful installer" || { echo "  [FAIL] SSH/package state machine"; rc=1; }
    body="$(declare -f _e141_install_key_only_ssh_guard)"
    [[ "$body" == *'_e121_write_ssh_port_guard'* && "$body" == *'_e121_verify_ssh_port_guard'* && "$body" != *'_e121_install_fail2ban_guard'* ]] && echo "  [PASS] key-only path skips fail2ban" || { echo "  [FAIL] key-only path"; rc=1; }
    body="$(declare -f _e141_hot_update_base)"
    [[ "$body" == *'_e135_install_ssh_guard'* && "$body" == *'E141_VERSION'* ]] && echo "  [PASS] E141 hot-update SSH path" || { echo "  [FAIL] hot-update override"; rc=1; }
    bash -n "$SCRIPT_PATH" >/dev/null 2>&1 && echo "  [PASS] bash syntax" || { echo "  [FAIL] bash syntax"; rc=1; }
    test "$rc" -eq 0 && echo "V199e141 result: PASS" || echo "V199e141 result: FAIL"
    return "$rc"
}
_e140_self_test() { _e141_self_test; }

if declare -F _e140_help >/dev/null 2>&1; then
    eval "$(declare -f _e140_help | sed '1s/_e140_help/_e141_help_base/')"
fi
_e141_help() {
    _e141_help_base | sed 's/ex199e140/ex199e141/g; s/V199e140/V199e141/g'
    cat <<'EOF_E141_HELP'
  --ssh-auth-status           查看sshd真实有效认证模式与fail2ban决策
  --fail2ban-install-log      查看最近一次fail2ban安装原始日志
EOF_E141_HELP
}
_e140_help() { _e141_help; }

#==============================================================================
# V199e142 RELIABILITY OVERRIDE
# 只覆盖最终活动入口；旧函数保留用于兼容历史状态和回滚快照。
#==============================================================================
readonly E142_VERSION="199e142"
readonly E142_DIR="$CONFIG_DIR/e142"
readonly E142_TX_ROOT="/var/backups/xray-e142"
readonly E142_SELF_PATH="$SCRIPT_DIR/ex199e142.sh"
readonly E142_LOG_EXTRA_SCRIPT="/usr/local/bin/xray-log-retention-e142-extra.sh"
readonly E142_LOG_DROPIN_DIR="/etc/systemd/system/xray-log-retention-e121.service.d"
readonly E142_LOG_DROPIN="$E142_LOG_DROPIN_DIR/99-e142-nested.conf"
readonly E142_SSH_AUTH_SERVICE="/etc/systemd/system/xray-ssh-auth-audit-e142.service"
readonly E142_SSH_AUTH_TIMER="/etc/systemd/system/xray-ssh-auth-audit-e142.timer"
readonly E142_CRITICAL_MARKER="$E142_DIR/CRITICAL_RECOVERY_REQUIRED.env"
readonly E142_XRAY_INSTALL_COMMIT="e741a4f56d368afbb9e5be3361b40c4552d3710d"
readonly E142_XRAY_INSTALL_SHA256="7f70c95f6b418da8b4f4883343d602964915e28748993870fd554383afdbe555"

_e142_prepare() {
    _e118_runtime_init || return 1
    install -d -m 0700 "$E142_DIR" "$E142_TX_ROOT" || return 1
    install -d -m 0755 "$SCRIPT_DIR" "$LOG_DIR" || return 1
}

_e142_new_tx() {
    local name="${1:-tx}" safe d
    _e142_prepare || return 1
    safe=$(printf '%s' "$name" | tr -c 'A-Za-z0-9_.-' '_')
    test -n "$safe" || safe=tx
    d="$E142_TX_ROOT/${safe}-$(date +%Y%m%d_%H%M%S)-$$-$RANDOM"
    install -d -m 0700 "$d" || return 1
    printf '%s\n' "$d"
}

_e142_tx_dir_ok() {
    local d="$1" real root
    test -d "$d" || return 1
    real=$(readlink -f -- "$d" 2>/dev/null || true)
    root=$(readlink -f -- "$E142_TX_ROOT" 2>/dev/null || true)
    test -n "$real" && test -n "$root" || return 1
    case "$real" in "$root"/*) return 0 ;; *) return 1 ;; esac
}

_e142_network_tx_dir_ok() {
    local d="$1" real root
    test -d "$d" || return 1
    real=$(readlink -f -- "$d" 2>/dev/null || true); test -n "$real" || return 1
    for root in "$E139_TX_ROOT" "$E138_TX_ROOT"; do
        root=$(readlink -f -- "$root" 2>/dev/null || true); test -n "$root" || continue
        case "$real" in "$root"/*) return 0 ;; esac
    done
    return 1
}

_e142_seal_network_tx() {
    local tx="$1" f rel seal
    _e142_network_tx_dir_ok "$tx" || return 1
    seal="$tx/e142-transaction.sha256"
    : > "$seal" || return 1
    while IFS= read -r -d '' f; do
        rel=${f#"$tx"/}
        (cd "$tx" && sha256sum -- "$rel") >> "$seal" || return 1
    done < <(find "$tx" -type f ! -name e142-transaction.sha256 -print0 2>/dev/null | sort -z)
    test -s "$seal"
}

_e142_verify_network_tx_seal() {
    local tx="$1"
    _e142_network_tx_dir_ok "$tx" || return 1
    test ! -e "$tx/e142-transaction.sha256" \
      || { test -s "$tx/e142-transaction.sha256" \
        && (cd "$tx" && sha256sum -c e142-transaction.sha256 >/dev/null 2>&1); }
}

_e142_atomic_text() {
    local src="$1" dst="$2" mode="${3:-0600}" stage parent name
    _e214_ensure_parent_dir "$dst" || return 1
    parent=$(dirname -- "$dst") || return 1
    name=${dst##*/}
    stage=$(mktemp --tmpdir="$parent" ".${name}.e142-new.XXXXXX") || return 1
    install -m "$mode" "$src" "$stage" || { rm -f -- "$stage"; return 1; }
    mv -f -- "$stage" "$dst" || { rm -f -- "$stage"; return 1; }
}

_e142_write_version() {
    local tmp
    tmp=$(_e118_mktemp version-e142) || return 1
    printf '%s\n' "$E142_VERSION" > "$tmp" || return 1
    _e142_atomic_text "$tmp" "$SCRIPT_VERSION_FILE" 0600
}

_e140_hot_update_preflight() {
    local c
    test "$EUID" -eq 0 || { error "热更新必须使用root。"; return 1; }
    for c in systemctl jq curl ip ss tar install sha256sum cp awk sed grep dirname mkdir mv cmp find \
      sort readlink xargs base64 paste tr chmod sysctl; do
        command -v "$c" >/dev/null 2>&1 || { error "热更新预检缺少命令：$c"; return 1; }
    done
    test -r "$SCRIPT_PATH" || return 1
    test -d /run/systemd/system || { error "当前环境没有运行中的systemd。"; return 1; }
    # Do not create /etc/sysctl.d here: creation must occur inside the network
    # transaction so a failed hot update can restore the original absence.
    if test -e /etc/sysctl.d; then test -d /etc/sysctl.d && test -w /etc/sysctl.d || return 1
    else test -w /etc || return 1; fi
    install -d -m 0700 "$E142_TX_ROOT" || return 1
}

# Pin the official installer to a reviewed commit and content hash.  Upstream
# changes now fail closed instead of executing a mutable main-branch script.
_e118_download_official_installer() {
    local out="$1" url actual
    local -a urls=(
      "https://raw.githubusercontent.com/XTLS/Xray-install/$E142_XRAY_INSTALL_COMMIT/install-release.sh"
      "https://github.com/XTLS/Xray-install/raw/$E142_XRAY_INSTALL_COMMIT/install-release.sh"
    )
    for url in "${urls[@]}"; do
        : > "$out" || return 1
        curl --proto '=https' --tlsv1.2 -fsSL --show-error --retry 3 \
          --connect-timeout 10 --max-time 180 -o "$out" "$url" || continue
        actual=$(sha256sum "$out" 2>/dev/null | awk '{print $1}')
        test "$actual" = "$E142_XRAY_INSTALL_SHA256" || continue
        head -n1 "$out" | grep -qE '^#!/usr/bin/env bash|^#!/bin/bash' || continue
        grep -q 'XTLS/Xray-install' "$out" || continue
        bash -n "$out" || continue
        chmod 0700 "$out" || return 1
        return 0
    done
    : > "$out" 2>/dev/null || true
    return 1
}

# Self-install is one four-target transaction.  A partial xrv/script replacement
# is restored immediately, so boot services never point at a half-updated file.
_e140_install_self() {
    local tx target snap tmp failed=0
    local -a targets=("$SYMLINK" "$E140_SELF_PATH" "$E142_SELF_PATH" "$E140_LATEST_PATH")
    test -r "$SCRIPT_PATH" || return 1
    _e142_prepare || return 1
    tx=$(_e142_new_tx self-install) || return 1
    for target in "${targets[@]}"; do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
        _e135_snapshot_file "$target" "$snap" || return 1
    done
    for target in "${targets[@]}"; do
        install -d -m 0755 "$(dirname -- "$target")" || { failed=1; break; }
        tmp="${target}.e142-new.$$"
        install -m 0755 "$SCRIPT_PATH" "$tmp" || { failed=1; break; }
        mv -f -- "$tmp" "$target" || { rm -f -- "$tmp"; failed=1; break; }
        cmp -s "$SCRIPT_PATH" "$target" || { failed=1; break; }
    done
    if test "$failed" -ne 0; then
        for target in "${targets[@]}"; do
            snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
            _e135_restore_file "$target" "$snap" || true
        done
        return 1
    fi
    hash -r 2>/dev/null || true
}
_e139_install_self() { _e140_install_self; }
_e138_install_self() { _e140_install_self; }
_e137_install_self() { _e140_install_self; }
_e136_install_self() { _e140_install_self; }
_e118_install_self() { _e140_install_self; }

# The active E141 snapshot omitted all E140/E141 files and the superseded
# volatile-journal file.  Add every file mutated by the final hot-update layer.
if declare -F _e138_system_paths >/dev/null 2>&1; then
    eval "$(declare -f _e138_system_paths | sed '1s/_e138_system_paths/_e142_system_paths_base/')"
fi
_e138_system_paths() {
    _e142_system_paths_base
    cat <<EOF_E142_PATHS
$SYMLINK
$E140_DIR
$E140_SELF_PATH
$E140_LATEST_PATH
$E140_FULL_ROUTE_SCRIPT
$E140_FULL_ROUTE_SERVICE
$E140_FULL_HEALTH_SERVICE
$E140_FULL_HEALTH_TIMER
$E140_FULL_ROLLBACK_SERVICE
$E140_FULL_ROLLBACK_TIMER
$E141_DIR
$E141_SSH_AUTH_STATE
$E142_DIR
$E142_SELF_PATH
$E142_LOG_EXTRA_SCRIPT
$E142_LOG_DROPIN_DIR
$E142_SSH_AUTH_SERVICE
$E142_SSH_AUTH_TIMER
/etc/systemd/journald.conf.d/99-xray-volatile.conf
EOF_E142_PATHS
}

# Hash the E140 service-state control file before it can drive restoration.
_e140_system_snapshot() {
    local b="$1" svc
    _e139_system_snapshot "$b" || return 1
    : > "$b/e140-services.env" || return 1
    for svc in \
      xray-warp-full-e140-route.service xray-warp-full-e140-health.service \
      xray-warp-full-e140-health.timer xray-warp-full-e140-rollback.service \
      xray-warp-full-e140-rollback.timer \
      xray-ssh-port-guard-e121.service xray-ssh-port-guard-e121.timer \
      xray-log-retention-e121.service xray-log-retention-e121.timer \
      xray-ssh-auth-audit-e142.service xray-ssh-auth-audit-e142.timer; do
        printf '%s|%s|%s\n' "$svc" \
          "$(systemctl is-enabled "$svc" 2>/dev/null || true)" \
          "$(systemctl is-active "$svc" 2>/dev/null || true)" >> "$b/e140-services.env" || return 1
    done
    {
        echo "journal_dir_preexisting=$(test -e /var/log/journal && echo 1 || echo 0)"
        echo "journald_dropin_dir_preexisting=$(test -e /etc/systemd/journald.conf.d && echo 1 || echo 0)"
    } > "$b/e142-prestate.env" || return 1
    (cd "$b" && sha256sum e140-services.env e142-prestate.env > e140-services.sha256) || return 1
}

_e140_system_restore() {
    local b="$1" svc enabled active rc=0 journal_pre=1 dropin_pre=1
    test -d "$b" || return 1
    if test -e "$b/e139-services.env"; then
        test -s "$b/e139-services.sha256" \
          && (cd "$b" && sha256sum -c e139-services.sha256 >/dev/null 2>&1) \
          || { error "E139服务状态快照校验失败，拒绝恢复。"; return 1; }
    fi
    if test -e "$b/e140-services.env"; then
        test -s "$b/e140-services.sha256" \
          && (cd "$b" && sha256sum -c e140-services.sha256 >/dev/null 2>&1) \
          || { error "E140服务状态快照校验失败，拒绝恢复。"; return 1; }
    fi
    _e139_system_restore "$b" || return 1
    if test -s "$b/e140-services.env"; then
        while IFS='|' read -r svc enabled active; do
            test -n "$svc" || continue
            if test "$enabled" = enabled; then systemctl enable "$svc" >/dev/null 2>&1 || rc=1
            else systemctl disable "$svc" >/dev/null 2>&1 || true; fi
            if test "$active" = active; then systemctl restart "$svc" >/dev/null 2>&1 || rc=1
            else systemctl stop "$svc" >/dev/null 2>&1 || true; fi
        done < "$b/e140-services.env"
    fi
    if test -s "$b/e142-prestate.env"; then
        journal_pre=$(sed -n 's/^journal_dir_preexisting=//p' "$b/e142-prestate.env" | tail -n1)
        dropin_pre=$(sed -n 's/^journald_dropin_dir_preexisting=//p' "$b/e142-prestate.env" | tail -n1)
        [[ "$journal_pre" =~ ^[01]$ ]] || return 1
        [[ "$dropin_pre" =~ ^[01]$ ]] || return 1
        test "$journal_pre" = 1 || rm -rf -- /var/log/journal 2>/dev/null || rc=1
        test "$dropin_pre" = 1 || rmdir /etc/systemd/journald.conf.d 2>/dev/null || true
    fi
    # A rollback can restore/remove journald drop-ins; reload the daemon so the
    # restored retention policy is the effective policy, not only disk state.
    systemctl restart systemd-journald.service >/dev/null 2>&1 || rc=1
    return "$rc"
}

# Existing-but-broken executables were previously accepted as a valid Core.
if declare -F e76_install_or_update_xray_core >/dev/null 2>&1; then
    eval "$(declare -f e76_install_or_update_xray_core | sed '1s/e76_install_or_update_xray_core/_e142_core_install_base/')"
fi
e76_install_or_update_xray_core() {
    local installer logf
    title "V199e142：安装 / 确认 Xray Core"
    if test -x "$XRAY_BIN" && "$XRAY_BIN" version >/dev/null 2>&1; then
        info "检测到可执行Xray Core：$($XRAY_BIN version 2>/dev/null | head -n1)"
        return 0
    fi
    test ! -e "$XRAY_BIN" || warn "现有Xray文件不能正常执行；将在外层Core快照保护下进行修复。"
    installer=$(_e118_mktemp xray-install-e142.sh) || return 1
    logf=$(_e118_mktemp xray-install-e142.log) || return 1
    _e118_download_official_installer "$installer" \
      || { error "固定版本的官方Xray安装器下载/哈希校验失败。"; return 1; }
    if ! bash "$installer" install > "$logf" 2>&1; then
        error "Xray Core安装/修复失败。"
        tail -n 100 "$logf" 2>/dev/null | sed 's/^/    /' || true
        return 1
    fi
    test -x "$XRAY_BIN" && "$XRAY_BIN" version >/dev/null 2>&1 \
      || { error "安装器结束后Xray Core仍不可执行。"; return 1; }
    info "Xray Core安装完成：$($XRAY_BIN version 2>/dev/null | head -n1)"
}

# Exact fallback for kernels that omit users: from ss output.  Match the
# listening/unconnected inode in /proc/net to an fd owned by systemd MainPID.
_e142_pid_owns_socket_port() {
    local proto="$1" port="$2" pid="$3" want state table inode fd target
    [[ "$port" =~ ^[0-9]+$ ]] && ((port >= 1 && port <= 65535)) \
      && [[ "$pid" =~ ^[1-9][0-9]*$ ]] || return 1
    want=$(printf '%04X' "$port")
    case "$proto" in
      tcp) state=0A; set -- /proc/net/tcp /proc/net/tcp6 ;;
      udp) state=07; set -- /proc/net/udp /proc/net/udp6 ;;
      *) return 1 ;;
    esac
    for table in "$@"; do
        test -r "$table" || continue
        while IFS= read -r inode; do
            [[ "$inode" =~ ^[0-9]+$ ]] || continue
            for fd in "/proc/$pid/fd/"*; do
                test -L "$fd" || continue
                target=$(readlink -- "$fd" 2>/dev/null || true)
                test "$target" = "socket:[$inode]" && return 0
            done
        done < <(awk -v p="$want" -v s="$state" \
          'NR>1{split($2,a,":"); if(toupper(a[2])==p && toupper($4)==s) print $10}' "$table")
    done
    return 1
}

# A listening socket must belong to the service MainPID.  Merely seeing
# another process named "xray", or an ownerless line for that port, is not
# sufficient.
_e127_socket_ready() {
    local proto="$1" port="$2" pid="$3" line out
    [[ "$port" =~ ^[0-9]+$ ]] && [[ "$pid" =~ ^[1-9][0-9]*$ ]] || return 1
    case "$proto" in
      tcp) out=$(ss -H -ltnp 2>/dev/null || true) ;;
      udp) out=$(ss -H -lunp 2>/dev/null || true) ;;
      *) return 1 ;;
    esac
    while IFS= read -r line; do
        test -n "$line" || continue
        awk -v p=":$port" '$4 ~ p"$"{ok=1} END{exit !ok}' <<< "$line" || continue
        if [[ "$line" == *"users:"* ]]; then
            [[ "$line" == *"pid=$pid,"* ]] && return 0
        fi
    done <<< "$out"
    _e142_pid_owns_socket_port "$proto" "$port" "$pid"
}

# Semantic validation now reuses the complete candidate validator: protocol
# count, UUID/flow, Reality key/SNI/shortId, SS2022 key length and Xray parser.
_e137_validate_semantic_config() {
    local file="$1" semantic="$2" internal
    internal=$(_e137_mode_internal "$semantic") || return 1
    _e118_validate_generated_config "$file" "$internal"
}

# Remove the E141 duplicate host-full reconcile.  The base transaction already
# reconciles and rolls back Core/config/WARP together on failure.
_e135_install_mode() {
    local guard was_active=0 rc=0 rollback_rc=0
    guard=$(_e116_backup_state before_e142_node_install) || return 1
    _e118_save_core_payload "$guard" || return 1
    was_active=$(sed -n 's/^xray_was_active=//p' "$guard/meta.env" 2>/dev/null | tail -n1); was_active=${was_active:-0}
    _e140_install_mode_base "$@" || rc=1
    test "$rc" -ne 0 || _e142_write_version || rc=1
    if test "$rc" -eq 0; then return 0; fi
    error "节点安装事务失败，执行e142外层Core/配置生存回滚。"
    _e118_restore_core_payload "$guard" >/dev/null 2>&1 || rollback_rc=1
    _e118_restore_state "$guard" >/dev/null 2>&1 || rollback_rc=1
    if test "$was_active" = 1; then _e127_verify_xray_runtime "$CONFIG" 12 >/dev/null 2>&1 || rollback_rc=1
    elif systemctl is-active --quiet xray.service 2>/dev/null; then rollback_rc=1; fi
    if test "$rollback_rc" -ne 0; then
        install -d -m 0700 "$E142_DIR" 2>/dev/null || true
        { echo "time=$(date -Is 2>/dev/null || date)"; echo "operation=node-install"; echo "core_backup=$guard"; } \
          > "${E142_CRITICAL_MARKER}.new.$$" 2>/dev/null \
          && chmod 0600 "${E142_CRITICAL_MARKER}.new.$$" 2>/dev/null \
          && mv -f -- "${E142_CRITICAL_MARKER}.new.$$" "$E142_CRITICAL_MARKER" 2>/dev/null || true
        error "严重：旧Xray运行态未能恢复；快照：$guard"
    fi
    return 1
}

# Keep generated metadata and the installed script on one release identifier.
_e118_write_generated_metadata() {
    local internal="${1:-}" semantic="${E137_SEMANTIC_MODE:-}" meta tmp
    test -n "$semantic" || semantic="$internal"
    meta="${E77_NODE_META_FILE:-$CONFIG_DIR/node.meta}"
    # Preserve the complete E124 credential transaction: Reality public-key
    # cache/fingerprint inputs, user SID/SNI/time maps, and all VLESSENC client
    # and server parameter files.  E139/E140 replaced this with node.meta only,
    # which could make a freshly installed node impossible to export.
    _e137_metadata_base "$internal" || return 1
    tmp=$(_e118_mktemp node-meta-e142) || return 1
    {
        echo "version=$E142_VERSION"
        echo "mode=$internal"
        echo "mode_semantic=$semantic"
        echo "mode_internal=$internal"
        awk -F= '$1!="version" && $1!="mode" && $1!="mode_semantic" && $1!="mode_internal"{print}' "$meta"
    } > "$tmp" || return 1
    _e142_atomic_text "$tmp" "$meta" 0600 || return 1
    _e142_write_version
}

#------------------------------------------------------------------------------
# SSH effective-authentication classifier and key-only port guard
#------------------------------------------------------------------------------
_e141_sshd_effective_dump() {
    local user host client_ip client_port local_ip local_port
    command -v sshd >/dev/null 2>&1 || return 1
    user="${SUDO_USER:-${USER:-root}}"
    id "$user" >/dev/null 2>&1 || user=root
    host=$(hostname -f 2>/dev/null || hostname 2>/dev/null || echo localhost)
    if test -n "${SSH_CONNECTION:-}"; then
        read -r client_ip client_port local_ip local_port <<< "$SSH_CONNECTION"
        if [[ "$client_ip" =~ ^[0-9A-Fa-f:.]+$ ]] \
          && [[ "$client_port" =~ ^[0-9]+$ ]] \
          && [[ "$local_ip" =~ ^[0-9A-Fa-f:.]+$ ]] \
          && [[ "$local_port" =~ ^[0-9]+$ ]] \
          && ((client_port >= 1 && client_port <= 65535)) \
          && ((local_port >= 1 && local_port <= 65535)); then
            sshd -T -C "user=$user,host=$host,addr=$client_ip,laddr=$local_ip,lport=$local_port" 2>/dev/null \
              || return 1
            return 0
        fi
    fi
    # Console/cron has no real peer address.  Do not invent 127.0.0.1 because
    # that can accidentally match a Match Address block and misclassify auth.
    sshd -T 2>/dev/null
}

_e142_classify_auth_dump() {
    local dump="$1" user="${2:-root}" password kbd challenge methods pubkey permitroot usepam
    local secret=0 mode=non-password normalized
    password=$(awk '$1=="passwordauthentication"{print tolower($2);exit}' <<< "$dump")
    kbd=$(awk '$1=="kbdinteractiveauthentication"{print tolower($2);exit}' <<< "$dump")
    challenge=$(awk '$1=="challengeresponseauthentication"{print tolower($2);exit}' <<< "$dump")
    methods=$(awk '$1=="authenticationmethods"{$1="";sub(/^ /,"");print tolower($0);exit}' <<< "$dump")
    pubkey=$(awk '$1=="pubkeyauthentication"{print tolower($2);exit}' <<< "$dump")
    permitroot=$(awk '$1=="permitrootlogin"{print tolower($2);exit}' <<< "$dump")
    usepam=$(awk '$1=="usepam"{print tolower($2);exit}' <<< "$dump")
    password=${password:-yes}; kbd=${kbd:-${challenge:-yes}}; challenge=${challenge:-$kbd}
    methods=${methods:-any}; pubkey=${pubkey:-yes}; permitroot=${permitroot:-unknown}; usepam=${usepam:-unknown}

    # OpenSSH applies these PermitRootLogin values to both password and
    # keyboard-interactive authentication for root.
    if test "$user" = root; then
        case "$permitroot" in
          no|prohibit-password|without-password|forced-commands-only)
            password=no; kbd=no; challenge=no
            ;;
        esac
    fi

    if test "$methods" = any; then
        test "$password" = yes && secret=1
        { test "$kbd" = yes || test "$challenge" = yes; } && secret=1
    else
        # AuthenticationMethods is a list of alternatives; comma-separated
        # methods form one required sequence.  A mentioned and enabled secret
        # method is conservatively classified as password-capable.
        normalized=${methods//keyboard-interactive:pam/keyboard-interactive}
        normalized=${normalized//keyboard-interactive:bsdauth/keyboard-interactive}
        [[ " $normalized " == *" password"* || " $normalized " == *",password"* ]] \
          && test "$password" = yes && secret=1
        [[ " $normalized " == *" keyboard-interactive"* || " $normalized " == *",keyboard-interactive"* ]] \
          && { test "$kbd" = yes || test "$challenge" = yes; } && secret=1
    fi
    if test "$secret" -eq 1; then mode="password-capable"
    elif test "$pubkey" = yes; then mode="key-only"
    else mode="non-password"; fi
    printf 'mode=%s\npasswordauthentication=%s\nkbdinteractiveauthentication=%s\nchallengeresponseauthentication=%s\nauthenticationmethods=%s\npubkeyauthentication=%s\npermitrootlogin=%s\nusepam=%s\n' \
      "$mode" "$password" "$kbd" "$challenge" "$methods" "$pubkey" "$permitroot" "$usepam"
}

_e142_sshd_config_files() {
    local f real token pattern hit i=0
    local -a queue=(/etc/ssh/sshd_config)
    local seen=" "
    while test "$i" -lt "${#queue[@]}" && test "$i" -lt 128; do
        f=${queue[$i]}; i=$((i+1))
        test -f "$f" || continue
        real=$(readlink -f -- "$f" 2>/dev/null || true); test -n "$real" || continue
        [[ "$seen" == *" $real "* ]] && continue
        seen+="$real "
        printf '%s\n' "$real"
        while IFS= read -r token; do
            token=${token#\"}; token=${token%\"}; token=${token#\'}; token=${token%\'}
            case "$token" in /*) pattern=$token ;; *) pattern="/etc/ssh/$token" ;; esac
            while IFS= read -r hit; do test -f "$hit" && queue+=("$hit"); done < <(compgen -G "$pattern" 2>/dev/null || true)
        done < <(awk 'tolower($1)=="include"{for(i=2;i<=NF;i++)print $i}' "$real" 2>/dev/null)
    done
}

_e142_match_blocks_may_allow_secret() {
    local f
    local -a files=()
    while IFS= read -r f; do files+=("$f"); done < <(_e142_sshd_config_files)
    test "${#files[@]}" -gt 0 || return 1
    awk '
      BEGIN{inmatch=0; risky=0}
      /^[[:space:]]*#/ || /^[[:space:]]*$/ {next}
      tolower($1)=="match" {inmatch=1; next}
      inmatch && tolower($1)=="passwordauthentication" && tolower($2)=="yes" {risky=1}
      inmatch && (tolower($1)=="kbdinteractiveauthentication" || tolower($1)=="challengeresponseauthentication") && tolower($2)=="yes" {risky=1}
      inmatch && tolower($1)=="authenticationmethods" {
        x=tolower($0); if(x ~ /(^|[ ,])(password|keyboard-interactive)(:[a-z0-9_-]+)?([ ,]|$)/) risky=1
      }
      END{exit !risky}
    ' "${files[@]}" 2>/dev/null
}

_e141_sshd_auth_profile() {
    local dump global_dump user probe_user context=global local_port="" current_profile global_profile
    local current_mode global_mode overall
    dump=$(_e141_sshd_effective_dump) || return 1
    global_dump=$(sshd -T 2>/dev/null) || return 1
    user="${SUDO_USER:-${USER:-root}}"; id "$user" >/dev/null 2>&1 || user=root
    probe_user="$user"
    if test "$probe_user" = root; then id nobody >/dev/null 2>&1 && probe_user=nobody || true; fi
    if test -n "${SSH_CONNECTION:-}"; then
        local _a _b _c _d
        read -r _a _b _c _d <<< "$SSH_CONNECTION"
        if [[ "$_d" =~ ^[0-9]+$ ]]; then context=live-ssh; local_port=$_d; fi
    fi
    current_profile=$(_e142_classify_auth_dump "$dump" "$user") || return 1
    global_profile=$(_e142_classify_auth_dump "$global_dump" "$probe_user") || return 1
    current_mode=$(sed -n 's/^mode=//p' <<< "$current_profile" | head -n1)
    global_mode=$(sed -n 's/^mode=//p' <<< "$global_profile" | head -n1)
    overall="non-password"
    if test "$current_mode" = password-capable || test "$global_mode" = password-capable \
      || _e142_match_blocks_may_allow_secret; then
        overall="password-capable"
    elif test "$current_mode" = key-only || test "$global_mode" = key-only; then
        overall="key-only"
    fi
    printf 'mode=%s\nevaluated_user=%s\ncontext=%s\nlocal_port=%s\nglobal_probe_user=%s\ncurrent_mode=%s\nglobal_mode=%s\n' \
      "$overall" "$user" "$context" "${local_port:-none}" "$probe_user" "$current_mode" "$global_mode"
    sed 's/^/current_/' <<< "$current_profile"
    sed 's/^/global_/' <<< "$global_profile"
}

_e142_write_key_only_guard() {
    local script_tmp service_tmp timer_tmp
    script_tmp=$(_e118_mktemp ssh-key-only-e142.sh) || return 1
    service_tmp=$(_e118_mktemp ssh-key-only-e142.service) || return 1
    timer_tmp=$(_e118_mktemp ssh-key-only-e142.timer) || return 1
    cat > "$script_tmp" <<'EOF_E142_KEY_GUARD'
#!/usr/bin/env bash
set -u
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
readonly STATE="/usr/local/etc/xray/e118_transactional/ssh_ports_e121.env"
readonly CHAIN="XRAY_SSH_E121"
ports=""; mode=unknown; rc=0; order=not-required-key-only

detect_ports() {
    local found="" saved=""
    command -v sshd >/dev/null 2>&1 \
      && found="$found $(sshd -T 2>/dev/null | awk '/^port [0-9]+$/{print $2}')"
    found="$found $(grep -hEi '^[[:space:]]*Port[[:space:]]+[0-9]+' \
      /etc/ssh/sshd_config /etc/ssh/sshd_config.d/*.conf 2>/dev/null | awk '{print $2}')"
    found="$found $(ss -H -ltnp 2>/dev/null | awk '/sshd/ {p=$4;sub(/^.*:/,"",p);if(p~/^[0-9]+$/)print p}')"
    if test -z "${found//[[:space:]]/}" && test -s "$STATE"; then
        saved=$(sed -n 's/^ports=//p' "$STATE" | head -n1 | tr ',' ' '); found="$saved"
    fi
    test -n "${found//[[:space:]]/}" || found=22
    printf '%s\n' $found 2>/dev/null | awk '$1~/^[0-9]+$/&&$1>=1&&$1<=65535{print $1}' | sort -nu
}

write_state() {
    local tmp csv configured listening
    mkdir -p "$(dirname "$STATE")" || return 1
    tmp="${STATE}.tmp.$$"; csv=$(printf '%s\n' $ports | paste -sd, -)
    configured=$(sshd -T 2>/dev/null | awk '/^port [0-9]+$/{print $2}' | sort -nu | paste -sd, -)
    listening=$(ss -H -ltnp 2>/dev/null | awk '/sshd/ {p=$4;sub(/^.*:/,"",p);if(p~/^[0-9]+$/)print p}' | sort -nu | paste -sd, -)
    {
        echo "time=$(date '+%F %T')"; echo "ports=$csv"
        echo "configured_ports=${configured:-none}"; echo "listening_ports=${listening:-none}"
        echo "mode=$mode"; echo "fail2ban_order=$order"; echo "fail2ban_chain=not-required"
        echo "ipv4_fail2ban_order=$order"; echo "ipv4_fail2ban_chain=not-required"
        echo "ipv6_fail2ban_order=$order"; echo "ipv6_fail2ban_chain=not-required"
        echo "fail2ban_ports_synced=not-required"; echo "degraded=0"; echo "auth_mode=key-only"
    } > "$tmp" || return 1
    chmod 0600 "$tmp" || return 1
    mv -f -- "$tmp" "$STATE"
}

apply_family() {
    local tool="$1" new="${CHAIN}_NEW" p f2b="" line insert=1
    while "$tool" -C INPUT -j "$new" >/dev/null 2>&1; do "$tool" -D INPUT -j "$new" >/dev/null 2>&1 || break; done
    "$tool" -F "$new" >/dev/null 2>&1 || true; "$tool" -X "$new" >/dev/null 2>&1 || true
    "$tool" -N "$new" >/dev/null 2>&1 || return 1
    for p in $ports; do "$tool" -A "$new" -p tcp --dport "$p" -j ACCEPT >/dev/null 2>&1 || return 1; done
    "$tool" -A "$new" -j RETURN >/dev/null 2>&1 || return 1
    # Preserve an existing Xray SSH fail2ban jump by inserting immediately
    # after it; otherwise put the anti-lockout chain first.
    f2b=$("$tool" -L INPUT --line-numbers -n 2>/dev/null | awk '$2 ~ /^f2b-/ && $2 ~ /xray-sshd/{n=$1} END{print n}')
    test -z "$f2b" || insert=$((f2b+1))
    "$tool" -I INPUT "$insert" -j "$new" >/dev/null 2>&1 || return 1
    while "$tool" -C INPUT -j "$CHAIN" >/dev/null 2>&1; do "$tool" -D INPUT -j "$CHAIN" >/dev/null 2>&1 || break; done
    "$tool" -F "$CHAIN" >/dev/null 2>&1 || true; "$tool" -X "$CHAIN" >/dev/null 2>&1 || true
    "$tool" -E "$new" "$CHAIN" >/dev/null 2>&1
}

ports=$(detect_ports); test -n "$ports" || ports=22
if command -v ufw >/dev/null 2>&1 && LC_ALL=C ufw status 2>/dev/null | grep -qi '^Status: active'; then
    mode=ufw; for p in $ports; do ufw allow "$p/tcp" >/dev/null 2>&1 || rc=1; done
elif command -v firewall-cmd >/dev/null 2>&1 && systemctl is-active --quiet firewalld.service; then
    mode=firewalld; changed=0
    for p in $ports; do
        firewall-cmd --permanent --query-port="$p/tcp" >/dev/null 2>&1 \
          || { firewall-cmd --permanent --add-port="$p/tcp" >/dev/null 2>&1 && changed=1 || rc=1; }
    done
    test "$changed" -eq 0 || firewall-cmd --reload >/dev/null 2>&1 || rc=1
elif command -v iptables >/dev/null 2>&1; then
    mode=iptables-managed-chain; apply_family iptables || rc=1
    if command -v ip6tables >/dev/null 2>&1 && ip -6 addr show scope global 2>/dev/null | grep -q 'inet6'; then
        apply_family ip6tables || rc=1
    fi
else
    mode=unsupported-firewall; rc=1
fi
write_state || rc=1
exit "$rc"
EOF_E142_KEY_GUARD

    cat > "$service_tmp" <<EOF_E142_KEY_SERVICE
[Unit]
Description=Xray V199e142 key-only SSH port anti-lockout guard
After=network-online.target ssh.service sshd.service ufw.service firewalld.service
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=$E121_SSH_GUARD_SCRIPT
TimeoutStartSec=45

[Install]
WantedBy=multi-user.target
EOF_E142_KEY_SERVICE
    cat > "$timer_tmp" <<'EOF_E142_KEY_TIMER'
[Unit]
Description=Periodic key-only SSH port and firewall self-check

[Timer]
OnBootSec=45s
OnUnitActiveSec=5min
AccuracySec=30s
Persistent=true
Unit=xray-ssh-port-guard-e121.service

[Install]
WantedBy=timers.target
EOF_E142_KEY_TIMER
    bash -n "$script_tmp" || return 1
    _e121_atomic_install "$script_tmp" "$E121_SSH_GUARD_SCRIPT" 0755 || return 1
    _e121_atomic_install "$service_tmp" "$E121_SSH_GUARD_SERVICE" 0644 || return 1
    _e121_atomic_install "$timer_tmp" "$E121_SSH_GUARD_TIMER" 0644 || return 1
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    systemctl enable xray-ssh-port-guard-e121.service xray-ssh-port-guard-e121.timer >/dev/null 2>&1 || return 1
}

_e142_verify_key_only_guard() {
    local detected recorded mode p current_port
    systemctl is-enabled --quiet xray-ssh-port-guard-e121.service 2>/dev/null || return 1
    systemctl is-enabled --quiet xray-ssh-port-guard-e121.timer 2>/dev/null || return 1
    test -s "$E121_SSH_GUARD_STATE" || return 1
    detected=$(_e121_detect_ssh_ports | paste -sd, -)
    recorded=$(sed -n 's/^ports=//p' "$E121_SSH_GUARD_STATE" | head -n1)
    mode=$(sed -n 's/^mode=//p' "$E121_SSH_GUARD_STATE" | head -n1)
    test -n "$detected" && test "$detected" = "$recorded" || return 1
    current_port=$(_e135_current_ssh_port 2>/dev/null || true)
    test -z "$current_port" || tr ',' '\n' <<< "$recorded" | grep -Fxq "$current_port" || return 1
    case "$mode" in
      ufw)
        while IFS= read -r p; do
            LC_ALL=C ufw status 2>/dev/null | awk -v p="$p/tcp" '$1==p{for(i=2;i<=NF;i++)if($i=="ALLOW")ok=1} END{exit !ok}' || return 1
        done < <(_e121_detect_ssh_ports)
        ;;
      firewalld)
        while IFS= read -r p; do firewall-cmd --query-port="$p/tcp" >/dev/null 2>&1 || return 1; done < <(_e121_detect_ssh_ports)
        ;;
      iptables-managed-chain)
        iptables -C INPUT -j "$E121_SSH_GUARD_CHAIN" >/dev/null 2>&1 || return 1
        while IFS= read -r p; do iptables -C "$E121_SSH_GUARD_CHAIN" -p tcp --dport "$p" -j ACCEPT >/dev/null 2>&1 || return 1; done < <(_e121_detect_ssh_ports)
        if command -v ip6tables >/dev/null 2>&1 && ip -6 addr show scope global 2>/dev/null | grep -q 'inet6'; then
            ip6tables -C INPUT -j "$E121_SSH_GUARD_CHAIN" >/dev/null 2>&1 || return 1
            while IFS= read -r p; do ip6tables -C "$E121_SSH_GUARD_CHAIN" -p tcp --dport "$p" -j ACCEPT >/dev/null 2>&1 || return 1; done < <(_e121_detect_ssh_ports)
        fi
        ;;
      *) return 1 ;;
    esac
}

_e141_install_key_only_ssh_guard() {
    local firewall_backup=""
    title "V199e142：Key-only SSH端口自适应防锁"
    command -v sshd >/dev/null 2>&1 || { error "未检测到OpenSSH sshd。"; return 1; }
    sshd -t > "$E118_TMPDIR/sshd-test.log" 2>&1 \
      || { error "sshd -t未通过。"; sed 's/^/    /' "$E118_TMPDIR/sshd-test.log"; return 1; }
    if command -v iptables-save >/dev/null 2>&1; then
        firewall_backup="$E118_BACKUP_DIR/iptables_before_ssh_e142_$(date +%Y%m%d_%H%M%S)_$$.rules"
        iptables-save > "$firewall_backup" 2>/dev/null || firewall_backup=""
    fi
    _e142_write_key_only_guard || return 1
    _e121_apply_ssh_port_guard || { error "Key-only SSH端口守护首次应用失败。"; return 1; }
    _e142_verify_key_only_guard || { error "Key-only SSH端口/开机守护复检失败。"; return 1; }
    info "有效认证为Key-only：不强制安装fail2ban；SSH端口已放行并启用开机/5分钟复检。"
    test -z "$firewall_backup" || info "iptables变更前快照：$firewall_backup"
}

_e142_install_ssh_auth_audit() {
    local service_tmp timer_tmp
    service_tmp=$(_e118_mktemp ssh-auth-audit-e142.service) || return 1
    timer_tmp=$(_e118_mktemp ssh-auth-audit-e142.timer) || return 1
    cat > "$service_tmp" <<'EOF_E142_AUTH_SERVICE'
[Unit]
Description=V199e142 reconcile SSH authentication policy and fail2ban
After=network-online.target ssh.service sshd.service
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/bin/xrv --ssh-auth-reconcile-boot
TimeoutStartSec=600
EOF_E142_AUTH_SERVICE
    cat > "$timer_tmp" <<'EOF_E142_AUTH_TIMER'
[Unit]
Description=Periodic SSH authentication and fail2ban policy reconciliation

[Timer]
OnBootSec=90s
OnUnitActiveSec=15min
AccuracySec=1min
Persistent=true
Unit=xray-ssh-auth-audit-e142.service

[Install]
WantedBy=timers.target
EOF_E142_AUTH_TIMER
    _e121_atomic_install "$service_tmp" "$E142_SSH_AUTH_SERVICE" 0644 || return 1
    _e121_atomic_install "$timer_tmp" "$E142_SSH_AUTH_TIMER" 0644 || return 1
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    systemctl enable --now xray-ssh-auth-audit-e142.timer >/dev/null 2>&1 || return 1
    systemctl is-enabled --quiet xray-ssh-auth-audit-e142.timer 2>/dev/null
}

if declare -F _e141_install_ssh_guard >/dev/null 2>&1; then
    eval "$(declare -f _e141_install_ssh_guard | sed '1s/_e141_install_ssh_guard/_e142_ssh_guard_decision_base/')"
fi
_e141_install_ssh_guard() {
