    _e142_install_ssh_auth_audit || { error "SSH认证模式开机/定时复检安装失败。"; return 1; }
}

_e142_ssh_auth_reconcile_boot() {
    # This runs in a separate audit service, never from the port-guard service,
    # so rewriting/restarting the port guard cannot recursively wait on itself.
    _e141_install_ssh_guard
}

_e142_record_new_package() {
    local pkg="$1" item
    _e135_pkg_present "$pkg" || return 0
    for item in "${E135_NEW_PACKAGES[@]}"; do
        test "$item" = "$pkg" && return 0
    done
    E135_NEW_PACKAGES+=("$pkg")
}

# These packages are installed below the original fail2ban installer wrapper;
# capture them even when the backend/fallback setup later returns an error.
if declare -F _e121_ensure_systemd_backend >/dev/null 2>&1; then
    eval "$(declare -f _e121_ensure_systemd_backend | sed '1s/_e121_ensure_systemd_backend/_e142_systemd_backend_base/')"
fi
_e121_ensure_systemd_backend() {
    local had=0 rc=0
    _e135_pkg_present python3-systemd && had=1 || true
    _e142_systemd_backend_base || rc=$?
    test "$had" -eq 1 || _e142_record_new_package python3-systemd
    return "$rc"
}

if declare -F _e121_prepare_rsyslog_auth_log >/dev/null 2>&1; then
    eval "$(declare -f _e121_prepare_rsyslog_auth_log | sed '1s/_e121_prepare_rsyslog_auth_log/_e142_rsyslog_auth_base/')"
fi
_e121_prepare_rsyslog_auth_log() {
    local had=0 rc=0
    _e135_pkg_present rsyslog && had=1 || true
    _e142_rsyslog_auth_base || rc=$?
    test "$had" -eq 1 || _e142_record_new_package rsyslog
    return "$rc"
}

# Record packages introduced by this transaction so a failed hot update can
# remove them instead of leaving fail2ban/python bindings behind.
if declare -F _e141_install_fail2ban_package >/dev/null 2>&1; then
    eval "$(declare -f _e141_install_fail2ban_package | sed '1s/_e141_install_fail2ban_package/_e142_fail2ban_install_base/')"
fi
_e141_install_fail2ban_package() {
    local had_f2b=0 had_py=0 pkg
    _e135_pkg_present fail2ban && had_f2b=1 || true
    _e135_pkg_present python3-systemd && had_py=1 || true
    _e142_fail2ban_install_base || return 1
    if test "$had_f2b" -eq 0 && _e135_pkg_present fail2ban; then E135_NEW_PACKAGES+=(fail2ban); fi
    if test "$had_py" -eq 0 && _e135_pkg_present python3-systemd; then E135_NEW_PACKAGES+=(python3-systemd); fi
    # De-duplicate because a retry can cross the first successful install.
    if test "${#E135_NEW_PACKAGES[@]}" -gt 0; then
        local -a unique=()
        for pkg in "${E135_NEW_PACKAGES[@]}"; do
            [[ " ${unique[*]} " == *" $pkg "* ]] || unique+=("$pkg")
        done
        E135_NEW_PACKAGES=("${unique[@]}")
    fi
}

# Active speed diagnostics must measure a verified HTTPS path.  The inherited
# e95 helper used curl -k, which could report a successful/fast MITM endpoint.
_e95_http_timing() {
    local url="${1:-https://www.cloudflare.com}"
    command -v curl >/dev/null 2>&1 || { echo "缺少 curl"; return 0; }
    [[ "$url" == https://* ]] || { echo "  拒绝非HTTPS诊断地址：$url"; return 1; }
    curl --proto '=https' --proto-redir '=https' --tlsv1.2 -fsSL -o /dev/null \
        --connect-timeout 4 --max-time 10 \
        -w "  url=%{url_effective}\n  dns=%{time_namelookup}s connect=%{time_connect}s tls=%{time_appconnect}s ttfb=%{time_starttransfer}s total=%{time_total}s speed=%{speed_download}B/s\n" \
        "$url" 2>/dev/null || echo "  curl/TLS失败：$url"
}

# Final cleanup owns only package caches, explicit Xray temp files and managed
# logs.  It never infers ownership from broad /compile or /usr/src name globs.
_e127_clean_space_base() {
    info "执行 V199e142 安全空间清理：包缓存、显式临时文件及3天受管日志。"
    command -v apt-get >/dev/null 2>&1 && apt-get clean >/dev/null 2>&1 || true
    command -v dnf >/dev/null 2>&1 && dnf clean packages >/dev/null 2>&1 || true
    command -v yum >/dev/null 2>&1 && yum clean packages >/dev/null 2>&1 || true
    test -x "$E121_LOG_RETENTION_SCRIPT" || _e121_install_log_retention || return 1
    "$E121_LOG_RETENTION_SCRIPT" || return 1
    test ! -x "$E142_LOG_EXTRA_SCRIPT" || "$E142_LOG_EXTRA_SCRIPT" || return 1
    find /tmp -maxdepth 1 -user root -type f \
      \( -name 'xray.*' -o -name 'xray-*' -o -name 'sni_test.*' \) \
      -mmin +1440 -delete 2>/dev/null || true
    sync 2>/dev/null || true
}

_e142_prune_transactions() {
    local keep="${XRAY_E142_TX_KEEP:-12}" root row real p rc=0
    local protected=" " pending=""
    # A hot update opens several nested E204 transactions.  Never accept a
    # retention count small enough to prune the still-live outer rollback.
    [[ "$keep" =~ ^[0-9]+$ ]] && ((keep >= 12 && keep <= 100)) || keep=12
    for p in "$@"; do
        real=$(readlink -f -- "$p" 2>/dev/null || true)
        test -z "$real" || protected+="$real "
    done
    if test -s "$E140_FULL_PENDING"; then
        pending=$(head -n1 "$E140_FULL_PENDING" 2>/dev/null || true)
        real=$(readlink -f -- "$pending" 2>/dev/null || true)
        test -z "$real" || protected+="$real "
    fi
    if test -s "$E142_CRITICAL_MARKER"; then
        while IFS= read -r p; do
            real=$(readlink -f -- "$p" 2>/dev/null || true)
            test -z "$real" || protected+="$real "
        done < <(sed -nE 's/^(system_backup|transaction|core_backup)=//p' "$E142_CRITICAL_MARKER")
    fi
    for root in "$E142_TX_ROOT" "$E140_TX_ROOT"; do
        test -d "$root" || continue
        root=$(readlink -f -- "$root" 2>/dev/null || true)
        test -n "$root" || { rc=1; continue; }
        while IFS= read -r row; do
            test -n "$row" || continue
            real=$(readlink -f -- "$row" 2>/dev/null || true)
            case "$real" in "$root"/*) ;; *) rc=1; continue ;; esac
            [[ "$protected" == *" $real "* ]] && continue
            rm -rf -- "${real:?}" 2>/dev/null || rc=1
        done < <(find "$root" -mindepth 1 -maxdepth 1 -type d -printf '%T@\t%p\n' 2>/dev/null \
          | sort -nr | awk -F '\t' -v keep="$keep" 'NR>keep{print $2}')
    done
    return "$rc"
}

_e121_check_and_clean_space() {
    _e127_clean_space_base "$@" || return 1
    _e127_prune_core_payload_backups
    _e142_prune_transactions
}

# Remove command-string eval from the still reachable legacy BBR full-kernel
# path.  Only validated make arguments are expanded as an argv array.
_e90_execute_compilation_base() {
    local extra_make_args="${1:-}" make_flags="${2:-}"
    local mem_mb swp_mb total_mb cpu_cores threads compiled_ver arg
    local -a extra_args=()
    info "执行源码内核编译（argv隔离、安装步骤fail-fast）..."
    mem_mb=$(free -m 2>/dev/null | awk '/^Mem:/ {print int($2); exit}' || echo 1024)
    swp_mb=$(free -m 2>/dev/null | awk '/^Swap:/ {print int($2); exit}' || echo 0)
    [[ "$mem_mb" =~ ^[0-9]+$ ]] || mem_mb=1024
    [[ "$swp_mb" =~ ^[0-9]+$ ]] || swp_mb=0
    total_mb=$((mem_mb + swp_mb))
    cpu_cores=$(nproc 2>/dev/null || echo 1)
    [[ "$cpu_cores" =~ ^[1-9][0-9]*$ ]] || cpu_cores=1
    threads=$((total_mb / 1000)); test "$threads" -ge 1 || threads=1
    test "$threads" -le "$cpu_cores" || threads=$cpu_cores
    if test -n "$extra_make_args"; then
        read -r -a extra_args <<< "$extra_make_args"
        for arg in "${extra_args[@]}"; do
            [[ "$arg" =~ ^[A-Za-z0-9_./:+,=@%-]+$ ]] \
              || { error "拒绝不安全的make参数：$arg"; return 1; }
        done
    fi
    if test -n "$make_flags" && gcc -E - -fcf-protection=none </dev/null >/dev/null 2>&1; then
        make_flags="$make_flags -fcf-protection=none"
    fi
    info "安全编译线程：$threads（内存+Swap ${total_mb}MB）"
    if test -n "$make_flags"; then
        make "-j$threads" "KCFLAGS=$make_flags" "${extra_args[@]}" || return 1
    else
        make "-j$threads" "${extra_args[@]}" || return 1
    fi
    make modules_install || return 1
    make install || return 1
    compiled_ver=$(make -s kernelrelease 2>/dev/null || true)
    test -n "$compiled_ver" || { error "无法识别编译后的 kernelrelease。"; return 1; }
    if command -v update-initramfs >/dev/null 2>&1; then
        if test -e "/boot/initrd.img-$compiled_ver"; then
            update-initramfs -u -k "$compiled_ver" || return 1
        else
            update-initramfs -c -k "$compiled_ver" || return 1
        fi
    elif command -v dracut >/dev/null 2>&1; then
        dracut --force "/boot/initramfs-${compiled_ver}.img" "$compiled_ver" || return 1
    else
        error "缺少 update-initramfs/dracut，无法生成 initramfs。"
        return 1
    fi
    _kernel_pre_reboot_verify_e52 "$compiled_ver" || return 1
    info "源码内核安装链路已通过：$compiled_ver。请确认有控制台/VNC后再重启。"
}

_e142_ssh_menu() {
    local n profile
    while true; do
        clear
        title "V199e142：SSH认证模式 / 端口防锁 / Fail2ban"
        echo "  1) 自动识别认证模式并应用最终防护"
        echo "  2) 查看有效认证模式、SSH端口与监听状态"
        echo "  3) 查看防火墙 / Fail2ban运行状态"
        echo "  4) 重新探测端口并同步开机防锁规则"
        echo "  5) 查看Fail2ban安装日志"
        echo "  0) 返回"
        read -rp "操作: " n || true
        case "$n" in
            1|4)
                _e141_install_ssh_guard || true
                _e135_pause
                ;;
            2)
                profile=$(_e141_sshd_auth_profile 2>/dev/null || true)
                printf '%s\n' "${profile:-认证模式探测失败。}"
                echo "合并配置/监听/保存端口："
                _e135_detect_ssh_ports || true
                echo "sshd监听："
                ss -H -lntp 2>/dev/null | awk '/sshd/{print}' || true
                _e135_pause
                ;;
            3)
                _e141_ssh_guard_status || true
                _e135_pause
                ;;
            5)
                test -r "$E141_F2B_INSTALL_LOG" && tail -n 200 "$E141_F2B_INSTALL_LOG" \
                  || warn "暂无安装日志：$E141_F2B_INSTALL_LOG"
                _e135_pause
                ;;
            0) return 0 ;;
            *) warn "无效操作。"; sleep 1 ;;
        esac
    done
}


#------------------------------------------------------------------------------
# V199e142 refinements over V199e141w
# - key-only SSH guard is now a rollback-capable transaction
# - periodic guards are started immediately, not only enabled for next boot
# - an existing managed fail2ban jail preserves and unbans the live SSH IP
# - superseded e141w timers/drop-ins are migrated without duplicate execution
# - rp_filter is snapshotted exactly once by the unified network key owner
#------------------------------------------------------------------------------
readonly E142_LEGACY_AUTH_SERVICE="/etc/systemd/system/xray-ssh-auth-audit-e141w.service"
readonly E142_LEGACY_AUTH_TIMER="/etc/systemd/system/xray-ssh-auth-audit-e141w.timer"
readonly E142_LEGACY_LOG_SCRIPT="/usr/local/bin/xray-log-retention-e141w-extra.sh"
readonly E142_LEGACY_LOG_DROPIN="/etc/systemd/system/xray-log-retention-e121.service.d/99-e141w-nested.conf"
readonly E142_LEGACY_SELF_PATH="$SCRIPT_DIR/ex199e141w.sh"
readonly E142_LEGACY_DIR="$CONFIG_DIR/e141w"

# Ensure the outer hot-update snapshot also knows about the superseded e141w
# files that E142 removes after the new services have passed verification.
if declare -F _e138_system_paths >/dev/null 2>&1; then
    eval "$(declare -f _e138_system_paths | sed '1s/_e138_system_paths/_e142_system_paths_before_migration/')"
fi
_e138_system_paths() {
    _e142_system_paths_before_migration
    cat <<EOF_E142_LEGACY_PATHS
$E142_LEGACY_AUTH_SERVICE
$E142_LEGACY_AUTH_TIMER
$E142_LEGACY_LOG_SCRIPT
$E142_LEGACY_LOG_DROPIN
$E142_LEGACY_SELF_PATH
$E142_LEGACY_DIR
EOF_E142_LEGACY_PATHS
}

# Start the periodic SSH authentication reconciler immediately and remove the
# superseded e141w timer only after the E142 timer is enabled and active.
if declare -F _e142_install_ssh_auth_audit >/dev/null 2>&1; then
    eval "$(declare -f _e142_install_ssh_auth_audit | sed '1s/_e142_install_ssh_auth_audit/_e142_install_ssh_auth_audit_base/')"
fi
_e142_install_ssh_auth_audit() {
    _e142_install_ssh_auth_audit_base || return 1
    systemctl is-enabled --quiet xray-ssh-auth-audit-e142.timer 2>/dev/null || return 1
    systemctl is-active --quiet xray-ssh-auth-audit-e142.timer 2>/dev/null || return 1
    systemctl disable --now xray-ssh-auth-audit-e141w.timer \
      xray-ssh-auth-audit-e141w.service >/dev/null 2>&1 || true
    rm -f -- "$E142_LEGACY_AUTH_SERVICE" "$E142_LEGACY_AUTH_TIMER" 2>/dev/null || true
    systemctl daemon-reload >/dev/null 2>&1 || return 1
}

# Retain one nested-log cleanup hook.  Leaving both e141w and E142 drop-ins in
# place executes two scripts after every retention run and complicates rollback.
if declare -F _e121_install_log_retention >/dev/null 2>&1; then
    eval "$(declare -f _e121_install_log_retention | sed '1s/_e121_install_log_retention/_e142_log_retention_before_migration/')"
fi
_e121_install_log_retention() {
    _e142_log_retention_before_migration || return 1
    rm -f -- "$E142_LEGACY_LOG_SCRIPT" "$E142_LEGACY_LOG_DROPIN" 2>/dev/null || true
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    systemctl restart xray-log-retention-e121.service >/dev/null 2>&1 || return 1
    systemctl is-enabled --quiet xray-log-retention-e121.timer 2>/dev/null || return 1
    systemctl is-active --quiet xray-log-retention-e121.timer 2>/dev/null || return 1
}

# The e141w guard verified only "enabled".  E142 requires the five-minute timer
# to be running in the current boot as well.
if declare -F _e142_verify_key_only_guard >/dev/null 2>&1; then
    eval "$(declare -f _e142_verify_key_only_guard | sed '1s/_e142_verify_key_only_guard/_e142_verify_key_only_guard_base/')"
fi
_e142_verify_key_only_guard() {
    _e142_verify_key_only_guard_base || return 1
    systemctl is-active --quiet xray-ssh-port-guard-e121.timer 2>/dev/null || return 1
}

# Standalone SSH application now has the same snapshot/apply/verify/rollback
# contract as the full hot update.  This covers iptables/ip6tables, UFW,
# firewalld, managed files and service states instead of merely writing an
# iptables-save file that was never restored by the old key-only path.
if declare -F _e141_install_key_only_ssh_guard >/dev/null 2>&1; then
    eval "$(declare -f _e141_install_key_only_ssh_guard | sed '1s/_e141_install_key_only_ssh_guard/_e142_key_only_guard_base/')"
fi
_e141_install_key_only_ssh_guard() {
    local tx ip failed=0 rollback_rc=0
    tx=$(_e142_new_tx ssh-key-only-guard) || return 1
    _e140_system_snapshot "$tx" || return 1
    _e142_key_only_guard_base || failed=1
    if test "$failed" -eq 0; then
        systemctl enable --now xray-ssh-port-guard-e121.service \
          xray-ssh-port-guard-e121.timer >/dev/null 2>&1 || failed=1
    fi
    test "$failed" -ne 0 || _e142_verify_key_only_guard || failed=1

    # A pre-existing script-managed jail may still be active on a key-only
    # machine.  Preserve it, but ensure the live administration IP cannot be
    # banned during the migration or by repeated public-key failures.
    ip=$(_e135_current_ssh_ip 2>/dev/null || true)
    if test "$failed" -eq 0 && command -v fail2ban-client >/dev/null 2>&1 \
      && fail2ban-client status "$E121_F2B_JAIL_NAME" >/dev/null 2>&1; then
        if test -f "$E121_F2B_JAIL"; then
            _e135_patch_fail2ban_ignoreip "$ip" || failed=1
        else
            test -z "$ip" || fail2ban-client set "$E121_F2B_JAIL_NAME" unbanip "$ip" >/dev/null 2>&1 || true
            warn "检测到运行中的受管jail但未找到脚本拥有的配置文件；仅执行当前IP解封，不改写未知配置。"
        fi
    fi

    if test "$failed" -ne 0; then
        error "Key-only SSH防锁事务失败，恢复防火墙、Fail2ban、文件和服务状态。"
        _e140_system_restore "$tx" || rollback_rc=1
        test "$rollback_rc" -eq 0 || error "Key-only SSH防锁回滚未完整通过；恢复材料：$tx"
        return 1
    fi
    info "Key-only SSH防锁已立即生效；开机与5分钟定时复检均处于活动状态。"
    test -z "$ip" || info "当前SSH客户端IP已在现有受管Fail2ban中保留/解封：$ip"
}


# Install only canonical E142 entry points on a clean host.  The old
# ex199e141.sh alias is refreshed only when it already exists, preserving
# compatibility without creating a misleading historical filename.
_e140_install_self() {
    local tx target snap tmp failed=0 legacy_needed=0
    local -a targets=("$SYMLINK" "$E142_SELF_PATH" "$E140_LATEST_PATH") unique=()
    test -r "$SCRIPT_PATH" || return 1
    _e142_prepare || return 1
    test -e "$E140_SELF_PATH" && legacy_needed=1 || true
    test "$legacy_needed" -eq 0 || targets+=("$E140_SELF_PATH")
    for target in "${targets[@]}"; do
        [[ " ${unique[*]} " == *" $target "* ]] || unique+=("$target")
    done
    targets=("${unique[@]}")
    tx=$(_e142_new_tx self-install) || return 1
    for target in "${targets[@]}"; do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
        _e135_snapshot_file "$target" "$snap" || return 1
    done
    for target in "${targets[@]}"; do
        install -d -m 0755 "$(dirname -- "$target")" || { failed=1; break; }
        tmp="${target}.e142-new.$$"
        install -m 0755 "$SCRIPT_PATH" "$tmp" || { rm -f -- "$tmp"; failed=1; break; }
        mv -f -- "$tmp" "$target" || { rm -f -- "$tmp"; failed=1; break; }
        cmp -s "$SCRIPT_PATH" "$target" || { failed=1; break; }
    done
    if test "$failed" -ne 0; then
        for target in "${targets[@]}"; do
            snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
            _e135_restore_file "$target" "$snap" || true
        done
        return 1
    fi
    hash -r 2>/dev/null || true
}
_e139_install_self() { _e140_install_self; }
_e138_install_self() { _e140_install_self; }
_e137_install_self() { _e140_install_self; }
_e136_install_self() { _e140_install_self; }
_e118_install_self() { _e140_install_self; }

# Add behavior checks for the specific defects fixed by E142 while preserving
# the broader V141w release gate.
if declare -F _e142_self_test >/dev/null 2>&1; then
    eval "$(declare -f _e142_self_test | sed '1s/_e142_self_test/_e142_self_test_base/')"
fi
_e142_self_test() {
    local rc=0 body
    _e142_self_test_base || rc=1
    echo "V199e142 refinement gate:"
    body=$(declare -f _e141_install_key_only_ssh_guard)
    [[ "$body" == *'_e140_system_snapshot'* && "$body" == *'_e140_system_restore'* \
      && "$body" == *'enable --now xray-ssh-port-guard-e121.service'* ]] \
      && echo "  [PASS] key-only guard snapshot/apply/rollback and immediate timer" \
      || { echo "  [FAIL] key-only guard transaction"; rc=1; }
    body=$(declare -f _e142_verify_key_only_guard)
    [[ "$body" == *'is-active --quiet xray-ssh-port-guard-e121.timer'* ]] \
      && echo "  [PASS] five-minute SSH guard must be active now" \
      || { echo "  [FAIL] SSH guard active-state verification"; rc=1; }
    body=$(declare -f _e142_install_ssh_auth_audit)
    [[ "$body" == *'xray-ssh-auth-audit-e141w.timer'* \
      && "$body" == *'xray-ssh-auth-audit-e142.timer'* ]] \
      && echo "  [PASS] superseded SSH audit timer migration" \
      || { echo "  [FAIL] SSH audit timer migration"; rc=1; }
    body=$(declare -f _e142_network_apply_base)
    [[ "$body" != *'for key in net.ipv4.conf.all.rp_filter net.ipv4.conf.default.rp_filter'* ]] \
      && echo "  [PASS] rp_filter runtime snapshot has a single owner" \
      || { echo "  [FAIL] duplicate rp_filter runtime snapshot"; rc=1; }
    body=$(declare -f _e138_system_paths)
    [[ "$body" == *'E142_LEGACY_AUTH_TIMER'* && "$body" == *'E142_LEGACY_LOG_DROPIN'* ]] \
      && echo "  [PASS] legacy migration files are rollback-covered" \
      || { echo "  [FAIL] legacy migration snapshot coverage"; rc=1; }
    body=$(declare -f _e140_install_self)
    [[ "$body" == *'targets=("$SYMLINK" "$E142_SELF_PATH" "$E140_LATEST_PATH")'* \
      && "$body" == *'test -e "$E140_SELF_PATH"'* && "$body" == *'_e135_restore_file'* ]] \
      && echo "  [PASS] canonical self-install with conditional legacy alias" \
      || { echo "  [FAIL] self-install target transaction"; rc=1; }
    test "$SCRIPT_VERSION" = 199e142 && test "$E142_VERSION" = 199e142 \
      && echo "  [PASS] E142 release identity convergence" \
      || { echo "  [FAIL] E142 release identity"; rc=1; }
    test "$rc" -eq 0 && echo "V199e142 refinement result: PASS" \
      || echo "V199e142 refinement result: FAIL"
    return "$rc"
}

# Final bindings must be immediately before the one and only active dispatcher;
# later compatibility layers above must not overwrite the e142 entry points.
if declare -F main_menu >/dev/null 2>&1; then
    eval "$(declare -f main_menu | sed '1s/main_menu/_e142_final_main_menu_impl/; s/V199e141/V199e142/g; s/_e135_ssh_menu/_e142_ssh_menu/g')"
fi
main_menu() { _e142_final_main_menu_impl; }
_e140_self_test() { _e142_self_test; }
_e140_help() { _e142_help; }


#==============================================================================
# V199e152 final convergence layer
# - truthful root-only secret export and least-privilege Xray permissions
# - staged/hashed rollback preflight
# - canonical supported sysctl owner with five-minute drift repair
# - host-full WARP committed rollback snapshot
# - login-capable-user SSH classification and password-only Fail2ban filter
# - guarded XanMod package transactions
#==============================================================================
readonly E152_VERSION="199e152"
readonly E152_DIR="$CONFIG_DIR/e152"
readonly E152_TX_ROOT="/var/backups/xray-e152"
readonly E152_SELF_PATH="$SCRIPT_DIR/ex199e152.sh"
readonly E152_NETWORK_CONF="/etc/sysctl.d/99-xray-e152-network.conf"
readonly E152_NETWORK_STATE="$E152_DIR/network.state"
readonly E152_NETWORK_SCRIPT="/usr/local/bin/xray-network-e152.sh"
readonly E152_NETWORK_SERVICE="/etc/systemd/system/xray-network-e152.service"
readonly E152_NETWORK_TIMER="/etc/systemd/system/xray-network-e152.timer"
readonly E152_SSH_AUTH_SERVICE="/etc/systemd/system/xray-ssh-auth-audit-e152.service"
readonly E152_SSH_AUTH_TIMER="/etc/systemd/system/xray-ssh-auth-audit-e152.timer"
readonly E152_F2B_FILTER="/etc/fail2ban/filter.d/xray-sshd-password-e152.conf"
readonly E152_TRANSIENT_IGNORE="$E152_DIR/ssh-transient-ignore.env"
readonly E152_CRITICAL_MARKER="$E152_DIR/CRITICAL_RECOVERY_REQUIRED.env"
readonly E152_LATEST_PATH="$SCRIPT_DIR/ex199e_latest.sh"

_e152_prepare() {
    _e118_runtime_init || return 1
    install -d -m 0700 "$E152_DIR" "$E152_TX_ROOT" || return 1
    install -d -m 0755 "$SCRIPT_DIR" "$LOG_DIR" || return 1
}
_e152_new_tx() {
    local name="${1:-tx}" safe d
    _e152_prepare || return 1
    safe=$(printf '%s' "$name" | tr -c 'A-Za-z0-9_.-' '_')
    test -n "$safe" || safe=tx
    d="$E152_TX_ROOT/${safe}-$(date +%Y%m%d_%H%M%S)-$$-$RANDOM"
    install -d -m 0700 "$d" || return 1
    printf '%s\n' "$d"
}
_e152_tx_ok() {
    local d="$1" real root
    test -d "$d" || return 1
    real=$(readlink -f -- "$d" 2>/dev/null || true)
    root=$(readlink -f -- "$E152_TX_ROOT" 2>/dev/null || true)
    test -n "$real" && test -n "$root" || return 1
    case "$real" in "$root"/*) return 0 ;; *) return 1 ;; esac
}

# Node exports contain UUIDs, Reality private-derived material and SS passwords.
# They are never a non-root read-only operation.
if declare -F do_summary >/dev/null 2>&1; then
    eval "$(declare -f do_summary | sed '1s/do_summary/_e152_summary_base/')"
    eval "$(declare -f _e152_summary_base | sed '1s/_e152_summary_base/_e152_summary_impl/; s/V199e137/V199e152/g; s/V199e142/V199e152/g')"
fi
do_summary() {
    test "$EUID" -eq 0 || { error "节点导出包含认证凭据，仅允许root执行。"; return 1; }
    _e152_summary_impl "$@"
}

# Do not recursively chown the whole configuration tree.  Only the Xray daemon's
# primary config needs daemon readability; user/export/backup secrets remain root-only.
fix_permissions() {
    local service_user service_group f
    service_user=$(systemctl show xray.service -p User --value 2>/dev/null || true)
    service_group=$(systemctl show xray.service -p Group --value 2>/dev/null || true)
    test -n "$service_user" || service_user=root
    if test "$service_user" = root; then
        install -d -o root -g root -m 0700 "$CONFIG_DIR" || return 1
        test ! -f "$CONFIG" || { chown root:root "$CONFIG" && chmod 0600 "$CONFIG"; } || return 1
    elif id "$service_user" >/dev/null 2>&1; then
        test -n "$service_group" || service_group=$(id -gn "$service_user" 2>/dev/null || true)
        getent group "$service_group" >/dev/null 2>&1 || { error "xray.service Group无效：$service_group"; return 1; }
        chown root:"$service_group" "$CONFIG_DIR" || return 1
        chmod 0750 "$CONFIG_DIR" || return 1
        test ! -f "$CONFIG" || { chown root:"$service_group" "$CONFIG" && chmod 0640 "$CONFIG"; } || return 1
    else
        error "xray.service User不存在：$service_user；拒绝以不可验证权限继续。"
        return 1
    fi
    install -d -m 0755 "$DAT_DIR" || return 1
    install -d -m 0700 "$BACKUP_DIR" "$E118_DIR" "$E118_BACKUP_DIR" "$E118_AUDIT_DIR" 2>/dev/null || true
    for f in "$PUBKEY_FILE" "$USER_SNI_MAP" "$USER_TIME_MAP" \
      "${E77_VLESSENC_CLIENT_FILE:-$CONFIG_DIR/vlessenc.client.txt}" \
      "${E77_VLESSENC_SERVER_FILE:-$CONFIG_DIR/vlessenc.server.txt}" \
      "$CONFIG_DIR/node.meta" "$SCRIPT_VERSION_FILE"; do
        test ! -e "$f" || { chown root:root "$f" && chmod 0600 "$f"; } || return 1
    done
}

_e152_write_version() {
    local tmp
    _e152_prepare || return 1
    tmp=$(_e118_mktemp e152-version) || return 1
    printf '%s\n' "$E152_VERSION" > "$tmp" || return 1
    _e118_atomic_install "$tmp" "$SCRIPT_VERSION_FILE" 0600
}
_e142_write_version() { _e152_write_version; }

_e118_write_generated_metadata() {
    local internal="${1:-}" semantic="${E137_SEMANTIC_MODE:-}" meta tmp
    test -n "$semantic" || semantic="$internal"
    meta="${E77_NODE_META_FILE:-$CONFIG_DIR/node.meta}"
    tmp=$(_e118_mktemp node-meta-e152) || return 1
    {
        echo "version=$E152_VERSION"
        echo "mode_semantic=$semantic"
        echo "mode_internal=$internal"
        echo "remark=${REMARK_NAME:-xp-reality}"
        echo "created=${E77_CTIME:-$(date -Is 2>/dev/null || date)}"
        echo "vlessenc_profile=${E79_VLESSENC_PROFILE:-none}"
        echo "vlessenc_network=${E79_VLESSENC_NETWORK:-none}"
        echo "vlessenc_actual_tuning=${E79_VLESSENC_ACTUAL_TUNING:-none}"
    } > "$tmp" || return 1
    _e118_atomic_install "$tmp" "$meta" 0600 || return 1
    _e152_write_version
}

# Canonical self installation.  A historical alias is refreshed only if it
# already exists; clean installations receive no misleading old filename.
_e152_install_self() {
    local tx target snap tmp failed=0 legacy
    local -a targets=("$SYMLINK" "$E152_SELF_PATH" "$E152_LATEST_PATH") unique=()
    test -r "$SCRIPT_PATH" || return 1
    _e152_prepare || return 1
    for legacy in "$E142_SELF_PATH" "$E140_SELF_PATH"; do test -e "$legacy" && targets+=("$legacy") || true; done
    for target in "${targets[@]}"; do [[ " ${unique[*]} " == *" $target "* ]] || unique+=("$target"); done
    targets=("${unique[@]}")
    tx=$(_e152_new_tx self-install) || return 1
    for target in "${targets[@]}"; do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
        _e135_snapshot_file "$target" "$snap" || return 1
    done
    for target in "${targets[@]}"; do
        install -d -m 0755 "$(dirname -- "$target")" || { failed=1; break; }
        tmp="${target}.e152-new.$$"
        install -m 0755 "$SCRIPT_PATH" "$tmp" || { rm -f -- "$tmp"; failed=1; break; }
        mv -f -- "$tmp" "$target" || { rm -f -- "$tmp"; failed=1; break; }
        cmp -s "$SCRIPT_PATH" "$target" || { failed=1; break; }
    done
    if test "$failed" -ne 0; then
        for target in "${targets[@]}"; do
            snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
            _e135_restore_file "$target" "$snap" || true
        done
        return 1
    fi
    hash -r 2>/dev/null || true
}
_e140_install_self() { _e152_install_self; }
_e139_install_self() { _e152_install_self; }
_e138_install_self() { _e152_install_self; }
_e137_install_self() { _e152_install_self; }
_e136_install_self() { _e152_install_self; }
_e118_install_self() { _e152_install_self; }

# Extend rollback coverage with E152-owned files.
if declare -F _e138_system_paths >/dev/null 2>&1; then
    eval "$(declare -f _e138_system_paths | sed '1s/_e138_system_paths/_e152_system_paths_base/')"
fi
_e138_system_paths() {
    _e152_system_paths_base
    cat <<EOF_E152_PATHS
$E152_DIR
$E152_NETWORK_CONF
$E152_NETWORK_SCRIPT
$E152_NETWORK_SERVICE
$E152_NETWORK_TIMER
$E152_SSH_AUTH_SERVICE
$E152_SSH_AUTH_TIMER
$E152_F2B_FILTER
$E152_SELF_PATH
EOF_E152_PATHS
}

# The old snapshot hashed control files but not optional firewall dumps.  Add a
# second seal and pre-extract the archive before any destructive restore.
if declare -F _e140_system_snapshot >/dev/null 2>&1; then
    eval "$(declare -f _e140_system_snapshot | sed '1s/_e140_system_snapshot/_e152_system_snapshot_base/')"
fi
_e140_system_snapshot() {
    local b="$1" f
    _e152_system_snapshot_base "$b" || return 1
    command -v nft >/dev/null 2>&1 && nft list ruleset > "$b/nft.rules.diagnostic" 2>/dev/null || true
    : > "$b/e152-extra.sha256" || return 1
    for f in iptables.rules ip6tables.rules nft.rules.diagnostic e140-services.env e142-prestate.env; do
        test ! -e "$b/$f" || (cd "$b" && sha256sum "$f" >> e152-extra.sha256) || return 1
    done
    test -s "$b/e152-extra.sha256" || printf '%s\n' '# no optional payload' > "$b/e152-extra.sha256"
}
if declare -F _e140_system_restore >/dev/null 2>&1; then
    eval "$(declare -f _e140_system_restore | sed '1s/_e140_system_restore/_e152_system_restore_base/')"
fi
_e152_restore_stage_verify() {
    local b="$1" stage rel
    test ! -s "$b/files.tar" && return 0
    stage=$(mktemp -d "$b/.restore-stage.XXXXXX") || return 1
    if ! tar -C "$stage" -xpf "$b/files.tar"; then rm -rf -- "$stage"; return 1; fi
    while IFS= read -r rel; do
        _e138_safe_restore_rel "$rel" || { rm -rf -- "$stage"; return 1; }
        test -e "$stage/$rel" || test -L "$stage/$rel" || { rm -rf -- "$stage"; return 1; }
    done < "$b/present.list"
    rm -rf -- "$stage"
}
_e140_system_restore() {
    local b="$1"
    test -s "$b/e152-extra.sha256" || { error "E152附加回滚校验缺失：$b"; return 1; }
    grep -qv '^#' "$b/e152-extra.sha256" 2>/dev/null \
      && (cd "$b" && sha256sum -c e152-extra.sha256 >/dev/null 2>&1) \
      || { grep -q '^# no optional payload$' "$b/e152-extra.sha256" || { error "E152附加回滚校验失败：$b"; return 1; }; }
    _e152_restore_stage_verify "$b" || { error "回滚归档无法完整预解包，尚未删除任何在线路径。"; return 1; }
    _e152_system_restore_base "$b"
}

# Build a persistent candidate only from keys actually supported by this kernel.
# IPv6 sysctls are omitted when the IPv6 subsystem is absent; absence itself is
# an acceptable closed state.
_e152_proc_path() { printf '%s/%s\n' "${E152_PROC_ROOT:-/proc/sys}" "${1//./\/}"; }
_e135_network_validate() {
    local file="$1" key value seen="" available p
    test -s "$file" || { error "网络候选文件为空。"; return 1; }
    while IFS='=' read -r key value; do
        key=$(printf '%s' "$key" | xargs); value=$(printf '%s' "$value" | xargs)
        case "$key" in ''|'#'*) continue ;; esac
        _e136_network_keys | grep -Fxq "$key" || { error "非E152白名单参数：$key"; return 1; }
        [[ " $seen " != *" $key "* ]] || { error "候选参数重复：$key"; return 1; }
        seen="$seen $key"
        p=$(_e152_proc_path "$key"); test -e "$p" || { error "候选含当前内核不支持项：$key"; return 1; }
        case "$key" in
          net.ipv4.tcp_notsent_lowat) test "$value" = 131072 || return 1 ;;
          net.ipv4.tcp_congestion_control)
            available=$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null || true)
            [[ " $available " == *" $value "* ]] || return 1 ;;
          net.ipv4.tcp_rmem|net.ipv4.tcp_wmem)
            [[ "$value" =~ ^[0-9]+[[:space:]]+[0-9]+[[:space:]]+[0-9]+$ ]] || return 1 ;;
          *) [[ "$value" =~ ^[A-Za-z0-9._-]+([[:space:]][0-9]+)?$ ]] || return 1 ;;
        esac
    done < "$file"
}
_e152_build_effective_candidate() {
    local profile="${1:-balanced}" out="$2" raw key value p
    raw=$(_e118_mktemp e152-network-raw) || return 1
    _e136_network_candidate "$profile" "$raw" || return 1
    grep -q '^net.ipv4.conf.all.rp_filter' "$raw" || echo 'net.ipv4.conf.all.rp_filter = 2' >> "$raw"
    grep -q '^net.ipv4.conf.default.rp_filter' "$raw" || echo 'net.ipv4.conf.default.rp_filter = 2' >> "$raw"
    printf '# Managed exclusively by ex199e152; profile=%s; generated=%s\n' "$profile" "$(date -Is 2>/dev/null || date)" > "$out" || return 1
    while IFS='=' read -r key value; do
        key=$(printf '%s' "$key" | xargs); value=$(printf '%s' "$value" | xargs)
        case "$key" in ''|'#'*) continue ;; esac
        p=$(_e152_proc_path "$key")
        test -e "$p" || continue
        printf '%s = %s\n' "$key" "$value" >> "$out" || return 1
    done < "$raw"
    for key in net.ipv4.tcp_notsent_lowat net.ipv4.conf.all.rp_filter net.ipv4.conf.default.rp_filter; do
        grep -q "^${key//./\\.}[[:space:]]*=" "$out" || { error "当前内核缺少E152强制参数：$key"; return 1; }
    done
    _e135_network_validate "$out"
}
_e152_ipv6_closed() {
    local root="${E152_PROC_ROOT:-/proc/sys}" f
    test ! -d "$root/net/ipv6" && return 0
    for f in "$root"/net/ipv6/conf/*/disable_ipv6; do
        test -e "$f" || continue
        test "$(cat "$f" 2>/dev/null)" = 1 || return 1
    done
    return 0
}
_e152_network_apply_runtime() {
    local file="$1" key value p f
    while IFS='=' read -r key value; do
        key=$(printf '%s' "$key" | xargs); value=$(printf '%s' "$value" | xargs)
        case "$key" in ''|'#'*) continue ;; esac
        p=$(_e152_proc_path "$key")
        test -w "$p" || return 1
        sysctl -w "$key=$value" >/dev/null 2>&1 || return 1
    done < "$file"
    if test -d "${E152_PROC_ROOT:-/proc/sys}/net/ipv6/conf"; then
        for f in "${E152_PROC_ROOT:-/proc/sys}"/net/ipv6/conf/*/disable_ipv6; do
            test -e "$f" || continue
            printf '1\n' > "$f" || return 1
        done
    fi
    while IFS='=' read -r key value; do
        key=$(printf '%s' "$key" | xargs); value=$(printf '%s' "$value" | xargs)
        case "$key" in ''|'#'*) continue ;; esac
        test "$(sysctl -n "$key" 2>/dev/null | xargs)" = "$value" || return 1
    done < "$file"
    _e152_ipv6_closed
}
_e152_install_network_guard() {
    local script_tmp service_tmp timer_tmp
    script_tmp=$(_e118_mktemp network-e152.sh) || return 1
    service_tmp=$(_e118_mktemp network-e152.service) || return 1
    timer_tmp=$(_e118_mktemp network-e152.timer) || return 1

    cat > "$script_tmp" <<'EOF_E152_NETWORK_SCRIPT'
#!/usr/bin/env bash
set -euo pipefail
CONF=/etc/sysctl.d/99-xray-e152-network.conf
[ -s "$CONF" ] || exit 1
while IFS='=' read -r key value; do
  key=$(printf '%s' "$key" | xargs); value=$(printf '%s' "$value" | xargs)
  case "$key" in ''|'#'*) continue ;; esac
  path="/proc/sys/${key//./\/}"
  [ -w "$path" ] || exit 1
  sysctl -w "$key=$value" >/dev/null
  [ "$(sysctl -n "$key" | xargs)" = "$value" ] || exit 1
done < "$CONF"
if [ -d /proc/sys/net/ipv6/conf ]; then
  for f in /proc/sys/net/ipv6/conf/*/disable_ipv6; do [ ! -e "$f" ] || printf '1\n' > "$f"; done
  for f in /proc/sys/net/ipv6/conf/*/disable_ipv6; do [ ! -e "$f" ] || [ "$(cat "$f")" = 1 ] || exit 1; done
fi
[ "$(sysctl -n net.ipv4.tcp_notsent_lowat)" = 131072 ]
EOF_E152_NETWORK_SCRIPT

    cat > "$service_tmp" <<EOF_E152_NETWORK_SERVICE
[Unit]
Description=V199e152 canonical network parameter apply and drift verification
After=systemd-sysctl.service network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=$E152_NETWORK_SCRIPT
TimeoutStartSec=45
EOF_E152_NETWORK_SERVICE

    cat > "$timer_tmp" <<'EOF_E152_NETWORK_TIMER'
[Unit]
Description=Periodic V199e152 network parameter drift repair

[Timer]
OnBootSec=60s
OnUnitInactiveSec=5min
AccuracySec=30s
Persistent=true
Unit=xray-network-e152.service

[Install]
WantedBy=timers.target
EOF_E152_NETWORK_TIMER

    bash -n "$script_tmp" || return 1
    _e121_atomic_install "$script_tmp" "$E152_NETWORK_SCRIPT" 0755 || return 1
    _e121_atomic_install "$service_tmp" "$E152_NETWORK_SERVICE" 0644 || return 1
    _e121_atomic_install "$timer_tmp" "$E152_NETWORK_TIMER" 0644 || return 1
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    systemctl enable --now xray-network-e152.timer >/dev/null 2>&1 || return 1
    systemctl restart xray-network-e152.service >/dev/null 2>&1 || return 1
    systemctl is-active --quiet xray-network-e152.timer 2>/dev/null || return 1
    systemctl is-enabled --quiet xray-network-e152.timer 2>/dev/null || return 1
}
_e152_network_apply() {
    local profile="${1:-balanced}" confirm="${2:-}" candidate backup key old failed=0 dir_preexisting=0
    _e152_prepare || return 1
    test -d /etc/sysctl.d && dir_preexisting=1 || true
    _e139_ensure_parent "$E152_NETWORK_CONF" || return 1
    candidate=$(_e118_mktemp e152-network.conf) || return 1
    _e152_build_effective_candidate "$profile" "$candidate" || return 1
    if test "$confirm" != force; then
        warn "将迁移/etc中的受管重复定义并写入$E152_NETWORK_CONF；vendor/run定义只审计、不改写。"
        read -rp "输入 APPLY-NETWORK 确认: " confirm || true
        test "$confirm" = APPLY-NETWORK || return 0
    fi
    backup=$(_e152_new_tx network-e152) || return 1
    printf 'dir_preexisting=%s\n' "$dir_preexisting" > "$backup/meta.env" || return 1
    : > "$backup/runtime.env" || return 1
    while IFS= read -r key; do
        old=$(sysctl -n "$key" 2>/dev/null || true)
        printf '%s|%s\n' "$key" "$old" >> "$backup/runtime.env" || return 1
    done < <(_e136_network_keys)
    _e135_snapshot_file "$E152_NETWORK_CONF" "$backup/e152-conf" || return 1
    _e135_snapshot_file "$E139_NETWORK_CONF" "$backup/e139-conf" || return 1
    _e135_snapshot_file "$E138_NETWORK_CONF" "$backup/e138-conf" || return 1
    _e135_snapshot_file "$E136_NETWORK_CONF" "$backup/e136-conf" || return 1
    _e135_snapshot_file "$E135_NETWORK_CONF" "$backup/e135-conf" || return 1
    _e139_network_backup_and_strip "$backup" || failed=1
    test "$failed" -ne 0 || _e142_seal_network_tx "$backup" || failed=1
    test "$failed" -ne 0 || install -m 0644 "$candidate" "$E152_NETWORK_CONF" || failed=1
    test "$failed" -ne 0 || _e152_network_apply_runtime "$E152_NETWORK_CONF" || failed=1
    test "$failed" -ne 0 || _e152_install_network_guard || failed=1
    if test "$failed" -ne 0; then
        error "E152网络参数事务失败，恢复旧文件与运行值。"
        _e139_network_rollback "$backup" "$dir_preexisting" || true
        _e135_restore_file "$E152_NETWORK_CONF" "$backup/e152-conf" || true
        return 1
    fi
    rm -f "$E139_NETWORK_CONF" "$E138_NETWORK_CONF" "$E136_NETWORK_CONF" "$E135_NETWORK_CONF" 2>/dev/null || true
    {
        echo "profile=$profile"; echo "applied=$(date -Is 2>/dev/null || date)"
        echo "tcp_notsent_lowat=131072"; echo "ipv6_closed=1"
        echo "owner=$E152_NETWORK_CONF"; echo "backup=$backup"
    } > "$E152_NETWORK_STATE" || return 1
    chmod 0600 "$E152_NETWORK_STATE" || return 1
    info "E152网络参数已应用：仅持久化当前内核支持项，notsent=131072，IPv6关闭/不可用，5分钟漂移修复已启用。"
}
_e139_network_apply() { command -v modprobe >/dev/null 2>&1 && { modprobe tcp_bbr >/dev/null 2>&1 || true; modprobe sch_fq >/dev/null 2>&1 || true; }; _e152_network_apply "$@"; }
_e139_network_audit() {
    local key root f real tmp
    local -a files=() unique=()
    title "V199e152：全来源sysctl审计（vendor/run只读，/etc由E152管理）"
    for root in /usr/lib/sysctl.d /usr/local/lib/sysctl.d /lib/sysctl.d /run/sysctl.d /etc/sysctl.d; do
        test -d "$root" || continue
        for f in "$root"/*.conf; do
            test -f "$f" || continue
            real=$(readlink -f -- "$f" 2>/dev/null || true); test -n "$real" || continue
            [[ " ${unique[*]} " == *" $real "* ]] || { unique+=("$real"); files+=("$real"); }
        done
    done
    test ! -f /etc/sysctl.conf || files+=(/etc/sysctl.conf)
    tmp=$(_e118_mktemp e152-sysctl-audit) || return 1
    : > "$tmp"
    if test "${#files[@]}" -gt 0; then
        awk '
          /^[[:space:]]*[A-Za-z0-9_.]+[[:space:]]*=/ {
            line=$0; key=$0; sub(/=.*/,"",key); gsub(/[[:space:]]/,"",key);
            print key "\t" FILENAME ":" FNR ":" line
          }
        ' "${files[@]}" > "$tmp" 2>/dev/null || true
    fi
    while IFS= read -r key; do
        printf '\n[%s] runtime=%s\n' "$key" "$(sysctl -n "$key" 2>/dev/null || echo unsupported)"
        awk -F '\t' -v k="$key" '$1==k{print "  "$2; found=1} END{if(!found)print "  未定义"}' "$tmp"
    done < <(_e136_network_keys)
    echo; echo "E152唯一脚本持久化目标：$E152_NETWORK_CONF"
    echo "说明：vendor与/run定义不会被脚本删除；E152通过/etc/99文件和运行态定时器覆盖并验证。"
}

# Login-capable users only.  Do not use 'nobody' as a proxy for a real account.
_e152_login_users() {
    awk -F: '($1=="root" || $3>=1000) && $7 !~ /(nologin|false)$/ {print $1}' /etc/passwd | awk 'NF&&!seen[$0]++'
}
_e141_sshd_auth_profile() {
    local user dump profile mode overall=non-password host addr any=0 match_risk=0
    local profiles="" current_user="${SUDO_USER:-${USER:-root}}" current_dump current_profile current_mode context=global local_port=none
    id "$current_user" >/dev/null 2>&1 || current_user=root
    host=$(hostname -f 2>/dev/null || hostname 2>/dev/null || echo localhost)
    addr=$(awk '{print $1}' <<< "${SSH_CONNECTION:-198.51.100.1}")
    _e136_is_ipv4 "$addr" || addr=198.51.100.1
    if test -n "${SSH_CONNECTION:-}"; then local a b c d; read -r a b c d <<< "$SSH_CONNECTION"; context=live-ssh; local_port=${d:-none}; fi
    current_dump=$(_e141_sshd_effective_dump) || return 1
    current_profile=$(_e142_classify_auth_dump "$current_dump" "$current_user") || return 1
    current_mode=$(sed -n 's/^mode=//p' <<< "$current_profile" | head -n1)
    profiles+="user=$current_user,current=1,$(tr '\n' ',' <<< "$current_profile")\n"
    test "$current_mode" = password-capable && overall=password-capable
    while IFS= read -r user; do
        any=1
        dump=$(sshd -T -C "user=$user,host=$host,addr=$addr" 2>/dev/null) || return 1
        profile=$(_e142_classify_auth_dump "$dump" "$user") || return 1
        mode=$(sed -n 's/^mode=//p' <<< "$profile" | head -n1)
        profiles+="user=$user,current=0,$(tr '\n' ',' <<< "$profile")\n"
        test "$mode" = password-capable && overall=password-capable
    done < <(_e152_login_users)
    _e142_match_blocks_may_allow_secret && match_risk=1 || true
    if test "$overall" != password-capable; then
        if test "$match_risk" = 1; then overall=ambiguous
        elif test "$current_mode" = key-only; then overall=key-only
        else overall=non-password
        fi
    fi
    printf 'mode=%s\nevaluated_user=%s\ncontext=%s\nlocal_port=%s\nlogin_user_count=%s\nmatch_secret_risk=%s\n' \
      "$overall" "$current_user" "$context" "$local_port" "$any" "$match_risk"
    sed 's/^/current_/' <<< "$current_profile"
    printf 'profiles=%b' "$profiles"
}

# Count only password/keyboard-interactive/PAM authentication failures for the
# user's requested 2-in-24h policy; public-key probe noise is not counted.
if declare -F _e121_write_fail2ban_candidates >/dev/null 2>&1; then
    eval "$(declare -f _e121_write_fail2ban_candidates | sed '1s/_e121_write_fail2ban_candidates/_e152_f2b_candidates_base/')"
fi
_e121_write_fail2ban_candidates() {
    local ports csv jail_tmp db_tmp filter_tmp
    ports=$(_e116_detect_ssh_ports); test -n "$ports" || ports=22
    csv=$(printf '%s\n' $ports | paste -sd, -)
    mkdir -p /etc/fail2ban/jail.d /etc/fail2ban/fail2ban.d /etc/fail2ban/filter.d /var/lib/fail2ban || return 1
    jail_tmp=$(_e118_mktemp fail2ban-e152-jail) || return 1
    db_tmp=$(_e118_mktemp fail2ban-e152-db) || return 1
    filter_tmp=$(_e118_mktemp fail2ban-e152-filter) || return 1
    cat > "$filter_tmp" <<'EOF_E152_F2B_FILTER'
[INCLUDES]
before = common.conf

[Definition]
failregex = ^%(__prefix_line)sFailed password for (?:invalid user )?.* from <HOST>(?: port \d+)?(?: ssh\d*)?\s*$
            ^%(__prefix_line)sFailed keyboard-interactive/pam for (?:invalid user )?.* from <HOST>(?: port \d+)?(?: ssh\d*)?\s*$
            ^%(__prefix_line)sPAM: Authentication failure for .* from <HOST>.*$
ignoreregex =
journalmatch = _SYSTEMD_UNIT=sshd.service + _COMM=sshd + _COMM=sshd-session
EOF_E152_F2B_FILTER
    cat > "$db_tmp" <<'EOF_E152_F2B_DB'
[Definition]
allowipv6 = auto
dbfile = /var/lib/fail2ban/fail2ban.sqlite3
dbpurgeage = 3d
logtarget = /var/log/xray-fail2ban.log
loglevel = INFO
EOF_E152_F2B_DB
    {
        echo "[$E121_F2B_JAIL_NAME]"; echo "enabled = true"; echo "filter = xray-sshd-password-e152"
        echo "backend = $E121_F2B_BACKEND"
        test "$E121_F2B_BACKEND" = systemd || echo "logpath = $E121_F2B_LOGPATH"
        echo "port = $csv"
        test -z "$E121_F2B_BANACTION" || echo "banaction = $E121_F2B_BANACTION"
        if test "$E121_F2B_EAGER_ACTION" -eq 1; then
            echo "chain = INPUT"; echo "action = %(action_)s[name=$E121_F2B_JAIL_NAME,actionstart_on_demand=false]"
        fi
        echo "maxretry = 2"; echo "findtime = 86400"; echo "bantime = 129600"
    } > "$jail_tmp" || return 1
    _e121_atomic_install "$filter_tmp" "$E152_F2B_FILTER" 0644 || return 1
    _e121_atomic_install "$db_tmp" "$E121_F2B_DB_CONF" 0644 || return 1
    _e121_atomic_install "$jail_tmp" "$E121_F2B_JAIL" 0644 || return 1
}

# Track only the address injected by E152.  A previous injected address is
# removed only when it was not already user-defined before E152 added it.
_e135_patch_fail2ban_ignoreip() {
    local ip="$1" tmp file_values runtime_values previous previous_pre=1 base merged pre=0 token
    test -f "$E121_F2B_JAIL" || return 1
    previous=$(sed -n 's/^ip=//p' "$E152_TRANSIENT_IGNORE" 2>/dev/null | tail -n1)
    previous_pre=$(sed -n 's/^was_preexisting=//p' "$E152_TRANSIENT_IGNORE" 2>/dev/null | tail -n1); previous_pre=${previous_pre:-1}
    file_values=$(awk -F= '/^[[:space:]]*ignoreip[[:space:]]*=/{sub(/^[^=]*=/,"");print}' "$E121_F2B_JAIL" | _e137_normalize_ignore_tokens | xargs echo)
    runtime_values=$(fail2ban-client get "$E121_F2B_JAIL_NAME" ignoreip 2>/dev/null | _e137_normalize_ignore_tokens | xargs echo || true)
    base=$(printf '%s\n' "$runtime_values $file_values" | tr ' ' '\n' | awk 'NF&&!seen[$0]++')
    if test -n "$previous" && test "$previous_pre" = 0 && test "$previous" != "$ip"; then
        base=$(grep -Fxv "$previous" <<< "$base" || true)
    fi
    grep -Fxq "$ip" <<< "$base" 2>/dev/null && pre=1 || true
    merged=$(printf '%s\n%s\n' "$base" "$ip" | awk 'NF&&!seen[$0]++' | paste -sd' ' -)
    merged=$(_e136_merge_ignoreip_values "$merged" "")
    tmp=$(_e118_mktemp f2b-ignore-e152.conf) || return 1
    awk -v merged="$merged" 'BEGIN{done=0} /^[[:space:]]*ignoreip[[:space:]]*=/{if(!done){print "ignoreip = " merged;done=1};next} {print} END{if(!done)print "ignoreip = " merged}' "$E121_F2B_JAIL" > "$tmp" || return 1
    install -m 0644 "$tmp" "$E121_F2B_JAIL" || return 1
    fail2ban-client -t >/dev/null 2>&1 || return 1
    systemctl restart fail2ban >/dev/null 2>&1 || return 1
    test -z "$ip" || fail2ban-client set "$E121_F2B_JAIL_NAME" unbanip "$ip" >/dev/null 2>&1 || true
    { echo "ip=$ip"; echo "was_preexisting=$pre"; echo "updated=$(date -Is 2>/dev/null || date)"; } > "$E152_TRANSIENT_IGNORE" || return 1
    chmod 0600 "$E152_TRANSIENT_IGNORE" || return 1
}

_e152_install_ssh_auth_audit() {
    cat > "$E152_SSH_AUTH_SERVICE" <<EOF_E152_AUTH_SERVICE
[Unit]
Description=V199e152 reconcile SSH authentication and Fail2ban policy
After=network-online.target ssh.service sshd.service
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/bin/xrv --ssh-auth-reconcile-boot
TimeoutStartSec=600
EOF_E152_AUTH_SERVICE
    cat > "$E152_SSH_AUTH_TIMER" <<'EOF_E152_AUTH_TIMER'
[Unit]
Description=Periodic V199e152 SSH authentication policy reconciliation

[Timer]
OnBootSec=90s
OnUnitActiveSec=15min
AccuracySec=1min
Persistent=true
Unit=xray-ssh-auth-audit-e152.service

[Install]
WantedBy=timers.target
EOF_E152_AUTH_TIMER
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    systemctl enable --now xray-ssh-auth-audit-e152.timer >/dev/null 2>&1 || return 1
    systemctl disable --now xray-ssh-auth-audit-e142.timer xray-ssh-auth-audit-e141w.timer >/dev/null 2>&1 || true
    systemctl is-active --quiet xray-ssh-auth-audit-e152.timer 2>/dev/null
}
_e142_install_ssh_auth_audit() { _e152_install_ssh_auth_audit; }
_e141_install_ssh_guard() {
    local profile mode ip tmp
    _e141_prepare || return 1
    profile=$(_e141_sshd_auth_profile) || { error "无法读取sshd有效认证配置。"; return 1; }
    mode=$(sed -n 's/^mode=//p' <<< "$profile" | head -n1)
    ip=$(_e135_current_ssh_ip 2>/dev/null || true)
    tmp="${E141_SSH_AUTH_STATE}.tmp.$$"
    { printf '%s\n' "$profile"; printf 'current_ssh_ip=%s\nchecked_at=%s\n' "$ip" "$(date -Is 2>/dev/null || date)"; } > "$tmp" || return 1
    install -m 0600 "$tmp" "$E141_SSH_AUTH_STATE" || { rm -f "$tmp"; return 1; }
    rm -f "$tmp"
    case "$mode" in
      key-only|non-password) _e141_install_key_only_ssh_guard || return 1 ;;
      password-capable)
        info "检测到真实可登录账户仍允许密码/交互式认证：必须启用Fail2ban密码失败过滤。"
        _e137_ssh_backend_supported || return 1
        _e137_ssh_guard_base || return 1
        ;;
      ambiguous)
        warn "Match块可能改变认证策略，但未确认真实可登录账户可用密码。先启用Key-only端口防锁。"
        _e141_install_key_only_ssh_guard || return 1
        if command -v fail2ban-client >/dev/null 2>&1; then
            warn "系统已有Fail2ban，将继续验证脚本受管jail；不执行新软件安装。"
            _e137_ssh_backend_supported && _e137_ssh_guard_base || return 1
        else
            warn "Fail2ban未安装；歧义模式不把软件源故障升级为热更新致命错误。"
        fi
        ;;
      *) error "未知SSH认证判定：$mode"; return 1 ;;
    esac
    _e152_install_ssh_auth_audit
}
_e142_ssh_auth_reconcile_boot() { _e141_install_ssh_guard; }

# Persist the successfully confirmed host-full transaction.  The health timer
# can then restore the pre-full-tunnel Xray/WARP state instead of failing open.
if declare -F _e140_warp_full_enable >/dev/null 2>&1; then
    eval "$(declare -f _e140_warp_full_enable | sed '1s/_e140_warp_full_enable/_e152_warp_full_enable_base/')"
    eval "$(declare -f _e152_warp_full_enable_base | sed '1s/_e152_warp_full_enable_base/_e152_warp_full_enable_impl/; s/V199e142/V199e152/g; s/managed_by e142/managed_by e152/g')"
fi
_e140_warp_full_enable() {
    local before after tx rc
    before=$(_e118_mktemp warp-full-before-e152) || return 1
    find "$E142_TX_ROOT" "$E140_TX_ROOT" -mindepth 1 -maxdepth 1 -type d -name 'warp-full-enable-*' -print 2>/dev/null | sort > "$before" || true
    _e152_warp_full_enable_impl "$@" || return $?
    after=$(_e118_mktemp warp-full-after-e152) || return 1
    find "$E142_TX_ROOT" "$E140_TX_ROOT" -mindepth 1 -maxdepth 1 -type d -name 'warp-full-enable-*' -print 2>/dev/null | sort > "$after" || true
    tx=$(comm -13 "$before" "$after" | tail -n1)
    test -n "$tx" || tx=$(find "$E142_TX_ROOT" "$E140_TX_ROOT" -mindepth 1 -maxdepth 1 -type d -name 'warp-full-enable-*' -printf '%T@\t%p\n' 2>/dev/null | sort -nr | awk -F'\t' 'NR==1{print $2}')
    _e142_full_snapshot_verify "$tx" || { error "全隧道已连接但提交快照不可验证，立即回滚。"; _e140_full_rollback_tx "$tx" || true; return 1; }
    _e139_state_set_fields full_commit_tx "$tx" full_committed_at "$(date -Is 2>/dev/null || date)" managed_by e152 || { _e140_full_rollback_tx "$tx" || true; return 1; }
    info "已记录全隧道提交快照：$tx"
}
if declare -F _e142_prune_transactions >/dev/null 2>&1; then
    eval "$(declare -f _e142_prune_transactions | sed '1s/_e142_prune_transactions/_e152_prune_transactions_base/')"
fi
_e142_prune_transactions() {
    local commit
    commit=$(_e138_state_get full_commit_tx "")
    if test -n "$commit"; then _e152_prune_transactions_base "$commit" "$@"; else _e152_prune_transactions_base "$@"; fi
}
_e140_warp_full_health_check() {
    local tx
    _e140_full_mode_active || return 0
    _e140_full_verify && return 0
    E140_ACTIVE_LOG="$E140_FULL_LOG_DIR/health-$(date +%Y%m%d_%H%M%S)-$$.log"
    : > "$E140_ACTIVE_LOG"
    _e140_warp_full_reconcile && _e140_full_verify && return 0
    _e140_capture_diagnostics "$E140_ACTIVE_LOG"
    tx=$(_e138_state_get full_commit_tx "")
    if test -n "$tx" && _e142_full_snapshot_verify "$tx" && _e140_full_rollback_tx "$tx"; then
        error "Cloudflare全隧道健康复检失败，已恢复启用前的Xray/WARP状态。日志：$E140_ACTIVE_LOG"
        return 1
    fi
    _e140_warp_cli disconnect >/dev/null 2>&1 || true
    _e140_full_route_cleanup
    _e139_clear_xray_warp_rules >/dev/null 2>&1 || true
    _e139_state_set_fields route_enabled 0 route_mode disabled profile disabled full_commit_tx '' managed_by e152 >/dev/null 2>&1 || true
    install -d -m 0700 "$E152_DIR" 2>/dev/null || true
    { echo "time=$(date -Is 2>/dev/null || date)"; echo "operation=warp-full-health"; echo "transaction=$tx"; echo "log=$E140_ACTIVE_LOG"; } > "$E152_CRITICAL_MARKER" 2>/dev/null || true
    error "全隧道健康失败且无可验证提交快照；已显式转为disabled并标记人工复核，未保留虚假的host-full状态。"
    return 1
}

# Guard source-build package installation: refuse overwriting an already
# installed same-name kernel package and only remove packages absent preflight.
if declare -F _e135_xanmod_source_build >/dev/null 2>&1; then
    eval "$(declare -f _e135_xanmod_source_build | sed '1s/_e135_xanmod_source_build/_e152_xanmod_source_build_base/')"
fi
_e135_xanmod_source_build() {
    local guard old_dpkg rc had_errexit=0
    [[ $- == *e* ]] && had_errexit=1 || true
    guard=$(_e118_mktemp xanmod-pkg-guard-e152) || return 1
    : > "$guard"
    old_dpkg=$(declare -f dpkg 2>/dev/null || true)
    dpkg() {
        local arg pkg deb
        if test "${1:-}" = -i; then
            shift
            for deb in "$@"; do
                pkg=$(command dpkg-deb -f "$deb" Package 2>/dev/null || return 1)
                if command dpkg-query -W -f='${Status}' "$pkg" 2>/dev/null | grep -q 'install ok installed'; then
                    error "同名内核包已安装，拒绝覆盖并避免失败回滚误删：$pkg"
                    return 1
                fi
                printf '%s\n' "$pkg" >> "$guard"
            done
            command dpkg -i "$@"
        elif test "${1:-}" = -r; then
            shift
            for pkg in "$@"; do
                grep -Fxq "$pkg" "$guard" || { warn "跳过删除非本事务新装包：$pkg"; continue; }
                command dpkg -r "$pkg" || true
            done
        else
            command dpkg "$@"
        fi
    }
    set +e
    _e152_xanmod_source_build_base
    rc=$?
    test "$had_errexit" = 1 && set -e || set +e
    unset -f dpkg
    test -z "$old_dpkg" || eval "$old_dpkg"
    return "$rc"
}

# Official XanMod APT path: exact CPU level only, fail-closed repository setup,
# and rollback only a package that was absent before this transaction.
do_install_xanmod_main_official() {
    local branch level pkg code confirm tx keytmp keygpg kver installed_before=0 rc=0
    title "V199e152：XanMod官方APT包安全事务"
    [[ "$(uname -m)" = x86_64 ]] || { error "仅支持x86_64。"; return 1; }
    echo "  1) Main  2) LTS  3) RT"
    read -rp "选择分支 (默认2=LTS): " branch || true
    case "${branch:-2}" in 1) branch=main;; 2) branch=lts;; 3) branch=rt;; *) return 1;; esac
    level=$(detect_x86_64_level); test "$level" -le 3 || level=3
    pkg=$(_e131_xanmod_pkg_name "$branch" "$level") || { error "CPU x64v$level没有该分支官方包，拒绝向上尝试更高指令集。"; return 1; }
    code=$(_e131_os_codename); test -n "$code" || return 1
    command dpkg-query -W -f='${Status}' "$pkg" 2>/dev/null | grep -q 'install ok installed' && installed_before=1 || true
    test "$installed_before" = 0 || { error "$pkg 已安装；本入口拒绝覆盖同名包。"; return 1; }
    echo "  codename=$code branch=$branch cpu=x64v$level package=$pkg"
    read -rp "输入 INSTALL-XANMOD 确认: " confirm || true
    test "$confirm" = INSTALL-XANMOD || return 0
    tx=$(_e152_new_tx xanmod-apt) || return 1
    _e135_snapshot_file "$E131_XANMOD_KEYRING" "$tx/keyring" || return 1
    _e135_snapshot_file "$E131_XANMOD_LIST" "$tx/list" || return 1
    _e135_snapshot_file /etc/apt/sources.list.d/xanmod-kernel.list "$tx/legacy-list" || return 1
    _e135_snapshot_file /etc/apt/keyrings/xanmod.gpg "$tx/legacy-key" || return 1
    rm -f -- "$E131_XANMOD_LIST" /etc/apt/sources.list.d/xanmod-kernel.list /etc/apt/keyrings/xanmod.gpg 2>/dev/null || true
    export DEBIAN_FRONTEND=noninteractive
    install -d -m 0755 /etc/apt/keyrings || rc=1
    test "$rc" -ne 0 || apt-get update -o Acquire::Retries=3 || rc=1
    test "$rc" -ne 0 || apt-get install -y --no-install-recommends ca-certificates curl gnupg lsb-release || rc=1
    keytmp=$(_e118_mktemp xanmod-archive-e152.key) || rc=1
    keygpg=$(_e118_mktemp xanmod-archive-e152.gpg) || rc=1
    test "$rc" -ne 0 || curl --proto '=https' --tlsv1.2 -fL --connect-timeout 10 --max-time 120 https://dl.xanmod.org/archive.key -o "$keytmp" || rc=1
    test "$rc" -ne 0 || gpg --batch --show-keys "$keytmp" >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || gpg --batch --yes --dearmor -o "$keygpg" "$keytmp" || rc=1
    test "$rc" -ne 0 || install -m 0644 "$keygpg" "$E131_XANMOD_KEYRING" || rc=1
    test "$rc" -ne 0 || printf 'deb [signed-by=%s] http://deb.xanmod.org %s main\n' "$E131_XANMOD_KEYRING" "$code" | _e131_atomic_text_file "$E131_XANMOD_LIST" 0644 || rc=1
    test "$rc" -ne 0 || apt-get update -o Acquire::Retries=3 || rc=1
    test "$rc" -ne 0 || apt-cache show "$pkg" >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || apt-get install -y "$pkg" || rc=1
    if test "$rc" = 0; then
        kver=$(ls -t /boot/vmlinuz-*xanmod* 2>/dev/null | head -n1 | sed 's|.*/vmlinuz-||')
        test -n "$kver" && _kernel_pre_reboot_verify_e52 "$kver" || rc=1
    fi
    test "$rc" -ne 0 || update-grub >/dev/null 2>&1 || rc=1
    if test "$rc" -ne 0; then
        command dpkg-query -W -f='${Status}' "$pkg" 2>/dev/null | grep -q 'install ok installed' && apt-get purge -y "$pkg" >/dev/null 2>&1 || true
        _e135_restore_file "$E131_XANMOD_KEYRING" "$tx/keyring" || true
        _e135_restore_file "$E131_XANMOD_LIST" "$tx/list" || true
        _e135_restore_file /etc/apt/sources.list.d/xanmod-kernel.list "$tx/legacy-list" || true
        _e135_restore_file /etc/apt/keyrings/xanmod.gpg "$tx/legacy-key" || true
        apt-get update >/dev/null 2>&1 || true
        error "XanMod APT事务失败并已尝试恢复仓库及本次新装包。恢复材料：$tx"
        return 1
    fi
    info "XanMod官方包已安装并验证：$kver；未改写GRUB_DEFAULT，未自动重启。"
}

