  --architecture-audit          report inherited layering debt
  --self-test                   non-mutating E152 release gate
EOF_E152_HELP
}

_e152_self_test() {
    local rc=0 tmp body
    echo "V199e152 release gate:"
    bash -n "$SCRIPT_PATH" && echo "  [PASS] bash syntax" || { echo "  [FAIL] bash syntax"; rc=1; }
    test "$SCRIPT_VERSION" = 199e152 && test "$E152_VERSION" = 199e152 \
      && echo "  [PASS] release identity" || { echo "  [FAIL] release identity"; rc=1; }
    grep -m1 '^case "${1:-}" in' -A1 "$SCRIPT_PATH" | grep -q -- '--summary' \
      && { echo "  [FAIL] non-root summary exposure"; rc=1; } \
      || echo "  [PASS] non-root summary rejected at entry gate"
    body=$(declare -f do_summary); [[ "$body" == *'EUID" -eq 0'* ]] \
      && echo "  [PASS] root-only secret export" || { echo "  [FAIL] summary root guard"; rc=1; }
    body=$(declare -f fix_permissions); [[ "$body" == *'chmod 0600 "$CONFIG"'* && "$body" != *'chown -R'* ]] \
      && echo "  [PASS] least-privilege config permissions" || { echo "  [FAIL] config permissions"; rc=1; }
    tmp=$(_e118_mktemp e152-self-network) || return 1
    local fakeproc raw key value path old_proc="${E152_PROC_ROOT:-}" old_sysctl
    fakeproc=$(mktemp -d /tmp/e152-proc.XXXXXX) || return 1
    raw=$(_e118_mktemp e152-self-network-raw) || return 1
    old_sysctl=$(declare -f sysctl 2>/dev/null || true)
    sysctl() {
        if test "${1:-}" = -n && test "${2:-}" = net.ipv4.tcp_available_congestion_control; then echo 'reno cubic bbr'; return 0; fi
        if test "${1:-}" = -n && test "${2:-}" = net.ipv4.tcp_congestion_control; then echo bbr; return 0; fi
        command sysctl "$@"
    }
    _e136_network_candidate balanced "$raw" || rc=1
    grep -q '^net.ipv4.conf.all.rp_filter' "$raw" || echo 'net.ipv4.conf.all.rp_filter = 2' >> "$raw"
    grep -q '^net.ipv4.conf.default.rp_filter' "$raw" || echo 'net.ipv4.conf.default.rp_filter = 2' >> "$raw"
    while IFS='=' read -r key value; do
        key=$(printf '%s' "$key" | xargs); case "$key" in ''|'#'*) continue;; esac
        path="$fakeproc/${key//./\/}"; mkdir -p "$(dirname "$path")"; : > "$path"
    done < "$raw"
    E152_PROC_ROOT="$fakeproc"
    _e152_build_effective_candidate balanced "$tmp" \
      && while IFS='=' read -r key value; do key=$(printf '%s' "$key" | xargs); case "$key" in ''|'#'*) continue;; esac; test -e "$fakeproc/${key//./\/}" || exit 1; done < "$tmp" \
      && echo "  [PASS] unsupported sysctls omitted" || { echo "  [FAIL] effective candidate"; rc=1; }
    if test -n "$old_proc"; then E152_PROC_ROOT="$old_proc"; else unset E152_PROC_ROOT; fi
    unset -f sysctl; test -z "$old_sysctl" || eval "$old_sysctl"
    rm -rf -- "$fakeproc"
    body=$(declare -f _e140_warp_full_health_check); [[ "$body" == *'full_commit_tx'* && "$body" == *'_e140_full_rollback_tx'* ]] \
      && echo "  [PASS] host-full health rollback snapshot" || { echo "  [FAIL] host-full fail-open guard"; rc=1; }
    body=$(declare -f _e142_prune_transactions); [[ "$body" == *'full_commit_tx'* ]] \
      && echo "  [PASS] committed full-tunnel snapshot retention" || { echo "  [FAIL] transaction retention"; rc=1; }
    body=$(declare -f _e140_system_snapshot); [[ "$body" == *'iptables.rules'* && "$body" == *'e152-extra.sha256'* ]] \
      && echo "  [PASS] firewall payload checksum" || { echo "  [FAIL] firewall checksum"; rc=1; }
    body=$(declare -f _e140_system_restore); [[ "$body" == *'_e152_restore_stage_verify'* ]] \
      && echo "  [PASS] staged restore preflight" || { echo "  [FAIL] staged restore"; rc=1; }
    body=$(declare -f _e141_sshd_auth_profile); [[ "$body" == *'_e152_login_users'* && "$body" != *'nobody'* ]] \
      && echo "  [PASS] login-capable SSH user classification" || { echo "  [FAIL] SSH user probe"; rc=1; }
    body=$(declare -f _e121_write_fail2ban_candidates); [[ "$body" == *'xray-sshd-password-e152'* && "$body" == *'maxretry = 2'* ]] \
      && echo "  [PASS] password-only Fail2ban policy" || { echo "  [FAIL] Fail2ban filter"; rc=1; }
    body=$(declare -f _e135_xanmod_source_build); [[ "$body" == *'同名内核包已安装'* ]] \
      && echo "  [PASS] source-kernel package prestate guard" || { echo "  [FAIL] source package guard"; rc=1; }
    test "$(_e137_mode_internal 1)" = 1 && test "$(_e137_mode_internal 2)" = 4 \
      && test "$(_e137_mode_internal 3)" = 2 && test "$(_e137_mode_internal 4)" = 3 \
      && echo "  [PASS] menu 1-4 semantic mapping" || { echo "  [FAIL] menu mapping"; rc=1; }
    body=$(declare -f _e142_write_version); [[ "$body" == *'_e152_write_version'* ]] \
      && echo "  [PASS] node-install version convergence" || { echo "  [FAIL] node version writer"; rc=1; }
    body=$(declare -f _e152_main_menu_impl); [[ "$body" == *'热更新到V199e152'* && "$body" == *'24) Cloudflare系统全隧道'* ]] \
      && echo "  [PASS] visible menu identity and WARP entries" || { echo "  [FAIL] active menu"; rc=1; }
    body=$(declare -f do_uninstall); [[ "$body" == *'E152_F2B_FILTER'* && "$body" == *'E152_SSH_AUTH_TIMER'* ]] \
      && echo "  [PASS] E152 uninstall ownership cleanup" || { echo "  [FAIL] uninstall cleanup"; rc=1; }
    body=$(declare -f _e152_network_apply); [[ "$body" == *'E152_NETWORK_CONF'* && "$body" == *'_e152_install_network_guard'* ]] \
      && echo "  [PASS] canonical network owner and drift timer" || { echo "  [FAIL] network ownership"; rc=1; }
    test "$rc" -eq 0 && echo "V199e152 result: PASS" || echo "V199e152 result: FAIL"
    return "$rc"
}
_e140_self_test() { _e152_self_test; }
_e140_help() { _e152_help; }


