_e159_prepare() {
    _e118_runtime_init || return 1
    install -d -m 0700 "$E159_DIR" "$E159_NETWORK_TX_ROOT" "$E159_TX_ROOT" \
        "$(dirname "$E159_HOT_LOG")" || return 1
    install -d -m 0755 "$SCRIPT_DIR" "$LOG_DIR" || return 1
}

_e159_norm() { printf '%s\n' "${1:-}" | awk '{$1=$1; print}'; }
_e159_proc_path() { printf '%s/%s\n' "${E159_PROC_ROOT:-/proc/sys}" "${1//./\/}"; }

_e159_full_spec() {
    local qdisc="${1:-fq}" new_scale="${2:-1}" new_app="${3:-31}" out="${4:--}"
    [[ "$qdisc" =~ ^(fq|fq_codel|cake)$ ]] || { error "qdisc仅允许 fq/fq_codel/cake。"; return 1; }
    [[ "$new_scale" =~ ^-?[0-9]+$ ]] && (( new_scale >= -31 && new_scale <= 31 )) \
        || { error "tcp_adv_win_scale必须在-31~31。"; return 1; }
    [[ "$new_app" =~ ^[0-9]+$ ]] && (( new_app >= 0 && new_app <= 31 )) \
        || { error "tcp_app_win必须在0~31。"; return 1; }
    {
        echo "# Managed exclusively by ex199e159"
        echo "# Requested entries: 127 = 125 persistent controls + 1 write trigger + 1 semantic alias"
        echo "# qdisc=$qdisc; adv_win_scale=$new_scale; app_win=$new_app"
        echo "# Unsupported/removed kernel keys are retained in the requested specification"
        echo "# and commented in the effective /etc/sysctl.d file instead of being silently lost."
        cat <<EOF_E159_SPEC
net.core.default_qdisc = ${qdisc}
net.ipv4.tcp_congestion_control = bbr
net.ipv4.neigh.default.base_reachable_time_ms = 60000
net.ipv4.neigh.default.mcast_solicit = 2
net.ipv4.neigh.default.retrans_time_ms = 500
net.ipv4.conf.all.rp_filter = 0
net.ipv4.conf.default.rp_filter = 0
net.ipv4.tcp_no_metrics_save = 1
net.ipv4.tcp_ecn = 0
net.ipv4.tcp_ecn_fallback = 1
net.ipv4.tcp_mtu_probing = 1
net.ipv4.tcp_rfc1337 = 1
net.ipv4.tcp_sack = 1
net.ipv4.tcp_window_scaling = 1
net.ipv4.tcp_adv_win_scale = ${new_scale}
net.ipv4.tcp_app_win = ${new_app}
net.ipv4.tcp_moderate_rcvbuf = 1

net.core.rmem_default = 7990577
net.core.wmem_default = 7990577
net.core.rmem_max = 97108868
net.core.wmem_max = 97108868
net.ipv4.tcp_rmem = 4096 7990577 97108868
net.ipv4.tcp_wmem = 4096 7990577 97108868
net.ipv4.udp_rmem_min = 4096
net.ipv4.udp_wmem_min = 4096

net.core.dev_weight = 64
net.core.dev_weight_tx_bias = 1
net.core.dev_weight_rx_bias = 1
net.core.netdev_budget = 300

net.ipv4.igmp_max_memberships = 200
net.ipv4.route.flush = 1
net.ipv4.tcp_slow_start_after_idle = 0

vm.swappiness = 10
fs.file-max = 1048576
fs.nr_open = 1048576
fs.inotify.max_user_instances = 262144

net.ipv4.tcp_syncookies = 1
net.ipv4.tcp_fin_timeout = 12
net.ipv4.tcp_keepalive_probes = 5
net.ipv4.tcp_keepalive_time = 60
net.ipv4.tcp_keepalive_intvl = 30
net.ipv4.tcp_tw_reuse = 1
net.ipv4.tcp_abort_on_overflow = 0
net.ipv4.ip_local_port_range = 1024 65535
net.ipv4.tcp_max_syn_backlog = 65535
net.ipv4.tcp_max_tw_buckets = 262144
net.ipv4.tcp_retries1 = 5
net.ipv4.tcp_retries2 = 8
net.ipv4.tcp_syn_retries = 3
net.ipv4.tcp_synack_retries = 2

net.core.somaxconn = 65535
net.core.netdev_max_backlog = 65535
net.ipv4.tcp_timestamps = 1
net.ipv4.tcp_max_orphans = 262144
net.core.optmem_max = 3276800
net.ipv4.tcp_fastopen = 0
net.ipv4.tcp_reordering = 3
net.ipv4.tcp_autocorking = 0
net.ipv4.tcp_tso_win_divisor = 6

kernel.pid_max = 4194304
# kernel.threads-max = 85536  # 不强行压低发行版默认线程上限
net.ipv4.neigh.default.gc_thresh1 = 1024
net.ipv4.neigh.default.gc_thresh2 = 4096
net.ipv4.neigh.default.gc_thresh3 = 8192
net.ipv4.neigh.default.gc_stale_time = 100
net.ipv4.conf.default.arp_announce = 2
net.ipv4.conf.lo.arp_announce = 2
net.ipv4.conf.all.arp_announce = 2
net.unix.max_dgram_qlen = 130000

net.core.busy_poll = 50
net.core.busy_read = 0
net.ipv4.tcp_notsent_lowat = 16384

vm.vfs_cache_pressure = 50
net.ipv4.conf.all.send_redirects = 0
net.ipv4.conf.all.accept_redirects = 0
net.ipv4.conf.all.accept_source_route = 0
net.ipv4.ip_forward = 0
net.ipv4.conf.all.arp_ignore = 1
net.ipv4.tcp_early_retrans = 3
net.ipv4.neigh.default.unres_qlen = 3000
net.ipv4.conf.all.route_localnet = 0
net.ipv4.tcp_orphan_retries = 8
net.ipv4.conf.all.forwarding = 0

net.ipv4.ipfrag_max_dist = 32
# net.ipv4.ipfrag_secret_interval = 200  # 新内核已移除
net.ipv4.ipfrag_low_thresh = 42008868
net.ipv4.ipfrag_high_thresh = 104917729
net.ipv4.ipfrag_time = 30

fs.aio-max-nr = 262144
kernel.msgmax = 655350
kernel.msgmnb = 655350
net.ipv4.neigh.default.proxy_qlen = 50000
net.ipv4.tcp_pacing_ca_ratio = 150
net.ipv4.tcp_pacing_ss_ratio = 210
fs.protected_fifos = 1
fs.protected_hardlinks = 1
fs.protected_regular = 1
fs.protected_symlinks = 1

net.core.rps_sock_flow_entries = 131072
net.core.flow_limit_table_len = 131072
net.ipv4.tcp_workaround_signed_windows = 1
vm.dirty_ratio = 35
vm.overcommit_memory = 0
kernel.sysrq = 1

# 默认不强制关闭 IPv6；保留双栈与IPv6-only VPS的连通性。
# net.ipv6.conf.all.disable_ipv6 = 1
# net.ipv6.conf.default.disable_ipv6 = 1
# net.ipv6.conf.lo.disable_ipv6 = 1

vm.max_map_count = 262144
net.ipv4.tcp_child_ehash_entries = 65535
net.ipv4.ip_no_pmtu_disc = 0
net.ipv4.tcp_stdurg = 0
net.ipv4.tcp_challenge_ack_limit = 1000
net.ipv4.tcp_comp_sack_delay_ns = 50000
net.ipv4.tcp_comp_sack_nr = 1
net.ipv4.tcp_fwmark_accept = 1
net.ipv4.tcp_invalid_ratelimit = 800
net.ipv4.tcp_l3mdev_accept = 1

net.core.tstamp_allow_data = 1
net.core.netdev_tstamp_prequeue = 1
kernel.randomize_va_space = 2

# net.ipv4.tcp_mem = 65536 131072 262144
# net.ipv4.udp_mem = 65536 131072 262144
net.ipv4.tcp_recovery = 0x1
net.ipv4.tcp_dsack = 1

# kernel.shmmax = 67108864  # 不强行压低共享内存上限
# kernel.shmall = 16777216

net.ipv4.icmp_echo_ignore_broadcasts = 1
net.ipv4.icmp_ignore_bogus_error_responses = 1
net.ipv4.tcp_limit_output_bytes = 1310720
net.ipv4.tcp_min_tso_segs = 1
net.ipv4.tcp_thin_linear_timeouts = 0
net.ipv4.tcp_early_demux = 1
net.ipv4.tcp_shrink_window = 0
net.ipv4.neigh.default.unres_qlen_bytes = 65535
kernel.printk = 3 4 1 3
kernel.sched_autogroup_enabled = 0
EOF_E159_SPEC
    } >"$out"
}

_e159_active_keys() {
    local file="$1"
    # Linux sysctl names also contain hyphens (notably fs.file-max and
    # fs.aio-max-nr).  E156 omitted both from counts and rollback snapshots.
    awk -F= '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{
      k=$1; gsub(/[[:space:]]/,"",k); print k
    }' "$file"
}

_e159_spec_validate() {
    local file="$1" count dup
    test -s "$file" || { error "E159请求规格为空。"; return 1; }
    count=$(_e159_active_keys "$file" | wc -l | tr -d ' ')
    test "$count" -eq 127 || { error "E159原始规格应为127条（125控制+1触发器+1别名），实际$count。"; return 1; }
    dup=$(_e159_active_keys "$file" | sort | uniq -d | head -n1)
    test -z "$dup" || { error "E159规格重复参数：$dup"; return 1; }
    grep -qx 'net.ipv4.tcp_congestion_control = bbr' "$file" || return 1
    grep -qx 'net.core.rmem_default = 7990577' "$file" || return 1
    grep -qx 'net.core.rmem_max = 97108868' "$file" || return 1
    grep -qx 'net.ipv4.tcp_notsent_lowat = 16384' "$file" || return 1
    grep -qx 'net.core.busy_poll = 50' "$file" || return 1
    grep -qx 'net.ipv4.tcp_fastopen = 0' "$file" || return 1
    grep -qx 'net.ipv4.tcp_ecn = 0' "$file" || return 1
    ! grep -Eq '^[[:space:]]*net\.ipv6\.conf\..*\.disable_ipv6[[:space:]]*=' "$file"
}

_e159_kernel_prepare() {
    local qdisc="${1:-fq}" available
    modprobe tcp_bbr >/dev/null 2>&1 || true
    available=$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null || true)
    [[ " $available " == *" bbr "* ]] || {
        error "当前内核没有注册BBR；E159不会用Cubic冒充你要求的BBR。可用：${available:-none}"
        return 1
    }
    modprobe "sch_${qdisc}" >/dev/null 2>&1 || true
    test -w "$(_e159_proc_path net.core.default_qdisc)" || {
        error "当前环境不可写net.core.default_qdisc。"
        return 1
    }
}

_e159_critical_key() {
    case "$1" in
        net.core.default_qdisc|net.ipv4.tcp_congestion_control|net.ipv4.tcp_mtu_probing|\
        net.ipv4.tcp_slow_start_after_idle|net.core.rmem_default|net.core.wmem_default|\
        net.core.rmem_max|net.core.wmem_max|net.ipv4.tcp_rmem|net.ipv4.tcp_wmem|\
        net.ipv4.tcp_notsent_lowat|net.ipv4.tcp_limit_output_bytes|\
        net.ipv4.conf.all.rp_filter|net.ipv4.conf.default.rp_filter|\
        net.ipv4.ip_forward|net.ipv4.conf.all.forwarding) return 0 ;;
        *) return 1 ;;
    esac
}

_e159_key_note() {
    case "$1" in
        net.ipv4.ipfrag_low_thresh) echo 'obsolete-since-linux-4.17' ;;
        net.ipv4.tcp_adv_win_scale) echo 'obsolete-noop-since-linux-6.6' ;;
        net.ipv4.tcp_child_ehash_entries) echo 'kernel-rounds-nonzero-value-up-to-power-of-two' ;;
        net.ipv4.route.flush) echo 'write-only-trigger' ;;
        net.ipv4.neigh.default.unres_qlen) echo 'deprecated-packet-view-shared-with-unres_qlen_bytes' ;;
        net.ipv4.neigh.default.unres_qlen_bytes) echo 'authoritative-unresolved-neighbour-queue-byte-limit' ;;
        net.core.busy_poll) echo 'cpu-cost-and-application-dependent' ;;
        net.ipv4.tcp_notsent_lowat) echo 'aggressive-low-latency-16KiB' ;;
        net.ipv4.ip_forward|net.ipv4.conf.all.forwarding) echo 'breaks-router-container-host-full-warp' ;;
        net.ipv4.tcp_retries2|net.ipv4.tcp_syn_retries|net.ipv4.tcp_synack_retries) echo 'aggressive-failure-timeout' ;;
        net.core.rmem_default|net.core.wmem_default|net.ipv4.tcp_rmem|net.ipv4.tcp_wmem) echo 'large-per-socket-default-memory' ;;
        kernel.sysrq) echo 'security-sensitive-sysrq-enabled' ;;
        *) echo 'requested' ;;
    esac
}

_e159_build_effective() {
    local requested="$1" effective="$2" report="$3" line key value path note ipf
    local alias_bytes="" alias_bytes_path="" supported=0 unsupported=0 shadowed=0 critical_missing=0
    : >"$effective" || return 1
    : >"$report" || return 1
    printf '# Generated from the ex199e127 block: 127 requests / 125 persistent controls by ex199e159\n' >>"$effective"
    printf '# ip_forward is deliberately emitted first: changing it resets several IPv4 defaults.\n' >>"$effective"
    printf 'key\tstatus\trequested\tnote\n' >>"$report"

    alias_bytes=$(awk -F= '$1 ~ /^[[:space:]]*net\.ipv4\.neigh\.default\.unres_qlen_bytes[[:space:]]*$/{print $2;exit}' "$requested" | xargs)
    alias_bytes_path=$(_e159_proc_path net.ipv4.neigh.default.unres_qlen_bytes)

    # Linux documents net.ipv4.ip_forward as a special switch that resets
    # IPv4 parameters to host/router defaults.  Keep the requested file in its
    # original order, but place this one key first in the effective file so no
    # already-applied E159 value is silently reset during systemd-sysctl boot.
    ipf=$(awk -F= '$1 ~ /^[[:space:]]*net\.ipv4\.ip_forward[[:space:]]*$/{print $2;exit}' "$requested" | xargs)
    if test -n "$ipf"; then
        key=net.ipv4.ip_forward
        path=$(_e159_proc_path "$key")
        note=$(_e159_key_note "$key")
        if test -e "$path" && test -w "$path"; then
            printf '%s = %s\n' "$key" "$ipf" >>"$effective" || return 1
            printf '%s\tsupported\t%s\t%s\n' "$key" "$ipf" "$note" >>"$report" || return 1
            supported=$((supported+1))
        else
            printf '# unsupported on %s: %s = %s\n' "$(uname -r)" "$key" "$ipf" >>"$effective" || return 1
            printf '%s\tunsupported\t%s\t%s\n' "$key" "$ipf" "$note" >>"$report" || return 1
            unsupported=$((unsupported+1))
            _e159_critical_key "$key" && critical_missing=$((critical_missing+1)) || true
        fi
    fi

    while IFS= read -r line || test -n "$line"; do
        case "$line" in
            ''|'#'*) printf '%s\n' "$line" >>"$effective"; continue ;;
        esac
        [[ "$line" == *=* ]] || { error "E159规格语法错误：$line"; return 1; }
        key=$(_e159_norm "${line%%=*}")
        value=$(_e159_norm "${line#*=}")
        if test "$key" = net.ipv4.ip_forward; then
            printf '# net.ipv4.ip_forward is applied first above (%s).\n' "$value" >>"$effective"
            continue
        fi
        path=$(_e159_proc_path "$key")
        note=$(_e159_key_note "$key")
        # Since Linux 3.3, unres_qlen is only a deprecated packet-count view
        # over the exact same QUEUE_LEN_BYTES storage used by
        # unres_qlen_bytes.  Keeping both active is internally contradictory:
        # the later 65535-byte write necessarily reads back as roughly 31
        # Ethernet SKBs, not 3000.  Retain all 127 requested source entries, but
        # give the modern byte limit authority in the effective file.
        if test "$key" = net.ipv4.neigh.default.unres_qlen \
            && test -n "$alias_bytes" \
            && test -e "$path" && test -w "$path" \
            && test -e "$alias_bytes_path" && test -w "$alias_bytes_path"; then
            printf '# semantic alias shadowed by unres_qlen_bytes=%s: %s = %s\n' \
                "$alias_bytes" "$key" "$value" >>"$effective" || return 1
            printf '%s\tshadowed-alias\t%s\t%s; authoritative-bytes=%s\n' \
                "$key" "$value" "$note" "$alias_bytes" >>"$report" || return 1
            shadowed=$((shadowed+1))
            continue
        fi
        if test -e "$path" && test -w "$path"; then
            printf '%s = %s\n' "$key" "$value" >>"$effective" || return 1
            printf '%s\tsupported\t%s\t%s\n' "$key" "$value" "$note" >>"$report" || return 1
            supported=$((supported+1))
        else
            printf '# unsupported on %s: %s = %s\n' "$(uname -r)" "$key" "$value" >>"$effective" || return 1
            printf '%s\tunsupported\t%s\t%s\n' "$key" "$value" "$note" >>"$report" || return 1
            unsupported=$((unsupported+1))
            _e159_critical_key "$key" && critical_missing=$((critical_missing+1)) || true
        fi
    done <"$requested"
    printf '# supported=%s unsupported=%s shadowed_alias=%s\n' \
        "$supported" "$unsupported" "$shadowed" >>"$effective"
    if test "$critical_missing" -ne 0; then
        error "当前内核缺少$critical_missing个E159关键参数，拒绝伪成功。"
        while IFS=$'\t' read -r key note value _; do
            test "$note" = unsupported || continue
            _e159_critical_key "$key" && printf '    %s = %s\n' "$key" "$value" >&2 || true
        done <"$report"
        return 1
    fi
    test "$supported" -gt 0
}

# Validate the three generated artifacts as one closed set.  E156 counted the
# report after installation and its key parser omitted the legal hyphenated
# names fs.file-max/fs.aio-max-nr.  The source actually contains 127 requests:
# 125 persistent controls, one write trigger, and one semantic alias.  This
# gate is used before/after install and again by hot-update verification.
_e159_network_artifacts_validate() (
    local requested="$1" effective="$2" report="$3"
    local work
    local req_keys rep_keys sup_keys eff_keys req_values rep_values eff_values sup_values
    local requested_count requested_unique report_count report_unique
    local supported unsupported shadowed status_total effective_count effective_unique bad
    test -s "$requested" && test -s "$effective" && test -s "$report" || {
        error "E159网络产物缺失或为空。"; return 1;
    }
    work=$(mktemp -d /tmp/e159-artifacts.XXXXXX) || return 1
    trap 'rm -rf -- "$work"' EXIT
    req_keys="$work/requested.keys"; rep_keys="$work/report.keys"
    sup_keys="$work/supported.keys"; eff_keys="$work/effective.keys"
    req_values="$work/requested.values"; rep_values="$work/report.values"
    eff_values="$work/effective.values"; sup_values="$work/supported.values"

    _e159_active_keys "$requested" | sort >"$req_keys" || return 1
    _e159_active_keys "$effective" | sort >"$eff_keys" || return 1
    awk -F'\t' 'NR>1 && NF{print $1}' "$report" | sort >"$rep_keys" || return 1
    awk -F'\t' 'NR>1 && $2=="supported"{print $1}' "$report" | sort >"$sup_keys" || return 1

    requested_count=$(wc -l <"$req_keys" | tr -d ' ')
    requested_unique=$(uniq "$req_keys" | wc -l | tr -d ' ')
    report_count=$(wc -l <"$rep_keys" | tr -d ' ')
    report_unique=$(uniq "$rep_keys" | wc -l | tr -d ' ')
    effective_count=$(wc -l <"$eff_keys" | tr -d ' ')
    effective_unique=$(uniq "$eff_keys" | wc -l | tr -d ' ')
    supported=$(awk -F'\t' 'NR>1 && $2=="supported"{n++}END{print n+0}' "$report")
    unsupported=$(awk -F'\t' 'NR>1 && $2=="unsupported"{n++}END{print n+0}' "$report")
    shadowed=$(awk -F'\t' 'NR>1 && $2=="shadowed-alias"{n++}END{print n+0}' "$report")
    status_total=$((supported+unsupported+shadowed))

    test "$(head -n1 "$report")" = $'key\tstatus\trequested\tnote' || {
        error "E159兼容报告表头损坏。"; return 1;
    }
    bad=$(awk -F'\t' 'NR>1 && NF && (NF<4 || $1 !~ /^[A-Za-z0-9_.-]+$/ || $2 !~ /^(supported|unsupported|shadowed-alias)$/){print NR;exit}' "$report")
    test -z "$bad" || { error "E159兼容报告第${bad}行结构/状态非法。"; return 1; }
    test "$requested_count" -eq 127 && test "$requested_unique" -eq 127 || {
        error "E159请求集合不变量失败：rows=$requested_count unique=$requested_unique（必须均为127）。"; return 1;
    }
    test "$report_count" -eq 127 && test "$report_unique" -eq 127 \
      && test "$status_total" -eq 127 || {
        error "E159报告集合不变量失败：rows=$report_count unique=$report_unique status_total=$status_total。"; return 1;
    }
    if ! cmp -s "$req_keys" "$rep_keys"; then
        error "E159兼容报告与请求规格的键集合不一致。"
        comm -3 "$req_keys" "$rep_keys" | head -n 20 | sed 's/^/    /' >&2 || true
        return 1
    fi
    test "$effective_count" -eq "$effective_unique" \
      && test "$effective_count" -eq "$supported" || {
        error "E159有效集合不变量失败：active=$effective_count unique=$effective_unique supported=$supported。"; return 1;
    }
    if ! cmp -s "$eff_keys" "$sup_keys"; then
        error "E159有效配置并非兼容报告中supported集合的精确映射。"
        comm -3 "$eff_keys" "$sup_keys" | head -n 20 | sed 's/^/    /' >&2 || true
        return 1
    fi

    awk -F= '
      /^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/ {
        k=$1; gsub(/[[:space:]]/,"",k); v=substr($0,index($0,"=")+1)
        gsub(/^[[:space:]]+|[[:space:]]+$/,"",v); gsub(/[[:space:]]+/," ",v)
        print k "\t" v
      }' "$requested" | sort >"$req_values" || return 1
    awk -F'\t' 'NR>1 && NF{v=$3;gsub(/^[[:space:]]+|[[:space:]]+$/,"",v);gsub(/[[:space:]]+/," ",v);print $1 "\t" v}' \
        "$report" | sort >"$rep_values" || return 1
    cmp -s "$req_values" "$rep_values" || {
        error "E159兼容报告中的请求值与127条原始规格不一致。"; return 1;
    }
    awk -F= '
      /^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/ {
        k=$1; gsub(/[[:space:]]/,"",k); v=substr($0,index($0,"=")+1)
        gsub(/^[[:space:]]+|[[:space:]]+$/,"",v); gsub(/[[:space:]]+/," ",v)
        print k "\t" v
      }' "$effective" | sort >"$eff_values" || return 1
    awk -F'\t' 'NR>1 && $2=="supported"{v=$3;gsub(/^[[:space:]]+|[[:space:]]+$/,"",v);gsub(/[[:space:]]+/," ",v);print $1 "\t" v}' \
        "$report" | sort >"$sup_values" || return 1
    cmp -s "$eff_values" "$sup_values" || {
        error "E159有效配置的键值与supported报告不一致。"; return 1;
    }
    (( shadowed <= 1 )) || { error "E159共享别名数量异常：$shadowed。"; return 1; }
    if test "$shadowed" -eq 1; then
        grep -q $'^net.ipv4.neigh.default.unres_qlen\tshadowed-alias\t' "$report" \
          && grep -q $'^net.ipv4.neigh.default.unres_qlen_bytes\tsupported\t' "$report" \
          && ! grep -q '^net.ipv4.neigh.default.unres_qlen$' "$eff_keys" || {
            error "E159邻居队列共享别名关系不完整。"; return 1;
        }
    fi
    ! grep -Eq '^[[:space:]]*net\.ipv6\.conf\..*\.disable_ipv6[[:space:]]*=' "$effective" || {
        error "E159有效配置意外接管了IPv6 disable策略。"; return 1;
    }
    return 0
)

_e159_network_state_validate() {
    local state="${1:-$E159_NETWORK_STATE}" requested logical effective_active effective_persistent
    local supported unsupported shadowed trigger backup origin actual
    local report_supported report_unsupported report_shadowed report_trigger
    test -s "$state" || return 1
    test "$(sed -n 's/^version=//p' "$state" | tail -n1)" = 199e159 || return 1
    requested=$(sed -n 's/^requested_entries=//p' "$state" | tail -n1)
    logical=$(sed -n 's/^logical_controls=//p' "$state" | tail -n1)
    effective_active=$(sed -n 's/^effective_active=//p' "$state" | tail -n1)
    effective_persistent=$(sed -n 's/^effective_persistent=//p' "$state" | tail -n1)
    supported=$(sed -n 's/^supported=//p' "$state" | tail -n1)
    unsupported=$(sed -n 's/^unsupported=//p' "$state" | tail -n1)
    shadowed=$(sed -n 's/^shadowed_alias=//p' "$state" | tail -n1)
    trigger=$(sed -n 's/^write_trigger=//p' "$state" | tail -n1)
    for actual in "$requested" "$logical" "$effective_active" "$effective_persistent" \
        "$supported" "$unsupported" "$shadowed" "$trigger"; do
        [[ "$actual" =~ ^[0-9]+$ ]] || return 1
    done
    test "$requested" -eq 127 && test "$logical" -eq 125 \
      && test "$effective_active" -eq "$supported" \
      && test "$effective_persistent" -eq $((supported-trigger)) \
      && test $((supported+unsupported+shadowed)) -eq 127 \
      && (( trigger <= 1 && shadowed <= 1 )) || return 1
    actual=$(_e159_active_keys "$E159_EFFECTIVE_CONF" | wc -l | tr -d ' ')
    test "$actual" -eq "$effective_active" || return 1
    report_supported=$(awk -F'\t' 'NR>1&&$2=="supported"{n++}END{print n+0}' "$E159_NETWORK_REPORT")
    report_unsupported=$(awk -F'\t' 'NR>1&&$2=="unsupported"{n++}END{print n+0}' "$E159_NETWORK_REPORT")
    report_shadowed=$(awk -F'\t' 'NR>1&&$2=="shadowed-alias"{n++}END{print n+0}' "$E159_NETWORK_REPORT")
    report_trigger=$(awk -F'\t' 'NR>1&&$1=="net.ipv4.route.flush"&&$2=="supported"{n++}END{print n+0}' "$E159_NETWORK_REPORT")
    test "$report_supported" -eq "$supported" \
      && test "$report_unsupported" -eq "$unsupported" \
      && test "$report_shadowed" -eq "$shadowed" \
      && test "$report_trigger" -eq "$trigger" || return 1
    backup=$(sed -n 's/^backup=//p' "$state" | tail -n1)
    origin=$(sed -n 's/^origin_backup=//p' "$state" | tail -n1)
    _e159_network_tx_verify "$backup" && _e159_network_tx_verify "$origin"
}

_e159_value_equal() {
    local key="$1" expected actual
    expected=$(_e159_norm "$2")
    actual=$(_e159_norm "$3")
    case "$key" in
        net.ipv4.tcp_recovery) (( expected == actual )) 2>/dev/null ;;
        net.ipv4.tcp_child_ehash_entries)
            test "$expected" = "$actual" \
                || { test "$expected" = 65535 && test "$actual" = 65536; } ;;
        *) test "$expected" = "$actual" ;;
    esac
}

# Linux exposes unres_qlen and unres_qlen_bytes as two unit views of one
# NEIGH_VAR_QUEUE_LEN_BYTES value.  The packet view is intentionally not
# compared with its contradictory requested value; correctness is established
# by a numeric packet view plus an exact readback of the authoritative bytes.
_e159_unres_alias_equal() {
    local requested="$1" actual_packets="$2" actual_bytes="$3" expected_bytes
    [[ "$actual_packets" =~ ^[0-9]+$ ]] || return 1
    expected_bytes=$(awk -F= '$1 ~ /^[[:space:]]*net\.ipv4\.neigh\.default\.unres_qlen_bytes[[:space:]]*$/{print $2;exit}' \
        "$requested" 2>/dev/null | xargs)
    test -n "$expected_bytes" || return 1
    _e159_value_equal net.ipv4.neigh.default.unres_qlen_bytes "$expected_bytes" "$actual_bytes"
}

_e159_forwarding_conflict() {
    local enabled=0 mode=disabled svc current_forward=0 all_forward=0
    if declare -F _e138_state_get >/dev/null 2>&1; then
        enabled=$(_e138_state_get route_enabled 0)
        mode=$(_e138_state_get route_mode disabled)
    fi
    if test "$enabled" = 1 && test "$mode" = host-full; then
        error "完整参数集要求ip_forward=0，与当前WARP host-full冲突；请先关闭系统全隧道。"
        return 1
    fi
    for svc in docker.service podman.service containerd.service kubelet.service \
        k3s.service k3s-agent.service rke2-server.service rke2-agent.service \
        libvirtd.service virtqemud.service lxd.service incus.service \
        tailscaled.service zerotier-one.service; do
        if systemctl is-active --quiet "$svc" 2>/dev/null; then
            test "${E159_ALLOW_FORWARDING_OFF:-0}" = 1 || {
                error "检测到$svc运行；完整参数集的ip_forward=0可能中断容器/虚拟网络。"
                error "确认接受后可临时执行：E159_ALLOW_FORWARDING_OFF=1 bash ex199e159.sh --full-network-apply"
                return 1
            }
        fi
    done
    current_forward=$(sysctl -n net.ipv4.ip_forward 2>/dev/null || echo 0)
    all_forward=$(sysctl -n net.ipv4.conf.all.forwarding 2>/dev/null || echo 0)
    if { test "$current_forward" = 1 || test "$all_forward" = 1; } \
        && test "${E159_ALLOW_FORWARDING_OFF:-0}" != 1; then
        error "当前主机正在转发IPv4（ip_forward=$current_forward/all.forwarding=$all_forward）。"
        error "完整参数集要求二者为0；确认不承担路由/NAT后，用E159_ALLOW_FORWARDING_OFF=1显式执行。"
        return 1
    fi
}

_e159_network_paths() {
    printf '%s\n' \
        "$E159_REQUESTED_CONF" "$E159_EFFECTIVE_CONF" "$E159_NETWORK_REPORT" \
        "$E159_NETWORK_STATE" "$E159_NETWORK_SEAL" \
        "$E159_NETWORK_SCRIPT" "$E159_NETWORK_SERVICE" "$E159_NETWORK_TIMER" \
        "$E159_MODULES_CONF" "$E159_HOST_SCRIPT" "$E159_HOST_SERVICE" "$E159_HOST_STATE" \
        "$E159_LEGACY_E156_REQUESTED_CONF" "$E159_LEGACY_E156_EFFECTIVE_CONF" \
        "$E159_LEGACY_E156_REPORT" "$E159_LEGACY_E156_STATE" "$E159_LEGACY_E156_SEAL" \
        "$E159_LEGACY_E156_SCRIPT" "$E159_LEGACY_E156_SERVICE" \
        "$E159_LEGACY_E156_TIMER" "$E159_LEGACY_E156_MODULES_CONF" \
        "$E159_LEGACY_E154_REQUESTED_CONF" "$E159_LEGACY_E154_EFFECTIVE_CONF" \
        "$E159_LEGACY_E154_REPORT" "$E159_LEGACY_E154_STATE" \
        "$E159_LEGACY_E154_SCRIPT" "$E159_LEGACY_E154_SERVICE" \
        "$E159_LEGACY_E154_TIMER" "$E159_LEGACY_E154_MODULES_CONF" \
        "$E152_NETWORK_CONF" "$E152_NETWORK_STATE" "$E152_NETWORK_SCRIPT" \
        "$E152_NETWORK_SERVICE" "$E152_NETWORK_TIMER" \
        /usr/local/bin/xray-hw-tweaks.sh /etc/systemd/system/xray-hw-tweaks.service \
        /etc/sysctl.d/99-xray-e125-accel.conf \
        /etc/sysctl.d/99-xray-e126-accel.conf \
        /etc/sysctl.d/99-xray-e135-network.conf \
        /etc/sysctl.d/99-xray-e136-network.conf \
        /etc/sysctl.d/99-xray-e138-network.conf \
        /etc/sysctl.d/99-xray-e139-network.conf \
        /etc/sysctl.d/99-xray-e142-network.conf \
        /etc/sysctl.d/99-xray-e143-network.conf \
        /etc/sysctl.d/99-xray-e145-network.conf \
        /etc/sysctl.d/99-network-optimized.conf \
        /etc/sysctl.d/98-xray-core-tuning.conf \
        /etc/sysctl.d/99-xray-hotupdate-fast.conf \
        /etc/sysctl.d/99-xray-pmtu-e106.conf \
        /etc/sysctl.d/99-xray-pmtu-e107.conf \
        /etc/sysctl.d/99-auto-tune-relay-e108.conf \
        /etc/sysctl.d/99-auto-tune-relay-e109.conf \
        /etc/sysctl.d/98-xray-swap.conf
}

_e159_legacy_sysctl_owned() {
    local f="$1" count
    case "$f" in
        /etc/sysctl.d/98-xray-core-tuning.conf|\
        /etc/sysctl.d/99-xray-hotupdate-fast.conf|\
        /etc/sysctl.d/99-xray-pmtu-e106.conf|\
        /etc/sysctl.d/99-xray-pmtu-e107.conf|\
        /etc/sysctl.d/99-auto-tune-relay-e108.conf|\
        /etc/sysctl.d/99-auto-tune-relay-e109.conf|\
        /etc/sysctl.d/98-xray-swap.conf) return 0 ;;
        /etc/sysctl.d/99-network-optimized.conf)
            test -s "$f" || return 1
            # E127/E153 generated files can contain commented unsupported
            # keys, so active-key counting alone is not a reliable ownership
            # test.  Their explicit generator marker is authoritative.
            grep -Eq '^# Xray / VPS Network Optimized Sysctl Profile([[:space:]]|$)' "$f" \
                && return 0
            count=$(_e159_active_keys "$f" | wc -l | tr -d ' ')
            test "$count" -ge 100 || return 1
            grep -Eq '^net\.core\.rmem_max[[:space:]]*=[[:space:]]*97108868([[:space:]]*)$' "$f" || return 1
            grep -Eq '^net\.unix\.max_dgram_qlen[[:space:]]*=[[:space:]]*130000([[:space:]]*)$' "$f" || return 1
            grep -Eq '^net\.ipv4\.tcp_pacing_ss_ratio[[:space:]]*=[[:space:]]*210([[:space:]]*)$' "$f" || return 1
            return 0 ;;
        *) return 1 ;;
    esac
}

_e159_network_tx_new() {
    local d
    _e159_prepare || return 1
    d="$E159_NETWORK_TX_ROOT/tx-$(date +%Y%m%d_%H%M%S)-$$-$RANDOM"
    install -d -m 0700 "$d/files" || return 1
    printf '%s\n' "$d"
}

_e159_snapshot_service() {
    local unit="$1"
    printf '%s|%s|%s\n' "$unit" \
        "$(systemctl is-enabled "$unit" 2>/dev/null || true)" \
        "$(systemctl is-active "$unit" 2>/dev/null || true)"
}

_e159_snapshot_side_effects() {
    local tx="$1" root="${E159_PROC_ROOT:-/proc/sys}" path rel value encoded
    : >"$tx/side-effects.before" || return 1
    if test -d "$root/net/ipv4/conf"; then
        while IFS= read -r path; do
            test -r "$path" && test -w "$path" || continue
            rel=${path#"$root"/}
            value=$(_e159_norm "$(cat "$path" 2>/dev/null || true)")
            encoded=$(printf '%s' "$value" | base64 | tr -d '\n\r')
            printf '%s\t%s\n' "$rel" "$encoded" >>"$tx/side-effects.before" || return 1
        done < <(find "$root/net/ipv4/conf" -type f -print 2>/dev/null | sort)
    fi
    path="$root/vm/dirty_bytes"
    if test -r "$path" && test -w "$path"; then
        value=$(_e159_norm "$(cat "$path" 2>/dev/null || true)")
        if test "${value:-0}" != 0; then
            encoded=$(printf '%s' "$value" | base64 | tr -d '\n\r')
            printf 'vm/dirty_bytes\t%s\n' "$encoded" >>"$tx/side-effects.before" || return 1
        fi
    fi
}

_e159_restore_side_effects() {
    local file="$1" root="${E159_PROC_ROOT:-/proc/sys}" rel encoded value path current rc=0
    test -s "$file" || return 0
    while IFS=$'\t' read -r rel encoded; do
        [[ "$rel" =~ ^(net/ipv4/conf/[A-Za-z0-9_.:-]+/[A-Za-z0-9_]+|vm/dirty_bytes)$ ]] || { rc=1; continue; }
        path="$root/$rel"
        test -e "$path" || continue
        test -w "$path" || { rc=1; continue; }
        value=$(printf '%s' "$encoded" | base64 -d 2>/dev/null) || { rc=1; continue; }
        printf '%s\n' "$value" >"$path" 2>/dev/null || { rc=1; continue; }
    done <"$file"
    while IFS=$'\t' read -r rel encoded; do
        [[ "$rel" =~ ^(net/ipv4/conf/[A-Za-z0-9_.:-]+/[A-Za-z0-9_]+|vm/dirty_bytes)$ ]] || continue
        path="$root/$rel"; test -r "$path" || continue
        value=$(printf '%s' "$encoded" | base64 -d 2>/dev/null) || { rc=1; continue; }
        current=$(_e159_norm "$(cat "$path" 2>/dev/null || true)")
        test "$current" = "$(_e159_norm "$value")" || rc=1
    done <"$file"
    return "$rc"
}

_e159_network_snapshot() {
    local tx="$1" requested="$2" p id key old
    : >"$tx/paths.tsv" || return 1
    while IFS= read -r p; do
        test -n "$p" || continue
        id=$(printf '%s' "$p" | sha256sum | awk '{print $1}')
        printf '%s|%s\n' "$p" "$id" >>"$tx/paths.tsv" || return 1
        _e135_snapshot_file "$p" "$tx/files/$id" || return 1
    done < <(_e159_network_paths | awk 'NF&&!seen[$0]++')

    : >"$tx/runtime.before" || return 1
    while IFS= read -r key; do
        test "$key" = net.ipv4.route.flush && continue
        old=$(sysctl -n "$key" 2>/dev/null || true)
        test -n "$old" && printf '%s|%s\n' "$key" "$(_e159_norm "$old")" >>"$tx/runtime.before"
    done < <(_e159_active_keys "$requested")

    _e159_snapshot_side_effects "$tx" || return 1

    {
        _e159_snapshot_service xray-network-e159.timer
        _e159_snapshot_service xray-network-e159.service
        _e159_snapshot_service xray-network-e156.timer
        _e159_snapshot_service xray-network-e156.service
        _e159_snapshot_service xray-network-e154.timer
        _e159_snapshot_service xray-network-e154.service
        _e159_snapshot_service xray-network-e152.timer
        _e159_snapshot_service xray-network-e152.service
        _e159_snapshot_service xray-hw-tweaks.service
        _e159_snapshot_service xray-accel-e125.service
        _e159_snapshot_service xray-accel-e126.service
    } >"$tx/services.before" || return 1
    printf 'created=%s\nkernel=%s\n' "$(date -Is 2>/dev/null || date)" "$(uname -r)" >"$tx/meta.env"
    (cd "$tx" && find . -type f ! -name seal.sha256 -print0 | sort -z | xargs -0 sha256sum >seal.sha256) || return 1
    test -s "$tx/seal.sha256"
}

_e159_network_tx_verify() {
    local tx="$1" real root trusted=0
    real=$(readlink -f -- "$tx" 2>/dev/null || true)
    test -n "$real" || return 1
    for root in "$E159_NETWORK_TX_ROOT" "$E159_LEGACY_E156_NETWORK_TX_ROOT" \
        "$E159_LEGACY_E154_NETWORK_TX_ROOT"; do
        root=$(readlink -f -- "$root" 2>/dev/null || true)
        test -n "$root" || continue
        case "$real" in "$root"/*) trusted=1; break ;; esac
    done
    test "$trusted" -eq 1 || return 1
    test -s "$tx/seal.sha256" || return 1
    (cd "$tx" && sha256sum -c seal.sha256 >/dev/null 2>&1)
}

_e159_restore_service() {
    local unit="$1" enabled="$2" active="$3" rc=0 now
    case "$enabled" in enabled|enabled-runtime|linked|linked-runtime|alias|indirect)
        systemctl enable "$unit" >/dev/null 2>&1 || rc=1 ;;
      *) systemctl disable "$unit" >/dev/null 2>&1 || true ;;
    esac
    case "$active" in active|activating|reloading)
        systemctl start "$unit" >/dev/null 2>&1 || rc=1 ;;
      *) systemctl stop "$unit" >/dev/null 2>&1 || true ;;
    esac
    now=$(systemctl is-enabled "$unit" 2>/dev/null || true)
    case "$enabled" in
        enabled|enabled-runtime|linked|linked-runtime|alias|indirect)
            case "$now" in enabled|enabled-runtime|linked|linked-runtime|alias|indirect) ;; *) rc=1 ;; esac ;;
        *) case "$now" in enabled|enabled-runtime|linked|linked-runtime) rc=1 ;; esac ;;
    esac
    now=$(systemctl is-active "$unit" 2>/dev/null || true)
    case "$active" in
        active|activating|reloading) case "$now" in active|activating|reloading) ;; *) rc=1 ;; esac ;;
        *) case "$now" in active|activating|reloading) rc=1 ;; esac ;;
    esac
    return "$rc"
}

_e159_restore_runtime_file() {
    local file="$1" key old current rc=0
    test -s "$file" || return 0
    old=$(awk -F'|' '$1=="net.ipv4.ip_forward"{print substr($0,index($0,"|")+1);exit}' "$file")
    if test -n "$old"; then
        current=$(sysctl -n net.ipv4.ip_forward 2>/dev/null || true)
        test "$current" = "$old" || sysctl -w "net.ipv4.ip_forward=$old" >/dev/null 2>&1 || rc=1
    fi
    while IFS='|' read -r key old; do
        test -n "$key" || continue
        case "$key" in net.ipv4.ip_forward|net.ipv4.route.flush) continue ;; esac
        sysctl -w "$key=$old" >/dev/null 2>&1 || rc=1
    done <"$file"
    return "$rc"
}

_e159_verify_runtime_file() {
    local file="$1" key old current failed=0
    test -s "$file" || return 0
    while IFS='|' read -r key old; do
        test -n "$key" || continue
        case "$key" in net.ipv4.route.flush) continue ;; esac
        current=$(sysctl -n "$key" 2>/dev/null || true)
        _e159_value_equal "$key" "$old" "$current" || {
            error "E159回滚读回不一致：$key 期望=$old 实际=${current:-unreadable}"
            failed=1
        }
    done <"$file"
    test "$failed" -eq 0
}

_e159_network_restore() {
    local tx="$1" p id unit enabled active rc=0
    _e159_network_tx_verify "$tx" || { error "E159网络回滚快照校验失败：$tx"; return 1; }
    systemctl disable --now xray-network-e159.timer xray-network-e159.service >/dev/null 2>&1 || true
    while IFS='|' read -r p id; do
        test -n "$p" && test -n "$id" || continue
        _e135_restore_file "$p" "$tx/files/$id" || rc=1
    done <"$tx/paths.tsv"
    systemctl daemon-reload >/dev/null 2>&1 || rc=1
    while IFS='|' read -r unit enabled active; do
        test -n "$unit" || continue
        _e159_restore_service "$unit" "$enabled" "$active" || rc=1
    done <"$tx/services.before"
    # Restored legacy oneshot services may write sysctls while being started;
    # restore the exact pre-transaction runtime values last, then read them all
    # back.  A rollback that drifts is a failure, never a cosmetic warning.
    _e159_restore_runtime_file "$tx/runtime.before" || rc=1
    _e159_restore_side_effects "$tx/side-effects.before" || rc=1
    _e159_verify_runtime_file "$tx/runtime.before" || rc=1
    return "$rc"
}

_e159_disable_old_network_layers() {
    local unit f
    # Stop this release's previous verifier too.  It uses the same advisory
    # lock as the transaction, so it cannot race a candidate/file/runtime
    # commit.  The new assets are enabled again only after all writes pass.
    for unit in xray-network-e159.timer xray-network-e159.service \
        xray-network-e156.timer xray-network-e156.service \
        xray-network-e154.timer xray-network-e154.service \
        xray-network-e152.timer xray-network-e152.service \
        xray-hw-tweaks.service xray-accel-e125.service xray-accel-e126.service; do
        systemctl disable --now "$unit" >/dev/null 2>&1 || true
    done
    # These files are all script-owned narrow layers.  The complete E159 file
    # supersedes them; user/distro sysctl files are deliberately not edited.
    for f in \
        "$E159_LEGACY_E156_REQUESTED_CONF" "$E159_LEGACY_E156_EFFECTIVE_CONF" \
        "$E159_LEGACY_E156_REPORT" "$E159_LEGACY_E156_STATE" "$E159_LEGACY_E156_SEAL" \
        "$E159_LEGACY_E156_SCRIPT" "$E159_LEGACY_E156_SERVICE" \
        "$E159_LEGACY_E156_TIMER" "$E159_LEGACY_E156_MODULES_CONF" \
        "$E159_LEGACY_E154_REQUESTED_CONF" "$E159_LEGACY_E154_EFFECTIVE_CONF" \
        "$E159_LEGACY_E154_REPORT" "$E159_LEGACY_E154_STATE" \
        "$E159_LEGACY_E154_SCRIPT" "$E159_LEGACY_E154_SERVICE" \
        "$E159_LEGACY_E154_TIMER" "$E159_LEGACY_E154_MODULES_CONF" \
        "$E152_NETWORK_CONF" "$E152_NETWORK_SCRIPT" "$E152_NETWORK_SERVICE" "$E152_NETWORK_TIMER" \
        /usr/local/bin/xray-hw-tweaks.sh /etc/systemd/system/xray-hw-tweaks.service \
        /etc/sysctl.d/99-xray-e125-accel.conf /etc/sysctl.d/99-xray-e126-accel.conf \
        /etc/sysctl.d/99-xray-e135-network.conf /etc/sysctl.d/99-xray-e136-network.conf \
        /etc/sysctl.d/99-xray-e138-network.conf /etc/sysctl.d/99-xray-e139-network.conf \
        /etc/sysctl.d/99-xray-e142-network.conf /etc/sysctl.d/99-xray-e143-network.conf \
        /etc/sysctl.d/99-xray-e145-network.conf; do
        rm -f -- "$f" 2>/dev/null || return 1
    done
    for f in /etc/sysctl.d/99-network-optimized.conf \
        /etc/sysctl.d/98-xray-core-tuning.conf /etc/sysctl.d/99-xray-hotupdate-fast.conf \
        /etc/sysctl.d/99-xray-pmtu-e106.conf /etc/sysctl.d/99-xray-pmtu-e107.conf \
        /etc/sysctl.d/99-auto-tune-relay-e108.conf /etc/sysctl.d/99-auto-tune-relay-e109.conf \
        /etc/sysctl.d/98-xray-swap.conf; do
        test -e "$f" || continue
        if _e159_legacy_sysctl_owned "$f"; then
            rm -f -- "$f" || return 1
        else
            warn "保留未能确认归属的旧sysctl文件：$f（逐项审计会报告重复定义）。"
        fi
    done
    rm -f -- "$E152_NETWORK_STATE" 2>/dev/null || true
    systemctl daemon-reload >/dev/null 2>&1 || return 1
}

_e159_apply_runtime() {
    local file="$1" key value current failed=0
    value=$(awk -F= '$1 ~ /^[[:space:]]*net.ipv4.ip_forward[[:space:]]*$/{print $2;exit}' "$file" | xargs)
    if test -n "$value"; then
        current=$(sysctl -n net.ipv4.ip_forward 2>/dev/null | xargs || true)
        if test "$current" != "$value"; then
            sysctl -w "net.ipv4.ip_forward=$value" >/dev/null 2>&1 || return 1
        fi
    fi
    while IFS='=' read -r key value; do
        key=$(_e159_norm "$key")
        value=$(_e159_norm "$value")
        case "$key" in ''|'#'*|net.ipv4.ip_forward|net.ipv4.route.flush) continue ;; esac
        sysctl -w "$key=$value" >/dev/null 2>&1 || { error "E159写入失败：$key"; return 1; }
    done <"$file"
    if grep -q '^net.ipv4.route.flush[[:space:]]*=' "$file"; then
        sysctl -w net.ipv4.route.flush=1 >/dev/null 2>&1 || { error "路由缓存刷新触发失败。"; return 1; }
    fi
    while IFS='=' read -r key value; do
        key=$(_e159_norm "$key")
        value=$(_e159_norm "$value")
        case "$key" in ''|'#'*|net.ipv4.route.flush) continue ;; esac
        current=$(sysctl -n "$key" 2>/dev/null || true)
        _e159_value_equal "$key" "$value" "$current" || {
            error "E159读回不一致：$key 期望=$value 实际=${current:-unreadable}"
            failed=1
        }
    done <"$file"
    test "$failed" -eq 0
}

_e159_install_network_assets() {
    local script service timer modules qdisc
    script=$(_e118_mktemp e159-network.sh) || return 1
    service=$(_e118_mktemp e159-network.service) || return 1
    timer=$(_e118_mktemp e159-network.timer) || return 1
    modules=$(_e118_mktemp e159-modules.conf) || return 1
    qdisc=$(awk -F= '$1 ~ /^[[:space:]]*net.core.default_qdisc[[:space:]]*$/{gsub(/[[:space:]]/,"",$2);print $2;exit}' "$E159_EFFECTIVE_CONF")
    [[ "$qdisc" =~ ^(fq|fq_codel|cake)$ ]] || { error "E159有效配置中的qdisc无效。"; return 1; }
    printf 'tcp_bbr\nsch_%s\n' "$qdisc" >"$modules" || return 1
    cat >"$script" <<'EOF_E159_BOOT'
#!/usr/bin/env bash
set -euo pipefail
export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
CONF=/etc/sysctl.d/99-xray-e159-full.conf
SEAL=/usr/local/etc/xray/e159/network-files.sha256
LOG=/var/log/xray/e159/network-boot.log
install -d -m 0700 "$(dirname "$LOG")"
: >"$LOG"
if test -e /run/lock || test -L /run/lock; then
    test -d /run/lock && test -x /run/lock || exit 1
else
    install -d -m 0755 /run/lock || exit 1
fi
exec 9>/run/lock/xray-network-e159.lock
flock -w 30 9
test -s "$CONF" && test -s "$SEAL"
sha256sum -c "$SEAL" >>"$LOG" 2>&1
modprobe tcp_bbr >/dev/null 2>&1 || true
qdisc=$(awk -F= '$1 ~ /^[[:space:]]*net.core.default_qdisc[[:space:]]*$/{gsub(/[[:space:]]/,"",$2);print $2;exit}' "$CONF")
case "$qdisc" in fq|fq_codel|cake) modprobe "sch_$qdisc" >/dev/null 2>&1 || true ;; *) exit 1 ;; esac
norm() { printf '%s\n' "${1:-}" | awk '{$1=$1;print}'; }
equal() {
  local key="$1" expected actual
  expected=$(norm "$2"); actual=$(norm "$3")
  case "$key" in
    net.ipv4.tcp_recovery) (( expected == actual )) 2>/dev/null ;;
    net.ipv4.tcp_child_ehash_entries)
      test "$expected" = "$actual" || { test "$expected" = 65535 && test "$actual" = 65536; } ;;
    *) test "$expected" = "$actual" ;;
  esac
}
failed=0 changed=0
forward=$(awk -F= '$1 ~ /^[[:space:]]*net.ipv4.ip_forward[[:space:]]*$/{print $2;exit}' "$CONF" | xargs)
if test -n "$forward" && test "$(sysctl -n net.ipv4.ip_forward 2>/dev/null | xargs)" != "$forward"; then
  sysctl -w "net.ipv4.ip_forward=$forward" >/dev/null 2>&1 || failed=1
  changed=$((changed+1))
fi
while IFS='=' read -r key value; do
  key=$(norm "$key"); value=$(norm "$value")
  case "$key" in ''|'#'*|net.ipv4.ip_forward|net.ipv4.route.flush) continue ;; esac
  path="/proc/sys/${key//./\/}"
  if test ! -w "$path"; then
    printf '%s unsupported %s\n' "$(date -Is)" "$key" >>"$LOG"
    failed=1
    continue
  fi
  actual=$(sysctl -n "$key" 2>/dev/null || true)
  if ! equal "$key" "$value" "$actual"; then
    if sysctl -w "$key=$value" >/dev/null 2>&1; then changed=$((changed+1)); else failed=1; continue; fi
  fi
  actual=$(sysctl -n "$key" 2>/dev/null || true)
  equal "$key" "$value" "$actual" || failed=1
done <"$CONF"
printf '%s changed=%s failed=%s\n' "$(date -Is)" "$changed" "$failed" >>"$LOG"
test "$failed" -eq 0
EOF_E159_BOOT

    cat >"$service" <<EOF_E159_SERVICE
[Unit]
Description=V199e159 127-request / 125-persistent-control network verification
After=systemd-sysctl.service network-online.target
Wants=network-online.target
Before=xray.service

[Service]
Type=oneshot
ExecStart=$E159_NETWORK_SCRIPT
TimeoutStartSec=90

[Install]
WantedBy=multi-user.target
EOF_E159_SERVICE

    cat >"$timer" <<'EOF_E159_TIMER'
[Unit]
Description=V199e159 network drift verification

[Timer]
# OnActiveSec avoids an immediate elapsed-OnBootSec trigger while the install
# transaction is still committing.  The separately enabled service still runs
# during normal boot before xray.service.
OnActiveSec=2min
OnUnitInactiveSec=15min
AccuracySec=1min
Persistent=true
Unit=xray-network-e159.service

[Install]
WantedBy=timers.target
EOF_E159_TIMER
    bash -n "$script" || return 1
    _e121_atomic_install "$script" "$E159_NETWORK_SCRIPT" 0755 || return 1
    _e121_atomic_install "$service" "$E159_NETWORK_SERVICE" 0644 || return 1
    _e121_atomic_install "$timer" "$E159_NETWORK_TIMER" 0644 || return 1
    _e121_atomic_install "$modules" "$E159_MODULES_CONF" 0644 || return 1
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    systemctl enable xray-network-e159.service xray-network-e159.timer >/dev/null 2>&1 || return 1
    # Runtime values were already applied and read back by the transaction.
    # Do not start the verifier while this same transaction owns its lock.
    systemctl start xray-network-e159.timer >/dev/null 2>&1 || return 1
    systemctl is-enabled --quiet xray-network-e159.service || return 1
    systemctl is-enabled --quiet xray-network-e159.timer || return 1
    systemctl is-active --quiet xray-network-e159.timer || return 1
}

_e159_network_verify_ownership() {
    local unit f
    for unit in xray-network-e156.timer xray-network-e156.service \
        xray-network-e154.timer xray-network-e154.service \
        xray-network-e152.timer xray-network-e152.service \
        xray-hw-tweaks.service xray-accel-e125.service xray-accel-e126.service; do
        systemctl is-enabled --quiet "$unit" 2>/dev/null && {
            error "旧网络所有者仍被启用：$unit"; return 1;
        } || true
        systemctl is-active --quiet "$unit" 2>/dev/null && {
            error "旧网络所有者仍在运行：$unit"; return 1;
        } || true
    done
    for f in "$E159_LEGACY_E156_REQUESTED_CONF" "$E159_LEGACY_E156_EFFECTIVE_CONF" \
        "$E159_LEGACY_E156_REPORT" "$E159_LEGACY_E156_STATE" "$E159_LEGACY_E156_SEAL" \
        "$E159_LEGACY_E156_SCRIPT" "$E159_LEGACY_E156_SERVICE" \
        "$E159_LEGACY_E156_TIMER" "$E159_LEGACY_E156_MODULES_CONF" \
        "$E159_LEGACY_E154_REQUESTED_CONF" "$E159_LEGACY_E154_EFFECTIVE_CONF" \
        "$E159_LEGACY_E154_REPORT" "$E159_LEGACY_E154_STATE" \
        "$E159_LEGACY_E154_SCRIPT" "$E159_LEGACY_E154_SERVICE" \
        "$E159_LEGACY_E154_TIMER" "$E159_LEGACY_E154_MODULES_CONF" \
        "$E152_NETWORK_CONF" "$E152_NETWORK_SCRIPT" "$E152_NETWORK_SERVICE" "$E152_NETWORK_TIMER" \
        /usr/local/bin/xray-hw-tweaks.sh /etc/systemd/system/xray-hw-tweaks.service \
        /etc/sysctl.d/99-xray-e125-accel.conf /etc/sysctl.d/99-xray-e126-accel.conf; do
        test ! -e "$f" || { error "旧网络所有者文件仍存在：$f"; return 1; }
    done
    systemctl is-enabled --quiet xray-network-e159.service 2>/dev/null || return 1
    systemctl is-enabled --quiet xray-network-e159.timer 2>/dev/null || return 1
    systemctl is-active --quiet xray-network-e159.timer 2>/dev/null || return 1
}

_e159_restore_ipv6_if_e152_owned() {
    local legacy_owned="$1"
    test "$legacy_owned" = 1 || return 0
    # E152 changed every interface, but did not retain the user's older
    # per-interface policy.  Blindly writing 0 here could expose IPv6 on a host
    # whose firewall only protects IPv4.  E159 removes the script-owned
    # persistent disable entries and leaves the current runtime untouched;
    # normal kernel/user policy takes over on reboot.
    warn "已移除旧E152的持久化IPv6强制关闭项；为避免改变用户防火墙暴露面，本次不盲目把所有接口写成0。"
    warn "E159以后不管理disable_ipv6；当前运行态保持不变，重启后遵循系统/用户自己的IPv6策略。"
    return 0
}

_e159_prune_network_tx() {
    local keep=10 n=0 d p real protected=" "
    test -d "$E159_NETWORK_TX_ROOT" || return 0
    p=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1)
    real=$(readlink -f -- "$p" 2>/dev/null || true); test -z "$real" || protected+="$real "
    p=$(sed -n 's/^origin_backup=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1)
    real=$(readlink -f -- "$p" 2>/dev/null || true); test -z "$real" || protected+="$real "
    p=$(sed -n 's/^network_backup=//p' "$E159_CRITICAL_MARKER" 2>/dev/null | tail -n1)
    real=$(readlink -f -- "$p" 2>/dev/null || true); test -z "$real" || protected+="$real "
    while IFS= read -r d; do
        n=$((n+1)); test "$n" -le "$keep" && continue
        real=$(readlink -f -- "$d" 2>/dev/null || true)
        [[ "$protected" == *" $real "* ]] && continue
        case "$real" in "$E159_NETWORK_TX_ROOT"/*) rm -rf -- "$real" 2>/dev/null || true ;; esac
    done < <(find "$E159_NETWORK_TX_ROOT" -mindepth 1 -maxdepth 1 -type d -printf '%T@ %p\n' 2>/dev/null | sort -nr | cut -d' ' -f2-)
}

_e159_prune_system_tx() {
    local keep="${XRAY_E159_TX_KEEP:-12}" protected=" " p real row n=0
    [[ "$keep" =~ ^[0-9]+$ ]] && (( keep >= 3 && keep <= 100 )) || keep=12
    for p in "$@"; do
        real=$(readlink -f -- "$p" 2>/dev/null || true)
        test -z "$real" || protected+="$real "
    done
    if test -s "$E159_CRITICAL_MARKER"; then
        while IFS= read -r p; do
            real=$(readlink -f -- "$p" 2>/dev/null || true)
            test -z "$real" || protected+="$real "
        done < <(sed -nE 's/^(system_backup|network_backup|core_backup)=//p' "$E159_CRITICAL_MARKER")
    fi
    test -d "$E159_TX_ROOT" || return 0
    while IFS=$'\t' read -r _ row; do
        test -n "$row" || continue
        n=$((n+1)); test "$n" -le "$keep" && continue
        real=$(readlink -f -- "$row" 2>/dev/null || true)
        case "$real" in "$E159_TX_ROOT"/*) ;; *) continue ;; esac
        [[ "$protected" == *" $real "* ]] && continue
        rm -rf -- "${real:?}" 2>/dev/null || true
    done < <(find "$E159_TX_ROOT" -mindepth 1 -maxdepth 1 -type d -printf '%T@\t%p\n' 2>/dev/null | sort -nr)
}

_e159_network_apply() (
    local qdisc="${1:-fq}" scale="${2:-1}" app="${3:-31}" confirm="${4:-}"
    local requested effective report tx tmp seal_tmp failed=0 legacy_ipv6=0
    local supported unsupported shadowed trigger effective_active effective_persistent
    local origin_backup=""
    _e159_prepare || return 1
    # The boot verifier and the mutating transaction deliberately share one
    # lock.  The function is a subshell so fd 154 (and its lock) is released on
    # every success/error return, including interactive-menu invocations.
    exec 154>/run/lock/xray-network-e159.lock
    flock -w 90 154 || { error "另一个E159网络事务/开机复检占用锁超过90秒。"; return 1; }
    _e159_forwarding_conflict || return 1
    _e159_kernel_prepare "$qdisc" || return 1
    requested=$(_e118_mktemp e159-requested.conf) || return 1
    effective=$(_e118_mktemp e159-effective.conf) || return 1
    report=$(_e118_mktemp e159-compat.tsv) || return 1
    _e159_full_spec "$qdisc" "$scale" "$app" "$requested" || return 1
    _e159_spec_validate "$requested" || return 1
    _e159_build_effective "$requested" "$effective" "$report" || return 1
    _e159_network_artifacts_validate "$requested" "$effective" "$report" || return 1
    if test "$confirm" != force; then
        warn "将事务应用完整参数集：127条请求/125个持久控制，BBR/$qdisc、7990577/97108868、busy_poll=50、notsent=16384。"
        warn "其中ip_forward=0、激进重试、16KiB notsent和大默认缓冲会影响整台VPS。"
        read -rp "输入 APPLY-FULL-125 确认: " confirm || true
        test "$confirm" = APPLY-FULL-125 || { info "已取消。"; return 0; }
    fi
    grep -RqsE '^[[:space:]]*net\.ipv6\.conf\..*\.disable_ipv6[[:space:]]*=[[:space:]]*1' \
        "$E152_NETWORK_CONF" /etc/sysctl.d/99-xray-e1*-network.conf 2>/dev/null && legacy_ipv6=1 || true
    origin_backup=$(sed -n 's/^origin_backup=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1)
    test -n "$origin_backup" || origin_backup=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1)
    if test -z "$origin_backup" && test -s "$E159_LEGACY_E156_STATE"; then
        origin_backup=$(sed -n 's/^origin_backup=//p' "$E159_LEGACY_E156_STATE" 2>/dev/null | tail -n1)
        test -n "$origin_backup" || origin_backup=$(sed -n 's/^backup=//p' "$E159_LEGACY_E156_STATE" 2>/dev/null | tail -n1)
    fi
    if test -z "$origin_backup" && test -s "$E159_LEGACY_E154_STATE"; then
        origin_backup=$(sed -n 's/^origin_backup=//p' "$E159_LEGACY_E154_STATE" 2>/dev/null | tail -n1)
        test -n "$origin_backup" || origin_backup=$(sed -n 's/^backup=//p' "$E159_LEGACY_E154_STATE" 2>/dev/null | tail -n1)
    fi
    if test -n "$origin_backup" && ! _e159_network_tx_verify "$origin_backup"; then
        warn "旧origin_backup无效；本次事务将建立新的可验证起点。"
        origin_backup=""
    fi
    tx=$(_e159_network_tx_new) || return 1
    _e159_network_snapshot "$tx" "$requested" || return 1
    test -n "$origin_backup" || origin_backup="$tx"

    _e159_disable_old_network_layers || failed=1
    test "$failed" -ne 0 || _e121_atomic_install "$requested" "$E159_REQUESTED_CONF" 0600 || failed=1
    test "$failed" -ne 0 || _e121_atomic_install "$effective" "$E159_EFFECTIVE_CONF" 0644 || failed=1
    test "$failed" -ne 0 || _e121_atomic_install "$report" "$E159_NETWORK_REPORT" 0600 || failed=1
    test "$failed" -ne 0 || _e159_network_artifacts_validate \
        "$E159_REQUESTED_CONF" "$E159_EFFECTIVE_CONF" "$E159_NETWORK_REPORT" || failed=1
    if test "$failed" -eq 0; then
        seal_tmp=$(_e118_mktemp e159-network-seal) || failed=1
    fi
    if test "$failed" -eq 0; then
        sha256sum "$E159_REQUESTED_CONF" "$E159_EFFECTIVE_CONF" "$E159_NETWORK_REPORT" \
            >"$seal_tmp" || failed=1
        test "$failed" -ne 0 || _e121_atomic_install "$seal_tmp" "$E159_NETWORK_SEAL" 0600 || failed=1
        test "$failed" -ne 0 || sha256sum -c "$E159_NETWORK_SEAL" >/dev/null 2>&1 || failed=1
    fi
    test "$failed" -ne 0 || _e159_apply_runtime "$E159_EFFECTIVE_CONF" || failed=1
    test "$failed" -ne 0 || _e159_install_network_assets || failed=1
    test "$failed" -ne 0 || _e159_network_verify_ownership || failed=1
    test "$failed" -ne 0 || _e159_restore_ipv6_if_e152_owned "$legacy_ipv6" || failed=1
    if test "$failed" -eq 0; then
        supported=$(awk -F'\t' 'NR>1 && $2=="supported"{n++}END{print n+0}' "$E159_NETWORK_REPORT")
        unsupported=$(awk -F'\t' 'NR>1 && $2=="unsupported"{n++}END{print n+0}' "$E159_NETWORK_REPORT")
        shadowed=$(awk -F'\t' 'NR>1 && $2=="shadowed-alias"{n++}END{print n+0}' "$E159_NETWORK_REPORT")
        trigger=$(awk -F'\t' 'NR>1 && $1=="net.ipv4.route.flush" && $2=="supported"{n++}END{print n+0}' "$E159_NETWORK_REPORT")
        effective_active=$(_e159_active_keys "$E159_EFFECTIVE_CONF" | wc -l | tr -d ' ')
        effective_persistent=$((effective_active-trigger))
        test "$effective_active" -eq "$supported" \
          && test $((supported+unsupported+shadowed)) -eq 127 \
          && test "$effective_persistent" -ge 0 || failed=1
    fi
    if test "$failed" -eq 0; then
        tmp="$E159_NETWORK_STATE.tmp.$$"
        {
            echo "version=199e159"
            echo "profile=full125-persistent/source127"
            echo "qdisc=$qdisc"
            echo "tcp_adv_win_scale=$scale"
            echo "tcp_app_win=$app"
            echo "requested_entries=127"
            echo "logical_controls=125"
            echo "effective_active=$effective_active"
            echo "effective_persistent=$effective_persistent"
            echo "supported=$supported"
            echo "unsupported=$unsupported"
            echo "shadowed_alias=$shadowed"
            echo "write_trigger=$trigger"
            echo "ipv6_policy=preserve"
            echo "backup=$tx"
            echo "origin_backup=$origin_backup"
            echo "applied=$(date -Is 2>/dev/null || date)"
        } >"$tmp" && chmod 0600 "$tmp" && mv -f "$tmp" "$E159_NETWORK_STATE" || failed=1
    fi
    test "$failed" -ne 0 || _e159_network_state_validate "$E159_NETWORK_STATE" || failed=1
    if test "$failed" -ne 0; then
        error "E159完整网络事务失败，正在恢复全部运行值、文件和服务状态。"
        _e159_network_restore "$tx" || error "严重：E159网络回滚未完整通过。快照：$tx"
        return 1
    fi
    _e159_prune_network_tx
    info "完整参数集已事务提交：127条请求 = persistent=$effective_persistent + trigger=$trigger + unsupported=$unsupported + shadowed_alias=$shadowed；effective_assignments=$effective_active，IPv6=保留。"
    info "请求规格：$E159_REQUESTED_CONF"
    info "有效配置：$E159_EFFECTIVE_CONF"
    info "兼容报告：$E159_NETWORK_REPORT"
    info "回滚快照：$tx"
)

_e159_network_verify_effective() {
    local key value actual failed=0
    test -s "$E159_EFFECTIVE_CONF" && test -s "$E159_NETWORK_SEAL" || return 1
    sha256sum -c "$E159_NETWORK_SEAL" >/dev/null 2>&1 || {
        error "E159网络配置封印校验失败，拒绝把被改写的产物当成当前事务。"; return 1;
    }
    _e159_network_artifacts_validate \
        "$E159_REQUESTED_CONF" "$E159_EFFECTIVE_CONF" "$E159_NETWORK_REPORT" || return 1
    _e159_network_state_validate "$E159_NETWORK_STATE" || {
        error "E159网络状态计数/报告/快照不变量失败。"; return 1;
    }
    while IFS='=' read -r key value; do
        key=$(_e159_norm "$key"); value=$(_e159_norm "$value")
        case "$key" in ''|'#'*|net.ipv4.route.flush) continue ;; esac
        actual=$(sysctl -n "$key" 2>/dev/null || true)
        _e159_value_equal "$key" "$value" "$actual" || failed=1
    done <"$E159_EFFECTIVE_CONF"
    test "$failed" -eq 0
}

_e159_network_audit() {
    local requested key value actual status supported=0 unsupported=0 mismatch=0 trigger=0 alias_normalized=0 duplicates=0 f n
    local bytes_actual
    local qdisc=fq scale=1 app=31
    title "V199e159：125个持久控制（127条请求）逐项审计"
    if test -r "$E159_REQUESTED_CONF" && test -s "$E159_REQUESTED_CONF"; then requested="$E159_REQUESTED_CONF"
    else
        requested=$(_e118_mktemp e159-audit-requested.conf) || return 1
        if test -r "$E159_EFFECTIVE_CONF"; then
            qdisc=$(awk -F= '$1 ~ /^[[:space:]]*net.core.default_qdisc[[:space:]]*$/{gsub(/[[:space:]]/,"",$2);print $2;exit}' "$E159_EFFECTIVE_CONF"); qdisc=${qdisc:-fq}
            scale=$(awk -F= '$1 ~ /^[[:space:]]*net.ipv4.tcp_adv_win_scale[[:space:]]*$/{gsub(/[[:space:]]/,"",$2);print $2;exit}' "$E159_EFFECTIVE_CONF"); scale=${scale:-1}
            app=$(awk -F= '$1 ~ /^[[:space:]]*net.ipv4.tcp_app_win[[:space:]]*$/{gsub(/[[:space:]]/,"",$2);print $2;exit}' "$E159_EFFECTIVE_CONF"); app=${app:-31}
        fi
        _e159_full_spec "$qdisc" "$scale" "$app" "$requested" || return 1
    fi
    printf '  %-44s %-12s %s\n' 参数 状态 '请求值 -> 运行值'
    while IFS='=' read -r key value; do
        key=$(_e159_norm "$key"); value=$(_e159_norm "$value")
        case "$key" in ''|'#'*) continue ;; esac
        if test "$key" = net.ipv4.route.flush; then
            status=trigger; actual='write-only'; trigger=$((trigger+1))
        elif test "$key" = net.ipv4.neigh.default.unres_qlen \
            && test -e "$(_e159_proc_path net.ipv4.neigh.default.unres_qlen)" \
            && test -e "$(_e159_proc_path net.ipv4.neigh.default.unres_qlen_bytes)"; then
            actual=$(sysctl -n "$key" 2>/dev/null || echo unreadable)
            bytes_actual=$(sysctl -n net.ipv4.neigh.default.unres_qlen_bytes 2>/dev/null || echo unreadable)
            if _e159_unres_alias_equal "$requested" "$(_e159_norm "$actual")" "$(_e159_norm "$bytes_actual")"; then
                status=alias-bytes; alias_normalized=$((alias_normalized+1))
            else
                status=MISMATCH; mismatch=$((mismatch+1))
            fi
        elif test ! -e "$(_e159_proc_path "$key")"; then
            status=unsupported; actual='not-present'; unsupported=$((unsupported+1))
        else
            actual=$(sysctl -n "$key" 2>/dev/null || echo unreadable)
            if _e159_value_equal "$key" "$value" "$actual"; then
                if test "$(_e159_norm "$value")" = "$(_e159_norm "$actual")"; then status=ok
                else status=normalized; fi
                supported=$((supported+1))
            else status=MISMATCH; mismatch=$((mismatch+1)); fi
        fi
        printf '  %-44s %-12s %s -> %s\n' "$key" "$status" "$value" "$(_e159_norm "$actual")"
    done <"$requested"
    while IFS= read -r key; do
        value=0
        for f in /etc/sysctl.conf /etc/sysctl.d/*.conf; do
            test -f "$f" || continue
            n=$(awk -F= -v wanted="$key" '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{k=$1;gsub(/[[:space:]]/,"",k);if(k==wanted)n++}END{print n+0}' "$f")
            value=$((value+n))
        done
        (( value > 1 )) && duplicates=$((duplicates+1)) || true
    done < <(_e159_active_keys "$requested")
    echo
    echo "  原始请求: 127；持久独立匹配: $supported；共享别名: $alias_normalized；写触发器: $trigger；不支持: $unsupported；不一致: $mismatch"
    echo "  存在重复持久化定义的参数数: $duplicates（E159服务会以运行态读回为准）"
    echo "  BBR可用: $(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null || echo unknown)"
    echo "  默认qdisc: $(sysctl -n net.core.default_qdisc 2>/dev/null || echo unknown)"
    local iface
    iface=$(ip route show default 2>/dev/null | awk 'NR==1{print $5}')
    test -z "$iface" || echo "  实际qdisc($iface): $(tc qdisc show dev "$iface" 2>/dev/null | head -n1 || echo unknown)"
    echo "  IPv6禁用项由E159管理: 否（保留系统/用户策略）"
    echo "  开机复检: $(systemctl is-enabled xray-network-e159.timer 2>/dev/null || echo disabled) / $(systemctl is-active xray-network-e159.timer 2>/dev/null || echo inactive)"
    test -r "$E159_NETWORK_STATE" && test -s "$E159_NETWORK_STATE" \
        && sed 's/^/    /' "$E159_NETWORK_STATE" || true
    test "$mismatch" -eq 0
}

_e159_network_risk_notes() {
    cat <<'EOF_E159_RISKS'
  原始块的127条请求已完整保留（125个持久控制+1个写触发器+1个共享别名），但并非每项都是“纯加速”：
  - tcp_notsent_lowat=16384：响应优先、排队很低；高RTT大吞吐可能更频繁唤醒应用。
  - rmem/wmem默认7990577、上限97108868：高BDP有余量，也提高大量并发socket的内存压力。
  - tcp_retries2=8、syn_retries=3、synack_retries=2：故障发现更快，极差跨境链路也更早放弃。
  - ip_forward=0/all.forwarding=0：适合纯Xray主机，会与Docker/路由器/host-full WARP冲突。
  - busy_poll=50：只有应用/内核路径使用busy-poll时才可能受益，会增加CPU占用。
  - tcp_adv_win_scale在Linux 6.6+已是no-op；ipfrag_low_thresh自4.17起废弃。
  - tcp_child_ehash_entries=65535会被内核按语义向上取整为65536；审计标为normalized。
  - unres_qlen=3000与unres_qlen_bytes=65535是同一内核存储的包数/字节数视图，无法同时精确成立。
    E159保留127条原始请求作审计证据，但在有效配置中以现代unres_qlen_bytes=65535为准；
    因而unres_qlen通常读回约31，审计标为alias-bytes，不再误判为事务失败。
  - rps_sock_flow_entries只建立全局表；每队列rps_flow_cnt/RPS掩码仍由独立RPS菜单管理。
  - route.flush是写触发器，不存在可持久读回的“当前值”。
  - 默认qdisc只影响新建队列；菜单20已有HTB/CAKE时以tc实际root qdisc为准。
EOF_E159_RISKS
}

_e159_network_remove() (
    local confirm="${1:-}" backup key old rc=0 state="$E159_NETWORK_STATE" managed_present=0 p
    if test "$confirm" != force; then
        warn "将移除E159网络层并尽力恢复首次应用前运行值。"
        read -rp "输入 REMOVE-E159-NETWORK 确认: " confirm || true
        test "$confirm" = REMOVE-E159-NETWORK || return 0
    fi
    _e159_prepare || return 1
    exec 154>/run/lock/xray-network-e159.lock
    flock -w 90 154 || { error "另一个E159网络事务/开机复检占用锁超过90秒。"; return 1; }
    test -s "$state" || state="$E159_LEGACY_E156_STATE"
    test -s "$state" || state="$E159_LEGACY_E154_STATE"
    backup=$(sed -n 's/^origin_backup=//p' "$state" 2>/dev/null | tail -n1)
    test -n "$backup" || backup=$(sed -n 's/^backup=//p' "$state" 2>/dev/null | tail -n1)
    for p in "$E159_EFFECTIVE_CONF" "$E159_NETWORK_SERVICE" "$E159_NETWORK_TIMER" \
        "$E159_LEGACY_E156_EFFECTIVE_CONF" "$E159_LEGACY_E156_SERVICE" \
        "$E159_LEGACY_E156_TIMER" \
        "$E159_LEGACY_E154_EFFECTIVE_CONF" "$E159_LEGACY_E154_SERVICE" \
        "$E159_LEGACY_E154_TIMER"; do
        test -e "$p" && managed_present=1 || true
    done
    if test -z "$backup" && test "$managed_present" -eq 1; then
        error "检测到E154/E156/E159网络所有者，但首次基线快照缺失；拒绝伪称已恢复。"
        error "请先保留现场并执行 --full-network-status，确认后再人工处理。"
        return 1
    fi
    systemctl disable --now xray-network-e159.timer xray-network-e159.service \
        xray-network-e156.timer xray-network-e156.service \
        xray-network-e154.timer xray-network-e154.service >/dev/null 2>&1 || true
    if test -n "$backup" && _e159_network_tx_verify "$backup"; then
        _e159_network_restore "$backup" || rc=1
    elif test -n "$backup"; then
        error "E159首次应用前快照不可验证，拒绝声称已恢复：$backup"
        return 1
    fi
    rm -f -- "$E159_EFFECTIVE_CONF" "$E159_REQUESTED_CONF" "$E159_NETWORK_REPORT" \
        "$E159_NETWORK_STATE" "$E159_NETWORK_SEAL" \
        "$E159_NETWORK_SCRIPT" "$E159_NETWORK_SERVICE" "$E159_NETWORK_TIMER" \
        "$E159_MODULES_CONF" "$E159_LEGACY_E154_EFFECTIVE_CONF" \
        "$E159_LEGACY_E156_EFFECTIVE_CONF" "$E159_LEGACY_E156_REQUESTED_CONF" \
        "$E159_LEGACY_E156_REPORT" "$E159_LEGACY_E156_STATE" "$E159_LEGACY_E156_SEAL" \
        "$E159_LEGACY_E156_SCRIPT" "$E159_LEGACY_E156_SERVICE" \
        "$E159_LEGACY_E156_TIMER" "$E159_LEGACY_E156_MODULES_CONF" \
        "$E159_LEGACY_E154_REQUESTED_CONF" "$E159_LEGACY_E154_REPORT" \
        "$E159_LEGACY_E154_STATE" "$E159_LEGACY_E154_SCRIPT" \
        "$E159_LEGACY_E154_SERVICE" "$E159_LEGACY_E154_TIMER" \
        "$E159_LEGACY_E154_MODULES_CONF" 2>/dev/null || true
    systemctl daemon-reload >/dev/null 2>&1 || true
    if test "$rc" -ne 0; then
        error "E159网络层移除后的基线恢复未完整通过；保留快照：$backup"
        return 1
    fi
    info "E159完整网络层已移除，并恢复首次应用前的文件、服务、运行值及ip_forward副作用。"
)

_e159_network_menu() {
    local n qdisc scale app
    while true; do
        clear
        title "V199e159：125个持久控制（127条请求）参数中心"
        echo "  1) 应用完整默认值（fq / adv=1 / app=31）"
        echo "  2) 应用完整参数集并自定义 qdisc / adv_win_scale / app_win"
        echo "  3) 逐项审计请求值、运行值、内核支持与重复定义"
        echo "  4) 显示完整127条请求规格"
        echo "  5) 按当前规格重新事务应用"
        echo "  6) 查看高风险/废弃/no-op参数说明"
        echo "  7) 移除E159网络层并恢复首次应用前运行值"
        echo "  0) 返回"
        read -rp "操作: " n || true
        case "$n" in
            1) _e159_network_apply fq 1 31; _e152_pause ;;
            2)
                read -rp "qdisc [fq/fq_codel/cake，默认fq]: " qdisc || true; qdisc=${qdisc:-fq}
                read -rp "tcp_adv_win_scale [-31~31，默认1]: " scale || true; scale=${scale:-1}
                read -rp "tcp_app_win [0~31，默认31]: " app || true; app=${app:-31}
                _e159_network_apply "$qdisc" "$scale" "$app"; _e152_pause ;;
            3) _e159_network_audit || true; _e152_pause ;;
            4)
                if test -s "$E159_REQUESTED_CONF"; then sed 's/^/    /' "$E159_REQUESTED_CONF"
                else _e159_full_spec fq 1 31 /dev/stdout | sed 's/^/    /'; fi
                _e152_pause ;;
            5)
                qdisc=$(sed -n 's/^qdisc=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1); qdisc=${qdisc:-fq}
                scale=$(sed -n 's/^tcp_adv_win_scale=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1); scale=${scale:-1}
                app=$(sed -n 's/^tcp_app_win=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1); app=${app:-31}
                _e159_network_apply "$qdisc" "$scale" "$app"; _e152_pause ;;
            6) _e159_network_risk_notes; _e152_pause ;;
            7) _e159_network_remove; _e152_pause ;;
            0) return 0 ;;
            *) warn "无效操作。"; sleep 1 ;;
        esac
    done
}

# Converge every still-reachable legacy network entry on the complete E159
# transaction.  No old alias may silently switch back to the narrow E152 file.
_e152_network_menu() { _e159_network_menu; }
_e139_network_menu() { _e159_network_menu; }
_e138_network_menu() { _e159_network_menu; }
_e136_network_menu() { _e159_network_menu; }
do_network_params_menu_e56() { _e159_network_menu; }
