_e159_install_host_safe_impl() {
    local mode="${1:-all}" script service state previous="$E159_HOST_STATE" thp=0 cpu=0
    test -s "$previous" || previous="$E159_LEGACY_E156_HOST_STATE"
    test -s "$previous" || previous="$E159_LEGACY_E154_HOST_STATE"
    case "$mode" in
        all) thp=1; cpu=1 ;;
        thp) thp=1; cpu=$(sed -n 's/^cpu=//p' "$previous" 2>/dev/null | tail -n1); cpu=${cpu:-0} ;;
        cpu) cpu=1; thp=$(sed -n 's/^thp=//p' "$previous" 2>/dev/null | tail -n1); thp=${thp:-0} ;;
        migrate)
            thp=$(sed -n 's/^thp=//p' "$previous" 2>/dev/null | tail -n1); thp=${thp:-0}
            cpu=$(sed -n 's/^cpu=//p' "$previous" 2>/dev/null | tail -n1); cpu=${cpu:-0} ;;
        *) return 1 ;;
    esac
    [[ "$thp" =~ ^[01]$ && "$cpu" =~ ^[01]$ ]] || {
        error "host-safe状态损坏：thp=$thp cpu=$cpu"; return 1;
    }
    script=$(_e118_mktemp e159-host-safe.sh) || return 1
    service=$(_e118_mktemp e159-host-safe.service) || return 1
    state=$(_e118_mktemp e159-host-safe.env) || return 1
    printf 'thp=%s\ncpu=%s\n' "$thp" "$cpu" >"$state" || return 1
    cat >"$script" <<'EOF_E159_HOST'
#!/usr/bin/env bash
set -u
STATE=/usr/local/etc/xray/e159/host-safe.env
thp=$(sed -n 's/^thp=//p' "$STATE" 2>/dev/null | tail -n1); thp=${thp:-0}
cpu=$(sed -n 's/^cpu=//p' "$STATE" 2>/dev/null | tail -n1); cpu=${cpu:-0}
if test "$thp" = 1; then
    for f in /sys/kernel/mm/transparent_hugepage/enabled /sys/kernel/mm/transparent_hugepage/defrag; do
        test -w "$f" && printf 'never\n' >"$f" 2>/dev/null || true
    done
fi
if test "$cpu" = 1; then
    for f in /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor; do
        test -w "$f" && printf 'performance\n' >"$f" 2>/dev/null || true
    done
fi
exit 0
EOF_E159_HOST
    cat >"$service" <<EOF_E159_HOST_SERVICE
[Unit]
Description=V199e159 host-only THP and CPU policy (no network ownership)
After=local-fs.target
Before=xray.service

[Service]
Type=oneshot
ExecStart=$E159_HOST_SCRIPT
RemainAfterExit=yes

[Install]
WantedBy=multi-user.target
EOF_E159_HOST_SERVICE
    bash -n "$script" || return 1
    _e121_atomic_install "$state" "$E159_HOST_STATE" 0600 || return 1
    _e121_atomic_install "$script" "$E159_HOST_SCRIPT" 0755 || return 1
    _e121_atomic_install "$service" "$E159_HOST_SERVICE" 0644 || return 1
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    systemctl enable xray-host-safe-e159.service >/dev/null 2>&1 || return 1
    systemctl restart xray-host-safe-e159.service >/dev/null 2>&1 || return 1
    systemctl is-enabled --quiet xray-host-safe-e159.service 2>/dev/null || return 1
    systemctl is-active --quiet xray-host-safe-e159.service 2>/dev/null || return 1
    systemctl disable --now xray-host-safe-e156.service xray-host-safe-e154.service >/dev/null 2>&1 || true
    rm -f -- "$E159_LEGACY_E156_HOST_SCRIPT" "$E159_LEGACY_E156_HOST_SERVICE" \
        "$E159_LEGACY_E156_HOST_STATE" \
        "$E159_LEGACY_E154_HOST_SCRIPT" "$E159_LEGACY_E154_HOST_SERVICE" \
        "$E159_LEGACY_E154_HOST_STATE" 2>/dev/null || return 1
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    for unit in xray-host-safe-e156.service xray-host-safe-e154.service; do
        systemctl is-enabled --quiet "$unit" 2>/dev/null && return 1 || true
        systemctl is-active --quiet "$unit" 2>/dev/null && return 1 || true
    done
}

# Host-only persistence is a small independent transaction as well: a failed
# unit install/restart must not leave half-written E159 files or disable the
# working E154 predecessor.  The snapshot also makes direct menu 13/15 calls
# as safe as the larger hot-update transaction.
_e159_install_host_safe() (
    local mode="${1:-all}" tx p id unit enabled active failed=0 rollback=0
    local -a paths=(
        "$E159_HOST_STATE" "$E159_HOST_SCRIPT" "$E159_HOST_SERVICE"
        "$E159_LEGACY_E156_HOST_STATE" "$E159_LEGACY_E156_HOST_SCRIPT"
        "$E159_LEGACY_E156_HOST_SERVICE"
        "$E159_LEGACY_E154_HOST_STATE" "$E159_LEGACY_E154_HOST_SCRIPT"
        "$E159_LEGACY_E154_HOST_SERVICE"
    )
    _e159_prepare || return 1
    tx=$(_e159_new_tx host-safe) || return 1
    install -d -m 0700 "$tx/host-files" || return 1
    for p in "${paths[@]}"; do
        id=$(printf '%s' "$p" | sha256sum | awk '{print $1}')
        printf '%s|%s\n' "$p" "$id" >>"$tx/host-paths.tsv" || return 1
        _e135_snapshot_file "$p" "$tx/host-files/$id" || return 1
    done
    {
        _e159_snapshot_service xray-host-safe-e159.service
        _e159_snapshot_service xray-host-safe-e156.service
        _e159_snapshot_service xray-host-safe-e154.service
    } >"$tx/host-services.before" || return 1
    (cd "$tx" && find host-files host-paths.tsv host-services.before -type f -print0 \
        | sort -z | xargs -0 sha256sum >host-seal.sha256) || return 1

    _e159_install_host_safe_impl "$mode" || failed=1
    if test "$failed" -eq 0; then
        _e159_prune_system_tx "$tx"
        return 0
    fi

    error "E159 host-safe安装失败，恢复E159/E154文件与服务状态。"
    (cd "$tx" && sha256sum -c host-seal.sha256 >/dev/null 2>&1) || {
        error "host-safe回滚快照校验失败：$tx"; return 1;
    }
    systemctl disable --now xray-host-safe-e159.service >/dev/null 2>&1 || true
    while IFS='|' read -r p id; do
        _e135_restore_file "$p" "$tx/host-files/$id" || rollback=1
    done <"$tx/host-paths.tsv"
    systemctl daemon-reload >/dev/null 2>&1 || rollback=1
    while IFS='|' read -r unit enabled active; do
        _e159_restore_service "$unit" "$enabled" "$active" || rollback=1
    done <"$tx/host-services.before"
    test "$rollback" -eq 0 || error "host-safe回滚未完整通过：$tx"
    return 1
)

_e159_migrate_host_safe() {
    local old_enabled
    if test -s "$E159_LEGACY_E156_HOST_STATE"; then
        _e159_install_host_safe migrate
        return
    fi
    if test -s "$E159_LEGACY_E154_HOST_STATE"; then
        _e159_install_host_safe migrate
        return
    fi
    old_enabled="$(systemctl is-enabled xray-host-safe-e156.service 2>/dev/null || true) \
$(systemctl is-enabled xray-host-safe-e154.service 2>/dev/null || true)"
    if test -e "$E159_LEGACY_E156_HOST_SCRIPT" \
        || test -e "$E159_LEGACY_E156_HOST_SERVICE" \
        || test -e "$E159_LEGACY_E154_HOST_SCRIPT" \
        || test -e "$E159_LEGACY_E154_HOST_SERVICE" \
        || [[ "$old_enabled" =~ (enabled|enabled-runtime|linked|linked-runtime) ]]; then
        warn "旧E154/E156 host-safe缺少可验证状态；停用孤立单元，不猜测THP/CPU策略。"
        systemctl disable --now xray-host-safe-e156.service xray-host-safe-e154.service >/dev/null 2>&1 || true
        rm -f -- "$E159_LEGACY_E156_HOST_SCRIPT" "$E159_LEGACY_E156_HOST_SERVICE" \
            "$E159_LEGACY_E154_HOST_SCRIPT" "$E159_LEGACY_E154_HOST_SERVICE" 2>/dev/null || return 1
        systemctl daemon-reload >/dev/null 2>&1 || return 1
    fi
}

# Native nftables/Fail2ban E159 correction.  Use a new transaction-owned table
# to avoid stale E152 collisions, then verify the running action definition,
# Fail2ban's in-memory ticket, and the actual nft set element independently.
if declare -F _e152_choose_banaction_for_backend >/dev/null 2>&1; then
    eval "$(declare -f _e152_choose_banaction_for_backend | sed '1s/_e152_choose_banaction_for_backend/_e159_choose_banaction_base/')"
fi
_e152_choose_banaction_for_backend() {
    local backend="$1" action_dir="${2:-/etc/fail2ban/action.d}"
    if test "$backend" = nft; then
        if test -f "$action_dir/nftables.conf"; then
            printf 'nftables[type=multiport,table=%s,table_family=inet,chain=%s,chain_hook=input,chain_priority=-1,blocktype=reject,actionstart_on_demand=false]\n' \
                "$E159_NFT_F2B_TABLE" "$E159_NFT_F2B_CHAIN"
            return 0
        fi
        test -f "$action_dir/nftables-multiport.conf" && return 2
        return 1
    fi
    _e159_choose_banaction_base "$backend" "$action_dir"
}

_e121_select_banaction() {
    local backend action action_rc=0
    E121_F2B_BANACTION=""; E121_F2B_EAGER_ACTION=0
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    action=$(_e152_choose_banaction_for_backend "$backend" /etc/fail2ban/action.d 2>/dev/null) || action_rc=$?
    test -n "$action" || {
        if test "$backend" = nft && test "$action_rc" -eq 2; then
            error "缺少统一nftables.conf；现有旧包装器不能提供E159可验证契约。"
        else
            error "后端=$backend，但没有匹配且可验证的Fail2ban action。"
        fi
        return 1
    }
    E152_F2B_BACKEND_KIND="$backend"
    E121_F2B_BANACTION="$action"
    case "$action" in
        nftables*)
            E121_F2B_EAGER_ACTION=1
            info "原生nftables：使用事务表 $E159_NFT_F2B_TABLE，并执行动作/票据/nft集合三重验证。" ;;
        iptables-multiport)
            E121_F2B_EAGER_ACTION=1
            info "iptables：使用立即创建的multiport封禁链。" ;;
    esac
}

# Build the managed jail without nesting a parameterized `banaction` inside
# Fail2Ban's default `action_`.  In 1.0.2 the default action appends another
# option group containing chain="%(chain)s"; E156 did not set the jail chain,
# so that later empty value could override f2b-e152-input/f2b-e159-input.  The
# native nft action is now explicit and therefore has one unambiguous owner for
# table, chain, hook, priority, port and protocol.
_e159_f2b_jail_action_lines() {
    local backend="$1" csv="$2"
    [[ "$csv" =~ ^[0-9]+(,[0-9]+)*$ ]] || return 1
    case "$backend" in
        nft)
            test -n "$E121_F2B_BANACTION" || return 1
            echo "banaction = nftables"
            printf 'action = %s[name=%s,port="%s",protocol="tcp"]\n' \
                "$E121_F2B_BANACTION" "$E121_F2B_JAIL_NAME" "$csv"
            ;;
        iptables)
            echo "chain = INPUT"
            test -z "$E121_F2B_BANACTION" || echo "banaction = $E121_F2B_BANACTION"
            ;;
        *) test -z "$E121_F2B_BANACTION" || echo "banaction = $E121_F2B_BANACTION" ;;
    esac
}

_e121_write_fail2ban_candidates() {
    local ports csv jail_tmp db_tmp filter_tmp ignore backend
    ports=$(_e116_detect_ssh_ports)
    test -n "$ports" || ports=22
    csv=$(printf '%s\n' $ports | paste -sd, -)
    [[ "$csv" =~ ^[0-9]+(,[0-9]+)*$ ]] || { error "SSH端口列表非法：$csv"; return 1; }
    ignore=$(_e152_collect_ignoreip "${E152_CURRENT_SSH_IP:-}")
    backend=${E152_F2B_BACKEND_KIND:-$(_e152_firewall_backend 2>/dev/null || echo none)}

    mkdir -p /etc/fail2ban/jail.d /etc/fail2ban/fail2ban.d \
        /etc/fail2ban/filter.d /var/lib/fail2ban || return 1
    jail_tmp=$(_e118_mktemp fail2ban-e159-jail) || return 1
    db_tmp=$(_e118_mktemp fail2ban-e159-db) || return 1
    filter_tmp=$(_e118_mktemp fail2ban-e159-filter) || return 1

    cat >"$filter_tmp" <<'EOF_E159_F2B_FILTER'
[INCLUDES]
before = common.conf

[Definition]
_daemon = sshd(?:-session)?
failregex = ^%(__prefix_line)sFailed password for (?:invalid user )?.*? from <HOST>(?: port \d+)?(?: ssh\d*)?(?: \[preauth\])?\s*$
            ^%(__prefix_line)sFailed keyboard-interactive/pam for (?:invalid user )?.*? from <HOST>(?: port \d+)?(?: ssh\d*)?(?: \[preauth\])?\s*$
ignoreregex =
journalmatch = _SYSTEMD_UNIT=sshd.service + _COMM=sshd + _COMM=sshd-session
EOF_E159_F2B_FILTER

    cat >"$db_tmp" <<'EOF_E159_F2B_DB'
[Definition]
allowipv6 = auto
dbfile = /var/lib/fail2ban/fail2ban.sqlite3
dbpurgeage = 3d
logtarget = /var/log/xray-fail2ban.log
loglevel = INFO
EOF_E159_F2B_DB

    {
        echo "[$E121_F2B_JAIL_NAME]"
        echo "enabled = true"
        echo "filter = xray-sshd-password-e152"
        echo "backend = $E121_F2B_BACKEND"
        test "$E121_F2B_BACKEND" = systemd || echo "logpath = $E121_F2B_LOGPATH"
        echo "port = $csv"
        echo "protocol = tcp"
        echo "usedns = no"
        test -z "$ignore" || echo "ignoreip = $ignore"
        _e159_f2b_jail_action_lines "$backend" "$csv" || return 1
        echo "maxretry = 2"
        echo "findtime = 86400"
        echo "bantime = 129600"
    } >"$jail_tmp" || return 1

    _e121_atomic_install "$filter_tmp" "$E152_F2B_FILTER" 0644 || return 1
    _e121_atomic_install "$db_tmp" "$E121_F2B_DB_CONF" 0644 || return 1
    _e121_atomic_install "$jail_tmp" "$E121_F2B_JAIL" 0644 || return 1
}

_e159_f2b_action_names() {
    local raw
    raw=$(fail2ban-client get "$E121_F2B_JAIL_NAME" actions 2>/dev/null || true)
    # Fail2Ban 1.0.2 beautifies this as a heading followed by a comma-separated
    # last line.  Restrict parsing to that last non-empty line so words from the
    # heading can never be mistaken for action names.
    raw=$(printf '%s\n' "$raw" | awk 'NF{line=$0} END{print line}')
    printf '%s\n' "$raw" | tr "[],'\"" '     ' | tr '[:space:]' '\n' \
        | grep -E '^[A-Za-z0-9_.:-]+$' | awk 'NF&&!seen[$0]++' || true
}

_e159_f2b_action_property() {
    local name="$1" property="$2"
    fail2ban-client get "$E121_F2B_JAIL_NAME" action "$name" "$property" 2>/dev/null
}

_e159_f2b_action_values_valid() {
    local table="$1" family="$2" chain="$3" hook="$4" priority="$5"
    local demand="$6" type="$7" blocktype="$8" port="$9" protocol="${10}"
    local expected_ports="${11}" start="${12}" ban="${13}" unban="${14}"
    test "$table" = "$E159_NFT_F2B_TABLE" || return 1
    test "$family" = inet || return 1
    test "$chain" = "$E159_NFT_F2B_CHAIN" || return 1
    test "$hook" = input || return 1
    test "$priority" = -1 || return 1
    test "$type" = multiport || return 1
    test "$blocktype" = reject || return 1
    test "$protocol" = tcp || return 1
    test "${port//[[:space:]]/}" = "${expected_ports//[[:space:]]/}" || return 1
    case "${demand,,}" in 0|false|no|off) ;; *) return 1 ;; esac
    [[ "$start" == *"add table"* && "$start" == *"add chain"* ]] || return 1
    [[ "$ban" == *"add element"* ]] || return 1
    [[ "$unban" == *"delete element"* ]] || return 1
}

_e159_f2b_action_contract() {
    local name start ban unban table family chain hook priority demand type blocktype port protocol expected_ports
    E159_F2B_ACTION_NAME=""; E159_F2B_ACTIONBAN=""; E159_F2B_ACTIONUNBAN=""
    while IFS= read -r name; do
        test -n "$name" || continue
        table=$(_e159_f2b_action_property "$name" table | tail -n1 | xargs || true)
        family=$(_e159_f2b_action_property "$name" table_family | tail -n1 | xargs || true)
        chain=$(_e159_f2b_action_property "$name" chain | tail -n1 | xargs || true)
        hook=$(_e159_f2b_action_property "$name" chain_hook | tail -n1 | xargs || true)
        priority=$(_e159_f2b_action_property "$name" chain_priority | tail -n1 | xargs || true)
        demand=$(_e159_f2b_action_property "$name" actionstart_on_demand | tail -n1 | xargs || true)
        type=$(_e159_f2b_action_property "$name" type | tail -n1 | xargs || true)
        blocktype=$(_e159_f2b_action_property "$name" blocktype | tail -n1 | xargs || true)
        port=$(_e159_f2b_action_property "$name" port | tail -n1 | xargs || true)
        protocol=$(_e159_f2b_action_property "$name" protocol | tail -n1 | xargs || true)
        expected_ports=$(_e116_detect_ssh_ports | paste -sd, -); expected_ports=${expected_ports:-22}
        start=$(_e159_f2b_action_property "$name" actionstart \
            | tr '\n\t' '  ' | sed 's/[[:space:]][[:space:]]*/ /g' || true)
        ban=$(_e159_f2b_action_property "$name" actionban \
            | tr '\n\t' '  ' | sed 's/[[:space:]][[:space:]]*/ /g' || true)
        unban=$(_e159_f2b_action_property "$name" actionunban \
            | tr '\n\t' '  ' | sed 's/[[:space:]][[:space:]]*/ /g' || true)

        _e159_f2b_action_values_valid "$table" "$family" "$chain" "$hook" \
            "$priority" "$demand" "$type" "$blocktype" "$port" "$protocol" \
            "$expected_ports" "$start" "$ban" "$unban" || continue
        E159_F2B_ACTION_NAME="$name"
        E159_F2B_ACTIONBAN="$ban"
        E159_F2B_ACTIONUNBAN="$unban"
        return 0
    done < <(_e159_f2b_action_names)
    return 1
}

_e159_nft_table_contract() {
    local json
    command -v nft >/dev/null 2>&1 || return 1
    nft list table inet "$E159_NFT_F2B_TABLE" >/dev/null 2>&1 || return 1
    if command -v jq >/dev/null 2>&1 \
      && json=$(nft -j list table inet "$E159_NFT_F2B_TABLE" 2>/dev/null); then
        jq -e --arg c "$E159_NFT_F2B_CHAIN" '
          ([.nftables[]? | .chain? | select(.name==$c and .hook=="input" and ((.prio|tostring)=="-1"))] | length)==1
          and ([.. | strings | select(test("^@addr(6)?-set-"))] | length)>0
          and ([.. | objects | select(has("reject"))] | length)>0
        ' <<<"$json" >/dev/null 2>&1
        return $?
    fi
    nft -a list table inet "$E159_NFT_F2B_TABLE" 2>/dev/null \
      | grep -Eq "chain[[:space:]]+$E159_NFT_F2B_CHAIN|chain[[:space:]]+\"$E159_NFT_F2B_CHAIN\"" || return 1
    nft -a list table inet "$E159_NFT_F2B_TABLE" 2>/dev/null | grep -q 'hook input priority -1' || return 1
    nft -a list table inet "$E159_NFT_F2B_TABLE" 2>/dev/null | grep -Eq '@addr6?-set-' || return 1
    nft -a list table inet "$E159_NFT_F2B_TABLE" 2>/dev/null | grep -qw reject
}

_e159_nft_has_element() {
    local ip="$1" json
    if command -v jq >/dev/null 2>&1 \
      && json=$(nft -j list table inet "$E159_NFT_F2B_TABLE" 2>/dev/null); then
        jq -e --arg ip "$ip" '[.. | strings | select(.==$ip)] | length>0' \
            <<<"$json" >/dev/null 2>&1
        return $?
    fi
    nft list table inet "$E159_NFT_F2B_TABLE" 2>/dev/null \
        | tr '{},' '   ' | tr '[:space:]' '\n' | grep -Fxq -- "$ip"
}

_e159_f2b_banned_state() {
    local ip="$1" expected="$2" out token found=0
    out=$(fail2ban-client get "$E121_F2B_JAIL_NAME" banned "$ip" 2>/dev/null | tail -n1 | xargs || true)
    case "$out" in
        0|1) test "$out" = "$expected"; return $? ;;
    esac

    # Fail2Ban 1.x exposes `get <jail> banned <ip>`.  Older supported builds
    # may only expose the complete banip list, so compare exact tokens rather
    # than treating a failed query as "not banned".
    out=$(fail2ban-client get "$E121_F2B_JAIL_NAME" banip 2>/dev/null) || return 1
    for token in $out; do
        if test "$token" = "$ip"; then found=1; break; fi
    done
    test "$found" -eq "$expected"
}

_e159_f2b_diag() {
    local result="${1:-unknown}" detail="${2:-}" test_ip="${3:-none}" name property value
    install -d -m 0700 "$(dirname "$E159_F2B_NFT_DIAG")" 2>/dev/null || return 0
    {
        echo "time=$(date -Is 2>/dev/null || date)"
        echo "result=$result"
        echo "detail=$detail"
        echo "test_ip=$test_ip"
        echo "jail=$E121_F2B_JAIL_NAME"
        echo "expected_table=inet/$E159_NFT_F2B_TABLE"
        echo "expected_chain=$E159_NFT_F2B_CHAIN"
        echo "actions=$(fail2ban-client get "$E121_F2B_JAIL_NAME" actions 2>/dev/null || true)"
        while IFS= read -r name; do
            test -n "$name" || continue
            for property in table table_family chain chain_hook chain_priority type \
                blocktype port protocol actionstart_on_demand; do
                value=$(_e159_f2b_action_property "$name" "$property" 2>&1 || true)
                printf '%s=%s\n' "$property" "$value"
            done
            echo "--- action=$name actionstart"
            fail2ban-client get "$E121_F2B_JAIL_NAME" action "$name" actionstart 2>&1 || true
            echo "--- action=$name actionban"
            fail2ban-client get "$E121_F2B_JAIL_NAME" action "$name" actionban 2>&1 || true
            echo "--- action=$name actionunban"
            fail2ban-client get "$E121_F2B_JAIL_NAME" action "$name" actionunban 2>&1 || true
        done < <(_e159_f2b_action_names)
        echo "--- expected nft table"
        nft -a list table inet "$E159_NFT_F2B_TABLE" 2>&1 || true
        echo "--- f2b nft tables"
        nft list tables 2>&1 | grep -E '(^|[[:space:]])f2b' || true
        echo "--- fail2ban journal tail"
        journalctl -u fail2ban.service --no-pager -n 100 2>&1 || true
        echo "--- fail2ban file tail"
        tail -n 100 /var/log/xray-fail2ban.log 2>&1 || true
    } >"$E159_F2B_NFT_DIAG" 2>&1
    chmod 0600 "$E159_F2B_NFT_DIAG" 2>/dev/null || true
}

_e159_f2b_test_family() {
    local family="$1" current="${E152_CURRENT_SSH_IP:-}" candidate test_ip="" i
    local plane1=0 plane2=0 cleanup_ok=0
    local -a candidates4=(192.0.2.158 198.51.100.158 203.0.113.158 192.0.2.159 198.51.100.159 203.0.113.159)
    local -a candidates6=(2001:db8:158::1 2001:db8:158::2 2001:db8:159::1)
    local -a candidates=()
    case "$family" in inet4) candidates=("${candidates4[@]}") ;; inet6) candidates=("${candidates6[@]}") ;; *) return 1 ;; esac

    for candidate in "${candidates[@]}"; do
        test "$candidate" = "$current" && continue
        fail2ban-client set "$E121_F2B_JAIL_NAME" unbanip --report-absent "$candidate" >/dev/null 2>&1 || true
        for i in {1..12}; do
            _e159_f2b_banned_state "$candidate" 0 && ! _e159_nft_has_element "$candidate" && break
            sleep 0.25
        done
        _e159_f2b_banned_state "$candidate" 0 && ! _e159_nft_has_element "$candidate" || continue
        if ! fail2ban-client set "$E121_F2B_JAIL_NAME" banip "$candidate" >/dev/null 2>&1; then
            # A server-side action may have inserted the ticket before the
            # client reports failure.  Never abandon a synthetic test ticket.
            fail2ban-client set "$E121_F2B_JAIL_NAME" unbanip --report-absent "$candidate" \
                >/dev/null 2>&1 || true
            continue
        fi
        for i in {1..40}; do
            if _e159_f2b_banned_state "$candidate" 1; then plane1=1; break; fi
            sleep 0.25
        done
        if test "$plane1" -eq 1; then test_ip="$candidate"; break; fi
        fail2ban-client set "$E121_F2B_JAIL_NAME" unbanip --report-absent "$candidate" >/dev/null 2>&1 || true
    done
    test -n "$test_ip" || {
        _e159_f2b_diag fail "$family:no-test-address-entered-fail2ban-plane" none
        return 1
    }
    for i in {1..40}; do
        if _e159_nft_has_element "$test_ip"; then plane2=1; break; fi
        sleep 0.25
    done
    fail2ban-client set "$E121_F2B_JAIL_NAME" unbanip --report-absent "$test_ip" >/dev/null 2>&1 || true
    for i in {1..40}; do
        if _e159_f2b_banned_state "$test_ip" 0 && ! _e159_nft_has_element "$test_ip"; then
            cleanup_ok=1; break
        fi
        sleep 0.25
    done
    if test "$plane2" -ne 1 || test "$cleanup_ok" -ne 1; then
        _e159_f2b_diag fail "$family:plane1=$plane1,plane2=$plane2,cleanup=$cleanup_ok" "$test_ip"
        return 1
    fi
    _e159_f2b_diag pass "$family:plane1=1,plane2=1,cleanup=1" "$test_ip"
}

_e159_ipv6_ssh_relevant() {
    command -v ip >/dev/null 2>&1 || return 1
    ip -6 addr show scope global 2>/dev/null | grep -q 'inet6 ' || return 1
    command -v sshd >/dev/null 2>&1 || return 1
    case "$(sshd -T 2>/dev/null | awk '/^addressfamily /{print $2;exit}')" in inet) return 1 ;; esac
    return 0
}

_e152_verify_nft_fail2ban_action() {
    _e159_f2b_action_contract || {
        _e159_f2b_diag fail running-action-does-not-target-e159 none
        error "Fail2ban运行action与E159专用表契约不一致；诊断：$E159_F2B_NFT_DIAG"
        return 1
    }
    _e159_nft_table_contract || {
        _e159_f2b_diag fail nft-base-chain-contract-failed none
        error "E159 nftables表/输入hook/terminal-reject/集合规则不完整；诊断：$E159_F2B_NFT_DIAG"
        return 1
    }
    _e159_f2b_test_family inet4 || {
        error "Fail2ban IPv4票据与nft集合双平面验证失败；诊断：$E159_F2B_NFT_DIAG"
        return 1
    }
    if _e159_ipv6_ssh_relevant; then
        _e159_f2b_test_family inet6 || {
            error "本机SSH暴露IPv6，但Fail2ban IPv6双平面验证失败；诊断：$E159_F2B_NFT_DIAG"
            return 1
        }
    fi
    return 0
}

_e152_fail2ban_passive_verify() {
    local backend
    systemctl is-enabled --quiet fail2ban.service 2>/dev/null || return 1
    systemctl is-active --quiet fail2ban.service 2>/dev/null || return 1
    _e152_fail2ban_numeric_verify || return 1
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    case "$backend" in
        nft) _e159_f2b_action_contract && _e159_nft_table_contract ;;
        iptables)
            fail2ban-client get "$E121_F2B_JAIL_NAME" actions 2>/dev/null | grep -qi iptables ;;
        ufw|firewalld)
            test -n "$(fail2ban-client get "$E121_F2B_JAIL_NAME" actions 2>/dev/null || true)" ;;
        *) return 1 ;;
    esac
}

# Extend the existing native-nft rollback boundary to both generations of the
# script-owned table.  A failed re-run can therefore neither leak f2b-e159 nor
# destroy the previously working f2b-e152 ruleset.
_e152_nft_ssh_tx_begin() {
    local tx p key table label
    tx=$(_e152_new_tx ssh-native-e159) || return 1
    install -d -m 0700 "$tx/files" || return 1
    : >"$tx/files.manifest" || return 1
    while IFS= read -r p; do
        test -n "$p" || continue
        key=$(printf '%s' "$p" | sha256sum | awk '{print $1}')
        printf '%s|%s\n' "$p" "$key" >>"$tx/files.manifest" || return 1
        _e135_snapshot_file "$p" "$tx/files/$key" || return 1
    done < <(_e121_managed_fail2ban_paths | awk 'NF&&!seen[$0]++')
    : >"$tx/services.env" || return 1
    for p in fail2ban.service xray-ssh-port-guard-e121.service xray-ssh-port-guard-e121.timer \
        xray-ssh-native-e152.service xray-ssh-native-e152.timer \
        xray-ssh-auth-audit-e152.service xray-ssh-auth-audit-e152.timer rsyslog.service; do
        _e152_unit_state_line "$p" >>"$tx/services.env" || return 1
    done
    for table in "$E152_NFT_F2B_TABLE" "$E159_NFT_F2B_TABLE"; do
        label=$(printf '%s' "$table" | tr -c 'A-Za-z0-9_.-' '_')
        if command -v nft >/dev/null 2>&1 \
          && nft list table inet "$table" >"$tx/$label.nft" 2>/dev/null; then
            : >"$tx/$label.present"
        else
            : >"$tx/$label.absent"
        fi
    done
    (cd "$tx" && find . -type f ! -name ssh-seal.sha256 ! -name COMMITTED \
        -print0 | sort -z | xargs -0 sha256sum >ssh-seal.sha256) || return 1
    test -s "$tx/ssh-seal.sha256" || return 1
    printf '%s\n' "$tx"
}

_e152_nft_ssh_tx_rollback() {
    local tx="$1" p key unit enabled active table label rc=0
    test -d "$tx" && test -s "$tx/files.manifest" && test -s "$tx/services.env" \
        && test -s "$tx/ssh-seal.sha256" \
        && (cd "$tx" && sha256sum -c ssh-seal.sha256 >/dev/null 2>&1) || return 1
    systemctl stop xray-ssh-native-e152.timer xray-ssh-native-e152.service \
        xray-ssh-auth-audit-e152.timer xray-ssh-auth-audit-e152.service \
        fail2ban.service >/dev/null 2>&1 || true
    for table in "$E152_NFT_F2B_TABLE" "$E159_NFT_F2B_TABLE"; do
        nft delete table inet "$table" >/dev/null 2>&1 || true
    done
    while IFS='|' read -r p key; do
        test -n "$p" && test -n "$key" || continue
        _e135_restore_file "$p" "$tx/files/$key" || rc=1
    done <"$tx/files.manifest"
    systemctl daemon-reload >/dev/null 2>&1 || rc=1
    while IFS='|' read -r unit enabled active; do
        test -n "$unit" || continue
        if test "$enabled" = 1; then systemctl enable "$unit" >/dev/null 2>&1 || rc=1
        else systemctl disable "$unit" >/dev/null 2>&1 || true; fi
    done <"$tx/services.env"
    while IFS='|' read -r unit enabled active; do
        test -n "$unit" || continue
        if test "$active" = 1; then
            if test "$unit" = fail2ban.service; then systemctl restart "$unit" >/dev/null 2>&1 || rc=1
            else systemctl start "$unit" >/dev/null 2>&1 || rc=1; fi
        else systemctl stop "$unit" >/dev/null 2>&1 || true; fi
    done <"$tx/services.env"
    if ! systemctl is-active --quiet fail2ban.service 2>/dev/null; then
        for table in "$E152_NFT_F2B_TABLE" "$E159_NFT_F2B_TABLE"; do
            label=$(printf '%s' "$table" | tr -c 'A-Za-z0-9_.-' '_')
            if test -e "$tx/$label.present" && test -s "$tx/$label.nft"; then
                nft -f "$tx/$label.nft" >/dev/null 2>&1 || rc=1
            fi
        done
    fi
    return "$rc"
}

_e152_nft_ssh_tx_commit() {
    local tx="$1"
    test -d "$tx" && test -s "$tx/ssh-seal.sha256" \
        && (cd "$tx" && sha256sum -c ssh-seal.sha256 >/dev/null 2>&1) || return 1
    {
        echo "committed=$(date -Is 2>/dev/null || date)"
        echo "version=$SCRIPT_VERSION"
    } >"$tx/COMMITTED" || return 1
    chmod 0600 "$tx/COMMITTED" || return 1
}

if declare -F _e121_install_fail2ban_guard >/dev/null 2>&1; then
    eval "$(declare -f _e121_install_fail2ban_guard | sed '1s/_e121_install_fail2ban_guard/_e159_fail2ban_guard_base/')"
fi
_e121_install_fail2ban_guard() {
    local backend
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    if test "$backend" = nft; then
        # Stop the old action before removing only the new script-owned table.
        # This repairs an interrupted prior E159 run without deleting user nft
        # policy.  The outer SSH transaction has already snapshotted both tables.
        systemctl stop fail2ban.service >/dev/null 2>&1 || true
        systemctl is-active --quiet fail2ban.service 2>/dev/null && {
            error "无法停止Fail2ban以清理E159残留事务表。"; return 1;
        }
        nft delete table inet "$E159_NFT_F2B_TABLE" >/dev/null 2>&1 || true
        nft list table inet "$E159_NFT_F2B_TABLE" >/dev/null 2>&1 && {
            error "无法清理残留的$E159_NFT_F2B_TABLE。"; return 1;
        } || true
    fi
    _e159_fail2ban_guard_base || return 1
    if test "$backend" = nft; then
        # The inherited installer has just completed the live ticket/set test.
        # Recheck the static runtime contract before retiring the old table,
        # without performing a redundant second ban cycle here.
        _e159_f2b_action_contract && _e159_nft_table_contract || return 1
        # f2b-e152 is an older script-owned name.  Remove it only after the new
        # action has passed both planes; rollback can restore its exact snapshot.
        nft delete table inet "$E152_NFT_F2B_TABLE" >/dev/null 2>&1 || true
        nft list table inet "$E152_NFT_F2B_TABLE" >/dev/null 2>&1 && {
            error "旧$E152_NFT_F2B_TABLE仍残留，拒绝留下双重SSH封禁所有者。"; return 1;
        } || true
    fi
}

# Serialize menu, hot-update and periodic authentication reconciliation.  E156
# stopped Fail2Ban briefly while the 15-minute audit could launch the same
# installer concurrently, producing stale tables or rollback races.
if declare -F _e141_install_ssh_guard >/dev/null 2>&1; then
    eval "$(declare -f _e141_install_ssh_guard | sed '1s/_e141_install_ssh_guard/_e159_ssh_guard_install_base/')"
fi
_e141_install_ssh_guard() {
    local lock_fd rc=0
    _e214_ensure_run_lock || return 1
    exec {lock_fd}>/run/lock/xray-ssh-guard-e159.lock || return 1
    if ! flock -w 540 "$lock_fd"; then
        exec {lock_fd}>&-
        error "SSH/Fail2ban事务锁等待超过540秒。"
        return 1
    fi
    if _e159_ssh_guard_install_base "$@"; then rc=0; else rc=$?; fi
    flock -u "$lock_fd" >/dev/null 2>&1 || true
    exec {lock_fd}>&-
    return "$rc"
}

_e159_ssh_guard_verify_final() {
    local profile mode backend
    profile=$(_e141_sshd_auth_profile 2>/dev/null || true)
    mode=$(sed -n 's/^mode=//p' <<<"$profile" | head -n1)
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    case "$backend:$mode" in
        nft:password-capable)
            _e152_fail2ban_passive_verify && _e152_nft_ssh_check ;;
        nft:key-only|nft:non-password|nft:ambiguous)
            _e152_nft_ssh_check ;;
        *:password-capable)
            _e152_fail2ban_passive_verify && _e121_verify_ssh_port_guard ;;
        *:key-only|*:non-password|*:ambiguous)
            _e142_verify_key_only_guard ;;
        *) return 1 ;;
    esac
}

# Tighten the Xray commit primitive.  The inherited E127 implementation called
# fix_permissions without checking its return value; because many callers use
# the function in an if/|| list, Bash errexit cannot be relied upon and a later
# successful command could mask an unusable config permission state.
_e118_commit_config() {
    local candidate="$1" bdir="${2:-}" start_policy="${3:-preserve}"
    local stage was_active=0 rollback_ok=0
    case "$start_policy" in preserve|start) ;; *) error "未知Xray启动策略：$start_policy"; return 1 ;; esac
    _e118_xray_test_config "$candidate" 1 || return 1
    if test -z "$bdir"; then
        bdir=$(_e116_backup_state before_config_commit_e159) || return 1
    fi
    _e127_verify_state_snapshot "$bdir" || return 1
    was_active=$(sed -n 's/^xray_was_active=//p' "$bdir/meta.env" 2>/dev/null | head -n1)
    was_active=${was_active:-0}
    [[ "$was_active" =~ ^[01]$ ]] || { error "Xray快照启停状态损坏。"; return 1; }
    E118_TX_ACTIVE=1; E118_TX_BACKUP="$bdir"; E118_TX_WAS_ACTIVE="$was_active"
    stage="$CONFIG_DIR/.config.e159.$$"
    if ! install -m 0600 "$candidate" "$stage" || ! mv -f -- "$stage" "$CONFIG"; then
        rm -f -- "$stage" 2>/dev/null || true
        E118_TX_ACTIVE=0; E118_TX_BACKUP=""; E118_TX_WAS_ACTIVE=0
        return 1
    fi
    if ! fix_permissions; then
        error "Xray配置权限收敛失败，正在恢复旧状态。"
        _e127_rollback_config_or_emergency "$bdir" && rollback_ok=1 || rollback_ok=0
        test "$rollback_ok" -eq 1 || error "严重：权限失败后的Xray旧状态恢复失败：$bdir"
        return 1
    fi
    if test "$was_active" = 1; then
        if ! systemctl restart xray.service >/dev/null 2>&1 \
          || ! _e127_verify_xray_runtime "$CONFIG" 12; then
            error "新配置运行态探针失败，正在恢复旧配置。"
            _e127_rollback_config_or_emergency "$bdir" && rollback_ok=1 || rollback_ok=0
            test "$rollback_ok" -eq 1 || error "严重：旧配置自动恢复失败，快照：$bdir"
            return 1
        fi
    elif test "$start_policy" = start; then
        if ! systemctl enable xray.service >/dev/null 2>&1 \
          || ! systemctl start xray.service >/dev/null 2>&1 \
          || ! _e127_verify_xray_runtime "$CONFIG" 12; then
            error "新节点未通过启动探针，正在恢复建仓前状态。"
            _e127_rollback_config_or_emergency "$bdir" && rollback_ok=1 || rollback_ok=0
            test "$rollback_ok" -eq 1 || error "严重：建仓前状态自动恢复失败，快照：$bdir"
            return 1
        fi
    elif systemctl is-active --quiet xray.service 2>/dev/null; then
        error "配置事务意外启动了原本停止的Xray，正在回滚。"
        _e127_rollback_config_or_emergency "$bdir" >/dev/null 2>&1 || true
        return 1
    fi
    E118_TX_ACTIVE=0; E118_TX_BACKUP=""; E118_TX_WAS_ACTIVE=0
    return 0
}

_e118_restore_state() {
    local bdir="${1:-}" f base was_active=0 was_enabled=0 restore_failed=0 now
    _e127_verify_state_snapshot "$bdir" || return 1
    was_active=$(sed -n 's/^xray_was_active=//p' "$bdir/meta.env" 2>/dev/null | head -n1); was_active=${was_active:-0}
    was_enabled=$(sed -n 's/^xray_was_enabled=//p' "$bdir/meta.env" 2>/dev/null | head -n1); was_enabled=${was_enabled:-0}
    [[ "$was_active" =~ ^[01]$ && "$was_enabled" =~ ^[01]$ ]] || return 1
    if grep -qx config.json "$bdir/files.manifest" 2>/dev/null; then
        test -s "$bdir/config.json" || return 1
        _e118_xray_test_config "$bdir/config.json" 1 || return 1
    fi
    while IFS= read -r f; do
        test -n "$f" || continue
        base=$(basename "$f")
        if grep -qxF "$base" "$bdir/files.manifest" 2>/dev/null; then
            _e118_atomic_install "$bdir/$base" "$f" 0600 || { restore_failed=1; break; }
        else
            rm -f -- "$f" 2>/dev/null || restore_failed=1
        fi
    done < <(_e118_managed_state_files)
    test "$restore_failed" -eq 0 || return 1
    fix_permissions || return 1
    if test "$was_enabled" = 1; then
        systemctl enable xray.service >/dev/null 2>&1 || return 1
    else
        systemctl disable xray.service >/dev/null 2>&1 || return 1
        now=$(systemctl is-enabled xray.service 2>/dev/null || true)
        case "$now" in enabled|enabled-runtime|linked|linked-runtime) return 1 ;; esac
    fi
    if test "$was_active" = 1; then
        systemctl reset-failed xray.service >/dev/null 2>&1 || true
        systemctl restart xray.service >/dev/null 2>&1 || return 1
        _e127_verify_xray_runtime "$CONFIG" 12 || return 1
    else
        systemctl stop xray.service >/dev/null 2>&1 || true
        systemctl is-active --quiet xray.service 2>/dev/null && return 1 || true
    fi
    E118_TX_ACTIVE=0; E118_TX_BACKUP=""; E118_TX_WAS_ACTIVE=0
    return 0
}

_e127_rollback_config_or_emergency() {
    local bdir="$1" was_active=0 was_enabled=0 marker failed=0
    _e118_restore_state "$bdir" && return 0
    error "完整状态回滚失败，尝试最小化恢复旧config.json。"
    if _e127_verify_state_snapshot "$bdir"; then
        was_active=$(sed -n 's/^xray_was_active=//p' "$bdir/meta.env" 2>/dev/null | head -n1); was_active=${was_active:-0}
        was_enabled=$(sed -n 's/^xray_was_enabled=//p' "$bdir/meta.env" 2>/dev/null | head -n1); was_enabled=${was_enabled:-0}
        if grep -qx config.json "$bdir/files.manifest" 2>/dev/null; then
            _e118_atomic_install "$bdir/config.json" "$CONFIG" 0600 || failed=1
        else
            rm -f -- "$CONFIG" 2>/dev/null || failed=1
        fi
        test "$failed" -ne 0 || fix_permissions || failed=1
        if test "$failed" -eq 0; then
            if test "$was_enabled" = 1; then
                systemctl enable xray.service >/dev/null 2>&1 || failed=1
            else
                systemctl disable xray.service >/dev/null 2>&1 || failed=1
            fi
        fi
        if test "$failed" -eq 0 && test "$was_active" = 1; then
            systemctl reset-failed xray.service >/dev/null 2>&1 || true
            systemctl restart xray.service >/dev/null 2>&1 \
              && _e127_verify_xray_runtime "$CONFIG" 12 \
              && { E118_TX_ACTIVE=0; E118_TX_BACKUP=""; E118_TX_WAS_ACTIVE=0; return 0; }
        elif test "$failed" -eq 0 && test "$was_active" = 0; then
            systemctl stop xray.service >/dev/null 2>&1 || true
            if ! systemctl is-active --quiet xray.service 2>/dev/null; then
                E118_TX_ACTIVE=0; E118_TX_BACKUP=""; E118_TX_WAS_ACTIVE=0; return 0
            fi
        fi
    fi
    marker="$E118_DIR/CRITICAL_RECOVERY_REQUIRED.env"
    {
        echo "time=$(date '+%F %T')"
        echo "backup=$bdir"
        echo "config=$CONFIG"
        echo "reason=e159-xray-rollback-incomplete"
    } >"${marker}.new.$$" 2>/dev/null \
      && chmod 0600 "${marker}.new.$$" 2>/dev/null \
      && mv -f -- "${marker}.new.$$" "$marker" 2>/dev/null || true
    E118_TX_ACTIVE=0; E118_TX_BACKUP=""; E118_TX_WAS_ACTIVE=0
    return 1
}

_e135_bundle_commit() {
    local cfg="$1" smap="$2" tmap="$3" pkey="$4" reason="${5:-user-change}"
    local bdir was_active=0 failed=0
    _e118_xray_test_config "$cfg" 1 || return 1
    bdir=$(_e116_backup_state "before_e159_${reason}") || return 1
    was_active=$(sed -n 's/^xray_was_active=//p' "$bdir/meta.env" 2>/dev/null | head -n1); was_active=${was_active:-0}
    [[ "$was_active" =~ ^[01]$ ]] || return 1
    E118_TX_ACTIVE=1; E118_TX_BACKUP="$bdir"; E118_TX_WAS_ACTIVE="$was_active"
    trap '' INT TERM HUP
    install -m 0600 "$cfg" "$CONFIG_DIR/.config.e159.$$" || failed=1
    test "$failed" -ne 0 || install -m 0600 "$smap" "$CONFIG_DIR/.user_sni.e159.$$" || failed=1
    test "$failed" -ne 0 || install -m 0600 "$tmap" "$CONFIG_DIR/.user_time.e159.$$" || failed=1
    test -z "$pkey" || test "$failed" -ne 0 || install -m 0600 "$pkey" "$CONFIG_DIR/.public.e159.$$" || failed=1
    if test "$failed" -eq 0; then
        mv -f "$CONFIG_DIR/.config.e159.$$" "$CONFIG" || failed=1
        test "$failed" -ne 0 || mv -f "$CONFIG_DIR/.user_sni.e159.$$" "$USER_SNI_MAP" || failed=1
        test "$failed" -ne 0 || mv -f "$CONFIG_DIR/.user_time.e159.$$" "$USER_TIME_MAP" || failed=1
        test -z "$pkey" || test "$failed" -ne 0 || mv -f "$CONFIG_DIR/.public.e159.$$" "$PUBKEY_FILE" || failed=1
    fi
    rm -f "$CONFIG_DIR"/.config.e159.$$ "$CONFIG_DIR"/.user_sni.e159.$$ \
        "$CONFIG_DIR"/.user_time.e159.$$ "$CONFIG_DIR"/.public.e159.$$ 2>/dev/null || true
    trap '_e118_signal_handler INT' INT
    trap '_e118_signal_handler TERM' TERM
    trap '_e118_signal_handler HUP' HUP
    test "$failed" -ne 0 || fix_permissions || failed=1
    if test "$failed" -eq 0 && test "$was_active" = 1; then
        systemctl restart xray.service >/dev/null 2>&1 || failed=1
        test "$failed" -ne 0 || _e127_verify_xray_runtime "$CONFIG" 12 || failed=1
    elif test "$failed" -eq 0 && systemctl is-active --quiet xray.service 2>/dev/null; then
        failed=1
    fi
    if test "$failed" -ne 0; then
        error "用户/凭据事务失败，恢复变更前配置与元数据。"
        _e118_restore_state "$bdir" || error "自动回滚失败：$bdir"
        E118_TX_ACTIVE=0; E118_TX_BACKUP=""; E118_TX_WAS_ACTIVE=0
        return 1
    fi
    E118_TX_ACTIVE=0; E118_TX_BACKUP=""; E118_TX_WAS_ACTIVE=0
    info "事务提交成功：$reason"
}

# Credential exports contain UUIDs, SS2022 secrets and Reality PBKs.  Treat
# directory ownership/mode and atomic file installation as hard gates instead
# of best-effort chmod calls.
_e118_prepare_dirs() {
    local d mode owner
    mkdir -p "$CONFIG_DIR" "$DAT_DIR" "$SCRIPT_DIR" "$LOG_DIR" "$FLAGS_DIR" /run/lock \
        2>/dev/null || return 1
    for d in "$BACKUP_DIR" "$E118_DIR" "$E118_BACKUP_DIR" "$E118_AUDIT_DIR"; do
        test ! -L "$d" || { error "拒绝使用符号链接事务目录：$d"; return 1; }
        install -d -o root -g root -m 0700 "$d" || return 1
        mode=$(stat -c '%a' "$d" 2>/dev/null || true)
        owner=$(stat -c '%u:%g' "$d" 2>/dev/null || true)
        test "$mode" = 700 && test "$owner" = 0:0 || {
            error "事务目录权限不安全：$d owner=$owner mode=$mode"; return 1;
        }
    done
}

# E127 sealed only the copied state files, not files.manifest/meta.env, and its
# snapshot creator unconditionally removed every directory after the newest
# 30.  A damaged service-state record could therefore drive the wrong restart
# decision, while a still-referenced emergency snapshot could be deleted by a
# later unrelated transaction.  E159 seals the complete base snapshot and
# prunes only unreferenced directories inside the trusted root.
_e159_prune_state_snapshots() {
    local keep="${XRAY_E159_STATE_KEEP:-30}" root real row p marker protected=" " n=0
    [[ "$keep" =~ ^[0-9]+$ ]] && (( keep >= 10 && keep <= 200 )) || keep=30
    root=$(readlink -f -- "$E118_BACKUP_DIR" 2>/dev/null || true)
    test -n "$root" && test -d "$root" || return 0
    p=$(cat "$E118_DIR/latest_backup.txt" 2>/dev/null || true)
    real=$(readlink -f -- "$p" 2>/dev/null || true); test -z "$real" || protected+="$real "
    test -z "${E118_TX_BACKUP:-}" || {
        real=$(readlink -f -- "$E118_TX_BACKUP" 2>/dev/null || true)
        test -z "$real" || protected+="$real "
    }
    for marker in "$E118_DIR/CRITICAL_RECOVERY_REQUIRED.env" "$E142_CRITICAL_MARKER" \
        "$E152_CRITICAL_MARKER" "$E159_CRITICAL_MARKER" \
        "$E159_LEGACY_E156_CRITICAL_MARKER" "$E159_LEGACY_E154_CRITICAL_MARKER"; do
        test -s "$marker" || continue
        while IFS= read -r p; do
            real=$(readlink -f -- "$p" 2>/dev/null || true)
            test -z "$real" || protected+="$real "
        done < <(sed -nE 's/^(backup|core_backup|transaction|xray_backup)=//p' "$marker")
    done
    while IFS=$'\t' read -r _ row; do
        test -n "$row" || continue
        n=$((n+1)); test "$n" -le "$keep" && continue
        real=$(readlink -f -- "$row" 2>/dev/null || true)
        case "$real" in "$root"/*) ;; *) continue ;; esac
        [[ "$protected" == *" $real "* ]] && continue
        rm -rf -- "${real:?}" 2>/dev/null || true
    done < <(find "$root" -mindepth 1 -maxdepth 1 -type d -printf '%T@\t%p\n' 2>/dev/null | sort -nr)
}

_e116_backup_state() (
    local tag="${1:-manual}" safe bdir f base seen=" " failed=0 latest_tmp enabled_state
    umask 077
    _e118_prepare_dirs || return 1
    safe=$(printf '%s' "$tag" | tr -c 'A-Za-z0-9_.-' '_')
    bdir=$(mktemp -d "$E118_BACKUP_DIR/${safe}_$(date +%Y%m%d_%H%M%S)_XXXXXX") || return 1
    chmod 0700 "$bdir" || { rm -rf -- "$bdir"; return 1; }
    : >"$bdir/files.manifest" || { rm -rf -- "$bdir"; return 1; }
    while IFS= read -r f; do
        test -n "$f" || continue
        base=$(basename -- "$f")
        [[ "$base" =~ ^[A-Za-z0-9._-]+$ ]] || { failed=1; break; }
        [[ "$seen" != *" $base "* ]] || { failed=1; break; }
        seen+="$base "
        test -e "$f" || continue
        test -f "$f" || { failed=1; break; }
        install -o root -g root -m 0600 "$f" "$bdir/$base" || { failed=1; break; }
        printf '%s\n' "$base" >>"$bdir/files.manifest" || { failed=1; break; }
    done < <(_e118_managed_state_files)
    if test "$failed" -ne 0; then rm -rf -- "$bdir"; return 1; fi
    enabled_state=$(systemctl is-enabled xray.service 2>/dev/null || true)
    enabled_state=$(printf '%s' "$enabled_state" | tr -c 'A-Za-z0-9_.@:-' '_' | head -c 80)
    {
        echo "created_at=$(date '+%F %T')"
        echo "version=$SCRIPT_VERSION"
        echo "tag=$safe"
        if systemctl is-active --quiet xray.service 2>/dev/null; then echo xray_was_active=1
        else echo xray_was_active=0; fi
        if systemctl is-enabled --quiet xray.service 2>/dev/null; then echo xray_was_enabled=1
        else echo xray_was_enabled=0; fi
        echo "xray_enabled_state=${enabled_state:-unknown}"
    } >"$bdir/meta.env" || { rm -rf -- "$bdir"; return 1; }
    command -v iptables-save >/dev/null 2>&1 \
        && iptables-save >"$bdir/iptables-save.txt" 2>/dev/null || true
    command -v ip6tables-save >/dev/null 2>&1 \
        && ip6tables-save >"$bdir/ip6tables-save.txt" 2>/dev/null || true
    : >"$bdir/files.sha256" || { rm -rf -- "$bdir"; return 1; }
    while IFS= read -r base; do
        test -n "$base" || continue
        (cd "$bdir" && sha256sum -- "$base") >>"$bdir/files.sha256" \
            || { failed=1; break; }
    done <"$bdir/files.manifest"
    if test "$failed" -ne 0; then rm -rf -- "$bdir"; return 1; fi
    chmod 0600 "$bdir"/* 2>/dev/null || { rm -rf -- "$bdir"; return 1; }
    (cd "$bdir" && find . -maxdepth 1 -type f ! -name snapshot-seal.sha256 \
        -printf '%P\0' | sort -z | xargs -0 sha256sum >snapshot-seal.sha256) \
        || { rm -rf -- "$bdir"; return 1; }
    test -s "$bdir/snapshot-seal.sha256" \
        && (cd "$bdir" && sha256sum -c snapshot-seal.sha256 >/dev/null 2>&1) \
        || { rm -rf -- "$bdir"; return 1; }
    chmod 0600 "$bdir/snapshot-seal.sha256" || { rm -rf -- "$bdir"; return 1; }
    latest_tmp="$E118_DIR/.latest_backup.e159.$$.$RANDOM"
    printf '%s\n' "$bdir" >"$latest_tmp" && chmod 0600 "$latest_tmp" \
        && mv -f -- "$latest_tmp" "$E118_DIR/latest_backup.txt" \
        || { rm -f -- "$latest_tmp"; rm -rf -- "$bdir"; return 1; }
    _e159_prune_state_snapshots
    printf '%s\n' "$bdir"
)

if declare -F _e127_verify_state_snapshot >/dev/null 2>&1; then
    eval "$(declare -f _e127_verify_state_snapshot | sed '1s/_e127_verify_state_snapshot/_e159_verify_state_snapshot_base/')"
fi
_e127_verify_state_snapshot() {
    local bdir="$1"
    _e159_verify_state_snapshot_base "$bdir" || return 1
    if grep -qx 'version=199e159' "$bdir/meta.env" 2>/dev/null; then
        test -s "$bdir/snapshot-seal.sha256" || {
            error "E159 Xray快照缺少元数据联合封印：$bdir"
            return 1
        }
    fi
    if test -e "$bdir/snapshot-seal.sha256"; then
        test -s "$bdir/snapshot-seal.sha256" \
            && (cd "$bdir" && sha256sum -c snapshot-seal.sha256 >/dev/null 2>&1) || {
            error "Xray快照元数据/清单联合封印失败：$bdir"
            return 1
        }
    fi
}

_e135_prepare() {
    local d mode owner
    _e118_runtime_init || return 1
    for d in "$E135_DIR" "$E135_BACKUP_DIR" "$E135_EXPORT_DIR"; do
        test ! -L "$d" || { error "拒绝使用符号链接凭据目录：$d"; return 1; }
        install -d -o root -g root -m 0700 "$d" || return 1
        mode=$(stat -c '%a' "$d" 2>/dev/null || true)
        owner=$(stat -c '%u:%g' "$d" 2>/dev/null || true)
        test "$mode" = 700 && test "$owner" = 0:0 || {
            error "凭据目录权限不安全：$d owner=$owner mode=$mode"; return 1;
        }
    done
}

_e135_emit_qr() {
    local uri="$1" label="$2" safe png txt tmp_txt tmp_png terminal_ok=0
    safe=$(_e135_safe_name "$label"); test -n "$safe" || safe=node
    _e135_prepare || return 1
    txt="$E135_EXPORT_DIR/${safe}.txt"
    png="$E135_EXPORT_DIR/${safe}.png"
    tmp_txt=$(_e118_mktemp export-uri-e159.txt) || return 1
    printf '%s\n' "$uri" >"$tmp_txt" || return 1
    _e118_atomic_install "$tmp_txt" "$txt" 0600 || return 1
    test "$(stat -c '%u:%g:%a' "$txt" 2>/dev/null || true)" = 0:0:600 || return 1
    if ! _e135_ensure_qrencode; then
        warn "qrencode不可用；已安全保存完整链接：$txt"
        return 0
    fi
    if test -t 1; then
        echo
        if qrencode -m 2 -t ANSIUTF8 "$uri" 2>/dev/null \
          || qrencode -m 2 -t UTF8 "$uri" 2>/dev/null; then
            terminal_ok=1
        else
            warn "终端二维码生成失败，继续尝试PNG。"
        fi
    fi
    tmp_png=$(_e118_mktemp export-qr-e159.png) || return 1
    if qrencode -m 2 -o "$tmp_png" "$uri" 2>/dev/null && test -s "$tmp_png"; then
        _e118_atomic_install "$tmp_png" "$png" 0600 || return 1
        test "$(stat -c '%u:%g:%a' "$png" 2>/dev/null || true)" = 0:0:600 || return 1
        info "二维码PNG：$png"
    else
        rm -f -- "$png" 2>/dev/null || true
        warn "链接未能生成PNG二维码；完整URI已安全保存：$txt"
    fi
    test "$terminal_ok" -eq 1 || info "终端未显示二维码；可使用上面的PNG或URI文件。"
}

# Manual Core update is a core-survival transaction too.  E127's menu path
# ignored fix_permissions failures and restored only the binary payload, which
# could pair an old core with installer-modified config/metadata.  Restore the
# state files first while Xray is stopped, then the old core/unit payload, and
# finally verify the exact original service state.
E159_CORE_TX_BACKUP=""

_e159_restore_xray_files_only() {
    local bdir="$1" f base
    _e127_verify_state_snapshot "$bdir" || return 1
    while IFS= read -r f; do
        test -n "$f" || continue
        base=$(basename "$f")
        if grep -qxF "$base" "$bdir/files.manifest" 2>/dev/null; then
            _e118_atomic_install "$bdir/$base" "$f" 0600 || return 1
        else
            rm -f -- "$f" 2>/dev/null || return 1
        fi
    done < <(_e118_managed_state_files)
    fix_permissions || return 1
}

_e159_restore_core_update() {
    local bdir="$1"
    systemctl stop xray.service >/dev/null 2>&1 || true
    _e159_restore_xray_files_only "$bdir" || return 1
    _e118_restore_core_payload "$bdir" || return 1
    _e118_restore_state "$bdir"
}

_e159_core_update_signal() {
    local sig="${1:-TERM}" bdir="${E159_CORE_TX_BACKUP:-}" rc=0
    trap - INT TERM HUP
    warn "Core更新收到$sig，执行Core、配置、元数据与服务联合回滚。"
    test -n "$bdir" && _e159_restore_core_update "$bdir" || rc=1
    if test "$rc" -ne 0; then
        {
            echo "time=$(date -Is 2>/dev/null || date)"
            echo "operation=core-update-signal"
            echo "signal=$sig"
            echo "core_backup=${bdir:-none}"
        } >"$E159_CRITICAL_MARKER" 2>/dev/null || true
    fi
    cleanup_temp_files
    exit 130
}

_e159_core_update_restore_traps() {
    trap '_e118_signal_handler INT' INT
    trap '_e118_signal_handler TERM' TERM
    trap '_e118_signal_handler HUP' HUP
    E159_CORE_TX_BACKUP=""
}

do_update_core() {
    local go="" installer logf bdir was_active=0 was_enabled=0 failed=0 rollback=0 enabled_now=""
    title "V199e159：Xray Core手动更新 / 联合回滚"
    _e159_prepare || return 1
    read -rp "是否从XTLS固定哈希官方安装器更新/修复Xray Core？[y/N]: " go || true
    [[ "$go" =~ ^[yY]$ ]] || { info "已取消；Core自动更新仍保持关闭。"; return 0; }
    test -s "$CONFIG" || { error "没有config.json，无法执行兼容性与回滚验证。"; return 1; }
    _e118_xray_test_config "$CONFIG" 1 || return 1
    bdir=$(_e116_backup_state before_core_update_e159) || return 1
    _e118_save_core_payload "$bdir" || {
        error "旧Core/DAT/systemd载荷备份或校验失败，拒绝更新。"; return 1;
    }
    _e127_verify_state_snapshot "$bdir" || return 1
    was_active=$(sed -n 's/^xray_was_active=//p' "$bdir/meta.env" | head -n1); was_active=${was_active:-0}
    was_enabled=$(sed -n 's/^xray_was_enabled=//p' "$bdir/meta.env" | head -n1); was_enabled=${was_enabled:-0}
    [[ "$was_active" =~ ^[01]$ && "$was_enabled" =~ ^[01]$ ]] || return 1

    E159_CORE_TX_BACKUP="$bdir"
    trap '_e159_core_update_signal INT' INT
    trap '_e159_core_update_signal TERM' TERM
    trap '_e159_core_update_signal HUP' HUP
    installer=$(_e118_mktemp xray-update-e159.sh) || { _e159_core_update_restore_traps; return 1; }
    logf=$(_e118_mktemp xray-update-e159.log) || { _e159_core_update_restore_traps; return 1; }
    if ! _e118_download_official_installer "$installer"; then
        _e159_core_update_restore_traps
        error "XTLS固定提交安装器下载/哈希/语法校验失败，旧Core未动。"
        return 1
    fi

    bash "$installer" install >"$logf" 2>&1 || failed=1
    test "$failed" -ne 0 || { test -x "$XRAY_BIN" && "$XRAY_BIN" version >/dev/null 2>&1; } || failed=1
    test "$failed" -ne 0 || e76_ensure_xray_service || failed=1
    test "$failed" -ne 0 || systemctl daemon-reload >/dev/null 2>&1 || failed=1
    test "$failed" -ne 0 || fix_permissions || failed=1
    test "$failed" -ne 0 || _e118_xray_test_config "$CONFIG" 1 || failed=1
    if test "$failed" -eq 0; then
        if test "$was_enabled" = 1; then
            systemctl enable xray.service >/dev/null 2>&1 || failed=1
        else
            systemctl disable xray.service >/dev/null 2>&1 || failed=1
        fi
    fi
    if test "$failed" -eq 0; then
        enabled_now=$(systemctl is-enabled xray.service 2>/dev/null || true)
        if test "$was_enabled" = 1; then
            case "$enabled_now" in enabled|enabled-runtime|linked|linked-runtime) ;; *) failed=1 ;; esac
        else
            case "$enabled_now" in enabled|enabled-runtime|linked|linked-runtime) failed=1 ;; esac
        fi
    fi
    if test "$failed" -eq 0 && test "$was_active" = 1; then
        systemctl restart xray.service >/dev/null 2>&1 || failed=1
        test "$failed" -ne 0 || _e127_verify_xray_runtime "$CONFIG" 12 || failed=1
    elif test "$failed" -eq 0; then
        systemctl stop xray.service >/dev/null 2>&1 || true
        systemctl is-active --quiet xray.service 2>/dev/null && failed=1 || true
    fi

    if test "$failed" -ne 0; then
        error "新Core、权限、配置或运行探针失败，执行联合回滚。"
        tail -n 120 "$logf" 2>/dev/null | sed 's/^/    /' || true
        _e159_restore_core_update "$bdir" || rollback=1
        _e159_core_update_restore_traps
        if test "$rollback" -ne 0; then
            {
                echo "time=$(date -Is 2>/dev/null || date)"
                echo "operation=core-update"
                echo "core_backup=$bdir"
                echo "installer_log=$logf"
            } >"$E159_CRITICAL_MARKER" 2>/dev/null || true
            error "严重：Core联合回滚未通过，快照：$bdir"
        fi
        return 1
    fi

    _e159_core_update_restore_traps
    _e105_disable_xray_core_auto_update || warn "Core自动更新禁用复检未完成，请检查systemd定时器。"
    _e127_prune_core_payload_backups
    info "Core手动更新完成并保持原服务状态：$($XRAY_BIN version 2>/dev/null | head -n1)"
}

# The inherited implementation masked an application-layer failure with later
# successful commands.  Every stage now propagates failure to the transaction.
_turn_on_app() {
    apply_xray_keep_2_to_6_defaults || return 1
    set_xray_gogc_300 || return 1
    fix_xray_systemd_limits || return 1
    systemctl daemon-reload >/dev/null 2>&1 || return 1
}

_e159_apply_safe_turbo_impl() {
    local qdisc scale app
    title "V199e159：安全系统级微操（完整网络事务版）"
    qdisc=$(sed -n 's/^qdisc=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1); qdisc=${qdisc:-fq}
    scale=$(sed -n 's/^tcp_adv_win_scale=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1); scale=${scale:-1}
    app=$(sed -n 's/^tcp_app_win=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1); app=${app:-31}
    _e159_network_apply "$qdisc" "$scale" "$app" force || return 1
    fix_xray_systemd_limits || return 1
    _e159_install_host_safe || return 1
    _e121_install_log_retention || return 1
    info "安全系统级微操完成；未自动改Swap/ZRAM、未最大化Ring、未关闭GRO/GSO、未强制关闭IPv6。"
}

apply_safe_turbo_defaults() {
    local protect sysbackup network_before="" was_active=0
    test -s "$CONFIG" || { error "config.json不存在。"; return 1; }
    protect=$(_e116_backup_state before_safe_turbo_e159) || return 1
    _e118_save_core_payload "$protect" || return 1
    sysbackup=$(_e159_new_tx safe-turbo) || return 1
    _e140_system_snapshot "$sysbackup" || return 1
    network_before=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1)
    was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2>/dev/null | tail -n1)
    was_active=${was_active:-0}
    if ! _e159_apply_safe_turbo_impl || ! systemctl daemon-reload >/dev/null 2>&1; then
        error "安全系统微操失败，恢复执行前网络、系统与Xray状态。"
        _e159_micro28_restore "$protect" "$sysbackup" "$network_before" || true
        return 1
    fi
    if test "$was_active" = 1; then
        if ! systemctl restart xray.service >/dev/null 2>&1 \
            || ! _e127_verify_xray_runtime "$CONFIG" 12; then
            error "安全系统微操后Xray运行探针失败，自动回滚。"
            _e159_micro28_restore "$protect" "$sysbackup" "$network_before" || true
            return 1
        fi
    elif systemctl is-active --quiet xray.service 2>/dev/null; then
        error "安全系统微操意外启动原本停止的Xray，自动回滚。"
        _e159_micro28_restore "$protect" "$sysbackup" "$network_before" || true
        return 1
    fi
    _e142_prune_transactions "$sysbackup" "$protect" || true
    _e159_prune_system_tx "$sysbackup"
    info "安全系统微操已通过Xray启停保持与运行态探针。"
}

_e159_micro28_restore() {
    local protect="$1" sysbackup="$2" network_before="${3:-}" network_tx="" rc=0
    network_tx=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1)
    if test -n "$network_tx" && test "$network_tx" != "$network_before"; then
        _e159_network_restore "$network_tx" || rc=1
    fi
    _e140_system_restore "$sysbackup" || rc=1
    _e118_restore_core_payload "$protect" >/dev/null 2>&1 || rc=1
    _e118_restore_state "$protect" >/dev/null 2>&1 || rc=1
    test "$rc" -eq 0 || error "第28项完整回滚失败：system=$sysbackup xray=$protect"
    return "$rc"
}

_e159_apply_micro_28() {
    local protect sysbackup network_before="" was_active=0
    test -s "$CONFIG" || { error "config.json不存在。"; return 1; }
    protect=$(_e116_backup_state before_micro28_e159) || return 1
    _e118_save_core_payload "$protect" || return 1
    sysbackup=$(_e159_new_tx micro28) || return 1
    _e140_system_snapshot "$sysbackup" || return 1
    network_before=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1)
    was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2>/dev/null | tail -n1)
    was_active=${was_active:-0}
    if ! _turn_on_app || ! apply_safe_turbo_defaults; then
        error "第28项失败，恢复执行前网络、系统和Xray状态。"
        _e159_micro28_restore "$protect" "$sysbackup" "$network_before" || true
        return 1
    fi
    if ! systemctl daemon-reload >/dev/null 2>&1; then
        error "第28项systemd重载失败，恢复完整旧状态。"
        _e159_micro28_restore "$protect" "$sysbackup" "$network_before" || true
        return 1
    fi
    if test "$was_active" = 1; then
        if ! systemctl restart xray.service >/dev/null 2>&1 \
            || ! _e127_verify_xray_runtime "$CONFIG" 12; then
            error "第28项后Xray重启/运行探针失败，恢复完整旧状态。"
            _e159_micro28_restore "$protect" "$sysbackup" "$network_before" || true
            return 1
        fi
    elif systemctl is-active --quiet xray.service 2>/dev/null; then
        error "第28项意外启动原本停止的Xray，恢复完整旧状态。"
        _e159_micro28_restore "$protect" "$sysbackup" "$network_before" || true
        return 1
    fi
    _e142_prune_transactions "$sysbackup" "$protect" || true
    _e159_prune_system_tx "$sysbackup"
    info "第28项已通过Xray配置测试、MainPID/监听端口探针和完整网络事务。"
}

e69_apply_micro_28_safe() { _e159_apply_micro_28; }
e68_apply_micro_28_defaults() { _e159_apply_micro_28; }
_e152_apply_micro_28() { _e159_apply_micro_28; }

# Converge WARP's Xray JSON mutation on the same config-test/runtime-probe/
# rollback primitive used by user and installer transactions.
_e138_xray_apply_warp() {
    local mode="${1:-disabled}" profile="${2:-disabled}" enable="${3:-false}"
    local tx cand protect failed=0
    _e138_prepare || return 1
    test -x "$XRAY_BIN" && test -s "$CONFIG" || { error "Xray尚未安装或配置不存在。"; return 1; }
    test "$enable" != true || _e137_warp_proxy_ready || { error "WARP本地代理未就绪。"; return 1; }
    tx=$(_e138_new_tx warp-route-e159) || return 1
    _e135_snapshot_file "$E138_WARP_STATE" "$tx/state" || return 1
    cand=$(_e118_mktemp xray-warp-e159.json) || return 1
    _e138_warp_config_build "$mode" "$profile" "$enable" "$cand" "$CONFIG" || return 1
    _e118_xray_test_config "$cand" 1 || return 1
    protect=$(_e116_backup_state before_warp_route_e159) || return 1
    _e118_commit_config "$cand" "$protect" preserve || return 1
    if test "$enable" = true; then
        _e138_warp_config_integrity "$mode" "$profile" || failed=1
        test "$failed" -ne 0 || _e138_state_write 1 "$mode" "$profile" || failed=1
    else
        _e138_warp_config_integrity disabled disabled || failed=1
        test "$failed" -ne 0 || _e138_state_write 0 disabled disabled || failed=1
    fi
    if test "$failed" -ne 0; then
        error "WARP配置提交后的完整性/状态写入失败，恢复旧Xray与WARP状态。"
        _e135_restore_file "$E138_WARP_STATE" "$tx/state" || true
        _e118_restore_state "$protect" || error "WARP Xray回滚未通过：$protect"
        return 1
    fi
}

_e139_clear_xray_warp_rules() { _e138_xray_apply_warp disabled disabled false; }

if declare -F _e140_warp_full_enable >/dev/null 2>&1; then
    eval "$(declare -f _e140_warp_full_enable | sed '1s/_e140_warp_full_enable/_e159_warp_full_enable_base/')"
