}

# The inherited outer installer ended its rollback scope before the final
# version/permission writes.  Keep one E159 guard alive through the final
# runtime probe so a late failure cannot strand the core.
_e135_install_mode() {
    local guard rc=0 rollback=0
    guard=$(_e116_backup_state before_e159_node_install) || return 1
    _e118_save_core_payload "$guard" || return 1
    _e152_install_mode_base "$@" || rc=1
    test "$rc" -ne 0 || _e159_write_version || rc=1
    test "$rc" -ne 0 || fix_permissions || rc=1
    test "$rc" -ne 0 || _e127_verify_xray_runtime "$CONFIG" 12 || rc=1
    if test "$rc" -ne 0; then
        error "E159节点安装最终门禁失败，恢复安装前Core、配置、元数据与服务状态。"
        _e118_restore_core_payload "$guard" >/dev/null 2>&1 || rollback=1
        _e118_restore_state "$guard" >/dev/null 2>&1 || rollback=1
        test "$rollback" -eq 0 || error "节点安装完整回滚失败：$guard"
        return 1
    fi
    info "节点安装已通过E159最终Xray运行探针。"
}

_e159_new_tx() {
    local name="${1:-tx}" d
    _e159_prepare || return 1
    name=$(printf '%s' "$name" | tr -c 'A-Za-z0-9_.-' '_')
    d="$E159_TX_ROOT/${name}-$(date +%Y%m%d_%H%M%S)-$$-$RANDOM"
    install -d -m 0700 "$d" || return 1
    printf '%s\n' "$d"
}

_e159_install_self() {
    local tx target snap tmp failed=0
    local -a targets=("$SYMLINK" "$E159_SELF_PATH" "$E159_LATEST_PATH")
    test -r "$SCRIPT_PATH" || return 1
    _e159_prepare || return 1
    tx=$(_e159_new_tx self-install) || return 1
    for target in "${targets[@]}"; do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
        _e135_snapshot_file "$target" "$snap" || return 1
    done
    for target in "${targets[@]}"; do
        install -d -m 0755 "$(dirname -- "$target")" || { failed=1; break; }
        tmp="$target.e159-new.$$"
        install -m 0755 "$SCRIPT_PATH" "$tmp" || { rm -f -- "$tmp"; failed=1; break; }
        mv -f -- "$tmp" "$target" || { rm -f -- "$tmp"; failed=1; break; }
        cmp -s "$SCRIPT_PATH" "$target" || { failed=1; break; }
    done
    if test "$failed" -ne 0; then
        for target in "${targets[@]}"; do
            snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
            _e135_restore_file "$target" "$snap" || true
        done
        return 1
    fi
    hash -r 2>/dev/null || true
}

_e159_write_version() {
    local tmp
    _e159_prepare || return 1
    tmp=$(_e118_mktemp e159-version) || return 1
    printf '%s\n' "$E159_VERSION" >"$tmp" || return 1
    _e118_atomic_install "$tmp" "$SCRIPT_VERSION_FILE" 0600
}
_e152_install_self() { _e159_install_self; }
_e152_write_version() { _e159_write_version; }

if declare -F _e138_system_paths >/dev/null 2>&1; then
