# Extend the inherited full-system transaction with E159 service states.  File
# snapshots alone do not restore enablement symlinks or active timers.
if declare -F _e140_system_snapshot >/dev/null 2>&1; then
    eval "$(declare -f _e140_system_snapshot | sed '1s/_e140_system_snapshot/_e159_system_snapshot_base/')"
fi
_e140_system_snapshot() {
    local b="$1" unit
    _e159_system_snapshot_base "$b" || return 1
    : >"$b/e159-services.env" || return 1
    for unit in xray-network-e159.service xray-network-e159.timer xray-host-safe-e159.service \
        xray-network-e156.service xray-network-e156.timer xray-host-safe-e156.service \
        xray-network-e154.service xray-network-e154.timer xray-host-safe-e154.service; do
        _e159_snapshot_service "$unit" >>"$b/e159-services.env" || return 1
    done
    (cd "$b" && sha256sum e159-services.env >e159-services.sha256) || return 1
}

if declare -F _e140_system_restore >/dev/null 2>&1; then
    eval "$(declare -f _e140_system_restore | sed '1s/_e140_system_restore/_e159_system_restore_base/')"
fi
_e140_system_restore() {
    local b="$1" unit enabled active rc=0
    if test -e "$b/e159-services.env" || test -e "$b/e159-services.sha256"; then
        test -s "$b/e159-services.env" && test -s "$b/e159-services.sha256" \
            && (cd "$b" && sha256sum -c e159-services.sha256 >/dev/null 2>&1) \
            || { error "E159服务状态快照损坏：$b"; return 1; }
    fi
    _e159_system_restore_base "$b" || rc=1
    if test -s "$b/e159-services.env"; then
        while IFS='|' read -r unit enabled active; do
            test -n "$unit" || continue
            _e159_restore_service "$unit" "$enabled" "$active" || rc=1
        done <"$b/e159-services.env"
    fi
    return "$rc"
}

# Uninstall removes the E159 owner only after the inherited DELETE-XRAY gate.
if declare -F _e142_restore_network_baseline >/dev/null 2>&1; then
    eval "$(declare -f _e142_restore_network_baseline | sed '1s/_e142_restore_network_baseline/_e159_restore_network_baseline_base/')"
fi
_e142_restore_network_baseline() {
    _e159_network_remove force || return 1
    _e159_restore_network_baseline_base "$@"
}

_e159_phase_log() {
    local file="$1" phase="$2" status="$3" detail="${4:-}"
    install -d -m 0700 "$(dirname "$file")" 2>/dev/null || true
    printf '%s\tphase=%s\tstatus=%s\tdetail=%q\n' \
        "$(date -Is 2>/dev/null || date)" "$phase" "$status" "$detail" >>"$file" 2>/dev/null || true
}

_e159_hot_step() {
    local phase="$1"; shift
    _e159_phase_log "$E159_HOT_LOG" "$phase" begin
    if "$@"; then _e159_phase_log "$E159_HOT_LOG" "$phase" ok; return 0; fi
    _e159_phase_log "$E159_HOT_LOG" "$phase" fail
    error "E159热更新失败阶段：$phase"
    return 1
}

_e159_hot_update_preflight() {
    _e152_hot_update_preflight || return 1
    _e159_prepare || return 1
    for c in modprobe tc cut wc uniq head tail; do
        command -v "$c" >/dev/null 2>&1 || { error "E159预检缺少命令：$c"; return 1; }
    done
    _e159_forwarding_conflict || return 1
}

_e159_hot_update() (
    local protect="" sysbackup="" network_tx="" rc=0 rollback_rc=0 was_active=0
    local enabled=0 mode=disabled profile=disabled phase=start
    local effective_active=0 effective_persistent=0 unsupported=0 shadowed=0 trigger=0
    _e214_ensure_run_lock || return 1
    exec 153> /run/lock/xray-e159-hot-update.lock
    flock -n 153 || { error "已有另一个E159热更新正在运行。"; return 1; }
    : >"$E159_HOT_LOG" || return 1
    E135_NEW_PACKAGES=()
    _e159_phase_log "$E159_HOT_LOG" start begin "$SCRIPT_PATH"
    _e159_prepare || return 1

    phase=xray-snapshot
    protect=$(_e116_backup_state before_hot_update_e159) || rc=1
    test "$rc" -ne 0 || _e118_save_core_payload "$protect" || rc=1
    if test "$rc" -eq 0; then
        was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2>/dev/null | tail -n1)
        was_active=${was_active:-0}
        _e159_phase_log "$E159_HOT_LOG" "$phase" ok "$protect"
    fi
    if test "$rc" -eq 0; then
        phase=system-snapshot
        sysbackup=$(_e159_new_tx hot-update) || rc=1
        test "$rc" -ne 0 || _e140_system_snapshot "$sysbackup" || rc=1
        test "$rc" -ne 0 || _e159_phase_log "$E159_HOT_LOG" "$phase" ok "$sysbackup"
    fi

    # WARP state migration writes E139_WARP_STATE.  It must happen after the
    # full-system snapshot so a later hot-update failure restores the old file
    # (or its prior absence) instead of leaking a pre-snapshot mutation.
    test "$rc" -ne 0 || _e159_hot_step warp-state-migrate _e138_warp_migrate_state || rc=1
    if test "$rc" -eq 0; then
        enabled=$(_e138_state_get route_enabled 0)
        mode=$(_e138_state_get route_mode disabled)
        profile=$(_e138_state_get profile disabled)
    fi

    test "$rc" -ne 0 || _e159_hot_step runtime-tools _e135_require_runtime_tools || rc=1
    test "$rc" -ne 0 || _e159_hot_step disable-legacy _e135_disable_legacy_optimizers || rc=1
    test "$rc" -ne 0 || _e159_hot_step self-install _e159_install_self || rc=1
    test "$rc" -ne 0 || _e159_hot_step dat-install install_update_dat || rc=1
    test "$rc" -ne 0 || _e159_hot_step dat-timer systemctl enable --now xray-dat-update.timer || rc=1
    test "$rc" -ne 0 || _e159_hot_step core-auto-update-off _e105_disable_xray_core_auto_update || rc=1
    test "$rc" -ne 0 || _e159_hot_step init-window _e137_apply_init_window_default30 || rc=1
    if test "$rc" -eq 0; then
        E159_DEFER_HOST_FULL_VERIFY=1
        _e159_hot_step network-source127-controls125 _e159_network_apply fq 1 31 force || rc=1
        unset E159_DEFER_HOST_FULL_VERIFY
        test "$rc" -ne 0 || network_tx=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" | tail -n1)
    fi
    test "$rc" -ne 0 || _e159_hot_step host-safe-migrate _e159_migrate_host_safe || rc=1
    test "$rc" -ne 0 || _e159_hot_step log-retention _e121_install_log_retention || rc=1
    test "$rc" -ne 0 || _e159_hot_step ssh-guard _e141_install_ssh_guard || rc=1
    test "$rc" -ne 0 || _e159_hot_step xray-limits fix_xray_systemd_limits || rc=1
    if test "$rc" -eq 0 && test "$enabled" = 1; then
        if test "$mode" = host-full; then
            _e159_hot_step warp-full-units _e140_full_install_units || rc=1
            test "$rc" -ne 0 || _e159_hot_step warp-full-reconcile _e140_warp_full_reconcile || rc=1
        else
            _e159_hot_step warp-proxy _e137_warp_connect_local_proxy || rc=1
            test "$rc" -ne 0 || _e159_hot_step warp-xray _e138_xray_apply_warp "$mode" "$profile" true || rc=1
            test "$rc" -ne 0 || _e159_hot_step warp-health _e138_warp_health_install || rc=1
        fi
    fi
    test "$rc" -ne 0 || _e159_hot_step version-write _e159_write_version || rc=1

    if test "$rc" -eq 0; then
        phase=verify
        _e159_phase_log "$E159_HOT_LOG" "$phase" begin
        test -x "$XRAY_BIN" && "$XRAY_BIN" version >/dev/null 2>&1 || rc=1
        test "$rc" -ne 0 || test ! -s "$CONFIG" || _e118_xray_test_config "$CONFIG" 1 || rc=1
        if test "$rc" -eq 0 && test "$was_active" = 1; then
            _e127_verify_xray_runtime "$CONFIG" 12 || rc=1
            test "$rc" -ne 0 || _e131_verify_nice_runtime || rc=1
        elif test "$rc" -eq 0 && systemctl is-active --quiet xray.service 2>/dev/null; then
            error "热更新意外启动了原本停止的Xray服务。"; rc=1
        fi
        test "$rc" -ne 0 || _e159_network_verify_effective || rc=1
        test "$rc" -ne 0 || _e159_network_verify_ownership || rc=1
        test "$rc" -ne 0 || _e159_ssh_guard_verify_final || rc=1
        test "$rc" -ne 0 || grep -qx 'net.ipv4.tcp_notsent_lowat = 16384' "$E159_EFFECTIVE_CONF" || rc=1
        test "$rc" -ne 0 || grep -qx 'net.core.busy_poll = 50' "$E159_EFFECTIVE_CONF" || rc=1
        test "$rc" -ne 0 || _e159_verify_neighbor_queue_semantics || rc=1
        test "$rc" -ne 0 || ! grep -Eq '^[[:space:]]*net\.ipv6\.conf\..*\.disable_ipv6[[:space:]]*=' "$E159_EFFECTIVE_CONF" || rc=1
        test "$rc" -ne 0 || grep -Eq 'initcwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1
        test "$rc" -ne 0 || grep -Eq 'initrwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1
        for unit in xray-dat-update.timer xray-log-retention-e121.timer xray-ssh-auth-audit-e152.timer xray-network-e159.timer; do
            test "$rc" -ne 0 || systemctl is-enabled --quiet "$unit" 2>/dev/null || rc=1
            test "$rc" -ne 0 || systemctl is-active --quiet "$unit" 2>/dev/null || rc=1
        done
        test "$rc" -ne 0 || systemctl is-enabled --quiet xray-network-e159.service 2>/dev/null || rc=1
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$SYMLINK" || rc=1
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$E159_SELF_PATH" || rc=1
        test "$rc" -eq 0 && _e159_phase_log "$E159_HOT_LOG" "$phase" ok \
            || _e159_phase_log "$E159_HOT_LOG" "$phase" fail
    fi

    if test "$rc" -ne 0; then
        error "E159热更新失败，开始总回滚；阶段日志：$E159_HOT_LOG"
        test -z "$network_tx" || _e159_network_restore "$network_tx" || rollback_rc=1
        test -z "$sysbackup" || _e140_system_restore "$sysbackup" || rollback_rc=1
        test -z "$protect" || _e118_restore_core_payload "$protect" >/dev/null 2>&1 || rollback_rc=1
        test -z "$protect" || _e118_restore_state "$protect" >/dev/null 2>&1 || rollback_rc=1
        _e135_remove_new_runtime_tools || true
        if test "$was_active" = 1; then
            _e127_verify_xray_runtime "$CONFIG" 12 >/dev/null 2>&1 || rollback_rc=1
        fi
        if test "$rollback_rc" -ne 0; then
            {
                echo "time=$(date -Is 2>/dev/null || date)"
                echo "operation=hot-update"
                echo "system_backup=${sysbackup:-none}"
                echo "network_backup=${network_tx:-none}"
                echo "core_backup=${protect:-none}"
                echo "log=$E159_HOT_LOG"
            } >"$E159_CRITICAL_MARKER" 2>/dev/null || true
            error "严重：E159回滚未通过复检。"
        fi
        _e159_phase_log "$E159_HOT_LOG" finish fail "rollback=$rollback_rc"
        return 1
    fi
    rm -f "$E159_CRITICAL_MARKER" 2>/dev/null || true
    _e142_prune_transactions "$sysbackup" "$protect" || warn "旧事务快照收敛未完成。"
    _e127_prune_core_payload_backups
    _e159_prune_system_tx "$sysbackup"
    _e152_cleanup_legacy_e143_units || true
    _e159_phase_log "$E159_HOT_LOG" finish ok
    effective_active=$(sed -n 's/^effective_active=//p' "$E159_NETWORK_STATE" | tail -n1)
    effective_persistent=$(sed -n 's/^effective_persistent=//p' "$E159_NETWORK_STATE" | tail -n1)
    unsupported=$(sed -n 's/^unsupported=//p' "$E159_NETWORK_STATE" | tail -n1)
    shadowed=$(sed -n 's/^shadowed_alias=//p' "$E159_NETWORK_STATE" | tail -n1)
    trigger=$(sed -n 's/^write_trigger=//p' "$E159_NETWORK_STATE" | tail -n1)
    info "V199e159热更新完成：127条请求（persistent=$effective_persistent，trigger=$trigger，unsupported=$unsupported，shadowed_alias=$shadowed，effective_assignments=$effective_active）、init30、3天日志、SSH守护和Xray运行态均已验证。"
    info "系统快照：$sysbackup"
    info "网络快照：$network_tx"
    info "阶段日志：$E159_HOT_LOG"
)

hot_update_from_legacy() { _e159_hot_update_preflight && _e159_hot_update; }

_e159_ipv6_status() {
    local all default lo
    all=$(sysctl -n net.ipv6.conf.all.disable_ipv6 2>/dev/null || echo unsupported)
    default=$(sysctl -n net.ipv6.conf.default.disable_ipv6 2>/dev/null || echo unsupported)
    lo=$(sysctl -n net.ipv6.conf.lo.disable_ipv6 2>/dev/null || echo unsupported)
    echo "IPv6 policy=preserve (E159 does not write disable_ipv6)"
    echo "runtime: all=$all default=$default lo=$lo"
}

_e159_optimization_menu_audit() {
    local body rc=0
    echo "V199e159 optimization-menu audit:"
    body=$(declare -f do_sys_init_menu 2>/dev/null || true)
    [[ "$body" == *'_e159_advanced_menu_impl'* ]] \
        && echo "  [PASS] advanced menu is bound to E159" \
        || { echo "  [FAIL] advanced menu binding"; rc=1; }
    body=$(declare -f _e159_advanced_menu_impl 2>/dev/null || true)
    [[ "$body" == *'_e152_network_menu'* && "$body" == *'_e152_apply_micro_28'* ]] \
        && echo "  [PASS] network and micro-28 entries retained" \
        || { echo "  [FAIL] advanced menu entries"; rc=1; }
    [[ "$(declare -f _e152_network_menu 2>/dev/null || true)" == *'_e159_network_menu'* ]] \
        && echo "  [PASS] every visible network entry converges on E159" \
        || { echo "  [FAIL] network menu convergence"; rc=1; }
    body=$(declare -f do_micro_control_menu 2>/dev/null || true)
    [[ "$body" == *'_e159_xray_action_tx'* && "$body" == *'_e159_apply_micro_28'* \
        && "$body" != *'systemctl restart xray > /dev/null 2>&1 || true'* ]] \
        && echo "  [PASS] micro menu uses the Xray survival gate" \
        || { echo "  [FAIL] unsafe inherited micro restart remains"; rc=1; }
    return "$rc"
}

_e159_structure_audit() {
    local rc=0 body
    echo "V199e159 effective-implementation audit:"
    body=$(declare -f hot_update_from_legacy 2>/dev/null || true)
    [[ "$body" == *'_e159_hot_update_preflight'* && "$body" == *'_e159_hot_update'* ]] \
        && echo "  [PASS] menu-11 hot update -> E159" \
        || { echo "  [FAIL] menu-11 still points to an older release"; rc=1; }
    body="$(declare -f _e152_network_apply 2>/dev/null || true)$(declare -f _e159_legacy_network_apply 2>/dev/null || true)"
    [[ "$body" == *'_e159_legacy_network_apply'* && "$body" == *'_e159_network_apply'* ]] \
        && echo "  [PASS] legacy network apply -> complete E159 transaction" \
        || { echo "  [FAIL] legacy narrow network path remains reachable"; rc=1; }
    body=$(declare -f _safe_jq_write 2>/dev/null || true)
    [[ "$body" == *'_e118_xray_test_config'* && "$body" == *'_e118_commit_config'* ]] \
        && echo "  [PASS] Xray jq writes retain config-test + transactional commit" \
        || { echo "  [FAIL] Xray safe-write gate"; rc=1; }
    body=$(declare -f _e118_commit_config 2>/dev/null || true)
    [[ "$body" == *'_e127_verify_xray_runtime'* && "$body" == *'_e127_rollback_config_or_emergency'* ]] \
        && echo "  [PASS] Xray commit retains runtime probe + emergency rollback" \
        || { echo "  [FAIL] Xray runtime survival gate"; rc=1; }
    [[ "$body" == *'if ! fix_permissions'* ]] \
        && echo "  [PASS] Xray config permissions are a mandatory commit gate" \
        || { echo "  [FAIL] Xray permission failure can be masked"; rc=1; }
    body=$(declare -f _e135_bundle_commit 2>/dev/null || true)
    [[ "$body" == *'fix_permissions || failed=1'* && "$body" == *'_e118_restore_state'* ]] \
        && echo "  [PASS] user/credential bundle propagates permission failure" \
        || { echo "  [FAIL] user/credential permission rollback gate"; rc=1; }
    body="$(declare -f _e118_prepare_dirs 2>/dev/null || true)
$(declare -f _e135_prepare 2>/dev/null || true)
$(declare -f _e135_emit_qr 2>/dev/null || true)"
    [[ "$body" == *'E118_BACKUP_DIR'* && "$body" == *'test ! -L'* \
        && "$body" == *'owner" = 0:0'* \
        && "$body" == *'_e118_atomic_install'* && "$body" == *'0:0:600'* ]] \
        && echo "  [PASS] snapshots and URI/QR exports enforce root-only atomic credentials" \
        || { echo "  [FAIL] credential export permission gate"; rc=1; }
    body="$(declare -f _e116_backup_state 2>/dev/null || true)
$(declare -f _e127_verify_state_snapshot 2>/dev/null || true)
$(declare -f _e159_prune_state_snapshots 2>/dev/null || true)"
    [[ "$body" == *'snapshot-seal.sha256'* && "$body" == *'meta.env'* \
        && "$body" == *'latest_backup.txt'* && "$body" == *'CRITICAL_RECOVERY_REQUIRED.env'* ]] \
        && echo "  [PASS] Xray snapshot metadata is sealed and referenced recovery points are protected" \
        || { echo "  [FAIL] Xray snapshot metadata/pruning invariant"; rc=1; }
    body="$(declare -f do_update_core 2>/dev/null || true)
$(declare -f _e159_restore_core_update 2>/dev/null || true)
$(declare -f _e159_core_update_signal 2>/dev/null || true)"
    [[ "$body" == *'_e118_download_official_installer'* && "$body" == *'fix_permissions || failed=1'* \
        && "$body" == *'_e127_verify_xray_runtime'* && "$body" == *'_e159_restore_xray_files_only'* \
        && "$body" == *'enabled_now=$(systemctl is-enabled xray.service'* \
