        && echo "  [PASS] manual Core update has pinned download, runtime probe and joint rollback" \
        || { echo "  [FAIL] manual Core update survival transaction"; rc=1; }
    body=$(declare -f _e159_hot_update 2>/dev/null || true)
    [[ "$body" == *'_e159_network_apply fq 1 31 force'* && "$body" == *'_e127_verify_xray_runtime'* \
        && "$body" == *'host-safe-migrate'* && "$body" == *'shadowed-alias'* \
        && "${body%%_e138_warp_migrate_state*}" == *'_e140_system_snapshot'* ]] \
        && echo "  [PASS] E159 hot update applies 127 requests / 125 persistent controls and verifies Xray" \
        || { echo "  [FAIL] E159 hot-update phase binding"; rc=1; }
    body=$(declare -f _e159_build_effective 2>/dev/null || true)
    [[ "$body" == *'shadowed-alias'* && "$body" == *'unres_qlen_bytes'* ]] \
        && echo "  [PASS] deprecated neighbour queue view is shadowed at candidate-build time" \
