    body=$(declare -f _e159_network_apply 2>/dev/null || true)
    [[ "$body" == *'_e159_network_artifacts_validate'* && "$body" == *'effective_active='* \
        && "$body" == *'E159_NETWORK_SEAL'* ]] \
