    body="$(declare -f _e152_verify_nft_fail2ban_action 2>/dev/null || true)
$(declare -f _e159_f2b_test_family 2>/dev/null || true)"
    [[ "$body" == *'_e159_f2b_action_contract'* && "$body" == *'_e159_f2b_banned_state'* \
        && "$body" == *'_e159_nft_has_element'* ]] \
        && echo "  [PASS] native nft Fail2ban uses action/ticket/set verification" \
