    body="$(declare -f _e121_write_fail2ban_candidates 2>/dev/null || true)
$(declare -f _e159_f2b_jail_action_lines 2>/dev/null || true)"
    [[ "$body" == *'_e159_f2b_jail_action_lines'* && "$body" == *'action = %s[name=%s'* \
        && "$body" == *'banaction = nftables'* && "$body" == *'chain = INPUT'* ]] \
        && echo "  [PASS] Fail2ban jail emits an explicit nft action without chain override" \
