    body="$(declare -f _e159_f2b_action_contract 2>/dev/null || true)
$(declare -f _e159_ssh_guard_install_base 2>/dev/null || true)
$(declare -f _e141_install_ssh_guard 2>/dev/null || true)"
    [[ "$body" == *'_e159_f2b_action_property'* && "$body" == *'table_family'* \
