        && "$body" == *'_e135_restore_file'* ]] \
        && echo "  [PASS] host-safe migration covers E156/E154 predecessors" \
        || { echo "  [FAIL] host-safe migration rollback boundary"; rc=1; }
    body=$(declare -f _e159_legacy_sysctl_owned 2>/dev/null || true)
    [[ "$body" == *'Xray / VPS Network Optimized Sysctl Profile'* ]] \
        && echo "  [PASS] script-marked E127/E153 sysctl ownership is recognized" \
        || { echo "  [FAIL] legacy sysctl ownership recognition"; rc=1; }
    _e159_optimization_menu_audit || rc=1
    test "$rc" -eq 0 && echo "V199e159 structure result: PASS" || echo "V199e159 structure result: FAIL"
    return "$rc"
}

# Deterministic regression for the exact production verifier.  The first
# scenario has both a Fail2Ban ticket and an nft element; the second deliberately
# keeps only the ticket.  E156 could not distinguish those states reliably.
_e159_f2b_mock_planes() (
    local MOCK_MODE=good MOCK_BANNED=""
    sleep() { :; }
    _e159_f2b_diag() { :; }
    _e116_detect_ssh_ports() { echo 22; }
    fail2ban-client() {
        local op="${1:-}" sub="${3:-}" name="${4:-}" property="${5:-}" ip=""
        if test "$op" = get && test "$sub" = actions; then echo "['nftables']"; return 0; fi
        if test "$op" = get && test "$sub" = action; then
            case "$property" in
                table) echo f2b-e159 ;; table_family) echo inet ;;
                chain) echo f2b-e159-input ;; chain_hook) echo input ;;
                chain_priority) echo -1 ;; actionstart_on_demand) echo false ;;
                type) echo multiport ;; blocktype) echo reject ;; port) echo 22 ;;
                protocol) echo tcp ;;
                actionstart) echo 'nft add table inet f2b-e159; nft add chain inet f2b-e159 f2b-e159-input' ;;
                actionban) echo 'nft add element inet f2b-e159 addr-set-mock { <ip> }' ;;
                actionunban) echo 'nft delete element inet f2b-e159 addr-set-mock { <ip> }' ;;
                *) return 1 ;;
            esac
            return 0
        fi
        if test "$op" = get && test "$sub" = banned; then
            ip="$name"; test -n "$MOCK_BANNED" && test "$MOCK_BANNED" = "$ip" && echo 1 || echo 0
            return 0
        fi
        if test "$op" = get && test "$sub" = banip; then
            test -z "$MOCK_BANNED" || echo "$MOCK_BANNED"; return 0
        fi
        if test "$op" = set && test "$sub" = banip; then MOCK_BANNED="$name"; return 0; fi
        if test "$op" = set && test "$sub" = unbanip; then MOCK_BANNED=""; return 0; fi
        return 1
    }
    nft() {
        local element=""
        test "$MOCK_MODE" != good || element="$MOCK_BANNED"
        if test "${1:-}" = -j; then
            command jq -nc --arg ip "$element" '{nftables:[
              {chain:{name:"f2b-e159-input",hook:"input",prio:-1}},
              {rule:{expr:[{match:{right:"@addr-set-mock"}},{reject:null}],element:$ip}}
            ]}'
            return 0
        fi
        if test "${1:-}" = -a; then
            printf 'chain f2b-e159-input { type filter hook input priority -1; ip saddr @addr-set-mock reject; }\n'
            test -z "$element" || printf '%s\n' "$element"
            return 0
        fi
        if test "${1:-}" = list; then
            printf 'chain f2b-e159-input { type filter hook input priority -1; ip saddr @addr-set-mock reject; }\n'
            test -z "$element" || printf '%s\n' "$element"
            return 0
        fi
        return 0
    }
    _e159_f2b_action_contract || return 1
    _e159_nft_table_contract || return 1
    _e159_f2b_test_family inet4 || return 1
    test -z "$MOCK_BANNED" || return 1
    MOCK_MODE=ticket-only
    ! _e159_f2b_test_family inet4 || return 1
    test -z "$MOCK_BANNED"
)

_e159_self_test() {
    local rc=0 d spec effective report hash count first key p old_proc="" had_proc=0 body action
    echo "V199e159 release gate:"
    bash -n "$SCRIPT_PATH" \
        && echo "  [PASS] bash syntax" \
        || { echo "  [FAIL] bash syntax"; rc=1; }
    test "$SCRIPT_VERSION" = 199e159 && test "$E159_VERSION" = 199e159 \
        && echo "  [PASS] release identity" \
        || { echo "  [FAIL] release identity"; rc=1; }
    d=$(mktemp -d /tmp/e159-selftest.XXXXXX) || return 1
    spec="$d/requested"; effective="$d/effective"; report="$d/report"
    _e159_full_spec fq 1 31 "$spec" || rc=1
    _e159_spec_validate "$spec" || rc=1
    hash=$(awk -F= '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{k=$1;v=substr($0,index($0,"=")+1);gsub(/[[:space:]]/,"",k);gsub(/^[[:space:]]+|[[:space:]]+$/,"",v);print k"="v}' "$spec" | sha256sum | awk '{print $1}')
    test "$hash" = 02b4e6b670d91938b70b77ebe8ae4c55e5ba02014f779d292d2699f524856882 \
        && echo "  [PASS] exact ex199e127 source: 127 requests / 125 persistent controls" \
        || { echo "  [FAIL] requested profile drift: $hash"; rc=1; }
    grep -qx 'fs.file-max' < <(_e159_active_keys "$spec") \
        && grep -qx 'fs.aio-max-nr' < <(_e159_active_keys "$spec") \
        && echo "  [PASS] hyphenated sysctl names are included in apply/snapshot/rollback" \
        || { echo "  [FAIL] hyphenated sysctl parser regression"; rc=1; }
    ! grep -Eq '^[[:space:]]*net\.ipv6\.conf\..*\.disable_ipv6[[:space:]]*=' "$spec" \
        && echo "  [PASS] IPv6 disable remains unowned" \
        || { echo "  [FAIL] active IPv6 disable found"; rc=1; }

    if [[ ${E159_PROC_ROOT+x} ]]; then had_proc=1; old_proc=$E159_PROC_ROOT; fi
    E159_PROC_ROOT="$d/proc"
    while IFS= read -r key; do
        p=$(_e159_proc_path "$key")
        mkdir -p "$(dirname "$p")" || rc=1
        : >"$p" || rc=1
        chmod 0600 "$p" || rc=1
    done < <(_e159_active_keys "$spec")
    _e159_build_effective "$spec" "$effective" "$report" || rc=1
    count=$(_e159_active_keys "$effective" | wc -l | tr -d ' ')
    first=$(_e159_active_keys "$effective" | head -n1)
    test "$count" -eq 126 && test "$first" = net.ipv4.ip_forward \
        && grep -q $'net.ipv4.neigh.default.unres_qlen\tshadowed-alias\t3000\t' "$report" \
        && ! grep -Eq '^[[:space:]]*net\.ipv4\.neigh\.default\.unres_qlen[[:space:]]*=' "$effective" \
        && grep -qx 'net.ipv4.neigh.default.unres_qlen_bytes = 65535' "$effective" \
        && echo "  [PASS] 127 requests -> 125 persistent controls + 1 trigger + 1 alias" \
        || { echo "  [FAIL] effective profile count/order: $count/$first"; rc=1; }
    _e159_network_artifacts_validate "$spec" "$effective" "$report" \
        && echo "  [PASS] valid 127/report/effective closed-set invariant" \
        || { echo "  [FAIL] valid artifact invariant rejected"; rc=1; }
    cp -- "$report" "$d/report-duplicate"
    awk -F'\t' 'NR==2{print;exit}' "$report" >>"$d/report-duplicate"
    if _e159_network_artifacts_validate "$spec" "$effective" "$d/report-duplicate" >/dev/null 2>&1; then
        echo "  [FAIL] duplicate report row was accepted"; rc=1
    else
        echo "  [PASS] impossible report/effective count is rejected before commit"
    fi
    cp -- "$effective" "$d/effective-duplicate"
    grep -m1 '^net\.core\.default_qdisc[[:space:]]*=' "$effective" >>"$d/effective-duplicate"
    if _e159_network_artifacts_validate "$spec" "$d/effective-duplicate" "$report" >/dev/null 2>&1; then
        echo "  [FAIL] duplicate effective key was accepted"; rc=1
    else
        echo "  [PASS] duplicate effective key is rejected before commit"
    fi
    if _e159_unres_alias_equal "$spec" 31 65535 \
        && ! _e159_unres_alias_equal "$spec" 31 65534; then
        echo "  [PASS] deprecated neighbour queue alias validates authoritative bytes"
    else
        echo "  [FAIL] neighbour queue alias normalization"; rc=1
    fi
    rm -f -- "$(_e159_proc_path net.ipv4.ipfrag_low_thresh)"
    _e159_build_effective "$spec" "$d/effective-noncritical" "$d/report-noncritical" \
        && grep -q $'net.ipv4.ipfrag_low_thresh\tunsupported\t' "$d/report-noncritical" \
        && echo "  [PASS] unsupported noncritical key is reported, not silently lost" \
        || { echo "  [FAIL] noncritical compatibility handling"; rc=1; }
    p=$(_e159_proc_path net.ipv4.ipfrag_low_thresh); : >"$p"; chmod 0600 "$p"
    rm -f -- "$(_e159_proc_path net.ipv4.tcp_mtu_probing)"
    if _e159_build_effective "$spec" "$d/effective-critical" "$d/report-critical" >/dev/null 2>&1; then
        echo "  [FAIL] unsupported critical key was accepted"; rc=1
    else
        echo "  [PASS] unsupported critical key rejects the transaction"
    fi
    mkdir -p "$d/actions"
    : >"$d/actions/nftables.conf"
    if [[ "$(_e152_choose_banaction_for_backend nft "$d/actions" 2>/dev/null || true)" \
          == *"table=$E159_NFT_F2B_TABLE"* ]]; then
        echo "  [PASS] native nft action targets the fresh E159 transaction table"
    else
        echo "  [FAIL] native nft action selection did not target E159"; rc=1
    fi
    action=$(E121_F2B_BANACTION="$(_e152_choose_banaction_for_backend nft "$d/actions")" \
        _e159_f2b_jail_action_lines nft 22,2222 2>/dev/null || true)
    if [[ "$action" == *'banaction = nftables'* \
       && "$action" == *"table=$E159_NFT_F2B_TABLE"* \
       && "$action" == *"chain=$E159_NFT_F2B_CHAIN"* \
       && "$action" == *'port="22,2222"'* \
       && "$action" != *'chain=""'* ]]; then
        echo "  [PASS] explicit jail action cannot be overwritten by an empty default chain"
    else
        echo "  [FAIL] explicit Fail2ban jail action rendering"; rc=1
    fi
    if _e159_f2b_action_values_valid "$E159_NFT_F2B_TABLE" inet \
          "$E159_NFT_F2B_CHAIN" input -1 false multiport reject 22,2222 tcp 22,2222 \
          '<nftables> add table <table_family> <table>; <nftables> add chain <table_family> <table> <chain>' \
          '<nftables> add element <table_family> <table> <addr_set> { <ip> }' \
          '<nftables> delete element <table_family> <table> <addr_set> { <ip> }' \
       && ! _e159_f2b_action_values_valid f2b-wrong inet \
          "$E159_NFT_F2B_CHAIN" input -1 false multiport reject 22,2222 tcp 22,2222 \
          'add table; add chain' 'add element' 'delete element' \
       && ! _e159_f2b_action_values_valid "$E159_NFT_F2B_TABLE" inet \
          "$E159_NFT_F2B_CHAIN" input -1 false multiport reject 22 tcp 22,2222 \
          'add table; add chain' 'add element' 'delete element'; then
        echo "  [PASS] Fail2ban raw placeholders are accepted only with exact E159 properties"
    else
        echo "  [FAIL] Fail2ban raw action-property contract"; rc=1
    fi
    if _e159_f2b_mock_planes; then
        echo "  [PASS] native nft ticket+set succeeds and ticket-only false positive is rejected"
    else
        echo "  [FAIL] native nft live-plane regression"; rc=1
    fi
    if test "$had_proc" -eq 1; then E159_PROC_ROOT=$old_proc; else unset E159_PROC_ROOT; fi
    rm -rf -- "$d"
    _e159_structure_audit || rc=1
    body="$(declare -f _e121_install_log_retention 2>/dev/null || true)
$(declare -f _e142_log_retention_before_migration 2>/dev/null || true)
$(declare -f _e142_log_retention_base 2>/dev/null || true)"
    [[ "$body" == *'_e142_log_retention_before_migration'* \
        && "$body" == *'MaxRetentionSec=3day'* \
        && "$body" == *'maxage 3'* \
        && "$body" == *'/var/log/xray/*/*.log'* \
        && "$body" != *'find /var/log/xray -mindepth 2 -type f -mmin +4320 -delete'* ]] \
        && echo "  [PASS] journald/logrotate/nested logs retain 3 days without unlinking current logs" \
        || { echo "  [FAIL] 3-day log retention binding"; rc=1; }
    test "$rc" -eq 0 && echo "V199e159 result: PASS" || echo "V199e159 result: FAIL"
    return "$rc"
}

_e159_xray_action_rollback() {
    local protect="$1" rc=0
    _e118_restore_core_payload "$protect" >/dev/null 2>&1 || rc=1
    _e118_restore_state "$protect" >/dev/null 2>&1 || rc=1
    test "$rc" -eq 0 || error "Xray动作回滚未完整通过：$protect"
    return "$rc"
}

_e159_xray_action_tx() {
    local name="$1" protect was_active=0; shift
    test -s "$CONFIG" || { error "config.json不存在。"; return 1; }
    protect=$(_e116_backup_state "before_${name}_e159") || return 1
    _e118_save_core_payload "$protect" || return 1
    was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2>/dev/null | tail -n1)
    was_active=${was_active:-0}
    if ! "$@"; then
        error "$name 执行失败，恢复Xray配置、Core、systemd drop-in与原启停状态。"
        _e159_xray_action_rollback "$protect" || true
        return 1
    fi
    _e118_xray_test_config "$CONFIG" 1 || {
        _e159_xray_action_rollback "$protect" || true
        return 1
    }
    systemctl daemon-reload >/dev/null 2>&1 || {
        _e159_xray_action_rollback "$protect" || true
        return 1
    }
    if test "$was_active" = 1; then
        if ! systemctl restart xray.service >/dev/null 2>&1 || ! _e127_verify_xray_runtime "$CONFIG" 12; then
            error "$name 后Xray运行探针失败，自动回滚。"
            _e159_xray_action_rollback "$protect" || true
            return 1
        fi
    else
        systemctl stop xray.service >/dev/null 2>&1 || true
        if systemctl is-active --quiet xray.service 2>/dev/null; then
            error "$name 意外启动了原本停止的Xray，自动回滚。"
            _e159_xray_action_rollback "$protect" || true
            return 1
        fi
    fi
    info "$name 已通过配置测试、启停状态保持与运行探针。"
}

_e159_action_tfo_toggle() {
    local current
    current=$(jq -r '.outbounds[]? | select(.protocol=="freedom") | .streamSettings?.sockopt?.tcpFastOpen // false' "$CONFIG" 2>/dev/null | head -n1)
    if test "$current" = true; then
        _safe_jq_write '(.outbounds[]? | select(.streamSettings?.sockopt? != null) | .streamSettings.sockopt.tcpFastOpen)=false | (.inbounds[]? | select(.streamSettings?.sockopt? != null) | .streamSettings.sockopt.tcpFastOpen)=false'
    else
        _safe_jq_write '(.outbounds[]? | select(.streamSettings?.sockopt? != null) | .streamSettings.sockopt.tcpFastOpen)=true | (.inbounds[]? | select(.streamSettings?.sockopt? != null) | .streamSettings.sockopt.tcpFastOpen)=true'
    fi
}

_e159_action_2_to_6() {
    apply_xray_keep_2_to_6_defaults || return 1
    remove_xray_env_buffer || return 1
}

_e159_action_mph() { _safe_jq_write '.routing |= (. // {}) | .routing.domainMatcher = "mph"'; }

_e159_action_reality_time() {
    jq -e '.inbounds[]? | select(.protocol=="vless" and .streamSettings?.security=="reality")' "$CONFIG" >/dev/null 2>&1 \
        || { error "当前配置没有Reality入站。"; return 1; }
    _safe_jq_write '(.inbounds[]? | select(.protocol=="vless" and .streamSettings?.security=="reality") | .streamSettings.realitySettings.maxTimeDiff) = 60000'
}

# Replace the inherited menu whose branches restarted Xray with "|| true" and
# could report success after a failed configuration action.  The 28 entries are
# retained, but every Xray-changing entry now uses the survival transaction.
do_micro_control_menu() {
    local opt qdisc confirm
    while true; do
        clear
        title "V199e159：28项应用层/系统微操（Xray生存门禁版）"
        echo "  1) TCP NoDelay稳态配置        1f) TCP FastOpen独立切换"
        echo "  2-6) KeepAlive/嗅探/路由/Buffer/DNS稳态组"
        echo "  7) GOGC=300                  8) Policy/Buffer/Reality稳态组"
        echo "  9) Xray CPU调度              10) routing domainMatcher=mph"
        echo " 11) Reality maxTimeDiff=60s   12) Dnsmasq接管（高影响，需确认）"
        echo " 13) THP=never独立固化          14) 125持久控制/127请求参数"
        echo " 15) CPU performance独立固化   16) Ring Buffer事务最大化"
        echo " 17) E159 qdisc选择             18-20) CAKE子项转到TC中心"
        echo " 21) Offload独立控制            22) RPS/RFS独立控制"
        echo " 23) ZRAM/Swap 1GiB（高影响）   24) 3天持久日志策略"
        echo " 25) Xray Nice/OOM限制          26) 一键应用层1-11"
        echo " 27) 安全系统微操（不改Swap/Ring/Offload/IPv6）"
        echo " 28) 应用层+安全系统微操完整事务"
        echo "  0) 返回"
        hr
        read -rp "操作: " opt || true
        case "$opt" in
            1) _e159_xray_action_tx nodelay apply_xray_nodelay_default || true; _e52_pause ;;
            1f|1F) _e159_xray_action_tx tcp-fastopen _e159_action_tfo_toggle || true; _e52_pause ;;
            2) _e159_xray_action_tx socket-keepalive _e204_action_socket_keepalive || true; _e52_pause ;;
            3) _e159_xray_action_tx sniffing-metadata-only _e204_action_metadata_only || true; _e52_pause ;;
            4) _e159_xray_action_tx sniffing-route-only _e204_action_route_only || true; _e52_pause ;;
            5) _e159_xray_action_tx buffer-128k _e204_action_buffer_128 || true; _e52_pause ;;
            6) _e159_xray_action_tx dns-use-ipv4 _e204_action_dns_ipv4 || true; _e52_pause ;;
            7) _e159_xray_action_tx gogc-300 set_xray_gogc_300 || true; _e52_pause ;;
            8) _e159_xray_action_tx core-defaults force_apply_xray_core_defaults_e52 || true; _e52_pause ;;
            9) _e159_xray_action_tx cpu-schedule apply_xray_cpu_schedule_default || true; _e52_pause ;;
            10) _e159_xray_action_tx mph _e159_action_mph || true; _e52_pause ;;
            11) _e159_xray_action_tx reality-time _e159_action_reality_time || true; _e52_pause ;;
            12)
                warn "Dnsmasq会接管resolv.conf并停用systemd-resolved/resolvconf。"
                read -rp "输入 APPLY-DNSMASQ 确认: " confirm || true
                test "$confirm" = APPLY-DNSMASQ && _e159_xray_action_tx dnsmasq enable_dnsmasq_cache_safely || true
                _e52_pause ;;
            13) _e159_install_host_safe thp || error "THP固化失败。"; _e52_pause ;;
            14) _e159_network_apply fq 1 31 || true; _e52_pause ;;
            15) _e159_install_host_safe cpu || error "CPU策略固化失败。"; _e52_pause ;;
            16) apply_ring_max_adaptive_default || error "Ring事务失败。"; _e52_pause ;;
            17)
                warn '此项会事务重放完整127条网络请求并写入所选qdisc，不是只改一个sysctl。'
                read -rp "qdisc [fq/fq_codel/cake]: " qdisc || true
                qdisc=${qdisc:-fq}; _e159_network_apply "$qdisc" 1 31 || true; _e52_pause ;;
            18|19|20)
                warn "CAKE ack-filter/ECN/wash属于实际TC root qdisc，不再由旧xray-hw大包围服务持久化。"
                declare -F do_tc_bandwidth_menu_e95 >/dev/null 2>&1 && do_tc_bandwidth_menu_e95 || true ;;
            21)
                declare -F _e88_manual_offload_profile >/dev/null 2>&1 \
                    && _e88_manual_offload_profile || warn "Offload模块不可用。"
                _e52_pause ;;
            22)
                declare -F _e88_apply_rps_rfs >/dev/null 2>&1 \
                    && _e88_apply_rps_rfs || warn "RPS/RFS模块不可用或应用失败。"
                _e52_pause ;;
            23)
                warn "此项会调整Swap/ZRAM和fstab。"
                read -rp "输入 APPLY-ZRAM-1G 确认: " confirm || true
                test "$confirm" = APPLY-ZRAM-1G && enable_zram_default || true
                _e52_pause ;;
            24) _e121_install_log_retention || error "3天日志策略安装失败。"; _e52_pause ;;
            25) _e159_xray_action_tx xray-limits apply_process_priority_default || true; _e52_pause ;;
            26) _e159_xray_action_tx app-1-to-11 _turn_on_app || true; _e52_pause ;;
            27) apply_safe_turbo_defaults || error "安全系统微操失败并已由子事务处理。"; _e52_pause ;;
            28) _e159_apply_micro_28 || true; _e52_pause ;;
            0) return 0 ;;
            *) warn "无效操作。"; sleep 1 ;;
        esac
    done
}

