        -e 's/fix_xray_systemd_limits;/_e159_xray_action_tx xray-limits fix_xray_systemd_limits || true;/g')"
fi
do_sys_init_menu() { _e159_advanced_menu_impl; }

if declare -F do_uninstall >/dev/null 2>&1; then
    eval "$(declare -f do_uninstall | sed '1s/do_uninstall/_e159_uninstall_base/')"
fi
do_uninstall() {
    local rc=0
    _e159_uninstall_base "$@" || rc=$?
    # A cancelled inherited DELETE-XRAY prompt also returns zero.  Only remove
    # E159 ownership after the core/config are actually gone.
    if test "$rc" -eq 0 && test ! -e "$XRAY_BIN" && test ! -e "$CONFIG"; then
        systemctl disable --now xray-host-safe-e159.service \
            xray-network-e159.service xray-network-e159.timer \
            xray-host-safe-e156.service xray-network-e156.service \
            xray-network-e156.timer \
            xray-host-safe-e154.service xray-network-e154.service \
            xray-network-e154.timer >/dev/null 2>&1 || true
        rm -f -- "$E159_HOST_SCRIPT" "$E159_HOST_SERVICE" "$E159_MODULES_CONF" \
            "$E159_NETWORK_SCRIPT" "$E159_NETWORK_SERVICE" "$E159_NETWORK_TIMER" \
            "$E159_EFFECTIVE_CONF" "$E159_NETWORK_SEAL" "$E159_SELF_PATH" "$E159_LATEST_PATH" \
            "$E159_LEGACY_E156_HOST_SCRIPT" "$E159_LEGACY_E156_HOST_SERVICE" \
            "$E159_LEGACY_E156_MODULES_CONF" "$E159_LEGACY_E156_SCRIPT" \
            "$E159_LEGACY_E156_SERVICE" "$E159_LEGACY_E156_TIMER" \
            "$E159_LEGACY_E156_EFFECTIVE_CONF" "$E159_LEGACY_E156_SELF_PATH" \
            "$E159_LEGACY_E154_HOST_SCRIPT" "$E159_LEGACY_E154_HOST_SERVICE" \
            "$E159_LEGACY_E154_MODULES_CONF" "$E159_LEGACY_E154_SCRIPT" \
            "$E159_LEGACY_E154_SERVICE" "$E159_LEGACY_E154_TIMER" \
            "$E159_LEGACY_E154_EFFECTIVE_CONF" "$E159_LEGACY_E154_SELF_PATH" 2>/dev/null || true
        rm -rf -- "$E159_DIR" "$E159_LEGACY_E156_DIR" "$E159_LEGACY_E154_DIR" 2>/dev/null || true
        systemctl daemon-reload >/dev/null 2>&1 || true
    fi
    return "$rc"
}

_e127_prune_core_payload_backups() {
    local keep=5 row dir count=0 marker p real protected=" "
    test -d "$E118_BACKUP_DIR" || return 0
    for marker in "$E118_DIR/CRITICAL_RECOVERY_REQUIRED.env" "$E142_CRITICAL_MARKER" \
        "$E159_CRITICAL_MARKER" "$E159_LEGACY_E156_CRITICAL_MARKER" \
        "$E159_LEGACY_E154_CRITICAL_MARKER"; do
        test -s "$marker" || continue
        while IFS= read -r p; do
            real=$(readlink -f -- "$p" 2>/dev/null || true)
            test -z "$real" || protected+="$real "
        done < <(sed -nE 's/^(backup|core_backup)=//p' "$marker")
    done
    while IFS= read -r row; do
        count=$((count+1)); test "$count" -le "$keep" && continue
        dir=${row#* }
        real=$(readlink -f -- "$dir" 2>/dev/null || true)
        case "$real" in "$E118_BACKUP_DIR"/*) ;; *) continue ;; esac
        [[ "$protected" == *" $real "* ]] && continue
        rm -f -- "$real/xray.core.before" "$real/xray.core.before.sha256" \
            "$real/xray.core.was-absent" "$real"/core-*.before "$real"/core-*.was-absent \
            "$real"/unit-*.before "$real"/unit-*.was-absent "$real/core-payload.sha256" 2>/dev/null || true
        rm -rf -- "$real"/unit-*.before 2>/dev/null || true
        : >"$real/core-payload-pruned" 2>/dev/null || true
    done < <(find "$E118_BACKUP_DIR" -mindepth 1 -maxdepth 1 -type d \
        -exec test -e '{}/xray.core.before' ';' -printf '%T@ %p\n' 2>/dev/null | sort -nr)
}

if declare -F _e152_space_cleanup_impl >/dev/null 2>&1; then
    eval "$(declare -f _e152_space_cleanup_impl | sed \
        -e '1s/_e152_space_cleanup_impl/_e159_space_cleanup_impl/' \
        -e 's/V199e152：受控空间清理/V199e159：受控空间清理/g')"
fi
do_space_cleanup_menu() { _e159_space_cleanup_impl "$@"; }

check_and_clean_space() {
    _e121_check_and_clean_space "$@" || return 1
    _e159_prune_state_snapshots
    _e159_prune_network_tx
    _e159_prune_system_tx
}


#==============================================================================
# V199e159 FINAL CONSOLIDATION LAYER
# - E127 exact 127-request/125-control network model retained from E158
# - Fail2ban native nftables action is now a dedicated action file, not a
#   nested bracket expression
# - ban/unban must converge in both Fail2ban ticket and nftables set planes
# - synthetic test addresses are cleaned on normal return, error and signals
# - sysctl audit covers all standard systemd-sysctl source directories
# - release self-test is fast, non-mutating and behavior-based
#==============================================================================

readonly E159_F2B_ACTION_ID="xray-nftables-e159"
readonly E159_F2B_ACTION_CONF="/etc/fail2ban/action.d/xray-nftables-e159.conf"
readonly E159_F2B_FILTER_NAME="xray-sshd-password-e159"
readonly E159_F2B_FILTER="/etc/fail2ban/filter.d/xray-sshd-password-e159.conf"
readonly E159_RELEASE_AUDIT="$E159_DIR/release-audit.env"
readonly E159_WARP_IPC_DIAG="$E159_DIR/warp-ipc-last.log"

# Host-full WARP carries locally originated VPS/Xray traffic.  It does not
# require the VPS to act as an IPv4 router, so E127's ip_forward=0 is not by
# itself a conflict.  Container/router workloads remain protected below.
_e159_forwarding_conflict() {
    local svc current_forward=0 all_forward=0 enabled=0 mode=disabled
    if declare -F _e138_state_get >/dev/null 2>&1; then
        enabled=$(_e138_state_get route_enabled 0)
        mode=$(_e138_state_get route_mode disabled)
    fi
    test "$enabled" = 1 && test "$mode" = host-full \
        && info '检测到Cloudflare host-full：保留原IPv4回程，允许E127的ip_forward=0。'
    for svc in docker.service podman.service containerd.service kubelet.service \
      k3s.service k3s-agent.service rke2-server.service rke2-agent.service \
      libvirtd.service virtqemud.service lxd.service incus.service \
      tailscaled.service zerotier-one.service; do
        if systemctl is-active --quiet "$svc" 2>/dev/null; then
            test "${E159_ALLOW_FORWARDING_OFF:-0}" = 1 || {
                error "检测到$svc运行；E127完整参数的ip_forward=0可能中断容器/虚拟网络。"
                error '确认不需要内核转发后，使用E159_ALLOW_FORWARDING_OFF=1显式执行。'
                return 1
            }
        fi
    done
    current_forward=$(sysctl -n net.ipv4.ip_forward 2>/dev/null || echo 0)
    all_forward=$(sysctl -n net.ipv4.conf.all.forwarding 2>/dev/null || echo 0)
    if { test "$current_forward" = 1 || test "$all_forward" = 1; } \
      && test "${E159_ALLOW_FORWARDING_OFF:-0}" != 1; then
        error "当前主机正在进行IPv4内核转发（ip_forward=$current_forward/all.forwarding=$all_forward）。"
        error 'E127完整参数要求二者为0；确认本机不是路由器/NAT后再显式覆盖。'
        return 1
    fi
}

# Remove the inherited false incompatibility between the exact E127 sysctl
# profile and host-full WARP.
_e140_warp_full_enable() { _e159_warp_full_enable_base "$@"; }

# If the exact network profile is replayed while host-full is active, reapply
# and verify the protected original-IPv4 reply route.  Failure restores the
# network transaction recorded by the profile before returning an error.
if declare -F _e159_network_apply >/dev/null 2>&1; then
    eval "$(declare -f _e159_network_apply | sed '1s/_e159_network_apply/_e159_network_apply_exact_base/')"
fi
_e159_network_apply() {
    local enabled=0 mode=disabled tx="" rc=0
    if declare -F _e138_state_get >/dev/null 2>&1; then
        enabled=$(_e138_state_get route_enabled 0)
        mode=$(_e138_state_get route_mode disabled)
    fi
    _e159_network_apply_exact_base "$@" || return 1
    if test "$enabled" = 1 && test "$mode" = host-full; then
        # Re-establish the original-IPv4 reply route immediately after sysctl
        # replay. During a hot update, the full client/service verification is
        # deferred to the explicit warp-full-reconcile stage below.
        if ! _e140_full_route_apply; then
            tx=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1)
            error 'E159网络已应用，但host-full原IPv4回程策略无法重建；恢复网络事务。'
            test -z "$tx" || _e159_network_restore "$tx" || rc=1
            _e140_full_route_apply >/dev/null 2>&1 || rc=1
            test "$rc" -eq 0 || error '严重：网络恢复后host-full原IPv4回程仍未恢复。'
            return 1
        fi
        if test "${E159_DEFER_HOST_FULL_VERIFY:-0}" = 1; then
            info 'E159网络重放后已恢复host-full原IPv4回程；完整WARP验证延后到热更新专用阶段。'
            return 0
        fi
        if _e140_full_verify; then
            info 'E159网络重放后Cloudflare host-full及SSH/Xray原IPv4回程已复检。'
            return 0
        fi
        tx=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1)
        error 'E159网络已应用，但host-full完整复检失败；恢复网络事务。'
        test -z "$tx" || _e159_network_restore "$tx" || rc=1
        _e140_full_route_apply >/dev/null 2>&1 || rc=1
        _e140_full_verify >/dev/null 2>&1 || rc=1
        test "$rc" -eq 0 || error '严重：网络恢复后host-full仍未通过复检。'
        return 1
    fi
}

#------------------------------------------------------------------------------
# Fail2ban: dedicated native nftables action.
# E158 produced nftables[...][name=...,port=...] which is not one valid action
# parameter group. E159 installs a small action overlay and references it once.
#------------------------------------------------------------------------------
_e159_write_nft_action_candidate() {
    local out="$1"
    cat >"$out" <<EOF_E159_NFT_ACTION
[INCLUDES]
before = nftables.conf

[Init]
type = multiport
table = $E159_NFT_F2B_TABLE
table_family = inet
chain = $E159_NFT_F2B_CHAIN
chain_type = filter
chain_hook = input
chain_priority = -1
blocktype = reject
actionstart_on_demand = false
EOF_E159_NFT_ACTION
}

if declare -F _e152_choose_banaction_for_backend >/dev/null 2>&1; then
    eval "$(declare -f _e152_choose_banaction_for_backend | sed '1s/_e152_choose_banaction_for_backend/_e159_choose_banaction_base/')"
fi
_e152_choose_banaction_for_backend() {
    local backend="$1" action_dir="${2:-/etc/fail2ban/action.d}"
    if test "$backend" = nft; then
        test -f "$action_dir/nftables.conf" || return 1
        printf '%s\n' "$E159_F2B_ACTION_ID"
        return 0
    fi
    _e159_choose_banaction_base "$backend" "$action_dir"
}

_e121_select_banaction() {
    local backend action action_rc=0
    E121_F2B_BANACTION=""
    E121_F2B_EAGER_ACTION=0
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    action=$(_e152_choose_banaction_for_backend "$backend" /etc/fail2ban/action.d 2>/dev/null) \
        || action_rc=$?
    test -n "$action" || {
        if test "$backend" = nft; then
            error "缺少Fail2ban统一nftables.conf，无法安装E159专用action。"
        else
            error "后端=$backend，但没有匹配且可验证的Fail2ban action。"
        fi
        return "${action_rc:-1}"
    }
    E152_F2B_BACKEND_KIND="$backend"
    E121_F2B_BANACTION="$action"
    case "$backend:$action" in
        nft:"$E159_F2B_ACTION_ID")
            E121_F2B_EAGER_ACTION=1
            info "原生nftables：使用$E159_F2B_ACTION_ID和事务表$E159_NFT_F2B_TABLE。"
            ;;
        iptables:iptables-multiport)
            E121_F2B_EAGER_ACTION=1
            info 'iptables：使用立即创建的multiport封禁链。'
            ;;
    esac
}

_e159_f2b_jail_action_lines() {
    local backend="$1" csv="$2"
    [[ "$csv" =~ ^[0-9]+(,[0-9]+)*$ ]] || return 1
    case "$backend" in
        nft)
            test "$E121_F2B_BANACTION" = "$E159_F2B_ACTION_ID" || return 1
            printf 'action = %s[name=%s,port="%s",protocol=tcp]\n' \
                "$E159_F2B_ACTION_ID" "$E121_F2B_JAIL_NAME" "$csv"
            ;;
        iptables)
            echo 'chain = INPUT'
            test -z "$E121_F2B_BANACTION" || echo "banaction = $E121_F2B_BANACTION"
            ;;
        *)
            test -z "$E121_F2B_BANACTION" || echo "banaction = $E121_F2B_BANACTION"
            ;;
    esac
}

# Preserve the old name used by inherited callers, but use the corrected E159
# renderer everywhere.
_e159_f2b_jail_action_lines_compat() { _e159_f2b_jail_action_lines "$@"; }

_e121_write_fail2ban_candidates() {
    local ports csv jail_tmp db_tmp filter_tmp action_tmp ignore backend
    ports=$(_e116_detect_ssh_ports)
    test -n "$ports" || ports=22
    csv=$(printf '%s\n' $ports | sort -nu | paste -sd, -)
    [[ "$csv" =~ ^[0-9]+(,[0-9]+)*$ ]] || {
        error "SSH端口列表非法：$csv"
        return 1
    }
    ignore=$(_e152_collect_ignoreip "${E152_CURRENT_SSH_IP:-}")
    backend=${E152_F2B_BACKEND_KIND:-$(_e152_firewall_backend 2>/dev/null || echo none)}

    install -d -m 0755 /etc/fail2ban/action.d /etc/fail2ban/filter.d \
        /etc/fail2ban/jail.d /etc/fail2ban/fail2ban.d || return 1
    install -d -m 0755 /var/lib/fail2ban || return 1

    jail_tmp=$(_e118_mktemp fail2ban-e159-jail) || return 1
    db_tmp=$(_e118_mktemp fail2ban-e159-db) || return 1
    filter_tmp=$(_e118_mktemp fail2ban-e159-filter) || return 1
    action_tmp=$(_e118_mktemp fail2ban-e159-action) || return 1

    _e159_write_nft_action_candidate "$action_tmp" || return 1

    cat >"$filter_tmp" <<'EOF_E159_F2B_FILTER'
[INCLUDES]
before = common.conf

[Definition]
_daemon = sshd(?:-session)?
# Count the final password/keyboard-interactive failure line only.  Do not also
# count the preceding generic PAM failure line, otherwise one attempt can count
# twice when maxretry=2.
failregex = ^%(__prefix_line)sFailed password for (?:invalid user )?.*? from <HOST>(?: port \d+)?(?: ssh\d*)?(?: \[preauth\])?\s*$
            ^%(__prefix_line)sFailed keyboard-interactive/pam for (?:invalid user )?.*? from <HOST>(?: port \d+)?(?: ssh\d*)?(?: \[preauth\])?\s*$
ignoreregex =
journalmatch = _SYSTEMD_UNIT=sshd.service + _SYSTEMD_UNIT=ssh.service + _COMM=sshd + _COMM=sshd-session
EOF_E159_F2B_FILTER

    cat >"$db_tmp" <<'EOF_E159_F2B_DB'
[Definition]
allowipv6 = auto
dbfile = /var/lib/fail2ban/fail2ban.sqlite3
dbpurgeage = 3d
logtarget = /var/log/xray-fail2ban.log
loglevel = INFO
EOF_E159_F2B_DB

    {
        echo "[$E121_F2B_JAIL_NAME]"
        echo 'enabled = true'
        echo "filter = $E159_F2B_FILTER_NAME"
        echo "backend = $E121_F2B_BACKEND"
        test "$E121_F2B_BACKEND" = systemd || echo "logpath = $E121_F2B_LOGPATH"
        echo "port = $csv"
        echo 'protocol = tcp'
        echo 'usedns = no'
        test -z "$ignore" || echo "ignoreip = $ignore"
        _e159_f2b_jail_action_lines "$backend" "$csv" || return 1
        echo 'maxretry = 2'
        echo 'findtime = 86400'
        echo 'bantime = 129600'
    } >"$jail_tmp" || return 1

    # The outer native-nft SSH transaction snapshots these paths before this
    # function runs, so partial writes are recoverable.
    if test "$backend" = nft; then
        _e121_atomic_install "$action_tmp" "$E159_F2B_ACTION_CONF" 0644 || return 1
    fi
    _e121_atomic_install "$filter_tmp" "$E159_F2B_FILTER" 0644 || return 1
    _e121_atomic_install "$db_tmp" "$E121_F2B_DB_CONF" 0644 || return 1
    _e121_atomic_install "$jail_tmp" "$E121_F2B_JAIL" 0644 || return 1
}

if declare -F _e121_managed_fail2ban_paths >/dev/null 2>&1; then
    eval "$(declare -f _e121_managed_fail2ban_paths | sed '1s/_e121_managed_fail2ban_paths/_e159_managed_fail2ban_paths_base/')"
fi
_e121_managed_fail2ban_paths() {
    _e159_managed_fail2ban_paths_base
    printf '%s\n' \
        "$E159_F2B_ACTION_CONF" "$E159_F2B_FILTER" \
        "$E152_F2B_FILTER" "$E159_F2B_NFT_DIAG"
}

_e159_f2b_action_contract() {
    local name table family chain hook priority demand type blocktype port protocol
    local start ban unban expected_ports table_ok=0 chain_ok=0
    E159_F2B_ACTION_NAME=""
    E159_F2B_ACTIONBAN=""
    E159_F2B_ACTIONUNBAN=""
    expected_ports=$(_e116_detect_ssh_ports | sort -nu | paste -sd, -)
    expected_ports=${expected_ports:-22}

    while IFS= read -r name; do
        test -n "$name" || continue
        case "$name" in "$E159_F2B_ACTION_ID"|"$E159_F2B_ACTION_ID"'['*) ;; *) continue ;; esac

        table=$(_e159_f2b_action_property "$name" table | tail -n1 | xargs || true)
        family=$(_e159_f2b_action_property "$name" table_family | tail -n1 | xargs || true)
        chain=$(_e159_f2b_action_property "$name" chain | tail -n1 | xargs || true)
        hook=$(_e159_f2b_action_property "$name" chain_hook | tail -n1 | xargs || true)
        priority=$(_e159_f2b_action_property "$name" chain_priority | tail -n1 | xargs || true)
        demand=$(_e159_f2b_action_property "$name" actionstart_on_demand | tail -n1 | xargs || true)
        type=$(_e159_f2b_action_property "$name" type | tail -n1 | xargs || true)
        blocktype=$(_e159_f2b_action_property "$name" blocktype | tail -n1 | xargs || true)
        port=$(_e159_f2b_action_property "$name" port | tail -n1 | tr -d '"' | xargs || true)
        protocol=$(_e159_f2b_action_property "$name" protocol | tail -n1 | tr -d '"' | xargs || true)
        start=$(_e159_f2b_action_property "$name" actionstart | tr '\n\t' '  ' | sed 's/[[:space:]][[:space:]]*/ /g' || true)
        ban=$(_e159_f2b_action_property "$name" actionban | tr '\n\t' '  ' | sed 's/[[:space:]][[:space:]]*/ /g' || true)
        unban=$(_e159_f2b_action_property "$name" actionunban | tr '\n\t' '  ' | sed 's/[[:space:]][[:space:]]*/ /g' || true)

        table_ok=0; chain_ok=0
        test "$table" = "$E159_NFT_F2B_TABLE" && table_ok=1 || true
        [[ "$start $ban $unban" == *"$E159_NFT_F2B_TABLE"* ]] && table_ok=1 || true
        test "$chain" = "$E159_NFT_F2B_CHAIN" && chain_ok=1 || true
        [[ "$start" == *"$E159_NFT_F2B_CHAIN"* ]] && chain_ok=1 || true
        test "$table_ok" -eq 1 && test "$chain_ok" -eq 1 || continue

        test -z "$family" || test "$family" = inet || continue
        test -z "$hook" || test "$hook" = input || continue
        test -z "$priority" || test "$priority" = -1 || continue
        test -z "$demand" || [[ "$demand" =~ ^(false|0|no)$ ]] || continue
        test -z "$type" || test "$type" = multiport || continue
        test -z "$blocktype" || [[ "$blocktype" == reject* ]] || continue
        test -z "$port" || test "$port" = "$expected_ports" || continue
        test -z "$protocol" || test "$protocol" = tcp || continue
        [[ "$start" == *'add table'* && "$start" == *'add chain'* ]] || continue
        [[ "$ban" == *'add element'* ]] || continue
        [[ "$unban" == *'delete element'* ]] || continue

        E159_F2B_ACTION_NAME="$name"
        E159_F2B_ACTIONBAN="$ban"
        E159_F2B_ACTIONUNBAN="$unban"
        return 0
    done < <(_e159_f2b_action_names)
    return 1
}

# Ban/unban is performed in a subshell with an EXIT cleanup trap.  A signal or
# an intermediate command failure therefore cannot leave an RFC test address
# banned in the live jail.
_e159_f2b_test_family() (
    local family="$1" current="${E152_CURRENT_SSH_IP:-}" candidate test_ip="" i
    local plane_ticket=0 plane_nft=0 cleanup_ok=0
    local -a candidates4=(192.0.2.159 198.51.100.159 203.0.113.159 192.0.2.160)
    local -a candidates6=(2001:db8:159::1 2001:db8:159::2 2001:db8:160::1)
    local -a candidates=()

    case "$family" in
        inet4) candidates=("${candidates4[@]}") ;;
        inet6) candidates=("${candidates6[@]}") ;;
        *) return 1 ;;
    esac

    cleanup_test_ip() {
        local j
        test -n "$test_ip" || return 0
        fail2ban-client set "$E121_F2B_JAIL_NAME" unbanip --report-absent "$test_ip" >/dev/null 2>&1 || true
        for j in {1..20}; do
            _e159_f2b_banned_state "$test_ip" 0 >/dev/null 2>&1 \
                && ! _e159_nft_has_element "$test_ip" && return 0
            sleep 0.1
        done
        return 1
    }
    trap cleanup_test_ip EXIT
    trap 'exit 130' INT TERM HUP

    for candidate in "${candidates[@]}"; do
        test "$candidate" = "$current" && continue
        test_ip="$candidate"
        cleanup_test_ip || { test_ip=""; continue; }
        if ! fail2ban-client set "$E121_F2B_JAIL_NAME" banip "$candidate" >/dev/null 2>&1; then
            cleanup_test_ip || true
            test_ip=""
            continue
        fi
        plane_ticket=0; plane_nft=0
        for i in {1..60}; do
            _e159_f2b_banned_state "$candidate" 1 && plane_ticket=1 || true
            _e159_nft_has_element "$candidate" && plane_nft=1 || true
            test "$plane_ticket" -eq 1 && test "$plane_nft" -eq 1 && break
            sleep 0.2
        done
        test "$plane_ticket" -eq 1 && test "$plane_nft" -eq 1 && break
        cleanup_test_ip || true
        test_ip=""
    done

    if test -z "$test_ip" || test "$plane_ticket" -ne 1 || test "$plane_nft" -ne 1; then
        _e159_f2b_diag fail "$family:ticket=$plane_ticket,nft=$plane_nft,no-converged-test-address" none
        return 1
    fi

    if cleanup_test_ip; then cleanup_ok=1; fi
    if test "$cleanup_ok" -ne 1; then
        _e159_f2b_diag fail "$family:ticket=1,nft=1,cleanup=0" "$test_ip"
        return 1
    fi
    _e159_f2b_diag pass "$family:ticket=1,nft=1,cleanup=1" "$test_ip"
    test_ip=""
    return 0
)

_e152_verify_nft_fail2ban_action() {
    _e159_f2b_action_contract || {
        _e159_f2b_diag fail running-action-does-not-target-e159 none
        error "Fail2ban运行action没有收敛到E159专用action；诊断：$E159_F2B_NFT_DIAG"
        return 1
    }
    _e159_nft_table_contract || {
        _e159_f2b_diag fail nft-base-chain-contract-failed none
        error "E159 nftables表、input hook、reject规则或集合不完整；诊断：$E159_F2B_NFT_DIAG"
        return 1
    }
    _e159_f2b_test_family inet4 || {
        error "Fail2ban IPv4票据与nft集合双平面验证失败；诊断：$E159_F2B_NFT_DIAG"
        return 1
    }
    if _e159_ipv6_ssh_relevant; then
        _e159_f2b_test_family inet6 || {
            error "SSH暴露IPv6，但Fail2ban IPv6双平面验证失败；诊断：$E159_F2B_NFT_DIAG"
            return 1
        }
    fi
}

# The final hot-update gate repeats one live dual-plane cycle.  This catches a
# restart that preserved a Fail2ban ticket but lost the nft action/table.
_e159_ssh_guard_verify_final() {
    local profile mode backend
    profile=$(_e141_sshd_auth_profile 2>/dev/null || true)
    mode=$(sed -n 's/^mode=//p' <<<"$profile" | head -n1)
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    case "$backend:$mode" in
        nft:password-capable)
            _e152_fail2ban_passive_verify \
                && _e152_verify_nft_fail2ban_action \
                && _e152_nft_ssh_check
            ;;
        nft:key-only|nft:non-password|nft:ambiguous)
            _e152_nft_ssh_check
            ;;
        *:password-capable)
            _e152_fail2ban_passive_verify && _e121_verify_ssh_port_guard
            ;;
        *:key-only|*:non-password|*:ambiguous)
            _e142_verify_key_only_guard
            ;;
        *) return 1 ;;
    esac
}

# Retire the old E152 password filter only after the new jail/action has passed
# the live verification performed by the inherited installer.  The outer SSH
# transaction has already snapshotted both files, so rollback remains exact.
if declare -F _e121_install_fail2ban_guard >/dev/null 2>&1; then
    eval "$(declare -f _e121_install_fail2ban_guard | sed '1s/_e121_install_fail2ban_guard/_e159_install_fail2ban_guard_verified_base/')"
fi
_e121_install_fail2ban_guard() {
    local backend
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    _e159_install_fail2ban_guard_verified_base "$@" || return 1
    if test "$backend" = nft; then
        _e159_f2b_action_contract && _e159_nft_table_contract || return 1
        rm -f -- "$E152_F2B_FILTER" 2>/dev/null || true
    fi
}

#------------------------------------------------------------------------------
# Full sysctl source audit.  Vendor/run files are never deleted; they are only
# displayed so the effective precedence and duplicate definitions are visible.
#------------------------------------------------------------------------------
_e159_sysctl_sources() {
    local f real
    local -A seen=()
    for f in /usr/lib/sysctl.d/*.conf /usr/local/lib/sysctl.d/*.conf \
             /lib/sysctl.d/*.conf /run/sysctl.d/*.conf \
             /etc/sysctl.d/*.conf /etc/sysctl.conf; do
        test -e "$f" || continue
        real=$(readlink -f -- "$f" 2>/dev/null || true)
        test -n "$real" || continue
        test -n "${seen[$real]:-}" && continue
        seen[$real]=1
        printf '%s\n' "$real"
    done
}

_e159_all_source_sysctl_audit() {
    local requested="$1" key f n count duplicate_keys=0 source_files=0
    local -a sources=()
    mapfile -t sources < <(_e159_sysctl_sources)
    source_files=${#sources[@]}
    echo
    echo "  全来源持久化审计：$source_files 个唯一文件"
    echo "  范围：/usr/lib、/usr/local/lib、/lib、/run、/etc/sysctl.d、/etc/sysctl.conf"
    echo "  处理原则：vendor/run只读；仅迁移脚本确认拥有的/etc文件。"
    while IFS= read -r key; do
        test -n "$key" || continue
        count=0
        for f in "${sources[@]}"; do
            n=$(awk -F= -v wanted="$key" '
              /^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/ {
                k=$1; gsub(/[[:space:]]/,"",k); if(k==wanted)n++
              }
              END{print n+0}' "$f" 2>/dev/null || echo 0)
            count=$((count+n))
        done
        if (( count > 1 )); then
            duplicate_keys=$((duplicate_keys+1))
            printf '    [重复%u] %s\n' "$count" "$key"
            for f in "${sources[@]}"; do
                grep -nE "^[[:space:]]*${key//./\\.}[[:space:]]*=" "$f" 2>/dev/null \
                    | sed "s#^#      $f:#" || true
            done
        fi
    done < <(_e159_active_keys "$requested")
    echo "  全来源重复键数量：$duplicate_keys"
}

if declare -F _e159_network_audit >/dev/null 2>&1; then
    eval "$(declare -f _e159_network_audit | sed '1s/_e159_network_audit/_e159_network_audit_base/')"
fi
_e159_network_audit() {
    local rc=0 requested
    _e159_network_audit_base || rc=$?
    if test -s "$E159_REQUESTED_CONF"; then
        requested="$E159_REQUESTED_CONF"
    else
        requested=$(_e118_mktemp e159-audit-requested.conf) || return 1
        _e159_full_spec fq 1 31 "$requested" || return 1
    fi
    _e159_all_source_sysctl_audit "$requested"
    return "$rc"
}

#------------------------------------------------------------------------------
# Cloudflare Linux client diagnostics.  2026.4 clients have a documented IPC
# failure mode on some Linux installs; do not collapse that into a generic
# registration failure.
#------------------------------------------------------------------------------
_e140_warp_service_wait() {
    local svc i version status restarted=0
    _e140_warp_cli_exists || {
        _e140_set_stage service 'warp-cli不存在'
        return 1
    }
    svc=$(_e140_warp_service_name)
    systemctl enable --now "$svc" >>"${E140_ACTIVE_LOG:-/dev/null}" 2>&1 || {
        _e140_set_stage service 'warp-svc无法启动'
        return 1
    }
    for i in {1..60}; do
        if systemctl is-active --quiet "$svc" 2>/dev/null && _e140_warp_ipc_ready; then
            return 0
        fi
        if test "$i" = 15 || test "$i" = 35; then
            systemctl restart "$svc" >>"${E140_ACTIVE_LOG:-/dev/null}" 2>&1 || true
            restarted=$((restarted+1))
        fi
        sleep 1
    done
    version=$(_e140_warp_cli_capture --version 2>/dev/null | head -n1 || true)
    status=$(_e140_warp_cli_capture status 2>&1 || true)
    install -d -m 0700 "$E159_DIR" 2>/dev/null || true
    {
        echo "time=$(date -Is 2>/dev/null || date)"
        echo "service=$svc"
        echo "service_state=$(systemctl is-active "$svc" 2>/dev/null || true)"
        echo "version=$version"
        echo "restarts=$restarted"
        echo 'status<<EOF'
        echo "$status"
        echo 'EOF'
        journalctl -u "$svc" -n 120 --no-pager 2>&1 || true
    } >"$E159_WARP_IPC_DIAG" 2>/dev/null || true
    if grep -qE '2026\.4\.' <<<"$version"; then
        _e140_set_stage ipc "Cloudflare Linux 2026.4客户端IPC在60秒内未就绪；诊断：$E159_WARP_IPC_DIAG"
    else
        _e140_set_stage ipc "warp-svc运行但CLI IPC在60秒内未就绪；诊断：$E159_WARP_IPC_DIAG"
    fi
    return 1
}

if declare -F _e140_warp_status >/dev/null 2>&1; then
    eval "$(declare -f _e140_warp_status | sed \
        -e '1s/_e140_warp_status/_e159_warp_status_impl/' \
        -e 's/V199e141/V199e159/g')"
fi
