#------------------------------------------------------------------------------
# Fast structure and release tests.  The E154/E156/E158 tests created one fake
# /proc path per key via many external processes; E159 validates the complete
# spec and a minimal alias fixture instead, so self-test finishes in seconds.
#------------------------------------------------------------------------------
_e159_structure_audit() {
    local total unique duplicate_names dynamic_copies dispatchers menus hotdefs
    total=$(grep -Ec '^[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" || true)
    unique=$(grep -E '^[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" \
        | sed -E 's/[[:space:]]*\(\).*//' | sort -u | wc -l)
    duplicate_names=$(grep -E '^[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" \
        | sed -E 's/[[:space:]]*\(\).*//' | sort | uniq -d | wc -l)
    dynamic_copies=$(grep -Fc 'declare -f' "$SCRIPT_PATH" || true)
    dispatchers=$(grep -Fc 'case "${1:-}" in' "$SCRIPT_PATH" || true)
    menus=$(grep -Ec '^main_menu\(\)' "$SCRIPT_PATH" || true)
    hotdefs=$(grep -Ec '^hot_update_from_legacy\(\)' "$SCRIPT_PATH" || true)
    title 'V199e159：结构与最终绑定审计'
    echo "  函数定义：$total；唯一函数：$unique；重复函数名：$duplicate_names"
    echo "  动态函数复制：$dynamic_copies；dispatcher文本：$dispatchers"
    echo "  main_menu定义：$menus；hot_update_from_legacy定义：$hotdefs"
    echo '  最终网络入口：_e159_network_apply（127请求/125持久控制）'
    echo '  最终SSH入口：_e141_install_ssh_guard（E159共享锁+双平面验证）'
    echo '  最终Xray提交：_e118_commit_config（配置、权限、MainPID、端口、回滚）'
    echo '  最终Fail2ban action：xray-nftables-e159（单一参数组）'
    echo '  说明：历史兼容层仍在文件中；最终dispatcher只有文件末尾一处生效。'
}

_e159_cross_version_audit() {
    title 'V199e159：E127→E159设计演进摘要'
    cat <<'EOF_E159_LINEAGE'
  E127：原始127条请求网络模型、Xray配置生存事务、3天日志与SSH基础。
  E145：引入WARP三模式、系统/网络快照、原生nftables兼容方向。
  E150：网络事务窄化与阶段日志，但曾偏离E127参数模型。
  E151：三档参数实验；不作为E159网络基线。
  E152：恢复10→6→28菜单链；三档网络仍属回归。
  E153：恢复E127完整参数主体，但尚未形成125项不可变量报告。
  E154：建立127请求/125持久控制的请求、有效、兼容报告三件套。
  E156：修正内核别名与计数，但实机Fail2ban nft动作仍可出现票据/集合脱节。
  E158：加入双平面验证、共享锁、Xray联合生存事务；action渲染仍存在嵌套参数组风险。
  E159：保留E158网络/Xray/WARP事务，改用专用Fail2ban action文件并强制票据+nft集合+清理三态收敛。
EOF_E159_LINEAGE
}

_e159_verify_neighbor_queue_semantics() {
    local packet_status bytes_status shadowed packet_actual bytes_actual
    packet_status=$(awk -F'\t' '$1=="net.ipv4.neigh.default.unres_qlen"{print $2;exit}' \
        "$E159_NETWORK_REPORT" 2>/dev/null || true)
    bytes_status=$(awk -F'\t' '$1=="net.ipv4.neigh.default.unres_qlen_bytes"{print $2;exit}' \
        "$E159_NETWORK_REPORT" 2>/dev/null || true)
    shadowed=$(sed -n 's/^shadowed_alias=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1)
    shadowed=${shadowed:-0}
    case "$packet_status:$bytes_status:$shadowed" in
        shadowed-alias:supported:1)
            ! grep -Eq '^[[:space:]]*net\.ipv4\.neigh\.default\.unres_qlen[[:space:]]*=' \
                "$E159_EFFECTIVE_CONF" || return 1
            grep -qx 'net.ipv4.neigh.default.unres_qlen_bytes = 65535' \
                "$E159_EFFECTIVE_CONF" || return 1
            bytes_actual=$(sysctl -n net.ipv4.neigh.default.unres_qlen_bytes 2>/dev/null || true)
            test "$bytes_actual" = 65535
            ;;
        supported:unsupported:0)
            grep -qx 'net.ipv4.neigh.default.unres_qlen = 3000' \
                "$E159_EFFECTIVE_CONF" || return 1
            packet_actual=$(sysctl -n net.ipv4.neigh.default.unres_qlen 2>/dev/null || true)
            test "$packet_actual" = 3000
            ;;
        unsupported:supported:0)
            grep -qx 'net.ipv4.neigh.default.unres_qlen_bytes = 65535' \
                "$E159_EFFECTIVE_CONF" || return 1
            bytes_actual=$(sysctl -n net.ipv4.neigh.default.unres_qlen_bytes 2>/dev/null || true)
            test "$bytes_actual" = 65535
            ;;
        unsupported:unsupported:0)
            ! grep -Eq '^[[:space:]]*net\.ipv4\.neigh\.default\.unres_qlen(_bytes)?[[:space:]]*=' \
                "$E159_EFFECTIVE_CONF"
            ;;
        *)
            error "邻居未解析队列别名状态不一致：packet=$packet_status bytes=$bytes_status shadowed=$shadowed"
            return 1
            ;;
    esac
}

_e159_alias_matrix_test() {
    local d spec effective report root case_name old_proc="" had_proc=0 rc=0
    d=$(mktemp -d /tmp/e159-alias-matrix.XXXXXX) || return 1
    spec="$d/spec.conf"
    cat >"$spec" <<'EOF_E159_ALIAS_SPEC'
net.ipv4.neigh.default.unres_qlen = 3000
net.ipv4.neigh.default.unres_qlen_bytes = 65535
EOF_E159_ALIAS_SPEC
    if test -n "${E159_PROC_ROOT+x}"; then old_proc=$E159_PROC_ROOT; had_proc=1; fi

    for case_name in both packets bytes; do
        root="$d/$case_name/proc"
        mkdir -p "$root/net/ipv4/neigh/default" || { rc=1; break; }
        case "$case_name" in
            both)
                : >"$root/net/ipv4/neigh/default/unres_qlen"
                : >"$root/net/ipv4/neigh/default/unres_qlen_bytes"
                ;;
            packets) : >"$root/net/ipv4/neigh/default/unres_qlen" ;;
            bytes) : >"$root/net/ipv4/neigh/default/unres_qlen_bytes" ;;
        esac
        effective="$d/$case_name/effective.conf"
        report="$d/$case_name/report.tsv"
        E159_PROC_ROOT="$root"
        _e159_build_effective "$spec" "$effective" "$report" || { rc=1; break; }
        case "$case_name" in
            both)
                grep -q $'^net.ipv4.neigh.default.unres_qlen\tshadowed-alias\t3000\t' "$report" \
                  && grep -q $'^net.ipv4.neigh.default.unres_qlen_bytes\tsupported\t65535\t' "$report" \
                  && ! grep -Eq '^net\.ipv4\.neigh\.default\.unres_qlen[[:space:]]*=' "$effective" \
                  || { rc=1; break; }
                ;;
            packets)
                grep -q $'^net.ipv4.neigh.default.unres_qlen\tsupported\t3000\t' "$report" \
                  && grep -q $'^net.ipv4.neigh.default.unres_qlen_bytes\tunsupported\t65535\t' "$report" \
                  && grep -qx 'net.ipv4.neigh.default.unres_qlen = 3000' "$effective" \
                  || { rc=1; break; }
                ;;
            bytes)
                grep -q $'^net.ipv4.neigh.default.unres_qlen\tunsupported\t3000\t' "$report" \
                  && grep -q $'^net.ipv4.neigh.default.unres_qlen_bytes\tsupported\t65535\t' "$report" \
                  && grep -qx 'net.ipv4.neigh.default.unres_qlen_bytes = 65535' "$effective" \
                  || { rc=1; break; }
                ;;
        esac
    done
    if test "$had_proc" -eq 1; then E159_PROC_ROOT=$old_proc; else unset E159_PROC_ROOT; fi
    rm -rf -- "$d"
    return "$rc"
}

_e159_self_test() {
    local rc=0 d spec effective report proc action jail action_dir count unique old_proc had_proc=0
    echo 'V199e159 fast release gate:'
    bash -n "$SCRIPT_PATH" \
        && echo '  [PASS] bash syntax' \
        || { echo '  [FAIL] bash syntax'; rc=1; }
    test "$SCRIPT_VERSION" = 199e159 && test "$E159_VERSION" = 199e159 \
        && echo '  [PASS] release identity' \
        || { echo '  [FAIL] release identity'; rc=1; }

    d=$(mktemp -d /tmp/e159-selftest.XXXXXX) || return 1
    spec="$d/spec.conf"; effective="$d/effective.conf"; report="$d/report.tsv"
    proc="$d/proc"; action_dir="$d/actions"
    mkdir -p "$proc/net/ipv4/route" "$proc/net/ipv4/neigh/default" "$action_dir" || rc=1
    : >"$proc/net/ipv4/route/flush"
    : >"$proc/net/ipv4/neigh/default/unres_qlen"
    : >"$proc/net/ipv4/neigh/default/unres_qlen_bytes"
    while IFS= read -r key; do
        path="$proc/${key//./\/}"
        mkdir -p "$(dirname "$path")" || { rc=1; break; }
        : >"$path" || { rc=1; break; }
    done < <(printf '%s\n' \
      net.core.default_qdisc net.ipv4.tcp_congestion_control \
      net.ipv4.tcp_mtu_probing net.ipv4.tcp_slow_start_after_idle \
      net.core.rmem_default net.core.wmem_default net.core.rmem_max net.core.wmem_max \
      net.ipv4.tcp_rmem net.ipv4.tcp_wmem net.ipv4.tcp_notsent_lowat \
      net.ipv4.tcp_limit_output_bytes net.ipv4.conf.all.rp_filter \
      net.ipv4.conf.default.rp_filter net.ipv4.ip_forward net.ipv4.conf.all.forwarding)

    _e159_full_spec fq 1 31 "$spec" || rc=1
    count=$(grep -Ec '^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=' "$spec" || true)
    unique=$(awk -F= '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{k=$1;gsub(/[[:space:]]/,"",k);print k}' \
        "$spec" | sort -u | wc -l)
    if test "$count" = 127 && test "$unique" = 127 && _e159_spec_validate "$spec"; then
        echo '  [PASS] 127 unique requested entries / 125-control model'
    else
        echo "  [FAIL] requested spec count=$count unique=$unique"; rc=1
    fi
    for line in \
      'net.core.default_qdisc = fq' \
      'net.ipv4.tcp_congestion_control = bbr' \
      'net.core.rmem_default = 7990577' \
      'net.core.rmem_max = 97108868' \
      'net.ipv4.ip_local_port_range = 1024 65535' \
      'net.core.busy_poll = 50' \
      'net.ipv4.tcp_notsent_lowat = 16384' \
      'net.ipv4.tcp_limit_output_bytes = 1310720'; do
        grep -Fqx "$line" "$spec" || { echo "  [FAIL] missing invariant: $line"; rc=1; }
    done
    test "$rc" -ne 0 || echo '  [PASS] E127 requested-value invariants'

    if test -n "${E159_PROC_ROOT+x}"; then old_proc=$E159_PROC_ROOT; had_proc=1; fi
    E159_PROC_ROOT="$proc"
    if _e159_build_effective "$spec" "$effective" "$report" \
      && _e159_network_artifacts_validate "$spec" "$effective" "$report" \
      && grep -q $'^net.ipv4.neigh.default.unres_qlen\tshadowed-alias\t3000\t' "$report" \
      && ! grep -Eq '^net\.ipv4\.neigh\.default\.unres_qlen[[:space:]]*=' "$effective"; then
        echo '  [PASS] alias normalization and artifact closure'
    else
        echo '  [FAIL] effective/report alias closure'; rc=1
    fi
    if test "$had_proc" -eq 1; then E159_PROC_ROOT=$old_proc; else unset E159_PROC_ROOT; fi

    : >"$action_dir/nftables.conf"
    action=$(_e152_choose_banaction_for_backend nft "$action_dir" 2>/dev/null || true)
    _e159_write_nft_action_candidate "$d/action.conf" || rc=1
    E121_F2B_BANACTION="$action"
    jail=$(_e159_f2b_jail_action_lines nft 22,2222 2>/dev/null || true)
    if test "$action" = "$E159_F2B_ACTION_ID" \
      && grep -qx "table = $E159_NFT_F2B_TABLE" "$d/action.conf" \
      && grep -qx "chain = $E159_NFT_F2B_CHAIN" "$d/action.conf" \
      && [[ "$jail" == 'action = xray-nftables-e159[name=xray-sshd-e121,port="22,2222",protocol=tcp]' ]] \
      && [[ "$jail" != *']['* ]]; then
        echo '  [PASS] single-group native nftables action rendering'
    else
        echo '  [FAIL] native nftables action rendering'; rc=1
    fi
    declare -f _e121_select_banaction | grep -q 'E121_F2B_EAGER_ACTION=1' \
      && echo '  [PASS] custom action starts eagerly and is truthfully recorded' \
      || { echo '  [FAIL] custom action eager-state binding'; rc=1; }

    declare -f _e159_f2b_test_family | grep -q 'trap cleanup_test_ip EXIT' \
      && echo '  [PASS] synthetic ban cleanup trap' \
      || { echo '  [FAIL] synthetic ban cleanup trap'; rc=1; }
    declare -f _e159_ssh_guard_verify_final | grep -q '_e152_verify_nft_fail2ban_action' \
      && echo '  [PASS] final SSH gate repeats live dual-plane verification' \
      || { echo '  [FAIL] final SSH gate'; rc=1; }
    { declare -f _e159_sysctl_sources; declare -f _e159_all_source_sysctl_audit; } \
      | grep -q '/usr/lib/sysctl.d' \
      && echo '  [PASS] all-source sysctl audit coverage' \
      || { echo '  [FAIL] sysctl source coverage'; rc=1; }
    declare -f _e140_warp_full_enable | grep -q '_e159_warp_full_enable_base' \
      && ! declare -f _e140_warp_full_enable | grep -q '互斥' \
      && declare -f _e159_network_apply | grep -q '_e140_full_verify' \
      && declare -f _e159_hot_update | grep -q 'warp-full-reconcile' \
      && ! declare -f _e159_hot_update | grep -q 'forwarding要求冲突' \
      && echo '  [PASS] E127 profile and host-full WARP coexist through hot update' \
      || { echo '  [FAIL] host-full/network hot-update compatibility'; rc=1; }
    _e159_alias_matrix_test \
      && echo '  [PASS] neighbor queue alias matrix (both/packets/bytes kernels)' \
      || { echo '  [FAIL] neighbor queue alias matrix'; rc=1; }
    declare -f _e118_commit_config | grep -q '_e127_verify_xray_runtime' \
      && declare -f _e118_commit_config | grep -q 'fix_permissions' \
      && echo '  [PASS] Xray permission/runtime survival transaction' \
      || { echo '  [FAIL] Xray survival gate'; rc=1; }
    grep -q '11) 热更新到V199e159' "$SCRIPT_PATH" \
      && grep -q '22) WARP定向分流' "$SCRIPT_PATH" \
      && grep -q '23) WARP全局分流' "$SCRIPT_PATH" \
      && grep -q '24) Cloudflare系统全隧道' "$SCRIPT_PATH" \
      && echo '  [PASS] visible menu identity and WARP coverage' \
      || { echo '  [FAIL] menu identity'; rc=1; }

    rm -rf -- "$d"
    test "$rc" -eq 0 \
      && echo 'V199e159 result: PASS' \
      || echo 'V199e159 result: FAIL'
    return "$rc"
}

_e159_help() {
    cat <<'EOF_E159_HELP'
V199e159:
  --hot-update              transactionally update an existing E127-E158 system
  --full-network-apply      apply the exact 127-request / 125-control network model
  --full-network-spec       print the requested 127-entry specification
  --full-network-status     runtime, compatibility and all-source duplicate audit
  --self-test               fast non-mutating release and behavior gate
  --structure-audit         final binding and layering-debt report
  --cross-version-audit     E127-E159 design lineage summary
  --optimization-menu       advanced optimization and 28-item micro-control center
  --micro-menu / --micro-28 application/system micro-control transaction
  --summary                 root-only node credential export
  --warp-menu               Google/Meta selective WARP
  --warp-global-menu        Xray-global WARP
  --warp-full-menu          Cloudflare host full tunnel with SSH rollback
EOF_E159_HELP
}

# Custom Fail2ban ownership is removed only after the inherited uninstall has
# actually removed Xray/config; a cancelled prompt leaves everything untouched.
if declare -F do_uninstall >/dev/null 2>&1; then
    eval "$(declare -f do_uninstall | sed '1s/do_uninstall/_e159_uninstall_before_custom_f2b/')"
fi
do_uninstall() {
    local rc=0
    _e159_uninstall_before_custom_f2b "$@" || rc=$?
    if test "$rc" -eq 0 && test ! -e "$XRAY_BIN" && test ! -e "$CONFIG"; then
        rm -f -- "$E159_F2B_ACTION_CONF" "$E159_F2B_FILTER" 2>/dev/null || true
        command -v nft >/dev/null 2>&1 \
            && nft delete table inet "$E159_NFT_F2B_TABLE" >/dev/null 2>&1 || true
        if systemctl is-active --quiet fail2ban.service 2>/dev/null \
          && fail2ban-client -t >/dev/null 2>&1; then
            systemctl restart fail2ban.service >/dev/null 2>&1 || true
        fi
    fi
    return "$rc"
}

# Rebuild visible main-menu identity from the proven final menu body.
if declare -F _e159_main_menu_impl >/dev/null 2>&1; then
    :
elif declare -F _e142_final_main_menu_impl >/dev/null 2>&1; then
    eval "$(declare -f _e142_final_main_menu_impl | sed \
        -e '1s/_e142_final_main_menu_impl/_e159_main_menu_impl/' \
        -e 's/V199e142/V199e159/g' -e 's/V199e141/V199e159/g' \
        -e 's/V199e139/V199e159/g' -e 's/V199e152/V199e159/g' \
        -e 's/统一网络优化参数中心（IPv4-only）/125持久控制\/127请求事务（IPv6策略保留）/g' \
        -e 's/全部受管网络参数与重复定义/127请求逐项审计与重复定义/g')"
fi
main_menu() { _e159_main_menu_impl; }

#==============================================================================
#==============================================================================
# V199e165 FINAL MAINTENANCE RELEASE
#
# This is a full, directly executable release layered inside one standalone
# file.  The proven E159 127-request/125-control network owner is deliberately
# retained to avoid creating a second sysctl/systemd owner.  E165 replaces the
# failed Fail2ban/nftables integration with the Fail2ban 1.0.2 native nftables action overlay
# and changes the production gate to ticket -> nft set -> unban cleanup truth.
#==============================================================================
readonly E165_VERSION="199e165"
readonly E165_DIR="$CONFIG_DIR/e165"
readonly E165_SELF_PATH="$SCRIPT_DIR/ex199e165.sh"
readonly E165_LATEST_PATH="$SCRIPT_DIR/ex199e_latest.sh"
readonly E165_TX_ROOT="/var/backups/xray-e165"
readonly E165_HOT_LOG="/var/log/xray/e165/hot-update-last.log"
readonly E165_CRITICAL_MARKER="$E165_DIR/CRITICAL_RECOVERY_REQUIRED.env"
readonly E165_RELEASE_AUDIT="$E165_DIR/release-audit.env"

readonly E165_NFT_F2B_TABLE="f2b-e165"
readonly E165_NFT_F2B_CHAIN="f2b-e165-input"
readonly E165_NFT_F2B_SET4="f2b-e165-v4"
readonly E165_NFT_F2B_SET6="f2b-e165-v6"
readonly E165_F2B_HELPER="/usr/local/libexec/xray-f2b-e165-inspect"
readonly E165_F2B_ACTION_ID="xray-nftables-e165"
readonly E165_F2B_ACTION_CONF="/etc/fail2ban/action.d/xray-nftables-e165.conf"
readonly E165_F2B_FILTER_NAME="xray-sshd-password-e165"
readonly E165_F2B_FILTER="/etc/fail2ban/filter.d/xray-sshd-password-e165.conf"
readonly E165_F2B_LEGACY_DISABLE="/etc/fail2ban/jail.d/zzzz-xray-disable-legacy-sshd-e165.local"
readonly E165_F2B_DIAG="/var/log/xray/e165/fail2ban-nft-last.log"

# Failed/partial E163 assets are treated as legacy state.  They are included in
# snapshots and removed only after the E165 live closure succeeds.
readonly E165_LEGACY_E163_NFT_TABLE="f2b-e163"
readonly E165_LEGACY_E163_HELPER="/usr/local/libexec/xray-f2b-e163-nft"
readonly E165_LEGACY_E163_ACTION_CONF="/etc/fail2ban/action.d/xray-nftables-e163.conf"
readonly E165_LEGACY_E163_FILTER="/etc/fail2ban/filter.d/xray-sshd-password-e163.conf"
readonly E165_LEGACY_E163_DISABLE="/etc/fail2ban/jail.d/zzzz-xray-disable-legacy-sshd-e163.local"
readonly E165_LEGACY_E163_DIAG="/var/log/xray/e163/fail2ban-nft-last.log"

_e165_prepare() {
    _e159_prepare || return 1
    install -d -m 0700 "$E165_DIR" "$E165_TX_ROOT" "$(dirname "$E165_HOT_LOG")" || return 1
    install -d -m 0755 "$SCRIPT_DIR" "$(dirname "$E165_F2B_HELPER")" || return 1
}

_e165_new_tx() {
    local name="${1:-tx}" d
    _e165_prepare || return 1
    name=$(printf '%s' "$name" | tr -c 'A-Za-z0-9_.-' '_')
    d="$E165_TX_ROOT/${name}-$(date +%Y%m%d_%H%M%S)-$$-$RANDOM"
    install -d -m 0700 "$d" || return 1
    printf '%s\n' "$d"
}

_e165_prune_system_tx() {
    local keep="${XRAY_E165_TX_KEEP:-12}" protected=" " p real row n=0
    [[ "$keep" =~ ^[0-9]+$ ]] && (( keep >= 3 && keep <= 100 )) || keep=12
    for p in "$@"; do
        real=$(readlink -f -- "$p" 2>/dev/null || true)
        test -z "$real" || protected+="$real "
    done
    if test -s "$E165_CRITICAL_MARKER"; then
        while IFS= read -r p; do
            real=$(readlink -f -- "$p" 2>/dev/null || true)
            test -z "$real" || protected+="$real "
        done < <(sed -nE 's/^(system_backup|network_backup|core_backup|ssh_backup)=//p' "$E165_CRITICAL_MARKER")
    fi
    test -d "$E165_TX_ROOT" || return 0
    while IFS=$'\t' read -r _ row; do
        test -n "$row" || continue
        n=$((n+1))
        test "$n" -le "$keep" && continue
        real=$(readlink -f -- "$row" 2>/dev/null || true)
        case "$real" in "$E165_TX_ROOT"/*) ;; *) continue ;; esac
        [[ "$protected" == *" $real "* ]] && continue
        rm -rf -- "${real:?}" 2>/dev/null || true
    done < <(find "$E165_TX_ROOT" -mindepth 1 -maxdepth 1 -type d -printf '%T@\t%p\n' 2>/dev/null | sort -nr)
}

_e165_install_self() {
    local tx target snap tmp failed=0
    local -a targets=("$SYMLINK" "$E165_SELF_PATH" "$E165_LATEST_PATH")
    test -r "$SCRIPT_PATH" || return 1
    _e165_prepare || return 1
    tx=$(_e165_new_tx self-install) || return 1
    for target in "${targets[@]}"; do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
        _e135_snapshot_file "$target" "$snap" || return 1
    done
    for target in "${targets[@]}"; do
        install -d -m 0755 "$(dirname -- "$target")" || { failed=1; break; }
        tmp="$target.e165-new.$$"
        install -m 0755 "$SCRIPT_PATH" "$tmp" || { rm -f -- "$tmp"; failed=1; break; }
        mv -f -- "$tmp" "$target" || { rm -f -- "$tmp"; failed=1; break; }
        cmp -s "$SCRIPT_PATH" "$target" || { failed=1; break; }
    done
    if test "$failed" -ne 0; then
        for target in "${targets[@]}"; do
            snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
            _e135_restore_file "$target" "$snap" || true
        done
        return 1
    fi
    hash -r 2>/dev/null || true
}

_e165_write_version() {
    local tmp
    _e165_prepare || return 1
    tmp=$(_e118_mktemp e165-version) || return 1
    printf '%s\n' "$E165_VERSION" >"$tmp" || return 1
    _e118_atomic_install "$tmp" "$SCRIPT_VERSION_FILE" 0600
}

# Historical callers still use the E159 function names.  Redirect those future
# calls to the complete E165 file/version, rather than reinstalling E159 paths.
_e159_install_self() { _e165_install_self "$@"; }
_e159_write_version() { _e165_write_version "$@"; }

_e165_write_nft_helper_candidate() {
    local out="$1"
    cat >"$out" <<'EOF_E165_NFT_INSPECTOR'
#!/usr/bin/env bash
set -euo pipefail
IFS=$' \n\t'
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
readonly TABLE="f2b-e165"
readonly CHAIN="f2b-e165-input"
readonly LOCK="/run/lock/xray-f2b-e165-inspect.lock"

err() { printf 'xray-f2b-e165-inspect: %s\n' "$*" >&2; }
need() { command -v "$1" >/dev/null 2>&1 || { err "missing command: $1"; return 1; }; }

normalize_ports() {
    local raw="${1:-}" p
    raw=${raw//\"/}; raw=${raw//\'/}; raw=${raw//[[:space:]]/}
    [[ "$raw" =~ ^[0-9]+(,[0-9]+)*$ ]] || return 1
    while IFS= read -r p; do
        [[ "$p" =~ ^[0-9]+$ ]] || return 1
        (( p >= 1 && p <= 65535 )) || return 1
    done < <(tr ',' '\n' <<<"$raw")
    tr ',' '\n' <<<"$raw" | awk 'NF&&!seen[$0]++' | sort -n | paste -sd, -
}

python_bin() {
    local x
    for x in /usr/bin/python3 "$(command -v python3 2>/dev/null || true)" \
             "$(command -v fail2ban-python 2>/dev/null || true)" \
             "$(command -v fail2ban-python3 2>/dev/null || true)"; do
        test -n "$x" && test -x "$x" && { printf '%s\n' "$x"; return 0; }
    done
    return 1
}

canonical_ip() {
    local ip="${1:-}" py
    py=$(python_bin) || return 1
    "$py" - "$ip" <<'PY_E165_IP'
import ipaddress, sys
try:
    obj = ipaddress.ip_address(sys.argv[1])
except Exception:
    raise SystemExit(1)
print(obj.compressed)
PY_E165_IP
}

nft_text_table() {
    if nft --help 2>&1 | grep -q -- '--numeric-priority'; then
        nft -n -y list table inet "$TABLE"
    else
        nft -n list table inet "$TABLE"
    fi
}

chain_metadata_ok() {
    local json py text
    py=$(python_bin) || return 1
    if json=$(nft -j list chain inet "$TABLE" "$CHAIN" 2>/dev/null); then
        "$py" - /dev/fd/3 "$CHAIN" 3<<<"$json" <<'PY_E165_CHAIN' && return 0
import json, sys
path=sys.argv[1]
name=sys.argv[2]
try:
    with open(path, 'r', encoding='utf-8') as fh:
        data=json.load(fh)
except Exception:
    raise SystemExit(1)
for item in data.get('nftables', []):
    ch=item.get('chain') if isinstance(item, dict) else None
    if not isinstance(ch, dict) or ch.get('name') != name:
        continue
    prio=ch.get('prio', ch.get('priority'))
    try:
        prio_ok=int(prio) == -1
    except Exception:
        prio_ok=str(prio).replace(' ', '') in ('-1', 'filter-1')
    if ch.get('hook') == 'input' and ch.get('type', 'filter') == 'filter' and prio_ok:
        raise SystemExit(0)
raise SystemExit(1)
PY_E165_CHAIN
    fi
    if nft --help 2>&1 | grep -q -- '--numeric-priority'; then
        text=$(nft -n -y list chain inet "$TABLE" "$CHAIN" 2>/dev/null) || return 1
        grep -Eq 'type[[:space:]]+filter[[:space:]]+hook[[:space:]]+input[[:space:]]+priority[[:space:]]+-1([[:space:]]*;|[[:space:]])' <<<"$text"
    else
        # Old nft builds can render numeric priorities symbolically.  Hook and
        # owned-rule truth remain hard gates; display spelling is diagnostic.
        text=$(nft -n list chain inet "$TABLE" "$CHAIN" 2>/dev/null) || return 1
        grep -Eq 'type[[:space:]]+filter[[:space:]]+hook[[:space:]]+input' <<<"$text"
    fi
}

contract() {
    local ports="${1:-}" protocol="${2:-tcp}" table p
    ports=$(normalize_ports "$ports") || return 1
    test "$protocol" = tcp || return 1
    nft list table inet "$TABLE" >/dev/null 2>&1 || return 1
    nft list chain inet "$TABLE" "$CHAIN" >/dev/null 2>&1 || return 1
    chain_metadata_ok || return 1
    table=$(nft_text_table 2>/dev/null) || return 1
    grep -Eq 'set[[:space:]]+"?addr6?-set-' <<<"$table" || return 1
    grep -Eq '@addr6?-set-' <<<"$table" || return 1
    grep -Eq 'tcp[[:space:]]+dport' <<<"$table" || return 1
    grep -qw reject <<<"$table" || return 1
    for p in ${ports//,/ }; do
        awk -v p="$p" '
          /tcp[[:space:]]+dport/ && /@addr(6)?-set-/ && /reject/ {
            line=$0
            sub(/^.*tcp[[:space:]]+dport[[:space:]]+/,"",line)
            sub(/[[:space:]]+ip6?[[:space:]]+saddr.*/,"",line)
            gsub(/[^0-9]+/," ",line)
            n=split(line,a,/ +/)
            for(i=1;i<=n;i++) if(a[i]==p) found=1
          }
          END{exit(found?0:1)}
        ' <<<"$table" || return 1
    done
}

contains_ip() {
    local canon json py text
    canon=$(canonical_ip "${1:-}") || return 1
    py=$(python_bin) || return 1
    if json=$(nft -j list table inet "$TABLE" 2>/dev/null); then
        "$py" - /dev/fd/3 "$canon" 3<<<"$json" <<'PY_E165_CONTAINS' && return 0
import json, sys
path=sys.argv[1]
needle=sys.argv[2]
try:
    with open(path, 'r', encoding='utf-8') as fh:
        data=json.load(fh)
except Exception:
    raise SystemExit(1)
def walk(v):
    if isinstance(v, str):
        return v == needle
    if isinstance(v, list):
        return any(walk(x) for x in v)
    if isinstance(v, dict):
        return any(walk(x) for x in v.values())
    return False
raise SystemExit(0 if walk(data) else 1)
PY_E165_CONTAINS
    fi
    text=$(nft_text_table 2>/dev/null) || return 1
    tr '{};,\t ' '\n' <<<"$text" | grep -Fxq -- "$canon"
}

stop_table() {
    nft delete table inet "$TABLE" >/dev/null 2>&1 || true
    ! nft list table inet "$TABLE" >/dev/null 2>&1
}

main() {
    local cmd="${1:-}"
    need nft || return 1
    if test -e /run/lock || test -L /run/lock; then
        test -d /run/lock && test -x /run/lock || return 1
    else
        install -d -m 0755 /run/lock || return 1
    fi
    exec 9>"$LOCK"
    flock -w 30 9 || { err 'lock timeout'; return 1; }
    case "$cmd" in
        check) contract "${2:-}" "${3:-tcp}" ;;
        contains) contains_ip "${2:-}" ;;
        status)
            echo "table=$TABLE"
            echo "chain=$CHAIN"
            nft_text_table
            ;;
        stop) stop_table ;;
        *) err "usage: $0 {check PORTS tcp|contains IP|status|stop}"; return 2 ;;
    esac
}
main "$@"
EOF_E165_NFT_INSPECTOR
    chmod 0755 "$out" || return 1
    bash -n "$out"
}

_e165_write_f2b_action_candidate() {
    local out="$1"
    cat >"$out" <<EOF_E165_ACTION
[INCLUDES]
before = nftables.conf

[Init]
type = multiport
table = $E165_NFT_F2B_TABLE
table_family = inet
chain = $E165_NFT_F2B_CHAIN
chain_type = filter
chain_hook = input
chain_priority = -1
blocktype = reject
actionstart_on_demand = false
EOF_E165_ACTION
}

_e165_write_f2b_filter_candidate() {
    local out="$1"
    cat >"$out" <<'EOF_E165_FILTER'
[INCLUDES]
before = common.conf

[Definition]
_daemon = sshd(?:-session)?
# Count one final authentication-failure record per attempt.  Matching the
# preceding generic PAM record as well would turn maxretry=2 into one attempt.
failregex = ^%(__prefix_line)sFailed password for (?:invalid user )?.*? from <HOST>(?: port \d+)?(?: ssh\d*)?(?: \[preauth\])?\s*$
            ^%(__prefix_line)sFailed keyboard-interactive/pam for (?:invalid user )?.*? from <HOST>(?: port \d+)?(?: ssh\d*)?(?: \[preauth\])?\s*$
ignoreregex =
journalmatch = _SYSTEMD_UNIT=sshd.service + _SYSTEMD_UNIT=ssh.service + _COMM=sshd + _COMM=sshd-session
EOF_E165_FILTER
}

_e165_write_legacy_disable_candidate() {
    local out="$1"
    cat >"$out" <<EOF_E165_DISABLE
# Managed by ex199e165.  The script-owned $E121_F2B_JAIL_NAME jail is the sole
# SSH password-failure owner, avoiding duplicate counters/actions and stale
# distribution sshd jails with missing log paths.
[sshd]
enabled = false

[sshd-ddos]
enabled = false
EOF_E165_DISABLE
}

if declare -F _e152_choose_banaction_for_backend >/dev/null 2>&1; then
    eval "$(declare -f _e152_choose_banaction_for_backend | sed '1s/_e152_choose_banaction_for_backend/_e165_choose_banaction_base/')"
fi
_e152_choose_banaction_for_backend() {
    local backend="$1" action_dir="${2:-/etc/fail2ban/action.d}"
    if test "$backend" = nft; then
        command -v nft >/dev/null 2>&1 || return 1
        test -f "$action_dir/nftables.conf" || return 1
        printf '%s\n' "$E165_F2B_ACTION_ID"
        return 0
    fi
    _e165_choose_banaction_base "$backend" "$action_dir"
}

if declare -F _e121_select_banaction >/dev/null 2>&1; then
    eval "$(declare -f _e121_select_banaction | sed '1s/_e121_select_banaction/_e165_select_banaction_base/')"
fi
_e121_select_banaction() {
    local backend
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    if test "$backend" = nft; then
        command -v nft >/dev/null 2>&1 || { error 'nftables后端不可读。'; return 1; }
        E152_F2B_BACKEND_KIND=nft
        E121_F2B_BANACTION="$E165_F2B_ACTION_ID"
        E121_F2B_EAGER_ACTION=1
        info "原生nftables：使用E165官方nftables action与事务表$E165_NFT_F2B_TABLE。"
        return 0
    fi
    _e165_select_banaction_base "$@"
}

_e165_f2b_jail_action_lines() {
    local backend="$1" csv="$2"
    [[ "$csv" =~ ^[0-9]+(,[0-9]+)*$ ]] || return 1
    case "$backend" in
        nft)
            printf 'action = %s[name=%s,port="%s",protocol=tcp]\n' \
                "$E165_F2B_ACTION_ID" "$E121_F2B_JAIL_NAME" "$csv"
            ;;
        iptables)
            echo 'chain = INPUT'
            test -z "${E121_F2B_BANACTION:-}" || echo "banaction = $E121_F2B_BANACTION"
            ;;
        *)
            test -z "${E121_F2B_BANACTION:-}" || echo "banaction = $E121_F2B_BANACTION"
            ;;
    esac
}
_e159_f2b_jail_action_lines() { _e165_f2b_jail_action_lines "$@"; }

_e121_write_fail2ban_candidates() {
    local ports csv jail_tmp db_tmp filter_tmp action_tmp helper_tmp disable_tmp ignore backend
    ports=$(_e116_detect_ssh_ports)
    test -n "$ports" || ports=22
    csv=$(printf '%s\n' $ports | sort -nu | paste -sd, -)
    [[ "$csv" =~ ^[0-9]+(,[0-9]+)*$ ]] || { error "SSH端口列表非法：$csv"; return 1; }
    ignore=$(_e152_collect_ignoreip "${E152_CURRENT_SSH_IP:-}")
    backend=${E152_F2B_BACKEND_KIND:-$(_e152_firewall_backend 2>/dev/null || echo none)}

    install -d -m 0755 /etc/fail2ban/action.d /etc/fail2ban/filter.d \
        /etc/fail2ban/jail.d /etc/fail2ban/fail2ban.d /var/lib/fail2ban \
        "$(dirname "$E165_F2B_HELPER")" || return 1

    jail_tmp=$(_e118_mktemp fail2ban-e165-jail) || return 1
    db_tmp=$(_e118_mktemp fail2ban-e165-db) || return 1
    filter_tmp=$(_e118_mktemp fail2ban-e165-filter) || return 1
    action_tmp=$(_e118_mktemp fail2ban-e165-action) || return 1
    helper_tmp=$(_e118_mktemp fail2ban-e165-helper) || return 1
    disable_tmp=$(_e118_mktemp fail2ban-e165-disable) || return 1

    _e165_write_nft_helper_candidate "$helper_tmp" || return 1
    _e165_write_f2b_action_candidate "$action_tmp" || return 1
    _e165_write_f2b_filter_candidate "$filter_tmp" || return 1
    _e165_write_legacy_disable_candidate "$disable_tmp" || return 1

    cat >"$db_tmp" <<'EOF_E165_DB'
[Definition]
allowipv6 = auto
dbfile = /var/lib/fail2ban/fail2ban.sqlite3
dbpurgeage = 3d
logtarget = /var/log/xray-fail2ban.log
loglevel = INFO
EOF_E165_DB

    {
        echo "[$E121_F2B_JAIL_NAME]"
        echo 'enabled = true'
        echo "filter = $E165_F2B_FILTER_NAME"
        echo "backend = $E121_F2B_BACKEND"
        test "$E121_F2B_BACKEND" = systemd || echo "logpath = $E121_F2B_LOGPATH"
        echo "port = $csv"
        echo 'protocol = tcp'
        echo 'usedns = no'
        test -z "$ignore" || echo "ignoreip = $ignore"
        _e165_f2b_jail_action_lines "$backend" "$csv" || return 1
        echo 'maxretry = 2'
        echo 'findtime = 86400'
        echo 'bantime = 129600'
    } >"$jail_tmp" || return 1

    if test "$backend" = nft; then
        _e121_atomic_install "$helper_tmp" "$E165_F2B_HELPER" 0755 || return 1
        _e121_atomic_install "$action_tmp" "$E165_F2B_ACTION_CONF" 0644 || return 1
    fi
    _e121_atomic_install "$filter_tmp" "$E165_F2B_FILTER" 0644 || return 1
    _e121_atomic_install "$disable_tmp" "$E165_F2B_LEGACY_DISABLE" 0644 || return 1
    _e121_atomic_install "$db_tmp" "$E121_F2B_DB_CONF" 0644 || return 1
    _e121_atomic_install "$jail_tmp" "$E121_F2B_JAIL" 0644 || return 1
}

if declare -F _e121_managed_fail2ban_paths >/dev/null 2>&1; then
    eval "$(declare -f _e121_managed_fail2ban_paths | sed '1s/_e121_managed_fail2ban_paths/_e165_managed_fail2ban_paths_base/')"
fi
_e121_managed_fail2ban_paths() {
    _e165_managed_fail2ban_paths_base
    printf '%s\n' \
        "$E165_F2B_HELPER" "$E165_F2B_ACTION_CONF" "$E165_F2B_FILTER" \
        "$E165_F2B_LEGACY_DISABLE" "$E165_F2B_DIAG" \
        "$E165_LEGACY_E163_HELPER" "$E165_LEGACY_E163_ACTION_CONF" \
        "$E165_LEGACY_E163_FILTER" "$E165_LEGACY_E163_DISABLE" "$E165_LEGACY_E163_DIAG" \
        "$E159_F2B_ACTION_CONF" "$E159_F2B_FILTER" "$E152_F2B_FILTER"
}

_e165_nft_tables() {
    printf '%s\n' "$E152_NFT_F2B_TABLE" "$E159_NFT_F2B_TABLE" \
        "$E165_LEGACY_E163_NFT_TABLE" "$E165_NFT_F2B_TABLE" \
        | awk 'NF&&!seen[$0]++'
}

_e152_nft_ssh_tx_begin() {
    local tx p key table label
    tx=$(_e152_new_tx ssh-native-e165) || return 1
    install -d -m 0700 "$tx/files" || return 1
    : >"$tx/files.manifest" || return 1
    while IFS= read -r p; do
        test -n "$p" || continue
        key=$(printf '%s' "$p" | sha256sum | awk '{print $1}')
        printf '%s|%s\n' "$p" "$key" >>"$tx/files.manifest" || return 1
        _e135_snapshot_file "$p" "$tx/files/$key" || return 1
    done < <(_e121_managed_fail2ban_paths | awk 'NF&&!seen[$0]++')
    : >"$tx/services.env" || return 1
    for p in fail2ban.service xray-ssh-port-guard-e121.service xray-ssh-port-guard-e121.timer \
        xray-ssh-native-e152.service xray-ssh-native-e152.timer \
        xray-ssh-auth-audit-e152.service xray-ssh-auth-audit-e152.timer rsyslog.service; do
        _e152_unit_state_line "$p" >>"$tx/services.env" || return 1
    done
    while IFS= read -r table; do
        label=$(printf '%s' "$table" | tr -c 'A-Za-z0-9_.-' '_')
        if command -v nft >/dev/null 2>&1 \
          && nft list table inet "$table" >"$tx/$label.nft" 2>/dev/null; then
            : >"$tx/$label.present"
        else
            : >"$tx/$label.absent"
        fi
    done < <(_e165_nft_tables)
    (cd "$tx" && find . -type f ! -name ssh-seal.sha256 ! -name COMMITTED \
        -print0 | sort -z | xargs -0 sha256sum >ssh-seal.sha256) || return 1
    test -s "$tx/ssh-seal.sha256" || return 1
    printf '%s\n' "$tx"
}

_e152_nft_ssh_tx_rollback() {
    local tx="$1" p key unit enabled active table label rc=0
    test -d "$tx" && test -s "$tx/files.manifest" && test -s "$tx/services.env" \
        && test -s "$tx/ssh-seal.sha256" \
        && (cd "$tx" && sha256sum -c ssh-seal.sha256 >/dev/null 2>&1) || return 1
    systemctl stop xray-ssh-native-e152.timer xray-ssh-native-e152.service \
        xray-ssh-auth-audit-e152.timer xray-ssh-auth-audit-e152.service \
        fail2ban.service >/dev/null 2>&1 || true
    while IFS= read -r table; do
        nft delete table inet "$table" >/dev/null 2>&1 || true
    done < <(_e165_nft_tables)
    while IFS='|' read -r p key; do
        test -n "$p" && test -n "$key" || continue
        _e135_restore_file "$p" "$tx/files/$key" || rc=1
    done <"$tx/files.manifest"
    systemctl daemon-reload >/dev/null 2>&1 || rc=1
    while IFS='|' read -r unit enabled active; do
        test -n "$unit" || continue
        if test "$enabled" = 1; then systemctl enable "$unit" >/dev/null 2>&1 || rc=1
        else systemctl disable "$unit" >/dev/null 2>&1 || true; fi
    done <"$tx/services.env"
    while IFS='|' read -r unit enabled active; do
        test -n "$unit" || continue
        if test "$active" = 1; then
            if test "$unit" = fail2ban.service; then systemctl restart "$unit" >/dev/null 2>&1 || rc=1
            else systemctl start "$unit" >/dev/null 2>&1 || rc=1; fi
        else systemctl stop "$unit" >/dev/null 2>&1 || true; fi
    done <"$tx/services.env"

    # Restore exact pre-transaction nft contents after service restoration.
    # A service restart may have recreated an empty/current-generation table;
    # delete it first so the sealed snapshot, including banned elements, wins.
    while IFS= read -r table; do
        local restore_batch current_present=0
        label=$(printf '%s' "$table" | tr -c 'A-Za-z0-9_.-' '_')
        nft list table inet "$table" >/dev/null 2>&1 && current_present=1 || true
        if test -e "$tx/$label.present"; then
            restore_batch=$(mktemp /run/xray-e165-restore.XXXXXX) || { rc=1; continue; }
            {
                test "$current_present" -eq 0 || echo "delete table inet $table"
                cat "$tx/$label.nft"
            } >"$restore_batch"
            nft -f "$restore_batch" >/dev/null 2>&1 || rc=1
            rm -f -- "$restore_batch"
            nft list table inet "$table" >/dev/null 2>&1 || rc=1
        else
            nft delete table inet "$table" >/dev/null 2>&1 || true
            nft list table inet "$table" >/dev/null 2>&1 && rc=1 || true
        fi
    done < <(_e165_nft_tables)
    if systemctl is-active --quiet fail2ban.service 2>/dev/null; then
        fail2ban-client ping >/dev/null 2>&1 || rc=1
    fi
    return "$rc"
}

_e165_detect_ports_csv() {
    local ports
    ports=$(_e116_detect_ssh_ports 2>/dev/null || true)
    test -n "$ports" || ports=22
    printf '%s\n' $ports | sort -nu | paste -sd, -
}

_e165_f2b_action_present() {
    local raw
    raw=$(fail2ban-client get "$E121_F2B_JAIL_NAME" actions 2>/dev/null) || return 1
    grep -Fq -- "$E165_F2B_ACTION_ID" <<<"$raw"
}

_e165_helper_check() {
    local csv
    test -x "$E165_F2B_HELPER" || return 1
    csv=$(_e165_detect_ports_csv)
    [[ "$csv" =~ ^[0-9]+(,[0-9]+)*$ ]] || return 1
    "$E165_F2B_HELPER" check "$csv" tcp >/dev/null 2>&1
}

_e165_nft_has_element() {
    test -x "$E165_F2B_HELPER" || return 1
    "$E165_F2B_HELPER" contains "$1" >/dev/null 2>&1
}

_e165_f2b_banned_state() {
    local ip="$1" expected="$2" out token found=0
    out=$(fail2ban-client get "$E121_F2B_JAIL_NAME" banned "$ip" 2>/dev/null | tail -n1 | xargs || true)
    case "$out" in 0|1) test "$out" = "$expected"; return $? ;; esac
    out=$(fail2ban-client get "$E121_F2B_JAIL_NAME" banip ',' 2>/dev/null) \
        || out=$(fail2ban-client get "$E121_F2B_JAIL_NAME" banip 2>/dev/null) \
        || return 1
    while IFS= read -r token; do
        token=${token#[}; token=${token%]}; token=${token#\'}; token=${token%\'}
        token=${token#\"}; token=${token%\"}
        test "$token" = "$ip" && { found=1; break; }
    done < <(printf '%s\n' "$out" | tr ',[:space:]' '\n' | awk 'NF')
    test "$found" -eq "$expected"
}

_e165_f2b_diag() {
    local result="${1:-unknown}" detail="${2:-}" test_ip="${3:-none}" action_name
    install -d -m 0700 "$(dirname "$E165_F2B_DIAG")" 2>/dev/null || return 0
    {
        echo "time=$(date -Is 2>/dev/null || date)"
        echo "result=$result"
        printf 'detail=%s\n' "$detail"
        echo "test_ip=$test_ip"
        echo "jail=$E121_F2B_JAIL_NAME"
        echo "expected_action=$E165_F2B_ACTION_ID"
        echo "expected_table=inet/$E165_NFT_F2B_TABLE"
        echo "expected_chain=$E165_NFT_F2B_CHAIN"
        echo '--- fail2ban version'
        fail2ban-client --version 2>&1 || true
        echo '--- jail status'
        fail2ban-client status "$E121_F2B_JAIL_NAME" 2>&1 || true
        echo '--- banned list'
        fail2ban-client get "$E121_F2B_JAIL_NAME" banip ',' 2>&1 || true
        echo '--- actions raw'
        fail2ban-client get "$E121_F2B_JAIL_NAME" actions 2>&1 || true
        echo '--- action properties (diagnostic only)'
        while IFS= read -r action_name; do
            test -n "$action_name" || continue
            echo "action=$action_name"
            fail2ban-client get "$E121_F2B_JAIL_NAME" action "$action_name" actionstart 2>&1 || true
            fail2ban-client get "$E121_F2B_JAIL_NAME" action "$action_name" actioncheck 2>&1 || true
            fail2ban-client get "$E121_F2B_JAIL_NAME" action "$action_name" actionban 2>&1 || true
            fail2ban-client get "$E121_F2B_JAIL_NAME" action "$action_name" actionunban 2>&1 || true
        done < <(fail2ban-client get "$E121_F2B_JAIL_NAME" actions 2>/dev/null \
            | awk 'NF{line=$0} END{print line}' | tr "[],'\"" '     ' \
            | tr '[:space:]' '\n' | grep -E '^[A-Za-z0-9_.:-]+$' | awk 'NF&&!seen[$0]++' || true)
        echo '--- jail config'
        sed -n '1,260p' "$E121_F2B_JAIL" 2>&1 || true
        echo '--- action overlay'
        sed -n '1,220p' "$E165_F2B_ACTION_CONF" 2>&1 || true
        echo '--- fail2ban config dump matches'
        fail2ban-client -d 2>&1 | grep -E "$E121_F2B_JAIL_NAME|$E165_F2B_ACTION_ID|$E165_NFT_F2B_TABLE|addaction|actionban|actioncheck" | tail -n 260 || true
        echo '--- read-only nft inspector'
        "$E165_F2B_HELPER" status 2>&1 || true
        echo '--- all f2b nft tables'
        nft list tables 2>&1 | grep -E '(^|[[:space:]])f2b' || true
        echo '--- fail2ban journal tail'
        journalctl -u fail2ban.service --no-pager -n 220 2>&1 || true
        echo '--- fail2ban file tail'
        tail -n 220 /var/log/xray-fail2ban.log 2>&1 || true
    } >"$E165_F2B_DIAG" 2>&1
    chmod 0600 "$E165_F2B_DIAG" 2>/dev/null || true
}
_e159_f2b_diag() { _e165_f2b_diag "$@"; }

_e165_f2b_cleanup_ip() {
    local ip="$1" i
    fail2ban-client set "$E121_F2B_JAIL_NAME" unbanip "$ip" >/dev/null 2>&1 || true
    for i in {1..50}; do
        _e165_f2b_banned_state "$ip" 0 >/dev/null 2>&1 \
            && ! _e165_nft_has_element "$ip" && return 0
        sleep 0.1
    done
    return 1
}

_e165_f2b_test_family() (
    local family="$1" current="${E152_CURRENT_SSH_IP:-}" candidate test_ip="" i
    local ticket=0 nft_plane=0 cleanup_ok=0 ban_rc=0 ban_out="" last_detail="no-candidate"
    local -a candidates4=(192.0.2.165 198.51.100.165 203.0.113.165 192.0.2.166 198.51.100.166)
    local -a candidates6=(2001:db8:165::1 2001:db8:165::2 2001:db8:166::1)
    local -a candidates=()
    case "$family" in inet4) candidates=("${candidates4[@]}") ;; inet6) candidates=("${candidates6[@]}") ;; *) return 1 ;; esac

    cleanup() { test -z "$test_ip" || _e165_f2b_cleanup_ip "$test_ip" || true; }
    trap cleanup EXIT
    trap 'exit 130' INT TERM HUP

    for candidate in "${candidates[@]}"; do
        test "$candidate" = "$current" && continue
        test_ip="$candidate"
        if ! _e165_f2b_cleanup_ip "$candidate"; then
            last_detail="$candidate:pre-cleanup-failed"
            test_ip=""
            continue
        fi
        set +e
        ban_out=$(fail2ban-client set "$E121_F2B_JAIL_NAME" banip "$candidate" 2>&1)
        ban_rc=$?
        set -e
        ticket=0; nft_plane=0
        for i in {1..75}; do
            _e165_f2b_banned_state "$candidate" 1 && ticket=1 || true
            _e165_nft_has_element "$candidate" && nft_plane=1 || true
            test "$ticket" -eq 1 && test "$nft_plane" -eq 1 && break
            sleep 0.2
        done
        if test "$ticket" -eq 1 && test "$nft_plane" -eq 1; then
            last_detail="$candidate:ban_rc=$ban_rc,ticket=1,nft=1"
            break
        fi
        last_detail="$candidate:ban_rc=$ban_rc,ticket=$ticket,nft=$nft_plane,output=${ban_out//$'\n'/ }"
        _e165_f2b_cleanup_ip "$candidate" || true
        test_ip=""
    done

    if test -z "$test_ip" || test "$ticket" -ne 1 || test "$nft_plane" -ne 1; then
        _e165_f2b_diag fail "$family:$last_detail" "${test_ip:-none}"
        return 1
    fi
    _e165_f2b_cleanup_ip "$test_ip" && cleanup_ok=1 || true
    if test "$cleanup_ok" -ne 1; then
        _e165_f2b_diag fail "$family:$last_detail,cleanup=0" "$test_ip"
        return 1
    fi
    _e165_f2b_diag pass "$family:$last_detail,cleanup=1" "$test_ip"
    test_ip=""
)

# Compatibility names now describe direct runtime truth, not action-property
# reflection.  No action metadata field is a production hard gate in E165.
_e159_f2b_action_contract() { _e165_f2b_action_present && _e165_helper_check; }
_e159_nft_table_contract() { _e165_helper_check; }
_e159_nft_has_element() { _e165_nft_has_element "$@"; }
_e159_f2b_banned_state() { _e165_f2b_banned_state "$@"; }

_e152_verify_nft_fail2ban_action() {
    _e165_f2b_action_present || {
        _e165_f2b_diag fail action-not-loaded none
        error "Fail2ban未加载$E165_F2B_ACTION_ID；诊断：$E165_F2B_DIAG"
        return 1
    }
    _e165_f2b_test_family inet4 || {
        error "Fail2ban IPv4票据→E165 nft集合→unban清理闭环失败；诊断：$E165_F2B_DIAG"
        return 1
    }
    _e165_helper_check || {
        _e165_f2b_diag fail helper-contract-after-ipv4 none
        error "E165 nftables只读结构验证在真实封禁后失败；诊断：$E165_F2B_DIAG"
        return 1
    }
    if _e159_ipv6_ssh_relevant; then
        _e165_f2b_test_family inet6 || {
            error "SSH暴露IPv6，但E165 IPv6封禁闭环失败；诊断：$E165_F2B_DIAG"
            return 1
        }
    fi
}

_e152_fail2ban_passive_verify() {
    local backend
    systemctl is-enabled --quiet fail2ban.service 2>/dev/null || return 1
    systemctl is-active --quiet fail2ban.service 2>/dev/null || return 1
    _e152_fail2ban_numeric_verify || return 1
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    case "$backend" in
        nft) _e165_f2b_action_present && _e165_helper_check ;;
        iptables) fail2ban-client get "$E121_F2B_JAIL_NAME" actions 2>/dev/null | grep -qi iptables ;;
        ufw|firewalld) test -n "$(fail2ban-client get "$E121_F2B_JAIL_NAME" actions 2>/dev/null || true)" ;;
        *) return 1 ;;
    esac
}

_e121_verify_fail2ban_runtime() {
    local i backend
    for i in {1..20}; do
        fail2ban-client ping >/dev/null 2>&1 \
            && fail2ban-client status "$E121_F2B_JAIL_NAME" >/dev/null 2>&1 && break
        sleep 0.25
    done
    _e152_fail2ban_numeric_verify || return 1
    systemctl is-enabled --quiet fail2ban.service 2>/dev/null || return 1
    backend=${E152_F2B_BACKEND_KIND:-$(_e152_firewall_backend 2>/dev/null || echo none)}
    case "$backend" in
        nft) _e152_verify_nft_fail2ban_action ;;
        iptables) fail2ban-client get "$E121_F2B_JAIL_NAME" actions 2>/dev/null | grep -qi iptables ;;
        ufw|firewalld) test -n "$(fail2ban-client get "$E121_F2B_JAIL_NAME" actions 2>/dev/null || true)" ;;
        *) return 1 ;;
    esac
}

# Install through the established package/log-source/config transaction, but
# use the E165 official-action overlay and E165 runtime truth.  Old E152/E159 assets are retired
# only after the new live cycle passes; the outer SSH transaction can restore
# all files, service states and all four table generations exactly.
_e121_install_fail2ban_guard() {
    local backend old_table
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    if ! command -v fail2ban-client >/dev/null 2>&1; then
        info '未检测到fail2ban，正在执行可诊断安装。'
        _e141_install_fail2ban_package || {
            error "fail2ban安装失败，原始日志：$E141_F2B_INSTALL_LOG"
            return 1
        }
    fi
    if test "$backend" = nft; then
        systemctl stop fail2ban.service >/dev/null 2>&1 || true
        systemctl is-active --quiet fail2ban.service 2>/dev/null && {
            error '无法停止Fail2ban以清理E165残留表。'
            return 1
        }
        nft delete table inet "$E165_NFT_F2B_TABLE" >/dev/null 2>&1 || true
    fi
    _e141_fail2ban_guard_original || return 1
    if test "$backend" = nft; then
        _e152_verify_nft_fail2ban_action || return 1
        for old_table in "$E165_LEGACY_E163_NFT_TABLE" "$E159_NFT_F2B_TABLE" "$E152_NFT_F2B_TABLE"; do
            nft delete table inet "$old_table" >/dev/null 2>&1 || true
            if nft list table inet "$old_table" >/dev/null 2>&1; then
                error "旧Fail2ban事务表$old_table仍存在，拒绝留下双重SSH封禁所有者。"
                return 1
            fi
        done
        rm -f -- "$E165_LEGACY_E163_HELPER" "$E165_LEGACY_E163_ACTION_CONF" \
            "$E165_LEGACY_E163_FILTER" "$E165_LEGACY_E163_DISABLE" \
            "$E159_F2B_ACTION_CONF" "$E159_F2B_FILTER" "$E152_F2B_FILTER" 2>/dev/null || true
        _e165_helper_check || return 1
    fi
}

# Rebuild the SSH wrapper from the final E159 decision engine so messages and
# rollback ownership accurately include E165.
if declare -F _e159_ssh_guard_install_base >/dev/null 2>&1; then
    eval "$(declare -f _e159_ssh_guard_install_base | sed \
        -e '1s/_e159_ssh_guard_install_base/_e165_ssh_guard_install_base/' \
        -e 's/E152\/E159专用表/E152\/E159\/E165专用表/g')"
fi
_e141_install_ssh_guard() {
    local lock_fd rc=0
    _e214_ensure_run_lock || return 1
    exec {lock_fd}>/run/lock/xray-ssh-guard-e165.lock || return 1
    if ! flock -w 540 "$lock_fd"; then
        exec {lock_fd}>&-
        error 'SSH/Fail2ban事务锁等待超过540秒。'
        return 1
    fi
    if _e165_ssh_guard_install_base "$@"; then rc=0; else rc=$?; fi
    flock -u "$lock_fd" >/dev/null 2>&1 || true
    exec {lock_fd}>&-
    return "$rc"
}
_e135_install_ssh_guard() { _e141_install_ssh_guard "$@"; }
_e121_install_ssh_guard() { _e141_install_ssh_guard "$@"; }
_e116_install_ssh_guard() { _e141_install_ssh_guard "$@"; }

_e165_ssh_guard_verify_final() {
    local profile mode backend
    profile=$(_e141_sshd_auth_profile 2>/dev/null || true)
    mode=$(sed -n 's/^mode=//p' <<<"$profile" | head -n1)
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    case "$backend:$mode" in
        nft:password-capable)
            _e152_fail2ban_passive_verify \
                && _e152_verify_nft_fail2ban_action \
                && _e152_nft_ssh_check
            ;;
        nft:key-only|nft:non-password|nft:ambiguous) _e152_nft_ssh_check ;;
        *:password-capable) _e152_fail2ban_passive_verify && _e121_verify_ssh_port_guard ;;
        *:key-only|*:non-password|*:ambiguous) _e142_verify_key_only_guard ;;
        *) return 1 ;;
    esac
}
_e159_ssh_guard_verify_final() { _e165_ssh_guard_verify_final "$@"; }

# Add E165 and all managed Fail2ban paths to the full-system rollback snapshot.
if declare -F _e138_system_paths >/dev/null 2>&1; then
    eval "$(declare -f _e138_system_paths | sed '1s/_e138_system_paths/_e165_system_paths_base/')"
fi
_e138_system_paths() {
    _e165_system_paths_base
    printf '%s\n' "$E165_DIR" "$E165_SELF_PATH" "$E165_F2B_HELPER" \
        "$E165_F2B_ACTION_CONF" "$E165_F2B_FILTER" "$E165_F2B_LEGACY_DISABLE" \
        "$E165_RELEASE_AUDIT" "$E165_LEGACY_E163_HELPER" \
        "$E165_LEGACY_E163_ACTION_CONF" "$E165_LEGACY_E163_FILTER" \
        "$E165_LEGACY_E163_DISABLE" "$E159_F2B_ACTION_CONF" "$E159_F2B_FILTER"
    _e121_managed_fail2ban_paths
}

# E165 overrides the inherited phase wrapper so every stage is written to the
# E165 transaction log and reports the correct release owner.
_e159_hot_step() {
    local phase="$1"; shift
    _e159_phase_log "$E165_HOT_LOG" "$phase" begin
    if "$@"; then
        _e159_phase_log "$E165_HOT_LOG" "$phase" ok
        return 0
    fi
    _e159_phase_log "$E165_HOT_LOG" "$phase" fail
    error "E165热更新失败阶段：$phase"
    return 1
}

_e165_hot_update_preflight() {
    _e159_hot_update_preflight || return 1
    _e165_prepare || return 1
    for c in nft flock sha256sum awk sed grep sort paste; do
        command -v "$c" >/dev/null 2>&1 || { error "E165预检缺少命令：$c"; return 1; }
    done
}

_e165_hot_update() (
    local protect="" sysbackup="" network_tx="" ssh_tx="" rc=0 rollback_rc=0 was_active=0
    local enabled=0 mode=disabled profile=disabled phase=start auth_mode=""
    local effective_active=0 effective_persistent=0 unsupported=0 shadowed=0 trigger=0
    _e214_ensure_run_lock || return 1
    exec 165>/run/lock/xray-e165-hot-update.lock
    flock -n 165 || { error '已有另一个E165热更新正在运行。'; return 1; }
    : >"$E165_HOT_LOG" || return 1
    E135_NEW_PACKAGES=()
    _e159_phase_log "$E165_HOT_LOG" start begin "$SCRIPT_PATH"
    _e165_prepare || return 1

    phase=xray-snapshot
    protect=$(_e116_backup_state before_hot_update_e165) || rc=1
    test "$rc" -ne 0 || _e118_save_core_payload "$protect" || rc=1
    if test "$rc" -eq 0; then
        was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2>/dev/null | tail -n1)
        was_active=${was_active:-0}
        _e159_phase_log "$E165_HOT_LOG" "$phase" ok "$protect"
    fi
    if test "$rc" -eq 0; then
        phase=system-snapshot
        sysbackup=$(_e165_new_tx hot-update) || rc=1
        test "$rc" -ne 0 || _e140_system_snapshot "$sysbackup" || rc=1
        test "$rc" -ne 0 || _e159_phase_log "$E165_HOT_LOG" "$phase" ok "$sysbackup"
    fi

    test "$rc" -ne 0 || _e159_hot_step warp-state-migrate _e138_warp_migrate_state || rc=1
    if test "$rc" -eq 0; then
        enabled=$(_e138_state_get route_enabled 0)
        mode=$(_e138_state_get route_mode disabled)
        profile=$(_e138_state_get profile disabled)
    fi
    test "$rc" -ne 0 || _e159_hot_step runtime-tools _e135_require_runtime_tools || rc=1
    test "$rc" -ne 0 || _e159_hot_step disable-legacy _e135_disable_legacy_optimizers || rc=1
    test "$rc" -ne 0 || _e159_hot_step self-install _e165_install_self || rc=1
    test "$rc" -ne 0 || _e159_hot_step dat-install install_update_dat || rc=1
    test "$rc" -ne 0 || _e159_hot_step dat-timer systemctl enable --now xray-dat-update.timer || rc=1
    test "$rc" -ne 0 || _e159_hot_step core-auto-update-off _e105_disable_xray_core_auto_update || rc=1
    test "$rc" -ne 0 || _e159_hot_step init-window _e137_apply_init_window_default30 || rc=1
    if test "$rc" -eq 0; then
        E159_DEFER_HOST_FULL_VERIFY=1
        _e159_hot_step network-e159-stable-owner _e159_network_apply fq 1 31 force || rc=1
        unset E159_DEFER_HOST_FULL_VERIFY
        test "$rc" -ne 0 || network_tx=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" | tail -n1)
    fi
    test "$rc" -ne 0 || _e159_hot_step host-safe-migrate _e159_migrate_host_safe || rc=1
    test "$rc" -ne 0 || _e159_hot_step log-retention _e121_install_log_retention || rc=1
    test "$rc" -ne 0 || _e159_hot_step ssh-guard-e165 _e141_install_ssh_guard || rc=1
    if test "$rc" -eq 0; then
        ssh_tx=$(sed -n 's/^transaction=//p' "$E141_SSH_AUTH_STATE" 2>/dev/null | tail -n1)
    fi
    test "$rc" -ne 0 || _e159_hot_step xray-limits fix_xray_systemd_limits || rc=1
    if test "$rc" -eq 0 && test "$enabled" = 1; then
        if test "$mode" = host-full; then
            _e159_hot_step warp-full-units _e140_full_install_units || rc=1
            test "$rc" -ne 0 || _e159_hot_step warp-full-reconcile _e140_warp_full_reconcile || rc=1
        else
            _e159_hot_step warp-proxy _e137_warp_connect_local_proxy || rc=1
            test "$rc" -ne 0 || _e159_hot_step warp-xray _e138_xray_apply_warp "$mode" "$profile" true || rc=1
            test "$rc" -ne 0 || _e159_hot_step warp-health _e138_warp_health_install || rc=1
        fi
    fi
    test "$rc" -ne 0 || _e159_hot_step version-write _e165_write_version || rc=1

    if test "$rc" -eq 0; then
        phase=verify
        _e159_phase_log "$E165_HOT_LOG" "$phase" begin
        test -x "$XRAY_BIN" && "$XRAY_BIN" version >/dev/null 2>&1 || rc=1
        test "$rc" -ne 0 || test ! -s "$CONFIG" || _e118_xray_test_config "$CONFIG" 1 || rc=1
        if test "$rc" -eq 0 && test "$was_active" = 1; then
            _e127_verify_xray_runtime "$CONFIG" 12 || rc=1
            test "$rc" -ne 0 || _e131_verify_nice_runtime || rc=1
        elif test "$rc" -eq 0 && systemctl is-active --quiet xray.service 2>/dev/null; then
            error '热更新意外启动了原本停止的Xray服务。'; rc=1
        fi
        test "$rc" -ne 0 || _e159_network_verify_effective || rc=1
        test "$rc" -ne 0 || _e159_network_verify_ownership || rc=1
        test "$rc" -ne 0 || _e165_ssh_guard_verify_final || rc=1
        test "$rc" -ne 0 || grep -qx 'net.ipv4.tcp_notsent_lowat = 16384' "$E159_EFFECTIVE_CONF" || rc=1
        test "$rc" -ne 0 || grep -qx 'net.core.busy_poll = 50' "$E159_EFFECTIVE_CONF" || rc=1
        test "$rc" -ne 0 || _e159_verify_neighbor_queue_semantics || rc=1
        test "$rc" -ne 0 || ! grep -Eq '^[[:space:]]*net\.ipv6\.conf\..*\.disable_ipv6[[:space:]]*=' "$E159_EFFECTIVE_CONF" || rc=1
        test "$rc" -ne 0 || grep -Eq 'initcwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1
        test "$rc" -ne 0 || grep -Eq 'initrwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1
        for unit in xray-dat-update.timer xray-log-retention-e121.timer \
            xray-ssh-auth-audit-e152.timer xray-network-e159.timer; do
            test "$rc" -ne 0 || systemctl is-enabled --quiet "$unit" 2>/dev/null || rc=1
            test "$rc" -ne 0 || systemctl is-active --quiet "$unit" 2>/dev/null || rc=1
        done
        test "$rc" -ne 0 || systemctl is-enabled --quiet xray-network-e159.service 2>/dev/null || rc=1
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$SYMLINK" || rc=1
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$E165_SELF_PATH" || rc=1
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$E165_LATEST_PATH" || rc=1
        test "$rc" -eq 0 && _e159_phase_log "$E165_HOT_LOG" "$phase" ok \
            || _e159_phase_log "$E165_HOT_LOG" "$phase" fail
    fi

    if test "$rc" -ne 0; then
        error "E165热更新失败，开始总回滚；阶段日志：$E165_HOT_LOG"
        test -z "$ssh_tx" || _e152_nft_ssh_tx_rollback "$ssh_tx" || rollback_rc=1
        test -z "$network_tx" || _e159_network_restore "$network_tx" || rollback_rc=1
        test -z "$sysbackup" || _e140_system_restore "$sysbackup" || rollback_rc=1
        test -z "$protect" || _e118_restore_core_payload "$protect" >/dev/null 2>&1 || rollback_rc=1
        test -z "$protect" || _e118_restore_state "$protect" >/dev/null 2>&1 || rollback_rc=1
        _e135_remove_new_runtime_tools || true
        if test "$was_active" = 1; then
            _e127_verify_xray_runtime "$CONFIG" 12 >/dev/null 2>&1 || rollback_rc=1
        fi
        if test "$rollback_rc" -ne 0; then
            {
                echo "time=$(date -Is 2>/dev/null || date)"
                echo 'operation=hot-update'
                echo "system_backup=${sysbackup:-none}"
                echo "network_backup=${network_tx:-none}"
                echo "ssh_backup=${ssh_tx:-none}"
                echo "core_backup=${protect:-none}"
                echo "log=$E165_HOT_LOG"
            } >"$E165_CRITICAL_MARKER" 2>/dev/null || true
            error '严重：E165回滚未通过复检。'
        fi
        _e159_phase_log "$E165_HOT_LOG" finish fail "rollback=$rollback_rc"
        return 1
    fi

    rm -f "$E165_CRITICAL_MARKER" 2>/dev/null || true
    _e142_prune_transactions "$sysbackup" "$protect" "$ssh_tx" || warn '旧事务快照收敛未完成。'
    _e127_prune_core_payload_backups
    _e165_prune_system_tx "$sysbackup"
    _e152_cleanup_legacy_e143_units || true
    _e159_phase_log "$E165_HOT_LOG" finish ok
    effective_active=$(sed -n 's/^effective_active=//p' "$E159_NETWORK_STATE" | tail -n1)
    effective_persistent=$(sed -n 's/^effective_persistent=//p' "$E159_NETWORK_STATE" | tail -n1)
    unsupported=$(sed -n 's/^unsupported=//p' "$E159_NETWORK_STATE" | tail -n1)
    shadowed=$(sed -n 's/^shadowed_alias=//p' "$E159_NETWORK_STATE" | tail -n1)
    trigger=$(sed -n 's/^write_trigger=//p' "$E159_NETWORK_STATE" | tail -n1)
    auth_mode=$(_e141_sshd_auth_profile 2>/dev/null | sed -n 's/^mode=//p' | head -n1)
    if test "$auth_mode" = password-capable; then
        info "V199e165热更新完成：127条请求（persistent=$effective_persistent，trigger=$trigger，unsupported=$unsupported，shadowed_alias=$shadowed，effective_assignments=$effective_active）、init30、3天日志、E165 Fail2ban官方nft action真实封禁闭环和Xray运行态均已验证。"
    else
        info "V199e165热更新完成：127条请求（persistent=$effective_persistent，trigger=$trigger，unsupported=$unsupported，shadowed_alias=$shadowed，effective_assignments=$effective_active）、init30、3天日志、SSH认证模式=$auth_mode（未强制启用Fail2ban）和Xray运行态均已验证。"
    fi
    info "系统快照：$sysbackup"
    info "网络快照：$network_tx"
    info "SSH快照：${ssh_tx:-none}"
    info "阶段日志：$E165_HOT_LOG"
)

hot_update_from_legacy() { _e165_hot_update_preflight && _e165_hot_update; }

_e165_structure_audit() {
    local rc=0 defs dup_names final_dispatchers size lines
    echo 'V199e165 structure audit:'
    size=$(wc -c <"$SCRIPT_PATH" | tr -d ' ')
    lines=$(wc -l <"$SCRIPT_PATH" | tr -d ' ')
    defs=$(grep -Ec '^[[:space:]]*[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" || true)
    dup_names=$(grep -E '^[[:space:]]*[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" \
        | sed -E 's/^[[:space:]]*([A-Za-z_][A-Za-z0-9_]*).*/\1/' | sort | uniq -d | wc -l | tr -d ' ')
    final_dispatchers=$(grep -c '^# V199e165 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true)
    echo "  file_bytes=$size"
    echo "  lines=$lines"
    echo "  function_definitions=$defs"
    echo "  historical_duplicate_names=$dup_names"
    echo "  final_dispatchers=$final_dispatchers"
    echo '  network_owner=e159 (intentional stable owner; no second sysctl timer)'
    echo "  fail2ban_owner=$E165_F2B_ACTION_ID"
    echo "  nft_table=$E165_NFT_F2B_TABLE"
    test "$size" -gt 2000000 || rc=1
    test "$lines" -gt 45000 || rc=1
    test "$final_dispatchers" -eq 1 || rc=1
    declare -f _e152_verify_nft_fail2ban_action | grep -q '_e165_f2b_test_family' || rc=1
    declare -f _e152_nft_ssh_tx_begin | grep -q '_e165_nft_tables' || rc=1
    declare -f _e121_write_fail2ban_candidates | grep -q 'E165_F2B_ACTION_CONF' || rc=1
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL'
    return "$rc"
}

_e165_self_test() {
    local rc=0 d helper action filter disable jail count unique size lines raw
    echo 'V199e165 fast release gate:'
    bash -n "$SCRIPT_PATH" && echo '  [PASS] bash syntax' || { echo '  [FAIL] bash syntax'; rc=1; }
    test "$SCRIPT_VERSION" = 199e165 && test "$E165_VERSION" = 199e165 \
        && echo '  [PASS] release identity' || { echo '  [FAIL] release identity'; rc=1; }
    size=$(wc -c <"$SCRIPT_PATH" | tr -d ' ')
    lines=$(wc -l <"$SCRIPT_PATH" | tr -d ' ')
    test "$size" -gt 2000000 && test "$lines" -gt 45000 \
        && echo '  [PASS] complete standalone script, not builder/patch' \
        || { echo "  [FAIL] incomplete file bytes=$size lines=$lines"; rc=1; }

    d=$(mktemp -d /tmp/e165-selftest.XXXXXX) || return 1
    helper="$d/helper"; action="$d/action.conf"; filter="$d/filter.conf"; disable="$d/disable.local"
    _e165_write_nft_helper_candidate "$helper" || rc=1
    _e165_write_f2b_action_candidate "$action" || rc=1
    _e165_write_f2b_filter_candidate "$filter" || rc=1
    _e165_write_legacy_disable_candidate "$disable" || rc=1
    bash -n "$helper" \
        && grep -q '^before = nftables.conf$' "$action" \
        && grep -q "^table = $E165_NFT_F2B_TABLE$" "$action" \
        && grep -q "^chain = $E165_NFT_F2B_CHAIN$" "$action" \
        && ! grep -q '^actionban[[:space:]]*=' "$action" \
        && grep -q 'contains_ip' "$helper" \
        && echo '  [PASS] official nftables action overlay + read-only inspector' \
        || { echo '  [FAIL] action/inspector generation'; rc=1; }
    grep -q '^\[sshd\]$' "$disable" && grep -q '^enabled = false$' "$disable" \
        && echo '  [PASS] deterministic legacy sshd jail disable' \
        || { echo '  [FAIL] legacy jail ownership'; rc=1; }

    # Multiple real-world Fail2ban action-list layouts must all be accepted.
    for raw in \
      $'The jail xray-sshd-e121 has the following actions:\nxray-nftables-e165' \
      $'The jail xray-sshd-e121 has the following actions:\nfoo, xray-nftables-e165' \
      $'[xray-nftables-e165]' \
      $'xray-nftables-e165\n'; do
        if ! (E165_FAKE_ACTIONS="$raw"; fail2ban-client() { printf '%s\n' "$E165_FAKE_ACTIONS"; }; _e165_f2b_action_present); then rc=1; fi
    done
    test "$rc" -ne 0 || echo '  [PASS] action discovery ignores presentation format'

    _e159_full_spec fq 1 31 "$d/spec.conf" || rc=1
    count=$(grep -Ec '^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=' "$d/spec.conf" || true)
    unique=$(awk -F= '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{k=$1;gsub(/[[:space:]]/,"",k);print k}' \
        "$d/spec.conf" | sort -u | wc -l | tr -d ' ')
    test "$count" = 127 && test "$unique" = 127 && _e159_spec_validate "$d/spec.conf" \
        && echo '  [PASS] E127 exact 127-request/125-control network model retained' \
        || { echo '  [FAIL] network model'; rc=1; }

    declare -f _e152_verify_nft_fail2ban_action | grep -q '_e165_f2b_test_family' \
        && ! declare -f _e152_verify_nft_fail2ban_action | grep -q 'action_property' \
        && echo '  [PASS] production gate is live ticket/nft/cleanup truth' \
        || { echo '  [FAIL] production gate binding'; rc=1; }
    declare -f _e152_nft_ssh_tx_begin | grep -q '_e165_nft_tables' \
        && declare -f _e152_nft_ssh_tx_rollback | grep -q '_e165_nft_tables' \
        && declare -f _e165_nft_tables | grep -q 'E165_LEGACY_E163_NFT_TABLE' \
        && echo '  [PASS] rollback covers E152/E159/E163/E165 tables and files' \
        || { echo '  [FAIL] SSH rollback coverage'; rc=1; }
    grep -q '11) 热更新到V199e165' "$SCRIPT_PATH" \
        && grep -q '22) WARP定向分流' "$SCRIPT_PATH" \
        && grep -q '24) Cloudflare系统全隧道' "$SCRIPT_PATH" \
        && echo '  [PASS] visible menu identity and WARP coverage' \
        || { echo '  [FAIL] menu identity'; rc=1; }
    rm -rf -- "$d"
    test "$rc" -eq 0 && echo 'V199e165 result: PASS' || echo 'V199e165 result: FAIL'
    return "$rc"
}

_e165_help() {
    cat <<'EOF_E165_HELP'
V199e165:
  --hot-update              full transactional update from E127-E159
  --self-test               non-mutating complete-file and behavior gate
  --structure-audit         final binding, size and layering audit
  --fail2ban-live-test      run real ticket -> nft set -> unban cleanup test
  --fail2ban-helper-status  show the owned E165 nftables table through read-only inspector
  --full-network-apply      replay the stable E159 127-request/125-control owner
  --full-network-spec       print the complete 127-entry request specification
  --full-network-status     runtime, compatibility and duplicate-source audit
  --optimization-menu       advanced optimization and micro-control center
  --summary                 root-only node credential export
  --warp-menu               Google/Meta selective WARP
  --warp-global-menu        Xray-global WARP
  --warp-full-menu          Cloudflare host full tunnel with SSH rollback
EOF_E165_HELP
}

# Relabel the complete proven menu body; handlers resolve dynamically to E165.
if declare -F _e159_main_menu_impl >/dev/null 2>&1; then
    eval "$(declare -f _e159_main_menu_impl | sed \
        -e '1s/_e159_main_menu_impl/_e165_main_menu_impl/' \
        -e 's/V199e159/V199e165/g' -e 's/E159热更新/E165热更新/g')"
fi
main_menu() { _e165_main_menu_impl; }

# Append E165 diagnostics to the established SSH status report.
if declare -F _e141_ssh_guard_status >/dev/null 2>&1; then
    eval "$(declare -f _e141_ssh_guard_status | sed '1s/_e141_ssh_guard_status/_e165_ssh_guard_status_base/')"
fi
_e141_ssh_guard_status() {
    _e165_ssh_guard_status_base "$@"
    echo 'E165 Fail2ban官方nft action：'
    echo "  action=$E165_F2B_ACTION_ID"
    echo "  helper=$E165_F2B_HELPER"
    echo "  table=inet/$E165_NFT_F2B_TABLE"
    echo "  runtime_contract=$(_e165_helper_check >/dev/null 2>&1 && echo ok || echo failed)"
    echo "  diagnostic=$E165_F2B_DIAG"
}

# Remove E165-owned Fail2ban assets only after the inherited uninstall actually
# removed Xray/config.  Cancelling DELETE-XRAY leaves all security state intact.
if declare -F do_uninstall >/dev/null 2>&1; then
    eval "$(declare -f do_uninstall | sed '1s/do_uninstall/_e165_uninstall_base/')"
fi
do_uninstall() {
    local rc=0
    _e165_uninstall_base "$@" || rc=$?
    if test "$rc" -eq 0 && test ! -e "$XRAY_BIN" && test ! -e "$CONFIG"; then
        systemctl stop fail2ban.service >/dev/null 2>&1 || true
        "$E165_F2B_HELPER" stop >/dev/null 2>&1 || true
        nft delete table inet "$E165_LEGACY_E163_NFT_TABLE" >/dev/null 2>&1 || true
        rm -f -- "$E165_F2B_HELPER" "$E165_F2B_ACTION_CONF" "$E165_F2B_FILTER" \
            "$E165_F2B_LEGACY_DISABLE" "$E165_LEGACY_E163_HELPER" \
            "$E165_LEGACY_E163_ACTION_CONF" "$E165_LEGACY_E163_FILTER" \
            "$E165_LEGACY_E163_DISABLE" "$E165_SELF_PATH" 2>/dev/null || true
        rm -rf -- "$E165_DIR" 2>/dev/null || true
        if command -v fail2ban-client >/dev/null 2>&1 && fail2ban-client -t >/dev/null 2>&1; then
            systemctl start fail2ban.service >/dev/null 2>&1 || true
        fi
    fi
    return "$rc"
}

#==============================================================================
# V199e166 FINAL RELEASE LAYER
# Restores the E127 top-level directory contract while retaining the proven
# E159 network transaction owner and E165 Fail2Ban/nftables security owner.
#==============================================================================
readonly E166_VERSION="199e166"
readonly E166_DIR="$CONFIG_DIR/e166"
readonly E166_SELF_PATH="$SCRIPT_DIR/ex199e166.sh"
readonly E166_LATEST_PATH="$SCRIPT_DIR/ex199e_latest.sh"
readonly E166_TX_ROOT="/var/backups/xray-e166"
readonly E166_HOT_LOG="/var/log/xray/e166/hot-update-last.log"
readonly E166_CRITICAL_MARKER="$E166_DIR/CRITICAL_RECOVERY_REQUIRED.env"

# Release-only helpers are cloned from E165.  The firewall implementation is
# deliberately not cloned or renamed: one live Fail2Ban owner is safer than
# parallel version-branded tables/actions.
if declare -F _e165_prepare >/dev/null 2>&1; then
    eval "$(declare -f _e165_prepare | sed \
        -e '1s/_e165_prepare/_e166_prepare/' \
        -e 's/_e159_prepare/_e159_prepare/g' \
        -e 's/E165_DIR/E166_DIR/g' -e 's/E165_TX_ROOT/E166_TX_ROOT/g' \
        -e 's/E165_HOT_LOG/E166_HOT_LOG/g')"
fi
if declare -F _e165_new_tx >/dev/null 2>&1; then
    eval "$(declare -f _e165_new_tx | sed \
        -e '1s/_e165_new_tx/_e166_new_tx/' -e 's/_e165_prepare/_e166_prepare/g' \
        -e 's/E165_TX_ROOT/E166_TX_ROOT/g')"
fi
if declare -F _e165_prune_system_tx >/dev/null 2>&1; then
    eval "$(declare -f _e165_prune_system_tx | sed \
        -e '1s/_e165_prune_system_tx/_e166_prune_system_tx/' \
        -e 's/E165_TX_ROOT/E166_TX_ROOT/g')"
fi
if declare -F _e165_install_self >/dev/null 2>&1; then
    eval "$(declare -f _e165_install_self | sed \
        -e '1s/_e165_install_self/_e166_install_self/' \
        -e 's/_e165_prepare/_e166_prepare/g' -e 's/_e165_new_tx/_e166_new_tx/g' \
        -e 's/E165_SELF_PATH/E166_SELF_PATH/g' -e 's/E165_LATEST_PATH/E166_LATEST_PATH/g' \
        -e 's/e165-new/e166-new/g')"
fi
if declare -F _e165_write_version >/dev/null 2>&1; then
    eval "$(declare -f _e165_write_version | sed \
        -e '1s/_e165_write_version/_e166_write_version/' \
        -e 's/_e165_prepare/_e166_prepare/g' -e 's/E165_VERSION/E166_VERSION/g' \
        -e 's/e165-version/e166-version/g')"
fi
if declare -F _e165_hot_update_preflight >/dev/null 2>&1; then
    eval "$(declare -f _e165_hot_update_preflight | sed \
        -e '1s/_e165_hot_update_preflight/_e166_hot_update_preflight/' \
        -e 's/_e165_prepare/_e166_prepare/g' -e 's/E165预检/E166预检/g')"
fi

# Include E166 release files in the already-proven whole-system snapshot.  The
# base list still contains all E159/E163/E165 network, WARP and SSH assets.
if declare -F _e138_system_paths >/dev/null 2>&1; then
    eval "$(declare -f _e138_system_paths | sed '1s/_e138_system_paths/_e166_system_paths_base/')"
fi
_e138_system_paths() {
    _e166_system_paths_base
    printf '%s\n' "$E166_DIR" "$E166_SELF_PATH" "$E166_LATEST_PATH"
}

# Rebuild only the release transaction bindings.  The Xray/network/SSH bodies
# remain the tested E159/E165 implementations and are still called directly.
if declare -F _e165_hot_update >/dev/null 2>&1; then
    eval "$(declare -f _e165_hot_update | sed \
        -e '1s/_e165_hot_update/_e166_hot_update/' \
        -e 's/_e165_prepare/_e166_prepare/g' -e 's/_e165_new_tx/_e166_new_tx/g' \
        -e 's/_e165_install_self/_e166_install_self/g' \
        -e 's/_e165_write_version/_e166_write_version/g' \
        -e 's/_e165_prune_system_tx/_e166_prune_system_tx/g' \
        -e 's/E165_HOT_LOG/E166_HOT_LOG/g' \
