_e166_structure_audit() {
    local rc=0 defs dup_names final_dispatchers size lines menu hot
    echo 'V199e166 structure audit:'
    size=$(wc -c <"$SCRIPT_PATH" | tr -d ' ')
    lines=$(wc -l <"$SCRIPT_PATH" | tr -d ' ')
    defs=$(grep -Ec '^[[:space:]]*[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" || true)
    dup_names=$(grep -E '^[[:space:]]*[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" \
        | sed -E 's/^[[:space:]]*([A-Za-z_][A-Za-z0-9_]*).*/\1/' | sort | uniq -d | wc -l | tr -d ' ')
    final_dispatchers=$(grep -c '^# V199e166 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true)
    menu=$(declare -f _e166_main_menu_impl)
    hot=$(declare -f _e166_hot_update)
    echo "  file_bytes=$size"
    echo "  lines=$lines"
    echo "  function_definitions=$defs"
    echo "  historical_duplicate_names=$dup_names"
    echo "  final_dispatchers=$final_dispatchers"
    echo '  menu_owner=e166 (E127 top-level contract)'
    echo '  network_owner=e159 (single 127-request/125-control transaction owner)'
    echo "  fail2ban_owner=$E165_F2B_ACTION_ID (single official nftables action owner)"
    test "$size" -gt 2000000 || rc=1
    test "$lines" -gt 45000 || rc=1
    test "$final_dispatchers" -eq 1 || rc=1
    grep -q '21) 跨境代理网络参数集合' <<<"$menu" || rc=1
    ! grep -Eq 'echo .*2[234]\)' <<<"$menu" || rc=1
    grep -q '_e166_install_self' <<<"$hot" || rc=1
    grep -q '_e165_ssh_guard_verify_final' <<<"$hot" || rc=1
    declare -f _update_matrix | grep -q '_e118_commit_config' || rc=1
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL'
    return "$rc"
}

_e166_self_test() {
    local rc=0 d helper action filter disable count unique size lines menu hot
    echo 'V199e166 fast release gate:'
    bash -n "$SCRIPT_PATH" && echo '  [PASS] bash syntax' \
        || { echo '  [FAIL] bash syntax'; rc=1; }
    test "$SCRIPT_VERSION" = 199e166 && test "$E166_VERSION" = 199e166 \
        && echo '  [PASS] release identity' \
        || { echo '  [FAIL] release identity'; rc=1; }
    size=$(wc -c <"$SCRIPT_PATH" | tr -d ' ')
    lines=$(wc -l <"$SCRIPT_PATH" | tr -d ' ')
    test "$size" -gt 2000000 && test "$lines" -gt 45000 \
        && echo '  [PASS] complete standalone script' \
        || { echo "  [FAIL] incomplete file bytes=$size lines=$lines"; rc=1; }

    d=$(mktemp -d /tmp/e166-selftest.XXXXXX) || return 1
    helper="$d/helper"; action="$d/action.conf"; filter="$d/filter.conf"; disable="$d/disable.local"
    _e165_write_nft_helper_candidate "$helper" || rc=1
    _e165_write_f2b_action_candidate "$action" || rc=1
    _e165_write_f2b_filter_candidate "$filter" || rc=1
    _e165_write_legacy_disable_candidate "$disable" || rc=1
    bash -n "$helper" \
        && grep -q '^before = nftables.conf$' "$action" \
        && grep -q "^table = $E165_NFT_F2B_TABLE$" "$action" \
        && grep -q "^chain = $E165_NFT_F2B_CHAIN$" "$action" \
        && ! grep -q '^actionban[[:space:]]*=' "$action" \
        && grep -q '^enabled = false$' "$disable" \
        && echo '  [PASS] E165 official nftables action remains the single SSH security owner' \
        || { echo '  [FAIL] Fail2Ban action/inspector generation'; rc=1; }

    _e159_full_spec fq 1 31 "$d/spec.conf" || rc=1
    count=$(grep -Ec '^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=' "$d/spec.conf" || true)
    unique=$(awk -F= '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{k=$1;gsub(/[[:space:]]/,"",k);print k}' \
        "$d/spec.conf" | sort -u | wc -l | tr -d ' ')
    test "$count" = 127 && test "$unique" = 127 && _e159_spec_validate "$d/spec.conf" \
        && echo '  [PASS] exact 127-request/125-control network model retained' \
        || { echo '  [FAIL] network request model'; rc=1; }

    menu=$(declare -f _e166_main_menu_impl)
    grep -q 'V199e166 - 事务稳态版' <<<"$menu" \
        && grep -q '6) 修改 Reality SNI 矩阵' <<<"$menu" \
        && grep -q '13) 网络参数（默认 initcwnd/initrwnd=30）' <<<"$menu" \
        && grep -q '21) 跨境代理网络参数集合' <<<"$menu" \
        && ! grep -Eq 'echo .*2[234]\)' <<<"$menu" \
        && echo '  [PASS] E127 top-level directory contract restored; WARP removed from homepage' \
        || { echo '  [FAIL] E127 menu contract'; rc=1; }
    grep -q 'choose_sni' <<<"$menu" && grep -q '_update_matrix' <<<"$menu" \
        && grep -q '_e166_network_params_menu' <<<"$menu" \
        && grep -q '_e159_network_menu' <<<"$menu" \
        && grep -q '_e166_security_center' <<<"$menu" \
        && echo '  [PASS] E127 menu items have distinct modern handlers' \
        || { echo '  [FAIL] main-menu handler mapping'; rc=1; }
    declare -f _e166_advanced_menu | grep -q '_e138_warp_selective_menu' \
        && declare -f _e166_advanced_menu | grep -q '_e138_warp_global_menu' \
        && declare -f _e166_advanced_menu | grep -q '_e140_warp_full_menu' \
        && echo '  [PASS] WARP features retained under advanced control board' \
        || { echo '  [FAIL] nested WARP coverage'; rc=1; }
    declare -f _update_matrix | grep -q '_e118_xray_test_config' \
        && declare -f _update_matrix | grep -q '_e118_commit_config' \
        && declare -f _e166_check_reexport | grep -q '_e127_verify_xray_runtime' \
        && echo '  [PASS] Reality SNI and re-export paths retain config/runtime gates' \
        || { echo '  [FAIL] Xray core safety bindings'; rc=1; }
    hot=$(declare -f _e166_hot_update)
    grep -q '_e166_install_self' <<<"$hot" \
        && grep -q '_e166_write_version' <<<"$hot" \
        && grep -q 'E166_HOT_LOG' <<<"$hot" \
        && grep -q '_e165_ssh_guard_verify_final' <<<"$hot" \
        && echo '  [PASS] E166 hot-update identity with E165 SSH security verification' \
        || { echo '  [FAIL] hot-update release binding'; rc=1; }
    rm -rf -- "$d"
    _e166_structure_audit >/dev/null || rc=1
    test "$rc" -eq 0 && echo 'V199e166 result: PASS' || echo 'V199e166 result: FAIL'
    return "$rc"
}

