# Add E166-owned files to the established controlled uninstall.  Cancelling
# DELETE-XRAY leaves every release and security asset untouched.
if declare -F do_uninstall >/dev/null 2>&1; then
    eval "$(declare -f do_uninstall | sed '1s/do_uninstall/_e166_uninstall_base/')"
fi
do_uninstall() {
    local rc=0
    _e166_uninstall_base "$@" || rc=$?
    if test "$rc" -eq 0 && test ! -e "$XRAY_BIN" && test ! -e "$CONFIG"; then
        rm -f -- "$E166_SELF_PATH" "$E166_LATEST_PATH" 2>/dev/null || true
        rm -rf -- "$E166_DIR" 2>/dev/null || true
    fi
    return "$rc"
}

