_e168_prune_system_tx() {
    local keep="${XRAY_E168_TX_KEEP:-${XRAY_E165_TX_KEEP:-12}}"
    local protected=" " p real row n=0
    [[ "$keep" =~ ^[0-9]+$ ]] && (( keep >= 3 && keep <= 100 )) || keep=12
    for p in "$@"; do
        real=$(readlink -f -- "$p" 2>/dev/null || true)
        test -z "$real" || protected+="$real "
    done
    if test -s "$E168_CRITICAL_MARKER"; then
        while IFS= read -r p; do
            real=$(readlink -f -- "$p" 2>/dev/null || true)
            test -z "$real" || protected+="$real "
        done < <(sed -nE 's/^(system_backup|network_backup|core_backup|ssh_backup)=//p' "$E168_CRITICAL_MARKER")
    fi
    test -d "$E168_TX_ROOT" || return 0
    while IFS=$'\t' read -r _ row; do
        test -n "$row" || continue
        n=$((n+1))
        test "$n" -le "$keep" && continue
        real=$(readlink -f -- "$row" 2>/dev/null || true)
        case "$real" in "$E168_TX_ROOT"/*) ;; *) continue ;; esac
        [[ "$protected" == *" $real "* ]] && continue
        rm -rf -- "${real:?}" 2>/dev/null || true
    done < <(find "$E168_TX_ROOT" -mindepth 1 -maxdepth 1 -type d -printf '%T@\t%p\n' 2>/dev/null | sort -nr)
}

