_e168_show_network_spec() {
    local tmp qdisc scale app
    tmp=$(_e118_mktemp e168-network-spec.conf) || return 1
    if test -r "$E159_REQUESTED_CONF" && test -s "$E159_REQUESTED_CONF" \
        && _e159_spec_validate "$E159_REQUESTED_CONF" >/dev/null 2>&1; then
        cp -f -- "$E159_REQUESTED_CONF" "$tmp" || return 1
    else
        qdisc=$(sed -n 's/^qdisc=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1)
        scale=$(sed -n 's/^tcp_adv_win_scale=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1)
        app=$(sed -n 's/^tcp_app_win=//p' "$E159_NETWORK_STATE" 2>/dev/null | tail -n1)
        _e159_full_spec "${qdisc:-fq}" "${scale:-1}" "${app:-31}" "$tmp" || return 1
    fi
    _e159_spec_validate "$tmp" || {
        error "完整网络规格未通过127条唯一键校验。"
        return 1
    }
    sed 's/^/    /' "$tmp" || return 1
    echo
    info "已完整显示127条请求；此操作只读，未修改运行参数。"
}

