_e168_system_tx_begin() {
    local name="${1:-advanced}" tx
    tx=$(_e168_new_tx "advanced-$name") || return 1
    _e140_system_snapshot "$tx" || return 1
    printf '%s\n' "$tx"
}

_e168_system_tx_fail() {
    local tx="$1" label="$2"
    error "$label 未通过运行态/持久化读回，恢复操作前系统状态。"
    _e140_system_restore "$tx" || {
        error "严重：$label 回滚未完整通过，保留快照：$tx"
        return 1
    }
    return 1
}

_e168_apply_init30_tx() {
    local tx oldroute
    oldroute=$(ip -4 route show default 2>/dev/null | head -n1 || true)
    test -n "$oldroute" || { error "没有IPv4默认路由。"; return 1; }
    tx=$(_e168_system_tx_begin init30) || return 1
    if _e137_apply_init_window_default30 \
        && grep -Eq 'initcwnd[[:space:]]+30' < <(ip -4 route show default) \
        && grep -Eq 'initrwnd[[:space:]]+30' < <(ip -4 route show default) \
        && systemctl is-enabled --quiet xray-init-window-e137.timer 2>/dev/null \
        && systemctl is-active --quiet xray-init-window-e137.timer 2>/dev/null \
        && bash -n "$E137_INIT_SCRIPT"; then
        _e168_prune_system_tx "$tx"
        return 0
    fi
    _e168_system_tx_fail "$tx" init30 || true
    ip -4 route replace $oldroute >/dev/null 2>&1 || true
    return 1
}

_e168_offload_verify() {
    local pattern actual
    pattern=$(cat "$E88_OFFLOAD_STATE_FILE" 2>/dev/null || true)
    [[ "$pattern" =~ ^[OX]{4}$ ]] || return 1
    actual=$(_e137_offload_current_pattern 2>/dev/null || true)
    test "$actual" = "$pattern" || return 1
    bash -n "$E137_OFFLOAD_SCRIPT" || return 1
    systemctl is-enabled --quiet xray-offload-e137.timer 2>/dev/null || return 1
    systemctl is-active --quiet xray-offload-e137.timer 2>/dev/null
}

_e168_offload_action() {
    local tx old
    old=$(_e137_offload_current_pattern 2>/dev/null || true)
    tx=$(_e168_system_tx_begin offload) || return 1
    if _e88_manual_offload_profile && _e168_offload_verify; then
        _e168_prune_system_tx "$tx"
        return 0
    fi
    _e168_system_tx_fail "$tx" Offload || true
    [[ "$old" =~ ^[OX]{4}$ ]] && _e137_offload_apply_runtime "$old" >/dev/null 2>&1 || true
    return 1
}

_e168_rps_verify() {
    local cpus mask flow perq iface q actual touched=0
    cpus=$(nproc 2>/dev/null || echo 1)
    test "$cpus" -gt 1 || return 2
    mask=$(_e137_cpu_mask "$cpus") || return 1
    flow=$((4096*cpus))
    perq=$((flow/cpus))
    test "$(cat /proc/sys/net/core/rps_sock_flow_entries 2>/dev/null || true)" = "$flow" || return 1
    iface=$(_e137_default_iface)
    test -n "$iface" || return 1
    for q in /sys/class/net/"$iface"/queues/rx-*/rps_cpus; do
        test -f "$q" || continue
        touched=$((touched+1))
        actual=$(cat "$q" | _e137_norm_mask)
        test "$actual" = "$(printf '%s' "$mask" | _e137_norm_mask)" || return 1
        test ! -f "$(dirname "$q")/rps_flow_cnt" \
            || test "$(cat "$(dirname "$q")/rps_flow_cnt" 2>/dev/null || true)" = "$perq" \
            || return 1
    done
    test "$touched" -gt 0 || return 1
    bash -n "$E137_RPS_SCRIPT" || return 1
    systemctl is-enabled --quiet xray-rps-rfs-e137.timer 2>/dev/null || return 1
    systemctl is-active --quiet xray-rps-rfs-e137.timer 2>/dev/null
}

_e168_rps_action() {
    local tx rc=0 cpus
    cpus=$(nproc 2>/dev/null || echo 1)
    if test "$cpus" -le 1; then
        info "单核CPU无需RPS/RFS；未写入持久化服务，也未报告伪成功。"
        return 0
    fi
    tx=$(_e168_system_tx_begin rps) || return 1
    _e137_rps_snapshot_runtime "$tx/rps-runtime" || return 1
    _e88_apply_rps_rfs || rc=1
    test "$rc" -ne 0 || _e168_rps_verify || rc=1
    if test "$rc" -eq 0; then
        {
            echo "cpus=$cpus"
            echo "iface=$(_e137_default_iface)"
            echo "mask=$(_e137_cpu_mask "$cpus")"
        } > "${E88_RPS_STATE_FILE}.tmp.$$" \
            && chmod 0600 "${E88_RPS_STATE_FILE}.tmp.$$" \
            && mv -f -- "${E88_RPS_STATE_FILE}.tmp.$$" "$E88_RPS_STATE_FILE" || rc=1
    fi
    if test "$rc" -eq 0; then
        _e168_prune_system_tx "$tx"
        return 0
    fi
    _e168_system_tx_fail "$tx" RPS/RFS || true
    _e137_rps_restore_runtime "$tx/rps-runtime" >/dev/null 2>&1 || true
    return 1
}

_e168_mss_verify_on() {
    test "$(cat "$E88_MSS_STATE_FILE" 2>/dev/null || true)" = ON || return 1
    bash -n /usr/local/bin/xray-mss-clamp-e88.sh || return 1
    systemctl is-enabled --quiet xray-mss-clamp-e137.timer 2>/dev/null || return 1
    systemctl is-active --quiet xray-mss-clamp-e137.timer 2>/dev/null || return 1
    test "$(systemctl show xray-mss-clamp-e88.service -p Result --value 2>/dev/null || true)" = success || return 1
    iptables -w 5 -t mangle -C POSTROUTING -j XRAY_MSS_CLAMP >/dev/null 2>&1 || return 1
    iptables -w 5 -t mangle -C XRAY_MSS_CLAMP -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1
}

_e168_mss_finalize_off() {
    local ipt
    systemctl disable --now xray-mss-clamp-e137.timer xray-mss-clamp-e88.service >/dev/null 2>&1 || true
    rm -f -- "$E137_MSS_TIMER" /etc/systemd/system/xray-mss-clamp-e88.service \
        /usr/local/bin/xray-mss-clamp-e88.sh 2>/dev/null || true
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    for ipt in iptables iptables-legacy iptables-nft; do
        command -v "$ipt" >/dev/null 2>&1 || continue
        while "$ipt" -w 5 -t mangle -D POSTROUTING -j XRAY_MSS_CLAMP 2>/dev/null; do :; done
        "$ipt" -w 5 -t mangle -F XRAY_MSS_CLAMP 2>/dev/null || true
        "$ipt" -w 5 -t mangle -X XRAY_MSS_CLAMP 2>/dev/null || true
    done
    printf 'OFF\n' > "${E88_MSS_STATE_FILE}.tmp.$$" || return 1
    chmod 0600 "${E88_MSS_STATE_FILE}.tmp.$$" || return 1
    mv -f -- "${E88_MSS_STATE_FILE}.tmp.$$" "$E88_MSS_STATE_FILE" || return 1
    ! systemctl is-enabled --quiet xray-mss-clamp-e137.timer 2>/dev/null \
        && ! iptables -w 5 -t mangle -C POSTROUTING -j XRAY_MSS_CLAMP >/dev/null 2>&1
}

_e168_mss_action() {
    local tx rc=0 state
    tx=$(_e168_system_tx_begin mss) || return 1
    _e88_manual_mss_clamp || rc=1
    state=$(cat "$E88_MSS_STATE_FILE" 2>/dev/null || true)
    if test "$rc" -eq 0; then
        case "$state" in
            ON) _e168_mss_verify_on || rc=1 ;;
            OFF) _e168_mss_finalize_off || rc=1 ;;
            *) rc=1 ;;
        esac
    fi
    if test "$rc" -eq 0; then
        _e168_prune_system_tx "$tx"
        info "MSS Clamp=$state 已通过规则、timer、服务Result与状态文件读回。"
        return 0
    fi
    _e168_system_tx_fail "$tx" 'MSS Clamp' || true
    return 1
}

_e168_txq_verify() {
    local target iface actual
    target=$(sed -n 's/.*--txqueue-restore "\([0-9][0-9]*\)".*/\1/p' "$E137_TXQ_SCRIPT" 2>/dev/null | tail -n1)
    [[ "$target" =~ ^[0-9]+$ ]] || return 1
    iface=$(_e137_default_iface)
    test -n "$iface" || return 1
    actual=$(ip -o link show dev "$iface" | sed -n 's/.* qlen \([0-9]\+\).*/\1/p')
    test "$actual" = "$target" || return 1
    bash -n "$E137_TXQ_SCRIPT" || return 1
    systemctl is-enabled --quiet xray-txqueue-e137.timer 2>/dev/null || return 1
    systemctl is-active --quiet xray-txqueue-e137.timer 2>/dev/null
}

_e168_txq_action() {
    local tx iface old
    iface=$(_e137_default_iface)
    test -n "$iface" || return 1
    old=$(ip -o link show dev "$iface" | sed -n 's/.* qlen \([0-9]\+\).*/\1/p')
    tx=$(_e168_system_tx_begin txqueue) || return 1
    if _e88_manual_txqueue && _e168_txq_verify; then
        _e168_prune_system_tx "$tx"
        return 0
    fi
    _e168_system_tx_fail "$tx" 'TX Queue' || true
    test -z "$old" || ip link set dev "$iface" txqueuelen "$old" >/dev/null 2>&1 || true
    return 1
}

_e168_ring_verify() {
    local iface target actual
    iface=$(_e137_default_iface)
    test -n "$iface" || return 1
    target=$(cat "$CONFIG_DIR/ring_target_rx.txt" 2>/dev/null || true)
    actual=$(_ring_cur_rx_e52 "$iface" 2>/dev/null || true)
    [[ "$target" =~ ^[0-9]+$ ]] && test "$actual" = "$target" || return 1
    bash -n "$E137_RING_SCRIPT" || return 1
    systemctl is-enabled --quiet xray-ring-e137.timer 2>/dev/null || return 1
    systemctl is-active --quiet xray-ring-e137.timer 2>/dev/null
}

_e168_ring_action() {
    local tx iface oldrx oldtx
    iface=$(_e137_default_iface)
    test -n "$iface" || return 1
    oldrx=$(_ring_cur_rx_e52 "$iface" 2>/dev/null || true)
    oldtx=$(_ring_cur_tx_e52 "$iface" 2>/dev/null || true)
    tx=$(_e168_system_tx_begin ring) || return 1
    if apply_ring_max_adaptive_default && _e168_ring_verify; then
        _e168_prune_system_tx "$tx"
        return 0
    fi
    _e168_system_tx_fail "$tx" 'Ring Buffer' || true
    if [[ "$oldrx" =~ ^[0-9]+$ && "$oldtx" =~ ^[0-9]+$ ]]; then
        ethtool -G "$iface" rx "$oldrx" tx "$oldtx" >/dev/null 2>&1 || true
    elif [[ "$oldrx" =~ ^[0-9]+$ ]]; then
        ethtool -G "$iface" rx "$oldrx" >/dev/null 2>&1 || true
    fi
    return 1
}

_e168_disable_legacy_tx() {
    local tx svc p rc=0
    local -a svcs=(xray-hw-tweaks.service nic-optimize.service rps-optimize.service txqueue.service xray-accel-e125.service xray-accel-e126.service)
    local -a paths=(/etc/systemd/system/xray-hw-tweaks.service /usr/local/bin/xray-hw-tweaks.sh /etc/systemd/system/nic-optimize.service /usr/local/bin/nic-optimize.sh /etc/systemd/system/rps-optimize.service /usr/local/bin/rps-optimize.sh /etc/systemd/system/txqueue.service /usr/local/bin/txqueue.sh /etc/systemd/system/xray-accel-e125.service /usr/local/bin/xray-accel-e125.sh /etc/systemd/system/xray-accel-e126.service /usr/local/bin/xray-accel-e126.sh)
    tx=$(_e168_system_tx_begin disable-legacy) || return 1
    _e135_disable_legacy_optimizers || rc=1
    for svc in "${svcs[@]}"; do
        systemctl is-enabled --quiet "$svc" 2>/dev/null && rc=1 || true
        systemctl is-active --quiet "$svc" 2>/dev/null && rc=1 || true
    done
    for p in "${paths[@]}"; do test ! -e "$p" && test ! -L "$p" || rc=1; done
    if test "$rc" -eq 0; then
        _e168_prune_system_tx "$tx"
        info "旧大包围优化服务已停用，并通过文件/enable/active三重读回。"
        return 0
    fi
    _e168_system_tx_fail "$tx" '旧优化器清理' || true
    return 1
}

_e168_tc_component_ready() {
    test -x "$E95_TC_SCRIPT" || return 1
    bash -n "$E95_TC_SCRIPT" || return 1
    test -s "$E95_TC_SERVICE" || return 1
    test -s "$E95_TC_CONF"
}

_e168_tc_tx_begin() {
    local name="${1:-tc}" tx p id svc
    tx=$(_e168_new_tx "tc-$name") || return 1
    install -d -m 0700 "$tx/files" || return 1
    for p in "$E95_TC_CONF" "$E95_TC_SCRIPT" "$E95_TC_SERVICE"; do
        id=$(printf '%s' "$p" | sha256sum | awk '{print $1}')
        printf '%s|%s\n' "$p" "$id" >> "$tx/paths.tsv" || return 1
        _e135_snapshot_file "$p" "$tx/files/$id" || return 1
    done
    : > "$tx/services.tsv" || return 1
    for svc in xray-tc-limit-e93.service xray-tc-limit-e94.service xray-tc-limit-e95.service; do
        printf '%s|%s|%s\n' "$svc" \
            "$(systemctl is-enabled "$svc" 2>/dev/null || true)" \
            "$(systemctl is-active "$svc" 2>/dev/null || true)" >> "$tx/services.tsv" || return 1
    done
    ( cd "$tx" && find files paths.tsv services.tsv -type f -print0 \
        | sort -z | xargs -0 sha256sum > seal.sha256 ) || return 1
    printf '%s\n' "$tx"
}

_e168_tc_tx_restore() {
    local tx="$1" p id svc enabled active rc=0
    test -s "$tx/seal.sha256" \
        && ( cd "$tx" && sha256sum -c seal.sha256 >/dev/null 2>&1 ) || {
            error "TC回滚快照校验失败：$tx"
            return 1
        }
    test -x "$E95_TC_SCRIPT" && "$E95_TC_SCRIPT" stop >/dev/null 2>&1 || true
    while IFS='|' read -r p id; do
        test -n "$p" || continue
        _e135_restore_file "$p" "$tx/files/$id" || rc=1
    done < "$tx/paths.tsv"
    systemctl daemon-reload >/dev/null 2>&1 || rc=1
    while IFS='|' read -r svc enabled active; do
        test -n "$svc" || continue
        if test "$enabled" = enabled; then
            systemctl enable "$svc" >/dev/null 2>&1 || rc=1
        else
            systemctl disable "$svc" >/dev/null 2>&1 || true
        fi
        if test "$active" = active; then
            systemctl restart "$svc" >/dev/null 2>&1 || rc=1
        else
            systemctl stop "$svc" >/dev/null 2>&1 || true
        fi
    done < "$tx/services.tsv"
    return "$rc"
}

_e168_tc_conf_valid() {
    local enable mbit iface leaf restore
    enable=$(_e95_tc_current_conf_value TC_ENABLE)
    mbit=$(_e95_tc_current_conf_value TC_EGRESS_MBIT)
    iface=$(_e95_tc_current_conf_value TC_IFACE)
    leaf=$(_e95_tc_current_conf_value TC_LEAF_QDISC)
    restore=$(_e95_tc_current_conf_value TC_RESTORE_QDISC)
    [[ "$enable" =~ ^[01]$ ]] || return 1
    test -z "$mbit" || _e95_valid_mbit "$mbit" || return 1
    _e95_valid_iface_or_auto "${iface:-auto}" || return 1
    _e95_valid_leaf_qdisc "${leaf:-fq}" || return 1
    _e95_valid_restore_qdisc "${restore:-fq}"
}

_e168_tc_rewrite_enable() {
    local enable="$1" mbit iface leaf restore
    mbit=$(_e95_tc_current_conf_value TC_EGRESS_MBIT)
    iface=$(_e95_tc_current_conf_value TC_IFACE); iface=${iface:-auto}
    leaf=$(_e95_tc_current_conf_value TC_LEAF_QDISC); leaf=${leaf:-fq}
    restore=$(_e95_tc_current_conf_value TC_RESTORE_QDISC); restore=${restore:-fq}
    test "$enable" = 0 || _e95_valid_mbit "$mbit" || {
        error "当前TC配置没有有效带宽上限。"
        return 1
    }
    _e95_tc_write_conf "$mbit" "$enable" "$iface" "$restore" "$leaf"
}

_e168_tc_verify_applied() {
    local iface line
    test "$(_e95_tc_current_conf_value TC_ENABLE)" = 1 || return 1
    iface=$(_e95_tc_current_conf_value TC_IFACE)
    test "$iface" != auto && test -n "$iface" || iface=$(_e95_default_iface)
    test -n "$iface" || return 1
    line=$(_e95_root_qdisc_line "$iface")
    grep -qw htb <<<"$line" || return 1
    tc class show dev "$iface" 2>/dev/null | grep -Eq 'class htb 1:10|class htb 1:1' || return 1
    _e168_tc_component_ready && _e168_tc_conf_valid
}

_e168_tc_verify_stopped() {
    local iface line
    test "$(_e95_tc_current_conf_value TC_ENABLE)" = 0 || return 1
    iface=$(_e95_tc_current_conf_value TC_IFACE)
    test "$iface" != auto && test -n "$iface" || iface=$(_e95_default_iface)
    test -n "$iface" || return 1
    line=$(_e95_root_qdisc_line "$iface")
    ! grep -qw htb <<<"$line"
}

_e168_tc_fail() {
    local tx="$1" label="$2"
    error "$label 失败，恢复TC配置、组件和e93/e94/e95服务状态。"
    _e168_tc_tx_restore "$tx" || error "TC回滚未完整通过：$tx"
    return 1
}

_e168_tc_menu() {
    local opt="" iface qdisc enabled active mbit tenable restore conf_iface leaf tx confirm rc
    _e95_install_tc_component || {
        error "TC组件生成失败。"
        return 1
    }
    _e168_tc_component_ready || {
        error "TC生成脚本/服务/配置未通过完整性检查。"
        return 1
    }
    while true; do
        clear
        title "V199e168：TC 带宽控制（读回验证 / 失败回滚）"
        iface=$(_e95_default_iface 2>/dev/null || true)
        qdisc=$(_e95_root_qdisc_line "$iface")
        enabled=$(systemctl is-enabled xray-tc-limit-e95.service 2>/dev/null || echo disabled)
        active=$(systemctl is-active xray-tc-limit-e95.service 2>/dev/null || echo inactive)
        tenable=$(_e95_tc_current_conf_value TC_ENABLE); tenable=${tenable:-0}
        mbit=$(_e95_tc_current_conf_value TC_EGRESS_MBIT)
        restore=$(_e95_tc_current_conf_value TC_RESTORE_QDISC); restore=${restore:-fq}
        leaf=$(_e95_tc_current_conf_value TC_LEAF_QDISC); leaf=${leaf:-fq}
        conf_iface=$(_e95_tc_current_conf_value TC_IFACE); conf_iface=${conf_iface:-auto}
        echo "  默认出口网卡: ${iface:-未知}"
        echo "  当前 root qdisc: ${qdisc:-未读取}"
        echo "  配置: enable=$tenable iface=$conf_iface mbit=${mbit:-未设置} leaf=$leaf restore=$restore"
        echo "  服务: active=$active enabled=$enabled"
        hr
        echo "  1) 查看TC/qdisc/class/stats"
        echo "  2) 设置出口上限并立即应用"
        echo "  3) 只保存出口上限，不启用"
        echo "  4) 按当前配置立即应用"
        echo "  5) 停止限速并恢复配置的qdisc"
        echo "  6) 开启开机自启（要求有效上限）"
        echo "  7) 关闭开机自启（不改变当前qdisc）"
        echo "  8) 恢复默认并停用e93/e94/e95"
        echo "  9) 查看日志"
        echo " 10) 删除E95组件"
        echo " 11) 查看TC/BBR/fq/cake说明"
        echo "  0) 返回"
        read -rp "操作: " opt || true
        case "$opt" in
            1) "$E95_TC_SCRIPT" status || true; _e116_pause ;;
            2)
                tx=$(_e168_tc_tx_begin apply-new) || { _e116_pause; continue; }
                rc=0
                _e95_tc_prompt_conf 1 || rc=1
                test "$rc" -ne 0 || "$E95_TC_SCRIPT" apply || rc=1
                test "$rc" -ne 0 || _e168_tc_verify_applied || rc=1
                if test "$rc" -eq 0; then info "TC新上限已应用并读回。"; _e168_prune_system_tx "$tx"; else _e168_tc_fail "$tx" TC应用 || true; fi
                _e116_pause
                ;;
            3)
                tx=$(_e168_tc_tx_begin config-only) || { _e116_pause; continue; }
                if _e95_tc_prompt_conf 0 && _e168_tc_conf_valid \
                    && test "$(_e95_tc_current_conf_value TC_ENABLE)" = 0; then
                    info "TC配置已保存；没有启用限速。"
                    _e168_prune_system_tx "$tx"
                else
                    _e168_tc_fail "$tx" TC配置写入 || true
                fi
                _e116_pause
                ;;
            4)
                tx=$(_e168_tc_tx_begin apply-current) || { _e116_pause; continue; }
                if _e95_tc_enable_config_inplace && "$E95_TC_SCRIPT" apply && _e168_tc_verify_applied; then
                    info "TC当前配置已应用并读回。"
                    _e168_prune_system_tx "$tx"
                else
                    _e168_tc_fail "$tx" TC重放 || true
                fi
                _e116_pause
                ;;
            5)
                tx=$(_e168_tc_tx_begin stop) || { _e116_pause; continue; }
                if "$E95_TC_SCRIPT" stop && _e168_tc_rewrite_enable 0 && _e168_tc_verify_stopped; then
                    info "TC限速已停止，配置保留为disabled。"
                    _e168_prune_system_tx "$tx"
                else
                    _e168_tc_fail "$tx" TC停止 || true
                fi
                _e116_pause
                ;;
            6)
                tx=$(_e168_tc_tx_begin enable-boot) || { _e116_pause; continue; }
                if _e168_tc_rewrite_enable 1 \
                    && systemctl enable xray-tc-limit-e95.service >/dev/null 2>&1 \
                    && systemctl is-enabled --quiet xray-tc-limit-e95.service 2>/dev/null; then
                    info "TC开机自启已启用；本操作未改变当前qdisc。"
                    _e168_prune_system_tx "$tx"
                else
                    _e168_tc_fail "$tx" TC开机自启 || true
                fi
                _e116_pause
                ;;
            7)
                tx=$(_e168_tc_tx_begin disable-boot) || { _e116_pause; continue; }
                if systemctl disable xray-tc-limit-e95.service >/dev/null 2>&1 \
                    && ! systemctl is-enabled --quiet xray-tc-limit-e95.service 2>/dev/null; then
                    info "TC开机自启已关闭；当前qdisc未改变。"
                    _e168_prune_system_tx "$tx"
                else
                    _e168_tc_fail "$tx" TC关闭自启 || true
                fi
                _e116_pause
                ;;
            8)
                read -rp "输入 RESET-TC 确认恢复默认: " confirm || true
                if test "$confirm" = RESET-TC; then
                    tx=$(_e168_tc_tx_begin reset) || { _e116_pause; continue; }
                    rc=0
                    for v in e95 e94 e93; do
                        systemctl disable --now "xray-tc-limit-${v}.service" >/dev/null 2>&1 || true
                        test ! -x "/usr/local/bin/xray-tc-limit-${v}.sh" \
                            || "/usr/local/bin/xray-tc-limit-${v}.sh" stop >/dev/null 2>&1 || rc=1
                    done
                    test "$rc" -ne 0 || _e95_tc_write_conf "" 0 auto fq fq || rc=1
                    test "$rc" -ne 0 || _e168_tc_verify_stopped || rc=1
                    if test "$rc" -eq 0; then info "TC已恢复默认并通过读回。"; _e168_prune_system_tx "$tx"; else _e168_tc_fail "$tx" TC恢复默认 || true; fi
                else
                    warn "已取消。"
                fi
                _e116_pause
                ;;
            9) tail -n 120 "$E95_TC_LOG" 2>/dev/null || warn "暂无日志：$E95_TC_LOG"; _e116_pause ;;
            10)
                read -rp "输入 DELETE-TC-E95 确认: " confirm || true
                if test "$confirm" = DELETE-TC-E95; then
                    tx=$(_e168_tc_tx_begin delete) || { _e116_pause; continue; }
                    rc=0
                    if test -x "$E95_TC_SCRIPT"; then
                        "$E95_TC_SCRIPT" stop >/dev/null 2>&1 || rc=1
                    fi
                    test "$rc" -ne 0 || _e168_tc_verify_stopped || rc=1
                    test "$rc" -ne 0 || systemctl disable --now xray-tc-limit-e95.service >/dev/null 2>&1 || rc=1
                    test "$rc" -ne 0 || rm -f -- "$E95_TC_SERVICE" "$E95_TC_SCRIPT" "$E95_TC_CONF" || rc=1
                    test "$rc" -ne 0 || systemctl daemon-reload >/dev/null 2>&1 || rc=1
                    if test "$rc" -eq 0 \
                        && test ! -e "$E95_TC_SERVICE" && test ! -e "$E95_TC_SCRIPT" && test ! -e "$E95_TC_CONF" \
                        && ! systemctl is-active --quiet xray-tc-limit-e95.service 2>/dev/null \
                        && _e168_tc_verify_stopped; then
                        info "E95 TC组件已删除并读回。"
                        _e168_prune_system_tx "$tx"
                    else
                        _e168_tc_fail "$tx" TC组件删除 || true
                    fi
                else
                    warn "已取消。"
                fi
                _e116_pause
                ;;
            11)
                cat <<'EOF_E168_TC_INFO'
TC用于限制出口总带宽，不是提速器。HTB负责总上限，fq/fq_codel作为叶子队列；
启用后实际root qdisc由HTB接管，不能同时把CAKE作为root。BBR仍可在fq叶子上pacing。
建议上限设为晚高峰稳定速度的85%-95%，减少队列和丢包。
EOF_E168_TC_INFO
                _e116_pause
                ;;
            0) return 0 ;;
            *) warn "无效操作。"; sleep 1 ;;
        esac
    done
}

_e168_advanced_menu_write_map() {
    local tmp="${E152_ADVANCED_MENU_MAP}.e168.tmp.$$"
    install -d -m 0700 "$(dirname "$E152_ADVANCED_MENU_MAP")" || return 1
    {
        echo 'version=199e168'
        echo 'main.10=_e168_advanced_menu'
        echo 'advanced.1=_e168_network_menu'
        echo 'advanced.2=_e159_xray_action_tx:xray-limits'
        echo 'advanced.3=_e168_apply_init30_tx'
        echo 'advanced.4=_e168_offload_action'
        echo 'advanced.5=_e168_rps_action'
        echo 'advanced.6=_e152_run_micro_control_menu'
        echo 'advanced.7=_e168_mss_action'
        echo 'advanced.8=_e168_txq_action'
        echo 'advanced.9=_e168_tc_menu'
        echo 'advanced.10=_e168_bbr_kernel_menu'
        echo 'advanced.11=_e168_disable_legacy_tx'
        echo 'advanced.12=_e168_show_optimization_status'
        echo 'advanced.13=_e168_ring_action'
        echo 'advanced.14=_e152_apply_micro_28'
        echo 'advanced.15=_e138_warp_selective_menu'
        echo 'advanced.16=_e138_warp_global_menu'
        echo 'advanced.17=_e140_warp_full_menu'
    } > "$tmp" || return 1
    chmod 0600 "$tmp" || return 1
    mv -f -- "$tmp" "$E152_ADVANCED_MENU_MAP"
}
_e152_advanced_menu_write_map() { _e168_advanced_menu_write_map; }

_e168_show_optimization_status() {
    _e135_show_optimization_status
    echo
    echo "  E168持久化控制单元："
    local unit
    for unit in xray-init-window-e137.timer xray-offload-e137.timer xray-rps-rfs-e137.timer \
        xray-txqueue-e137.timer xray-ring-e137.timer xray-mss-clamp-e137.timer xray-tc-limit-e95.service; do
        printf '    %-36s enabled=%-9s active=%s\n' "$unit" \
            "$(systemctl is-enabled "$unit" 2>/dev/null || echo no)" \
            "$(systemctl is-active "$unit" 2>/dev/null || echo no)"
    done
}
_e152_show_optimization_status() { _e168_show_optimization_status; }

_e168_advanced_menu() {
    local n="" confirm=""
    _e168_advanced_menu_write_map || warn "高级菜单映射审计文件未能更新；功能仍可使用。"
    while true; do
        clear
        title "V199e168：内核 / 网络 / 应用层高级控制板"
        echo "  1) 完整127条请求 / 125个持久控制事务（保留IPv6策略）"
        echo "  2) 固化并验证 Xray Nice=-20"
        echo "  3) 固化 initcwnd/initrwnd=30"
        echo "  4) 网卡 Offload 独立事务"
        echo "  5) RPS/RFS 独立事务与状态"
        echo "  6) 完整28项应用层与系统微操中心"
        echo "  7) MSS Clamp 独立事务"
        echo "  8) TX Queue 独立事务"
        echo "  9) TC/HTB/fq 带宽控制事务"
        echo " 10) BBR / XanMod官方包 / 完整源码编译"
        echo " 11) 停用旧大包围优化服务（验证/回滚）"
        echo " 12) 显示全部优化参数运行态"
        echo " 13) Ring Buffer自适应最大化（显式事务）"
        echo " 14) 直接执行第28项稳态一键优化"
        echo -e "  ${cyan}15) WARP定向分流（Google/Meta）${none}"
        echo -e "  ${cyan}16) WARP全局分流（仅Xray层）${none}"
        echo -e "  ${yellow}17) Cloudflare系统全隧道（SSH自动回滚）${none}"
        echo "  0) 返回"
        hr
        read -rp "请输入操作代码: " n || true
        case "$n" in
            1) _e168_network_menu ;;
            2) _e159_xray_action_tx xray-limits fix_xray_systemd_limits || true; _e116_pause ;;
            3) _e168_apply_init30_tx || true; _e116_pause ;;
            4) _e168_offload_action || true; _e116_pause ;;
            5)
                _e88_show_rps_rfs_state || true
                read -rp "输入 APPLY-RPS 启用/刷新，其他键返回: " confirm || true
                test "$confirm" = APPLY-RPS && _e168_rps_action || true
                _e116_pause
                ;;
            6) _e152_run_micro_control_menu || true ;;
            7) _e168_mss_action || true; _e116_pause ;;
            8) _e168_txq_action || true; _e116_pause ;;
            9) _e168_tc_menu || true ;;
            10) _e168_bbr_kernel_menu ;;
            11)
                warn "将停用并删除E125/E126及更早的大包围优化服务，不影响E137/E159独立事务。"
                read -rp "输入 DISABLE-LEGACY-OPT 确认: " confirm || true
                test "$confirm" = DISABLE-LEGACY-OPT && _e168_disable_legacy_tx || true
                _e116_pause
                ;;
            12) _e168_show_optimization_status; _e116_pause ;;
            13)
                warn "Ring最大化可能增加排队，只适合明确需要吞吐的场景。"
                read -rp "输入 APPLY-RING 确认: " confirm || true
                test "$confirm" = APPLY-RING && _e168_ring_action || true
                _e116_pause
                ;;
            14)
                warn "第28项会修改Xray应用层与部分系统优化，并可能重启Xray。"
                read -rp "输入 APPLY-MICRO-28 确认: " confirm || true
                test "$confirm" = APPLY-MICRO-28 && _e152_apply_micro_28 || true
                _e116_pause
                ;;
            15) _e136_warp_preflight && _e138_warp_selective_menu || true ;;
            16) _e136_warp_preflight && _e138_warp_global_menu || true ;;
            17) _e136_warp_preflight && _e140_warp_full_menu || true ;;
            0) return 0 ;;
            *) warn "无效操作。"; sleep 1 ;;
        esac
    done
}
