_e168_structure_audit() {
    local rc=0 defs dup_names final_dispatchers size lines menu hot advanced
    echo 'V199e168 structure audit:'
    size=$(wc -c <"$SCRIPT_PATH" | tr -d ' ')
    lines=$(wc -l <"$SCRIPT_PATH" | tr -d ' ')
    defs=$(grep -Ec '^[[:space:]]*[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" || true)
    dup_names=$(grep -E '^[[:space:]]*[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" \
        | sed -E 's/^[[:space:]]*([A-Za-z_][A-Za-z0-9_]*).*/\1/' | sort | uniq -d | wc -l | tr -d ' ')
    final_dispatchers=$(grep -c '^# V199e168 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true)
    menu=$(declare -f _e168_main_menu_impl)
    hot=$(declare -f _e168_hot_update)
    advanced=$(declare -f _e168_advanced_menu)
    echo "  file_bytes=$size"
    echo "  lines=$lines"
    echo "  function_definitions=$defs"
    echo "  historical_duplicate_names=$dup_names"
    echo "  final_dispatchers=$final_dispatchers"
    echo '  menu_owner=e168 (E127 top-level contract)'
    echo '  network_owner=e159 data model / e168 safe presentation and action menu'
    echo '  node_owner=e168 identity / inherited E159-E165 Xray survival transaction'
    echo "  fail2ban_owner=$E165_F2B_ACTION_ID"
    test "$size" -gt 2000000 || rc=1
    test "$lines" -gt 45000 || rc=1
    test "$final_dispatchers" -eq 1 || rc=1
    grep -q 'V199e168 - 事务稳态版' <<<"$menu" || rc=1
    grep -q '_e168_advanced_menu' <<<"$menu" || rc=1
    grep -q '_e168_install_self' <<<"$hot" || rc=1
    grep -q '_e165_ssh_guard_verify_final' <<<"$hot" || rc=1
    grep -q '_e168_tc_menu' <<<"$advanced" || rc=1
    declare -F _e152_pause _e152_disable_legacy_optimizers _e152_show_optimization_status >/dev/null || rc=1
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL'
    return "$rc"
}

_e168_self_test() {
    local rc=0 advanced_rc=0 d count unique size lines menu hot advanced f out cancel_rc
    local -a required=(
        _e168_prepare _e168_new_tx _e168_install_self _e168_write_version
        _e168_hot_update_preflight _e168_hot_update _e168_install_mode
        _e168_install_menu _e168_show_network_spec _e168_network_menu
        _e168_network_params_menu _e168_advanced_menu _e168_tc_menu
        _e168_apply_init30_tx _e168_offload_action _e168_rps_action
        _e168_mss_action _e168_txq_action _e168_ring_action
        _e168_disable_legacy_tx _e168_main_menu_impl
    )
    echo 'V199e168 fast release gate:'
    bash -n "$SCRIPT_PATH" && echo '  [PASS] bash syntax' \
        || { echo '  [FAIL] bash syntax'; rc=1; }
    test "$SCRIPT_VERSION" = 199e168 && test "$E168_VERSION" = 199e168 \
        && echo '  [PASS] release identity' \
        || { echo '  [FAIL] release identity'; rc=1; }
    size=$(wc -c <"$SCRIPT_PATH" | tr -d ' ')
    lines=$(wc -l <"$SCRIPT_PATH" | tr -d ' ')
    test "$size" -gt 2000000 && test "$lines" -gt 45000 \
        && echo '  [PASS] complete standalone script' \
        || { echo "  [FAIL] incomplete file bytes=$size lines=$lines"; rc=1; }
    for f in "${required[@]}"; do
        declare -F "$f" >/dev/null 2>&1 || { echo "  [FAIL] missing function: $f"; rc=1; }
    done
    test "$rc" -ne 0 || echo '  [PASS] all E168 final handlers are defined'

    d=$(mktemp -d /tmp/e168-selftest.XXXXXX) || return 1
    _e159_full_spec fq 1 31 "$d/spec.conf" || rc=1
    count=$(grep -Ec '^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=' "$d/spec.conf" || true)
    unique=$(awk -F= '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{k=$1;gsub(/[[:space:]]/,"",k);print k}' \
        "$d/spec.conf" | sort -u | wc -l | tr -d ' ')
    test "$count" = 127 && test "$unique" = 127 && _e159_spec_validate "$d/spec.conf" \
        && echo '  [PASS] exact 127-request/125-control network model' \
        || { echo '  [FAIL] network request model'; rc=1; }

    if (
        clear() { :; }
        title() { :; }
        hr() { :; }
        _e116_pause() { :; }
        _e118_mktemp() { mktemp "$d/menu-spec.XXXXXX"; }
        printf '4\n0\n' | _e168_network_menu
    ) >"$d/menu4.out" 2>"$d/menu4.err" \
        && grep -q 'net.core.default_qdisc' "$d/menu4.out" \
        && ! grep -qiE 'command not found|unbound variable' "$d/menu4.err"; then
        echo '  [PASS] network menu option 4 renders and returns without flash-exit'
    else
        echo '  [FAIL] network menu option 4 behavior'
        rc=1
    fi

    test "$(_e137_mode_internal 1)" = 1 \
        && test "$(_e137_mode_internal 2)" = 4 \
        && test "$(_e137_mode_internal 3)" = 2 \
        && test "$(_e137_mode_internal 4)" = 3 \
        && echo '  [PASS] semantic menu modes map to Reality/Reality+SS/VLESSENC/SS2022 internals' \
        || { echo '  [FAIL] node protocol mapping'; rc=1; }
    if (
        BEST_SNI=www.example.com
        SNI_JSON_ARRAY='["www.example.com"]'
        REMARK_NAME=e168-selftest
        E79_VLESSENC_NETWORK=raw
        _e118_generate_reality_material() {
            E77_REALITY_PRIV=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA
            E77_REALITY_PUB=BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB
            E77_REALITY_UUID=11111111-1111-4111-8111-111111111111
            E77_REALITY_SID=a1b2c3d4
        }
        e77_generate_vlessenc_pair() {
            E77_VLESSENC_DECRYPTION=mlkem768x25519plus.native.0rtt
            E77_VLESSENC_ENCRYPTION=mlkem768x25519plus.native.0rtt
        }
        local mode file
        for mode in 1 2 3 4; do
            file="$d/mode-$mode.json"
            e79_build_full_config "$mode" 443 8443 8388 \
                2022-blake3-aes-128-gcm AAAAAAAAAAAAAAAAAAAAAA== "$file" || exit 1
            jq -e --arg m "$mode" '
              ([.outbounds[]|select(.tag=="direct" and .protocol=="freedom" and .settings.targetStrategy=="UseIPv4")]|length)==1 and
              (if $m=="1" then ([.inbounds[]|select(.streamSettings.security=="reality")]|length)==1 and ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==0
               elif $m=="2" then ([.inbounds[]|select(.protocol=="vless" and .streamSettings.security=="none")]|length)==1
               elif $m=="3" then ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==1 and ([.inbounds[]|select(.protocol=="vless")]|length)==0
               elif $m=="4" then ([.inbounds[]|select(.streamSettings.security=="reality")]|length)==1 and ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==1
               else false end)
            ' "$file" >/dev/null || exit 1
        done
    ); then
        echo '  [PASS] all four node builders emit the selected protocol set and IPv4 Freedom'
    else
        echo '  [FAIL] generated node protocol/Freedom contract'
        rc=1
    fi
    declare -f _e168_write_generated_metadata_impl | grep -q 'E168_VERSION' \
        && declare -f _e118_install_self | grep -q '_e168_install_self' \
        && declare -f _e159_write_version | grep -q '_e168_write_version' \
        && declare -f e77_build_full_config | grep -q '_e168_build_full_config_impl' \
        && declare -f _e168_build_full_config_impl | grep -q 'targetStrategy: "UseIPv4"' \
        && declare -f _e118_validate_generated_config | grep -q 'UseIPv4' \
        && declare -f _e168_install_mode | grep -q '_e137_validate_semantic_config' \
        && declare -f _e168_install_mode | grep -q '_e138_warp_config_integrity' \
        && echo '  [PASS] node metadata/version/self-copy/semantic/WARP gates bind to E168' \
        || { echo '  [FAIL] node installation binding'; rc=1; }

    cancel_rc=0
    (
        _e168_install_mode_core_base() { choose_sni || return 0; }
        _e168_choose_sni_base() { return 1; }
        _e116_install_mode 1 test
    ) >/dev/null 2>&1 || cancel_rc=$?
    test "$cancel_rc" = 125 \
        && echo '  [PASS] SNI cancellation cannot be interpreted as install success' \
        || { echo "  [FAIL] SNI cancellation status=$cancel_rc"; rc=1; }

    menu=$(declare -f _e168_main_menu_impl)
    advanced=$(declare -f _e168_advanced_menu)
    grep -q 'V199e168 - 事务稳态版' <<<"$menu" \
        && grep -q '21) 跨境代理网络参数集合' <<<"$menu" \
        && ! grep -Eq 'echo .*2[234]\)' <<<"$menu" \
        && echo '  [PASS] E127 homepage contract remains intact' \
        || { echo '  [FAIL] homepage contract'; rc=1; }
    for f in _e168_network_menu _e159_xray_action_tx _e168_apply_init30_tx \
        _e168_offload_action _e168_rps_action _e152_run_micro_control_menu \
        _e168_mss_action _e168_txq_action _e168_tc_menu _e168_bbr_kernel_menu \
        _e168_disable_legacy_tx _e168_show_optimization_status _e168_ring_action \
        _e152_apply_micro_28 _e138_warp_selective_menu _e138_warp_global_menu _e140_warp_full_menu; do
        grep -q "$f" <<<"$advanced" || { echo "  [FAIL] advanced handler not bound: $f"; advanced_rc=1; rc=1; }
    done
    test "$advanced_rc" -ne 0 || echo '  [PASS] all 17 advanced-menu handlers are bound'
    declare -f _e168_advanced_menu | grep -q '_e168_disable_legacy_tx' \
        && declare -f _e168_tc_menu | grep -q '_e168_tc_verify_applied' \
        && declare -f _e168_mss_action | grep -q '_e168_mss_finalize_off' \
        && echo '  [PASS] no unconditional success path for legacy cleanup/TC/MSS-off' \
        || { echo '  [FAIL] advanced transaction gates'; rc=1; }

    hot=$(declare -f _e168_hot_update)
    grep -q '_e168_install_self' <<<"$hot" \
        && grep -q '_e168_write_version' <<<"$hot" \
        && grep -q 'E168_HOT_LOG' <<<"$hot" \
        && grep -q '_e165_ssh_guard_verify_final' <<<"$hot" \
        && echo '  [PASS] E168 hot-update identity with E165 official Fail2Ban verification' \
        || { echo '  [FAIL] hot-update release binding'; rc=1; }
    rm -rf -- "$d"
    _e168_structure_audit >/dev/null || rc=1
    test "$rc" -eq 0 && echo 'V199e168 result: PASS' || echo 'V199e168 result: FAIL'
    return "$rc"
}

