#==============================================================================
# V199e170 FINAL RELIABILITY LAYER
#==============================================================================
readonly E170_VERSION="199e170"
readonly E170_DIR="$CONFIG_DIR/e170"
readonly E170_SELF_PATH="$SCRIPT_DIR/ex199e170.sh"
readonly E170_LATEST_PATH="$SCRIPT_DIR/ex199e_latest.sh"
readonly E170_TX_ROOT="/var/backups/xray-e170"
readonly E170_HOT_LOG="/var/log/xray/e170/hot-update-last.log"
readonly E170_CRITICAL_MARKER="$E170_DIR/CRITICAL_RECOVERY_REQUIRED.env"

# ipfrag_low_thresh must never be raised above the currently active high
# threshold.  Keep the historical 127-line request/report order, but commit
# the coupled pair in a kernel-safe order.  Rollback uses the inverse order
# when the old high threshold is lower than the current low threshold.
_e170_reorder_ipfrag_file() {
    local file="$1" tmp
    test -s "$file" || return 1
    grep -Eq '^[[:space:]]*net\.ipv4\.ipfrag_low_thresh[[:space:]]*=' "$file" || return 0
    grep -Eq '^[[:space:]]*net\.ipv4\.ipfrag_high_thresh[[:space:]]*=' "$file" || return 0
    tmp=$(mktemp /tmp/e170-ipfrag-order.XXXXXX) || return 1
    awk '
      /^[[:space:]]*net\.ipv4\.ipfrag_low_thresh[[:space:]]*=/ { low=$0; next }
      /^[[:space:]]*net\.ipv4\.ipfrag_high_thresh[[:space:]]*=/ {
        print
        if (low != "") { print low; low="" }
        next
      }
      { print }
      END { if (low != "") print low }
    ' "$file" >"$tmp" || { rm -f -- "$tmp"; return 1; }
    mv -f -- "$tmp" "$file"
}

if declare -F _e159_build_effective >/dev/null 2>&1; then
    eval "$(declare -f _e159_build_effective | sed '1s/_e159_build_effective/_e170_build_effective_base/')"
fi
_e159_build_effective() {
    local effective="$2"
    _e170_build_effective_base "$@" || return 1
    _e170_reorder_ipfrag_file "$effective" || {
        error "E170无法生成ipfrag高阈值先于低阈值的有效提交序列。"
        return 1
    }
}

_e170_apply_ipfrag_pair_values() {
    local low="$1" high="$2" current_low current_high
    [[ "$low" =~ ^[0-9]+$ && "$high" =~ ^[0-9]+$ ]] || {
        error "ipfrag阈值不是非负整数：low=$low high=$high"
        return 1
    }
    (( low <= high )) || {
        error "ipfrag阈值关系非法：low=$low > high=$high"
        return 1
    }
    current_low=$(sysctl -n net.ipv4.ipfrag_low_thresh 2>/dev/null | xargs || true)
    current_high=$(sysctl -n net.ipv4.ipfrag_high_thresh 2>/dev/null | xargs || true)
    [[ "$current_low" =~ ^[0-9]+$ && "$current_high" =~ ^[0-9]+$ ]] || return 1
    if (( high < current_low )); then
        test "$current_low" = "$low" \
            || sysctl -w "net.ipv4.ipfrag_low_thresh=$low" >/dev/null 2>&1 \
            || { error "E170写入失败：net.ipv4.ipfrag_low_thresh（降阈值前置）"; return 1; }
        test "$current_high" = "$high" \
            || sysctl -w "net.ipv4.ipfrag_high_thresh=$high" >/dev/null 2>&1 \
            || { error "E170写入失败：net.ipv4.ipfrag_high_thresh"; return 1; }
    else
        test "$current_high" = "$high" \
            || sysctl -w "net.ipv4.ipfrag_high_thresh=$high" >/dev/null 2>&1 \
            || { error "E170写入失败：net.ipv4.ipfrag_high_thresh（升阈值前置）"; return 1; }
        test "$current_low" = "$low" \
            || sysctl -w "net.ipv4.ipfrag_low_thresh=$low" >/dev/null 2>&1 \
            || { error "E170写入失败：net.ipv4.ipfrag_low_thresh"; return 1; }
    fi
    current_low=$(sysctl -n net.ipv4.ipfrag_low_thresh 2>/dev/null | xargs || true)
    current_high=$(sysctl -n net.ipv4.ipfrag_high_thresh 2>/dev/null | xargs || true)
    test "$current_low" = "$low" && test "$current_high" = "$high"
}

_e159_apply_runtime() {
    local file="$1" key value current failed=0 low="" high="" pair=0
    value=$(awk -F= '$1 ~ /^[[:space:]]*net.ipv4.ip_forward[[:space:]]*$/{print $2;exit}' "$file" | xargs)
    if test -n "$value"; then
        current=$(sysctl -n net.ipv4.ip_forward 2>/dev/null | xargs || true)
        test "$current" = "$value" \
            || sysctl -w "net.ipv4.ip_forward=$value" >/dev/null 2>&1 \
            || return 1
    fi
    low=$(awk -F= '$1 ~ /^[[:space:]]*net.ipv4.ipfrag_low_thresh[[:space:]]*$/{print $2;exit}' "$file" | xargs)
    high=$(awk -F= '$1 ~ /^[[:space:]]*net.ipv4.ipfrag_high_thresh[[:space:]]*$/{print $2;exit}' "$file" | xargs)
    if test -n "$low" && test -n "$high"; then
        _e170_apply_ipfrag_pair_values "$low" "$high" || return 1
        pair=1
    fi
    while IFS='=' read -r key value; do
        key=$(_e159_norm "$key"); value=$(_e159_norm "$value")
        case "$key" in
            ''|'#'*|net.ipv4.ip_forward|net.ipv4.route.flush) continue ;;
            net.ipv4.ipfrag_low_thresh|net.ipv4.ipfrag_high_thresh)
                test "$pair" -eq 1 && continue
                ;;
        esac
        sysctl -w "$key=$value" >/dev/null 2>&1 || {
            error "E159写入失败：$key"
            return 1
        }
    done <"$file"
    if grep -q '^net.ipv4.route.flush[[:space:]]*=' "$file"; then
        sysctl -w net.ipv4.route.flush=1 >/dev/null 2>&1 || {
            error "路由缓存刷新触发失败。"
            return 1
        }
    fi
    while IFS='=' read -r key value; do
        key=$(_e159_norm "$key"); value=$(_e159_norm "$value")
        case "$key" in ''|'#'*|net.ipv4.route.flush) continue ;; esac
        current=$(sysctl -n "$key" 2>/dev/null || true)
        _e159_value_equal "$key" "$value" "$current" || {
            error "E159读回不一致：$key 期望=$value 实际=${current:-unreadable}"
            failed=1
        }
    done <"$file"
    test "$failed" -eq 0
}

_e159_restore_runtime_file() {
    local file="$1" key old current rc=0 low="" high="" pair=0
    test -s "$file" || return 0
    old=$(awk -F'|' '$1=="net.ipv4.ip_forward"{print substr($0,index($0,"|")+1);exit}' "$file")
    if test -n "$old"; then
        current=$(sysctl -n net.ipv4.ip_forward 2>/dev/null || true)
        test "$current" = "$old" || sysctl -w "net.ipv4.ip_forward=$old" >/dev/null 2>&1 || rc=1
    fi
    low=$(awk -F'|' '$1=="net.ipv4.ipfrag_low_thresh"{print substr($0,index($0,"|")+1);exit}' "$file")
    high=$(awk -F'|' '$1=="net.ipv4.ipfrag_high_thresh"{print substr($0,index($0,"|")+1);exit}' "$file")
    test -n "$low" && test -n "$high" && pair=1 || true
    while IFS='|' read -r key old; do
        test -n "$key" || continue
        case "$key" in
            net.ipv4.ip_forward|net.ipv4.route.flush) continue ;;
            net.ipv4.ipfrag_low_thresh|net.ipv4.ipfrag_high_thresh)
                test "$pair" -eq 1 && continue
                ;;
        esac
        sysctl -w "$key=$old" >/dev/null 2>&1 || rc=1
    done <"$file"
    if test "$pair" -eq 1; then
        _e170_apply_ipfrag_pair_values "$low" "$high" || rc=1
    fi
    return "$rc"
}

_e170_ipfrag_order_verify() {
    local file="${1:-$E159_EFFECTIVE_CONF}" low_line high_line
    test -s "$file" || return 1
    low_line=$(grep -nE '^[[:space:]]*net\.ipv4\.ipfrag_low_thresh[[:space:]]*=' "$file" \
        | head -n1 | cut -d: -f1 || true)
    high_line=$(grep -nE '^[[:space:]]*net\.ipv4\.ipfrag_high_thresh[[:space:]]*=' "$file" \
        | head -n1 | cut -d: -f1 || true)
    if test -n "$low_line" && test -n "$high_line"; then
        (( high_line < low_line )) || {
            error "E170持久配置的ipfrag提交顺序不安全：high行=$high_line low行=$low_line"
            return 1
        }
    fi
}
if declare -F _e159_network_verify_ownership >/dev/null 2>&1; then
    eval "$(declare -f _e159_network_verify_ownership | sed \
        '1s/_e159_network_verify_ownership/_e170_network_verify_ownership_base/')"
fi
_e159_network_verify_ownership() {
    _e170_network_verify_ownership_base "$@" || return 1
    _e170_ipfrag_order_verify "$E159_EFFECTIVE_CONF"
}

# E165 performed several identical live ban cycles back-to-back.  E170 keeps
# the live test inside the original installer and one final test after any
# ignoreip restart; all later gates are passive readback checks.
_e121_install_fail2ban_guard() {
    local backend old_table
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    if ! command -v fail2ban-client >/dev/null 2>&1; then
        info '未检测到fail2ban，正在执行可诊断安装。'
        _e141_install_fail2ban_package || {
            error "fail2ban安装失败，原始日志：$E141_F2B_INSTALL_LOG"
            return 1
        }
    fi
    if test "$backend" = nft; then
        systemctl stop fail2ban.service >/dev/null 2>&1 || true
        systemctl is-active --quiet fail2ban.service 2>/dev/null && {
            error '无法停止Fail2ban以清理活动E165表。'
            return 1
        }
        nft delete table inet "$E165_NFT_F2B_TABLE" >/dev/null 2>&1 || true
    fi
    _e141_fail2ban_guard_original || return 1
    if test "$backend" = nft; then
        _e152_fail2ban_passive_verify || {
            error 'E170安装后Fail2ban/nftables被动读回失败。'
            return 1
        }
        for old_table in "$E165_LEGACY_E163_NFT_TABLE" "$E159_NFT_F2B_TABLE" "$E152_NFT_F2B_TABLE"; do
            nft delete table inet "$old_table" >/dev/null 2>&1 || true
            if nft list table inet "$old_table" >/dev/null 2>&1; then
                error "旧Fail2ban事务表$old_table仍存在。"
                return 1
            fi
        done
        rm -f -- "$E165_LEGACY_E163_HELPER" "$E165_LEGACY_E163_ACTION_CONF" \
            "$E165_LEGACY_E163_FILTER" "$E165_LEGACY_E163_DISABLE" \
            "$E159_F2B_ACTION_CONF" "$E159_F2B_FILTER" "$E152_F2B_FILTER" 2>/dev/null || true
        _e165_helper_check || return 1
    fi
}

_e170_current_ip_ignored() {
    local ip="$1" values
    test -n "$ip" || return 0
    values=$(fail2ban-client get "$E121_F2B_JAIL_NAME" ignoreip 2>/dev/null \
        | _e137_normalize_ignore_tokens || true)
    grep -Fxq -- "$ip" <<<"$values"
}

_e165_ssh_guard_install_base() {
    local profile mode ip tmp backend tx="" failed=0 stage=prepare restart_after_install=0
    _e141_prepare || return 1
    profile=$(_e141_sshd_auth_profile) || {
        error "无法读取sshd有效认证配置。"
        return 1
    }
    mode=$(sed -n 's/^mode=//p' <<<"$profile" | head -n1)
    ip=$(_e135_current_ssh_ip 2>/dev/null || true)
    E152_CURRENT_SSH_IP="$ip"
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    if test "$backend" != nft; then
        tmp="${E141_SSH_AUTH_STATE}.tmp.$$"
        {
            printf '%s\n' "$profile"
            printf 'current_ssh_ip=%s\nfirewall_backend=%s\nchecked_at=%s\n' \
                "$ip" "$backend" "$(date -Is 2>/dev/null || date)"
        } >"$tmp" || return 1
        install -m 0600 "$tmp" "$E141_SSH_AUTH_STATE" || { rm -f "$tmp"; return 1; }
        rm -f "$tmp"
        _e152_ssh_guard_inherited || return 1
        return 0
    fi

    stage=snapshot
    tx=$(_e152_nft_ssh_tx_begin) || {
        error "原生nftables SSH变更前快照失败。"
        return 1
    }
    tmp="${E141_SSH_AUTH_STATE}.tmp.$$"
    {
        printf '%s\n' "$profile"
        printf 'current_ssh_ip=%s\nfirewall_backend=%s\nchecked_at=%s\ntransaction=%s\n' \
            "$ip" "$backend" "$(date -Is 2>/dev/null || date)" "$tx"
    } >"$tmp" || failed=1
    test "$failed" -ne 0 || install -m 0600 "$tmp" "$E141_SSH_AUTH_STATE" || failed=1
    rm -f "$tmp" 2>/dev/null || true

    if test "$failed" -eq 0; then
        case "$mode" in
            key-only|non-password)
                stage=key-only-audit
                info "原生nftables + $mode：保留现有策略并部署只读SSH审计。"
                _e152_install_nft_ssh_audit || failed=1
                ;;
            password-capable)
                stage=fail2ban-install
                info '原生nftables + 密码认证：安装Fail2ban官方nftables action。'
                _e121_install_fail2ban_guard || failed=1
                if test "$failed" -eq 0 && test -n "$ip" && ! _e170_current_ip_ignored "$ip"; then
                    stage=ignoreip-reconcile
                    _e135_patch_fail2ban_ignoreip "$ip" || failed=1
                    test "$failed" -ne 0 || restart_after_install=1
                fi
                if test "$failed" -eq 0; then
                    stage=passive-readback
                    _e152_fail2ban_passive_verify || failed=1
                fi
                if test "$failed" -eq 0; then
                    if test "$restart_after_install" -eq 1; then
                        stage=live-ban-after-final-restart
                        _e152_verify_nft_fail2ban_action || failed=1
                    else
                        stage=live-proof-readback
                        _e170_fail2ban_live_proof && _e165_helper_check || failed=1
                    fi
                fi
                if test "$failed" -eq 0; then
                    stage=boot-audit-install
                    _e152_install_nft_ssh_audit || failed=1
                fi
                ;;
            ambiguous)
                stage=ambiguous-audit
                warn 'SSH认证策略存在Match歧义：不改变nft策略，只部署读回审计。'
                _e152_install_nft_ssh_audit || failed=1
                ;;
            *) stage=auth-mode; failed=1 ;;
        esac
    fi
    if test "$failed" -eq 0; then stage=auth-audit-install; _e152_install_ssh_auth_audit || failed=1; fi
    if test "$failed" -eq 0; then stage=legacy-guard-disable; _e152_disable_legacy_iptables_ssh_guard || failed=1; fi
    if test "$failed" -eq 0; then stage=final-readback; _e152_nft_ssh_check || failed=1; fi
    if test "$failed" -eq 0; then stage=commit; _e152_nft_ssh_tx_commit "$tx" || failed=1; fi
    if test "$failed" -ne 0; then
        error "E170原生nftables SSH/Fail2ban事务失败阶段：$stage"
        error '恢复原配置、服务状态及E152/E159/E165专用表。'
        _e152_nft_ssh_tx_rollback "$tx" \
            || warn "局部回滚未完全成功；快照：$tx"
        return 1
    fi
    info "E170 SSH事务已提交：auth=$mode backend=nft ports=$(_e165_detect_ports_csv)。"
}

_e170_fail2ban_live_proof() {
    test -s "$E165_F2B_DIAG" \
        && grep -qx 'result=pass' "$E165_F2B_DIAG" \
        && grep -qx "expected_table=inet/$E165_NFT_F2B_TABLE" "$E165_F2B_DIAG"
}

_e170_ssh_guard_verify_final() {
    local profile mode backend
    profile=$(_e141_sshd_auth_profile 2>/dev/null || true)
    mode=$(sed -n 's/^mode=//p' <<<"$profile" | head -n1)
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    case "$backend:$mode" in
        nft:password-capable)
            _e152_fail2ban_passive_verify \
                && _e165_helper_check \
                && _e170_fail2ban_live_proof \
                && _e152_nft_ssh_check
            ;;
        nft:key-only|nft:non-password|nft:ambiguous) _e152_nft_ssh_check ;;
        *:password-capable) _e152_fail2ban_passive_verify && _e121_verify_ssh_port_guard ;;
        *:key-only|*:non-password|*:ambiguous) _e142_verify_key_only_guard ;;
        *) return 1 ;;
    esac
}
_e165_ssh_guard_verify_final() { _e170_ssh_guard_verify_final "$@"; }
_e159_ssh_guard_verify_final() { _e170_ssh_guard_verify_final "$@"; }

# Restore the visible 1..28 control directory.  Later safety transactions are
# retained; only the compressed E159 presentation is replaced.
_e170_micro_control_menu() {
    local opt="" qdisc="" confirm=""
    while true; do
        clear
        title "V199e170：完整28项应用层 / 系统微操中心"
        echo "  1) TCP NoDelay 小包低延迟（默认开启）"
        echo " 1f) TCP FastOpen 独立开关（默认关闭）"
        echo "  2) Socket KeepAlive（30s/15s稳态组）"
        echo "  3) 嗅探 metadataOnly 减负"
        echo "  4) routeOnly 纯净路由解析"
        echo "  5) Xray Buffer 收缩至128KB"
        echo "  6) Native DNS / UseIPv4稳态"
        echo "  7) GOGC=300"
        echo "  8) Policy连接生命周期 / Buffer稳态"
        echo "  9) Xray CPU / GOMAXPROCS调度"
        echo " 10) routing domainMatcher=mph"
        echo " 11) Reality maxTimeDiff=60s"
        echo " 12) Dnsmasq本地缓存（高影响，需确认）"
        echo " 13) THP=never独立固化"
        echo " 14) TCP PMTU/完整127请求网络事务"
        echo " 15) CPU performance独立固化"
        echo " 16) Ring Buffer自适应最大化事务"
        echo " 17) qdisc选择（fq/fq_codel/cake）"
        echo " 18) CAKE ACK Filter（进入TC真实root控制）"
        echo " 19) CAKE ECN（进入TC真实root控制）"
        echo " 20) CAKE WASH（进入TC真实root控制）"
        echo " 21) 网卡Offload独立控制"
        echo " 22) RPS/RFS独立控制"
        echo " 23) ZRAM/Swap 1GiB（高影响，需确认）"
        echo " 24) 3天持久日志与滚动清理"
        echo " 25) Xray Nice/OOM限制事务"
        echo " 26) 一键应用层1-11"
        echo " 27) 安全系统微操（不改Swap/Ring/Offload/IPv6）"
        echo " 28) 应用层 + 安全系统微操完整事务"
        echo "  0) 返回"
        hr
        read -rp "操作: " opt || true
        case "$opt" in
            1) _e159_xray_action_tx nodelay apply_xray_nodelay_default || true; _e52_pause ;;
            1f|1F) _e159_xray_action_tx tcp-fastopen _e159_action_tfo_toggle || true; _e52_pause ;;
            2|3|4|5|6) _e159_xray_action_tx app-2-to-6 _e159_action_2_to_6 || true; _e52_pause ;;
            7) _e159_xray_action_tx gogc-300 set_xray_gogc_300 || true; _e52_pause ;;
            8) _e159_xray_action_tx core-defaults force_apply_xray_core_defaults_e52 || true; _e52_pause ;;
            9) _e159_xray_action_tx cpu-schedule apply_xray_cpu_schedule_default || true; _e52_pause ;;
            10) _e159_xray_action_tx mph _e159_action_mph || true; _e52_pause ;;
            11) _e159_xray_action_tx reality-time _e159_action_reality_time || true; _e52_pause ;;
            12)
                warn 'Dnsmasq会接管resolv.conf并停用systemd-resolved/resolvconf。'
                read -rp "输入 APPLY-DNSMASQ 确认: " confirm || true
                test "$confirm" = APPLY-DNSMASQ \
                    && _e159_xray_action_tx dnsmasq enable_dnsmasq_cache_safely || true
                _e52_pause
                ;;
            13) _e159_install_host_safe thp || error 'THP固化失败。'; _e52_pause ;;
            14) _e159_network_apply fq 1 31 || true; _e52_pause ;;
            15) _e159_install_host_safe cpu || error 'CPU策略固化失败。'; _e52_pause ;;
            16) apply_ring_max_adaptive_default || error 'Ring事务失败。'; _e52_pause ;;
            17)
                read -rp "qdisc [fq/fq_codel/cake]: " qdisc || true
                qdisc=${qdisc:-fq}
                _e159_network_apply "$qdisc" 1 31 || true
                _e52_pause
                ;;
            18|19|20)
                warn 'CAKE子项必须作用于实际TC root qdisc，转入TC事务中心。'
                _e204_tc_menu || true
                ;;
            21) _e170_offload_action || true; _e52_pause ;;
            22) _e170_rps_action || true; _e52_pause ;;
            23)
                warn '此项会调整Swap/ZRAM和fstab。'
                read -rp "输入 APPLY-ZRAM-1G 确认: " confirm || true
                test "$confirm" = APPLY-ZRAM-1G && enable_zram_default || true
                _e52_pause
                ;;
            24) _e121_install_log_retention || error '3天日志策略安装失败。'; _e52_pause ;;
            25) _e159_xray_action_tx xray-limits apply_process_priority_default || true; _e52_pause ;;
            26) _e159_xray_action_tx app-1-to-11 _turn_on_app || true; _e52_pause ;;
            27) apply_safe_turbo_defaults || error '安全系统微操失败。'; _e52_pause ;;
            28) _e159_apply_micro_28 || true; _e52_pause ;;
            0) return 0 ;;
            *) warn '无效操作。'; sleep 1 ;;
        esac
    done
}
do_micro_control_menu() { _e170_micro_control_menu; }
_e152_micro_control_available() {
    local body n
    body=$(declare -f _e170_micro_control_menu 2>/dev/null || true)
    for n in {1..28}; do
        grep -Eq "echo \\\"[[:space:]]+${n}\\)" <<<"$body" || return 1
    done
    grep -Eq '(^|[[:space:]])28\)' <<<"$body"
}
_e170_run_micro_control_menu() {
    _e152_micro_control_available || {
        error '完整1-28显示或第28项处理器缺失，拒绝进入残缺菜单。'
        return 1
    }
    _e170_micro_control_menu
}
_e152_run_micro_control_menu() { _e170_run_micro_control_menu; }

