        _e152_apply_micro_28 _e138_warp_selective_menu _e138_warp_global_menu _e140_warp_full_menu; do
        grep -q "$n" <<<"$body" || { echo "  [FAIL] 高级入口缺失：$n"; rc=1; }
    done
