_e159_hot_step() {
    local phase="$1"; shift
    _e159_phase_log "$E170_HOT_LOG" "$phase" begin
    if "$@"; then
        _e159_phase_log "$E170_HOT_LOG" "$phase" ok
        return 0
    fi
    _e159_phase_log "$E170_HOT_LOG" "$phase" fail
    error "E170热更新失败阶段：$phase"
    return 1
}

_e170_hot_update_preflight() {
