_e170_structure_audit() {
    local rc=0 size lines dispatchers menu advanced hot
    echo 'V199e170 structure audit:'
    size=$(wc -c <"$SCRIPT_PATH" | tr -d ' ')
    lines=$(wc -l <"$SCRIPT_PATH" | tr -d ' ')
    dispatchers=$(grep -c '^# V199e170 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true)
    menu=$(declare -f _e170_main_menu_impl 2>/dev/null || true)
    advanced=$(declare -f _e170_advanced_menu 2>/dev/null || true)
    hot=$(declare -f _e170_hot_update 2>/dev/null || true)
    echo "  file_bytes=$size"
    echo "  lines=$lines"
    echo "  final_dispatchers=$dispatchers"
    echo '  menu_owner=e170 (E127 top-level contract)'
    echo '  network_owner=e159 data model / e170 ordered ipfrag commit'
    echo '  node_owner=e170 identity / Xray survival transaction'
    echo '  ssh_owner=e165 official action / e170 staged verifier'
    test "$size" -gt 2000000 && test "$lines" -gt 45000 || rc=1
    test "$dispatchers" -eq 1 || rc=1
    grep -q 'V199e170 - 事务稳态版' <<<"$menu" || rc=1
    grep -q '_e170_advanced_menu' <<<"$menu" || rc=1
    grep -q '_e170_run_micro_control_menu' <<<"$advanced" || rc=1
    grep -q '_e170_install_self' <<<"$hot" || rc=1
    grep -q '_e170_ssh_guard_verify_final' <<<"$hot" || rc=1
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL'
    return "$rc"
}

_e170_self_test() {
    local rc=0 d count unique low_line high_line body menu hot mode file
    echo 'V199e170 fast release gate:'
    bash -n "$SCRIPT_PATH" && echo '  [PASS] bash syntax' \
        || { echo '  [FAIL] bash syntax'; rc=1; }
    test "$SCRIPT_VERSION" = 199e170 && test "$E170_VERSION" = 199e170 \
        && echo '  [PASS] release identity' \
        || { echo '  [FAIL] release identity'; rc=1; }
    d=$(mktemp -d /tmp/e170-selftest.XXXXXX) || return 1
    _e159_full_spec fq 1 31 "$d/spec.conf" || rc=1
    count=$(grep -Ec '^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=' "$d/spec.conf" || true)
    unique=$(awk -F= '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{k=$1;gsub(/[[:space:]]/,"",k);print k}' \
        "$d/spec.conf" | sort -u | wc -l | tr -d ' ')
    test "$count" = 127 && test "$unique" = 127 && _e159_spec_validate "$d/spec.conf" \
        && echo '  [PASS] exact 127-request / 125-control model' \
        || { echo '  [FAIL] network request model'; rc=1; }
    cp -f "$d/spec.conf" "$d/order.conf"
    _e170_reorder_ipfrag_file "$d/order.conf" || rc=1
    low_line=$(grep -n '^net.ipv4.ipfrag_low_thresh' "$d/order.conf" | cut -d: -f1)
    high_line=$(grep -n '^net.ipv4.ipfrag_high_thresh' "$d/order.conf" | cut -d: -f1)
    test -n "$low_line" && test -n "$high_line" && (( high_line < low_line )) \
        && echo '  [PASS] ipfrag high-before-low commit ordering' \
        || { echo '  [FAIL] ipfrag ordering'; rc=1; }
    if (
        clear() { :; }; title() { :; }; hr() { :; }
        printf '0\n' | _e170_micro_control_menu
    ) >"$d/micro.out" 2>"$d/micro.err" \
        && grep -q '  1) TCP NoDelay' "$d/micro.out" \
        && grep -q ' 28) 应用层' "$d/micro.out" \
        && _e152_micro_control_available; then
        echo '  [PASS] menu 10 -> 6 visibly retains all 1-28 entries'
    else
        echo '  [FAIL] complete 28-item menu behavior'
        rc=1
    fi
    test "$(_e137_mode_internal 1)" = 1 \
        && test "$(_e137_mode_internal 2)" = 4 \
        && test "$(_e137_mode_internal 3)" = 2 \
        && test "$(_e137_mode_internal 4)" = 3 \
        && echo '  [PASS] four node menu semantics' \
        || { echo '  [FAIL] node protocol mapping'; rc=1; }
    if command -v jq >/dev/null 2>&1 && (
        BEST_SNI=www.example.com
        SNI_JSON_ARRAY='["www.example.com"]'
        REMARK_NAME=e170-selftest
        E79_VLESSENC_NETWORK=raw
        _e118_generate_reality_material() {
            E77_REALITY_PRIV=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA
            E77_REALITY_PUB=BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB
            E77_REALITY_UUID=11111111-1111-4111-8111-111111111111
            E77_REALITY_SID=a1b2c3d4
        }
        e77_generate_vlessenc_pair() {
            E77_VLESSENC_DECRYPTION=mlkem768x25519plus.native.0rtt
            E77_VLESSENC_ENCRYPTION=mlkem768x25519plus.native.0rtt
        }
        for mode in 1 2 3 4; do
            file="$d/mode-$mode.json"
            e79_build_full_config "$mode" 443 8443 8388 \
                2022-blake3-aes-128-gcm AAAAAAAAAAAAAAAAAAAAAA== "$file" || exit 1
            jq -e --arg m "$mode" '
              ([.outbounds[]|select(.tag=="direct" and .protocol=="freedom" and .settings.targetStrategy=="UseIPv4")]|length)==1 and
              (if $m=="1" then ([.inbounds[]|select(.streamSettings.security=="reality")]|length)==1 and ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==0
               elif $m=="2" then ([.inbounds[]|select(.protocol=="vless" and .streamSettings.security=="none")]|length)==1
               elif $m=="3" then ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==1 and ([.inbounds[]|select(.protocol=="vless")]|length)==0
               elif $m=="4" then ([.inbounds[]|select(.streamSettings.security=="reality")]|length)==1 and ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==1
               else false end)' "$file" >/dev/null || exit 1
        done
    ); then
        echo '  [PASS] all four node builders and IPv4 Freedom contract'
    else
        echo '  [FAIL] generated node contract'
        rc=1
    fi
    declare -f _e170_install_mode | grep -q '_e137_validate_semantic_config' \
        && declare -f _e170_install_mode | grep -q '_e138_warp_config_integrity' \
        && declare -f _e118_write_generated_metadata | grep -q '_e170_write_generated_metadata_impl' \
        && echo '  [PASS] node config/runtime/metadata/WARP gates bind to E170' \
        || { echo '  [FAIL] node transaction binding'; rc=1; }
    _e170_optimization_menu_audit >/dev/null \
        && echo '  [PASS] every menu-10 entry is bound' \
        || { echo '  [FAIL] menu-10 handler audit'; rc=1; }
    body=$(declare -f _e165_ssh_guard_install_base)
    grep -q 'live-ban-after-final-restart' <<<"$body" \
        && grep -q 'final-readback' <<<"$body" \
        && echo '  [PASS] SSH staged transaction and final live proof' \
        || { echo '  [FAIL] SSH staged gates'; rc=1; }
    menu=$(declare -f _e170_main_menu_impl)
    grep -q 'V199e170 - 事务稳态版' <<<"$menu" \
        && grep -q '21) 跨境代理网络参数集合' <<<"$menu" \
        && echo '  [PASS] E127 homepage contract retained' \
        || { echo '  [FAIL] homepage contract'; rc=1; }
    hot=$(declare -f _e170_hot_update)
    grep -q '_e170_install_self' <<<"$hot" \
        && grep -q '_e170_ssh_guard_verify_final' <<<"$hot" \
        && grep -q 'E170_HOT_LOG' <<<"$hot" \
        && echo '  [PASS] E170 hot-update identity and final gates' \
        || { echo '  [FAIL] hot-update binding'; rc=1; }
    rm -rf -- "$d"
    _e170_structure_audit >/dev/null || rc=1
    test "$rc" -eq 0 && echo 'V199e170 result: PASS' || echo 'V199e170 result: FAIL'
    return "$rc"
}

