#==============================================================================
# V199e172 FINAL RELIABILITY LAYER
#==============================================================================
readonly E172_VERSION="199e172"
readonly E172_DIR="$CONFIG_DIR/e172"
readonly E172_SELF_PATH="$SCRIPT_DIR/ex199e172.sh"
readonly E172_LATEST_PATH="$SCRIPT_DIR/ex199e_latest.sh"
readonly E172_TX_ROOT="/var/backups/xray-e172"
readonly E172_HOT_LOG="/var/log/xray/e172/hot-update-last.log"
readonly E172_CRITICAL_MARKER="$E172_DIR/CRITICAL_RECOVERY_REQUIRED.env"
readonly E172_BACKEND_STATE="$E172_DIR/firewall-backend.env"
readonly E172_BACKEND_DIAG="/var/log/xray/e172/firewall-backend-last.log"
E172_BACKEND_OVERRIDE=""

# Preserve the last detector before adding the E172 capability/state layer.
if declare -F _e152_firewall_backend >/dev/null 2>&1; then
    eval "$(declare -f _e152_firewall_backend | sed \
        '1s/_e152_firewall_backend/_e172_firewall_backend_base/')"
fi

_e172_backend_diag() {
    local result="${1:-unknown}" detail="${2:-}" backend="${3:-none}"
    install -d -m 0700 "$(dirname "$E172_BACKEND_DIAG")" 2>/dev/null || return 0
    {
        echo "time=$(date -Is 2>/dev/null || date)"
        echo "result=$result"
        echo "detail=$detail"
        echo "backend=$backend"
        echo "virt=$(systemd-detect-virt 2>/dev/null || echo unknown)"
        echo "kernel=$(uname -r 2>/dev/null || echo unknown)"
        echo "euid=$EUID"
        echo "cap_eff=$(awk '/^CapEff:/{print $2}' /proc/self/status 2>/dev/null || echo unreadable)"
        echo '--- commands'
        command -v nft 2>&1 || true
        command -v iptables 2>&1 || true
        command -v ufw 2>&1 || true
        command -v firewall-cmd 2>&1 || true
        echo '--- versions'
        nft --version 2>&1 || true
        iptables --version 2>&1 || true
        echo '--- read probes'
        nft list ruleset 2>&1 | sed -n '1,80p' || true
        iptables -w 2 -S INPUT 2>&1 | sed -n '1,80p' || true
        echo '--- kernel modules'
        grep -E '(^|[[:space:]])(nf_tables|ip_tables|x_tables)([[:space:]]|$)' /proc/modules 2>/dev/null || true
    } >"$E172_BACKEND_DIAG" 2>&1
    chmod 0600 "$E172_BACKEND_DIAG" 2>/dev/null || true
}

# These probes create only an unreferenced temporary table/chain and delete it
# before returning.  They never flush an existing ruleset and never add an
# ACCEPT/DROP rule to INPUT.
_e172_nft_write_probe() (
    local table="xray_e172_probe_$$_$RANDOM" rc=0
    command -v nft >/dev/null 2>&1 || return 1
    _e214_ensure_run_lock || return 1
    exec 172>/run/lock/xray-firewall-capability-e172.lock
    flock -w 30 172 || return 1
    cleanup() { nft delete table inet "$table" >/dev/null 2>&1 || true; }
    trap cleanup EXIT INT TERM HUP
    nft add table inet "$table" >/dev/null 2>&1 || return 1
    nft "add chain inet $table probe_input { type filter hook input priority -1; }" \
        >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || nft "add set inet $table probe_addr { type ipv4_addr; }" \
        >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || nft list chain inet "$table" probe_input >/dev/null 2>&1 || rc=1
    cleanup
    trap - EXIT INT TERM HUP
    ! nft list table inet "$table" >/dev/null 2>&1 || rc=1
    return "$rc"
)

_e172_iptables_write_probe() (
    local chain="XE172P$$_$RANDOM" rc=0
    chain=${chain:0:27}
    command -v iptables >/dev/null 2>&1 || return 1
    _e214_ensure_run_lock || return 1
    exec 172>/run/lock/xray-firewall-capability-e172.lock
    flock -w 30 172 || return 1
    cleanup() {
        iptables -w 2 -F "$chain" >/dev/null 2>&1 || true
        iptables -w 2 -X "$chain" >/dev/null 2>&1 || true
    }
    trap cleanup EXIT INT TERM HUP
    iptables -w 2 -N "$chain" >/dev/null 2>&1 || return 1
    iptables -w 2 -L "$chain" -n >/dev/null 2>&1 || rc=1
    cleanup
    trap - EXIT INT TERM HUP
    ! iptables -w 2 -L "$chain" -n >/dev/null 2>&1 || rc=1
    return "$rc"
)

_e172_backend_record() {
    local backend="$1" source="$2" tmp
    case "$backend" in nft|iptables|ufw|firewalld) ;; *) return 1 ;; esac
    install -d -m 0700 "$E172_DIR" || return 1
    tmp="${E172_BACKEND_STATE}.tmp.$$"
    {
        echo "version=$E172_VERSION"
        echo "preferred_backend=$backend"
        echo "source=$source"
        echo "nft_service_started=0"
        echo "sshd_stopped=0"
        echo "xray_stopped=0"
        echo "verified=$(date -Is 2>/dev/null || date)"
    } >"$tmp" || { rm -f -- "$tmp"; return 1; }
    chmod 0600 "$tmp" || return 1
    mv -f -- "$tmp" "$E172_BACKEND_STATE" || return 1
    E172_BACKEND_OVERRIDE="$backend"
}

# Active firewall managers always win.  Otherwise a previously verified E172
# capability is reused only while its read path is still valid.
_e152_firewall_backend() {
    local detected preferred="${E172_BACKEND_OVERRIDE:-}"
    detected=$(_e172_firewall_backend_base 2>/dev/null || echo none)
    case "$detected" in ufw|firewalld) echo "$detected"; return 0 ;; esac
    if test -z "$preferred" && test -s "$E172_BACKEND_STATE"; then
        preferred=$(sed -n 's/^preferred_backend=//p' "$E172_BACKEND_STATE" | tail -n1)
    fi
    case "$preferred" in
        nft)
            command -v nft >/dev/null 2>&1 && nft list ruleset >/dev/null 2>&1 \
                && { echo nft; return 0; }
            ;;
        iptables)
            command -v iptables >/dev/null 2>&1 && iptables -w 2 -S INPUT >/dev/null 2>&1 \
                && { echo iptables; return 0; }
            ;;
        ufw|firewalld) ;;
    esac
    echo "$detected"
}

_e172_remove_package() {
    local pkg="$1"
    case "$pkg" in nftables|iptables|fail2ban|python3-systemd) ;; *) return 0 ;; esac
    if command -v apt-get >/dev/null 2>&1; then
        apt-get -o DPkg::Lock::Timeout=120 remove -y -- "$pkg" >/dev/null 2>&1 || true
    elif command -v dnf >/dev/null 2>&1; then
        dnf -y remove "$pkg" >/dev/null 2>&1 || true
    elif command -v yum >/dev/null 2>&1; then
        yum -y remove "$pkg" >/dev/null 2>&1 || true
    fi
}

_e172_remove_packages_since() {
    local start="${1:-0}" i
    [[ "$start" =~ ^[0-9]+$ ]] || start=0
    for ((i=${#E135_NEW_PACKAGES[@]}-1; i>=start; i--)); do
        _e172_remove_package "${E135_NEW_PACKAGES[$i]}"
    done
    E135_NEW_PACKAGES=("${E135_NEW_PACKAGES[@]:0:start}")
    hash -r 2>/dev/null || true
}

_e172_install_package_no_start() {
    local pkg="$1" cmd="$2" was=0 rc=0
    command -v "$cmd" >/dev/null 2>&1 && return 0
    _e135_pkg_present "$pkg" && was=1 || true

    # Debian-family maintainer scripts consult policy-rc.d.  A short-lived,
    # transactionally restored policy prevents package installation from
    # starting a firewall service behind the current SSH session.  The package
    # supplies command-line capability only; E172 never loads /etc/nftables.conf.
    if command -v apt-get >/dev/null 2>&1 && command -v dpkg-query >/dev/null 2>&1; then
        (
            local d policy=/usr/sbin/policy-rc.d tmp
            d=$(mktemp -d /run/xray-e172-policy.XXXXXX) || exit 1
            cleanup() {
                _e135_restore_file "$policy" "$d/policy" >/dev/null 2>&1 || true
                rm -rf -- "$d" 2>/dev/null || true
            }
            trap cleanup EXIT INT TERM HUP
            _e135_snapshot_file "$policy" "$d/policy" || exit 1
            tmp="$d/policy.new"
            printf '%s\n' '#!/bin/sh' '# E172 package transaction: never start services' 'exit 101' >"$tmp" || exit 1
            install -m 0755 "$tmp" "$policy" || exit 1
            pkg_install "$pkg" || exit $?
            command -v "$cmd" >/dev/null 2>&1 || exit 1
        ) || rc=$?
        hash -r 2>/dev/null || true
        test "$rc" -eq 0 || return "$rc"
        test "$was" -eq 1 || E135_NEW_PACKAGES+=("$pkg")
        return 0
    fi
    _e135_install_package_verified "$pkg" "$cmd"
}

_e172_nft_service_contract() {
    local enabled_before="$1" active_before="$2" enabled_after active_after
    enabled_after=$(systemctl is-enabled nftables.service 2>/dev/null || true)
    active_after=$(systemctl is-active nftables.service 2>/dev/null || true)
    case "$enabled_before" in
        enabled|enabled-runtime|linked|linked-runtime)
            case "$enabled_after" in enabled|enabled-runtime|linked|linked-runtime) ;; *)
                error 'nftables.service启用状态在能力安装期间意外丢失。'; return 1 ;;
            esac
            ;;
        *)
            case "$enabled_after" in
                enabled|enabled-runtime|linked|linked-runtime)
                    # Disabling a unit does not execute ExecStop and therefore
                    # cannot flush a live ruleset.
                    systemctl disable nftables.service >/dev/null 2>&1 || return 1
                    enabled_after=$(systemctl is-enabled nftables.service 2>/dev/null || true)
                    case "$enabled_after" in enabled|enabled-runtime|linked|linked-runtime) return 1 ;; esac
                    ;;
            esac
            ;;
    esac
    case "$active_before" in
        active|activating|reloading)
            case "$active_after" in active|activating|reloading) ;; *)
                error '原本活动的nftables.service在能力安装期间发生状态漂移。'; return 1 ;;
            esac
            ;;
        *)
            case "$active_after" in
                active|activating|reloading)
                    error '软件包安装意外启动nftables.service；为避免flush在线规则，不执行盲目stop。'
                    return 1
                    ;;
            esac
            ;;
    esac
}

_e172_ensure_firewall_backend() {
    local backend source=existing nft_enabled_before nft_active_before
    nft_enabled_before=$(systemctl is-enabled nftables.service 2>/dev/null || true)
    nft_active_before=$(systemctl is-active nftables.service 2>/dev/null || true)
    backend=$(_e172_firewall_backend_base 2>/dev/null || echo none)
    case "$backend" in
        ufw|firewalld)
            _e172_backend_record "$backend" active-manager || return 1
            _e172_backend_diag pass active-manager "$backend"
            info "SSH防护沿用活动防火墙管理器：$backend。"
            return 0
            ;;
        nft)
            if _e172_nft_write_probe; then
                _e172_backend_record nft existing-write-capability || return 1
                _e172_backend_diag pass existing-write-capability nft
                info '已验证原生nftables读写能力；空ruleset也可由Fail2ban创建独立表。'
                return 0
            fi
            warn 'nft命令可读但写能力探测失败，将尝试iptables后端。'
            ;;
        iptables)
            if _e172_iptables_write_probe; then
                _e172_backend_record iptables existing-write-capability || return 1
                _e172_backend_diag pass existing-write-capability iptables
                info '已验证iptables独立链读写能力。'
                return 0
            fi
            warn 'iptables可读但无法创建独立链，将尝试原生nftables。'
            ;;
    esac

    source=auto-installed
    if ! command -v nft >/dev/null 2>&1; then
        _e172_install_package_no_start nftables nft || true
        hash -r 2>/dev/null || true
    fi
    _e172_nft_service_contract "$nft_enabled_before" "$nft_active_before" || {
        _e172_backend_diag fail nftables-service-state-drift none
        return 1
    }
    modprobe nf_tables >/dev/null 2>&1 || true
    if command -v nft >/dev/null 2>&1 && nft list ruleset >/dev/null 2>&1 \
        && _e172_nft_write_probe; then
        _e172_backend_record nft "$source-nftables" || return 1
        _e172_backend_diag pass "$source-nftables" nft
        info '未发现活动防火墙后端；已安装并验证nftables能力（未启动nftables.service，未接管整机规则）。'
        return 0
    fi

    if ! command -v iptables >/dev/null 2>&1; then
        _e172_install_package_no_start iptables iptables || true
        hash -r 2>/dev/null || true
    fi
    modprobe ip_tables >/dev/null 2>&1 || true
    if command -v iptables >/dev/null 2>&1 && iptables -w 2 -S INPUT >/dev/null 2>&1 \
        && _e172_iptables_write_probe; then
        _e172_backend_record iptables "$source-iptables" || return 1
        _e172_backend_diag pass "$source-iptables" iptables
        info '原生nftables不可写；已安装并验证iptables独立链能力。'
        return 0
    fi

    E172_BACKEND_OVERRIDE=""
    _e172_backend_diag fail no-netfilter-write-capability none
    error '系统没有可验证的nftables/iptables写能力；无法安全实现按IP封禁。'
    error "可能缺少CAP_NET_ADMIN或VPS内核禁用netfilter；诊断：$E172_BACKEND_DIAG"
    return 1
}

_e172_backend_state_verify() {
    local expected actual
    test -s "$E172_BACKEND_STATE" || return 1
    expected=$(sed -n 's/^preferred_backend=//p' "$E172_BACKEND_STATE" | tail -n1)
    actual=$(_e152_firewall_backend 2>/dev/null || echo none)
    test "$expected" = "$actual" || return 1
    grep -qx 'nft_service_started=0' "$E172_BACKEND_STATE" || return 1
    grep -qx 'sshd_stopped=0' "$E172_BACKEND_STATE" || return 1
    grep -qx 'xray_stopped=0' "$E172_BACKEND_STATE" || return 1
    case "$actual" in
        nft) command -v nft >/dev/null 2>&1 && nft list ruleset >/dev/null 2>&1 ;;
        iptables) command -v iptables >/dev/null 2>&1 && iptables -w 2 -S INPUT >/dev/null 2>&1 ;;
        ufw) LC_ALL=C ufw status 2>/dev/null | grep -qi '^Status: active' ;;
        firewalld) firewall-cmd --state 2>/dev/null | grep -qi running ;;
        *) return 1 ;;
    esac
}

_e152_firewall_backend_status() {
    local backend
    if test "$EUID" -ne 0; then
        echo 'firewall_backend=unknown-unprivileged'
        echo 'privilege=root-required-to-read-active-ruleset'
        return 0
    fi
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    echo "firewall_backend=$backend"
    echo "e172_state=$E172_BACKEND_STATE"
    echo "e172_diagnostic=$E172_BACKEND_DIAG"
    case "$backend" in
        nft) echo 'ssh_guard_model=fail2ban-owned-native-nft-base-chain' ;;
        iptables) echo 'ssh_guard_model=managed-iptables-chain' ;;
        ufw|firewalld) echo 'ssh_guard_model=active-firewall-manager' ;;
        *) echo 'ssh_guard_model=capability-provision-required' ;;
    esac
}

_e172_ssh_listener_precheck() {
    local ports listening p current_port
    command -v sshd >/dev/null 2>&1 && sshd -t >/dev/null 2>&1 || {
        error 'sshd配置语法/命令预检失败。'
        return 1
    }
    ports=$(_e116_detect_ssh_ports 2>/dev/null | sort -nu || true)
    test -n "$ports" || ports=22
    listening=$(ss -H -ltn 2>/dev/null | awk '{a=$4;sub(/^.*:/,"",a);if(a~/^[0-9]+$/)print a}' | sort -nu)
    for p in $ports; do
        grep -Fxq "$p" <<<"$listening" || {
            error "SSH配置端口$p当前没有TCP监听，拒绝进入防火墙事务。"
            return 1
        }
    done
    current_port=$(_e135_current_ssh_port 2>/dev/null || true)
    test -z "$current_port" || grep -Fxq "$current_port" <<<"$listening" || {
        error "当前SSH会话端口$current_port不在监听集合，拒绝继续。"
        return 1
    }
}

# Extend the local SSH transaction with every historical audit unit that will
# be paused/retired.  The seal is regenerated after appending their states.
if declare -F _e152_nft_ssh_tx_begin >/dev/null 2>&1; then
    eval "$(declare -f _e152_nft_ssh_tx_begin | sed \
        '1s/_e152_nft_ssh_tx_begin/_e172_nft_ssh_tx_begin_base/')"
fi
_e152_nft_ssh_tx_begin() {
    local tx unit
    tx=$(_e172_nft_ssh_tx_begin_base) || return 1
    rm -f -- "$tx/ssh-seal.sha256" || return 1
    for unit in \
        xray-ssh-auth-audit-e141w.service xray-ssh-auth-audit-e141w.timer \
        xray-ssh-auth-audit-e142.service xray-ssh-auth-audit-e142.timer \
        xray-ssh-auth-audit-e143.service xray-ssh-auth-audit-e143.timer; do
        grep -q "^${unit}|" "$tx/services.env" 2>/dev/null \
            || _e152_unit_state_line "$unit" >>"$tx/services.env" || return 1
    done
    (cd "$tx" && find . -type f ! -name ssh-seal.sha256 ! -name COMMITTED \
        -print0 | sort -z | xargs -0 sha256sum >ssh-seal.sha256) || return 1
    test -s "$tx/ssh-seal.sha256" || return 1
    printf '%s\n' "$tx"
}

_e172_quiesce_ssh_managers() {
    local auth_mode="${1:-unknown}" unit
    local -a timers=(
        xray-ssh-native-e152.timer xray-ssh-auth-audit-e152.timer
        xray-ssh-auth-audit-e141w.timer xray-ssh-auth-audit-e142.timer
        xray-ssh-auth-audit-e143.timer xray-ssh-port-guard-e121.timer
    )
    local -a audits=(
        xray-ssh-native-e152.service xray-ssh-auth-audit-e152.service
        xray-ssh-auth-audit-e141w.service xray-ssh-auth-audit-e142.service
        xray-ssh-auth-audit-e143.service xray-ssh-port-guard-e121.service
    )
    for unit in "${timers[@]}"; do systemctl stop "$unit" >/dev/null 2>&1 || true; done
    for unit in "${audits[@]}"; do systemctl stop "$unit" >/dev/null 2>&1 || true; done
    if test "$auth_mode" = password-capable; then
        systemctl stop fail2ban.service >/dev/null 2>&1 || true
        systemctl is-active --quiet fail2ban.service 2>/dev/null && {
            error '无法在已快照事务内暂停Fail2ban；拒绝并发改写规则。'
            return 1
        }
    fi
    for unit in "${timers[@]}" "${audits[@]}"; do
        systemctl is-active --quiet "$unit" 2>/dev/null && {
            error "无法暂停会争用SSH配置的单元：$unit"
            return 1
        }
    done
    _e172_ssh_listener_precheck || {
        error '暂停审计组件后SSH监听读回失败。'
        return 1
    }
    info "已暂停旧SSH审计/自愈触发器（auth=$auth_mode）；密码模式下Fail2ban也已在快照内暂停。sshd、当前监听、Xray和现有防火墙管理器保持运行。"
}

_e172_retire_legacy_ssh_audits() {
    local unit state
    for unit in \
        xray-ssh-auth-audit-e141w.timer xray-ssh-auth-audit-e141w.service \
        xray-ssh-auth-audit-e142.timer xray-ssh-auth-audit-e142.service \
        xray-ssh-auth-audit-e143.timer xray-ssh-auth-audit-e143.service; do
        systemctl disable --now "$unit" >/dev/null 2>&1 || true
        systemctl is-active --quiet "$unit" 2>/dev/null && return 1
        state=$(systemctl is-enabled "$unit" 2>/dev/null || true)
        case "$state" in enabled|enabled-runtime|linked|linked-runtime) return 1 ;; esac
    done
}

# Rebuild the nft path with an explicit quiet window.  Fail2ban may be stopped
# inside its already-snapshotted transaction; sshd and Xray are never stopped.
_e165_ssh_guard_install_base() {
    local profile mode ip tmp backend tx="" failed=0 stage=prepare restart_after_install=0
    _e141_prepare || return 1
    profile=$(_e141_sshd_auth_profile) || { error '无法读取sshd有效认证配置。'; return 1; }
    mode=$(sed -n 's/^mode=//p' <<<"$profile" | head -n1)
    ip=$(_e135_current_ssh_ip 2>/dev/null || true)
    E152_CURRENT_SSH_IP="$ip"
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    if test "$backend" != nft; then
        tmp="${E141_SSH_AUTH_STATE}.tmp.$$"
        {
            printf '%s\n' "$profile"
            printf 'current_ssh_ip=%s\nfirewall_backend=%s\nchecked_at=%s\n' \
                "$ip" "$backend" "$(date -Is 2>/dev/null || date)"
        } >"$tmp" || return 1
        install -m 0600 "$tmp" "$E141_SSH_AUTH_STATE" || { rm -f "$tmp"; return 1; }
        rm -f "$tmp"
        _e152_ssh_guard_inherited || return 1
        return 0
    fi

    stage=snapshot
    tx=$(_e152_nft_ssh_tx_begin) || { error '原生nftables SSH变更前快照失败。'; return 1; }
    stage=quiesce
    _e172_quiesce_ssh_managers "$mode" || failed=1
    tmp="${E141_SSH_AUTH_STATE}.tmp.$$"
    if test "$failed" -eq 0; then
        {
            printf '%s\n' "$profile"
            printf 'current_ssh_ip=%s\nfirewall_backend=%s\nchecked_at=%s\ntransaction=%s\n' \
                "$ip" "$backend" "$(date -Is 2>/dev/null || date)" "$tx"
        } >"$tmp" || failed=1
        test "$failed" -ne 0 || install -m 0600 "$tmp" "$E141_SSH_AUTH_STATE" || failed=1
    fi
    rm -f "$tmp" 2>/dev/null || true

    if test "$failed" -eq 0; then
        case "$mode" in
            key-only|non-password)
                stage=key-only-audit
                info "原生nftables + $mode：保留现有策略并部署只读SSH审计。"
                _e152_install_nft_ssh_audit || failed=1
                ;;
            password-capable)
                stage=fail2ban-install
                info '原生nftables + 密码认证：安装Fail2ban官方nftables action。'
                _e121_install_fail2ban_guard || failed=1
                if test "$failed" -eq 0 && test -n "$ip" && ! _e170_current_ip_ignored "$ip"; then
                    stage=ignoreip-reconcile
                    _e135_patch_fail2ban_ignoreip "$ip" || failed=1
                    test "$failed" -ne 0 || restart_after_install=1
                fi
                if test "$failed" -eq 0; then
                    stage=passive-readback
                    _e152_fail2ban_passive_verify || failed=1
                fi
                if test "$failed" -eq 0; then
                    if test "$restart_after_install" -eq 1; then
                        stage=live-ban-after-final-restart
                        _e152_verify_nft_fail2ban_action || failed=1
                    else
                        stage=live-proof-readback
                        _e170_fail2ban_live_proof && _e165_helper_check || failed=1
                    fi
                fi
                if test "$failed" -eq 0; then
                    stage=boot-audit-install
                    _e152_install_nft_ssh_audit || failed=1
                fi
                ;;
            ambiguous)
                stage=ambiguous-audit
                warn 'SSH认证策略存在Match歧义：不改变nft策略，只部署读回审计。'
                _e152_install_nft_ssh_audit || failed=1
                ;;
            *) stage=auth-mode; failed=1 ;;
        esac
    fi
    if test "$failed" -eq 0; then stage=auth-audit-install; _e152_install_ssh_auth_audit || failed=1; fi
    if test "$failed" -eq 0; then stage=legacy-audit-retire; _e172_retire_legacy_ssh_audits || failed=1; fi
    if test "$failed" -eq 0; then stage=legacy-guard-disable; _e152_disable_legacy_iptables_ssh_guard || failed=1; fi
    if test "$failed" -eq 0; then stage=final-readback; _e152_nft_ssh_check || failed=1; fi
    if test "$failed" -eq 0; then stage=commit; _e152_nft_ssh_tx_commit "$tx" || failed=1; fi
    if test "$failed" -ne 0; then
        error "E172原生nftables SSH/Fail2ban事务失败阶段：$stage"
        error '恢复原配置、服务状态及所有脚本专用表。'
        _e152_nft_ssh_tx_rollback "$tx" || warn "局部回滚未完整成功；快照：$tx"
        return 1
    fi
    info "E172 SSH事务已提交：auth=$mode backend=nft ports=$(_e165_detect_ports_csv)。"
}

if declare -F _e141_install_ssh_guard >/dev/null 2>&1; then
    eval "$(declare -f _e141_install_ssh_guard | sed \
        '1s/_e141_install_ssh_guard/_e172_install_ssh_guard_lock_base/')"
fi
_e141_install_ssh_guard() {
    local before_count=${#E135_NEW_PACKAGES[@]} prov restore_state restore_nft rc=0
    prov=$(_e172_new_tx ssh-backend-provision) || return 1
    restore_state="$prov/backend-state.before"
    restore_nft="$prov/nftables-conf.before"
    _e135_snapshot_file "$E172_BACKEND_STATE" "$restore_state" || return 1
    _e135_snapshot_file /etc/nftables.conf "$restore_nft" || return 1
    _e172_ssh_listener_precheck || return 1
    if ! _e172_ensure_firewall_backend; then
        _e172_remove_packages_since "$before_count"
        _e135_restore_file "$E172_BACKEND_STATE" "$restore_state" || true
        _e135_restore_file /etc/nftables.conf "$restore_nft" || true
        return 1
    fi
    if _e172_install_ssh_guard_lock_base "$@"; then
        rc=0
    else
        rc=$?
        _e172_remove_packages_since "$before_count"
        _e135_restore_file "$E172_BACKEND_STATE" "$restore_state" || true
        _e135_restore_file /etc/nftables.conf "$restore_nft" || true
        E172_BACKEND_OVERRIDE=""
    fi
    return "$rc"
}
_e135_install_ssh_guard() { _e141_install_ssh_guard "$@"; }
_e121_install_ssh_guard() { _e141_install_ssh_guard "$@"; }
_e116_install_ssh_guard() { _e141_install_ssh_guard "$@"; }

