# Every hot-update phase now writes to the E172 log.
_e159_hot_step() {
    local phase="$1"; shift
    _e159_phase_log "$E172_HOT_LOG" "$phase" begin
    if "$@"; then
        _e159_phase_log "$E172_HOT_LOG" "$phase" ok
        return 0
    fi
    _e159_phase_log "$E172_HOT_LOG" "$phase" fail
    error "E172热更新失败阶段：$phase"
    return 1
}

if declare -F _e170_hot_update_preflight >/dev/null 2>&1; then
    eval "$(declare -f _e170_hot_update_preflight | sed \
        -e '1s/_e170_hot_update_preflight/_e172_hot_update_preflight/' \
        -e 's/_e170_/_e172_/g' -e 's/E170/E172/g' -e 's/e170/e172/g')"
fi
if declare -F _e172_hot_update_preflight >/dev/null 2>&1; then
