        '1s/_e172_hot_update_preflight/_e172_hot_update_preflight_base/')"
fi
_e172_hot_update_preflight() {
    local backend
    _e172_hot_update_preflight_base || return 1
    for c in systemctl sshd ss ip; do
        command -v "$c" >/dev/null 2>&1 || {
            error "E172 SSH不中断预检缺少命令：$c"
            return 1
        }
    done
    sshd -t >/dev/null 2>&1 || {
        error 'E172预检发现sshd配置无效；尚未修改防火墙。'
        return 1
    }
    _e172_ssh_listener_precheck || return 1
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    if test "$backend" = none && ! command -v nft >/dev/null 2>&1 \
      && ! command -v iptables >/dev/null 2>&1; then
        if ! command -v apt-get >/dev/null 2>&1 \
          && ! command -v dnf >/dev/null 2>&1 \
          && ! command -v yum >/dev/null 2>&1; then
            error '没有防火墙命令且没有受支持的软件包管理器，无法自动补齐netfilter用户态能力。'
            return 1
        fi
        info '预检确认当前缺少防火墙命令；将在系统快照完成后优先补齐并验证nftables/iptables能力。'
    fi
}
