    eval "$(declare -f _e170_hot_update | sed \
        -e '1s/_e170_hot_update/_e172_hot_update/' \
        -e 's/_e170_/_e172_/g' -e 's/E170/E172/g' -e 's/e170/e172/g' \
        -e 's/test "$rc" -ne 0 || _e159_hot_step warp-state-migrate/test "$rc" -ne 0 || _e159_hot_step firewall-capability _e172_ensure_firewall_backend || rc=1; test "$rc" -ne 0 || _e159_hot_step warp-state-migrate/' \
        -e 's/_e172_ssh_guard_verify_final/_e172_ssh_guard_verify_final/g')"
fi
hot_update_from_legacy() { _e172_hot_update_preflight && _e172_hot_update; }

_e172_structure_audit() {
    local rc=0 size lines dispatchers menu advanced hot ssh ensure quiesce
    echo 'V199e172 structure audit:'
    size=$(wc -c <"$SCRIPT_PATH" | tr -d ' ')
    lines=$(wc -l <"$SCRIPT_PATH" | tr -d ' ')
    dispatchers=$(grep -c '^# V199e172 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true)
    menu=$(declare -f _e172_main_menu_impl 2>/dev/null || true)
    advanced=$(declare -f _e172_advanced_menu 2>/dev/null || true)
    hot=$(declare -f _e172_hot_update 2>/dev/null || true)
    ssh=$(declare -f _e165_ssh_guard_install_base 2>/dev/null || true)
    ensure=$(declare -f _e172_ensure_firewall_backend 2>/dev/null || true)
    quiesce=$(declare -f _e172_quiesce_ssh_managers 2>/dev/null || true)
    echo "  file_bytes=$size"
    echo "  lines=$lines"
    echo "  final_dispatchers=$dispatchers"
    echo '  menu_owner=e172 (E127 top-level contract)'
    echo '  network_owner=e159 data model / E170 ordered ipfrag transaction'
    echo '  ssh_owner=e172 backend bootstrap + E165 official Fail2Ban action'
    test "$size" -gt 2000000 && test "$lines" -gt 45000 || rc=1
    test "$dispatchers" -eq 1 || rc=1
    grep -q 'V199e172 - 事务稳态版' <<<"$menu" || rc=1
    grep -q '_e172_advanced_menu' <<<"$menu" || rc=1
    grep -q '_e172_run_micro_control_menu' <<<"$advanced" || rc=1
    grep -q '_e172_install_self' <<<"$hot" || rc=1
    grep -q '_e172_ssh_guard_verify_final' <<<"$hot" || rc=1
    grep -q '_e172_quiesce_ssh_managers' <<<"$ssh" || rc=1
    grep -q '_e172_install_package_no_start nftables nft' <<<"$ensure" || rc=1
    grep -q '_e172_nft_service_contract' <<<"$ensure" || rc=1
    ! grep -Eq 'systemctl (stop|disable).*nftables' <<<"$ensure" || rc=1
    ! grep -Eq 'systemctl (stop|restart).*\b(xray|ssh|sshd)\b' <<<"$quiesce" || rc=1
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL'
    return "$rc"
}

_e172_self_test() {
    local rc=0 d count unique low_line high_line body menu hot f
    echo 'V199e172 fast release gate:'
    bash -n "$SCRIPT_PATH" && echo '  [PASS] bash syntax' \
        || { echo '  [FAIL] bash syntax'; rc=1; }
    test "$SCRIPT_VERSION" = 199e172 && test "$E172_VERSION" = 199e172 \
        && echo '  [PASS] release identity' \
        || { echo '  [FAIL] release identity'; rc=1; }
    d=$(mktemp -d /tmp/e172-selftest.XXXXXX) || return 1
    _e159_full_spec fq 1 31 "$d/spec.conf" || rc=1
    count=$(grep -Ec '^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=' "$d/spec.conf" || true)
    unique=$(awk -F= '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{k=$1;gsub(/[[:space:]]/,"",k);print k}' \
        "$d/spec.conf" | sort -u | wc -l | tr -d ' ')
    test "$count" = 127 && test "$unique" = 127 && _e159_spec_validate "$d/spec.conf" \
        && echo '  [PASS] exact 127-request / 125-control model' \
        || { echo '  [FAIL] network request model'; rc=1; }
    cp -f "$d/spec.conf" "$d/order.conf"
    _e170_reorder_ipfrag_file "$d/order.conf" || rc=1
    low_line=$(grep -n '^net.ipv4.ipfrag_low_thresh' "$d/order.conf" | cut -d: -f1)
    high_line=$(grep -n '^net.ipv4.ipfrag_high_thresh' "$d/order.conf" | cut -d: -f1)
    test -n "$low_line" && test -n "$high_line" && (( high_line < low_line )) \
        && echo '  [PASS] ipfrag high-before-low ordering retained' \
        || { echo '  [FAIL] ipfrag ordering'; rc=1; }
    if (
        clear() { :; }; title() { :; }; hr() { :; }
        printf '0\n' | _e172_micro_control_menu
    ) >"$d/micro.out" 2>"$d/micro.err" \
        && grep -q '  1) TCP NoDelay' "$d/micro.out" \
        && grep -q ' 28) 应用层' "$d/micro.out" \
        && _e152_micro_control_available; then
        echo '  [PASS] menu 10 -> 6 retains visible 1-28 entries'
    else
        echo '  [FAIL] 28-item menu behavior'; rc=1
    fi
    test "$(_e137_mode_internal 1)" = 1 \
        && test "$(_e137_mode_internal 2)" = 4 \
        && test "$(_e137_mode_internal 3)" = 2 \
        && test "$(_e137_mode_internal 4)" = 3 \
        && echo '  [PASS] four node menu semantics' \
        || { echo '  [FAIL] node mapping'; rc=1; }
    if command -v jq >/dev/null 2>&1 && (
        BEST_SNI=www.example.com
        SNI_JSON_ARRAY='["www.example.com"]'
        REMARK_NAME=e172-selftest
        E79_VLESSENC_NETWORK=raw
        _e118_generate_reality_material() {
            E77_REALITY_PRIV=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA
            E77_REALITY_PUB=BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB
            E77_REALITY_UUID=11111111-1111-4111-8111-111111111111
            E77_REALITY_SID=a1b2c3d4
        }
        e77_generate_vlessenc_pair() {
            E77_VLESSENC_DECRYPTION=mlkem768x25519plus.native.0rtt
            E77_VLESSENC_ENCRYPTION=mlkem768x25519plus.native.0rtt
        }
        for mode in 1 2 3 4; do
            file="$d/mode-$mode.json"
            e79_build_full_config "$mode" 443 8443 8388 \
                2022-blake3-aes-128-gcm AAAAAAAAAAAAAAAAAAAAAA== "$file" || exit 1
            jq -e --arg m "$mode" '
              ([.outbounds[]|select(.tag=="direct" and .protocol=="freedom" and .settings.targetStrategy=="UseIPv4")]|length)==1 and
              (if $m=="1" then ([.inbounds[]|select(.streamSettings.security=="reality")]|length)==1 and ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==0
               elif $m=="2" then ([.inbounds[]|select(.protocol=="vless" and .streamSettings.security=="none")]|length)==1
               elif $m=="3" then ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==1 and ([.inbounds[]|select(.protocol=="vless")]|length)==0
               elif $m=="4" then ([.inbounds[]|select(.streamSettings.security=="reality")]|length)==1 and ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==1
               else false end)' "$file" >/dev/null || exit 1
        done
    ); then
        echo '  [PASS] all four node builders and IPv4 Freedom contract'
    else
        echo '  [FAIL] generated node contract'; rc=1
    fi
    declare -f _e172_install_mode | grep -q '_e137_validate_semantic_config' \
        && declare -f _e172_install_mode | grep -q '_e138_warp_config_integrity' \
        && declare -f _e118_write_generated_metadata | grep -q '_e172_write_generated_metadata_impl' \
        && echo '  [PASS] node survival/metadata/WARP gates bind to E172' \
        || { echo '  [FAIL] node transaction binding'; rc=1; }
    body=$(declare -f _e172_ensure_firewall_backend)
    grep -q '_e172_install_package_no_start nftables nft' <<<"$body" \
        && grep -q '_e172_nft_write_probe' <<<"$body" \
        && grep -q '_e172_iptables_write_probe' <<<"$body" \
        && grep -q '_e172_nft_service_contract' <<<"$body" \
        && declare -f _e172_install_package_no_start | grep -q 'policy-rc.d' \
        && ! grep -Eq 'systemctl[[:space:]]+enable([[:space:]]|.*--now).*nftables\.service' <<<"$body" \
        && echo '  [PASS] empty/no-backend capability bootstrap without nftables.service takeover' \
        || { echo '  [FAIL] firewall capability bootstrap'; rc=1; }
    body=$(declare -f _e172_quiesce_ssh_managers)
    grep -q 'xray-ssh-auth-audit-e152.timer' <<<"$body" \
        && grep -q 'systemctl stop fail2ban.service' <<<"$body" \
        && ! grep -Eq 'systemctl (stop|restart).*\b(xray|ssh|sshd)\b' <<<"$body" \
        && echo '  [PASS] quiet window pauses managers but not sshd/Xray' \
        || { echo '  [FAIL] quiet-window contract'; rc=1; }
    body=$(declare -f _e165_ssh_guard_install_base)
    grep -q 'stage=quiesce' <<<"$body" \
        && grep -q 'stage=final-readback' <<<"$body" \
        && echo '  [PASS] SSH staged transaction and rollback binding' \
        || { echo '  [FAIL] SSH staged gates'; rc=1; }
    _e172_optimization_menu_audit >/dev/null \
        && echo '  [PASS] all menu-10 handlers and 1-28 entries are bound' \
        || { echo '  [FAIL] menu-10 audit'; rc=1; }
    menu=$(declare -f _e172_main_menu_impl)
    grep -q 'V199e172 - 事务稳态版' <<<"$menu" \
        && grep -q '21) 跨境代理网络参数集合' <<<"$menu" \
        && echo '  [PASS] E127 homepage contract retained' \
        || { echo '  [FAIL] homepage contract'; rc=1; }
    hot=$(declare -f _e172_hot_update)
    grep -q '_e172_install_self' <<<"$hot" \
        && grep -q '_e172_ssh_guard_verify_final' <<<"$hot" \
        && grep -q 'ssh-guard-e172' <<<"$hot" \
        && echo '  [PASS] E172 hot-update identity and SSH final gate' \
        || { echo '  [FAIL] hot-update binding'; rc=1; }
    rm -rf -- "$d"
    _e172_structure_audit >/dev/null || rc=1
    test "$rc" -eq 0 && echo 'V199e172 result: PASS' || echo 'V199e172 result: FAIL'
    return "$rc"
}

