# Every state writer must create its own destination parent.  A hot update may
# legitimately arrive after an older cleanup removed e141/e152/e159 directories;
# relying on another version's prepare function recreates the E178 failure.
_e182_secure_state_temp() {
    local dest="$1" dir_mode="${2:-0700}" parent
    test -n "$dest" && [[ "$dest" = /* ]] || return 1
    parent=$(dirname -- "$dest") || return 1
    # Do not let install(1) follow an already-present attacker-controlled link.
    # The post-create check remains necessary for the missing-directory case.
    test ! -L "$parent" || return 1
    install -d -m "$dir_mode" "$parent" || return 1
    test -d "$parent" && test ! -L "$parent" || return 1
    mktemp "${dest}.tmp.XXXXXX"
}

_e182_commit_state() {
    local tmp="$1" dest="$2" mode="${3:-0600}"
    test -f "$tmp" && test -n "$dest" || return 1
    chmod "$mode" "$tmp" || { rm -f -- "$tmp"; return 1; }
    mv -f -- "$tmp" "$dest" || { rm -f -- "$tmp"; return 1; }
    chmod "$mode" "$dest" || return 1
}

if declare -F _e152_firewall_backend >/dev/null 2>&1; then
    eval "$(declare -f _e152_firewall_backend | sed \
        '1s/_e152_firewall_backend/_e182_firewall_detector_base/')"
fi

_e182_backend_state_get() {
    local key="$1" fallback="${2:-}"
    test -s "$E182_BACKEND_STATE" \
        && sed -n "s/^${key}=//p" "$E182_BACKEND_STATE" | tail -n1 \
        || printf '%s\n' "$fallback"
}

_e182_backend_record() {
    local backend="$1" source="$2" ip_ban="${3:-0}" reason="${4:-none}" tmp
    case "$backend" in nft|iptables|ufw|firewalld|sshd-native) ;; *) return 1 ;; esac
    tmp=$(_e182_secure_state_temp "$E182_BACKEND_STATE") || return 1
    {
        echo "version=$E182_VERSION"
        echo "preferred_backend=$backend"
        echo "source=$source"
        echo "ip_ban_capable=$ip_ban"
        echo "degraded=$(test "$ip_ban" = 1 && echo 0 || echo 1)"
        echo "reason=$reason"
        echo "iptables_target=$(readlink -f "$(command -v iptables 2>/dev/null)" 2>/dev/null || true)"
        echo "ip6tables_target=$(readlink -f "$(command -v ip6tables 2>/dev/null)" 2>/dev/null || true)"
        echo "nft_service_started=0"
        echo "sshd_stopped=0"
        echo "xray_stopped=0"
        echo "verified=$(date -Is 2>/dev/null || date)"
    } >"$tmp" || { rm -f -- "$tmp"; return 1; }
    _e182_commit_state "$tmp" "$E182_BACKEND_STATE" || return 1
    E182_BACKEND_OVERRIDE="$backend"
    # 只允许紧接着的SSH事务复用这一次真实探测，使用后必须清零。
    E182_BACKEND_PREFLIGHT_VERIFIED=1
}

_e182_backend_diag() {
    local result="${1:-unknown}" detail="${2:-none}" selected="${3:-none}" bin
    install -d -m 0700 "$(dirname "$E182_BACKEND_DIAG")" 2>/dev/null || return 0
    {
        echo "time=$(date -Is 2>/dev/null || date)"
        echo "result=$result"
        echo "detail=$detail"
        echo "selected=$selected"
        echo "virt=$(systemd-detect-virt 2>/dev/null || echo unknown)"
        echo "kernel=$(uname -r 2>/dev/null || echo unknown)"
        echo "euid=$EUID"
        echo "cap_eff=$(awk '/^CapEff:/{print $2}' /proc/self/status 2>/dev/null || echo unreadable)"
        echo '--- nft'
        command -v nft 2>&1 || true
        nft --version 2>&1 || true
        nft list ruleset 2>&1 | sed -n '1,100p' || true
        echo '--- xtables variants'
        for bin in iptables iptables-nft iptables-legacy ip6tables ip6tables-nft ip6tables-legacy; do
            echo "[$bin]"
            command -v "$bin" 2>&1 || true
            "$bin" --version 2>&1 || true
            "$bin" -w 2 -S INPUT 2>&1 | sed -n '1,40p' || true
        done
        echo '--- modules'
        grep -E '(^|[[:space:]])(nf_tables|ip_tables|ip6_tables|x_tables)([[:space:]]|$)' \
            /proc/modules 2>/dev/null || true
        echo '--- sshd native capabilities'
        sshd -T 2>/dev/null | grep -E '^(maxauthtries|logingracetime|maxstartups|persourcemaxstartups|persourcepenalties) ' || true
    } >"$E182_BACKEND_DIAG" 2>&1
    chmod 0600 "$E182_BACKEND_DIAG" 2>/dev/null || true
}

_e182_xtables_write_probe() (
    local bin="$1" chain="XE182P$$_$RANDOM" rc=0
    chain=${chain:0:27}
    command -v "$bin" >/dev/null 2>&1 || return 1
    _e214_ensure_run_lock || return 1
    exec 176>/run/lock/xray-xtables-capability-e182.lock
    flock -w 30 176 || return 1
    cleanup() {
        "$bin" -w 3 -F "$chain" >/dev/null 2>&1 || true
        "$bin" -w 3 -X "$chain" >/dev/null 2>&1 || true
    }
    trap cleanup EXIT INT TERM HUP
    "$bin" -w 3 -N "$chain" >/dev/null 2>&1 || return 1
    "$bin" -w 3 -L "$chain" -n >/dev/null 2>&1 || rc=1
    cleanup
    trap - EXIT INT TERM HUP
    ! "$bin" -w 3 -L "$chain" -n >/dev/null 2>&1 || rc=1
    return "$rc"
)

_e182_ipv6_guard_required() {
    declare -F _e159_ipv6_ssh_relevant >/dev/null 2>&1 \
        && _e159_ipv6_ssh_relevant
}

_e182_switch_xtables_variant() {
    local candidate="$1" variant old4 old6 target4 target6 rc=0
    case "$candidate" in iptables-nft) variant=nft ;; iptables-legacy) variant=legacy ;; *) return 1 ;; esac
    target4=$(command -v "$candidate" 2>/dev/null || true)
    target6=$(command -v "ip6tables-$variant" 2>/dev/null || true)
    test -n "$target4" || return 1
    _e182_ipv6_guard_required && test -z "$target6" && return 1
    old4=$(readlink /etc/alternatives/iptables 2>/dev/null \
        || readlink -f "$(command -v iptables 2>/dev/null)" 2>/dev/null || true)
    old6=$(readlink /etc/alternatives/ip6tables 2>/dev/null \
        || readlink -f "$(command -v ip6tables 2>/dev/null)" 2>/dev/null || true)

    if command -v update-alternatives >/dev/null 2>&1; then
        update-alternatives --set iptables "$target4" >/dev/null 2>&1 || rc=1
        if test "$rc" -eq 0 && test -n "$target6"; then
            update-alternatives --set ip6tables "$target6" >/dev/null 2>&1 || rc=1
        fi
    elif command -v alternatives >/dev/null 2>&1; then
        alternatives --set iptables "$target4" >/dev/null 2>&1 || rc=1
        if test "$rc" -eq 0 && test -n "$target6"; then
            alternatives --set ip6tables "$target6" >/dev/null 2>&1 || rc=1
        fi
    else
        return 1
    fi
    hash -r 2>/dev/null || true
    test "$rc" -ne 0 || _e182_xtables_write_probe iptables || rc=1
    if test "$rc" -eq 0 && _e182_ipv6_guard_required; then
        _e182_xtables_write_probe ip6tables || rc=1
    fi
    if test "$rc" -ne 0; then
        if command -v update-alternatives >/dev/null 2>&1; then
            test -z "$old4" || update-alternatives --set iptables "$old4" >/dev/null 2>&1 || true
            test -z "$old6" || update-alternatives --set ip6tables "$old6" >/dev/null 2>&1 || true
        elif command -v alternatives >/dev/null 2>&1; then
            test -z "$old4" || alternatives --set iptables "$old4" >/dev/null 2>&1 || true
            test -z "$old6" || alternatives --set ip6tables "$old6" >/dev/null 2>&1 || true
        fi
        hash -r 2>/dev/null || true
        return 1
    fi
    return 0
}

_e182_try_xtables_matrix() {
    local candidate v6 selected=""
    for candidate in iptables iptables-legacy iptables-nft; do
        command -v "$candidate" >/dev/null 2>&1 || continue
        _e182_xtables_write_probe "$candidate" || continue
        if _e182_ipv6_guard_required; then
            case "$candidate" in
                iptables) v6=ip6tables ;;
                iptables-legacy) v6=ip6tables-legacy ;;
                iptables-nft) v6=ip6tables-nft ;;
            esac
            command -v "$v6" >/dev/null 2>&1 && _e182_xtables_write_probe "$v6" || continue
        fi
        if test "$candidate" != iptables; then
            _e182_switch_xtables_variant "$candidate" || continue
        fi
        _e182_xtables_write_probe iptables || continue
        selected="$candidate"
        break
    done
    test -n "$selected" || return 1
    printf '%s\n' "$selected"
}

# Active UFW/firewalld still wins.  E182 state additionally represents the
# verified OpenSSH-native fallback, which intentionally has no IP-ban claim.
_e152_firewall_backend() {
    local detected preferred="${E182_BACKEND_OVERRIDE:-}"
    detected=$(_e182_firewall_detector_base 2>/dev/null || echo none)
    case "$detected" in ufw|firewalld) echo "$detected"; return 0 ;; esac
    if test -z "$preferred" && test -s "$E182_BACKEND_STATE"; then
        preferred=$(_e182_backend_state_get preferred_backend none)
    fi
    case "$preferred" in
        nft)
            command -v nft >/dev/null 2>&1 && nft list ruleset >/dev/null 2>&1 \
                && { echo nft; return 0; }
            ;;
        iptables)
            command -v iptables >/dev/null 2>&1 && iptables -w 2 -S INPUT >/dev/null 2>&1 \
                && { echo iptables; return 0; }
            ;;
        sshd-native) echo sshd-native; return 0 ;;
    esac
    echo "$detected"
}

_e182_ensure_firewall_backend() {
    local backend selected nft_enabled_before nft_active_before nft_contract_ok=1
    local before_count=${#E135_NEW_PACKAGES[@]}
    backend=$(_e182_firewall_detector_base 2>/dev/null || echo none)
    case "$backend" in
        ufw|firewalld)
            _e182_backend_record "$backend" active-manager 1 none || return 1
            _e182_backend_diag pass active-manager "$backend"
            info "SSH防护沿用活动防火墙管理器：$backend。"
            return 0
            ;;
        nft)
            if _e172_nft_write_probe; then
                _e182_backend_record nft existing-nft 1 none || return 1
                _e182_backend_diag pass existing-nft nft
                info '已验证原生nftables临时表、输入hook与集合写入能力。'
                return 0
            fi
            ;;
        iptables)
            if selected=$(_e182_try_xtables_matrix); then
                _e182_backend_record iptables "existing-$selected" 1 none || return 1
                _e182_backend_diag pass "existing-$selected" iptables
                info "已验证xtables后端：$selected。"
                return 0
            fi
            ;;
    esac

    nft_enabled_before=$(systemctl is-enabled nftables.service 2>/dev/null || true)
    nft_active_before=$(systemctl is-active nftables.service 2>/dev/null || true)
    command -v nft >/dev/null 2>&1 || _e172_install_package_no_start nftables nft || true
    hash -r 2>/dev/null || true
    _e172_nft_service_contract "$nft_enabled_before" "$nft_active_before" || {
        nft_contract_ok=0
        warn 'nftables软件包服务状态发生漂移；不采用该后端，继续测试xtables/OpenSSH。'
    }
    modprobe nf_tables >/dev/null 2>&1 || true
    if test "$nft_contract_ok" -eq 1 \
      && command -v nft >/dev/null 2>&1 && nft list ruleset >/dev/null 2>&1 \
      && _e172_nft_write_probe; then
        _e182_backend_record nft auto-installed-nft 1 none || return 1
        _e182_backend_diag pass auto-installed-nft nft
        info '已安装并验证nftables能力；未启动或加载nftables.service。'
        return 0
    fi

    command -v iptables >/dev/null 2>&1 || _e172_install_package_no_start iptables iptables || true
    hash -r 2>/dev/null || true
    modprobe ip_tables >/dev/null 2>&1 || true
    modprobe ip6_tables >/dev/null 2>&1 || true
    if selected=$(_e182_try_xtables_matrix); then
        _e182_backend_record iptables "auto-$selected" 1 none || return 1
        _e182_backend_diag pass "auto-$selected" iptables
        info "nft不可写；已验证并选择xtables后端：$selected。"
        return 0
    fi

    # A container without CAP_NET_ADMIN cannot implement a truthful firewall
    # ban.  This is a capability classification, not a reason to roll back DAT,
    # Xray, logging and network transactions.  The SSH phase will install and
    # verify built-in sshd throttles without disabling password authentication.
    _e182_backend_record sshd-native no-netfilter-write 0 cap-net-admin-or-kernel || return 1
    _e182_backend_diag degraded no-netfilter-write sshd-native
    _e172_remove_packages_since "$before_count"
    warn 'nft、iptables-nft与iptables-legacy均不可写；切换到OpenSSH原生限流/审计模式。'
    warn "该模式不能宣称按IP防火墙封禁；完整诊断：$E182_BACKEND_DIAG"
    return 0
}

_e182_sshd_reload_safe() {
    local pid need_hup=0
    sshd -t >/dev/null 2>&1 || return 1
    if systemctl is-active --quiet ssh.service 2>/dev/null; then
        systemctl reload ssh.service >/dev/null 2>&1 || need_hup=1
    elif systemctl is-active --quiet sshd.service 2>/dev/null; then
        systemctl reload sshd.service >/dev/null 2>&1 || need_hup=1
    elif systemctl is-active --quiet ssh.socket 2>/dev/null \
      || systemctl is-active --quiet sshd.socket 2>/dev/null; then
        : # Socket activation reads the validated file for new daemon instances.
    else
        need_hup=1
    fi
    if test "$need_hup" -eq 1; then
        pid=$(ss -H -ltnp 2>/dev/null \
            | sed -n 's/.*"sshd",pid=\([0-9][0-9]*\).*/\1/p' | head -n1)
        [[ "$pid" =~ ^[0-9]+$ ]] || return 1
        test "$(cat "/proc/$pid/comm" 2>/dev/null || true)" = sshd || return 1
        kill -HUP "$pid" >/dev/null 2>&1 || return 1
        sleep 1
    fi
    _e172_ssh_listener_precheck
}

_e182_native_effective_values() {
    sshd -T 2>/dev/null | awk '
      $1=="maxauthtries" || $1=="logingracetime" || $1=="maxstartups" ||
      $1=="persourcemaxstartups" || $1=="persourcepenalties" {print}'
}

_e182_native_values_verify() {
    local auth="$1" grace="$2" starts="$3" per="${4:-}" dump
    dump=$(_e182_native_effective_values) || return 1
    grep -qx "maxauthtries $auth" <<<"$dump" || return 1
    grep -qx "logingracetime $grace" <<<"$dump" || return 1
    grep -qx "maxstartups $starts" <<<"$dump" || return 1
    test -z "$per" || grep -qx "persourcemaxstartups $per" <<<"$dump"
}

_e182_tighten_maxstartups() {
    local current="$1" s r f new_s new_r new_f
    IFS=: read -r s r f <<<"$current"
    [[ "$s" =~ ^[0-9]+$ ]] || s=10
    [[ "$r" =~ ^[0-9]+$ ]] || r=30
    [[ "$f" =~ ^[0-9]+$ ]] || f=100
    # start/full越小越严格；rate是从start开始的拒绝概率，越大越严格。
    # E172曾把rate方向写反，可能把用户已有的高拒绝率降到30%。
    (( s < 10 )) && new_s=$s || new_s=10
    (( r > 30 )) && new_r=$r || new_r=30
    (( f < 60 )) && new_f=$f || new_f=60
    (( new_f < new_s )) && new_f=$new_s
    printf '%s:%s:%s\n' "$new_s" "$new_r" "$new_f"
}

_e182_strip_main_native_block() {
    local src="$1" dst="$2"
    awk -v b="$E182_NATIVE_MAIN_BEGIN" -v e="$E182_NATIVE_MAIN_END" \
        -v pb="$E182_PREVIOUS_NATIVE_MAIN_BEGIN" -v pe="$E182_PREVIOUS_NATIVE_MAIN_END" \
        -v ob="$E182_OLDER_NATIVE_MAIN_BEGIN" -v oe="$E182_OLDER_NATIVE_MAIN_END" \
        -v lb="$E182_LEGACY_NATIVE_MAIN_BEGIN" -v le="$E182_LEGACY_NATIVE_MAIN_END" '
      $0==b  {if(skip) exit 2; skip="current"; next}
      $0==pb {if(skip) exit 2; skip="previous"; next}
      $0==ob {if(skip) exit 2; skip="older"; next}
      $0==lb {if(skip) exit 2; skip="legacy"; next}
      $0==e  {if(skip!="current") exit 2; skip=""; next}
      $0==pe {if(skip!="previous") exit 2; skip=""; next}
      $0==oe {if(skip!="older") exit 2; skip=""; next}
      $0==le {if(skip!="legacy") exit 2; skip=""; next}
      !skip {print}
      END {if(skip) exit 2}
    ' "$src" >"$dst"
}

_e182_write_native_settings() {
    local settings="$1" auth="$2" grace="$3" starts="$4" per="${5:-}"
    local d clean main_tmp main_mode
    install -d -m 0755 /etc/ssh/sshd_config.d || return 1
    d=$(mktemp -d /run/xray-e182-sshd.XXXXXX) || return 1
    clean="$d/sshd.clean"
    main_tmp="$d/sshd.new"
    _e182_strip_main_native_block /etc/ssh/sshd_config "$clean" || { rm -rf -- "$d"; return 1; }
    main_mode=$(stat -c '%a' /etc/ssh/sshd_config 2>/dev/null || echo 600)
    [[ "$main_mode" =~ ^[0-7]{3,4}$ ]] || main_mode=600
    rm -f -- "$E182_PREVIOUS_NATIVE_DROPIN" "$E182_OLDER_NATIVE_DROPIN" \
        "$E182_LEGACY_NATIVE_DROPIN" \
        || { rm -rf -- "$d"; return 1; }
    if ! cmp -s "$clean" /etc/ssh/sshd_config; then
        _e118_atomic_install "$clean" /etc/ssh/sshd_config "$main_mode" \
            || { rm -rf -- "$d"; return 1; }
    fi
    _e118_atomic_install "$settings" "$E182_NATIVE_DROPIN" 0644 \
        || { rm -rf -- "$d"; return 1; }
    if sshd -t >/dev/null 2>&1 \
      && _e182_native_values_verify "$auth" "$grace" "$starts" "$per"; then
        rm -rf -- "$d"
        printf '%s\n' dropin
        return 0
    fi

    # Some distributions process an explicit value before their Include, so a
    # drop-in cannot override it.  Prepend one sealed E182 block to the already
    # sanitized main file; OpenSSH's first-value rule makes it deterministic.
    rm -f -- "$E182_NATIVE_DROPIN" || { rm -rf -- "$d"; return 1; }
    {
        echo "$E182_NATIVE_MAIN_BEGIN"
        cat "$settings"
        echo "$E182_NATIVE_MAIN_END"
        cat "$clean"
    } >"$main_tmp" || { rm -rf -- "$d"; return 1; }
    _e118_atomic_install "$main_tmp" /etc/ssh/sshd_config "$main_mode" \
        || { rm -rf -- "$d"; return 1; }
    rm -rf -- "$d"
    sshd -t >/dev/null 2>&1 \
        && _e182_native_values_verify "$auth" "$grace" "$starts" "$per" \
        && { printf '%s\n' main-prefix; return 0; }
    return 1
}

_e182_native_state_write() {
    local mode="$1" auth="${2:-none}" grace="${3:-none}" starts="${4:-none}"
    local per="${5:-none}" location="${6:-none}" tx="${7:-none}" tmp jail_runtime
    jail_runtime=$(_e182_managed_f2b_runtime_state)
    tmp=$(_e182_secure_state_temp "$E182_NATIVE_STATE") || return 1
    {
        echo "version=$E182_VERSION"
        echo "mode=$mode"
        echo "ip_ban_capable=0"
        echo "maxauthtries=$auth"
        echo "logingracetime=$grace"
        echo "maxstartups=$starts"
        echo "persourcemaxstartups=$per"
        echo "location=$location"
        echo "transaction=$tx"
        echo "managed_jail_runtime=$jail_runtime"
        echo "checked_at=$(date -Is 2>/dev/null || date)"
    } >"$tmp" || { rm -f -- "$tmp"; return 1; }
    _e182_commit_state "$tmp" "$E182_NATIVE_STATE"
}

_e182_managed_f2b_runtime_state() {
    if ! command -v fail2ban-client >/dev/null 2>&1; then
        echo unavailable
    elif fail2ban-client status "$E121_F2B_JAIL_NAME" >/dev/null 2>&1; then
        echo active
    else
        echo inactive
    fi
}

_e182_disable_managed_f2b_jail_native() {
    local tmp running=0
    if ! command -v fail2ban-client >/dev/null 2>&1 \
      && test ! -e "$E121_F2B_JAIL"; then
        rm -f -- "$E182_NATIVE_F2B_DISABLE" "$E182_PREVIOUS_NATIVE_F2B_DISABLE" \
            "$E182_OLDER_NATIVE_F2B_DISABLE" \
            "$E182_LEGACY_NATIVE_F2B_DISABLE" \
            2>/dev/null || true
        return 0
    fi
    # A partial/manual Fail2Ban install can expose fail2ban-client while omitting
    # jail.d.  Own the destination parent just like the cross-version state
    # writer; otherwise the fallback would fail before its atomic install.
    _e214_ensure_parent_dir "$E182_NATIVE_F2B_DISABLE" || return 1
    tmp=$(mktemp /run/xray-e182-f2b-disable.XXXXXX) || return 1
    {
        echo "[$E121_F2B_JAIL_NAME]"
        echo 'enabled = false'
        echo '# E182: kernel firewall unavailable; do not claim a working ban action.'
    } >"$tmp" || { rm -f -- "$tmp"; return 1; }
    _e121_atomic_install "$tmp" "$E182_NATIVE_F2B_DISABLE" 0644 \
        || { rm -f -- "$tmp"; return 1; }
    rm -f -- "$tmp"
    rm -f -- "$E182_PREVIOUS_NATIVE_F2B_DISABLE" "$E182_OLDER_NATIVE_F2B_DISABLE" \
        "$E182_LEGACY_NATIVE_F2B_DISABLE" || return 1
    if command -v fail2ban-client >/dev/null 2>&1 \
      && fail2ban-client status "$E121_F2B_JAIL_NAME" >/dev/null 2>&1; then
        running=1
        # Fail2Ban正式支持 `stop <JAIL>`。但部分发行版action在清理一条
        # 已不存在的防火墙链时会返回非零；持久的enabled=false才是下次
        # reload/boot的权威状态，运行态清理失败不能让Xray热更新随之失败。
        fail2ban-client stop "$E121_F2B_JAIL_NAME" >/dev/null 2>&1 || true
    fi
    if test "$running" -eq 1; then
        if fail2ban-client status "$E121_F2B_JAIL_NAME" >/dev/null 2>&1; then
            fail2ban-client set "$E121_F2B_JAIL_NAME" idle on >/dev/null 2>&1 || true
            warn "脚本所属Fail2ban jail仍在旧进程中运行；已持久禁用，未重启全局Fail2ban，也未影响其它jail。"
        fi
    fi
    return 0
}

_e182_enable_managed_f2b_jail_firewall() {
    rm -f -- "$E182_NATIVE_F2B_DISABLE" "$E182_PREVIOUS_NATIVE_F2B_DISABLE" \
        "$E182_OLDER_NATIVE_F2B_DISABLE" \
        "$E182_LEGACY_NATIVE_F2B_DISABLE" \
        2>/dev/null || return 1
    if command -v fail2ban-client >/dev/null 2>&1 \
      && fail2ban-client status "$E121_F2B_JAIL_NAME" >/dev/null 2>&1; then
        fail2ban-client set "$E121_F2B_JAIL_NAME" idle off >/dev/null 2>&1 || true
    fi
}

_e182_auth_state_write_native_to() {
    local dest="$1" profile ip tmp
    test -n "$dest" || return 1
    profile=$(_e141_sshd_auth_profile 2>/dev/null || true)
    test -n "$profile" || return 1
    ip=$(_e135_current_ssh_ip 2>/dev/null || true)
    tmp=$(_e182_secure_state_temp "$dest") || return 1
    {
        printf '%s\n' "$profile"
        printf 'current_ssh_ip=%s\nfirewall_backend=sshd-native\nip_ban_capable=0\nchecked_at=%s\n' \
            "$ip" "$(date -Is 2>/dev/null || date)"
    } >"$tmp" || { rm -f -- "$tmp"; return 1; }
    _e182_commit_state "$tmp" "$dest"
}

_e182_auth_state_write_native() {
    _e182_auth_state_write_native_to "$E141_SSH_AUTH_STATE"
}

_e182_native_verify() {
    local mode auth grace starts per backend
    test -s "$E182_NATIVE_STATE" || return 1
    mode=$(sed -n 's/^mode=//p' "$E182_NATIVE_STATE" | tail -n1)
    backend=$(_e182_backend_state_get preferred_backend none)
    test "$backend" = sshd-native || return 1
    grep -qx 'ip_ban_capable=0' "$E182_NATIVE_STATE" || return 1
    sshd -t >/dev/null 2>&1 || return 1
    _e172_ssh_listener_precheck || return 1
    case "$mode" in
        native-throttle)
            auth=$(sed -n 's/^maxauthtries=//p' "$E182_NATIVE_STATE" | tail -n1)
            grace=$(sed -n 's/^logingracetime=//p' "$E182_NATIVE_STATE" | tail -n1)
            starts=$(sed -n 's/^maxstartups=//p' "$E182_NATIVE_STATE" | tail -n1)
            per=$(sed -n 's/^persourcemaxstartups=//p' "$E182_NATIVE_STATE" | tail -n1)
            test "$per" = none && per=""
            _e182_native_values_verify "$auth" "$grace" "$starts" "$per" || return 1
            ;;
        audit-only) ;;
        *) return 1 ;;
    esac
    if test -e "$E182_NATIVE_F2B_DISABLE"; then
        grep -Fxq "[$E121_F2B_JAIL_NAME]" "$E182_NATIVE_F2B_DISABLE" || return 1
        grep -Fxq 'enabled = false' "$E182_NATIVE_F2B_DISABLE" || return 1
        # 旧action清理失败时，单个jail可能在当前server进程中暂时残留。
        # 这不等于具备IP封禁，也不能据此重启用户的其它jail或回滚Xray。
    fi
    systemctl is-enabled --quiet xray-ssh-auth-audit-e152.timer 2>/dev/null || return 1
    systemctl is-active --quiet xray-ssh-auth-audit-e152.timer 2>/dev/null || return 1
    ! systemctl is-enabled --quiet xray-ssh-port-guard-e121.timer 2>/dev/null || return 1
    ! systemctl is-enabled --quiet xray-ssh-native-e152.timer 2>/dev/null || return 1
}

_e182_install_audit_only() {
    local tx="${1:-none}"
    _e172_ssh_listener_precheck || return 1
    _e182_backend_record sshd-native audit-only 0 native-throttle-unavailable || return 1
    systemctl disable --now xray-ssh-port-guard-e121.timer xray-ssh-port-guard-e121.service \
        xray-ssh-native-e152.timer xray-ssh-native-e152.service >/dev/null 2>&1 || true
    _e182_disable_managed_f2b_jail_native || return 1
    _e152_install_ssh_auth_audit || return 1
    _e182_native_state_write audit-only none none none none none "$tx" || return 1
    _e182_auth_state_write_native || return 1
    _e182_native_verify || return 1
    warn 'OpenSSH限流值未能安全接管；已进入只读认证/端口审计模式，未宣称具备IP封禁。'
}

_e182_install_native_guard() {
    # 在 `set -u` 下，同一条 local 中的赋值会先展开右值；不能在这里用
    # tx="$outer_tx" 引用本行才声明的变量。E176实机故障正由此触发。
    local outer_tx tx profile auth_mode dump current_auth current_grace
    local current_starts new_auth new_grace new_starts
    local per_current="" per_new="" settings location rc=0
    outer_tx="${1:-}"
    tx="$outer_tx"
    test -n "$tx" || { tx=$(_e182_new_tx ssh-native-throttle) || return 1; _e140_system_snapshot "$tx" || return 1; }
    profile=$(_e141_sshd_auth_profile 2>/dev/null || true)
    auth_mode=$(sed -n 's/^mode=//p' <<<"$profile" | head -n1)
    test -n "$auth_mode" || auth_mode=unknown
    # 必须把实时探测出的认证模式传入暂停器。硬编码 non-password 会在密码
    # 登录仍开启时漏停 Fail2ban，导致事务中途被旧 jail/action 干扰。
    _e172_quiesce_ssh_managers "$auth_mode" || rc=1
    dump=$(sshd -T 2>/dev/null) || rc=1
    if test "$rc" -eq 0; then
        current_auth=$(awk '$1=="maxauthtries"{print $2;exit}' <<<"$dump")
        current_grace=$(awk '$1=="logingracetime"{print $2;exit}' <<<"$dump")
        current_starts=$(awk '$1=="maxstartups"{print $2;exit}' <<<"$dump")
        [[ "$current_auth" =~ ^[0-9]+$ ]] || current_auth=6
        [[ "$current_grace" =~ ^[0-9]+$ ]] || current_grace=120
        (( current_auth > 0 && current_auth < 3 )) && new_auth=$current_auth || new_auth=3
        (( current_grace > 0 && current_grace < 30 )) && new_grace=$current_grace || new_grace=30
        new_starts=$(_e182_tighten_maxstartups "$current_starts") || rc=1
        per_current=$(awk '$1=="persourcemaxstartups"{print $2;exit}' <<<"$dump")
        if [[ "$per_current" =~ ^[0-9]+$ ]]; then
            (( per_current > 0 && per_current < 3 )) && per_new=$per_current || per_new=3
        elif test "$per_current" = none; then
            # 指令已被当前OpenSSH识别，但发行版默认未限制单来源并发。
            per_new=3
        fi
        settings=$(mktemp /run/xray-e182-native.XXXXXX) || rc=1
    fi
    if test "$rc" -eq 0; then
        {
            echo '# Managed by ex199e182.sh; does not disable password authentication.'
            echo "MaxAuthTries $new_auth"
            echo "LoginGraceTime $new_grace"
            echo "MaxStartups $new_starts"
            test -z "$per_new" || echo "PerSourceMaxStartups $per_new"
        } >"$settings" || rc=1
    fi
    if test "$rc" -eq 0; then
        location=$(_e182_write_native_settings "$settings" "$new_auth" "$new_grace" "$new_starts" "$per_new") || rc=1
    fi
    rm -f -- "${settings:-}" 2>/dev/null || true
    test "$rc" -ne 0 || _e182_sshd_reload_safe || rc=1
    if test "$rc" -eq 0; then
        systemctl disable --now xray-ssh-port-guard-e121.timer xray-ssh-port-guard-e121.service \
            xray-ssh-native-e152.timer xray-ssh-native-e152.service >/dev/null 2>&1 || true
        _e182_disable_managed_f2b_jail_native || rc=1
    fi
    if test "$rc" -eq 0; then
        _e152_install_ssh_auth_audit || rc=1
    fi
    test "$rc" -ne 0 || _e172_retire_legacy_ssh_audits || rc=1
    test "$rc" -ne 0 || _e182_native_state_write native-throttle "$new_auth" "$new_grace" \
        "$new_starts" "${per_new:-none}" "$location" "$tx" || rc=1
    test "$rc" -ne 0 || _e182_auth_state_write_native || rc=1
    test "$rc" -ne 0 || _e182_native_verify || rc=1
    if test "$rc" -eq 0; then
        info "E182 OpenSSH原生限流已验证：auth=$auth_mode MaxAuthTries=$new_auth LoginGraceTime=$new_grace MaxStartups=$new_starts PerSourceMaxStartups=${per_new:-unsupported}。"
        warn '当前VPS没有netfilter写权限，因此没有声称Fail2ban可执行IP封禁。'
        return 0
    fi

    error 'OpenSSH原生限流事务未通过，恢复旧sshd配置和服务状态。'
    if ! _e140_system_restore "$tx" >/dev/null 2>&1 \
      || ! _e182_sshd_reload_safe >/dev/null 2>&1; then
        install -d -m 0700 "${E182_DIR:-$CONFIG_DIR/e182}" 2>/dev/null || true
        {
            echo "time=$(date -Is 2>/dev/null || date)"
            echo 'operation=ssh-native-rollback'
            echo "backup=$tx"
            echo "auth_mode=$auth_mode"
        } >"${E182_CRITICAL_MARKER:-$CONFIG_DIR/e182/CRITICAL_RECOVERY_REQUIRED.env}" 2>/dev/null || true
        error "严重：OpenSSH限流提交和回滚均未通过；保留快照：$tx"
        return 1
    fi
    _e182_install_audit_only "$tx"
}

if declare -F _e142_ssh_auth_reconcile_boot >/dev/null 2>&1; then
    eval "$(declare -f _e142_ssh_auth_reconcile_boot | sed \
        '1s/_e142_ssh_auth_reconcile_boot/_e182_ssh_auth_reconcile_base/')"
fi
_e142_ssh_auth_reconcile_boot() {
    if test "$(_e182_backend_state_get preferred_backend none)" = sshd-native; then
        _e182_native_verify
    else
        _e182_ssh_auth_reconcile_base "$@"
    fi
}

if declare -F _e172_ssh_guard_verify_final >/dev/null 2>&1; then
    eval "$(declare -f _e172_ssh_guard_verify_final | sed \
        '1s/_e172_ssh_guard_verify_final/_e182_ssh_guard_firewall_verify_base/')"
fi
_e182_backend_state_verify() {
    local expected actual
    test -s "$E182_BACKEND_STATE" || return 1
    expected=$(_e182_backend_state_get preferred_backend none)
    actual=$(_e152_firewall_backend 2>/dev/null || echo none)
    test "$expected" = "$actual" || return 1
    grep -qx 'nft_service_started=0' "$E182_BACKEND_STATE" || return 1
    grep -qx 'sshd_stopped=0' "$E182_BACKEND_STATE" || return 1
    grep -qx 'xray_stopped=0' "$E182_BACKEND_STATE" || return 1
    case "$actual" in
        nft)
            grep -qx 'ip_ban_capable=1' "$E182_BACKEND_STATE" \
                && command -v nft >/dev/null 2>&1 \
                && nft list ruleset >/dev/null 2>&1 \
                && _e172_nft_write_probe
            ;;
        iptables)
            grep -qx 'ip_ban_capable=1' "$E182_BACKEND_STATE" \
                && command -v iptables >/dev/null 2>&1 \
                && iptables -w 2 -S INPUT >/dev/null 2>&1 \
                && _e182_xtables_write_probe iptables \
                && { ! _e182_ipv6_guard_required || _e182_xtables_write_probe ip6tables; }
            ;;
        ufw)
            grep -qx 'ip_ban_capable=1' "$E182_BACKEND_STATE" \
                && LC_ALL=C ufw status 2>/dev/null | grep -qi '^Status: active'
            ;;
        firewalld)
            grep -qx 'ip_ban_capable=1' "$E182_BACKEND_STATE" \
                && firewall-cmd --state 2>/dev/null | grep -qi running
            ;;
        sshd-native)
            grep -qx 'ip_ban_capable=0' "$E182_BACKEND_STATE" && _e182_native_verify
            ;;
        *) return 1 ;;
    esac
}
_e182_ssh_guard_verify_final() {
    case "$(_e152_firewall_backend 2>/dev/null || echo none)" in
        sshd-native) _e182_backend_state_verify ;;
        *) _e172_ssh_guard_verify_base "$@" && _e182_backend_state_verify ;;
    esac
}
_e172_ssh_guard_verify_final() { _e182_ssh_guard_verify_final "$@"; }
_e170_ssh_guard_verify_final() { _e182_ssh_guard_verify_final "$@"; }
_e165_ssh_guard_verify_final() { _e182_ssh_guard_verify_final "$@"; }
_e159_ssh_guard_verify_final() { _e182_ssh_guard_verify_final "$@"; }

# A complete outer system snapshot is required here because selecting an
# xtables alternative is persistent.  E172 only snapshotted its state file and
# /etc/nftables.conf, leaving direct menu failures unable to restore symlinks.
if declare -F _e141_install_ssh_guard >/dev/null 2>&1; then
    eval "$(declare -f _e141_install_ssh_guard | sed \
        '1s/_e141_install_ssh_guard/_e182_install_ssh_guard_firewall_base/')"
fi
_e141_install_ssh_guard() {
    local tx backend before_count=${#E135_NEW_PACKAGES[@]} rc=0
    tx=$(_e182_new_tx ssh-guard-dispatch) || return 1
    _e140_system_snapshot "$tx" || return 1
    # The outer dispatcher must own this shared state directory before either
    # the inherited firewall writer or the native fallback can redirect a temp
    # file into it.  The snapshot above deliberately precedes creation so a
    # rollback also restores the directory's former absence and permissions.
    install -d -m 0700 "$E141_DIR" || rc=1
    if test "$rc" -eq 0 && test "${E182_BACKEND_PREFLIGHT_VERIFIED:-0}" != 1; then
        _e182_ensure_firewall_backend || rc=1
    fi
    # 防止主菜单长驻进程在稍后的菜单18里复用陈旧能力结果。
    E182_BACKEND_PREFLIGHT_VERIFIED=0
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    if test "$rc" -eq 0; then
        case "$backend" in
            sshd-native) _e182_install_native_guard "$tx" || rc=1 ;;
            *)
                _e182_enable_managed_f2b_jail_firewall || rc=1
                test "$rc" -ne 0 || _e182_install_ssh_guard_firewall_base "$@" || rc=1
                ;;
        esac
    fi
    if test "$rc" -ne 0; then
        _e140_system_restore "$tx" >/dev/null 2>&1 || true
        _e182_sshd_reload_safe >/dev/null 2>&1 || true
        _e172_remove_packages_since "$before_count"
        E182_BACKEND_OVERRIDE=""
        E182_BACKEND_PREFLIGHT_VERIFIED=0
        return 1
    fi
    E182_BACKEND_PREFLIGHT_VERIFIED=0
    return 0
}
_e135_install_ssh_guard() { _e141_install_ssh_guard "$@"; }
_e121_install_ssh_guard() { _e141_install_ssh_guard "$@"; }
_e116_install_ssh_guard() { _e141_install_ssh_guard "$@"; }

if declare -F _e141_ssh_guard_status >/dev/null 2>&1; then
    eval "$(declare -f _e141_ssh_guard_status | sed \
        '1s/_e141_ssh_guard_status/_e182_ssh_guard_status_base/')"
fi
_e141_ssh_guard_status() {
    if test "$(_e182_backend_state_get preferred_backend none)" = sshd-native; then
        title 'V199e182：OpenSSH原生防爆破降级状态'
        cat "$E182_BACKEND_STATE" 2>/dev/null || true
        cat "$E182_NATIVE_STATE" 2>/dev/null || true
        _e182_native_effective_values || true
        if _e182_native_verify; then
            info '原生限流/审计运行正常；ip_ban_capable=0。'
        else
            error '原生限流/审计读回失败。'
            return 1
        fi
    else
        _e182_ssh_guard_status_base "$@"
    fi
}

