}

#------------------------------------------------------------------------------
# E182 IPv6 policy owner: default disabled, explicit persistent enable/disable,
# live-IPv6 SSH self-lock protection, dedicated rollback and boot revalidation.
# This layer is intentionally separate from E159's 127-request data model.
#------------------------------------------------------------------------------
_e182_ipv6_runtime_capture() {
    local out="$1" f value
    : >"$out" || return 1
    chmod 0600 "$out" || return 1
    if test ! -d "$E182_IPV6_PROC_ROOT"; then
        echo 'kernel-unavailable|1' >"$out"
        return 0
    fi
    for f in "$E182_IPV6_PROC_ROOT"/*/disable_ipv6; do
        test -e "$f" || continue
        value=$(cat "$f" 2>/dev/null) || return 1
        case "$value" in 0|1) ;; *) return 1 ;; esac
        printf '%s|%s\n' "$f" "$value" >>"$out" || return 1
    done
    test -s "$out"
}

_e182_ipv6_runtime_restore() {
    local snap="$1" path value rc=0
    test -s "$snap" || return 1
    grep -qx 'kernel-unavailable|1' "$snap" 2>/dev/null && return 0
    while IFS='|' read -r path value; do
        case "$path" in "$E182_IPV6_PROC_ROOT"/*/disable_ipv6) ;; *) rc=1; continue ;; esac
        case "$value" in 0|1) ;; *) rc=1; continue ;; esac
        test -e "$path" || continue
        printf '%s\n' "$value" >"$path" 2>/dev/null || rc=1
    done <"$snap"
    return "$rc"
}

_e182_ipv6_tx_snapshot() {
    local tx="$1" p key
    install -d -m 0700 "$tx/ipv6" || return 1
    while IFS='|' read -r p key; do
        _e135_snapshot_file "$p" "$tx/ipv6/$key" || return 1
    done <<EOF_E182_IPV6_FILES
$E182_IPV6_CONF|policy-conf
$E182_IPV6_STATE|policy-state
$E182_IPV6_PENDING|pending-state
$E182_IPV6_APPLY|apply-script
$E182_IPV6_SERVICE|systemd-unit
EOF_E182_IPV6_FILES
    _e159_snapshot_service "$E182_IPV6_UNIT" >"$tx/ipv6/service.env" || return 1
    _e182_ipv6_runtime_capture "$tx/ipv6/runtime.tsv" || return 1
    (
        cd "$tx" || exit 1
        find ipv6 -type f ! -name seal.sha256 -exec sha256sum '{}' \; | LC_ALL=C sort -k2 \
            >ipv6/seal.sha256
        test -s ipv6/seal.sha256
    ) || return 1
}

_e182_ipv6_tx_valid() {
    local tx="$1" real root
    test -n "$tx" || return 1
    real=$(readlink -f -- "$tx" 2>/dev/null || true)
    root=$(readlink -f -- "$E182_TX_ROOT" 2>/dev/null || true)
    test -n "$real" && test -n "$root" || return 1
    case "$real" in "$root"/*) ;; *) return 1 ;; esac
    test -s "$real/ipv6/seal.sha256" \
        && (cd "$real" && sha256sum -c ipv6/seal.sha256 >/dev/null 2>&1)
}

_e182_ipv6_tx_restore() {
    local tx="$1" p key unit enabled active rc=0
    _e182_ipv6_tx_valid "$tx" || return 1
    systemctl stop "$E182_IPV6_UNIT" >/dev/null 2>&1 || true
    while IFS='|' read -r p key; do
        _e135_restore_file "$p" "$tx/ipv6/$key" || rc=1
    done <<EOF_E182_IPV6_FILES
$E182_IPV6_CONF|policy-conf
$E182_IPV6_STATE|policy-state
$E182_IPV6_PENDING|pending-state
$E182_IPV6_APPLY|apply-script
$E182_IPV6_SERVICE|systemd-unit
EOF_E182_IPV6_FILES
    systemctl daemon-reload >/dev/null 2>&1 || rc=1
    _e182_ipv6_runtime_restore "$tx/ipv6/runtime.tsv" || rc=1
    IFS='|' read -r unit enabled active <"$tx/ipv6/service.env" || rc=1
    test "$rc" -ne 0 || _e159_restore_service "$unit" "$enabled" "$active" || rc=1
    return "$rc"
}

_e182_ipv6_state_get() {
    local key="$1" fallback="${2:-}"
    test -s "$E182_IPV6_STATE" \
        && sed -n "s/^${key}=//p" "$E182_IPV6_STATE" | tail -n1 \
        || printf '%s\n' "$fallback"
}

_e182_ipv6_state_write() {
    local mode="$1" desired="$2" tx="$3" initial="$4" source="$5" tmp
    case "$mode" in enabled|disabled|kernel-disabled) ;; *) return 1 ;; esac
    case "$desired" in 0|1) ;; *) return 1 ;; esac
    tmp=$(_e182_secure_state_temp "$E182_IPV6_STATE") || return 1
    {
        echo "version=$E182_VERSION"
        echo "mode=$mode"
        echo "desired_disable_ipv6=$desired"
        echo "transaction=$tx"
        echo "initial_transaction=$initial"
        echo "source=$source"
        echo "persistent_conf=$E182_IPV6_CONF"
        echo "checked_at=$(date -Is 2>/dev/null || date)"
    } >"$tmp" || { rm -f -- "$tmp"; return 1; }
    _e182_commit_state "$tmp" "$E182_IPV6_STATE"
}

_e182_ipv6_runtime_set() {
    local desired="$1" f current rc=0
    case "$desired" in 0|1) ;; *) return 1 ;; esac
    test -d "$E182_IPV6_PROC_ROOT" || { test "$desired" = 1; return; }
    # default first governs future interfaces; all and each present interface
    # are then converged so an old per-device override cannot survive.
    for f in "$E182_IPV6_PROC_ROOT/default/disable_ipv6" \
        "$E182_IPV6_PROC_ROOT/all/disable_ipv6" \
        "$E182_IPV6_PROC_ROOT"/*/disable_ipv6; do
        test -e "$f" || continue
        current=$(cat "$f" 2>/dev/null || true)
        test "$current" = "$desired" || printf '%s\n' "$desired" >"$f" 2>/dev/null || rc=1
    done
    return "$rc"
}

_e182_ipv6_verify() {
    local desired="$1" f value
    case "$desired" in 0|1) ;; *) return 1 ;; esac
    if test ! -d "$E182_IPV6_PROC_ROOT"; then
        test "$desired" = 1
        return
    fi
    test -s "$E182_IPV6_CONF" && test -x "$E182_IPV6_APPLY" \
        && test -s "$E182_IPV6_SERVICE" || return 1
    grep -qx "net.ipv6.conf.all.disable_ipv6 = $desired" "$E182_IPV6_CONF" || return 1
    grep -qx "net.ipv6.conf.default.disable_ipv6 = $desired" "$E182_IPV6_CONF" || return 1
    grep -qx "net.ipv6.conf.lo.disable_ipv6 = $desired" "$E182_IPV6_CONF" || return 1
    systemctl is-enabled --quiet "$E182_IPV6_UNIT" 2>/dev/null || return 1
    for f in "$E182_IPV6_PROC_ROOT"/*/disable_ipv6; do
        test -e "$f" || continue
        value=$(cat "$f" 2>/dev/null || true)
        test "$value" = "$desired" || return 1
    done
}

_e182_ipv6_install_assets() {
    local desired="$1" conf_tmp script_tmp unit_tmp rc=0
    conf_tmp=$(mktemp /run/xray-e182-ipv6-conf.XXXXXX) || return 1
    script_tmp=$(mktemp /run/xray-e182-ipv6-apply.XXXXXX) || { rm -f -- "$conf_tmp"; return 1; }
    unit_tmp=$(mktemp /run/xray-e182-ipv6-unit.XXXXXX) \
        || { rm -f -- "$conf_tmp" "$script_tmp"; return 1; }
    {
        echo '# Managed by ex199e182.sh. Use menu 25 or --ipv6-enable/--ipv6-disable.'
        echo "net.ipv6.conf.all.disable_ipv6 = $desired"
        echo "net.ipv6.conf.default.disable_ipv6 = $desired"
        echo "net.ipv6.conf.lo.disable_ipv6 = $desired"
    } >"$conf_tmp" || rc=1
    cat >"$script_tmp" <<'EOF_E182_IPV6_APPLY'
#!/usr/bin/env bash
conf=/etc/sysctl.d/99-z-xray-ipv6-policy.conf
desired=$(sed -n 's/^[[:space:]]*net\.ipv6\.conf\.all\.disable_ipv6[[:space:]]*=[[:space:]]*\([01]\)[[:space:]]*$/\1/p' "$conf" 2>/dev/null | tail -n1)
case "$desired" in 0|1) ;; *) exit 1 ;; esac
test -d /proc/sys/net/ipv6/conf || { test "$desired" = 1; exit; }
rc=0
for f in /proc/sys/net/ipv6/conf/default/disable_ipv6 \
    /proc/sys/net/ipv6/conf/all/disable_ipv6 \
    /proc/sys/net/ipv6/conf/*/disable_ipv6; do
    test -e "$f" || continue
    test "$(cat "$f" 2>/dev/null)" = "$desired" \
        || printf '%s\n' "$desired" >"$f" 2>/dev/null || rc=1
done
exit "$rc"
EOF_E182_IPV6_APPLY
    cat >"$unit_tmp" <<EOF_E182_IPV6_UNIT
[Unit]
Description=Xray E182 persistent IPv6 policy revalidation
After=systemd-sysctl.service procps.service
Before=network-online.target
ConditionPathExists=/proc/sys/net/ipv6/conf

[Service]
Type=oneshot
ExecStart=$E182_IPV6_APPLY

[Install]
WantedBy=multi-user.target
EOF_E182_IPV6_UNIT
    install -d -m 0755 /etc/sysctl.d /usr/local/libexec /etc/systemd/system || rc=1
    test "$rc" -ne 0 || _e118_atomic_install "$conf_tmp" "$E182_IPV6_CONF" 0644 || rc=1
    test "$rc" -ne 0 || _e118_atomic_install "$script_tmp" "$E182_IPV6_APPLY" 0755 || rc=1
    test "$rc" -ne 0 || _e118_atomic_install "$unit_tmp" "$E182_IPV6_SERVICE" 0644 || rc=1
    rm -f -- "$conf_tmp" "$script_tmp" "$unit_tmp"
    test "$rc" -ne 0 || systemctl daemon-reload >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || systemctl enable "$E182_IPV6_UNIT" >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || _e182_ipv6_runtime_set "$desired" || rc=1
    test "$rc" -ne 0 || systemctl start "$E182_IPV6_UNIT" >/dev/null 2>&1 || rc=1
    return "$rc"
}

_e182_ipv6_live_ssh_session() {
    local client _client_port server _server_port
    test -n "${SSH_CONNECTION:-}" || return 1
    read -r client _client_port server _server_port <<<"$SSH_CONNECTION"
    [[ "$client" == *:* || "$server" == *:* ]]
}

_e182_ipv6_apply() (
    local desired="$1" source="${2:-menu}" hot="${3:-0}"
    local tx initial old_initial mode rc=0 marker_tmp
    case "$desired" in 0|1) ;; *) return 1 ;; esac
    if test "$desired" = 1 && _e182_ipv6_live_ssh_session; then
        error '当前管理会话使用IPv6；拒绝立即关闭IPv6，避免SSH自锁。请改用IPv4 SSH或控制台后重试。'
        return 2
    fi
    _e214_ensure_run_lock || return 1
    exec 182>/run/lock/xray-ipv6-policy-e182.lock
    flock -w 30 182 || { error '另一个IPv6策略事务正在运行。'; return 1; }
    _e182_ipv6_hot_recover_stale || {
        error '无法恢复上次中断的IPv6事务；拒绝覆盖其回滚证据。'
        return 1
    }
    tx=$(_e182_new_tx ipv6-policy) || return 1
    _e182_ipv6_tx_snapshot "$tx" || return 1
    old_initial=$(_e182_ipv6_state_get initial_transaction '')
    if _e182_ipv6_tx_valid "$old_initial"; then initial="$old_initial"; else initial="$tx"; fi
    if test "$hot" = 1; then
        marker_tmp=$(_e182_secure_state_temp "$E182_IPV6_HOT_MARKER") || return 1
        printf 'transaction=%s\n' "$tx" >"$marker_tmp" \
            && _e182_commit_state "$marker_tmp" "$E182_IPV6_HOT_MARKER" \
            || { rm -f -- "$marker_tmp"; return 1; }
    fi
    if test ! -d "$E182_IPV6_PROC_ROOT"; then
        if test "$desired" = 0; then
            error '当前内核未提供IPv6协议栈，无法执行“开启IPv6”。'
            rc=1
        else
            systemctl disable --now "$E182_IPV6_UNIT" >/dev/null 2>&1 || true
            rm -f -- "$E182_IPV6_CONF" "$E182_IPV6_APPLY" "$E182_IPV6_SERVICE" || rc=1
            systemctl daemon-reload >/dev/null 2>&1 || rc=1
            test "$rc" -ne 0 || _e182_ipv6_state_write kernel-disabled 1 "$tx" "$initial" "$source" || rc=1
        fi
    else
        _e182_ipv6_install_assets "$desired" || rc=1
        test "$rc" -ne 0 || _e182_ipv6_verify "$desired" || rc=1
        if test "$desired" = 1; then mode=disabled; else mode=enabled; fi
        test "$rc" -ne 0 || _e182_ipv6_state_write "$mode" "$desired" "$tx" "$initial" "$source" || rc=1
    fi
    if test "$rc" -ne 0; then
        if ! _e182_ipv6_tx_restore "$tx" >/dev/null 2>&1; then
            install -d -m 0700 "$E182_DIR" 2>/dev/null || true
            {
                echo "time=$(date -Is 2>/dev/null || date)"
                echo 'operation=ipv6-policy'
                echo "backup=$tx"
                echo "desired_disable_ipv6=$desired"
            } >"$E182_CRITICAL_MARKER" 2>/dev/null || true
            error "严重：IPv6策略提交失败且回滚未通过；保留快照：$tx"
            return 1
        fi
        rm -f -- "$E182_IPV6_HOT_MARKER" 2>/dev/null || true
        error 'IPv6策略事务失败，已恢复配置、服务状态和全部可见接口运行值。'
        return 1
    fi
    rm -f -- "$E182_IPV6_PENDING" 2>/dev/null || true
    if grep -qx 'operation=ipv6-policy' "$E182_CRITICAL_MARKER" 2>/dev/null; then
        rm -f -- "$E182_CRITICAL_MARKER" 2>/dev/null || true
    fi
    if test "$desired" = 1; then
        info 'IPv6已永久关闭，并通过当前接口、sysctl.d与开机复检服务读回。'
    else
        info 'IPv6已永久开启，并通过当前接口、sysctl.d与开机复检服务读回。'
    fi
)

_e182_ipv6_policy_desired() {
    local desired
    desired=$(_e182_ipv6_state_get desired_disable_ipv6 '')
    case "$desired" in 0|1) printf '%s\n' "$desired"; return ;; esac
    desired=$(sed -n 's/^[[:space:]]*net\.ipv6\.conf\.all\.disable_ipv6[[:space:]]*=[[:space:]]*\([01]\)[[:space:]]*$/\1/p' \
        "$E182_IPV6_CONF" 2>/dev/null | tail -n1)
    case "$desired" in 0|1) printf '%s\n' "$desired" ;; *) echo 1 ;; esac
}

_e182_ipv6_pending_write() {
    local tmp
    tmp=$(_e182_secure_state_temp "$E182_IPV6_PENDING") || return 1
    {
        echo 'desired_disable_ipv6=1'
        echo 'reason=live-ipv6-ssh-self-lock-protection'
        echo "ssh_connection=${SSH_CONNECTION:-unknown}"
        echo "checked_at=$(date -Is 2>/dev/null || date)"
    } >"$tmp" || { rm -f -- "$tmp"; return 1; }
    _e182_commit_state "$tmp" "$E182_IPV6_PENDING"
}

_e182_ipv6_hot_apply_default() {
    local desired
    desired=$(_e182_ipv6_policy_desired) || return 1
    if test "$desired" = 1 && _e182_ipv6_live_ssh_session; then
        _e182_ipv6_pending_write || return 1
        warn '默认IPv6关闭已因当前IPv6 SSH会话暂缓，避免热更新自锁；请从IPv4 SSH/控制台执行菜单25。'
        return 0
    fi
    _e182_ipv6_apply "$desired" hot-update 1
}

_e182_ipv6_apply_default() {
    local source="${1:-install}" desired
    desired=$(_e182_ipv6_policy_desired) || return 1
    if test "$desired" = 1 && _e182_ipv6_live_ssh_session; then
        _e182_ipv6_pending_write || return 1
        warn '默认IPv6关闭已因当前IPv6 SSH会话暂缓；请从IPv4 SSH/控制台执行菜单25。'
        return 0
    fi
    _e182_ipv6_apply "$desired" "$source" 0
}

_e182_ipv6_hot_rollback_if_marked() {
    local tx
    test -s "$E182_IPV6_HOT_MARKER" || return 0
    tx=$(sed -n 's/^transaction=//p' "$E182_IPV6_HOT_MARKER" | tail -n1)
    _e182_ipv6_tx_restore "$tx" || return 1
    rm -f -- "$E182_IPV6_HOT_MARKER" 2>/dev/null || true
}

_e182_ipv6_hot_commit() {
    rm -f -- "$E182_IPV6_HOT_MARKER" 2>/dev/null || true
}

_e182_ipv6_hot_verify() {
    local desired
    if test -s "$E182_IPV6_PENDING"; then
        _e182_ipv6_live_ssh_session || return 1
        grep -qx 'desired_disable_ipv6=1' "$E182_IPV6_PENDING"
        return
    fi
    desired=$(_e182_ipv6_policy_desired) || return 1
    _e182_ipv6_verify "$desired"
}

_e182_ipv6_hot_recover_stale() {
    test -s "$E182_IPV6_HOT_MARKER" || return 0
    warn '发现上次中断的IPv6热更新事务，先恢复其运行值与持久配置。'
    _e182_ipv6_hot_rollback_if_marked
}

# Recovering an interrupted IPv6 transaction changes both runtime sysctls and
# persistent files, so it must use the same lock as a normal policy commit.
# The hot-update preflight invokes this before taking its new outer snapshot;
# otherwise an IPv6 SSH safety deferral could bypass recovery and later delete
# the old marker as though it belonged to the new transaction.
_e182_ipv6_recover_stale_serialized() (
    test -s "$E182_IPV6_HOT_MARKER" || return 0
    _e214_ensure_run_lock || return 1
    exec 183>/run/lock/xray-ipv6-policy-e182.lock
    flock -w 30 183 || {
        error '另一个IPv6策略事务正在运行，无法恢复中断事务。'
        return 1
    }
    _e182_ipv6_hot_recover_stale
)

_e182_ipv6_status() {
    local desired mode f value mismatch=0 duplicates
    desired=$(_e182_ipv6_policy_desired)
    mode=$(_e182_ipv6_state_get mode unmanaged)
    title 'V199e182：IPv6永久策略状态'
    echo "  策略模式: $mode"
    echo "  期望disable_ipv6: $desired（1=关闭，0=开启）"
    echo "  持久文件: $E182_IPV6_CONF"
    echo "  开机服务: $(systemctl is-enabled "$E182_IPV6_UNIT" 2>/dev/null || echo not-installed)"
    test ! -s "$E182_IPV6_HOT_MARKER" || {
        error '发现未完成的IPv6热更新事务；下一次热更新/策略应用会先执行加锁回滚。'
        sed 's/^/    /' "$E182_IPV6_HOT_MARKER"
        mismatch=1
    }
    test ! -s "$E182_IPV6_PENDING" || { echo '  安全暂缓: 是（当前/上次为IPv6 SSH会话）'; cat "$E182_IPV6_PENDING"; }
    if test -d "$E182_IPV6_PROC_ROOT"; then
        echo '  运行态:'
        for f in "$E182_IPV6_PROC_ROOT"/*/disable_ipv6; do
            test -e "$f" || continue
            value=$(cat "$f" 2>/dev/null || echo unreadable)
            printf '    %-18s %s\n' "$(basename "$(dirname "$f")")" "$value"
            test "$value" = "$desired" || mismatch=1
        done
    else
        echo '  运行态: 内核未提供IPv6协议栈（等效关闭）'
        test "$desired" = 1 || mismatch=1
    fi
    duplicates=$(grep -RnsE '^[[:space:]]*net\.ipv6\.conf\.(all|default|lo)\.disable_ipv6[[:space:]]*=' \
        /etc/sysctl.conf /etc/sysctl.d /usr/lib/sysctl.d /lib/sysctl.d 2>/dev/null \
        | grep -Fv "$E182_IPV6_CONF:" || true)
    if test -n "$duplicates"; then
        warn '发现其它IPv6持久定义；E182开机服务会在sysctl加载后重新收敛，以下仅供审计：'
        sed 's/^/    /' <<<"$duplicates"
    fi
    test "$mismatch" -eq 0 || { error 'IPv6运行值与永久策略不一致。'; return 1; }
    info 'IPv6运行态与期望策略一致。'
}

# Historical status entries remain reachable from nested WARP/network menus;
# route all of them to the final E182 owner so they cannot report "preserve"
# after E182 has deliberately taken the permanent policy.
_e138_ipv6_status() { _e182_ipv6_status "$@"; }
_e136_ipv6_status() { _e182_ipv6_status "$@"; }
_e159_ipv6_status() { _e182_ipv6_status "$@"; }

_e182_ipv6_menu() {
    local n confirm
    while true; do
        clear
        title 'IPv6永久策略（默认关闭）'
        echo '  1) 永久关闭IPv6（当前IPv6 SSH会话将被拒绝）'
        echo '  2) 永久开启IPv6'
        echo '  3) 查看运行态、持久文件、开机服务与重复定义'
        echo '  0) 返回'
        read -rp '操作: ' n || true
        case "$n" in
            1)
                read -rp '输入 DISABLE-IPV6 确认: ' confirm || true
                test "$confirm" = DISABLE-IPV6 \
                    && _e182_ipv6_apply 1 menu 0 || warn '未执行IPv6关闭。'
                _e116_pause
                ;;
            2) _e182_ipv6_apply 0 menu 0 || true; _e116_pause ;;
            3) _e182_ipv6_status || true; _e116_pause ;;
            0) return 0 ;;
            *) warn '无效操作。'; sleep 1 ;;
        esac
    done
}

_e182_ipv6_uninstall_restore() {
    local initial
    test -e "$E182_IPV6_CONF" || test -e "$E182_IPV6_STATE" \
      || test -e "$E182_IPV6_APPLY" || test -e "$E182_IPV6_SERVICE" \
      || test -e "$E182_IPV6_PENDING" || test -e "$E182_IPV6_HOT_MARKER" \
      || return 0
    _e182_ipv6_hot_recover_stale || return 1
    initial=$(_e182_ipv6_state_get initial_transaction '')
    if _e182_ipv6_tx_valid "$initial"; then
        _e182_ipv6_tx_restore "$initial" || return 1
        info '已恢复E182首次接管IPv6前的持久配置、服务状态与运行值。'
        return 0
    fi
    warn 'IPv6首次接管快照不存在；仅移除E182持久层，当前运行值保持不变。'
    systemctl disable --now "$E182_IPV6_UNIT" >/dev/null 2>&1 || true
    rm -f -- "$E182_IPV6_CONF" "$E182_IPV6_APPLY" "$E182_IPV6_SERVICE" \
        "$E182_IPV6_PENDING" "$E182_IPV6_HOT_MARKER" || return 1
    systemctl daemon-reload >/dev/null 2>&1 || return 1
}

if declare -F _e182_prune_system_tx >/dev/null 2>&1; then
    eval "$(declare -f _e182_prune_system_tx | sed '1s/_e182_prune_system_tx/_e182_prune_system_tx_base/')"
fi
