for pair in \
    _e172_tc_menu:_e182_tc_menu \
    _e172_show_optimization_status:_e182_show_optimization_status \
    _e172_network_params_menu:_e182_network_params_menu \
    _e172_bbr_kernel_menu:_e182_bbr_kernel_menu \
    _e172_security_center:_e182_security_center \
    _e172_check_reexport:_e182_check_reexport \
    _e172_traffic_monitor:_e182_traffic_monitor; do
    old=${pair%%:*}; new=${pair#*:}
