_e159_hot_step() {
    local phase="$1"; shift
    _e159_phase_log "$E182_HOT_LOG" "$phase" begin
    if "$@"; then _e159_phase_log "$E182_HOT_LOG" "$phase" ok; return 0; fi
    _e159_phase_log "$E182_HOT_LOG" "$phase" fail
    error "E182热更新失败阶段：$phase"
    return 1
}

_e182_hot_update_preflight() {
    local c
    _e172_hot_update_preflight_base || return 1
    _e182_prepare || return 1
    _e182_ipv6_recover_stale_serialized || {
        error 'E182预检无法恢复上次中断的IPv6事务；拒绝建立新快照。'
        return 1
    }
    for c in systemctl sshd ss ip; do
        command -v "$c" >/dev/null 2>&1 || {
            error "E182不中断预检缺少命令：$c"
            return 1
        }
    done
    sshd -t >/dev/null 2>&1 || {
        error 'E182预检发现sshd配置无效；尚未修改防火墙或网络参数。'
        return 1
    }
    _e172_ssh_listener_precheck
}
