        -e '1s/_e172_hot_update/_e182_hot_update/' \
        -e 's/_e172_/_e182_/g' -e 's/E172/E182/g' -e 's/e172/e182/g' \
        -e 's/test "$rc" -ne 0 || _e159_hot_step firewall-capability/test "$rc" -ne 0 || _e159_hot_step ipv6-policy _e182_ipv6_hot_apply_default || rc=1; test "$rc" -ne 0 || _e159_hot_step firewall-capability/' \
        -e 's/test "$rc" -ne 0 || _e159_verify_neighbor_queue_semantics || rc=1;/test "$rc" -ne 0 || _e159_verify_neighbor_queue_semantics || rc=1; test "$rc" -ne 0 || _e182_ipv6_hot_verify || rc=1;/' \
        -e 's/test -z "$sysbackup" || _e140_system_restore "$sysbackup" || rollback_rc=1;/_e182_ipv6_hot_rollback_if_marked || rollback_rc=1; test -z "$sysbackup" || _e140_system_restore "$sysbackup" || rollback_rc=1; test -z "$sysbackup" || _e182_sshd_reload_safe || rollback_rc=1;/' \
        -e 's/rm -f "$E182_CRITICAL_MARKER"/_e182_ipv6_hot_commit; rm -f "$E182_CRITICAL_MARKER"/' \
        -e 's/E165 Fail2ban官方nft action真实封禁闭环/SSH能力状态（防火墙封禁、OpenSSH原生限流或只读审计）/g')"
fi
