_e152_firewall_backend_status() {
    local backend native_mode
    if test "$EUID" -ne 0; then
        echo 'firewall_backend=unknown-unprivileged'
        echo 'privilege=root-required-to-read-active-ruleset'
        return 0
    fi
    backend=$(_e152_firewall_backend 2>/dev/null || echo none)
    echo "firewall_backend=$backend"
    echo "e182_state=$E182_BACKEND_STATE"
    echo "e182_native_state=$E182_NATIVE_STATE"
    echo "e182_diagnostic=$E182_BACKEND_DIAG"
    echo "ip_ban_capable=$(_e182_backend_state_get ip_ban_capable unknown)"
    echo "managed_fail2ban_jail_runtime=$(_e182_managed_f2b_runtime_state)"
    case "$backend" in
        nft) echo 'ssh_guard_model=fail2ban-owned-native-nft-base-chain' ;;
        iptables) echo 'ssh_guard_model=managed-xtables-chain' ;;
        ufw|firewalld) echo 'ssh_guard_model=active-firewall-manager' ;;
        sshd-native)
            native_mode=$(sed -n 's/^mode=//p' "$E182_NATIVE_STATE" 2>/dev/null | tail -n1)
            echo "ssh_guard_model=openssh-${native_mode:-not-applied}-no-firewall-ban"
            ;;
        *) echo 'ssh_guard_model=unclassified' ;;
    esac
}

_e182_structure_audit() {
    local rc=0 size lines dispatchers menu advanced hot preflight ensure native guard ipv6 uninstall install_mode install_base
    echo 'V199e182 structure audit:'
    size=$(wc -c <"$SCRIPT_PATH" | tr -d ' ')
    lines=$(wc -l <"$SCRIPT_PATH" | tr -d ' ')
    dispatchers=$(grep -c '^# V199e182 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true)
    menu=$(declare -f _e182_main_menu_impl 2>/dev/null || true)
    advanced=$(declare -f _e182_advanced_menu 2>/dev/null || true)
    hot=$(declare -f _e182_hot_update 2>/dev/null || true)
    preflight=$(declare -f _e182_hot_update_preflight 2>/dev/null || true)
    ensure=$(declare -f _e182_ensure_firewall_backend 2>/dev/null || true)
    native=$(declare -f _e182_install_native_guard 2>/dev/null || true)
    guard=$(declare -f _e141_install_ssh_guard 2>/dev/null || true)
    ipv6=$(declare -f _e182_ipv6_apply 2>/dev/null || true)
    uninstall=$(declare -f do_uninstall 2>/dev/null || true)
    install_mode=$(declare -f _e182_install_mode 2>/dev/null || true)
    install_base=$(declare -f _e182_install_mode_base 2>/dev/null || true)
    echo "  file_bytes=$size"
    echo "  lines=$lines"
    echo "  final_dispatchers=$dispatchers"
    echo '  menu_owner=e182 (E127 contract + WARP 22-24 + IPv6 25)'
    echo '  network_owner=e159 data model / E170 ordered ipfrag transaction'
    echo '  ssh_owner=e182 nft -> xtables variants -> OpenSSH native matrix'
    test "$size" -gt 2000000 && test "$lines" -gt 45000 || rc=1
    test "$dispatchers" -eq 1 || rc=1
    grep -q 'V199e182 - 事务稳态版' <<<"$menu" || rc=1
    grep -q '22) WARP定向分流' <<<"$menu" || rc=1
    grep -q '23) WARP全局分流' <<<"$menu" || rc=1
    grep -q '24) Cloudflare系统全隧道' <<<"$menu" || rc=1
    grep -q '25) IPv6永久开关' <<<"$menu" || rc=1
    grep -q '_e182_run_micro_control_menu' <<<"$advanced" || rc=1
    grep -q '_e182_ensure_firewall_backend' <<<"$hot" || rc=1
    grep -q '_e182_ssh_guard_verify_final' <<<"$hot" || rc=1
    grep -q 'iptables-legacy' <<<"$ensure" || rc=1
    grep -q 'sshd-native' <<<"$ensure" || rc=1
    grep -q '_e182_write_native_settings' <<<"$native" || rc=1
    grep -q '_e182_native_verify' <<<"$native" || rc=1
    grep -q '_e182_ipv6_hot_apply_default' <<<"$hot" || rc=1
    grep -q '_e182_ipv6_hot_rollback_if_marked' <<<"$hot" || rc=1
    grep -q '_e182_ipv6_recover_stale_serialized' <<<"$preflight" || rc=1
    grep -q '_e182_ipv6_tx_snapshot' <<<"$ipv6" || rc=1
    grep -q '_e182_ipv6_uninstall_restore' <<<"$uninstall" || rc=1
    grep -q '_e182_ipv6_apply_default' <<<"$install_mode" || rc=1
    grep -q '_e138_warp_config_integrity' <<<"$install_base" || rc=1
    grep -q '_e140_system_snapshot' <<<"$guard" || rc=1
    ! grep -Eq 'systemctl (stop|restart).*\b(xray|ssh|sshd)\b' <<<"$native" || rc=1
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL'
    return "$rc"
}

_e182_self_test() {
    local rc=0 d count unique low_line high_line body menu hot preflight file mode
    echo 'V199e182 fast release gate:'
    bash -n "$SCRIPT_PATH" && echo '  [PASS] bash syntax' || { echo '  [FAIL] bash syntax'; rc=1; }
    test "$SCRIPT_VERSION" = 199e182 && test "$E182_VERSION" = 199e182 \
        && echo '  [PASS] release identity' || { echo '  [FAIL] release identity'; rc=1; }
    d=$(mktemp -d /tmp/e182-selftest.XXXXXX) || return 1
    _e159_full_spec fq 1 31 "$d/spec.conf" || rc=1
    count=$(grep -Ec '^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=' "$d/spec.conf" || true)
    unique=$(awk -F= '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{k=$1;gsub(/[[:space:]]/,"",k);print k}' \
        "$d/spec.conf" | sort -u | wc -l | tr -d ' ')
    test "$count" = 127 && test "$unique" = 127 && _e159_spec_validate "$d/spec.conf" \
        && echo '  [PASS] exact 127-request / 125-control model' \
        || { echo '  [FAIL] network request model'; rc=1; }
    if _e182_show_network_spec >"$d/spec-display.out" \
      && test "$(grep -Ec '^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=' "$d/spec-display.out" || true)" = 127; then
        echo '  [PASS] read-only menu-4 specification works without persistent runtime initialization'
    else
        echo '  [FAIL] read-only network specification display'; rc=1
    fi
    cp -f "$d/spec.conf" "$d/order.conf"
    _e170_reorder_ipfrag_file "$d/order.conf" || rc=1
    low_line=$(grep -n '^net.ipv4.ipfrag_low_thresh' "$d/order.conf" | cut -d: -f1)
    high_line=$(grep -n '^net.ipv4.ipfrag_high_thresh' "$d/order.conf" | cut -d: -f1)
    test -n "$low_line" && test -n "$high_line" && (( high_line < low_line )) \
        && echo '  [PASS] ipfrag high-before-low ordering retained' \
        || { echo '  [FAIL] ipfrag ordering'; rc=1; }
    if (clear(){ :; }; title(){ :; }; hr(){ :; }; printf '0\n' | _e182_micro_control_menu) \
        >"$d/micro.out" 2>"$d/micro.err" \
      && grep -q '  1) TCP NoDelay' "$d/micro.out" \
      && grep -q ' 28) 应用层' "$d/micro.out" \
