    else echo '  [FAIL] 28-item menu behavior'; rc=1; fi
    test "$(_e137_mode_internal 1)" = 1 && test "$(_e137_mode_internal 2)" = 4 \
      && test "$(_e137_mode_internal 3)" = 2 && test "$(_e137_mode_internal 4)" = 3 \
      && echo '  [PASS] four node menu semantics' || { echo '  [FAIL] node mapping'; rc=1; }
    if command -v jq >/dev/null 2>&1 && (
        BEST_SNI=www.example.com; SNI_JSON_ARRAY='["www.example.com"]'; REMARK_NAME=e182-selftest
        E79_VLESSENC_NETWORK=raw
        _e118_generate_reality_material(){
