        }
        mktemp(){ printf '%s\n' "$d/native-settings"; }
        _e182_write_native_settings(){ test -s "$1" && printf '%s\n' dropin; }
        _e182_sshd_reload_safe(){ :; }
        systemctl(){ :; }
        _e182_disable_managed_f2b_jail_native(){ :; }
        _e152_install_ssh_auth_audit(){ :; }
        _e172_retire_legacy_ssh_audits(){ :; }
        expected_tx="$d/outer-tx"
        _e182_native_state_write(){
            test "$1" = native-throttle && test "$2" = 3 && test "$3" = 30 \
                && test "$4" = 10:30:60 && test "$5" = 3 \
                && test "$6" = dropin && test "$7" = "$expected_tx"
        }
        _e182_auth_state_write_native(){ :; }
        _e182_native_verify(){ :; }
        _e182_new_tx(){ printf '%s\n' "$d/generated-tx"; }
        _e140_system_snapshot(){ test "$1" = "$d/generated-tx"; }
        info(){ :; }; warn(){ :; }
        _e182_install_native_guard "$d/outer-tx" \
            && expected_tx="$d/generated-tx" \
            && _e182_install_native_guard
    ); then
        echo '  [PASS] native guard with/without outer transaction executes under set -u'
    else
        echo '  [FAIL] native guard nounset execution'; rc=1
    fi
    if (
        set -u
        _e141_sshd_auth_profile(){ printf '%s\n' 'mode=password-capable'; }
        _e172_quiesce_ssh_managers(){ :; }
        sshd(){ test "${1:-}" != -T || printf '%s\n' \
            'maxauthtries 6' 'logingracetime 120' 'maxstartups 10:30:100'; }
        mktemp(){ printf '%s\n' "$d/native-settings-fail"; }
        _e182_write_native_settings(){ return 1; }
        restored=0; reloaded=0; audited=0
        _e140_system_restore(){ test "$1" = "$d/fallback-tx" && restored=1; }
        _e182_sshd_reload_safe(){ reloaded=1; }
        _e182_install_audit_only(){ test "$1" = "$d/fallback-tx" && audited=1; }
        error(){ :; }; info(){ :; }; warn(){ :; }
        _e182_install_native_guard "$d/fallback-tx" \
            && test "$restored:$reloaded:$audited" = 1:1:1
    ); then
        echo '  [PASS] native throttle failure restores snapshot then enters verified audit-only floor'
    else
        echo '  [FAIL] native-to-audit rollback path'; rc=1
    fi
    if (
        set -u
        E135_NEW_PACKAGES=()
        E182_BACKEND_PREFLIGHT_VERIFIED=1
        ensure_calls=0
        state_parent_prepared=0
        _e182_new_tx(){ printf '%s\n' "$d/ssh-dispatch"; }
        _e140_system_snapshot(){ :; }
        install(){ test "${!#}" = "$E141_DIR" && state_parent_prepared=1; }
        _e182_ensure_firewall_backend(){ ensure_calls=$((ensure_calls + 1)); }
        _e152_firewall_backend(){ printf '%s\n' sshd-native; }
        _e182_install_native_guard(){ test "$1" = "$d/ssh-dispatch"; }
        _e140_system_restore(){ :; }
        _e182_sshd_reload_safe(){ :; }
        _e172_remove_packages_since(){ :; }
        _e141_install_ssh_guard \
            && test "$ensure_calls" = 0 \
            && test "$state_parent_prepared" = 1 \
            && test "$E182_BACKEND_PREFLIGHT_VERIFIED" = 0
    ); then
        echo '  [PASS] hot update reuses capability probe exactly once; menu state cannot stay stale'
    else
        echo '  [FAIL] one-shot firewall capability handoff'; rc=1
    fi
    body=$(declare -f _e182_install_native_guard)
    grep -q '_e182_sshd_reload_safe' <<<"$body" \
      && grep -q '_e182_install_audit_only' <<<"$body" \
      && ! grep -Eq 'systemctl (stop|restart).*(xray|ssh|sshd)' <<<"$body" \
      && echo '  [PASS] native fallback never stops sshd/Xray and has audit-only floor' \
      || { echo '  [FAIL] native fallback contract'; rc=1; }
    body=$(declare -f _e182_ssh_guard_verify_final)
    grep -q '_e172_ssh_guard_verify_base' <<<"$body" \
      && grep -q '_e182_backend_state_verify' <<<"$body" \
      && ! grep -q '_e182_ssh_guard_firewall_verify_base' <<<"$body" \
      && echo '  [PASS] firewall final gate reads E182 capability state' \
      || { echo '  [FAIL] cross-version firewall final gate'; rc=1; }
    _e182_optimization_menu_audit >/dev/null \
      && echo '  [PASS] all menu-10 handlers and 1-28 entries are bound' \
      || { echo '  [FAIL] menu-10 audit'; rc=1; }
    menu=$(declare -f _e182_main_menu_impl)
    grep -q 'V199e182 - 事务稳态版' <<<"$menu" \
      && grep -q '21) 跨境代理网络参数集合' <<<"$menu" \
      && grep -q '22) WARP定向分流' <<<"$menu" \
      && grep -q '23) WARP全局分流' <<<"$menu" \
      && grep -q '24) Cloudflare系统全隧道' <<<"$menu" \
      && grep -q '25) IPv6永久开关' <<<"$menu" \
      && grep -q '_e138_warp_selective_menu' <<<"$menu" \
      && grep -q '_e138_warp_global_menu' <<<"$menu" \
      && grep -q '_e140_warp_full_menu' <<<"$menu" \
      && grep -q '_e182_ipv6_menu' <<<"$menu" \
      && echo '  [PASS] homepage exposes WARP 22-24 and persistent IPv6 option 25' \
      || { echo '  [FAIL] homepage contract'; rc=1; }
    hot=$(declare -f _e182_hot_update)
    preflight=$(declare -f _e182_hot_update_preflight)
    grep -q '_e182_ensure_firewall_backend' <<<"$hot" \
      && grep -q '_e182_ssh_guard_verify_final' <<<"$hot" \
      && grep -q '_e182_sshd_reload_safe' <<<"$hot" \
      && grep -q 'ssh-guard-e182' <<<"$hot" \
      && grep -q '_e182_ipv6_hot_apply_default' <<<"$hot" \
      && grep -q '_e182_ipv6_hot_verify' <<<"$hot" \
      && grep -q '_e182_ipv6_hot_rollback_if_marked' <<<"$hot" \
      && grep -q '_e182_ipv6_hot_commit' <<<"$hot" \
      && grep -q '_e182_ipv6_recover_stale_serialized' <<<"$preflight" \
      && echo '  [PASS] E182 hot-update binds SSH matrix and IPv6 apply/verify/rollback/commit' \
      || { echo '  [FAIL] hot-update binding'; rc=1; }
    rm -rf -- "$d"
    _e182_structure_audit >/dev/null || rc=1
    test "$rc" -eq 0 && echo 'V199e182 result: PASS' || echo 'V199e182 result: FAIL'
    return "$rc"
}

