_e185_hot_step() {
    local phase="$1"; shift
    _e159_phase_log "$E185_HOT_LOG" "$phase" begin
    if "$@"; then _e159_phase_log "$E185_HOT_LOG" "$phase" ok; return 0; fi
    _e159_phase_log "$E185_HOT_LOG" "$phase" fail
    error "E185热更新失败阶段：$phase"
    return 1
}

_e185_hot_update_preflight() {
    _e183_hot_update_preflight || return 1
    _e185_prepare || return 1
