do_uninstall() {
    local rc=0
    _e185_uninstall_base "$@" || rc=$?
    if test "$rc" -eq 0; then
        rm -f -- "$E185_SELF_PATH" "$E185_LATEST_PATH" "$E185_WGCF_BIN" 2>/dev/null || true
        rm -rf -- "$E185_DIR" "$E185_TX_ROOT" "$(dirname "$E185_HOT_LOG")" 2>/dev/null || true
