}

_e185_structure_audit() {
    local rc=0 size lines dispatchers menu build enable
    echo 'V199e185 structure audit:'
    size=$(wc -c <"$SCRIPT_PATH" | tr -d ' ')
    lines=$(wc -l <"$SCRIPT_PATH" | tr -d ' ')
    dispatchers=$(grep -c '^# V199e185 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true)
    menu=$(declare -f _e185_main_menu_impl 2>/dev/null || true)
    build=$(declare -f _e138_warp_config_build 2>/dev/null || true)
    enable=$(declare -f _e185_warp_enable 2>/dev/null || true)
    echo "  file_bytes=$size"
    echo "  lines=$lines"
    echo "  final_dispatchers=$dispatchers"
    echo '  warp_backend_owner=e185 (MASQUE + Xray-native WireGuard fallback)'
    echo '  host_route_policy=noKernelTun=true for Xray WireGuard'
    echo '  qr_owner=e183 retained'
    test "$size" -gt 2000000 && test "$lines" -gt 45000 || rc=1
    test "$dispatchers" -eq 1 || rc=1
    grep -q 'V199e185 - 事务稳态版' <<<"$menu" || rc=1
    grep -q 'protocol:"wireguard"' <<<"$(declare -f _e185_wg_outbound_json)" || rc=1
    grep -q 'noKernelTun' <<<"$(declare -f _e185_wg_outbound_json)" || rc=1
    grep -q '_e185_confirm_wgcf_fallback' <<<"$enable" || rc=1
    grep -q 'masque-ingress-udp-timeout' <<<"$(declare -f _e185_masque_failure_reason)" || rc=1
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL'
    return "$rc"
}

_e185_self_test() {
    local rc=0 d profile out family strategy
    d=$(mktemp -d /tmp/xray-e185-selftest.XXXXXX) || return 1
    profile="$d/wgcf-profile.conf"
    cat >"$profile" <<'EOF_E185_PROFILE'
[Interface]
PrivateKey = AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=
Address = 172.16.0.2/32
Address = 2606:4700:110:1234::2/128
MTU = 1280
[Peer]
PublicKey = bmXOC+F1FxEMF9dyiK2H5/1SUtzH0JuVo51h2wPfgyo=
Endpoint = engage.cloudflareclient.com:2408
AllowedIPs = 0.0.0.0/0, ::/0
Reserved = 1, 2, 3
EOF_E185_PROFILE
    echo 'V199e185 fast release gate:'
    test "$SCRIPT_VERSION" = 199e185 && test "$E185_VERSION" = 199e185 \
      && echo '  [PASS] release identity' || { echo '  [FAIL] release identity'; rc=1; }
    for family in ipv4 ipv6 dual; do
        out="$d/$family.json"
        _e185_wg_outbound_json "$profile" 162.159.193.10:2408 "$family" warp-test-e185 "$out" || rc=1
        strategy=$(_e185_wg_strategy "$family")
        jq -e --arg s "$strategy" '
          .protocol=="wireguard" and .settings.noKernelTun==true and
          .settings.domainStrategy==$s and .settings.peers[0].endpoint=="162.159.193.10:2408" and
          .settings.reserved==[1,2,3]
        ' "$out" >/dev/null 2>&1 || rc=1
    done
    test "$rc" -ne 0 || echo '  [PASS] IPv4/IPv6/dual native WireGuard generation'
    grep -q 'AllChecksTimedOut' <<<"$(declare -f _e185_masque_failure_reason)" \
      && echo '  [PASS] MASQUE failure classifier' || { echo '  [FAIL] classifier'; rc=1; }
    grep -q 'wgcf为非Cloudflare官方' <<<"$(declare -f _e185_confirm_wgcf_fallback)" \
      && echo '  [PASS] explicit unofficial-fallback consent' || { echo '  [FAIL] consent'; rc=1; }
    grep -q 'queryStrategy' <<<"$(declare -f _e138_warp_config_build)" \
      && { echo '  [FAIL] global DNS queryStrategy mutation remains'; rc=1; } \
      || echo '  [PASS] no global DNS queryStrategy mutation'
    _e185_structure_audit >/dev/null || rc=1
    rm -rf -- "$d"
    test "$rc" -eq 0 && echo 'V199e185 result: PASS' || echo 'V199e185 result: FAIL'
    return "$rc"
}

