#==============================================================================
# V199e186 FINAL RELIABILITY LAYER
# - Verifies Cloudflare Local proxy with both a strict loopback listener check
#   and a real SOCKS5 Cloudflare trace instead of a four-second port snapshot.
# - Keeps IPv4-only, IPv6-only and dual-stack Xray target policies independent.
# - Makes node QR output visible in install/export flows and writes verified,
#   atomic PNG/SVG artifacts with per-node diagnostics.
# - Owns self-install, hot-update identity, final menus and the dispatcher.
#==============================================================================
readonly E186_VERSION="199e186"
readonly E186_DIR="$CONFIG_DIR/e186"
readonly E186_SELF_PATH="$SCRIPT_DIR/ex199e186.sh"
readonly E186_LATEST_PATH="$SCRIPT_DIR/ex199e_latest.sh"
readonly E186_TX_ROOT="/var/backups/xray-e186"
readonly E186_HOT_LOG="/var/log/xray/e186/hot-update-last.log"
readonly E186_CRITICAL_MARKER="$E186_DIR/CRITICAL_RECOVERY_REQUIRED.env"
readonly E186_WARP_DIAG="/var/log/xray/e186/warp-local-last.log"
readonly E186_QR_DIAG_DIR="/var/log/xray/e186/qr"
readonly E186_WARP_WAIT_SECONDS="90"
E186_FORCE_TERMINAL_QR=0

_e186_prepare() {
    _e185_prepare || return 1
    install -d -m 0700 "$E186_DIR" "$E186_TX_ROOT" \
        "$(dirname "$E186_HOT_LOG")" "$E186_QR_DIAG_DIR" || return 1
}

_e186_new_tx() {
    local name="${1:-transaction}" dir
    _e186_prepare || return 1
    dir="$E186_TX_ROOT/${name}-$(date +%Y%m%d_%H%M%S)-$$-$RANDOM"
    install -d -m 0700 "$dir" || return 1
    printf '%s\n' "$dir"
}

_e186_install_self() {
    local tx target snap tmp failed=0
    local -a targets=("$SYMLINK" "$E186_SELF_PATH" "$E186_LATEST_PATH")
    test -r "$SCRIPT_PATH" || return 1
    _e186_prepare || return 1
    tx=$(_e186_new_tx self-install) || return 1
    for target in "${targets[@]}"; do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
        _e135_snapshot_file "$target" "$snap" || return 1
    done
    for target in "${targets[@]}"; do
        install -d -m 0755 "$(dirname -- "$target")" || { failed=1; break; }
        tmp="$target.e186-new.$$"
        install -m 0755 "$SCRIPT_PATH" "$tmp" || {
            rm -f -- "$tmp"
            failed=1
            break
        }
        mv -f -- "$tmp" "$target" || {
            rm -f -- "$tmp"
            failed=1
            break
        }
        cmp -s "$SCRIPT_PATH" "$target" || { failed=1; break; }
    done
    if test "$failed" -ne 0; then
        for target in "${targets[@]}"; do
            snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
            _e135_restore_file "$target" "$snap" || true
        done
        return 1
    fi
    hash -r 2>/dev/null || true
}

_e186_write_version() {
    local tmp
    _e186_prepare || return 1
    tmp=$(_e118_mktemp e186-version) || return 1
    printf '%s\n' "$E186_VERSION" >"$tmp" || return 1
    _e118_atomic_install "$tmp" "$SCRIPT_VERSION_FILE" 0600
}

# All inherited install and version aliases resolve to the E186 artifact.
_e118_install_self() { _e186_install_self "$@"; }
_e138_install_self() { _e186_install_self "$@"; }
_e152_install_self() { _e186_install_self "$@"; }
