_e183_install_self() { _e186_install_self "$@"; }
_e185_install_self() { _e186_install_self "$@"; }
_e159_write_version() { _e186_write_version "$@"; }
_e152_write_version() { _e186_write_version "$@"; }
_e142_write_version() { _e186_write_version "$@"; }
_e182_write_version() { _e186_write_version "$@"; }
_e183_write_version() { _e186_write_version "$@"; }
_e185_write_version() { _e186_write_version "$@"; }

#------------------------------------------------------------------------------
# QR export: force terminal output for node workflows and commit only verified
# artifacts. A failed regeneration removes stale images so an old credential QR
# cannot be mistaken for the current node.
#------------------------------------------------------------------------------
_e186_png_valid() {
    local file="$1" sig
    test -s "$file" || return 1
    sig=$(od -An -tx1 -N8 "$file" 2>/dev/null | tr -d ' \n')
    test "$sig" = 89504e470d0a1a0a
}

_e186_svg_valid() {
    local file="$1"
    test -s "$file" && LC_ALL=C grep -q '<svg' "$file"
}

_e186_qr_terminal_wanted() {
    test "${E186_FORCE_TERMINAL_QR:-0}" = 1 || test "${E186_QR_TERMINAL:-auto}" = always || test -t 1
}

_e186_qr_level() {
    local bytes
    bytes=$(LC_ALL=C printf '%s' "${1:-}" | wc -c | tr -d ' ')
    if test "$bytes" -le 1200; then echo H
    elif test "$bytes" -le 1600; then echo Q
    elif test "$bytes" -le 2300; then echo M
    else echo L
    fi
}

_e186_qr_terminal() {
    local uri="$1" diag="$2" level
    level=$(_e186_qr_level "$uri")
    qrencode -l "$level" -m 2 -t UTF8 "$uri" 2>>"$diag" \
      || qrencode -l "$level" -m 2 -t ANSIUTF8 "$uri" 2>>"$diag" \
      || qrencode -l "$level" -m 2 -t UTF8i "$uri" 2>>"$diag" \
      || qrencode -l "$level" -m 2 -t ASCIIi "$uri" 2>>"$diag"
}

_e186_qr_generate_files() {
    local uri="$1" png="$2" svg="$3" diag="$4"
    local tmp_png tmp_svg generated=0 level
    level=$(_e186_qr_level "$uri")
    tmp_png=$(mktemp "$(dirname -- "$png")/.e186-qr-png.XXXXXX") || return 1
    if qrencode -l "$level" -m 4 -s 8 -t PNG -o "$tmp_png" "$uri" 2>>"$diag" \
      && _e186_png_valid "$tmp_png"; then
        chmod 0600 "$tmp_png" || { rm -f -- "$tmp_png"; return 1; }
        mv -f -- "$tmp_png" "$png" || { rm -f -- "$tmp_png"; return 1; }
        generated=1
    else
        rm -f -- "$tmp_png" "$png" 2>/dev/null || true
    fi
    tmp_svg=$(mktemp "$(dirname -- "$svg")/.e186-qr-svg.XXXXXX") || {
        test "$generated" -eq 1
        return
    }
    if qrencode -l "$level" -m 4 -t SVG -o "$tmp_svg" "$uri" 2>>"$diag" \
      && _e186_svg_valid "$tmp_svg"; then
        chmod 0600 "$tmp_svg" || { rm -f -- "$tmp_svg"; return 1; }
        mv -f -- "$tmp_svg" "$svg" || { rm -f -- "$tmp_svg"; return 1; }
        generated=1
    else
        rm -f -- "$tmp_svg" "$svg" 2>/dev/null || true
    fi
    test "$generated" -eq 1
}

_e135_emit_qr() {
    local uri="${1:-}" label="${2:-node}" safe txt png svg diag tmp_txt bytes
    local terminal_ok=0 files_ok=0
    test -n "$uri" || { error '二维码输入URI为空。'; return 1; }
    safe=$(_e135_safe_name "$label")
    test -n "$safe" || safe=node
    _e135_prepare || return 1
    _e186_prepare || return 1
    txt="$E135_EXPORT_DIR/${safe}.txt"
    png="$E135_EXPORT_DIR/${safe}.png"
    svg="$E135_EXPORT_DIR/${safe}.svg"
    diag="$E186_QR_DIAG_DIR/${safe}.log"
    tmp_txt=$(_e118_mktemp export-uri-e186.txt) || return 1
    printf '%s\n' "$uri" >"$tmp_txt" || return 1
    _e118_atomic_install "$tmp_txt" "$txt" 0600 || return 1
    bytes=$(LC_ALL=C printf '%s' "$uri" | wc -c | tr -d ' ')
    {
        echo "time=$(date -Is 2>/dev/null || date)"
        echo "label=$safe"
        echo "uri_bytes=${bytes:-0}"
        echo "error_correction=$(_e186_qr_level "$uri")"
        echo "terminal_forced=${E186_FORCE_TERMINAL_QR:-0}"
        echo "txt=$txt"
        echo "png=$png"
        echo "svg=$svg"
        command -v qrencode 2>&1 || true
        qrencode --version 2>&1 || true
    } >"$diag" 2>&1 || true
    chmod 0600 "$diag" 2>/dev/null || true
    if ! _e183_ensure_qrencode; then
        rm -f -- "$png" "$svg" 2>/dev/null || true
        warn "qrencode不可用；完整链接已保存：$txt"
        return 0
    fi
    if ! [[ "${bytes:-}" =~ ^[0-9]+$ ]] || test "$bytes" -gt 2950; then
        rm -f -- "$png" "$svg" 2>/dev/null || true
        warn "URI长度为${bytes:-unknown}字节，超过QR-L二进制容量；仅保留URI文本：$txt"
        return 0
    fi
    if _e186_qr_terminal_wanted; then
        echo
        if _e186_qr_terminal "$uri" "$diag"; then
            terminal_ok=1
            info "终端二维码已生成：$label"
        else
            warn "终端二维码生成失败，继续生成文件；诊断：$diag"
        fi
    fi
    if _e186_qr_generate_files "$uri" "$png" "$svg" "$diag"; then
        files_ok=1
        test -s "$png" && info "二维码PNG：$png"
        test -s "$svg" && info "二维码SVG：$svg"
    fi
    if test "$terminal_ok" -eq 0 && test "$files_ok" -eq 0; then
        warn "二维码生成失败；当前URI文本仍可用：$txt；诊断：$diag"
    fi
    return 0
}

if declare -F do_summary >/dev/null 2>&1; then
