        '1s/_e138_warp_migrate_state/_e186_warp_migrate_state_base/')"
fi

_e186_warp_config_mode() {
    local config="${1:-$CONFIG}"
    test -s "$config" || { echo disabled; return 0; }
    jq -r '
      def has_tag($tags):
        any(.outbounds[]?; (.tag // "") as $t | ($tags | index($t)) != null);
      if has_tag(["warp-global-e138","warp-global-e185","warp-global-socks-e183","warp-global-socks-e185"]) then "global"
      elif has_tag(["warp-selective-e138","warp-selective-e185","warp-selective-socks-e183","warp-selective-socks-e185","warp-selective"]) then "selective"
      else "disabled" end
    ' "$config" 2>/dev/null || echo disabled
}

_e186_warp_config_backend() {
    local config="${1:-$CONFIG}"
    test -s "$config" || { echo disabled; return 0; }
    jq -r '
      def tagged($tags; $protocol):
        any(.outbounds[]?; (.tag // "") as $t |
          (($tags | index($t)) != null and .protocol == $protocol));
      if tagged(["warp-global-e185","warp-selective-e185"]; "wireguard") then "xray-wg"
      elif tagged([
        "warp-global-e138","warp-selective-e138","warp-global-socks-e183",
        "warp-selective-socks-e183","warp-global-socks-e185",
        "warp-selective-socks-e185","warp-selective"
      ]; "socks") then "masque"
      else "disabled" end
    ' "$config" 2>/dev/null || echo disabled
}

_e138_warp_migrate_state() {
    local enabled mode profile family backend request config_mode config_backend
    _e186_warp_migrate_state_base >/dev/null 2>&1 || true
    enabled=$(_e138_state_get route_enabled 0)
    mode=$(_e138_state_get route_mode disabled)
    profile=$(_e138_state_get profile disabled)
    family=$(_e138_state_get family ipv4)
    backend=$(_e138_state_get backend disabled)
    request=$(_e138_state_get backend_request auto)
    config_mode=$(_e186_warp_config_mode)
    config_backend=$(_e186_warp_config_backend)
    if test "$config_mode" = global || test "$config_mode" = selective; then
        enabled=1
        mode="$config_mode"
        backend="$config_backend"
    fi
    if test "$enabled" != 1; then
        _e138_state_write 0 disabled disabled disabled disabled disabled
        return $?
    fi
    test "$mode" != host-full || return 0
    family=$(_e185_family_normalize "${family:-ipv4}" 2>/dev/null || echo ipv4)
    test "$family" != disabled || family=ipv4
    backend=$(_e185_backend_normalize "${backend:-$config_backend}" 2>/dev/null || echo "$config_backend")
    if test "$backend" != masque && test "$backend" != xray-wg; then
        backend="$config_backend"
    fi
    if test "$backend" != masque && test "$backend" != xray-wg; then
        backend=auto
    fi
    request=$(_e185_backend_normalize "${request:-auto}" 2>/dev/null || echo auto)
    test "$request" != disabled || request=auto
    if test "$mode" = global; then
        profile=global
    elif test -z "$profile" || test "$profile" = disabled || test "$profile" = global; then
        # E138 always installed this profile by default. The warning makes the
        # only ambiguous legacy case visible rather than silently widening it.
        profile=google-meta-core
        warn '旧定向WARP状态缺少profile字段；按E138默认google-meta-core迁移。'
    fi
    _e138_state_write 1 "$mode" "$profile" "$family" "$backend" "$request"
}

_e186_warp_listener_lines() {
    command -v ss >/dev/null 2>&1 || return 1
    ss -H -lntp 2>/dev/null |
      awk -v p="$E138_WARP_PORT" '$4 ~ (":" p "$") {print}'
}

_e186_listener_set_safe() {
    local lines="${1:-}" line addr count=0
    test -n "$lines" || return 1
    while IFS= read -r line; do
        test -n "$line" || continue
        addr=$(awk '{print $4}' <<<"$line")
        test "$addr" = "127.0.0.1:$E138_WARP_PORT" || return 1
        count=$((count+1))
    done <<<"$lines"
    test "$count" -gt 0
}

_e186_warp_listener_ok() {
    local lines
    lines=$(_e186_warp_listener_lines 2>/dev/null || true)
    _e186_listener_set_safe "$lines"
}

_e186_warp_listener_owner_ok() {
    local lines="${1:-}"
    grep -qiE 'warp-svc|cloudflare-warp|cloudflare_one' <<<"$lines"
}

_e186_warp_trace() {
    curl --proto '=https' --tlsv1.2 -fsS \
      --noproxy '' \
      --proxy "socks5h://127.0.0.1:$E138_WARP_PORT" \
      --connect-timeout 5 --max-time 9 \
      https://www.cloudflare.com/cdn-cgi/trace 2>/dev/null
}

_e186_warp_trace_ok() {
    local trace="${1:-}" warp loc
    warp=$(awk -F= '$1=="warp"{print tolower($2)}' <<<"$trace")
    loc=$(awk -F= '$1=="loc"{print toupper($2)}' <<<"$trace")
    [[ "$warp" =~ ^(on|plus)$ ]] && test "$loc" != CN
}

_e186_warp_proxy_ready() {
    local trace
    _e186_warp_listener_ok || return 1
    trace=$(_e186_warp_trace 2>/dev/null || true)
    _e186_warp_trace_ok "$trace"
}

_e136_warp_listener_ok() { _e186_warp_listener_ok; }
_e183_warp_listener_lines() { _e186_warp_listener_lines; }
_e183_warp_listener_ok() { _e186_warp_listener_ok; }
_e136_warp_trace() { _e186_warp_trace; }
_e136_warp_proxy_ready() { _e186_warp_proxy_ready; }
_e137_warp_proxy_ready() { _e186_warp_proxy_ready; }

_e186_warp_port_preflight() {
    local lines trace
    lines=$(_e186_warp_listener_lines 2>/dev/null || true)
    test -z "$lines" && return 0
    if ! _e186_listener_set_safe "$lines"; then
        error "TCP端口$E138_WARP_PORT存在非127.0.0.1监听，拒绝配置Local proxy。"
        sed 's/^/    /' <<<"$lines"
        return 1
    fi
    trace=$(_e186_warp_trace 2>/dev/null || true)
    if _e186_warp_trace_ok "$trace" || _e186_warp_listener_owner_ok "$lines"; then
        return 0
    fi
    error "TCP端口$E138_WARP_PORT虽为本机监听，但无法确认属于warp-svc；拒绝覆盖。"
    sed 's/^/    /' <<<"$lines"
    return 1
}
_e183_warp_port_preflight() { _e186_warp_port_preflight; }

_e186_route_guard_snapshot() {
    local ssh_ip=""
    declare -F _e135_current_ssh_ip >/dev/null 2>&1 \
      && ssh_ip=$(_e135_current_ssh_ip 2>/dev/null || true)
    {
        echo '[default4]'
        ip -4 route show default 2>/dev/null |
          sed -E 's/[[:space:]]+expires[[:space:]]+[0-9]+sec//g; s/[[:space:]]+/ /g' |
          LC_ALL=C sort
        echo '[rule4]'
        ip -4 rule show 2>/dev/null | sed -E 's/[[:space:]]+/ /g' | LC_ALL=C sort
        echo '[default6]'
        ip -6 route show default 2>/dev/null |
          sed -E 's/[[:space:]]+expires[[:space:]]+[0-9]+sec//g; s/[[:space:]]+/ /g' |
          LC_ALL=C sort
        echo '[rule6]'
        ip -6 rule show 2>/dev/null | sed -E 's/[[:space:]]+/ /g' | LC_ALL=C sort
        if _e136_is_ipv4 "$ssh_ip"; then
            echo '[ssh-route4]'
            ip -4 route get "$ssh_ip" 2>/dev/null | head -n1 |
              sed -E 's/[[:space:]]+expires[[:space:]]+[0-9]+sec//g; s/[[:space:]]+/ /g'
        elif test -n "$ssh_ip"; then
            echo '[ssh-route6]'
            ip -6 route get "$ssh_ip" 2>/dev/null | head -n1 |
              sed -E 's/[[:space:]]+expires[[:space:]]+[0-9]+sec//g; s/[[:space:]]+/ /g'
        fi
    }
}

_e186_warp_route_guard_ok() {
    local before="$1" after
    after=$(_e186_route_guard_snapshot)
    test "$before" = "$after"
}

_e186_capture_warp_diag() {
    local reason="${1:-unknown}" tmp old svc
    _e186_prepare >/dev/null 2>&1 || true
    old=$(_e118_mktemp e186-warp-old.log 2>/dev/null || true)
    test -z "$old" || cp -f -- "$E186_WARP_DIAG" "$old" 2>/dev/null || true
    tmp=$(_e118_mktemp e186-warp-diag.log 2>/dev/null || true)
    test -n "$tmp" || return 0
    svc=$(_e136_warp_service_name)
    {
        echo "time=$(date -Is 2>/dev/null || date)"
        echo "reason=$reason"
        echo "port=$E138_WARP_PORT"
        echo '--- warp-cli version ---'
        _e183_warp_cli_capture --version 2>&1 || true
        echo '--- warp-cli help ---'
        _e183_warp_cli_capture --help 2>&1 || true
        echo '--- warp-cli status ---'
        _e183_warp_cli_capture status 2>&1 || true
        echo '--- warp-cli settings ---'
        _e183_warp_cli_capture settings 2>&1 || true
        echo '--- registration ---'
        _e183_warp_cli_capture registration show 2>&1 || true
        echo '--- listeners on configured port ---'
        ss -H -lntp 2>&1 | awk -v p="$E138_WARP_PORT" '$4 ~ (":" p "$") {print}' || true
        echo '--- SOCKS5 Cloudflare trace ---'
        _e186_warp_trace 2>&1 || true
        echo '--- route guard ---'
        _e186_route_guard_snapshot 2>&1 || true
        echo '--- service ---'
        systemctl status "$svc" --no-pager 2>&1 || true
        echo '--- journal ---'
        journalctl -u "$svc" -n 220 --no-pager 2>&1 || true
        if test -n "$old" && test -s "$old"; then
            echo '--- convergence transcript ---'
            tail -n 260 "$old" 2>/dev/null || true
        fi
    } >"$tmp" 2>&1
    install -m 0600 "$tmp" "$E186_WARP_DIAG" 2>/dev/null || true
    test -z "$old" || rm -f -- "$old" 2>/dev/null || true
}

_e186_configure_local_proxy() {
    _e140_warp_set_protocol MASQUE || return 1
    # Client releases have used both mode-before-port and port-before-mode.
    _e183_warp_set_proxy_mode >/dev/null 2>&1 || true
    _e183_warp_set_proxy_port || return 1
    _e183_warp_set_proxy_mode || return 1
    _e183_warp_set_proxy_port >/dev/null 2>&1 || true
}

_e186_warp_connect_local_proxy() {
    local before svc old_log i lines trace warp loc reason=not-converged
    local failed=0
    _e186_prepare || return 1
    before=$(_e186_route_guard_snapshot)
    test -n "$before" || { error '无法建立宿主机路由与SSH回程安全基线。'; return 1; }
    _e186_warp_port_preflight || {
        _e186_capture_warp_diag port-conflict
        return 1
    }
    if _e186_warp_proxy_ready && _e186_warp_route_guard_ok "$before"; then
        info "WARP Local proxy已就绪：127.0.0.1:$E138_WARP_PORT。"
        return 0
    fi
    svc=$(_e136_warp_service_name)
    old_log="${E140_ACTIVE_LOG:-}"
    E140_ACTIVE_LOG="$E186_WARP_DIAG"
    : >"$E186_WARP_DIAG" 2>/dev/null || true
    if ! _e140_warp_service_wait; then
        reason=service-ipc
        failed=1
    elif ! _e140_warp_register; then
        reason=registration
        failed=1
    elif ! _e186_configure_local_proxy; then
        reason=proxy-configuration
        failed=1
    else
        _e183_warp_cli_capture connect >>"$E186_WARP_DIAG" 2>&1 || true
    fi
    if test "$failed" -eq 0; then
        for i in $(seq 1 "$E186_WARP_WAIT_SECONDS"); do
            if ! _e186_warp_route_guard_ok "$before"; then
                reason=host-route-drift
                failed=1
                break
            fi
            lines=$(_e186_warp_listener_lines 2>/dev/null || true)
            if test -n "$lines" && ! _e186_listener_set_safe "$lines"; then
                reason=unsafe-listener
                failed=1
                break
            fi
            if _e186_listener_set_safe "$lines"; then
                trace=$(_e186_warp_trace 2>/dev/null || true)
                warp=$(awk -F= '$1=="warp"{print tolower($2)}' <<<"$trace")
                loc=$(awk -F= '$1=="loc"{print toupper($2)}' <<<"$trace")
                if _e186_warp_trace_ok "$trace"; then
                    E140_ACTIVE_LOG="$old_log"
                    info "WARP Local proxy已通过监听、SOCKS5和出口三重验证：127.0.0.1:$E138_WARP_PORT，warp=$warp，loc=${loc:-unknown}。"
                    return 0
                fi
                if test "$loc" = CN; then
                    reason=warp-egress-cn
                    failed=1
                    break
                fi
            fi
            if (( i % 10 == 0 )); then
                {
                    echo "poll=$i listener=$([[ -n "$lines" ]] && echo present || echo absent)"
                    _e183_warp_cli_capture status 2>&1 || true
                } >>"$E186_WARP_DIAG"
            fi
            if test "$i" = 15 || test "$i" = 35; then
                _e186_configure_local_proxy >>"$E186_WARP_DIAG" 2>&1 || true
                _e183_warp_cli_capture connect >>"$E186_WARP_DIAG" 2>&1 || true
            fi
            if test "$i" = 55; then
                _e183_warp_cli_capture disconnect >>"$E186_WARP_DIAG" 2>&1 || true
                _e186_configure_local_proxy >>"$E186_WARP_DIAG" 2>&1 || true
                _e183_warp_cli_capture connect >>"$E186_WARP_DIAG" 2>&1 || true
            fi
            if test "$i" = 70; then
                systemctl restart "$svc" >>"$E186_WARP_DIAG" 2>&1 || true
                sleep 2
                _e140_warp_register >>"$E186_WARP_DIAG" 2>&1 || true
                _e186_configure_local_proxy >>"$E186_WARP_DIAG" 2>&1 || true
                _e183_warp_cli_capture connect >>"$E186_WARP_DIAG" 2>&1 || true
            fi
            sleep 1
        done
    fi
    _e186_capture_warp_diag "$reason"
    _e183_warp_cli_capture disconnect >/dev/null 2>&1 || true
    E140_ACTIVE_LOG="$old_log"
    error "WARP Local proxy未安全收敛（阶段：$reason），已断开；诊断：$E186_WARP_DIAG"
    return 1
}

_e183_warp_connect_local_proxy() { _e186_warp_connect_local_proxy; }
_e136_warp_connect_local_proxy() { _e186_warp_connect_local_proxy; }
_e137_warp_connect_local_proxy() { _e186_warp_connect_local_proxy; }

# E185 already owns the safe Xray-native WireGuard fallback. Clone its enable
# transaction only to update release identity; dynamic Local proxy calls now
# resolve to the E186 implementation above.
if declare -F _e185_warp_enable >/dev/null 2>&1; then
    eval "$(declare -f _e185_warp_enable | sed \
        -e '1s/_e185_warp_enable/_e186_warp_enable/' \
        -e 's/V199e185/V199e186/g' \
        -e 's/TCP经WARP；UDP全局阻断。/未被已有明确规则命中的TCP经WARP；同范围UDP阻断。/g' \
        -e 's/E185 WARP/E186 WARP/g')"
fi
_e185_warp_enable() { _e186_warp_enable "$@"; }

if declare -F _e185_warp_status >/dev/null 2>&1; then
    eval "$(declare -f _e185_warp_status | sed \
        -e '1s/_e185_warp_status/_e186_warp_status_base/' \
        -e 's/V199e185/V199e186/g')"
fi
_e186_warp_status() {
    local functional=NOT-USED backend
    _e186_warp_status_base
    backend=$(_e138_state_get backend disabled)
    if test "$backend" = masque; then
        functional=DOWN
        _e186_warp_proxy_ready && functional=UP || true
    fi
    printf '  %-28s %s\n' '官方代理功能验证' "$functional (listener + SOCKS5 + warp trace)"
    printf '  %-28s %s\n' 'E186 Local proxy诊断' "$E186_WARP_DIAG"
}
_e185_warp_status() { _e186_warp_status; }
_e183_warp_status() { _e186_warp_status; }
_e140_warp_status() { _e186_warp_status; }
_e139_warp_status() { _e186_warp_status; }
_e138_warp_status() { _e186_warp_status; }
_e137_warp_status() { _e186_warp_status; }

_e138_warp_global_menu() {
    local n
    while true; do
        clear
        _e186_warp_status
        echo '  1) 自动后端：仅IPv4目标走WARP'
        echo '  2) 自动后端：仅IPv6目标走WARP'
        echo '  3) 自动后端：IPv4+IPv6目标都走WARP'
        echo '  4) 强制Xray原生WireGuard后端（再选IPv4/IPv6/双栈）'
        echo '  5) 强制Cloudflare官方MASQUE Local proxy（再选地址族）'
        echo '  6) 按期望状态修复WARP与Xray规则'
        echo '  7) 关闭全部Xray WARP分流'
        echo '  8) 查看最近诊断'
        echo '  9) 查看IPv4/IPv6语义说明'
        echo '  0) 返回'
        read -rp '操作: ' n || true
        case "$n" in
            1) _e138_warp_enable global global ipv4 auto; _e138_pause ;;
            2) _e138_warp_enable global global ipv6 auto; _e138_pause ;;
            3) _e138_warp_enable global global dual auto; _e138_pause ;;
            4) _e185_force_backend_menu xray-wg global global; _e138_pause ;;
            5) _e185_force_backend_menu masque global global; _e138_pause ;;
            6) _e138_warp_reconcile; _e138_pause ;;
            7) _e138_warp_disable; _e138_pause ;;
            8)
                tail -n 240 "$E186_WARP_DIAG" 2>/dev/null || true
                tail -n 180 "$E185_WARP_DIAG" 2>/dev/null || true
                tail -n 180 "$E185_WG_LOG" 2>/dev/null || true
                _e138_pause
                ;;
            9)
                warn 'IPv4/IPv6表示由Xray送入WARP的目标地址族，不会启用Cloudflare系统全隧道，也不会改VPS默认路由。'
                warn '官方Local proxy固定使用MASQUE和127.0.0.1监听；Xray原生WireGuard使用noKernelTun=true。'
                warn 'IPv4-only会阻断未被既有规则命中的IPv6字面量，IPv6-only同理阻断IPv4；双栈允许两者，同范围UDP阻断以防直连泄漏。'
                _e138_pause
                ;;
            0) return ;;
            *) warn '无效操作。'; sleep 1 ;;
        esac
    done
}

_e138_warp_selective_menu() {
    local n
    while true; do
        clear
        _e186_warp_status
        echo '  1) Google+Meta核心档：IPv4目标走WARP'
        echo '  2) Google+Meta核心档：IPv6目标走WARP'
        echo '  3) Google+Meta核心档：IPv4+IPv6目标走WARP'
        echo '  4) 强制Xray原生WireGuard（再选地址族）'
        echo '  5) 强制官方MASQUE Local proxy（再选地址族）'
        echo '  6) 仅Google核心档：自动后端IPv4'
        echo '  7) 仅Meta核心档：自动后端IPv4'
        echo '  8) 按期望状态修复WARP与Xray规则'
        echo '  9) 关闭全部Xray WARP分流'
        echo '  0) 返回'
        read -rp '操作: ' n || true
        case "$n" in
            1) _e138_warp_enable selective google-meta-core ipv4 auto; _e138_pause ;;
            2) _e138_warp_enable selective google-meta-core ipv6 auto; _e138_pause ;;
            3) _e138_warp_enable selective google-meta-core dual auto; _e138_pause ;;
            4) _e185_force_backend_menu xray-wg selective google-meta-core; _e138_pause ;;
            5) _e185_force_backend_menu masque selective google-meta-core; _e138_pause ;;
            6) _e138_warp_enable selective google-core ipv4 auto; _e138_pause ;;
            7) _e138_warp_enable selective meta-core ipv4 auto; _e138_pause ;;
            8) _e138_warp_reconcile; _e138_pause ;;
            9) _e138_warp_disable; _e138_pause ;;
            0) return ;;
            *) warn '无效操作。'; sleep 1 ;;
        esac
    done
}

