#==============================================================================
# V199e188 FINAL TRANSACTION / QR DEDUPLICATION LAYER
# - The inherited E127 installer emits a summary after its core commit, while
#   E139/E140 emits another after WARP/runtime reconciliation. E183 only
#   prevented a third fallback export. E188 suppresses every nested export and
#   emits exactly once after the outer node transaction has fully succeeded.
# - Failed, rolled-back or user-cancelled node transactions emit no credential
#   QR. Manual exports and user-management exports remain immediate.
# - Terminal qrencode fallbacks are captured before display so a formatter
#   which writes partial output and then fails cannot leave duplicate fragments.
#==============================================================================
readonly E188_VERSION="199e188"
readonly E188_DIR="$CONFIG_DIR/e188"
readonly E188_SELF_PATH="$SCRIPT_DIR/ex199e188.sh"
readonly E188_LATEST_PATH="$SCRIPT_DIR/ex199e_latest.sh"
readonly E188_TX_ROOT="/var/backups/xray-e188"
readonly E188_HOT_LOG="/var/log/xray/e188/hot-update-last.log"
readonly E188_CRITICAL_MARKER="$E188_DIR/CRITICAL_RECOVERY_REQUIRED.env"

_e188_prepare() {
    _e186_prepare || return 1
    install -d -m 0700 "$E188_DIR" "$E188_TX_ROOT" \
        "$(dirname "$E188_HOT_LOG")" || return 1
}

_e188_new_tx() {
    local name="${1:-transaction}" dir
    _e188_prepare || return 1
    dir="$E188_TX_ROOT/${name}-$(date +%Y%m%d_%H%M%S)-$$-$RANDOM"
    install -d -m 0700 "$dir" || return 1
    printf '%s\n' "$dir"
}

_e188_install_self() {
    local tx target snap tmp failed=0
    local -a targets=("$SYMLINK" "$E188_SELF_PATH" "$E188_LATEST_PATH")
    test -r "$SCRIPT_PATH" || return 1
    _e188_prepare || return 1
    tx=$(_e188_new_tx self-install) || return 1
    for target in "${targets[@]}"; do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
        _e135_snapshot_file "$target" "$snap" || return 1
    done
    for target in "${targets[@]}"; do
        install -d -m 0755 "$(dirname -- "$target")" || { failed=1; break; }
        tmp="$target.e188-new.$$"
        install -m 0755 "$SCRIPT_PATH" "$tmp" || {
            rm -f -- "$tmp"
            failed=1
            break
        }
        mv -f -- "$tmp" "$target" || {
            rm -f -- "$tmp"
            failed=1
            break
        }
        cmp -s "$SCRIPT_PATH" "$target" || { failed=1; break; }
    done
    if test "$failed" -ne 0; then
        for target in "${targets[@]}"; do
            snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
            _e135_restore_file "$target" "$snap" || true
        done
        return 1
    fi
    hash -r 2>/dev/null || true
}

_e188_write_version() {
    local tmp
    _e188_prepare || return 1
    tmp=$(_e118_mktemp e188-version) || return 1
    printf '%s\n' "$E188_VERSION" >"$tmp" || return 1
    _e118_atomic_install "$tmp" "$SCRIPT_VERSION_FILE" 0600
}

# All inherited writers now resolve to the E188 artifact.
_e118_install_self() { _e188_install_self "$@"; }
_e138_install_self() { _e188_install_self "$@"; }
_e152_install_self() { _e188_install_self "$@"; }
_e159_install_self() { _e188_install_self "$@"; }
_e182_install_self() { _e188_install_self "$@"; }
_e183_install_self() { _e188_install_self "$@"; }
_e185_install_self() { _e188_install_self "$@"; }
_e186_install_self() { _e188_install_self "$@"; }
_e159_write_version() { _e188_write_version "$@"; }
_e152_write_version() { _e188_write_version "$@"; }
_e142_write_version() { _e188_write_version "$@"; }
_e182_write_version() { _e188_write_version "$@"; }
_e183_write_version() { _e188_write_version "$@"; }
_e185_write_version() { _e188_write_version "$@"; }
_e186_write_version() { _e188_write_version "$@"; }

if declare -F _e138_system_paths >/dev/null 2>&1; then
    eval "$(declare -f _e138_system_paths | sed \
        '1s/_e138_system_paths/_e188_system_paths_base/')"
fi
_e138_system_paths() {
    _e188_system_paths_base
    printf '%s\n' "$E188_DIR" "$E188_SELF_PATH" "$E188_LATEST_PATH"
}

_e188_qr_terminal() {
    local uri="$1" diag="$2" level tmp format rc=1
    level=$(_e186_qr_level "$uri")
    tmp=$(mktemp /tmp/xray-e188-qr-terminal.XXXXXX) || return 1
    chmod 0600 "$tmp" 2>/dev/null || true
    for format in UTF8 ANSIUTF8 UTF8i ASCIIi; do
        : >"$tmp" || { rm -f -- "$tmp"; return 1; }
        if qrencode -l "$level" -m 2 -t "$format" "$uri" \
          >"$tmp" 2>>"$diag" && test -s "$tmp"; then
            if cat -- "$tmp"; then rc=0; fi
            break
        fi
    done
    rm -f -- "$tmp"
    return "$rc"
}
_e186_qr_terminal() { _e188_qr_terminal "$@"; }

if declare -F do_summary >/dev/null 2>&1; then
    eval "$(declare -f do_summary | sed '1s/do_summary/_e188_summary_base/')"
fi
do_summary() {
    if test "${E188_SUMMARY_SUPPRESS:-0}" = 1; then
        E188_SUMMARY_PENDING=1
        E183_SUMMARY_EMITTED=1
        return 0
    fi
    _e188_summary_base "$@"
}

if declare -F _e182_install_mode >/dev/null 2>&1; then
    eval "$(declare -f _e182_install_mode | sed \
        '1s/_e182_install_mode/_e188_install_mode_base/')"
fi
_e182_install_mode() {
    local rc=0
    local E188_SUMMARY_SUPPRESS=1
    local E188_SUMMARY_PENDING=0

    # A previous cancelled Reality build must not poison a later VLESSENC or
    # SS2022 build which does not call choose_sni().
    E182_SNI_CANCELLED=0
    E168_SNI_CANCELLED=0

    _e188_install_mode_base "$@" || rc=$?
    test "$rc" -eq 0 || return "$rc"

    # Cancellation is a successful no-op. Never export the pre-existing node
    # as though it were the newly requested one.
    if test "${E182_SNI_CANCELLED:-0}" = 1 \
      || test "${E168_SNI_CANCELLED:-0}" = 1; then
        return 0
    fi

    # Release the dynamically scoped gate only after every inherited
    # Xray/WARP/IPv6/runtime check has passed, then export exactly once.
    E188_SUMMARY_SUPPRESS=0
    E188_SUMMARY_PENDING=0
    do_summary || rc=$?
    return "$rc"
}

if declare -F _e186_main_menu_impl >/dev/null 2>&1; then
    eval "$(declare -f _e186_main_menu_impl | sed \
        -e '1s/_e186_main_menu_impl/_e188_main_menu_impl/' \
        -e 's/V199e186/V199e188/g' \
