main_menu() { _e188_main_menu_impl; }

_e188_hot_step() {
    local phase="$1"
    shift
    _e159_phase_log "$E188_HOT_LOG" "$phase" begin
    if "$@"; then
        _e159_phase_log "$E188_HOT_LOG" "$phase" ok
        return 0
    fi
    _e159_phase_log "$E188_HOT_LOG" "$phase" fail
    error "E188热更新失败阶段：$phase"
    return 1
}

_e188_hot_update_preflight() {
    _e186_hot_update_preflight || return 1
    _e188_prepare || return 1
    declare -F _e188_install_self >/dev/null 2>&1 || return 1
    declare -F _e188_install_mode_base >/dev/null 2>&1 || return 1
    declare -F _e188_summary_base >/dev/null 2>&1 || return 1
    declare -F _e188_qr_terminal >/dev/null 2>&1 || return 1
}

