        -e '1s/_e186_hot_update/_e188_hot_update/' \
        -e 's/_e186_hot_step/_e188_hot_step/g' \
        -e 's/_e186_install_self/_e188_install_self/g' \
        -e 's/_e186_write_version/_e188_write_version/g' \
        -e 's/_e186_new_tx/_e188_new_tx/g' \
        -e 's/\$E186_HOT_LOG/\$E188_HOT_LOG/g' \
        -e 's/\$E186_CRITICAL_MARKER/\$E188_CRITICAL_MARKER/g' \
        -e 's/\$E186_SELF_PATH/\$E188_SELF_PATH/g' \
        -e 's/\$E186_LATEST_PATH/\$E188_LATEST_PATH/g' \
        -e 's/xray-e186-hot-update.lock/xray-e188-hot-update.lock/g' \
        -e 's/exec 186>/exec 188>/g' \
        -e 's/flock -n 186/flock -n 188/g' \
        -e 's/before_hot_update_e186/before_hot_update_e188/g' \
        -e 's/E186热更新/E188热更新/g' \
        -e 's/E186回滚/E188回滚/g' \
        -e 's/V199e186/V199e188/g')"
fi
hot_update_from_legacy() { _e188_hot_update_preflight && _e188_hot_update; }

if declare -F do_uninstall >/dev/null 2>&1; then
    eval "$(declare -f do_uninstall | sed '1s/do_uninstall/_e188_uninstall_base/')"
fi
do_uninstall() {
    local rc=0
    _e188_uninstall_base "$@" || rc=$?
    if test "$rc" -eq 0; then
        rm -f -- "$E188_SELF_PATH" "$E188_LATEST_PATH" 2>/dev/null || true
        rm -rf -- "$E188_DIR" "$E188_TX_ROOT" \
            "$(dirname "$E188_HOT_LOG")" 2>/dev/null || true
    fi
    return "$rc"
}

_e188_summary_transaction_self_test() (
    local emitted=0
    _e188_summary_base() { emitted=$((emitted + 1)); return 0; }

    _e188_install_mode_base() {
        do_summary
        do_summary
        return 0
    }
    _e182_install_mode 1 test >/dev/null || return 1
    test "$emitted" -eq 1 || return 1

    emitted=0
    _e188_install_mode_base() {
        do_summary
        return 7
    }
    if _e182_install_mode 1 test >/dev/null; then return 1; fi
    test "$emitted" -eq 0 || return 1

    emitted=0
    _e188_install_mode_base() {
        E182_SNI_CANCELLED=1
        do_summary
        return 0
    }
    _e182_install_mode 1 test >/dev/null || return 1
    test "$emitted" -eq 0 || return 1

    # The cancellation flag must be cleared before the next non-Reality build.
    emitted=0
    _e188_install_mode_base() {
        do_summary
        return 0
    }
    _e182_install_mode 3 test >/dev/null || return 1
    test "$emitted" -eq 1 || return 1

    emitted=0
    do_summary >/dev/null || return 1
    test "$emitted" -eq 1
)

_e188_structure_audit() {
    local rc=0 size lines dispatchers menu summary install_mode terminal hot
    echo 'V199e188 structure audit:'
    size=$(wc -c <"$SCRIPT_PATH" | tr -d ' ')
    lines=$(wc -l <"$SCRIPT_PATH" | tr -d ' ')
    dispatchers=$(grep -c '^# V199e188 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true)
    menu=$(declare -f _e188_main_menu_impl 2>/dev/null || true)
    summary=$(declare -f do_summary 2>/dev/null || true)
    install_mode=$(declare -f _e182_install_mode 2>/dev/null || true)
    terminal=$(declare -f _e188_qr_terminal 2>/dev/null || true)
    hot=$(declare -f _e188_hot_update 2>/dev/null || true)
    echo "  file_bytes=$size"
    echo "  lines=$lines"
    echo "  final_dispatchers=$dispatchers"
    echo '  node_summary_owner=e188 (nested suppression + final single commit)'
    echo '  qr_terminal_owner=e188 (failed formatter output isolated)'
    echo '  warp_owner=e186 (strict loopback + SOCKS5 trace + route guard)'
    test "$size" -gt 2000000 && test "$lines" -gt 45000 || rc=1
    test "$dispatchers" -eq 1 || rc=1
    grep -q 'V199e188 - 事务稳态版' <<<"$menu" || rc=1
    grep -q 'E188_SUMMARY_SUPPRESS' <<<"$summary" || rc=1
    grep -q 'E188_SUMMARY_SUPPRESS=1' <<<"$install_mode" || rc=1
    grep -q 'do_summary' <<<"$install_mode" || rc=1
    grep -Eq '>[[:space:]]*"\$tmp"' <<<"$terminal" || rc=1
    grep -q '_e188_install_self' <<<"$hot" || rc=1
    _e188_summary_transaction_self_test || rc=1
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL'
    return "$rc"
}

_e188_self_test() {
    local rc=0 d fake out png svg diag
    d=$(mktemp -d /tmp/xray-e188-selftest.XXXXXX) || return 1
    echo 'V199e188 fast release gate:'
    bash -n "$SCRIPT_PATH" \
      && echo '  [PASS] bash syntax' \
      || { echo '  [FAIL] bash syntax'; rc=1; }
    test "$SCRIPT_VERSION" = 199e188 && test "$E188_VERSION" = 199e188 \
      && echo '  [PASS] release identity' \
      || { echo '  [FAIL] release identity'; rc=1; }
    _e188_summary_transaction_self_test \
      && echo '  [PASS] one final summary; failure/cancel none; cancel state resets' \
      || { echo '  [FAIL] node summary transaction gate'; rc=1; }

    fake="$d/bin"
    mkdir -p "$fake"
    cat >"$fake/qrencode" <<'EOF_E188_FAKE_TERMINAL'
#!/usr/bin/env bash
type=
out=
while test "$#" -gt 0; do
    case "$1" in
        --version) echo 'qrencode mock 1'; exit 0 ;;
        -t) type="$2"; shift 2 ;;
        -o) out="$2"; shift 2 ;;
        -l|-m|-s) shift 2 ;;
        *) shift ;;
    esac
done
case "$type" in
    UTF8) printf 'discarded-partial\n'; exit 1 ;;
    ANSIUTF8) printf 'single-terminal-qr\n'; exit 0 ;;
    PNG) printf '\211PNG\r\n\032\nmock' >"$out"; exit 0 ;;
    SVG) printf '<svg xmlns="http://www.w3.org/2000/svg"></svg>\n' >"$out"; exit 0 ;;
    *) exit 1 ;;
esac
EOF_E188_FAKE_TERMINAL
    chmod 0755 "$fake/qrencode"
    diag="$d/qr.log"
    out=$(PATH="$fake:$PATH" _e188_qr_terminal 'vless://unit-test' "$diag" || true)
    test "$out" = single-terminal-qr \
      && echo '  [PASS] terminal QR fallback cannot duplicate partial output' \
      || { echo '  [FAIL] terminal QR fallback isolation'; rc=1; }
    png="$d/test.png"
    svg="$d/test.svg"
    PATH="$fake:$PATH" _e186_qr_generate_files \
        'vless://unit-test' "$png" "$svg" "$diag" \
      && _e186_png_valid "$png" && _e186_svg_valid "$svg" \
      && echo '  [PASS] verified QR PNG/SVG artifacts' \
      || { echo '  [FAIL] QR artifacts'; rc=1; }
    _e186_listener_set_safe \
        "LISTEN 0 4096 127.0.0.1:$E138_WARP_PORT 0.0.0.0:* users:((\"warp-svc\",pid=1,fd=1))" \
      && ! _e186_listener_set_safe \
        "LISTEN 0 4096 0.0.0.0:$E138_WARP_PORT 0.0.0.0:*" \
      && _e186_warp_trace_ok $'warp=on\nloc=US\n' \
      && echo '  [PASS] inherited WARP listener/trace truth gate' \
      || { echo '  [FAIL] inherited WARP truth gate'; rc=1; }
    _e188_structure_audit >/dev/null || rc=1
    rm -rf -- "$d"
    test "$rc" -eq 0 && echo 'V199e188 result: PASS' || echo 'V199e188 result: FAIL'
    return "$rc"
}

