_e202_prepare() {
    _e188_prepare || return 1
    install -d -m 0700 "$E202_DIR" "$E202_TX_ROOT" \
        "$(dirname "$E202_HOT_LOG")" || return 1
}

_e202_new_tx() {
    local name="${1:-transaction}" dir
    _e202_prepare || return 1
    dir="$E202_TX_ROOT/${name}-$(date +%Y%m%d_%H%M%S)-$$-$RANDOM"
    install -d -m 0700 "$dir" || return 1
    printf '%s\n' "$dir"
}

_e202_prune_tx_root() {
    local root="$1" keep="$2" protected=" " p real row n=0
    shift 2
    [[ "$keep" =~ ^[0-9]+$ ]] && (( keep >= 3 && keep <= 100 )) || keep=12
    real=$(readlink -f -- "$root" 2>/dev/null || true)
    test -n "$real" && test -d "$real" || return 0
    root="$real"
    for p in "$@"; do
        real=$(readlink -f -- "$p" 2>/dev/null || true)
        case "$real" in "$root"/*) protected+="$real " ;; esac
    done
    while IFS=$'\t' read -r _ row; do
        test -n "$row" || continue
        real=$(readlink -f -- "$row" 2>/dev/null || true)
        case "$real" in "$root"/*) ;; *) continue ;; esac
        n=$((n+1))
        test "$n" -le "$keep" && continue
        [[ "$protected" == *" $real "* ]] && continue
        rm -rf -- "${real:?}" 2>/dev/null || true
    done < <(find "$root" -mindepth 1 -maxdepth 1 -type d \
        -printf '%T@\t%p\n' 2>/dev/null | sort -nr)
}

_e202_prune_tx() {
    local keep="${XRAY_E202_TX_KEEP:-12}" state_restore="" critical_restore=""
    state_restore=$(sed -n 's/^restore_snapshot=//p' \
        "$E202_SMALL_STATE" 2>/dev/null | tail -n1)
    critical_restore=$(sed -n 's/^restore_snapshot=//p' \
        "$E202_CRITICAL_MARKER" 2>/dev/null | tail -n1)
    _e202_prune_tx_root "$E202_TX_ROOT" "$keep" \
        "$state_restore" "$critical_restore" "$@"
}

_e202_install_self() {
    local tx target snap tmp failed=0
    local -a targets=("$SYMLINK" "$E202_SELF_PATH" "$E202_LATEST_PATH")
    test -r "$SCRIPT_PATH" || return 1
    _e202_prepare || return 1
    tx=$(_e202_new_tx self-install) || return 1
    for target in "${targets[@]}"; do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
        _e135_snapshot_file "$target" "$snap" || return 1
    done
    for target in "${targets[@]}"; do
        install -d -m 0755 "$(dirname -- "$target")" || { failed=1; break; }
        tmp="$target.e202-new.$$"
        install -m 0755 "$SCRIPT_PATH" "$tmp" || {
            rm -f -- "$tmp"
            failed=1
            break
        }
        mv -f -- "$tmp" "$target" || {
            rm -f -- "$tmp"
            failed=1
            break
        }
        cmp -s "$SCRIPT_PATH" "$target" || { failed=1; break; }
    done
    if test "$failed" -ne 0; then
        for target in "${targets[@]}"; do
            snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
            _e135_restore_file "$target" "$snap" || true
        done
        return 1
    fi
    hash -r 2>/dev/null || true
}

_e202_write_version() {
    local tmp
    _e202_prepare || return 1
    tmp=$(_e118_mktemp e202-version) || return 1
    printf '%s\n' "$E202_VERSION" >"$tmp" || return 1
    _e118_atomic_install "$tmp" "$SCRIPT_VERSION_FILE" 0600
}

