# Mode 3F2 intentionally has one profile-specific item more than the legacy
# F tail.  Keep tcp_max_tw_buckets out of the shared F tail so switching from
# 3F2 back to a 25-item F/B1 profile restores that key from the first-enable
# snapshot instead of silently retaining 8192.
_e202_small_bbr_mode3f2() {
    cat <<'EOF_E202_SMALL_BBR_MODE3F2'
net.core.default_qdisc = fq
net.ipv4.tcp_congestion_control = bbr
net.core.rmem_default = 96695
net.core.wmem_default = 26215
net.core.rmem_max = 19977218
net.core.wmem_max = 19977218
net.ipv4.tcp_rmem = 4096 96695 19977218
net.ipv4.tcp_wmem = 4096 26215 19977218
net.ipv4.tcp_moderate_rcvbuf = 1
net.ipv4.tcp_window_scaling = 1
net.ipv4.tcp_adv_win_scale = 1
net.ipv4.tcp_mtu_probing = 1
net.ipv4.tcp_ecn = 0
net.ipv4.tcp_slow_start_after_idle = 0
EOF_E202_SMALL_BBR_MODE3F2
    _e202_small_bbr_f_tail | sed \
        's/net.ipv4.tcp_fin_timeout = 20/net.ipv4.tcp_fin_timeout = 10/'
    printf '%s\n' 'net.ipv4.tcp_max_tw_buckets = 8192'
}

