    cat <<'EOF_E202_SMALL_BBR_MODEB1'
net.core.default_qdisc = fq
net.ipv4.tcp_congestion_control = bbr
net.core.rmem_default = 353026
net.core.wmem_default = 262144
net.core.rmem_max = 65777218
net.core.wmem_max = 65777218
