net.ipv4.tcp_slow_start_after_idle = 0
EOF_E202_SMALL_BBR_MODEB1
    _e202_small_bbr_f_tail
}

# Mode 2 is the default/recommended profile. Profile labels are retained from
# the user's naming, while status output also prints exact byte/KiB/MiB values.
_e202_small_bbr_default() {
    _e202_small_bbr_mode2
}

_e202_small_bbr_base_keys() {
    _e202_small_bbr_mode2 | awk -F= '{
        key=$1
        gsub(/[[:space:]]/,"",key)
        if (key!="") print key
    }'
}

_e202_small_bbr_extra_keys() {
    _e202_small_bbr_f_tail | awk -F= '{
        key=$1
        gsub(/[[:space:]]/,"",key)
        if (key!="") print key
    }'
}

_e202_small_bbr_f2_extra_keys() {
    printf '%s\n' net.ipv4.tcp_max_tw_buckets
}

_e202_small_bbr_keys() {
    _e202_small_bbr_base_keys
}

_e202_small_bbr_all_keys() {
    {
        _e202_small_bbr_base_keys
        _e202_small_bbr_extra_keys
        _e202_small_bbr_f2_extra_keys
    } | awk 'NF&&!seen[$0]++'
}

_e202_small_bbr_file_keys() {
    local file="$1"
    awk -F= '{
        key=$1
        gsub(/[[:space:]]/,"",key)
        if (key!="") print key
    }' "$file"
}

_e202_profile_value() {
    local file="$1" wanted="$2"
    awk -F= -v wanted="$wanted" '{
      k=$1
      gsub(/[[:space:]]/,"",k)
      if (k==wanted) {
        v=substr($0,index($0,"=")+1)
        gsub(/^[[:space:]]+|[[:space:]]+$/,"",v)
        print v
        exit
      }
    }' "$file"
}

_e202_small_bbr_validate_file() {
    local file="$1" lines active keys expected_keys qdisc cc key value extended=0 f2=0
    local rdef wdef rmax wmax trmin trdef trmax twmin twdef twmax
    local tw_reuse timestamps
    test -f "$file" || return 1
    lines=$(awk 'NF{n++}END{print n+0}' "$file")
    active=$(awk -F= '
      /^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/ {n++}
      END {print n+0}
    ' "$file")
    case "$lines:$active" in
        14:14) expected_keys=$(_e202_small_bbr_base_keys) ;;
        25:25)
            expected_keys=$({
                _e202_small_bbr_base_keys
                _e202_small_bbr_extra_keys
            } | awk 'NF&&!seen[$0]++')
            extended=1
            ;;
        26:26) expected_keys=$(_e202_small_bbr_all_keys); extended=1; f2=1 ;;
        *) return 1 ;;
    esac
    keys=$(_e202_small_bbr_file_keys "$file")
    test "$keys" = "$expected_keys" || return 1

    qdisc=$(_e202_profile_value "$file" net.core.default_qdisc)
    cc=$(_e202_profile_value "$file" net.ipv4.tcp_congestion_control)
    test "$qdisc" = fq && test "$cc" = bbr || return 1

    for key in net.core.rmem_default net.core.wmem_default \
        net.core.rmem_max net.core.wmem_max; do
        value=$(_e202_profile_value "$file" "$key")
        [[ "$value" =~ ^[0-9]+$ ]] || return 1
        test "$value" -ge 4096 && test "$value" -le 1073741824 || return 1
    done
    rdef=$(_e202_profile_value "$file" net.core.rmem_default)
    wdef=$(_e202_profile_value "$file" net.core.wmem_default)
    rmax=$(_e202_profile_value "$file" net.core.rmem_max)
    wmax=$(_e202_profile_value "$file" net.core.wmem_max)
    test "$rdef" -le "$rmax" && test "$wdef" -le "$wmax" || return 1

    read -r trmin trdef trmax <<<"$(_e202_profile_value "$file" net.ipv4.tcp_rmem)"
    read -r twmin twdef twmax <<<"$(_e202_profile_value "$file" net.ipv4.tcp_wmem)"
    for value in "$trmin" "$trdef" "$trmax" "$twmin" "$twdef" "$twmax"; do
        [[ "$value" =~ ^[0-9]+$ ]] || return 1
        test "$value" -ge 1024 && test "$value" -le 1073741824 || return 1
    done
    test "$trmin" -le "$trdef" && test "$trdef" -le "$trmax" || return 1
    test "$twmin" -le "$twdef" && test "$twdef" -le "$twmax" || return 1
    test "$trmax" -le "$rmax" && test "$twmax" -le "$wmax" || return 1

    for key in net.ipv4.tcp_moderate_rcvbuf \
        net.ipv4.tcp_window_scaling net.ipv4.tcp_slow_start_after_idle; do
        value=$(_e202_profile_value "$file" "$key")
        case "$value" in 0|1) ;; *) return 1 ;; esac
    done
    value=$(_e202_profile_value "$file" net.ipv4.tcp_adv_win_scale)
    [[ "$value" =~ ^-?[0-9]+$ ]] \
      && test "$value" -ge -31 && test "$value" -le 31 || return 1
    value=$(_e202_profile_value "$file" net.ipv4.tcp_mtu_probing)
    case "$value" in 0|1|2) ;; *) return 1 ;; esac
    value=$(_e202_profile_value "$file" net.ipv4.tcp_ecn)
    case "$value" in 0|1|2|3|4|5) ;; *) return 1 ;; esac

    if test "$extended" -eq 1; then
        value=$(_e202_profile_value "$file" net.ipv4.tcp_max_reordering)
        [[ "$value" =~ ^[0-9]+$ ]] \
          && test "$value" -ge 3 && test "$value" -le 100000 || return 1
        value=$(_e202_profile_value "$file" net.ipv4.tcp_fastopen)
        [[ "$value" =~ ^[0-9]+$ ]] \
          && test "$value" -ge 0 && test "$value" -le 2047 || return 1
        tw_reuse=$(_e202_profile_value "$file" net.ipv4.tcp_tw_reuse)
        case "$tw_reuse" in 0|1|2) ;; *) return 1 ;; esac
        timestamps=$(_e202_profile_value "$file" net.ipv4.tcp_timestamps)
        case "$timestamps" in 0|1|2) ;; *) return 1 ;; esac
        if test "$tw_reuse" != 0; then
            test "$timestamps" != 0 || return 1
        fi
        value=$(_e202_profile_value "$file" net.ipv4.tcp_fin_timeout)
        [[ "$value" =~ ^[0-9]+$ ]] \
          && test "$value" -ge 1 && test "$value" -le 600 || return 1
        for key in net.ipv4.tcp_max_syn_backlog \
            net.core.netdev_max_backlog net.core.somaxconn; do
            value=$(_e202_profile_value "$file" "$key")
            [[ "$value" =~ ^[0-9]+$ ]] \
              && test "$value" -ge 128 && test "$value" -le 16777216 || return 1
        done
        for key in net.ipv4.tcp_sack net.ipv4.tcp_dsack; do
            value=$(_e202_profile_value "$file" "$key")
            case "$value" in 0|1) ;; *) return 1 ;; esac
        done
        value=$(_e202_profile_value "$file" net.ipv4.tcp_recovery)
        [[ "$value" =~ ^(0[xX][0-9A-Fa-f]+|[0-9]+)$ ]] || return 1
        (( value >= 0 && value <= 255 )) 2>/dev/null || return 1
        if test "$f2" -eq 1; then
            value=$(_e202_profile_value "$file" net.ipv4.tcp_max_tw_buckets)
            [[ "$value" =~ ^[0-9]+$ ]] \
              && test "$value" -ge 1024 && test "$value" -le 16777216 || return 1
        fi
    fi
}

_e202_small_bbr_profile_id_file() {
    local file="$1" id fn
    _e202_small_bbr_validate_file "$file" || {
        echo invalid
        return 1
    }
    for id in mode1 mode2 mode3 mode1f mode2f mode3f mode3f2 modeb1; do
        fn="_e202_small_bbr_${id}"
        cmp -s "$file" <("$fn") && {
            echo "$id"
            return 0
        }
    done
    case "$(awk 'NF{n++}END{print n+0}' "$file")" in
        14) echo custom ;;
        25) echo custom-f ;;
        26) echo custom-f2 ;;
        *) echo invalid; return 1 ;;
    esac
}

_e202_small_bbr_profile_name() {
    case "${1:-}" in
        mode1) echo '模式1--2.50-22MB' ;;
        mode2) echo '模式2--1.30x0.19-31MB（默认）' ;;
        mode3) echo '模式3--0.9x0.25-13MB' ;;
        mode1f) echo '模式1F--2.50-22MB' ;;
        mode2f) echo '模式2F--1.30w0.19-31MB' ;;
        mode3f) echo '模式3F--0.9w0.23-14MB' ;;
        mode3f2) echo '模式3F2--0.9w0.25-19MB-time10s' ;;
        modeb1) echo '模式B1--3.5w2.6-62MB' ;;
        custom) echo '自定义基础14项' ;;
        custom-f) echo '自定义扩展25项' ;;
        custom-f2) echo '自定义扩展26项' ;;
        invalid) echo '无效保存档（拒绝应用）' ;;
        *) echo '未知档位' ;;
    esac
}

# E196/E198 extended profiles used the former 21-item schema. E202 adds
# tcp_timestamps, tcp_sack, tcp_dsack and tcp_recovery and therefore owns
# exactly 25 items.
# Only byte-for-byte known legacy presets are mapped. An unknown legacy custom
# profile is rejected before the old release exits, so E202 never invents two
# new values or silently rewrites an old user-owned profile.
_e202_legacy_old_tail() {
    local reordering="$1"
    cat <<EOF_E202_LEGACY_OLD_TAIL
net.ipv4.tcp_max_reordering = $reordering
net.ipv4.tcp_fastopen = 3
net.ipv4.tcp_tw_reuse = 1
net.ipv4.tcp_fin_timeout = 20
net.ipv4.tcp_max_syn_backlog = 8192
net.core.netdev_max_backlog = 16380
net.core.somaxconn = 8192
EOF_E202_LEGACY_OLD_TAIL
}

_e202_legacy_old_profile() {
    local id="$1" reordering="$2"
    case "$id" in
        mode1) _e202_small_bbr_mode1 ;;
        mode2) _e202_small_bbr_mode2 ;;
        mode3) _e202_small_bbr_mode3 ;;
        mode1f)
            _e202_small_bbr_mode1 | sed \
                's/net.ipv4.tcp_slow_start_after_idle = 1/net.ipv4.tcp_slow_start_after_idle = 0/'
            _e202_legacy_old_tail "$reordering"
            ;;
        mode2f)
            _e202_small_bbr_mode2
            _e202_legacy_old_tail "$reordering"
            ;;
        mode3f)
            _e202_small_bbr_mode3
            _e202_legacy_old_tail "$reordering"
            ;;
        modeb)
            cat <<'EOF_E202_LEGACY_OLD_MODEB'
net.core.default_qdisc = fq
net.ipv4.tcp_congestion_control = bbr
net.core.rmem_default = 131072
net.core.wmem_default = 17380
net.core.rmem_max = 33054432
net.core.wmem_max = 33054432
net.ipv4.tcp_rmem = 4096 131072 33054432
net.ipv4.tcp_wmem = 4096 17380 33054432
net.ipv4.tcp_moderate_rcvbuf = 1
net.ipv4.tcp_window_scaling = 1
net.ipv4.tcp_adv_win_scale = 1
net.ipv4.tcp_mtu_probing = 1
net.ipv4.tcp_ecn = 0
net.ipv4.tcp_slow_start_after_idle = 0
EOF_E202_LEGACY_OLD_MODEB
            _e202_legacy_old_tail "$reordering"
            ;;
        *) return 1 ;;
    esac
}

_e202_legacy_profile_id() {
    local source="$1" label="$2" id reordering
    case "$label" in
        196) reordering='500 300' ;;
        198) reordering='300' ;;
        *) return 1 ;;
    esac
    for id in mode1 mode2 mode3; do
        cmp -s "$source" <(_e202_legacy_old_profile "$id" 300) && {
            printf '%s\n' "$id"
            return 0
        }
    done
    for reordering in $reordering; do
        for id in mode1f mode2f mode3f modeb; do
            cmp -s "$source" <(_e202_legacy_old_profile "$id" "$reordering") && {
                printf '%s\n' "$id"
                return 0
            }
        done
    done
    return 1
}

# E200 owned either 14 base keys or 23 extended keys. Convert a SHA-sealed
# extended file by removing the retired tcp_tw_reuse_delay assignment and
# appending the three newly explicit recovery controls. The original 22 values
# are preserved byte-for-byte; a former custom/B1 profile therefore stays a
# custom-f profile instead of being silently remapped to a different preset.
_e202_convert_e200_profile() {
    local source="$1" out="$2" lines assignments delay_count delay
    test -f "$source" || return 1
    lines=$(awk 'NF{n++}END{print n+0}' "$source")
    assignments=$(_e202_small_bbr_assignment_count "$source")
    case "$lines:$assignments" in
        14:14)
            cp -f -- "$source" "$out" || return 1
            ;;
        23:23)
            delay_count=$(awk -F= '
              {
                k=$1
                gsub(/[[:space:]]/,"",k)
                if (k=="net.ipv4.tcp_tw_reuse_delay") n++
              }
              END {print n+0}
            ' "$source")
            test "$delay_count" -eq 1 || return 1
            delay=$(_e202_profile_value "$source" net.ipv4.tcp_tw_reuse_delay)
            [[ "$delay" =~ ^[0-9]+$ ]] \
              && test "$delay" -ge 1000 && test "$delay" -le 600000 || return 1
            awk -F= '
              {
                k=$1
                gsub(/[[:space:]]/,"",k)
                if (k!="net.ipv4.tcp_tw_reuse_delay") print
              }
            ' "$source" >"$out" || return 1
            cat >>"$out" <<'EOF_E202_E200_RECOVERY_TAIL'
net.ipv4.tcp_sack = 1
net.ipv4.tcp_dsack = 1
net.ipv4.tcp_recovery = 1
EOF_E202_E200_RECOVERY_TAIL
            ;;
        *) return 1 ;;
    esac
    _e202_small_bbr_validate_file "$out"
}

_e202_legacy_e200_validate_file() {
    local source="$1" tmp rc=0
    tmp=$(mktemp /tmp/xray-e202-e200-profile.XXXXXX) || return 1
    chmod 0600 "$tmp" 2>/dev/null || true
    _e202_convert_e200_profile "$source" "$tmp" || rc=1
    rm -f -- "$tmp"
    return "$rc"
}

_e202_prepare_legacy_profile() {
    local label="$1" source="$2" out="$3" id new_id
    if test "$label" = 200; then
        _e202_convert_e200_profile "$source" "$out" || {
            error 'E200活动档不是可验证的14/23项档位；拒绝删除参数或退出旧档。'
            return 1
        }
        id=$(_e202_small_bbr_profile_id_file "$out") || return 1
        info "已密封E200活动档：移除tcp_tw_reuse_delay并显式加入SACK/DSACK/RACK；将迁移为E202的${id}（14/25项）。"
        return 0
    fi
    id=$(_e202_legacy_profile_id "$source" "$label") || {
        error "E${label}活动档不是可证明的内置14/21项预设；为避免猜测迁移，热更新尚未退出旧档。"
        error "请先用原版E${label}切换到内置模式1/2/3/1F/2F/3F/B，或先退出旧小BBR。"
        return 1
    }
    new_id="$id"
    if test "$id" = modeb; then
        # Do not map the legacy B preset to the materially different new B1.
        # Preserve its legacy base and attach only the new documented F tail.
        _e202_legacy_old_profile modeb 300 | sed -n '1,14p' >"$out" || return 1
        _e202_small_bbr_f_tail >>"$out" || return 1
        new_id=custom-f
    else
        "_e202_small_bbr_${new_id}" >"$out" || return 1
    fi
    _e202_small_bbr_validate_file "$out" || return 1
    info "已验证E${label}活动内置档${id}，将迁移为E202的${new_id}（14/25项新规格）。"
}

_e202_small_bbr_assignment_count() {
    local file="$1"
    awk -F= '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{n++}END{print n+0}' "$file"
}

# A legacy layer marked active is migrated from its sealed active config, not
# from a separately saved (possibly pending and never applied) menu choice.
_e202_legacy_active_config_valid() {
    local label="$1" state="$2" conf="$3" stored_sha actual_sha
    local stored_assignments actual_assignments
    case "$label" in
        196|198)
            _e202_legacy_profile_id "$conf" "$label" >/dev/null || {
                error "E${label}活动配置不是可证明的内置14/21项档位：$conf"
                return 1
            }
            ;;
        200)
            _e202_legacy_e200_validate_file "$conf" || {
                error "E200活动小BBR持久配置缺失或不是可转换的14/23项档位：$conf"
                return 1
            }
            ;;
        *)
            _e202_small_bbr_validate_file "$conf" || {
                error "E${label}活动小BBR持久配置缺失或格式无效：$conf"
                return 1
            }
            ;;
    esac
    stored_sha=$(sed -n 's/^config_sha256=//p' "$state" 2>/dev/null | tail -n1)
    actual_sha=$(sha256sum "$conf" 2>/dev/null | awk '{print $1}')
    [[ "$stored_sha" =~ ^[0-9a-f]{64}$ ]] \
      && test "$stored_sha" = "$actual_sha" || {
        error "E${label}活动配置哈希与状态不一致；拒绝猜测迁移。"
        return 1
    }
    stored_assignments=$(sed -n 's/^persistent_assignments=//p' \
        "$state" 2>/dev/null | tail -n1)
    actual_assignments=$(_e202_small_bbr_assignment_count "$conf")
    [[ "$stored_assignments" =~ ^[0-9]+$ ]] \
      && test "$stored_assignments" -eq "$actual_assignments" || {
        error "E${label}活动配置项数与状态不一致；拒绝猜测迁移。"
        return 1
    }
}

_e202_capture_active_config() {
    local label="$1" state="$2" conf="$3" out="$4"
    _e202_legacy_active_config_valid "$label" "$state" "$conf" || return 1
    cp -f -- "$conf" "$out" || return 1
    case "$label" in
        196|198) _e202_legacy_profile_id "$out" "$label" >/dev/null ;;
        200) _e202_legacy_e200_validate_file "$out" ;;
        *) _e202_small_bbr_validate_file "$out" ;;
    esac
}

_e202_small_bbr_desired() {
    if _e202_small_bbr_validate_file "$E202_SMALL_PROFILE"; then
        cat -- "$E202_SMALL_PROFILE"
    else
        _e202_small_bbr_default
    fi
}

# Compatibility name used by the inherited audit/self-test layer.
_e202_small_bbr_expected() {
    _e202_small_bbr_desired
}

_e202_small_bbr_active() {
    test -s "$E202_SMALL_STATE" \
      && test "$(sed -n 's/^active=//p' "$E202_SMALL_STATE" 2>/dev/null | tail -n1)" = 1 \
      && test "$(sed -n 's/^profile=//p' "$E202_SMALL_STATE" 2>/dev/null | tail -n1)" = small-bbr-multi
}

_e202_unrecognized_current_active() {
    local active_flag unit_state unit_enabled
    _e202_small_bbr_active && return 1
    active_flag=$(sed -n 's/^active=//p' "$E202_SMALL_STATE" 2>/dev/null | tail -n1)
    unit_state=$(systemctl is-active "$E202_SMALL_UNIT" 2>/dev/null || true)
    unit_enabled=$(systemctl is-enabled "$E202_SMALL_UNIT" 2>/dev/null || true)
    if test "$active_flag" = 1; then
        error "E202小BBR状态标记active，但状态格式/档位标识损坏：$E202_SMALL_STATE"
        error '拒绝覆盖其唯一恢复快照；请先依据状态文件和CRITICAL_RECOVERY_REQUIRED.env修复。'
        return 0
    fi
    case "$unit_state" in
        active|activating|reloading)
            error "E202小BBR服务仍在运行，但活动状态无法验证：$E202_SMALL_UNIT"
            return 0
            ;;
    esac
    case "$unit_enabled" in
        enabled|enabled-runtime|linked|linked-runtime|alias)
            error "E202小BBR服务仍设为开机运行，但活动状态无法验证：$E202_SMALL_UNIT"
            error '拒绝把异常状态当作首次启用，否则退出快照会指向错误基线。'
            return 0
            ;;
    esac
    return 1
}

_e202_current_owner_claimed() {
    local active_flag unit_state unit_enabled
    _e202_small_bbr_active && return 0
    active_flag=$(sed -n 's/^active=//p' "$E202_SMALL_STATE" 2>/dev/null | tail -n1)
    test "$active_flag" = 1 && return 0
    unit_state=$(systemctl is-active "$E202_SMALL_UNIT" 2>/dev/null || true)
    case "$unit_state" in active|activating|reloading) return 0 ;; esac
    unit_enabled=$(systemctl is-enabled "$E202_SMALL_UNIT" 2>/dev/null || true)
    case "$unit_enabled" in
        enabled|enabled-runtime|linked|linked-runtime|alias) return 0 ;;
    esac
    return 1
}

_e202_legacy_e190_active() {
    test -s "$E202_LEGACY_E190_STATE" \
      && test "$(sed -n 's/^active=//p' "$E202_LEGACY_E190_STATE" 2>/dev/null | tail -n1)" = 1 \
      && test "$(sed -n 's/^profile=//p' "$E202_LEGACY_E190_STATE" 2>/dev/null | tail -n1)" = small-bbr-6
}

_e202_legacy_e192_active() {
    test -s "$E202_LEGACY_E192_STATE" \
      && test "$(sed -n 's/^active=//p' "$E202_LEGACY_E192_STATE" 2>/dev/null | tail -n1)" = 1 \
      && test "$(sed -n 's/^profile=//p' "$E202_LEGACY_E192_STATE" 2>/dev/null | tail -n1)" = small-bbr-13
}

_e202_legacy_e194_active() {
    test -s "$E202_LEGACY_E194_STATE" \
      && test "$(sed -n 's/^active=//p' "$E202_LEGACY_E194_STATE" 2>/dev/null | tail -n1)" = 1 \
      && test "$(sed -n 's/^profile=//p' "$E202_LEGACY_E194_STATE" 2>/dev/null | tail -n1)" = small-bbr-14
}

_e202_legacy_e196_active() {
    test -s "$E202_LEGACY_E196_STATE" \
      && test "$(sed -n 's/^active=//p' "$E202_LEGACY_E196_STATE" 2>/dev/null | tail -n1)" = 1 \
      && test "$(sed -n 's/^profile=//p' "$E202_LEGACY_E196_STATE" 2>/dev/null | tail -n1)" = small-bbr-multi
}

_e202_legacy_e198_active() {
    test -s "$E202_LEGACY_E198_STATE" \
      && test "$(sed -n 's/^active=//p' "$E202_LEGACY_E198_STATE" 2>/dev/null | tail -n1)" = 1 \
      && test "$(sed -n 's/^profile=//p' "$E202_LEGACY_E198_STATE" 2>/dev/null | tail -n1)" = small-bbr-multi
}

_e202_legacy_e200_active() {
    test -s "$E202_LEGACY_E200_STATE" \
      && test "$(sed -n 's/^active=//p' "$E202_LEGACY_E200_STATE" 2>/dev/null | tail -n1)" = 1 \
      && test "$(sed -n 's/^profile=//p' "$E202_LEGACY_E200_STATE" 2>/dev/null | tail -n1)" = small-bbr-multi
}

# Never "clean up" a legacy layer merely because its state format is not
# recognized. An active unit or active=1 with an unexpected profile may still
# own the current runtime and its private restore snapshot. Only that original
# release is allowed to unwind it.
_e202_unrecognized_legacy_active() {
    local label state unit fn active_flag unit_state unit_enabled row
    local -a rows=(
        "190|$E202_LEGACY_E190_STATE|$E202_LEGACY_E190_UNIT|_e202_legacy_e190_active"
        "192|$E202_LEGACY_E192_STATE|$E202_LEGACY_E192_UNIT|_e202_legacy_e192_active"
        "194|$E202_LEGACY_E194_STATE|$E202_LEGACY_E194_UNIT|_e202_legacy_e194_active"
        "196|$E202_LEGACY_E196_STATE|$E202_LEGACY_E196_UNIT|_e202_legacy_e196_active"
        "198|$E202_LEGACY_E198_STATE|$E202_LEGACY_E198_UNIT|_e202_legacy_e198_active"
        "200|$E202_LEGACY_E200_STATE|$E202_LEGACY_E200_UNIT|_e202_legacy_e200_active"
    )
    for row in "${rows[@]}"; do
        IFS='|' read -r label state unit fn <<<"$row"
        "$fn" && continue
        active_flag=$(sed -n 's/^active=//p' "$state" 2>/dev/null | tail -n1)
        unit_state=$(systemctl is-active "$unit" 2>/dev/null || true)
        unit_enabled=$(systemctl is-enabled "$unit" 2>/dev/null || true)
        if test "$active_flag" = 1; then
            error "E${label}旧小BBR状态标记active，但档位格式无法识别：$state"
            error "必须使用原版ex199e${label}.sh检查/退出，E202拒绝直接删除其恢复依据。"
            return 0
        fi
        case "$unit_state" in
            active|activating|reloading)
                error "E${label}旧小BBR服务仍在运行，但状态不完整：$unit"
                error "必须使用原版ex199e${label}.sh检查/退出，E202拒绝直接停止并覆盖。"
                return 0
                ;;
        esac
        case "$unit_enabled" in
            enabled|enabled-runtime|linked|linked-runtime|alias)
                error "E${label}旧小BBR服务仍设为开机运行，但状态未证明其可安全接管：$unit"
                error "必须使用原版ex199e${label}.sh退出；E202拒绝留下重启后复活的旧网络所有者。"
                return 0
                ;;
        esac
    done
    return 1
}

_e202_recognized_legacy_active() {
    local label fn row
    local -a rows=(
        "190|_e202_legacy_e190_active"
        "192|_e202_legacy_e192_active"
        "194|_e202_legacy_e194_active"
        "196|_e202_legacy_e196_active"
        "198|_e202_legacy_e198_active"
        "200|_e202_legacy_e200_active"
    )
    for row in "${rows[@]}"; do
        IFS='|' read -r label fn <<<"$row"
        if "$fn"; then
            error "E${label}旧小BBR仍是活动所有者；拒绝由E202清理其文件或服务。"
            error "请先使用原版ex199e${label}.sh执行 --small-bbr-disable。"
            return 0
        fi
    done
    return 1
}

_e202_full_network_owner_present() {
    local p unit state
    for p in "$E159_EFFECTIVE_CONF" "$E159_NETWORK_STATE" "$E159_NETWORK_SCRIPT" \
        "$E159_NETWORK_SERVICE" "$E159_NETWORK_TIMER" \
        "$E159_LEGACY_E156_EFFECTIVE_CONF" "$E159_LEGACY_E156_SERVICE" \
        "$E159_LEGACY_E156_TIMER" "$E159_LEGACY_E154_EFFECTIVE_CONF" \
        "$E159_LEGACY_E154_SERVICE" "$E159_LEGACY_E154_TIMER" \
        /etc/sysctl.d/99-xray-e125-accel.conf \
        /etc/sysctl.d/99-xray-e126-accel.conf \
        /etc/sysctl.d/99-xray-e135-network.conf \
        /etc/sysctl.d/99-xray-e136-network.conf \
        /etc/sysctl.d/99-xray-e138-network.conf \
        /etc/sysctl.d/99-xray-e139-network.conf \
        /etc/sysctl.d/99-xray-e142-network.conf \
        /etc/sysctl.d/99-xray-e143-network.conf \
        /etc/sysctl.d/99-xray-e145-network.conf \
        "$E202_LEGACY_E190_CONF" "$E202_LEGACY_E190_SERVICE" \
        "$E202_LEGACY_E192_CONF" "$E202_LEGACY_E192_SERVICE" \
        "$E202_LEGACY_E194_CONF" "$E202_LEGACY_E194_SERVICE" \
        "$E202_LEGACY_E196_CONF" "$E202_LEGACY_E196_SERVICE" \
        "$E202_LEGACY_E198_CONF" "$E202_LEGACY_E198_SERVICE" \
        "$E202_LEGACY_E200_CONF" "$E202_LEGACY_E200_SERVICE"; do
        test -e "$p" && return 0
    done
    for unit in xray-network-e159.service xray-network-e159.timer \
        xray-network-e156.service xray-network-e156.timer \
        xray-network-e154.service xray-network-e154.timer \
        "$E202_LEGACY_E190_UNIT" "$E202_LEGACY_E192_UNIT" \
        "$E202_LEGACY_E194_UNIT" "$E202_LEGACY_E196_UNIT" \
        "$E202_LEGACY_E198_UNIT" "$E202_LEGACY_E200_UNIT"; do
        state=$(systemctl is-enabled "$unit" 2>/dev/null || true)
        case "$state" in enabled|enabled-runtime|linked|linked-runtime|alias) return 0 ;; esac
        state=$(systemctl is-active "$unit" 2>/dev/null || true)
        case "$state" in active|activating|reloading) return 0 ;; esac
    done
    return 1
}

_e202_small_bbr_kernel_ready() {
    local key path qdisc cc
    qdisc=$(_e202_profile_value "$E202_SMALL_CONF" net.core.default_qdisc)
    cc=$(_e202_profile_value "$E202_SMALL_CONF" net.ipv4.tcp_congestion_control)
    test "$qdisc" = fq && test "$cc" = bbr || {
        error '小BBR结构锚点必须保持 fq + bbr。'
        return 1
    }
    modprobe sch_fq >/dev/null 2>&1 || true
    modprobe tcp_bbr >/dev/null 2>&1 || true
    grep -qw bbr < <(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null) || {
        error '当前内核没有可用的BBR拥塞控制器；未写入小BBR配置。'
        return 1
    }
    while IFS= read -r key; do
        path=$(_e159_proc_path "$key")
        test -e "$path" && test -w "$path" || {
            error "内核参数不存在或不可写：$key"
            return 1
        }
    done < <(_e202_small_bbr_file_keys "$E202_SMALL_CONF")
}

_e202_small_bbr_verify_runtime() {
    local source="${1:-$E202_SMALL_CONF}" key value actual failed=0
    _e202_small_bbr_validate_file "$source" || return 1
    while IFS='=' read -r key value; do
        key=$(_e159_norm "$key")
        value=$(_e159_norm "$value")
        actual=$(sysctl -n "$key" 2>/dev/null || true)
        if ! _e159_value_equal "$key" "$value" "$actual"; then
            error "小BBR读回不一致：$key 期望=$value 实际=${actual:-unreadable}"
            failed=1
        fi
    done <"$source"
    test "$failed" -eq 0
}

_e202_small_bbr_apply_runtime() {
    local key value
    _e202_small_bbr_validate_file "$E202_SMALL_CONF" || {
        error "小BBR持久文件不是合法的14/25/26行档位：$E202_SMALL_CONF"
        return 1
    }
    _e202_small_bbr_kernel_ready || return 1
    # max先于default写入，避免低默认上限主机在中途拒绝自定义默认值；
    # 文件保持固定14/25/26行结构，运行事务按依赖顺序提交。
    for key in \
        net.core.default_qdisc net.ipv4.tcp_congestion_control \
        net.core.rmem_max net.core.wmem_max \
        net.core.rmem_default net.core.wmem_default \
        net.ipv4.tcp_rmem net.ipv4.tcp_wmem \
        net.ipv4.tcp_moderate_rcvbuf net.ipv4.tcp_window_scaling \
        net.ipv4.tcp_adv_win_scale net.ipv4.tcp_mtu_probing \
        net.ipv4.tcp_ecn net.ipv4.tcp_slow_start_after_idle \
        net.ipv4.tcp_max_reordering net.ipv4.tcp_fastopen \
        net.ipv4.tcp_timestamps \
        net.ipv4.tcp_tw_reuse net.ipv4.tcp_fin_timeout \
        net.ipv4.tcp_max_syn_backlog net.core.netdev_max_backlog \
        net.core.somaxconn net.ipv4.tcp_sack net.ipv4.tcp_dsack \
        net.ipv4.tcp_recovery net.ipv4.tcp_max_tw_buckets; do
        value=$(_e202_profile_value "$E202_SMALL_CONF" "$key")
        test -n "$value" || continue
        sysctl -w "$key=$value" >/dev/null 2>&1 || {
            error "小BBR写入失败：$key"
            return 1
        }
    done
    _e202_small_bbr_verify_runtime "$E202_SMALL_CONF"
}

_e202_small_bbr_restore_unowned_runtime() {
    local snapshot="$1" target="$2" key expected actual path failed=0
    _e202_snapshot_valid "$snapshot" || return 1
    _e202_small_bbr_validate_file "$target" || return 1
    while IFS= read -r key; do
        grep -Fqx "$key" < <(_e202_small_bbr_file_keys "$target") && continue
        path=$(_e159_proc_path "$key")
        test -e "$path" && test -w "$path" || continue
        expected=$(awk -F'|' -v wanted="$key" '$1==wanted {
            print substr($0,index($0,"|")+1)
            exit
        }' "$snapshot/runtime-sysctl.env")
        test -n "$expected" || {
            error "恢复非目标参数时快照缺值：$key"
            failed=1
            continue
        }
        sysctl -w "$key=$expected" >/dev/null 2>&1 || {
            error "恢复非目标参数失败：$key"
            failed=1
            continue
        }
        actual=$(sysctl -n "$key" 2>/dev/null || true)
        _e159_value_equal "$key" "$expected" "$actual" || {
            error "恢复非目标参数读回不一致：$key 期望=$expected 实际=${actual:-unreadable}"
            failed=1
        }
    done < <(_e202_small_bbr_all_keys)
    test "$failed" -eq 0
}

_e202_small_bbr_unit_candidate() {
    local out="$1"
    cat >"$out" <<EOF_E202_SMALL_UNIT
[Unit]
Description=V199e202 exact selected small BBR profile boot verification
After=systemd-sysctl.service
Before=xray.service
ConditionPathExists=$E202_SMALL_STATE

[Service]
Type=oneshot
ExecStart=$E202_SELF_PATH --small-bbr-reconcile
TimeoutStartSec=60

[Install]
WantedBy=multi-user.target
EOF_E202_SMALL_UNIT
}

_e202_small_bbr_write_assets() {
    local conf_tmp unit_tmp
    if test -e "$E202_SMALL_PROFILE" \
      && ! _e202_small_bbr_validate_file "$E202_SMALL_PROFILE"; then
        error "保存的小BBR档位无效，拒绝静默回落默认值：$E202_SMALL_PROFILE"
        return 1
    fi
    conf_tmp=$(_e118_mktemp e202-small-bbr.conf) || return 1
    unit_tmp=$(_e118_mktemp e202-small-bbr.service) || return 1
    _e202_small_bbr_desired >"$conf_tmp" || return 1
    _e202_small_bbr_unit_candidate "$unit_tmp" || return 1
    _e202_small_bbr_validate_file "$conf_tmp" || return 1
    grep -Fqx "ExecStart=$E202_SELF_PATH --small-bbr-reconcile" "$unit_tmp" || return 1
    _e121_atomic_install "$conf_tmp" "$E202_SMALL_CONF" 0644 || return 1
    _e121_atomic_install "$unit_tmp" "$E202_SMALL_SERVICE" 0644 || return 1
    _e202_small_bbr_validate_file "$E202_SMALL_CONF" || return 1
}

_e202_small_bbr_write_state() {
    local snapshot="$1" tmp profile_id assignments extensions
    _e202_snapshot_valid "$snapshot" || return 1
    profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_CONF") || return 1
    assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF")
    extensions=$((assignments-14))
    tmp="$E202_SMALL_STATE.tmp.$$"
    {
        echo 'version=199e202'
        echo 'active=1'
        echo 'profile=small-bbr-multi'
        echo "profile_id=$profile_id"
        echo "profile_kind=$profile_id"
        echo "persistent_assignments=$assignments"
        echo "extension_assignments=$extensions"
        echo 'extra_assignments=0'
        echo "restore_snapshot=$snapshot"
        echo "config_sha256=$(sha256sum "$E202_SMALL_CONF" | awk '{print $1}')"
        echo "applied=$(date -Is 2>/dev/null || date)"
    } >"$tmp" || return 1
    chmod 0600 "$tmp" || return 1
    mv -f -- "$tmp" "$E202_SMALL_STATE" || return 1
}

_e202_snapshot_valid() {
    local snapshot="$1" real root
    real=$(readlink -f -- "$snapshot" 2>/dev/null || true)
    root=$(readlink -f -- "$E202_TX_ROOT" 2>/dev/null || true)
    test -n "$real" && test -n "$root" || return 1
    case "$real" in "$root"/*/system) ;; *) return 1 ;; esac
    test -s "$real/control.sha256" \
      && (cd "$real" && sha256sum -c control.sha256 >/dev/null 2>&1) || return 1
    if test -s "$real/files.tar"; then
        test -s "$real/archive.sha256" \
          && (cd "$real" && sha256sum -c archive.sha256 >/dev/null 2>&1) || return 1
    fi
    if test -e "$real/e159-services.env" || test -e "$real/e159-services.sha256"; then
        test -s "$real/e159-services.env" && test -s "$real/e159-services.sha256" \
          && (cd "$real" && sha256sum -c e159-services.sha256 >/dev/null 2>&1) || return 1
    fi
    if test -e "$real/e202-services.env" || test -e "$real/e202-services.sha256"; then
        test -s "$real/e202-services.env" && test -s "$real/e202-services.sha256" \
          && (cd "$real" && sha256sum -c e202-services.sha256 >/dev/null 2>&1) || return 1
    fi
    if test -e "$real/e190-services.env" || test -e "$real/e190-services.sha256"; then
        test -s "$real/e190-services.env" && test -s "$real/e190-services.sha256" \
          && (cd "$real" && sha256sum -c e190-services.sha256 >/dev/null 2>&1) || return 1
    fi
    if test -e "$real/e192-services.env" || test -e "$real/e192-services.sha256"; then
        test -s "$real/e192-services.env" && test -s "$real/e192-services.sha256" \
          && (cd "$real" && sha256sum -c e192-services.sha256 >/dev/null 2>&1) || return 1
    fi
    if test -e "$real/e194-services.env" || test -e "$real/e194-services.sha256"; then
        test -s "$real/e194-services.env" && test -s "$real/e194-services.sha256" \
          && (cd "$real" && sha256sum -c e194-services.sha256 >/dev/null 2>&1) || return 1
    fi
    if test -e "$real/e196-services.env" || test -e "$real/e196-services.sha256"; then
        test -s "$real/e196-services.env" && test -s "$real/e196-services.sha256" \
          && (cd "$real" && sha256sum -c e196-services.sha256 >/dev/null 2>&1) || return 1
    fi
    if test -e "$real/e198-services.env" || test -e "$real/e198-services.sha256"; then
        test -s "$real/e198-services.env" && test -s "$real/e198-services.sha256" \
          && (cd "$real" && sha256sum -c e198-services.sha256 >/dev/null 2>&1) || return 1
    fi
    if test -e "$real/e200-services.env" || test -e "$real/e200-services.sha256"; then
        test -s "$real/e200-services.env" && test -s "$real/e200-services.sha256" \
          && (cd "$real" && sha256sum -c e200-services.sha256 >/dev/null 2>&1) || return 1
    fi
}

_e202_snapshot_runtime_verify() {
    local snapshot="$1" key expected actual failed=0
    test -s "$snapshot/runtime-sysctl.env" || return 1
    while IFS= read -r key; do
        test -e "$(_e159_proc_path "$key")" || continue
        expected=$(awk -F'|' -v wanted="$key" '$1==wanted {
            print substr($0,index($0,"|")+1)
            exit
        }' "$snapshot/runtime-sysctl.env")
        test -n "$expected" || {
            error "小BBR回滚快照缺少运行值：$key"
            failed=1
            continue
        }
        actual=$(sysctl -n "$key" 2>/dev/null || true)
        _e159_value_equal "$key" "$expected" "$actual" || failed=1
    done < <(_e202_small_bbr_all_keys)
    test "$failed" -eq 0
}

_e202_legacy_e190_snapshot_valid() {
    local snapshot="$1" real root
    real=$(readlink -f -- "$snapshot" 2>/dev/null || true)
    root=$(readlink -f -- "$E202_LEGACY_E190_TX_ROOT" 2>/dev/null || true)
    test -n "$real" && test -n "$root" || return 1
    case "$real" in "$root"/*/system) ;; *) return 1 ;; esac
    test -s "$real/control.sha256" \
      && (cd "$real" && sha256sum -c control.sha256 >/dev/null 2>&1) || return 1
    if test -s "$real/files.tar"; then
        test -s "$real/archive.sha256" \
          && (cd "$real" && sha256sum -c archive.sha256 >/dev/null 2>&1) || return 1
    fi
    if test -e "$real/e159-services.env" || test -e "$real/e159-services.sha256"; then
        test -s "$real/e159-services.env" && test -s "$real/e159-services.sha256" \
          && (cd "$real" && sha256sum -c e159-services.sha256 >/dev/null 2>&1) || return 1
    fi
    if test -e "$real/e190-services.env" || test -e "$real/e190-services.sha256"; then
        test -s "$real/e190-services.env" && test -s "$real/e190-services.sha256" \
          && (cd "$real" && sha256sum -c e190-services.sha256 >/dev/null 2>&1) || return 1
    fi
}

