# Full snapshots also preserve the small-BBR unit's enable/active state.
if declare -F _e140_system_snapshot >/dev/null 2>&1; then
    eval "$(declare -f _e140_system_snapshot | sed \
        '1s/_e140_system_snapshot/_e202_system_snapshot_base/')"
fi
_e202_snapshot_capture_small_runtime() {
    local b="$1" key value tmp
    test -s "$b/runtime-sysctl.env" || return 1
    tmp="$b/runtime-sysctl.env.e202.$$"
    cp -f -- "$b/runtime-sysctl.env" "$tmp" || return 1
    while IFS= read -r key; do
        grep -Fq "${key}|" "$tmp" && continue
        value=$(sysctl -n "$key" 2>/dev/null || true)
        test -n "$value" || continue
        printf '%s|%s\n' "$key" "$value" >>"$tmp" || {
            rm -f -- "$tmp"
            return 1
        }
    done < <(_e202_small_bbr_all_keys)
    awk -F'|' 'NF&&!seen[$1]++' "$tmp" >"$b/runtime-sysctl.env" || {
        rm -f -- "$tmp"
        return 1
    }
    rm -f -- "$tmp"
    (cd "$b" && sha256sum present.list absent.list runtime-sysctl.env \
        services.env >control.sha256) || return 1
}
_e140_system_snapshot() {
    local b="$1"
    _e202_system_snapshot_base "$b" || return 1
    _e202_snapshot_capture_small_runtime "$b" || return 1
    _e159_snapshot_service "$E202_SMALL_UNIT" >"$b/e202-services.env" || return 1
    (cd "$b" && sha256sum e202-services.env >e202-services.sha256) || return 1
    _e159_snapshot_service "$E202_LEGACY_E190_UNIT" >"$b/e190-services.env" || return 1
    (cd "$b" && sha256sum e190-services.env >e190-services.sha256) || return 1
    _e159_snapshot_service "$E202_LEGACY_E192_UNIT" >"$b/e192-services.env" || return 1
    (cd "$b" && sha256sum e192-services.env >e192-services.sha256) || return 1
    _e159_snapshot_service "$E202_LEGACY_E194_UNIT" >"$b/e194-services.env" || return 1
    (cd "$b" && sha256sum e194-services.env >e194-services.sha256) || return 1
    _e159_snapshot_service "$E202_LEGACY_E196_UNIT" >"$b/e196-services.env" || return 1
    (cd "$b" && sha256sum e196-services.env >e196-services.sha256) || return 1
    _e159_snapshot_service "$E202_LEGACY_E198_UNIT" >"$b/e198-services.env" || return 1
    (cd "$b" && sha256sum e198-services.env >e198-services.sha256) || return 1
    _e159_snapshot_service "$E202_LEGACY_E200_UNIT" >"$b/e200-services.env" || return 1
    (cd "$b" && sha256sum e200-services.env >e200-services.sha256) || return 1
}

if declare -F _e140_system_restore >/dev/null 2>&1; then
    eval "$(declare -f _e140_system_restore | sed \
        '1s/_e140_system_restore/_e202_system_restore_base/')"
fi
_e140_system_restore() {
    local b="$1" unit enabled active rc=0
    if test -e "$b/e202-services.env" || test -e "$b/e202-services.sha256"; then
        test -s "$b/e202-services.env" && test -s "$b/e202-services.sha256" \
          && (cd "$b" && sha256sum -c e202-services.sha256 >/dev/null 2>&1) \
          || { error "E202服务状态快照损坏：$b"; return 1; }
    fi
    if test -e "$b/e190-services.env" || test -e "$b/e190-services.sha256"; then
        test -s "$b/e190-services.env" && test -s "$b/e190-services.sha256" \
          && (cd "$b" && sha256sum -c e190-services.sha256 >/dev/null 2>&1) \
          || { error "E190兼容服务状态快照损坏：$b"; return 1; }
    fi
    if test -e "$b/e192-services.env" || test -e "$b/e192-services.sha256"; then
        test -s "$b/e192-services.env" && test -s "$b/e192-services.sha256" \
          && (cd "$b" && sha256sum -c e192-services.sha256 >/dev/null 2>&1) \
          || { error "E192兼容服务状态快照损坏：$b"; return 1; }
    fi
    if test -e "$b/e194-services.env" || test -e "$b/e194-services.sha256"; then
        test -s "$b/e194-services.env" && test -s "$b/e194-services.sha256" \
          && (cd "$b" && sha256sum -c e194-services.sha256 >/dev/null 2>&1) \
          || { error "E194兼容服务状态快照损坏：$b"; return 1; }
    fi
    if test -e "$b/e196-services.env" || test -e "$b/e196-services.sha256"; then
        test -s "$b/e196-services.env" && test -s "$b/e196-services.sha256" \
          && (cd "$b" && sha256sum -c e196-services.sha256 >/dev/null 2>&1) \
          || { error "E196兼容服务状态快照损坏：$b"; return 1; }
    fi
    if test -e "$b/e198-services.env" || test -e "$b/e198-services.sha256"; then
        test -s "$b/e198-services.env" && test -s "$b/e198-services.sha256" \
          && (cd "$b" && sha256sum -c e198-services.sha256 >/dev/null 2>&1) \
          || { error "E198兼容服务状态快照损坏：$b"; return 1; }
    fi
    if test -e "$b/e200-services.env" || test -e "$b/e200-services.sha256"; then
        test -s "$b/e200-services.env" && test -s "$b/e200-services.sha256" \
          && (cd "$b" && sha256sum -c e200-services.sha256 >/dev/null 2>&1) \
          || { error "E200兼容服务状态快照损坏：$b"; return 1; }
    fi
    _e202_system_restore_base "$b" || rc=1
    if test -s "$b/e202-services.env"; then
        while IFS='|' read -r unit enabled active; do
            test -n "$unit" || continue
            _e159_restore_service "$unit" "$enabled" "$active" || rc=1
        done <"$b/e202-services.env"
    fi
    if test -s "$b/e190-services.env"; then
        while IFS='|' read -r unit enabled active; do
            test -n "$unit" || continue
            _e159_restore_service "$unit" "$enabled" "$active" || rc=1
        done <"$b/e190-services.env"
    fi
    if test -s "$b/e192-services.env"; then
        while IFS='|' read -r unit enabled active; do
            test -n "$unit" || continue
            _e159_restore_service "$unit" "$enabled" "$active" || rc=1
        done <"$b/e192-services.env"
    fi
    if test -s "$b/e194-services.env"; then
        while IFS='|' read -r unit enabled active; do
            test -n "$unit" || continue
            _e159_restore_service "$unit" "$enabled" "$active" || rc=1
        done <"$b/e194-services.env"
    fi
    if test -s "$b/e196-services.env"; then
        while IFS='|' read -r unit enabled active; do
            test -n "$unit" || continue
            _e159_restore_service "$unit" "$enabled" "$active" || rc=1
        done <"$b/e196-services.env"
    fi
    if test -s "$b/e198-services.env"; then
        while IFS='|' read -r unit enabled active; do
            test -n "$unit" || continue
            _e159_restore_service "$unit" "$enabled" "$active" || rc=1
        done <"$b/e198-services.env"
    fi
    if test -s "$b/e200-services.env"; then
        while IFS='|' read -r unit enabled active; do
            test -n "$unit" || continue
            _e159_restore_service "$unit" "$enabled" "$active" || rc=1
        done <"$b/e200-services.env"
    fi
    return "$rc"
}

_e202_legacy_e190_runtime_verify() {
    local snapshot="$1" key expected actual failed=0
    test -s "$snapshot/runtime-sysctl.env" || return 1
    for key in net.core.default_qdisc net.ipv4.tcp_congestion_control \
        net.core.rmem_max net.core.wmem_max net.ipv4.tcp_rmem net.ipv4.tcp_wmem; do
        expected=$(awk -F'|' -v wanted="$key" '$1==wanted {
            print substr($0,index($0,"|")+1)
            exit
        }' "$snapshot/runtime-sysctl.env")
        test -n "$expected" || continue
        actual=$(sysctl -n "$key" 2>/dev/null || true)
        _e159_value_equal "$key" "$expected" "$actual" || failed=1
    done
    test "$failed" -eq 0
}

_e202_delegate_legacy_small_bbr_exit() {
    local version="$1" script="$2" active_fn="$3" unit="$4" reported state enabled
    local label="${version#199e}"
    "$active_fn" || return 0
    test -r "$script" || {
        error "检测到E${label}小BBR仍启用，但原版退出脚本缺失：$script"
        error "请恢复原版ex${version}.sh后执行：bash $script --small-bbr-disable"
        return 1
    }
    bash -n "$script" >/dev/null 2>&1 || {
        error "原版E${label}脚本语法检查失败，拒绝由新版本猜测旧快照。"
        return 1
    }
    reported=$(bash "$script" --version 2>/dev/null | tail -n1 || true)
    test "$reported" = "$version" || {
        error "旧脚本身份不符：期望=$version 实际=${reported:-unknown} 路径=$script"
        return 1
    }
    warn "检测到E${label}小BBR；按稳态迁移规则，先由原版E${label}自己退出旧档位。"
    bash "$script" --small-bbr-disable || {
        error "原版E${label}退出失败；热更新尚未开始。"
        error "请手动执行：bash $script --small-bbr-disable"
        return 1
    }
    "$active_fn" && {
        error "原版E${label}返回成功但状态仍标记active；停止热更新。"
        return 1
    }
    state=$(systemctl is-active "$unit" 2>/dev/null || true)
    case "$state" in active|activating|reloading)
        error "原版E${label}退出后旧服务仍在运行：$unit"
        return 1
        ;;
    esac
    enabled=$(systemctl is-enabled "$unit" 2>/dev/null || true)
    case "$enabled" in enabled|enabled-runtime|linked|linked-runtime|alias)
        error "原版E${label}退出后旧服务仍设为开机启动：$unit"
        error '拒绝继续，避免重启后旧网络所有者复活。'
        return 1
        ;;
    esac
    info "原版E${label}已退出旧小BBR并恢复其原始基线；现在才允许进入E202热更新。"
}

_e202_legacy_e190_disable() {
    _e202_delegate_legacy_small_bbr_exit \
        199e190 "$E202_LEGACY_E190_SELF_PATH" \
        _e202_legacy_e190_active "$E202_LEGACY_E190_UNIT"
}

_e202_legacy_e192_disable() {
    _e202_delegate_legacy_small_bbr_exit \
        199e192 "$E202_LEGACY_E192_SELF_PATH" \
        _e202_legacy_e192_active "$E202_LEGACY_E192_UNIT"
}

_e202_legacy_e194_disable() {
    _e202_delegate_legacy_small_bbr_exit \
        199e194 "$E202_LEGACY_E194_SELF_PATH" \
        _e202_legacy_e194_active "$E202_LEGACY_E194_UNIT"
}

_e202_legacy_e196_disable() {
    _e202_delegate_legacy_small_bbr_exit \
        199e196 "$E202_LEGACY_E196_SELF_PATH" \
        _e202_legacy_e196_active "$E202_LEGACY_E196_UNIT"
}

_e202_legacy_e198_disable() {
    _e202_delegate_legacy_small_bbr_exit \
        199e198 "$E202_LEGACY_E198_SELF_PATH" \
        _e202_legacy_e198_active "$E202_LEGACY_E198_UNIT"
}

_e202_legacy_e200_disable() {
    _e202_delegate_legacy_small_bbr_exit \
        199e200 "$E202_LEGACY_E200_SELF_PATH" \
        _e202_legacy_e200_active "$E202_LEGACY_E200_UNIT"
}

_e202_retire_confirmed_legacy_layers() {
    local f
    systemctl disable --now "$E202_LEGACY_E190_UNIT" \
        "$E202_LEGACY_E192_UNIT" "$E202_LEGACY_E194_UNIT" \
        "$E202_LEGACY_E196_UNIT" "$E202_LEGACY_E198_UNIT" \
        "$E202_LEGACY_E200_UNIT" \
        xray-network-e159.timer xray-network-e159.service \
        xray-network-e156.timer xray-network-e156.service \
        xray-network-e154.timer xray-network-e154.service \
        xray-network-e152.timer xray-network-e152.service \
        xray-hw-tweaks.service xray-accel-e125.service \
        xray-accel-e126.service >/dev/null 2>&1 || true
    for f in \
        "$E202_LEGACY_E190_CONF" "$E202_LEGACY_E190_STATE" \
        "$E202_LEGACY_E190_SERVICE" \
        "$E202_LEGACY_E192_CONF" "$E202_LEGACY_E192_STATE" \
        "$E202_LEGACY_E192_SERVICE" \
        "$E202_LEGACY_E194_CONF" "$E202_LEGACY_E194_STATE" \
        "$E202_LEGACY_E194_SERVICE" \
        "$E202_LEGACY_E196_CONF" "$E202_LEGACY_E196_STATE" \
        "$E202_LEGACY_E196_SERVICE" \
        "$E202_LEGACY_E198_CONF" "$E202_LEGACY_E198_STATE" \
        "$E202_LEGACY_E198_SERVICE" \
        "$E202_LEGACY_E200_CONF" "$E202_LEGACY_E200_STATE" \
        "$E202_LEGACY_E200_SERVICE" \
        "$E159_EFFECTIVE_CONF" "$E159_NETWORK_SCRIPT" \
        "$E159_NETWORK_SERVICE" "$E159_NETWORK_TIMER" \
        "$E159_LEGACY_E156_EFFECTIVE_CONF" "$E159_LEGACY_E156_SERVICE" \
        "$E159_LEGACY_E156_TIMER" "$E159_LEGACY_E154_EFFECTIVE_CONF" \
        "$E159_LEGACY_E154_SERVICE" "$E159_LEGACY_E154_TIMER" \
        /etc/sysctl.d/99-xray-e125-accel.conf \
        /etc/sysctl.d/99-xray-e126-accel.conf \
        /etc/sysctl.d/99-xray-e135-network.conf \
        /etc/sysctl.d/99-xray-e136-network.conf \
        /etc/sysctl.d/99-xray-e138-network.conf \
        /etc/sysctl.d/99-xray-e139-network.conf \
        /etc/sysctl.d/99-xray-e142-network.conf \
        /etc/sysctl.d/99-xray-e143-network.conf \
        /etc/sysctl.d/99-xray-e145-network.conf; do
        rm -f -- "$f" 2>/dev/null || return 1
    done
    for f in /etc/sysctl.d/99-network-optimized.conf \
        /etc/sysctl.d/98-xray-core-tuning.conf \
        /etc/sysctl.d/99-xray-hotupdate-fast.conf \
        /etc/sysctl.d/99-xray-pmtu-e106.conf \
        /etc/sysctl.d/99-xray-pmtu-e107.conf \
        /etc/sysctl.d/99-auto-tune-relay-e108.conf \
        /etc/sysctl.d/99-auto-tune-relay-e109.conf; do
        test -e "$f" || continue
        if _e159_legacy_sysctl_owned "$f"; then
            rm -f -- "$f" || return 1
        else
            warn "保留无法确认归属的sysctl文件：$f；小BBR状态页会逐键报告其重复定义。"
        fi
    done
    systemctl daemon-reload >/dev/null 2>&1 || return 1
}

_e202_prepare_exclusive_small_profile() {
    if _e202_unrecognized_current_active; then
        return 1
    fi
    if _e202_recognized_legacy_active; then
        return 1
    fi
    if _e202_unrecognized_legacy_active; then
        return 1
    fi
    _e159_network_remove force || return 1
    _e202_retire_confirmed_legacy_layers || return 1
}

_e202_small_bbr_restore_snapshot() {
    local snapshot="$1" operation="$2" rc=0
    _e202_snapshot_valid "$snapshot" || {
        error "小BBR回滚快照不可验证：$snapshot"
        return 1
    }
    systemctl disable --now "$E202_SMALL_UNIT" >/dev/null 2>&1 || true
    _e140_system_restore "$snapshot" || rc=1
    systemctl daemon-reload >/dev/null 2>&1 || rc=1
    _e202_snapshot_runtime_verify "$snapshot" || rc=1
    if test "$rc" -ne 0; then
        install -d -m 0700 "$E202_DIR" 2>/dev/null || true
        {
            echo "time=$(date -Is 2>/dev/null || date)"
            echo "operation=$operation"
            echo "restore_snapshot=$snapshot"
        } >"$E202_CRITICAL_MARKER" 2>/dev/null || true
        error "严重：小BBR事务恢复未通过复检；快照：$snapshot"
        return 1
    fi
    rm -f -- "$E202_CRITICAL_MARKER" 2>/dev/null || true
}

_e202_small_bbr_reconcile_locked() {
    local sha assignments profile_id restore_snapshot
    _e202_small_bbr_active || {
        error '小BBR状态未启用，拒绝开机复写。'
        return 1
    }
    _e202_small_bbr_validate_file "$E202_SMALL_CONF" || {
        error '小BBR配置不是合法的14/25/26项档位，拒绝使用被改写的文件。'
        return 1
    }
    sha=$(sed -n 's/^config_sha256=//p' "$E202_SMALL_STATE" | tail -n1)
    test "$sha" = "$(sha256sum "$E202_SMALL_CONF" | awk '{print $1}')" || {
        error '小BBR配置哈希与状态不一致。'
        return 1
    }
    restore_snapshot=$(sed -n 's/^restore_snapshot=//p' \
        "$E202_SMALL_STATE" | tail -n1)
    _e202_snapshot_valid "$restore_snapshot" || {
        error '小BBR首次启用恢复点无效；拒绝进行不完整的开机复写。'
        return 1
    }
    if _e202_full_network_owner_present; then
        warn '检测到完整参数或旧小BBR所有者复现；先收敛脚本拥有的冲突层，再重放当前档位。'
        _e202_prepare_exclusive_small_profile || return 1
    fi
    _e202_small_bbr_restore_unowned_runtime \
        "$restore_snapshot" "$E202_SMALL_CONF" || return 1
    _e202_small_bbr_apply_runtime || return 1
    assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF")
    profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_CONF") || return 1
    install -d -m 0700 "$(dirname "$E202_SMALL_LOG")" 2>/dev/null || true
    printf '%s result=ok profile=%s assignments=%s hidden=0\n' \
        "$(date -Is 2>/dev/null || date)" "$profile_id" "$assignments" \
        >>"$E202_SMALL_LOG" 2>/dev/null || true
}

_e202_small_bbr_boot_preflight() {
    local cmd
    test "$EUID" -eq 0 || return 1
    for cmd in sysctl modprobe flock sha256sum awk sed grep readlink systemctl install; do
        command -v "$cmd" >/dev/null 2>&1 || {
            error "小BBR开机复检缺少命令：$cmd"
            return 1
        }
    done
}

_e202_small_bbr_reconcile() (
    _e202_small_bbr_boot_preflight || return 1
    _e214_ensure_run_lock || return 1
    exec 189>/run/lock/xray-small-bbr-e202.lock || {
        error '无法创建小BBR事务锁。'
        return 1
    }
    flock -w 90 189 || {
        error '另一个小BBR事务占用锁超过90秒。'
        return 1
    }
    _e202_small_bbr_reconcile_locked
)

_e202_small_bbr_enable() (
    local confirm="${1:-}" tx="" snapshot="" restore_snapshot="" failed=0
    local assignments profile_id token desired_tmp
    if test -e "$E202_SMALL_PROFILE" \
      && ! _e202_small_bbr_validate_file "$E202_SMALL_PROFILE"; then
        error "保存的小BBR档位无效，请先在菜单26重新编辑或恢复默认值：$E202_SMALL_PROFILE"
        return 1
    fi
    if _e202_unrecognized_current_active; then
        return 1
    fi
    if _e202_legacy_e190_active; then
        error '检测到E190小BBR仍在运行；必须先由原版E190执行 --small-bbr-disable。'
        return 1
    fi
    if _e202_legacy_e192_active; then
        error '检测到E192小BBR仍在运行；必须先由原版E192执行 --small-bbr-disable。'
        return 1
    fi
    if _e202_legacy_e194_active; then
        error '检测到E194小BBR仍在运行；必须先由原版E194执行 --small-bbr-disable。'
        return 1
    fi
    if _e202_legacy_e196_active; then
        error '检测到E196小BBR仍在运行；必须先由原版E196执行 --small-bbr-disable。'
        return 1
    fi
    if _e202_legacy_e198_active; then
        error '检测到E198小BBR仍在运行；必须先由原版E198执行 --small-bbr-disable。'
        return 1
    fi
    if _e202_legacy_e200_active; then
        error '检测到E200小BBR仍在运行；必须先由原版E200执行 --small-bbr-disable。'
        return 1
    fi
    assignments=$(_e202_small_bbr_desired | awk -F= \
        '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{n++}END{print n+0}')
    desired_tmp=$(_e118_mktemp e202-profile-id) || return 1
    _e202_small_bbr_desired >"$desired_tmp" || return 1
    profile_id=$(_e202_small_bbr_profile_id_file "$desired_tmp") || return 1
    if test "$confirm" != force; then
        warn "将切换到互斥小BBR档位：$(_e202_small_bbr_profile_name "$profile_id")。"
        warn "该档位持久化${assignments}项，隐藏参数=0："
        _e202_small_bbr_desired | sed 's/^/    /'
        warn 'E159及脚本确认拥有的旧网络层会被暂停；退出小BBR时按快照完整恢复。'
        token=APPLY-SMALL-BBR-14
        if test "$assignments" -ge 25; then
            warn '扩展档会改变乱序上限、TFO、回环TIME_WAIT复用、时间戳、FIN_WAIT_2、连接队列与SACK/DSACK/RACK；26项档还会限制TIME_WAIT桶上限。'
            token=APPLY-SMALL-BBR-F
        fi
        read -rp "输入 $token 确认: " confirm || true
        test "$confirm" = "$token" || {
            info '已取消。'
            return 0
        }
    fi
    _e202_prepare || return 1
    _e214_ensure_run_lock || return 1
    exec 189>/run/lock/xray-small-bbr-e202.lock || {
        error '无法创建小BBR事务锁。'
        return 1
    }
    flock -w 90 189 || {
        error '另一个小BBR事务占用锁超过90秒。'
        return 1
    }
    if _e202_small_bbr_active; then
        restore_snapshot=$(sed -n 's/^restore_snapshot=//p' "$E202_SMALL_STATE" | tail -n1)
        _e202_snapshot_valid "$restore_snapshot" || {
            error '现有小BBR状态的恢复快照无效；拒绝覆盖唯一回滚依据。'
            return 1
        }
        _e202_install_self || return 1
        _e202_write_version || return 1
        tx=$(_e202_new_tx profile-switch) || return 1
        snapshot="$tx/system"
        _e140_system_snapshot "$snapshot" || {
            error '无法建立小BBR档位切换前快照。'
            return 1
        }
        _e202_snapshot_valid "$snapshot" || return 1
        if _e202_full_network_owner_present; then
            _e202_prepare_exclusive_small_profile || failed=1
        fi
        test "$failed" -ne 0 || _e202_small_bbr_write_assets || failed=1
        test "$failed" -ne 0 \
          || _e202_small_bbr_restore_unowned_runtime \
                "$restore_snapshot" "$E202_SMALL_CONF" || failed=1
        test "$failed" -ne 0 || _e202_small_bbr_write_state "$restore_snapshot" || failed=1
        test "$failed" -ne 0 || systemctl daemon-reload >/dev/null 2>&1 || failed=1
        test "$failed" -ne 0 || systemctl enable "$E202_SMALL_UNIT" >/dev/null 2>&1 || failed=1
        test "$failed" -ne 0 || _e202_small_bbr_apply_runtime || failed=1
        test "$failed" -ne 0 || _e202_small_bbr_verify_runtime "$E202_SMALL_CONF" || failed=1
        if test "$failed" -ne 0; then
            error '小BBR配置切换失败，恢复切换前的活动配置与运行值。'
            _e202_small_bbr_restore_snapshot "$snapshot" profile-switch-failed || true
            return 1
        fi
        assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF")
        profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_CONF")
        _e202_prune_tx "$restore_snapshot" "$snapshot"
        info "小BBR已按原恢复点提交：$(_e202_small_bbr_profile_name "$profile_id")；持久参数=$assignments，隐藏参数=0。"
        return 0
    fi
    # The persistent boot unit executes the installed E202 artifact. Commit the
    # script identity before taking the network rollback snapshot so disabling
    # small BBR never downgrades xrv to an older release.
    _e202_install_self || return 1
    _e202_write_version || return 1
    tx=$(_e202_new_tx enable) || return 1
    snapshot="$tx/system"
    _e140_system_snapshot "$snapshot" || {
        error '无法建立小BBR启用前的完整系统快照。'
        return 1
    }
    _e202_snapshot_valid "$snapshot" || return 1

    # 恢复完整档位的原始基线，并清理脚本明确拥有的旧冲突层。
    # 未确认归属的用户/发行版sysctl文件只报告，绝不自动改写。
    _e202_prepare_exclusive_small_profile || failed=1
    test "$failed" -ne 0 || _e202_small_bbr_write_assets || failed=1
    test "$failed" -ne 0 \
      || _e202_small_bbr_restore_unowned_runtime \
            "$snapshot" "$E202_SMALL_CONF" || failed=1
    test "$failed" -ne 0 || _e202_small_bbr_write_state "$snapshot" || failed=1
    test "$failed" -ne 0 || systemctl daemon-reload >/dev/null 2>&1 || failed=1
    test "$failed" -ne 0 || systemctl enable "$E202_SMALL_UNIT" >/dev/null 2>&1 || failed=1
    test "$failed" -ne 0 || _e202_small_bbr_apply_runtime || failed=1
    test "$failed" -ne 0 || _e202_small_bbr_verify_runtime "$E202_SMALL_CONF" || failed=1
    test "$failed" -ne 0 || systemctl is-enabled --quiet "$E202_SMALL_UNIT" || failed=1
    if test "$failed" -ne 0; then
        error '小BBR事务失败，正在恢复启用前的完整网络配置。'
        _e202_small_bbr_restore_snapshot "$snapshot" enable-failed || true
        return 1
    fi
    rm -f -- "$E202_CRITICAL_MARKER" 2>/dev/null || true
    assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF")
    profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_CONF")
    _e202_prune_tx "$snapshot"
    info "小BBR已事务提交：$(_e202_small_bbr_profile_name "$profile_id")；持久参数=$assignments，隐藏参数=0，开机复检=enabled。"
    info "精确配置：$E202_SMALL_CONF"
    info "退出恢复快照：$snapshot"
)

_e202_small_bbr_disable() (
    local confirm="${1:-}" snapshot saved_profile=""
    if ! _e202_small_bbr_active; then
        info '小BBR当前未启用。'
        return 0
    fi
    if test "$confirm" != force; then
        warn '将退出小BBR，并恢复启用前的网络文件、运行值和systemd所有者。'
        read -rp '输入 RESTORE-PREVIOUS-NETWORK 确认: ' confirm || true
        test "$confirm" = RESTORE-PREVIOUS-NETWORK || {
            info '已取消。'
            return 0
        }
    fi
    _e202_prepare || return 1
    _e214_ensure_run_lock || return 1
    exec 189>/run/lock/xray-small-bbr-e202.lock || {
        error '无法创建小BBR事务锁。'
        return 1
    }
    flock -w 90 189 || {
        error '另一个小BBR事务占用锁超过90秒。'
        return 1
    }
    snapshot=$(sed -n 's/^restore_snapshot=//p' "$E202_SMALL_STATE" | tail -n1)
    _e202_snapshot_valid "$snapshot" || {
        error "恢复快照无效，拒绝删除当前小BBR：$snapshot"
        return 1
    }
    saved_profile=$(_e118_mktemp e202-saved-profile) || return 1
    if _e202_small_bbr_validate_file "$E202_SMALL_PROFILE"; then
        cp -f -- "$E202_SMALL_PROFILE" "$saved_profile" || return 1
    elif _e202_small_bbr_validate_file "$E202_SMALL_CONF"; then
        cp -f -- "$E202_SMALL_CONF" "$saved_profile" || return 1
    else
        _e202_small_bbr_default >"$saved_profile" || return 1
    fi
    _e202_small_bbr_restore_snapshot "$snapshot" disable || return 1
    _e202_small_bbr_profile_save "$saved_profile" || {
        error '网络基线已恢复，但保存小BBR档位失败；活动网络未受影响。'
        return 1
    }
    _e202_prune_tx
    info '小BBR已退出，启用前的网络配置与服务状态已恢复并读回验证。'
)

_e202_small_bbr_duplicate_count() {
    local key="$1" f count=0 n
    for f in /etc/sysctl.conf /etc/sysctl.d/*.conf /run/sysctl.d/*.conf \
        /usr/local/lib/sysctl.d/*.conf /usr/lib/sysctl.d/*.conf /lib/sysctl.d/*.conf; do
        test -f "$f" || continue
        test "$f" = "$E202_SMALL_CONF" && continue
        n=$(awk -F= -v wanted="$key" '
          /^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/ {
            k=$1
            gsub(/[[:space:]]/,"",k)
            if (k==wanted) n++
          }
          END {print n+0}
        ' "$f")
        count=$((count+n))
    done
    printf '%s\n' "$count"
}

_e202_small_bbr_status() {
    local active=no config=absent unit=disabled owner=absent profile_id=mode2
    local pending=no saved_profile_state=absent key value actual duplicates
    local malformed_current=no
    local rc=0 assignments=14 target_file
    _e202_small_bbr_active && active=yes
    if test "$active" != yes && _e202_unrecognized_current_active; then
        malformed_current=yes
        rc=1
    fi
    test -e "$E202_SMALL_CONF" && config=invalid
    if _e202_small_bbr_validate_file "$E202_SMALL_CONF"; then
        assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF")
        config="exact-${assignments}-lines"
    fi
    if test -e "$E202_SMALL_PROFILE"; then
        if _e202_small_bbr_validate_file "$E202_SMALL_PROFILE"; then
            saved_profile_state=valid
            profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_PROFILE")
        else
            saved_profile_state=invalid
            profile_id=invalid
            pending=invalid
            rc=1
        fi
    fi
    if test "$active" = yes && test "$saved_profile_state" != invalid \
      && _e202_small_bbr_validate_file "$E202_SMALL_CONF"; then
        cmp -s "$E202_SMALL_CONF" <(_e202_small_bbr_desired) || pending=yes
    fi
    _e202_full_network_owner_present && owner=CONFLICT
    unit=$(systemctl is-enabled "$E202_SMALL_UNIT" 2>/dev/null || true)
    case "$unit" in
        enabled|enabled-runtime|linked|linked-runtime|disabled|static|masked|indirect) ;;
        *) unit=unavailable ;;
    esac
    target_file="$E202_SMALL_PROFILE"
    if test "$active" = yes && _e202_small_bbr_validate_file "$E202_SMALL_CONF"; then
        target_file="$E202_SMALL_CONF"
        profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_CONF")
        assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF")
    elif test "$saved_profile_state" = invalid; then
        assignments=0
        profile_id=invalid
    elif ! _e202_small_bbr_validate_file "$target_file"; then
        assignments=14
        profile_id=mode2
    else
        assignments=$(_e202_small_bbr_assignment_count "$target_file")
    fi
    title 'V199e230：小BBR八档状态（E202兼容稳定所有权）'
    echo "  状态: $active"
    echo "  持久配置: $config"
    echo "  目标/活动档位: $(_e202_small_bbr_profile_name "$profile_id") [$profile_id]"
    echo "  保存档文件状态: $saved_profile_state"
    echo "  保存值待应用: $pending"
    echo "  当前档位sysctl项: $assignments"
    echo '  隐藏sysctl项: 0'
    echo "  开机复检服务: $unit"
    echo "  脚本旧网络所有者: $owner"
    echo '  兼容提示: tcp_adv_win_scale自Linux 6.6起已废弃；仍按请求保存/读回，但新内核可能不再用它计算窗口。'
    echo
    printf '  %-43s %-25s %-25s %s\n' 参数 目标值 运行值 其他文件定义
    if test "$saved_profile_state" = invalid && test "$active" != yes; then
        warn '保存档无效；下表仅显示默认模式2参考值，不会静默覆盖或应用无效文件。'
    fi
    while IFS='=' read -r key value; do
        key=$(_e159_norm "$key")
        value=$(_e159_norm "$value")
        actual=$(sysctl -n "$key" 2>/dev/null || echo unsupported)
        duplicates=$(_e202_small_bbr_duplicate_count "$key")
        printf '  %-43s %-25s %-25s %s\n' "$key" "$value" "$actual" "$duplicates"
        if test "$active" = yes && ! _e159_value_equal "$key" "$value" "$actual"; then
            rc=1
        fi
    done < <(
        if test "$active" = yes \
          && _e202_small_bbr_validate_file "$E202_SMALL_CONF"; then
            cat -- "$E202_SMALL_CONF"
        else
            _e202_small_bbr_desired
        fi
    )
    echo
    echo '  说明：已清理脚本确认拥有的冲突层；未知/用户文件只报告，不擅自删除。'
    if test "$active" = yes; then
        case "$config" in exact-14-lines|exact-25-lines|exact-26-lines) ;; *) rc=1 ;; esac
        test "$owner" = absent || rc=1
        case "$unit" in enabled|enabled-runtime|linked|linked-runtime) ;; *) rc=1 ;; esac
        _e202_snapshot_valid \
            "$(sed -n 's/^restore_snapshot=//p' "$E202_SMALL_STATE" | tail -n1)" || rc=1
        test "$(sed -n 's/^config_sha256=//p' "$E202_SMALL_STATE" | tail -n1)" \
          = "$(sha256sum "$E202_SMALL_CONF" 2>/dev/null | awk '{print $1}')" || rc=1
        test "$(sed -n 's/^persistent_assignments=//p' "$E202_SMALL_STATE" | tail -n1)" \
          = "$assignments" || rc=1
        test "$rc" -eq 0 \
          && info "小BBR状态通过：$assignments 项全部一致，隐藏项=0。" \
          || error '小BBR启用态存在漂移；可在菜单26选择修复。'
    elif test "$malformed_current" = yes; then
        error 'E202小BBR存在不可验证的状态/服务所有权；未将其误报为“未启用”。'
    else
        info '小BBR未启用；当前网络参数由现有系统/E159档位管理。'
    fi
    return "$rc"
}

# Kernel source builds are irreversible until the next reboot.  E204 refuses
# every historical path that could silently skip a custom BBR patch, fall back
# to defconfig, or compile an unpinned mutable patch.
_e204_bbr_conf_safe() {
    local conf="$1"
    test -s "$conf" || { error "BBR参数文件不存在或为空：$conf"; return 1; }
    awk '
      /^[[:space:]]*($|#)/ {next}
      /^[A-Z][A-Z0-9_]*=[0-9]+$/ {next}
      /^[A-Z][A-Z0-9_]*="[A-Za-z0-9_. +*\/<>()-]+"$/ {next}
      {print NR ":" $0 > "/dev/stderr"; bad=1}
      END {exit bad?1:0}
    ' "$conf" || {
        error 'BBR参数文件含可执行Shell语法或未知格式；拒绝source和编译。'
        return 1
    }
    ! grep -Eq '(`|\$\(|\$\{|;|\||&|(^|[^<])>([^=]|$))' "$conf" || {
        error 'BBR参数文件含命令替换、控制符或重定向。'
        return 1
    }
}

if declare -F _e89_patch_bbr_source_from_conf >/dev/null 2>&1; then
    eval "$(declare -f _e89_patch_bbr_source_from_conf | sed '1s/_e89_patch_bbr_source_from_conf/_e204_patch_bbr_source_base/')"
fi
_e89_patch_bbr_source_from_conf() {
    _e204_bbr_conf_safe "$2" || return 1
    _e204_patch_bbr_source_base "$@"
}

if declare -F _e91_verify_patch_hit >/dev/null 2>&1; then
    eval "$(declare -f _e91_verify_patch_hit | sed '1s/_e91_verify_patch_hit/_e204_verify_patch_hit_base/')"
fi
_e91_verify_patch_hit() {
    _e204_bbr_conf_safe "$2" || return 1
    _e204_verify_patch_hit_base "$@"
}

_e204_kernel_kconfig_verify() {
    local src="$1" rc=0
    test -s "$src/.config" || { error '内核.config不存在。'; return 1; }
    grep -Eq '^CONFIG_TCP_CONG_BBR=(y|m)$' "$src/.config" || rc=1
    grep -qx 'CONFIG_DEFAULT_BBR=y' "$src/.config" || rc=1
    grep -qx 'CONFIG_DEFAULT_TCP_CONG="bbr"' "$src/.config" || rc=1
    grep -Eq '^CONFIG_NET_SCH_FQ=(y|m)$' "$src/.config" || rc=1
    if test "$rc" -ne 0; then
        error 'BBR/FQ默认Kconfig读回不完整；拒绝继续安装内核。'
        return 1
    fi
}

if declare -F _e135_kernel_config_guard >/dev/null 2>&1; then
    eval "$(declare -f _e135_kernel_config_guard | sed '1s/_e135_kernel_config_guard/_e204_kernel_config_guard_base/')"
fi
_e135_kernel_config_guard() {
    local src="$1" conf="${E91_BBR_KERNEL_CONF:-${E90_BBR_KERNEL_CONF:-}}"
    _e204_kernel_config_guard_base "$src" || return 1
    if test -n "$conf"; then
        _e204_bbr_conf_safe "$conf" || return 1
        (
            cd "$src" || exit 1
            _e90_kernel_patch_before_compile || exit 1
            _e91_verify_patch_hit net/ipv4/tcp_bbr.c "$conf" \
                "${E91_BBR_KERNEL_KIND:-${E90_BBR_KERNEL_KIND:-}}" || exit 1
        ) || {
            error 'XanMod源码中的自定义BBR注入/逐项读回失败；未进入编译。'
            return 1
        }
    fi
    make -C "$src" olddefconfig >/dev/null || return 1
    _e204_kernel_kconfig_verify "$src"
}

_execute_compilation() {
    local conf="${E91_BBR_KERNEL_CONF:-${E90_BBR_KERNEL_CONF:-}}"
    _e97_full_kernel_compile_guard || return 1
    test -s .config && test -x ./scripts/config || {
        error '当前目录不是已配置的Linux源码树；拒绝编译。'
        return 1
    }
    if test -n "$conf"; then
        _e204_bbr_conf_safe "$conf" || return 1
        _e90_kernel_patch_before_compile || return 1
        _e91_verify_patch_hit net/ipv4/tcp_bbr.c "$conf" \
            "${E91_BBR_KERNEL_KIND:-${E90_BBR_KERNEL_KIND:-}}" || return 1
    fi
    if test "${XRAY_E204_ENABLE_KERNEL_SLIM:-0}" = 1; then
        _e97_kernel_driver_slim_before_compile || return 1
    else
        info 'E204默认保留当前内核驱动配置；如明确需要瘦身，请设置XRAY_E204_ENABLE_KERNEL_SLIM=1。'
    fi
    make olddefconfig >/dev/null || return 1
    _e204_kernel_kconfig_verify "$PWD" || return 1
    _e90_execute_compilation_base "$@"
}

_compile_kernel_mainline_legacy_e53() {
    error '旧“最新主线+在线可变补丁”入口无法做提交/摘要双重固定，E204已失败闭锁。'
    warn '请使用菜单17 → XanMod官方包，或完整XanMod源码编译（固定tag commit并继承当前内核配置）。'
    return 1
}

_e202_small_bbr_profile_save() {
    local source="$1" tmp
    _e202_small_bbr_validate_file "$source" || {
        error '拒绝保存：档位未通过精确14/25/26项结构与范围校验。'
        return 1
    }
    _e202_prepare || return 1
    tmp="$E202_SMALL_PROFILE.tmp.$$"
    install -m 0600 "$source" "$tmp" || {
        rm -f -- "$tmp"
        return 1
    }
    mv -f -- "$tmp" "$E202_SMALL_PROFILE" || {
        rm -f -- "$tmp"
        return 1
    }
}

# Selecting a preset and making it active is one user-visible transaction.
# The runtime/sysctl transaction already restores the active network state on
# failure; this wrapper also restores the previous *saved* profile, so status
# never advertises a failed target as a pending successful selection.
_e202_small_bbr_commit_profile_and_enable() {
    local source="$1" tx profile_snapshot
    _e202_small_bbr_validate_file "$source" || {
        error '拒绝提交：目标档位未通过精确14/25/26项校验。'
        return 1
    }
    tx=$(_e202_new_tx profile-selection) || return 1
    profile_snapshot="$tx/saved-profile"
    _e135_snapshot_file "$E202_SMALL_PROFILE" "$profile_snapshot" || {
        error '无法快照当前保存档；未修改档位。'
        return 1
    }
    _e202_small_bbr_profile_save "$source" || return 1
    if _e202_small_bbr_enable force; then
        return 0
    fi
    error '目标档位未能生效；恢复选择前的保存档。'
    if ! _e135_restore_file "$E202_SMALL_PROFILE" "$profile_snapshot"; then
        error "保存档恢复失败；人工恢复依据：$profile_snapshot"
    fi
    return 1
}

_e202_small_bbr_show_profiles() {
    local id fn
    title 'V199e230：小BBR八个预设 / 保存值 / 活动值（E202兼容稳定所有权）'
    for id in mode1 mode2 mode3 mode1f mode2f mode3f mode3f2 modeb1; do
        fn="_e202_small_bbr_${id}"
        echo "  [$id] $(_e202_small_bbr_profile_name "$id")"
        "$fn" | nl -ba -w2 -s') ' | sed 's/^/    /'
        echo
    done
    echo '  当前保存值（无保存文件时等于模式2）：'
    _e202_small_bbr_desired | nl -ba -w2 -s') ' | sed 's/^/    /'
    if _e202_small_bbr_active; then
        echo
        echo '  当前活动持久值：'
        if _e202_small_bbr_validate_file "$E202_SMALL_CONF"; then
            nl -ba -w2 -s') ' "$E202_SMALL_CONF" | sed 's/^/    /'
        else
            warn '活动持久文件缺失或无效。'
        fi
    fi
}

_e202_small_bbr_edit_profile() {
    local tmp next choice key current value max_index assignments
    local -a keys
    tmp=$(_e118_mktemp e202-small-bbr-edit) || return 1
    _e202_small_bbr_desired >"$tmp" || return 1
    while true; do
        mapfile -t keys < <(_e202_small_bbr_file_keys "$tmp")
        assignments=${#keys[@]}
        max_index="$assignments"
        clear
        title "V199e202：逐项自定义小BBR（严格${assignments}项）"
        echo "  1、2项 fq/bbr 为结构锚点，只读；3—${max_index}项可修改。"
        echo '  数值必须通过范围、布尔值及 min<=default<=max 联合校验。'
        echo
        nl -ba -w2 -s') ' "$tmp" | sed 's/^/  /'
        echo
        echo '  S) 保存但暂不应用'
        echo '  A) 保存并立即启用/应用'
        echo '  R) 将编辑区恢复为E202默认值'
        echo '  0) 放弃并返回'
        read -rp '选择参数编号或操作: ' choice || true
        case "$choice" in
            1|2)
                warn 'fq 与 bbr 是小BBR结构锚点，不在自定义菜单中改变。'
                sleep 1
                ;;
            [3-9]|1[0-9]|2[0-6])
                test "$choice" -le "$max_index" || {
                    warn '该编号不属于当前档位。'
                    sleep 1
                    continue
                }
                key="${keys[$((choice-1))]}"
                current=$(_e202_profile_value "$tmp" "$key")
                read -rp "$key 当前=$current，新值: " value || true
                value=$(_e159_norm "$value")
                test -n "$value" || {
                    warn '空值未保存。'
                    sleep 1
                    continue
                }
                next="${tmp}.next"
                awk -F= -v wanted="$key" -v replacement="$value" '{
                  k=$1
                  gsub(/[[:space:]]/,"",k)
                  if (k==wanted) print wanted " = " replacement
                  else print
                }' "$tmp" >"$next" || {
                    rm -f -- "$next"
                    return 1
                }
                if _e202_small_bbr_validate_file "$next"; then
                    mv -f -- "$next" "$tmp" || return 1
                    info '编辑值已通过联合校验。'
                else
                    rm -f -- "$next"
                    error '该值会形成无效档位，未写入。请检查范围及缓冲三元组顺序。'
                fi
                sleep 1
                ;;
            S|s)
                _e202_small_bbr_profile_save "$tmp" || return 1
                info "自定义${assignments}项已保存：$E202_SMALL_PROFILE"
                return 0
                ;;
            A|a)
                _e202_small_bbr_commit_profile_and_enable "$tmp"
                return $?
                ;;
            R|r)
                _e202_small_bbr_default >"$tmp" || return 1
                info '编辑区已恢复默认值；尚未保存或应用。'
                sleep 1
                ;;
            0)
                info '已放弃本次编辑。'
                return 0
                ;;
            *)
                warn '无效操作。'
                sleep 1
                ;;
        esac
    done
}

_e202_small_bbr_reset_default() {
    local confirm="" tmp
    warn '这会恢复默认模式2并立即启用/应用；原退出快照保持不变。'
    read -rp '输入 RESET-SMALL-BBR-DEFAULT 确认: ' confirm || true
    test "$confirm" = RESET-SMALL-BBR-DEFAULT || {
        info '已取消。'
        return 0
    }
    tmp=$(_e118_mktemp e202-small-bbr-default) || return 1
    _e202_small_bbr_default >"$tmp" || return 1
    _e202_small_bbr_commit_profile_and_enable "$tmp"
}

_e202_small_bbr_select_profile() {
    local id="$1" fn tmp confirm token
    case "$id" in mode1|mode2|mode3|mode1f|mode2f|mode3f|mode3f2|modeb1) ;; *)
        error "未知小BBR档位：$id"
        return 1
    esac
    fn="_e202_small_bbr_${id}"
    tmp=$(_e118_mktemp "e202-${id}") || return 1
    "$fn" >"$tmp" || return 1
    _e202_small_bbr_validate_file "$tmp" || {
        error "内置档位未通过发布校验：$id"
        return 1
    }
    title "应用 $(_e202_small_bbr_profile_name "$id")"
    nl -ba -w2 -s') ' "$tmp" | sed 's/^/  /'
    echo
    token=APPLY-SMALL-BBR-14
    if test "$(_e202_small_bbr_assignment_count "$tmp")" -ge 25; then
        warn 'F/B1是扩展实验档：会改变乱序上限、TFO、回环TIME_WAIT复用、时间戳、FIN_WAIT_2、连接队列与SACK/DSACK/RACK。'
        warn 'tcp_tw_reuse=2仅对loopback连接启用复用；不会直接加速公网Xray连接。'
        warn 'tcp_max_reordering=300与tcp_timestamps=1为当前Linux文档默认值。'
        if test "$id" = mode3f2; then
            warn '模式3F2还会把tcp_fin_timeout设为10，并把tcp_max_tw_buckets设为8192；后者限制系统可同时保留的TIME_WAIT套接字总数。'
        fi
        token=APPLY-SMALL-BBR-F
    fi
    warn '切换失败会恢复切换前活动档；退出小BBR会恢复首次启用前完整网络层。'
    read -rp "输入 $token 确认: " confirm || true
    test "$confirm" = "$token" || {
        info '已取消，保存档与活动档均未改变。'
        return 0
    }
    _e202_small_bbr_commit_profile_and_enable "$tmp"
}

_e202_small_bbr_menu() {
    local n
    while true; do
        clear
        title 'V199e230：小BBR八档切换中心（E202兼容稳定所有权）'
        echo '  基础档=精确14项；F/B1档=精确25项；3F2档=精确26项；隐藏项=0。'
        echo '  IPv6、WARP、MSS、重试与ip_forward不属于小BBR；tcp_max_tw_buckets仅属于3F2。'
        echo '  tcp_adv_win_scale在Linux 6.6起已废弃；保留是为了兼容你的明确参数规格。'
        echo '  1) 模式1--2.50-22MB（256KiB对称 / 22.68MiB / idle=1）'
        echo '  2) 模式2--1.30x0.19-31MB（128KiB/18.91KiB / 31.05MiB，默认）'
        echo '  3) 模式3--0.9x0.25-13MB（95.10KiB/25.60KiB / 12.47MiB）'
        echo '  4) 模式1F--模式1缓冲 + 11项扩展参数（idle=0）'
        echo '  5) 模式2F--1.30w0.19-31MB + 11项扩展参数'
        echo '  6) 模式3F--0.9w0.23-14MB + 11项扩展参数'
        echo '  7) 模式B1--3.5w2.6-62MB + 11项扩展参数'
        echo '  8) 模式3F2--0.9w0.25-19MB-time10s + 12项扩展参数'
        echo '  9) 查看目标值、运行值、持久状态与重复定义'
        echo ' 10) 逐项自定义当前14/25/26项并选择保存/生效'
        echo ' 11) 应用当前保存档位（无保存值时使用模式2）'
        echo ' 12) 按当前活动档位修复/重新应用'
        echo ' 13) 恢复默认模式2并立即生效'
        echo ' 14) 退出小BBR并恢复首次启用前网络配置'
        echo ' 15) 显示八个预设、保存值和活动值'
        echo '  0) 返回'
        read -rp '操作: ' n || true
        case "$n" in
            1) _e202_small_bbr_select_profile mode1; _e138_pause ;;
            2) _e202_small_bbr_select_profile mode2; _e138_pause ;;
            3) _e202_small_bbr_select_profile mode3; _e138_pause ;;
            4) _e202_small_bbr_select_profile mode1f; _e138_pause ;;
            5) _e202_small_bbr_select_profile mode2f; _e138_pause ;;
            6) _e202_small_bbr_select_profile mode3f; _e138_pause ;;
            7) _e202_small_bbr_select_profile modeb1; _e138_pause ;;
            8) _e202_small_bbr_select_profile mode3f2; _e138_pause ;;
            9) _e202_small_bbr_status || true; _e138_pause ;;
            10) _e202_small_bbr_edit_profile; _e138_pause ;;
            11) _e202_small_bbr_enable; _e138_pause ;;
            12)
                if _e202_small_bbr_active; then
                    _e202_small_bbr_reconcile
                else
                    warn '小BBR尚未启用；请先选择一个档位或应用保存档。'
                fi
                _e138_pause
                ;;
            13) _e202_small_bbr_reset_default; _e138_pause ;;
            14) _e202_small_bbr_disable; _e138_pause ;;
            15) _e202_small_bbr_show_profiles; _e138_pause ;;
            0) return 0 ;;
            *) warn '无效操作。'; sleep 1 ;;
        esac
    done
}

