_e202_hot_step() {
    local phase="$1"
    shift
    _e159_phase_log "$E202_HOT_LOG" "$phase" begin
    if "$@"; then
        _e159_phase_log "$E202_HOT_LOG" "$phase" ok
        return 0
    fi
    _e159_phase_log "$E202_HOT_LOG" "$phase" fail
    error "E202热更新失败阶段：$phase"
    return 1
}

_e202_hot_update_preflight() {
    local spec
    _e188_hot_update_preflight || return 1
    _e202_prepare || return 1
    if _e202_unrecognized_current_active; then
        return 1
    fi
    if _e202_unrecognized_legacy_active; then
        return 1
    fi
    if test -e "$E202_SMALL_PROFILE" \
      && ! _e202_small_bbr_validate_file "$E202_SMALL_PROFILE"; then
        error "E202保存的小BBR档位无效，拒绝热更新：$E202_SMALL_PROFILE"
        return 1
    fi
    spec=$(_e118_mktemp e202-small-bbr-spec) || return 1
    _e202_small_bbr_expected >"$spec" || return 1
    _e202_small_bbr_validate_file "$spec" || return 1
    rm -f -- "$spec"
    declare -F _e202_install_self >/dev/null 2>&1 || return 1
    declare -F _e202_small_bbr_enable >/dev/null 2>&1 || return 1
    declare -F _e202_small_bbr_disable >/dev/null 2>&1 || return 1
}

