        -e 's/\$E188_HOT_LOG/\$E202_HOT_LOG/g' \
        -e 's/\$E188_CRITICAL_MARKER/\$E202_CRITICAL_MARKER/g' \
        -e 's/\$E188_SELF_PATH/\$E202_SELF_PATH/g' \
        -e 's/\$E188_LATEST_PATH/\$E202_LATEST_PATH/g' \
        -e 's/xray-e188-hot-update.lock/xray-e202-hot-update.lock/g' \
        -e 's/exec 188>/exec 192>/g' \
        -e 's/flock -n 188/flock -n 192/g' \
        -e 's/before_hot_update_e188/before_hot_update_e202/g' \
        -e 's/E188热更新/E202热更新/g' \
        -e 's/E188回滚/E202回滚/g' \
        -e 's/V199e188/V199e202/g')"
fi

# 稳态迁移规则：旧小BBR必须由“旧版本自己的脚本”先退出，然后才允许
# 新版本进入热更新。新版本绝不猜测旧版本快照格式或代替旧版本恢复。
_e202_hot_update() (
    local small_owner=none outer="" rc=0 legacy_profile_tmp="" legacy_source=""
    local legacy_raw_tmp="" saved_profile_snapshot=""
    local assignments=0 profile_id=""
    if _e202_small_bbr_active; then
        small_owner=e202
    elif _e202_legacy_e200_active; then
        small_owner=e200
    elif _e202_legacy_e198_active; then
        small_owner=e198
    elif _e202_legacy_e196_active; then
        small_owner=e196
    elif _e202_legacy_e194_active; then
        small_owner=e194
    elif _e202_legacy_e192_active; then
        small_owner=e192
    elif _e202_legacy_e190_active; then
        small_owner=e190
    fi
    if test "$small_owner" = e202; then
        outer=$(_e202_new_tx hot-update-outer) || return 1
        _e140_system_snapshot "$outer/system" || return 1
        _e202_snapshot_valid "$outer/system" || return 1
        legacy_profile_tmp=$(_e118_mktemp e202-active-profile-import) || return 1
        _e202_capture_active_config 202 "$E202_SMALL_STATE" \
            "$E202_SMALL_CONF" "$legacy_profile_tmp" || return 1
        saved_profile_snapshot="$outer/saved-profile-choice"
        _e135_snapshot_file "$E202_SMALL_PROFILE" "$saved_profile_snapshot" || return 1
        _e202_small_bbr_disable force || {
            _e202_small_bbr_restore_snapshot "$outer/system" hot-preflight-restore || true
            return 1
        }
    elif test "$small_owner" = e200; then
        legacy_profile_tmp=$(_e118_mktemp e200-profile-import) || return 1
        legacy_raw_tmp=$(_e118_mktemp e200-active-profile-raw) || return 1
        _e202_capture_active_config 200 "$E202_LEGACY_E200_STATE" \
            "$E202_LEGACY_E200_CONF" "$legacy_raw_tmp" || return 1
        if _e202_legacy_e200_validate_file "$E202_LEGACY_E200_PROFILE" \
          && ! cmp -s "$E202_LEGACY_E200_PROFILE" "$E202_LEGACY_E200_CONF"; then
            warn 'E200另有尚未应用的保存档；本次只迁移状态哈希密封的活动档，旧保存文件继续保留供人工核对。'
        fi
        _e202_prepare_legacy_profile 200 "$legacy_raw_tmp" \
            "$legacy_profile_tmp" || return 1
        _e202_legacy_e200_disable || return 1
    elif test "$small_owner" = e198; then
        legacy_profile_tmp=$(_e118_mktemp e198-profile-import) || return 1
        legacy_raw_tmp=$(_e118_mktemp e198-active-profile-raw) || return 1
        _e202_capture_active_config 198 "$E202_LEGACY_E198_STATE" \
            "$E202_LEGACY_E198_CONF" "$legacy_raw_tmp" || return 1
        if _e202_legacy_profile_id "$E202_LEGACY_E198_PROFILE" 198 >/dev/null \
          && ! cmp -s "$E202_LEGACY_E198_PROFILE" "$E202_LEGACY_E198_CONF"; then
            warn 'E198另有尚未应用的保存档；本次只迁移状态哈希密封的活动档，旧保存文件继续保留供人工核对。'
        fi
        _e202_prepare_legacy_profile 198 "$legacy_raw_tmp" \
            "$legacy_profile_tmp" || return 1
        _e202_legacy_e198_disable || return 1
    elif test "$small_owner" = e196; then
        legacy_profile_tmp=$(_e118_mktemp e196-profile-import) || return 1
        legacy_raw_tmp=$(_e118_mktemp e196-active-profile-raw) || return 1
        _e202_capture_active_config 196 "$E202_LEGACY_E196_STATE" \
            "$E202_LEGACY_E196_CONF" "$legacy_raw_tmp" || return 1
        legacy_source="$legacy_raw_tmp"
        if _e202_legacy_profile_id "$E202_LEGACY_E196_PROFILE" 196 >/dev/null \
          && ! cmp -s "$E202_LEGACY_E196_PROFILE" "$E202_LEGACY_E196_CONF"; then
            warn 'E196另有尚未应用的保存档；本次只迁移已密封的活动档，旧保存文件继续保留供人工核对。'
        fi
        _e202_prepare_legacy_profile 196 "$legacy_source" "$legacy_profile_tmp" || return 1
        _e202_legacy_e196_disable || return 1
    elif test "$small_owner" = e194; then
        legacy_profile_tmp=$(_e118_mktemp e194-profile-import) || return 1
        _e202_capture_active_config 194 "$E202_LEGACY_E194_STATE" \
            "$E202_LEGACY_E194_CONF" "$legacy_profile_tmp" || return 1
        if _e202_small_bbr_validate_file "$E202_LEGACY_E194_PROFILE" \
          && ! cmp -s "$E202_LEGACY_E194_PROFILE" "$E202_LEGACY_E194_CONF"; then
            warn 'E194另有尚未应用的保存档；本次只迁移已密封的活动档。'
        fi
        _e202_legacy_e194_disable || return 1
    elif test "$small_owner" = e192; then
        _e202_legacy_e192_disable || return 1
    elif test "$small_owner" = e190; then
        _e202_legacy_e190_disable || return 1
    fi
    _e202_hot_update_base || rc=1
    if test "$rc" -eq 0; then
        case "$small_owner" in
            e202|e194|e196|e198|e200) _e202_small_bbr_profile_save "$legacy_profile_tmp" || rc=1 ;;
        esac
    fi
    if test "$rc" -eq 0 && test "$small_owner" != none; then
        _e202_small_bbr_enable force || rc=1
    fi
    if test "$rc" -ne 0 && test "$small_owner" = e202; then
        error 'E202热更新/小BBR重入失败，恢复热更新前的E202活动档位。'
        _e202_small_bbr_restore_snapshot "$outer/system" hot-update-failed || true
        return 1
    fi
    if test "$rc" -ne 0 && test "$small_owner" != none; then
        error "E202热更新/小BBR重入失败；原版${small_owner}已安全退出，当前保留已通过回滚复检的非小BBR网络状态。"
        error '拒绝由E202反向猜测并重建旧版本档位。'
        return 1
    fi
    if test "$small_owner" = e202; then
        _e135_restore_file "$E202_SMALL_PROFILE" "$saved_profile_snapshot" || {
            error 'E202活动档已重入，但恢复热更新前的待应用保存档失败；执行总回滚。'
            _e202_small_bbr_restore_snapshot "$outer/system" hot-saved-choice-failed || true
            return 1
        }
    fi
    if test "$small_owner" != none; then
        assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF")
        profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_CONF")
        info "热更新后已进入E202：$(_e202_small_bbr_profile_name "$profile_id")；持久参数=$assignments，隐藏参数=0。"
    fi
    return "$rc"
)
hot_update_from_legacy() { _e202_hot_update_preflight && _e202_hot_update; }

if declare -F do_uninstall >/dev/null 2>&1; then
    eval "$(declare -f do_uninstall | sed '1s/do_uninstall/_e202_uninstall_base/')"
fi
do_uninstall() {
    local confirm="" rc=0
    title 'V199e202：受控卸载 Xray 环境'
    warn '卸载会先退出小BBR并恢复其启用前网络档位，然后进入既有归档/回滚流程。'
    read -rp '请输入 DELETE-XRAY 确认: ' confirm || true
    test "$confirm" = DELETE-XRAY || {
        info '已取消，未修改小BBR、IPv6、WARP或Xray状态。'
        return 0
    }
    _e202_uninstall_base "$@" <<< 'DELETE-XRAY' || rc=$?
    if test "$rc" -eq 0 && test ! -e "$XRAY_BIN" && test ! -e "$CONFIG"; then
        systemctl disable --now "$E202_SMALL_UNIT" >/dev/null 2>&1 || true
        rm -f -- "$E202_SMALL_CONF" "$E202_SMALL_SERVICE" \
            "$E202_SELF_PATH" "$E202_LATEST_PATH" 2>/dev/null || true
        rm -rf -- "$E202_DIR" "$E202_TX_ROOT" \
            "$(dirname "$E202_HOT_LOG")" 2>/dev/null || true
        systemctl daemon-reload >/dev/null 2>&1 || true
    elif test "$rc" -eq 0; then
        error '下层卸载未删除Xray核心/配置，E202保留自身状态并返回失败。'
        rc=1
    fi
    return "$rc"
}

_e202_structure_audit() {
    local rc=0 size lines dispatchers menu expected apply hot commit select edit reset
    local reconcile cleanup prune full_apply convert snapshot
    echo 'V199e202 structure audit:'
    size=$(wc -c <"$SCRIPT_PATH" | tr -d ' ')
    lines=$(wc -l <"$SCRIPT_PATH" | tr -d ' ')
    dispatchers=$(grep -c '^# V199e202 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true)
    menu=$(declare -f _e202_main_menu_impl 2>/dev/null || true)
    expected=$(_e202_small_bbr_expected)
    apply=$(declare -f _e202_small_bbr_apply_runtime 2>/dev/null || true)
    hot=$(declare -f _e202_hot_update 2>/dev/null || true)
    commit=$(declare -f _e202_small_bbr_commit_profile_and_enable 2>/dev/null || true)
    select=$(declare -f _e202_small_bbr_select_profile 2>/dev/null || true)
    edit=$(declare -f _e202_small_bbr_edit_profile 2>/dev/null || true)
    reset=$(declare -f _e202_small_bbr_reset_default 2>/dev/null || true)
    reconcile=$(declare -f _e202_small_bbr_reconcile_locked 2>/dev/null || true)
    cleanup=$(declare -f check_and_clean_space 2>/dev/null || true)
    prune=$(declare -f _e202_prune_tx 2>/dev/null || true)
    full_apply=$(declare -f _e159_network_apply 2>/dev/null || true)
    convert=$(declare -f _e202_convert_e200_profile 2>/dev/null || true)
    snapshot=$(declare -f _e140_system_snapshot 2>/dev/null || true)
    echo "  file_bytes=$size"
    echo "  lines=$lines"
    echo "  final_dispatchers=$dispatchers"
    echo '  small_bbr_owner=e202 (exclusive eight-profile 14/25/26 transaction)'
    echo '  full_profile_owner=e159 (blocked while small BBR is active)'
    echo '  network_audit=profile-aware (14/25/26-item or 127-request)'
    echo '  node_summary_owner=e188 (single final QR)'
    test "$size" -gt 2000000 && test "$lines" -gt 45000 || rc=1
    test "$dispatchers" -eq 1 || rc=1
    case "$(printf '%s\n' "$expected" | awk 'NF{n++}END{print n+0}')" in
        14|25|26) ;;
        *) rc=1 ;;
    esac
    ! grep -q '^net.ipv4.tcp_tw_reuse_delay[[:space:]]*=' <<<"$expected" || rc=1
    ! grep -q 'tcp_tw_reuse_delay' <<<"$apply" || rc=1
    grep -q '26) 小BBR' <<<"$menu" || rc=1
    grep -q '_e202_small_bbr_menu' <<<"$menu" || rc=1
    declare -f _e202_small_bbr_menu | grep -q '_e202_small_bbr_select_profile mode3f2' || rc=1
    grep -q '_e202_small_bbr_kernel_ready' <<<"$apply" || rc=1
    grep -q '_e202_small_bbr_disable force' <<<"$hot" || rc=1
    grep -q '_e202_legacy_e190_disable' <<<"$hot" || rc=1
    grep -q '_e202_legacy_e192_disable' <<<"$hot" || rc=1
    grep -q '_e202_legacy_e194_disable' <<<"$hot" || rc=1
    grep -q '_e202_legacy_e196_disable' <<<"$hot" || rc=1
    grep -q '_e202_legacy_e198_disable' <<<"$hot" || rc=1
    grep -q '_e202_legacy_e200_disable' <<<"$hot" || rc=1
    grep -q '_e202_prepare_legacy_profile 196' <<<"$hot" || rc=1
    grep -q '_e202_prepare_legacy_profile 198' <<<"$hot" || rc=1
    grep -q '_e202_prepare_legacy_profile 200' <<<"$hot" || rc=1
    grep -q '_e202_capture_active_config 202' <<<"$hot" || rc=1
    grep -q '_e202_capture_active_config 200' <<<"$hot" || rc=1
    grep -q '_e202_capture_active_config 198' <<<"$hot" || rc=1
    grep -q '_e202_capture_active_config 196' <<<"$hot" || rc=1
    grep -q '_e202_capture_active_config 194' <<<"$hot" || rc=1
    grep -q 'tcp_tw_reuse_delay' <<<"$convert" || rc=1
    grep -q 'E202_LEGACY_E200_UNIT' <<<"$snapshot" || rc=1
    grep -q '_e135_restore_file "$E202_SMALL_PROFILE"' <<<"$hot" || rc=1
    grep -q '_e202_small_bbr_enable force' <<<"$hot" || rc=1
    grep -q '_e202_small_bbr_restore_unowned_runtime' <<<"$reconcile" || rc=1
    grep -q '_e202_unrecognized_current_active' <<<"$full_apply" || rc=1
    grep -q '_e202_unrecognized_legacy_active' <<<"$full_apply" || rc=1
    grep -q '_e202_recognized_legacy_active' <<<"$full_apply" || rc=1
    ! grep -q 'E202_ALLOW_FULL_APPLY' <<<"$full_apply" || rc=1
    grep -q '_e135_snapshot_file "$E202_SMALL_PROFILE"' <<<"$commit" || rc=1
    grep -q '_e135_restore_file "$E202_SMALL_PROFILE"' <<<"$commit" || rc=1
    grep -q '_e202_small_bbr_commit_profile_and_enable' <<<"$select" || rc=1
    grep -q '_e202_small_bbr_commit_profile_and_enable' <<<"$edit" || rc=1
    grep -Fq '2[0-5]' <<<"$edit" || rc=1
    grep -q '_e202_small_bbr_commit_profile_and_enable' <<<"$reset" || rc=1
    grep -q '_e202_prune_tx' <<<"$cleanup" || rc=1
    grep -q 'E202_SMALL_STATE' <<<"$prune" || rc=1
    grep -q 'E202_CRITICAL_MARKER' <<<"$prune" || rc=1
    declare -f _e202_prepare_exclusive_small_profile \
      | grep -q '_e202_unrecognized_legacy_active' || rc=1
    declare -f _e202_prepare_exclusive_small_profile \
      | grep -q '_e202_unrecognized_current_active' || rc=1
    declare -f _e202_prepare_exclusive_small_profile \
      | grep -q '_e202_recognized_legacy_active' || rc=1
    declare -f _e202_hot_update_preflight \
      | grep -q '_e202_unrecognized_legacy_active' || rc=1
    declare -f _e202_hot_update_preflight \
      | grep -q '_e202_unrecognized_current_active' || rc=1
    declare -f _e202_small_bbr_menu | grep -q '_e202_small_bbr_select_profile modeb1' || rc=1
    declare -f _e202_network_params_menu | grep -q '_e202_network_audit' || rc=1
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL'
    return "$rc"
}

_e202_inherited_core_self_test() (
    local d fake out png svg diag family strategy mode menu rc=0
    d=$(mktemp -d /tmp/xray-e202-core-test.XXXXXX) || return 1

    _e186_listener_set_safe \
        "LISTEN 0 4096 127.0.0.1:$E138_WARP_PORT 0.0.0.0:* users:((\"warp-svc\",pid=1,fd=1))" \
      && ! _e186_listener_set_safe \
        "LISTEN 0 4096 0.0.0.0:$E138_WARP_PORT 0.0.0.0:*" \
      && ! _e186_listener_set_safe \
        "LISTEN 0 4096 [::]:$E138_WARP_PORT [::]:*" \
      && _e186_warp_trace_ok $'warp=on\nloc=US\n' \
      && ! _e186_warp_trace_ok $'warp=off\nloc=US\n' || rc=1

    fake="$d/bin"
    mkdir -p "$fake" || rc=1
    cat >"$fake/qrencode" <<'EOF_E202_FAKE_QR'
#!/usr/bin/env bash
type=
out=
while test "$#" -gt 0; do
    case "$1" in
        --version) echo 'qrencode mock 1'; exit 0 ;;
        -t) type="$2"; shift 2 ;;
        -o) out="$2"; shift 2 ;;
        -l|-m|-s) shift 2 ;;
        *) shift ;;
    esac
done
case "$type" in
    UTF8) printf 'discarded-partial\n'; exit 1 ;;
    ANSIUTF8) printf 'single-terminal-qr\n'; exit 0 ;;
    PNG) printf '\211PNG\r\n\032\nmock' >"$out"; exit 0 ;;
    SVG) printf '<svg xmlns="http://www.w3.org/2000/svg"></svg>\n' >"$out"; exit 0 ;;
    *) exit 1 ;;
esac
EOF_E202_FAKE_QR
    chmod 0755 "$fake/qrencode" || rc=1
    qrencode() { bash "$fake/qrencode" "$@"; }
    diag="$d/qr.log"
    out=$(PATH="$fake:$PATH" _e188_qr_terminal \
        'vless://unit-test' "$diag" 2>/dev/null || true)
    test "$out" = single-terminal-qr || rc=1
    png="$d/test.png"
    svg="$d/test.svg"
    PATH="$fake:$PATH" _e186_qr_generate_files \
        'vless://unit-test' "$png" "$svg" "$diag" \
      && _e186_png_valid "$png" && _e186_svg_valid "$svg" || rc=1

    if command -v jq >/dev/null 2>&1; then
        cat >"$d/base.json" <<'EOF_E202_WARP_BASE'
{"dns":{"servers":["1.1.1.1"],"queryStrategy":"UseIPv4"},"outbounds":[{"tag":"direct","protocol":"freedom","settings":{"domainStrategy":"UseIPv4"}},{"tag":"block","protocol":"blackhole"}],"routing":{"domainStrategy":"AsIs","rules":[]}}
EOF_E202_WARP_BASE
        for family in ipv4 ipv6 dual; do
            out="$d/warp-$family.json"
            _e138_warp_config_build global global true \
                "$out" "$d/base.json" "$family" masque || rc=1
            strategy=$(_e185_freedom_strategy "$family")
            jq -e --arg w "$E185_WARP_GLOBAL_TAG" \
              --arg s "$E185_WARP_GLOBAL_SOCKS_TAG" --arg st "$strategy" '
              any(.outbounds[]?;.tag==$s and .protocol=="socks" and .settings.address=="127.0.0.1") and
              any(.outbounds[]?;.tag==$w and .protocol=="freedom" and .settings.domainStrategy==$st and .proxySettings.tag==$s) and
              .dns.queryStrategy=="UseIPv4"
            ' "$out" >/dev/null 2>&1 || rc=1
        done

        BEST_SNI=www.example.com
        SNI_JSON_ARRAY='["www.example.com"]'
        REMARK_NAME=e202-selftest
        E79_VLESSENC_NETWORK=raw
        _e118_generate_reality_material() {
            E77_REALITY_PRIV=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA
            E77_REALITY_PUB=BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB
            E77_REALITY_UUID=11111111-1111-4111-8111-111111111111
            E77_REALITY_SID=a1b2c3d4
        }
        e77_generate_vlessenc_pair() {
            E77_VLESSENC_DECRYPTION=mlkem768x25519plus.native.0rtt
            E77_VLESSENC_ENCRYPTION=mlkem768x25519plus.native.0rtt
        }
        for mode in 1 2 3 4; do
            out="$d/node-$mode.json"
            e79_build_full_config "$mode" 443 8443 8388 \
                2022-blake3-aes-128-gcm \
                AAAAAAAAAAAAAAAAAAAAAA== "$out" || rc=1
            jq -e --arg m "$mode" '
              ([.outbounds[]|select(.tag=="direct" and .protocol=="freedom" and .settings.targetStrategy=="UseIPv4")]|length)==1 and
              (if $m=="1" then ([.inbounds[]|select(.streamSettings.security=="reality")]|length)==1 and ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==0
               elif $m=="2" then ([.inbounds[]|select(.protocol=="vless" and .streamSettings.security=="none")]|length)==1
               elif $m=="3" then ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==1 and ([.inbounds[]|select(.protocol=="vless")]|length)==0
               elif $m=="4" then ([.inbounds[]|select(.streamSettings.security=="reality")]|length)==1 and ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==1
               else false end)
            ' "$out" >/dev/null 2>&1 || rc=1
        done
    fi

    menu=$(declare -f _e202_main_menu_impl 2>/dev/null || true)
    grep -q '_e138_warp_selective_menu' <<<"$menu" \
      && grep -q '_e138_warp_global_menu' <<<"$menu" \
      && grep -q '_e140_warp_full_menu' <<<"$menu" \
      && grep -q '_e182_ipv6_menu' <<<"$menu" \
      && grep -q '_e202_small_bbr_menu' <<<"$menu" || rc=1

    rm -rf -- "$d"
    return "$rc"
)

_e202_small_bbr_self_test() (
    local d conf bad unit rc=0 id fn expected_count detected key
    d=$(mktemp -d /tmp/xray-e202-small-bbr-test.XXXXXX) || return 1
    conf="$d/small.conf"
    bad="$d/small-extra.conf"
    unit="$d/small.service"
    _e202_small_bbr_unit_candidate "$unit" || rc=1
    for id in mode1 mode2 mode3 mode1f mode2f mode3f mode3f2 modeb1; do
        fn="_e202_small_bbr_${id}"
        "$fn" >"$conf" || rc=1
        _e202_small_bbr_validate_file "$conf" || rc=1
        expected_count=14
        case "$id" in
            mode1f|mode2f|mode3f|modeb1) expected_count=25 ;;
            mode3f2) expected_count=26 ;;
        esac
        test "$(_e202_small_bbr_assignment_count "$conf")" -eq "$expected_count" || rc=1
        detected=$(_e202_small_bbr_profile_id_file "$conf" 2>/dev/null || true)
        test "$detected" = "$id" || rc=1
    done
    _e202_small_bbr_default >"$conf" || rc=1
    test "$(_e202_small_bbr_profile_id_file "$conf")" = mode2 || rc=1
    grep -Fqx 'net.core.rmem_default = 131072' "$conf" || rc=1
    grep -Fqx 'net.core.wmem_default = 19365' "$conf" || rc=1
    grep -Fqx 'net.core.wmem_max = 32554432' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_mtu_probing = 1' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_ecn = 0' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_slow_start_after_idle = 0' "$conf" || rc=1
    ! grep -Eq 'mss|retries|backlog|forward|disable_ipv6|max_tw_buckets' "$conf" || rc=1
    _e202_small_bbr_mode1f >"$conf" || rc=1
    grep -Fqx 'net.core.rmem_max = 23777216' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_max_reordering = 300' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_tw_reuse = 2' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_timestamps = 1' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_sack = 1' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_dsack = 1' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_recovery = 1' "$conf" || rc=1
    ! grep -q '^net.ipv4.tcp_tw_reuse_delay[[:space:]]*=' "$conf" || rc=1
    grep -Fqx 'net.core.netdev_max_backlog = 16380' "$conf" || rc=1
    grep -Fqx 'net.core.somaxconn = 8192' "$conf" || rc=1
    ! grep -Eq 'ip_forward|max_tw_buckets|ulimit|LimitNOFILE' "$conf" || rc=1
    _e202_small_bbr_mode3f2 >"$conf" || rc=1
    test "$(_e202_small_bbr_assignment_count "$conf")" -eq 26 || rc=1
    grep -Fqx 'net.core.rmem_default = 96695' "$conf" || rc=1
    grep -Fqx 'net.core.wmem_default = 26215' "$conf" || rc=1
    grep -Fqx 'net.core.rmem_max = 19977218' "$conf" || rc=1
    grep -Fqx 'net.core.wmem_max = 19977218' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_rmem = 4096 96695 19977218' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_wmem = 4096 26215 19977218' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_fin_timeout = 10' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_max_tw_buckets = 8192' "$conf" || rc=1
    cp -- "$conf" "$bad" || rc=1
    sed -i 's/net.ipv4.tcp_max_tw_buckets = 8192/net.ipv4.tcp_max_tw_buckets = 100/' "$bad" || rc=1
    ! _e202_small_bbr_validate_file "$bad" || rc=1
    cp -- "$conf" "$bad" || rc=1
    sed -i 's/net.ipv4.tcp_timestamps = 1/net.ipv4.tcp_timestamps = 0/' "$bad" || rc=1
    ! _e202_small_bbr_validate_file "$bad" || rc=1
    _e202_small_bbr_modeb1 >"$conf" || rc=1
    grep -Fqx 'net.core.rmem_default = 353026' "$conf" || rc=1
    grep -Fqx 'net.core.wmem_default = 262144' "$conf" || rc=1
    grep -Fqx 'net.core.rmem_max = 65777218' "$conf" || rc=1
    grep -Fqx 'net.core.wmem_max = 65777218' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_rmem = 4096 353026 65777218' "$conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_wmem = 4096 262144 65777218' "$conf" || rc=1
    _e202_small_bbr_mode3f >"$conf" || rc=1
    grep -Fqx 'net.core.rmem_default = 95695' "$conf" || rc=1
    grep -Fqx 'net.core.wmem_default = 23215' "$conf" || rc=1
    grep -Fqx 'net.core.wmem_max = 15077216' "$conf" || rc=1
    grep -Fqx "ExecStart=$E202_SELF_PATH --small-bbr-reconcile" "$unit" || rc=1
    ! grep -q '^\[Timer\]' "$unit" || rc=1

    # Legacy migration accepts only the active config sealed by the legacy
    # state. A valid-looking but modified config must not pass on shape alone.
    _e202_small_bbr_mode2 >"$d/legacy-active.conf" || rc=1
    {
        echo 'persistent_assignments=14'
        echo "config_sha256=$(sha256sum "$d/legacy-active.conf" | awk '{print $1}')"
    } >"$d/legacy-active.state" || rc=1
    _e202_legacy_active_config_valid 196 \
        "$d/legacy-active.state" "$d/legacy-active.conf" >/dev/null || rc=1
    sed -i 's/net.core.wmem_default = 19365/net.core.wmem_default = 19366/' \
        "$d/legacy-active.conf" || rc=1
    ! _e202_legacy_active_config_valid 196 \
        "$d/legacy-active.state" "$d/legacy-active.conf" >/dev/null 2>&1 || rc=1
    _e202_legacy_old_profile mode2f 300 >"$d/e198-active.conf" || rc=1
    {
        echo 'persistent_assignments=21'
        echo "config_sha256=$(sha256sum "$d/e198-active.conf" | awk '{print $1}')"
    } >"$d/e198-active.state" || rc=1
    _e202_legacy_active_config_valid 198 \
        "$d/e198-active.state" "$d/e198-active.conf" >/dev/null || rc=1
    sed -i 's/net.ipv4.tcp_fastopen = 3/net.ipv4.tcp_fastopen = 7/' \
        "$d/e198-active.conf" || rc=1
    ! _e202_legacy_active_config_valid 198 \
        "$d/e198-active.state" "$d/e198-active.conf" >/dev/null 2>&1 || rc=1

    # Snapshot convergence keeps the newest N transactions and any explicitly
    # protected rollback pointer, removing only direct children of its root.
    mkdir -p "$d/prune-root" || rc=1
    for key in 1 2 3 4 5 6; do
        mkdir -p "$d/prune-root/tx-$key" || rc=1
        touch -d "@$key" "$d/prune-root/tx-$key" || rc=1
    done
    _e202_prune_tx_root "$d/prune-root" 3 "$d/prune-root/tx-1" || rc=1
    test "$(find "$d/prune-root" -mindepth 1 -maxdepth 1 -type d | wc -l)" -eq 4 || rc=1
    test -d "$d/prune-root/tx-1" && test -d "$d/prune-root/tx-4" \
      && test -d "$d/prune-root/tx-5" && test -d "$d/prune-root/tx-6" || rc=1
    test ! -e "$d/prune-root/tx-2" && test ! -e "$d/prune-root/tx-3" || rc=1

    # A failed preset switch must restore the saved-profile file as well as
    # the runtime transaction. Keep this test in a nested shell so mocks never
    # leak into the migration and rollback tests below.
    (
        : >"$d/profile-transaction.log"
        _e202_small_bbr_validate_file() { return 0; }
        _e202_new_tx() {
            printf '%s/profile-tx\n' "$d"
        }
        _e135_snapshot_file() {
            echo snapshot >>"$d/profile-transaction.log"
        }
        _e202_small_bbr_profile_save() {
            echo save >>"$d/profile-transaction.log"
        }
        _e202_small_bbr_enable() {
            echo enable >>"$d/profile-transaction.log"
            return 1
        }
        _e135_restore_file() {
            echo restore >>"$d/profile-transaction.log"
        }
        ! _e202_small_bbr_commit_profile_and_enable "$conf" >/dev/null 2>&1
        test "$(tr '\n' ' ' <"$d/profile-transaction.log")" \
          = 'snapshot save enable restore '
    ) || rc=1

    # Exercise the active-E202 hot-update failure path explicitly. Historical
    # releases have failed here on unset transaction variables; the only valid
    # order is outer snapshot -> old profile exit -> base update -> attempted
    # re-entry -> outer snapshot restore.
    (
        : >"$d/e202-hot-failure.log"
        _e202_small_bbr_active() { return 0; }
        _e202_legacy_e200_active() { return 1; }
        _e202_legacy_e198_active() { return 1; }
        _e202_legacy_e196_active() { return 1; }
        _e202_legacy_e194_active() { return 1; }
        _e202_legacy_e192_active() { return 1; }
        _e202_legacy_e190_active() { return 1; }
        _e202_new_tx() {
            printf '%s/e202-hot-outer\n' "$d"
        }
        _e140_system_snapshot() {
            echo snapshot >>"$d/e202-hot-failure.log"
        }
        _e202_snapshot_valid() { return 0; }
        _e118_mktemp() {
            printf '%s/e202-active-import.conf\n' "$d"
        }
        _e202_capture_active_config() {
            echo capture-active >>"$d/e202-hot-failure.log"
            : >"$4"
        }
        _e135_snapshot_file() {
            echo snapshot-saved-choice >>"$d/e202-hot-failure.log"
        }
        _e202_small_bbr_disable() {
            echo disable >>"$d/e202-hot-failure.log"
        }
        _e202_hot_update_base() {
            echo base-update >>"$d/e202-hot-failure.log"
        }
        _e202_small_bbr_profile_save() {
            echo import-active >>"$d/e202-hot-failure.log"
        }
        _e202_small_bbr_enable() {
            echo enable-failed >>"$d/e202-hot-failure.log"
            return 1
        }
        _e202_small_bbr_restore_snapshot() {
            echo outer-restore >>"$d/e202-hot-failure.log"
        }
        ! _e202_hot_update >/dev/null 2>&1
        test "$(tr '\n' ' ' <"$d/e202-hot-failure.log")" \
          = 'snapshot capture-active snapshot-saved-choice disable base-update import-active enable-failed outer-restore '
    ) || rc=1

    # On success, an E202 hot update re-enters the sealed active profile and
    # then restores the independent saved/pending profile choice.
    (
        : >"$d/e202-hot-success.log"
        _e202_small_bbr_active() { return 0; }
        _e202_legacy_e200_active() { return 1; }
        _e202_legacy_e198_active() { return 1; }
        _e202_legacy_e196_active() { return 1; }
        _e202_legacy_e194_active() { return 1; }
        _e202_legacy_e192_active() { return 1; }
        _e202_legacy_e190_active() { return 1; }
        _e202_new_tx() { printf '%s/e202-hot-outer\n' "$d"; }
        _e140_system_snapshot() { return 0; }
        _e202_snapshot_valid() { return 0; }
        _e118_mktemp() { printf '%s/e202-active-import.conf\n' "$d"; }
        _e202_capture_active_config() {
            echo capture-active >>"$d/e202-hot-success.log"
            : >"$4"
        }
        _e135_snapshot_file() {
            echo snapshot-saved-choice >>"$d/e202-hot-success.log"
        }
        _e202_small_bbr_disable() {
            echo disable >>"$d/e202-hot-success.log"
        }
        _e202_hot_update_base() {
            echo base-update >>"$d/e202-hot-success.log"
        }
        _e202_small_bbr_profile_save() {
            echo import-active >>"$d/e202-hot-success.log"
        }
        _e202_small_bbr_enable() {
            echo enable-active >>"$d/e202-hot-success.log"
        }
        _e135_restore_file() {
            echo restore-saved-choice >>"$d/e202-hot-success.log"
        }
        _e202_small_bbr_assignment_count() { echo 14; }
        _e202_small_bbr_profile_id_file() { echo mode2; }
        _e202_small_bbr_profile_name() { echo mode2; }
        _e202_hot_update >/dev/null 2>&1
        test "$(tr '\n' ' ' <"$d/e202-hot-success.log")" \
          = 'capture-active snapshot-saved-choice disable base-update import-active enable-active restore-saved-choice '
    ) || rc=1

    _e202_small_bbr_default >"$conf" || rc=1
    cp -- "$conf" "$bad" || rc=1
    printf '%s\n' 'net.ipv4.tcp_retries2 = 8' >>"$bad" || rc=1
    ! _e202_small_bbr_validate_file "$bad" || rc=1
    (
        _e202_small_bbr_active() { return 0; }
        _e202_full_network_apply_base() { return 0; }
        ! _e159_network_apply fq 1 31 force >/dev/null 2>&1
    ) || rc=1
    (
        _e202_small_bbr_active() { return 1; }
        _e202_legacy_e200_active() { return 1; }
        _e202_legacy_e198_active() { return 1; }
        _e202_legacy_e196_active() { return 1; }
        _e202_legacy_e194_active() { return 1; }
        _e202_legacy_e192_active() { return 1; }
        _e202_legacy_e190_active() { return 1; }
        _e202_hot_update_base() { return 0; }
        _e202_hot_update >/dev/null 2>&1
    ) || rc=1

    # The union now has twelve optional keys: eleven shared F keys plus the
    # 3F2-only tcp_max_tw_buckets.  Switching to a 14-item profile restores all
    # twelve; switching to a 25-item profile restores only the 3F2-only key;
    # switching to 3F2 restores none because all 26 keys remain owned.
    mkdir -p "$d/baseline" || rc=1
    : >"$d/baseline/runtime-sysctl.env"
    while IFS= read -r key; do
        printf '%s|101\n' "$key" >>"$d/baseline/runtime-sysctl.env" || rc=1
    done < <(_e202_small_bbr_all_keys)
    : >"$d/proc"
    : >"$d/sysctl-write.log"
    _e202_snapshot_valid() { return 0; }
    _e159_proc_path() { printf '%s/proc\n' "$d"; }
    sysctl() {
        case "${1:-}" in
            -w) printf '%s\n' "$*" >>"$d/sysctl-write.log" ;;
            -n) printf '%s\n' 101 ;;
            *) return 1 ;;
        esac
        return 0
    }
    _e202_small_bbr_mode1 >"$conf" || rc=1
    _e202_small_bbr_restore_unowned_runtime "$d/baseline" "$conf" || rc=1
    test "$(wc -l <"$d/sysctl-write.log")" -eq 12 || rc=1
    while IFS= read -r key; do
        grep -Fqx "$key" < <(_e202_small_bbr_base_keys) && continue
        grep -Fqx -- "-w $key=101" "$d/sysctl-write.log" || rc=1
    done < <(_e202_small_bbr_all_keys)
    : >"$d/sysctl-write.log"
    _e202_small_bbr_mode1f >"$conf" || rc=1
    _e202_small_bbr_restore_unowned_runtime "$d/baseline" "$conf" || rc=1
    test "$(wc -l <"$d/sysctl-write.log")" -eq 1 || rc=1
    grep -Fqx -- '-w net.ipv4.tcp_max_tw_buckets=101' "$d/sysctl-write.log" || rc=1
    : >"$d/sysctl-write.log"
    _e202_small_bbr_mode3f2 >"$conf" || rc=1
    _e202_small_bbr_restore_unowned_runtime "$d/baseline" "$conf" || rc=1
    test ! -s "$d/sysctl-write.log" || rc=1

    # Known E196/E198 built-ins map to the new 25-item schema. A custom legacy
    # 21-item profile is rejected before its original owner is asked to exit.
    _e202_legacy_old_profile mode1f 500 >"$d/e196-known.conf" || rc=1
    _e202_prepare_legacy_profile 196 \
        "$d/e196-known.conf" "$d/e196-known-mapped.conf" >/dev/null || rc=1
    test "$(_e202_small_bbr_profile_id_file "$d/e196-known-mapped.conf")" = mode1f || rc=1
    grep -Fqx 'net.ipv4.tcp_max_reordering = 300' "$d/e196-known-mapped.conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_tw_reuse = 2' "$d/e196-known-mapped.conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_timestamps = 1' "$d/e196-known-mapped.conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_sack = 1' "$d/e196-known-mapped.conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_dsack = 1' "$d/e196-known-mapped.conf" || rc=1
    grep -Fqx 'net.ipv4.tcp_recovery = 1' "$d/e196-known-mapped.conf" || rc=1
    ! grep -q '^net.ipv4.tcp_tw_reuse_delay[[:space:]]*=' "$d/e196-known-mapped.conf" || rc=1
    sed 's/net.core.rmem_default = 262144/net.core.rmem_default = 262145/' \
        "$d/e196-known.conf" >"$d/e196-custom.conf" || rc=1
    ! _e202_prepare_legacy_profile 196 \
        "$d/e196-custom.conf" "$d/e196-custom-mapped.conf" >/dev/null 2>&1 || rc=1
    _e202_legacy_old_profile modeb 300 >"$d/e198-modeb.conf" || rc=1
    _e202_prepare_legacy_profile 198 \
        "$d/e198-modeb.conf" "$d/e198-modeb1.conf" >/dev/null || rc=1
    test "$(_e202_small_bbr_profile_id_file "$d/e198-modeb1.conf")" = custom-f || rc=1
    grep -Fqx 'net.core.wmem_max = 33054432' "$d/e198-modeb1.conf" || rc=1

    # Migration ordering is a release invariant: preserve/map the validated
    # E196 profile, make E196 restore its own baseline, run the E202 update,
    # import the saved profile and only then enable the new owner.
    _e202_small_bbr_mode2 >"$d/e196-profile.conf" || rc=1
    : >"$d/migration-order.log"
    (
        _e202_small_bbr_active() { return 1; }
        _e202_legacy_e200_active() { return 1; }
        _e202_legacy_e198_active() { return 1; }
        _e202_legacy_e196_active() { return 0; }
        _e202_legacy_e194_active() { return 1; }
        _e202_legacy_e192_active() { return 1; }
        _e202_legacy_e190_active() { return 1; }
        _e118_mktemp() {
            case "${1:-}" in
                e196-active-profile-raw) printf '%s/e196-raw.conf\n' "$d" ;;
                *) printf '%s/import.conf\n' "$d" ;;
            esac
        }
        _e202_small_bbr_validate_file() { return 0; }
        _e202_capture_active_config() {
            echo capture-e196-active >>"$d/migration-order.log"
            command cp -- "$d/e196-profile.conf" "$4"
        }
        _e202_prepare_legacy_profile() {
            echo prepare-e196-profile >>"$d/migration-order.log"
            command cp -- "$d/e196-profile.conf" "$3"
        }
        _e202_legacy_e196_disable() {
            echo old-e196-exit >>"$d/migration-order.log"
        }
        _e202_hot_update_base() {
            echo e202-base-update >>"$d/migration-order.log"
        }
        _e202_small_bbr_profile_save() {
            echo import-profile >>"$d/migration-order.log"
        }
        _e202_small_bbr_enable() {
            echo enable-e202 >>"$d/migration-order.log"
        }
        _e202_small_bbr_assignment_count() { echo 14; }
        _e202_small_bbr_profile_id_file() { echo custom; }
        _e202_small_bbr_profile_name() { echo custom; }
        _e202_hot_update >/dev/null 2>&1
    ) || rc=1
    test "$(tr '\n' ' ' <"$d/migration-order.log")" \
      = 'capture-e196-active prepare-e196-profile old-e196-exit e202-base-update import-profile enable-e202 ' || rc=1

    # The E198 owner follows the same invariant: seal and
    # map its active built-in, let original E198 restore its own baseline, then
    # install E202 and activate the mapped 14/25-item profile.
    : >"$d/e198-migration-order.log"
    (
        _e202_small_bbr_active() { return 1; }
        _e202_legacy_e200_active() { return 1; }
        _e202_legacy_e198_active() { return 0; }
        _e202_legacy_e196_active() { return 1; }
        _e202_legacy_e194_active() { return 1; }
        _e202_legacy_e192_active() { return 1; }
        _e202_legacy_e190_active() { return 1; }
        _e118_mktemp() {
            case "${1:-}" in
                e198-active-profile-raw) printf '%s/e198-raw.conf\n' "$d" ;;
                *) printf '%s/e198-import.conf\n' "$d" ;;
            esac
        }
        _e202_capture_active_config() {
            echo capture-e198-active >>"$d/e198-migration-order.log"
            _e202_legacy_old_profile mode2f 300 >"$4"
        }
        _e202_legacy_profile_id() { return 1; }
        _e202_prepare_legacy_profile() {
            echo prepare-e198-profile >>"$d/e198-migration-order.log"
            _e202_small_bbr_mode2f >"$3"
        }
        _e202_legacy_e198_disable() {
            echo old-e198-exit >>"$d/e198-migration-order.log"
        }
        _e202_hot_update_base() {
            echo e202-base-update >>"$d/e198-migration-order.log"
        }
        _e202_small_bbr_profile_save() {
            echo import-profile >>"$d/e198-migration-order.log"
        }
        _e202_small_bbr_enable() {
            echo enable-e202 >>"$d/e198-migration-order.log"
        }
        _e202_small_bbr_assignment_count() { echo 25; }
        _e202_small_bbr_profile_id_file() { echo mode2f; }
        _e202_small_bbr_profile_name() { echo mode2f; }
        _e202_hot_update >/dev/null 2>&1
    ) || rc=1
    test "$(tr '\n' ' ' <"$d/e198-migration-order.log")" \
      = 'capture-e198-active prepare-e198-profile old-e198-exit e202-base-update import-profile enable-e202 ' || rc=1

    # E200 extended profiles contain exactly one now-retired delay key. Seal
    # the old active file, remove that assignment, append the explicit three
    # recovery controls, let E200 restore its own baseline, then enable E202.
    _e202_small_bbr_mode2f | awk '
      $1=="net.ipv4.tcp_sack" || $1=="net.ipv4.tcp_dsack" ||
      $1=="net.ipv4.tcp_recovery" {next}
      {print}
      $1=="net.ipv4.tcp_timestamps" {
        print "net.ipv4.tcp_tw_reuse_delay = 1000"
      }
    ' >"$d/e200-active.conf" || rc=1
    {
        echo 'persistent_assignments=23'
        echo "config_sha256=$(sha256sum "$d/e200-active.conf" | awk '{print $1}')"
    } >"$d/e200-active.state" || rc=1
    _e202_legacy_active_config_valid 200 \
        "$d/e200-active.state" "$d/e200-active.conf" || rc=1
    _e202_prepare_legacy_profile 200 "$d/e200-active.conf" \
        "$d/e200-mapped.conf" >/dev/null || rc=1
    test "$(_e202_small_bbr_assignment_count "$d/e200-mapped.conf")" -eq 25 || rc=1
    ! grep -q '^net.ipv4.tcp_tw_reuse_delay[[:space:]]*=' \
        "$d/e200-mapped.conf" || rc=1
    cmp -s "$d/e200-mapped.conf" <(_e202_small_bbr_mode2f) || rc=1

    : >"$d/e200-migration-order.log"
    (
        _e202_small_bbr_active() { return 1; }
        _e202_legacy_e200_active() { return 0; }
        _e202_legacy_e198_active() { return 1; }
        _e202_legacy_e196_active() { return 1; }
        _e202_legacy_e194_active() { return 1; }
        _e202_legacy_e192_active() { return 1; }
        _e202_legacy_e190_active() { return 1; }
        _e118_mktemp() {
            case "${1:-}" in
                e200-active-profile-raw) printf '%s/e200-hot-raw.conf\n' "$d" ;;
                *) printf '%s/e200-hot-import.conf\n' "$d" ;;
            esac
        }
        _e202_capture_active_config() {
            echo capture-e200-active >>"$d/e200-migration-order.log"
            command cp -- "$d/e200-active.conf" "$4"
        }
        _e202_legacy_e200_validate_file() { return 1; }
        _e202_prepare_legacy_profile() {
            echo prepare-e200-profile >>"$d/e200-migration-order.log"
            command cp -- "$d/e200-mapped.conf" "$3"
        }
        _e202_legacy_e200_disable() {
            echo old-e200-exit >>"$d/e200-migration-order.log"
        }
        _e202_hot_update_base() {
            echo e202-base-update >>"$d/e200-migration-order.log"
        }
        _e202_small_bbr_profile_save() {
            echo import-profile >>"$d/e200-migration-order.log"
        }
        _e202_small_bbr_enable() {
            echo enable-e202 >>"$d/e200-migration-order.log"
        }
        _e202_small_bbr_assignment_count() { echo 25; }
        _e202_small_bbr_profile_id_file() { echo mode2f; }
        _e202_small_bbr_profile_name() { echo mode2f; }
        _e202_hot_update >/dev/null 2>&1
    ) || rc=1
    test "$(tr '\n' ' ' <"$d/e200-migration-order.log")" \
      = 'capture-e200-active prepare-e200-profile old-e200-exit e202-base-update import-profile enable-e202 ' || rc=1

    # An enabled current E202 unit with malformed/missing state is not
    # "inactive": treating it as a first enable would seal the wrong baseline.
    (
        _e202_small_bbr_active() { return 1; }
        sed() { return 0; }
        systemctl() {
            case "${1:-}" in
                is-active) echo inactive; return 3 ;;
                is-enabled) echo enabled; return 0 ;;
            esac
            return 1
        }
        _e202_unrecognized_current_active >/dev/null 2>&1
    ) || rc=1

    # An enabled but currently inactive legacy oneshot is still a future boot
    # owner. Missing state must not let it survive preflight unnoticed.
    (
        _e202_legacy_e200_active() { return 1; }
        _e202_legacy_e198_active() { return 1; }
        _e202_legacy_e196_active() { return 1; }
        _e202_legacy_e194_active() { return 1; }
        _e202_legacy_e192_active() { return 1; }
        _e202_legacy_e190_active() { return 1; }
        sed() { return 0; }
        systemctl() {
            case "${1:-}:${2:-}" in
                is-active:*) echo inactive; return 3 ;;
                is-enabled:"$E202_LEGACY_E198_UNIT") echo enabled; return 0 ;;
                is-enabled:*) echo disabled; return 1 ;;
            esac
            return 1
        }
        _e202_unrecognized_legacy_active >/dev/null 2>&1
    ) || rc=1

    # A malformed active legacy state is not an inactive leftover. It must stop
    # the new release before any cleanup can destroy the old restore pointer.
    _e202_legacy_e196_active() { return 1; }
    _e202_legacy_e200_active() { return 1; }
    _e202_legacy_e198_active() { return 1; }
    _e202_legacy_e194_active() { return 1; }
    _e202_legacy_e192_active() { return 1; }
    _e202_legacy_e190_active() { return 1; }
    sed() {
        case "$*" in
            *"$E202_LEGACY_E196_STATE"*) printf '%s\n' 1 ;;
            *) command sed "$@" ;;
        esac
    }
    systemctl() {
        test "${1:-}" = is-active && {
            echo inactive
            return 3
        }
        return 0
    }
    _e202_unrecognized_legacy_active >/dev/null 2>&1 || rc=1
    rm -rf -- "$d"
    return "$rc"
)

_e202_self_test() {
    local rc=0
    echo 'V199e202 fast release gate:'
    bash -n "$SCRIPT_PATH" \
      && echo '  [PASS] bash syntax' \
      || { echo '  [FAIL] bash syntax'; rc=1; }
    test "$SCRIPT_VERSION" = 199e202 && test "$E202_VERSION" = 199e202 \
      && echo '  [PASS] release identity' \
      || { echo '  [FAIL] release identity'; rc=1; }
    _e188_summary_transaction_self_test \
      && echo '  [PASS] inherited one-summary/one-QR transaction gate' \
      || { echo '  [FAIL] inherited QR transaction gate'; rc=1; }
    _e202_inherited_core_self_test \
      && echo '  [PASS] inherited Xray/WARP/QR behavior gate' \
      || { echo '  [FAIL] inherited Xray/WARP/QR behavior gate'; rc=1; }
    _e202_small_bbr_self_test \
      && echo '  [PASS] eight exact 14/25/26-line profiles; no hidden knobs' \
      || { echo '  [FAIL] small-BBR eight-profile invariant'; rc=1; }
    _e202_structure_audit >/dev/null \
      && echo '  [PASS] menu/hot-update/rollback final bindings' \
      || { echo '  [FAIL] E202 structure binding'; rc=1; }
    test "$rc" -eq 0 && echo 'V199e202 result: PASS' || echo 'V199e202 result: FAIL'
    return "$rc"
}

_e202_help() {
    cat <<'EOF_E202_HELP'
V199e202:
  --hot-update                         事务热更新到E202
  --small-bbr-menu                     八个预设档位与14/25/26项自定义菜单
  --small-bbr-enable                   启用当前保存档（无保存值时模式2）
  --small-bbr-status                   只读查看当前14/25/26项及重复定义
  --small-bbr-reconcile                开机/手动复检并仅重写当前档位
  --small-bbr-disable                  退出并恢复启用前网络档位
  --summary                            手动导出节点URI、单次终端QR及PNG/SVG
  --self-test                          E202快速发行门禁
  --structure-audit                    E202最终绑定审计
EOF_E202_HELP
}

#==============================================================================
# V199e204 FINAL RELIABILITY LAYER
# - E202 remains the compatibility owner for the small-BBR transaction;
#   E214 extends its exact profile schema with the eighth 26-item preset.
# - All new mutations below are fail-closed and keep a sealed rollback point.
#==============================================================================
readonly E204_VERSION="199e204"
readonly E204_DIR="$CONFIG_DIR/e204"
readonly E204_SELF_PATH="$SCRIPT_DIR/ex199e204.sh"
readonly E204_LATEST_PATH="$SCRIPT_DIR/ex199e_latest.sh"
readonly E204_TX_ROOT="/var/backups/xray-e204"
readonly E204_HOT_LOG="$LOG_DIR/e204/hot-update-last.log"
readonly E204_CRITICAL_MARKER="$E204_DIR/CRITICAL_RECOVERY_REQUIRED.env"
readonly E204_ZRAM_SCRIPT="/usr/local/bin/xray-zram-e204.sh"
readonly E204_ZRAM_SERVICE="/etc/systemd/system/xray-zram-e204.service"
readonly E204_ZRAM_UNIT="xray-zram-e204.service"
readonly E204_ZRAM_STATE="$E204_DIR/zram-owner.env"
readonly E204_SWAPFILE="/swapfile.xray-e204"
# Never trust a caller-supplied test-mode environment variable.  These values
# are reset while loading and are enabled only for the narrow internal tests.
E204_INTERNAL_SELF_TEST=0
E204_INTERNAL_SELF_TEST_TMP=""
E159_DEFER_HOST_FULL_VERIFY=0
E188_SUMMARY_SUPPRESS=0
E188_SUMMARY_PENDING=0

_e204_prepare() {
    install -d -m 0700 "$E204_DIR" "$E204_TX_ROOT" \
        "$(dirname -- "$E204_HOT_LOG")" || return 1
    _e214_ensure_run_lock || return 1
}

_e204_prune_transactions() {
    local keep="${XRAY_E204_TX_KEEP:-12}" root="" p="" real="" child="" row=""
    local pid="" expected_start="" actual_start="" marker_refs=0
    local protected=" " rc=0
    [[ "$keep" =~ ^[0-9]+$ ]] && ((keep >= 12 && keep <= 100)) || keep=12
    root=$(readlink -f -- "$E204_TX_ROOT" 2>/dev/null || true)
    test -n "$root" && test -d "$root" || return 0
    # Callers pass every live transaction.  A critical marker normally points
    # at its system/ child, so normalize every protected path to its top-level
    # E204 transaction directory before pruning.
    for p in "$@"; do
        real=$(readlink -f -- "$p" 2>/dev/null || true)
        case "$real" in
            "$root"/*)
                child=${real#"$root"/}; child=${child%%/*}
                test -n "$child" && protected+="$root/$child " ;;
        esac
    done
    if test -e "$E204_CRITICAL_MARKER" || test -L "$E204_CRITICAL_MARKER"; then
        test -f "$E204_CRITICAL_MARKER" && test ! -L "$E204_CRITICAL_MARKER" \
          && test -r "$E204_CRITICAL_MARKER" && test -s "$E204_CRITICAL_MARKER" \
          || { warn "E204恢复标记异常，停止清理E204事务：$E204_CRITICAL_MARKER" >&2; return 1; }
        while IFS= read -r p; do
            real=$(readlink -f -- "$p" 2>/dev/null || true)
            case "$real" in
                "$root"/*)
                    child=${real#"$root"/}; child=${child%%/*}
                    if test -n "$child"; then
                        protected+="$root/$child "
                        marker_refs=$((marker_refs + 1))
                    fi ;;
            esac
        done < <(sed -n 's/^backup=//p' "$E204_CRITICAL_MARKER" 2>/dev/null)
        test "$marker_refs" -gt 0 || {
            warn "E204恢复标记未指向E204事务根内的有效快照，停止清理：$E204_CRITICAL_MARKER" >&2
            return 1
        }
    fi
    while IFS=$'\t' read -r _ row; do
        test -n "$row" || continue
        real=$(readlink -f -- "$row" 2>/dev/null || true)
        case "$real" in "$root"/*) ;; *) rc=1; continue ;; esac
        [[ "$protected" == *" $real "* ]] && continue
        test ! -s "$real/.preserve.env" || continue
        if test -s "$real/.active.env"; then
            pid=$(sed -n 's/^pid=//p' "$real/.active.env" 2>/dev/null | head -n1)
            expected_start=$(sed -n 's/^start=//p' "$real/.active.env" 2>/dev/null | head -n1)
            if [[ "$pid" =~ ^[1-9][0-9]*$ && "$expected_start" =~ ^[0-9]+$ ]] \
              && kill -0 "$pid" 2>/dev/null; then
                actual_start=$(awk '{print $22}' "/proc/$pid/stat" 2>/dev/null || true)
                test "$actual_start" != "$expected_start" || continue
            fi
        fi
        rm -rf -- "${real:?}" 2>/dev/null || rc=1
    done < <(find "$root" -mindepth 1 -maxdepth 1 -type d -printf '%T@\t%p\n' 2>/dev/null \
        | sort -nr | awk -F '\t' -v keep="$keep" 'NR>keep{print $1 "\t" $2}')
    return "$rc"
}

_e204_new_tx() {
    local purpose="${1:-transaction}" d start owner_pid=""
    owner_pid=$(_e230_tx_owner_pid) || return 1
    _e204_prepare || return 1
    purpose=$(printf '%s' "$purpose" | tr -cd 'A-Za-z0-9._-' | cut -c1-48)
    test -n "$purpose" || purpose=transaction
    d="$E204_TX_ROOT/${purpose}-$(date +%Y%m%d_%H%M%S)-${owner_pid}-$RANDOM"
    install -d -m 0700 "$d" || return 1
    start=$(awk '{print $22}' "/proc/$owner_pid/stat" 2>/dev/null || true)
    [[ "$start" =~ ^[0-9]+$ ]] || { rm -rf -- "$d"; return 1; }
    printf 'pid=%s\nstart=%s\n' "$owner_pid" "$start" >"$d/.active.env" || return 1
    chmod 0600 "$d/.active.env" || return 1
    _e204_prune_transactions "$d" \
        || warn 'E204旧事务快照收敛未完全完成；当前事务继续并保留。' >&2
    printf '%s\n' "$d"
}

# A transaction snapshot remains available after the operation, but its
# liveness marker must describe only an operation which is actually running.
# Without this close step, every successful action in one long-lived menu
# process appears active forever and snapshot convergence cannot reclaim it.
_e204_tx_close() {
    local tx="${1:-}" root real
    test -n "$tx" || return 0
    root=$(readlink -f -- "$E204_TX_ROOT" 2>/dev/null || true)
    real=$(readlink -f -- "$tx" 2>/dev/null || true)
    test -n "$root" && test -n "$real" || return 1
    case "$real" in
        "$root"/*) rm -f -- "$real/.active.env" ;;
        *) error "拒绝关闭E204事务根目录外的标记：$tx"; return 1 ;;
    esac
}

if declare -F check_and_clean_space >/dev/null 2>&1; then
    eval "$(declare -f check_and_clean_space | sed '1s/check_and_clean_space/_e204_clean_space_base/')"
fi
check_and_clean_space() {
    _e204_clean_space_base "$@" || return 1
    _e204_prune_transactions \
        || warn 'E204部分旧事务快照因保护标记或文件系统状态未能收敛。'
}

_e204_mark_critical() {
    local operation="$1" backup="${2:-unknown}" detail="${3:-unspecified}" tmp
    _e204_prepare || return 1
    tmp=$(_e118_mktemp e204-critical) || return 1
    {
        echo "time=$(date -Is 2>/dev/null || date)"
        echo "operation=$operation"
        echo "backup=$backup"
        printf 'detail=%s\n' "$detail" | tr '\n\r' '  '
    } >"$tmp" || return 1
    _e118_atomic_install "$tmp" "$E204_CRITICAL_MARKER" 0600
}

_e204_service_snapshot() {
    local unit="$1" load enabled active
    load=$(systemctl show "$unit" -p LoadState --value 2>/dev/null || true)
    enabled=$(systemctl is-enabled "$unit" 2>/dev/null || true)
    active=$(systemctl is-active "$unit" 2>/dev/null || true)
    load=${load:-not-found}
    enabled=${enabled:-disabled}
    active=${active:-inactive}
    printf '%s|%s|%s|%s\n' "$unit" "$load" "$enabled" "$active"
}

_e204_service_candidate_ok() {
    case "${1:-}" in
        *@.service|*@.timer|*@.socket) return 1 ;;
        xray*.service|xray*.timer|xray*.socket|\
        ssh*.service|ssh*.timer|ssh*.socket|\
        fail2ban.service|warp-svc.service|\
        dnsmasq.service|systemd-resolved.service|resolvconf.service|\
        nftables.service|firewalld.service|ufw.service|\
        rsyslog.service|systemd-journald.service) return 0 ;;
        *) return 1 ;;
    esac
}

_e204_service_candidates() {
    local path unit
    # Keep an explicit core list so an originally missing unit is still
    # recorded before this transaction has a chance to create it.
    printf '%s\n' \
        xray.service fail2ban.service \
        ssh.service sshd.service ssh.socket sshd.socket \
        warp-svc.service dnsmasq.service systemd-resolved.service \
        resolvconf.service nftables.service firewalld.service ufw.service \
        rsyslog.service systemd-journald.service

    # The final path owner contains absent as well as existing managed units.
    # Taking names from it avoids silently omitting a unit introduced by any
    # retained compatibility layer.
    while IFS= read -r path; do
        unit=${path##*/}
        _e204_service_candidate_ok "$unit" && printf '%s\n' "$unit"
    done < <(_e138_system_paths 2>/dev/null || true)

    # Literal names cover compatibility units which are intentionally no
    # longer present in the current path manifest but can be disabled/removed
    # during migration.  Input is restricted to a unit-name alphabet.
    if test -r "$SCRIPT_PATH"; then
        while IFS= read -r unit; do
            _e204_service_candidate_ok "$unit" && printf '%s\n' "$unit"
        done < <(LC_ALL=C grep -Eo \
            '[A-Za-z0-9_.@-]+\.(service|timer|socket)' "$SCRIPT_PATH" \
            2>/dev/null | LC_ALL=C sort -u)
    fi

    # Preserve pre-existing Xray units unknown to this release too.  They may
    # share ownership with an older ex199e layer stopped during migration.
    while IFS=' ' read -r unit _; do
        _e204_service_candidate_ok "$unit" && printf '%s\n' "$unit"
    done < <(systemctl list-unit-files 'xray*.service' 'xray*.timer' \
        'xray*.socket' --no-legend 2>/dev/null || true)
}

_e204_service_restore_line() {
    local unit="$1" load="$2" enabled="$3" active="$4" rc=0 now now_enabled now_load
    if test "$load" = not-found; then
        systemctl stop "$unit" >/dev/null 2>&1 || true
        systemctl disable "$unit" >/dev/null 2>&1 || true
        now_load=$(systemctl show "$unit" -p LoadState --value 2>/dev/null || true)
        now_load=${now_load:-not-found}
        test "$now_load" = not-found
        return
    fi
    case "$enabled" in
        masked)
            systemctl stop "$unit" >/dev/null 2>&1 || true
            systemctl unmask "$unit" >/dev/null 2>&1 || true
            systemctl mask "$unit" >/dev/null 2>&1 || rc=1
            ;;
        masked-runtime)
            systemctl stop "$unit" >/dev/null 2>&1 || true
            systemctl unmask "$unit" >/dev/null 2>&1 || true
            systemctl mask --runtime "$unit" >/dev/null 2>&1 || rc=1
            ;;
        enabled-runtime) systemctl unmask "$unit" >/dev/null 2>&1 || true; systemctl enable --runtime "$unit" >/dev/null 2>&1 || rc=1 ;;
        enabled) systemctl unmask "$unit" >/dev/null 2>&1 || true; systemctl enable "$unit" >/dev/null 2>&1 || rc=1 ;;
        disabled) systemctl unmask "$unit" >/dev/null 2>&1 || true; systemctl disable "$unit" >/dev/null 2>&1 || true ;;
        linked|linked-runtime|alias|indirect|static|generated|transient|'')
            systemctl unmask "$unit" >/dev/null 2>&1 || true
            ;;
        *) : ;;
    esac
    case "$active" in
        active|activating|reloading) systemctl start "$unit" >/dev/null 2>&1 || rc=1 ;;
        *) systemctl stop "$unit" >/dev/null 2>&1 || true ;;
    esac
    now=$(systemctl is-active "$unit" 2>/dev/null || true)
    case "$active:$now" in
        active:active|activating:active|activating:activating|reloading:active|reloading:reloading) ;;
        active:*|activating:*|reloading:*) rc=1 ;;
        inactive:inactive) ;;
        deactivating:inactive|deactivating:deactivating) ;;
        # A pre-existing failed unit cannot be manufactured safely during
        # rollback.  It may remain failed or become cleanly inactive, but it
        # must never be started accidentally.
        failed:failed|failed:inactive) ;;
        unknown:unknown|unknown:inactive|'':inactive) ;;
        *) rc=1 ;;
    esac
    now_enabled=$(systemctl is-enabled "$unit" 2>/dev/null || true)
    case "$enabled" in
        enabled|enabled-runtime|masked|masked-runtime|disabled|linked|linked-runtime|alias|indirect|static|generated|transient)
            test "$now_enabled" = "$enabled" || rc=1 ;;
        '') ;;
        *) rc=1 ;;
    esac
    now_load=$(systemctl show "$unit" -p LoadState --value 2>/dev/null || true)
    test -z "$load" || test "$now_load" = "$load" || rc=1
    return "$rc"
}

_e204_services_restore_file() {
    local file="$1" unit load enabled active rc=0
    test -s "$file" || return 0
    systemctl daemon-reload >/dev/null 2>&1 || rc=1
    while IFS='|' read -r unit load enabled active; do
        test -n "$unit" || continue
        _e204_service_restore_line "$unit" "$load" "$enabled" "$active" || rc=1
    done <"$file"
    return "$rc"
}

# Extend every inherited full-system transaction with service states introduced
# after E140.  File snapshots alone cannot restore a previously inactive
# dnsmasq/warp/TC/ZRAM unit to its exact active/enabled state.
if declare -F _e140_system_snapshot >/dev/null 2>&1; then
    eval "$(declare -f _e140_system_snapshot | sed '1s/_e140_system_snapshot/_e204_system_snapshot_base/')"
fi
if declare -F _e140_system_restore >/dev/null 2>&1; then
    eval "$(declare -f _e140_system_restore | sed '1s/_e140_system_restore/_e204_system_restore_base/')"
fi
_e140_system_snapshot() {
    local b="$1" unit
    _e204_system_snapshot_base "$b" || return 1
    : >"$b/e204-services.env" || return 1
    while IFS= read -r unit; do
        test -n "$unit" || continue
        _e204_service_snapshot "$unit" >>"$b/e204-services.env" || return 1
    done < <(_e204_service_candidates | LC_ALL=C sort -u)
    test -s "$b/e204-services.env" || return 1
    (cd "$b" && sha256sum e204-services.env >e204-services.sha256) || return 1
}

_e140_system_restore() {
    local b="$1" rc=0
    if test -e "$b/e204-services.env" || test -e "$b/e204-services.sha256"; then
        test -s "$b/e204-services.env" && test -s "$b/e204-services.sha256" \
            && (cd "$b" && sha256sum -c e204-services.sha256 >/dev/null 2>&1) || {
                error "E204服务状态快照损坏：$b"
                return 1
            }
    fi
    _e204_system_restore_base "$b" || rc=1
    test ! -s "$b/e204-services.env" || _e204_services_restore_file "$b/e204-services.env" || rc=1
    return "$rc"
}

# Menu 10 still reaches several E168 implementations through the retained
# E170/E172/E182 compatibility aliases.  Those implementations have useful
# device-specific rollback code, but some of them intentionally suppress the
# return value from their local rollback (`... || true`).  Wrap the complete
# action in an E204 system snapshot as a second, independently checksummed
# recovery boundary.  A failed inner action can therefore never be presented
# as a clean rollback when files/services could not be restored.
if declare -F _e168_apply_init30_tx >/dev/null 2>&1; then
    eval "$(declare -f _e168_apply_init30_tx | sed '1s/_e168_apply_init30_tx/_e204_apply_init30_tx_base/')"
fi
if declare -F _e168_offload_action >/dev/null 2>&1; then
    eval "$(declare -f _e168_offload_action | sed '1s/_e168_offload_action/_e204_offload_action_base/')"
fi
if declare -F _e168_rps_action >/dev/null 2>&1; then
    eval "$(declare -f _e168_rps_action | sed '1s/_e168_rps_action/_e204_rps_action_base/')"
fi
if declare -F _e168_mss_action >/dev/null 2>&1; then
    eval "$(declare -f _e168_mss_action | sed '1s/_e168_mss_action/_e204_mss_action_base/')"
fi
if declare -F _e168_txq_action >/dev/null 2>&1; then
    eval "$(declare -f _e168_txq_action | sed '1s/_e168_txq_action/_e204_txq_action_base/')"
fi
if declare -F _e168_ring_action >/dev/null 2>&1; then
    eval "$(declare -f _e168_ring_action | sed '1s/_e168_ring_action/_e204_ring_action_base/')"
fi
if declare -F _e168_disable_legacy_tx >/dev/null 2>&1; then
    eval "$(declare -f _e168_disable_legacy_tx | sed '1s/_e168_disable_legacy_tx/_e204_disable_legacy_tx_base/')"
fi
if declare -F _e159_apply_micro_28 >/dev/null 2>&1; then
    eval "$(declare -f _e159_apply_micro_28 | sed '1s/_e159_apply_micro_28/_e204_micro28_base/')"
fi

_e204_advanced_action_tx() {
    local label="${1:-advanced}" handler="${2:-}" tx="" rc=0 restore_rc=0
    shift 2 || return 1
    declare -F "$handler" >/dev/null 2>&1 || {
        error "E204高级事务处理器不存在：$handler"
        return 1
    }
    tx=$(_e204_new_tx "advanced-$label") || return 1
    _e140_system_snapshot "$tx/system" || {
        rm -f -- "$tx/.active.env" 2>/dev/null || true
        error "E204高级事务快照失败：$label"
        return 1
    }
    if "$handler" "$@"; then
        rm -f -- "$tx/.active.env" 2>/dev/null || true
        return 0
    else
        rc=$?
    fi
    error "E204高级事务失败：$label；执行外围完整恢复。"
    _e140_system_restore "$tx/system" || restore_rc=1
    rm -f -- "$tx/.active.env" 2>/dev/null || true
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical "advanced-$label" "$tx/system" \
            "outer rollback/readback failed; inner_rc=$rc" || true
        error "严重：$label 外围回滚未完整通过；快照：$tx/system"
    else
        info "$label 已恢复到操作前文件与服务状态；快照：$tx/system"
    fi
    return 1
}

# Every application-layer action in menu 10/6 ultimately enters this E159
# helper.  Its local Xray rollback is useful, but historical call sites
# deliberately suppressed a failed rollback with `|| true`.  Preserve that
# implementation as the inner transaction and add the checksummed E204 system
# snapshot outside it, so a failed Xray rollback can never be mistaken for a
# completed recovery.
if declare -F _e159_xray_action_tx >/dev/null 2>&1; then
    eval "$(declare -f _e159_xray_action_tx | sed '1s/_e159_xray_action_tx/_e204_xray_action_tx_base/')"
fi
_e159_xray_action_tx() {
    local name="${1:-}"
    test -n "$name" || {
        error 'E204 Xray事务缺少动作名称。'
        return 1
    }
    _e204_advanced_action_tx "xray-$name" _e204_xray_action_tx_base "$@"
}

_e168_apply_init30_tx() { _e204_advanced_action_tx init30 _e204_apply_init30_tx_base "$@"; }
_e168_offload_action() { _e204_advanced_action_tx offload _e204_offload_action_base "$@"; }
_e168_rps_action() { _e204_advanced_action_tx rps-rfs _e204_rps_action_base "$@"; }
_e168_mss_action() { _e204_advanced_action_tx mss-clamp _e204_mss_action_base "$@"; }
_e168_txq_action() { _e204_advanced_action_tx txqueue _e204_txq_action_base "$@"; }
_e168_ring_action() { _e204_advanced_action_tx ring-buffer _e204_ring_action_base "$@"; }
_e168_disable_legacy_tx() { _e204_advanced_action_tx disable-legacy _e204_disable_legacy_tx_base "$@"; }
_e159_apply_micro_28() { _e204_advanced_action_tx micro-28 _e204_micro28_base "$@"; }

# Extend the inherited system snapshot with the actual Xray payload and the
# E204 identity.  Earlier snapshots covered many overlays but omitted the core
# binary/config, so a failed post-commit node export could not truly roll back.
if declare -F _e138_system_paths >/dev/null 2>&1; then
    eval "$(declare -f _e138_system_paths | sed '1s/_e138_system_paths/_e204_system_paths_base/')"
fi
_e138_system_paths() {
    _e204_system_paths_base
    printf '%s\n' \
        "$XRAY_BIN" "$CONFIG" "$PUBKEY_FILE" "$SNI_CACHE_FILE" \
        "$INSTALL_DATE_FILE" "$SCRIPT_VERSION_FILE" "$USER_SNI_MAP" \
        "$USER_TIME_MAP" "$DAT_DIR/geoip.dat" "$DAT_DIR/geosite.dat" \
        "$CONFIG_DIR/xray_core_auto_update_disabled_e105.txt" \
        /etc/systemd/system/xray.service /etc/systemd/system/xray.service.d \
        "$E204_DIR" "$E204_SELF_PATH" "$E204_LATEST_PATH" \
        /etc/resolv.conf /etc/dnsmasq.conf "${E67_DNS_MODE_FILE:-$CONFIG_DIR/dns_mode.txt}" \
        /etc/fstab /etc/sysctl.d/98-xray-swap.conf \
        /var/spool/cron/crontabs/root /var/spool/cron/root \
        "$E204_ZRAM_SCRIPT" "$E204_ZRAM_SERVICE" "$E204_ZRAM_STATE"
}

_e204_install_self() {
    local tx target snap tmp failed=0
    local -a targets=("$SYMLINK" "$E204_SELF_PATH" "$E204_LATEST_PATH" "$E202_SELF_PATH")
    test -r "$SCRIPT_PATH" || return 1
    _e204_prepare || return 1
    tx=$(_e204_new_tx self-install) || return 1
    for target in "${targets[@]}"; do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
        _e135_snapshot_file "$target" "$snap" || {
            _e204_tx_close "$tx" || true
            return 1
        }
    done
    for target in "${targets[@]}"; do
        install -d -m 0755 "$(dirname -- "$target")" || { failed=1; break; }
        tmp="$target.e204-new.$$"
        install -m 0755 "$SCRIPT_PATH" "$tmp" || { rm -f -- "$tmp"; failed=1; break; }
        bash -n "$tmp" || { rm -f -- "$tmp"; failed=1; break; }
        mv -f -- "$tmp" "$target" || { rm -f -- "$tmp"; failed=1; break; }
        cmp -s "$SCRIPT_PATH" "$target" || { failed=1; break; }
    done
    if test "$failed" -ne 0; then
        for target in "${targets[@]}"; do
            snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
            _e135_restore_file "$target" "$snap" || true
        done
        error "E204脚本入口原子安装失败，已恢复旧入口；快照：$tx"
        _e204_tx_close "$tx" || true
        return 1
    fi
    hash -r 2>/dev/null || true
    _e204_tx_close "$tx"
}

_e204_write_version() {
    local tmp
    _e204_prepare || return 1
    tmp=$(_e118_mktemp e204-version) || return 1
    printf '%s\n' "$E204_VERSION" >"$tmp" || return 1
    _e118_atomic_install "$tmp" "$SCRIPT_VERSION_FILE" 0600
}

# Keep the E202 compatibility path because its boot unit intentionally owns the
# exact eight profiles, while the final executable byte owner is E214.
_e202_install_self() { _e204_install_self "$@"; }
_e188_install_self() { _e204_install_self "$@"; }
_e186_install_self() { _e204_install_self "$@"; }
_e185_install_self() { _e204_install_self "$@"; }
_e183_install_self() { _e204_install_self "$@"; }
_e182_install_self() { _e204_install_self "$@"; }
_e159_install_self() { _e204_install_self "$@"; }
_e152_install_self() { _e204_install_self "$@"; }
_e142_install_self() { _e204_install_self "$@"; }
_e138_install_self() { _e204_install_self "$@"; }
_e118_install_self() { _e204_install_self "$@"; }
_e202_write_version() { _e204_write_version "$@"; }
_e188_write_version() { _e204_write_version "$@"; }
_e186_write_version() { _e204_write_version "$@"; }
_e185_write_version() { _e204_write_version "$@"; }
_e183_write_version() { _e204_write_version "$@"; }
_e182_write_version() { _e204_write_version "$@"; }
_e159_write_version() { _e204_write_version "$@"; }
_e152_write_version() { _e204_write_version "$@"; }
_e142_write_version() { _e204_write_version "$@"; }

# The inherited node builder still stamped node.meta as E182 even though its
# script/version entry had already advanced.  Keep the proven metadata schema,
# but bind both the writer and the readback version to the active E204 owner.
if declare -F _e182_write_generated_metadata_impl >/dev/null 2>&1; then
    eval "$(declare -f _e182_write_generated_metadata_impl | sed \
        -e '1s/_e182_write_generated_metadata_impl/_e204_write_generated_metadata_impl/' \
        -e 's/\$E182_VERSION/\$E204_VERSION/g' \
        -e 's/node-meta-e182/node-meta-e204/g' \
        -e 's/_e182_write_version/_e204_write_version/g')"
fi
_e182_write_generated_metadata_impl() { _e204_write_generated_metadata_impl "$@"; }
_e118_write_generated_metadata() { _e204_write_generated_metadata_impl "$@"; }

# Network ownership: never manufacture a new "origin" from an already-managed
# runtime, and never delete the current owner before a sealed origin restores.
if declare -F _e159_network_apply >/dev/null 2>&1; then
    eval "$(declare -f _e159_network_apply | sed '1s/_e159_network_apply/_e204_network_apply_base/')"
fi

_e204_network_state_file() {
    local s
    for s in "$E159_NETWORK_STATE" "$E159_LEGACY_E156_STATE" "$E159_LEGACY_E154_STATE"; do
        test -s "$s" && { printf '%s\n' "$s"; return 0; }
    done
    return 1
}

_e204_network_origin() {
    local state origin
    state=$(_e204_network_state_file) || return 1
    origin=$(sed -n 's/^origin_backup=//p' "$state" 2>/dev/null | tail -n1)
    test -n "$origin" || origin=$(sed -n 's/^backup=//p' "$state" 2>/dev/null | tail -n1)
    test -n "$origin" || return 1
    _e159_network_tx_verify "$origin" || return 1
    printf '%s\n' "$origin"
}

_e204_snapshot_path_absent() {
    local tx="$1" path="$2" id
    id=$(awk -F'|' -v p="$path" '$1==p{print $2;exit}' "$tx/paths.tsv" 2>/dev/null || true)
    test -n "$id" && test -e "$tx/files/$id.absent"
}

_e204_network_origin_clean() {
    local tx="$1" p
    for p in "$E159_EFFECTIVE_CONF" "$E159_NETWORK_STATE" \
        "$E159_NETWORK_SERVICE" "$E159_NETWORK_TIMER"; do
        _e204_snapshot_path_absent "$tx" "$p" || return 1
    done
}

_e204_network_owner_present() {
    local p
    for p in "$E159_EFFECTIVE_CONF" "$E159_NETWORK_STATE" "$E159_NETWORK_SERVICE" \
        "$E159_LEGACY_E156_EFFECTIVE_CONF" "$E159_LEGACY_E156_STATE" \
        "$E159_LEGACY_E154_EFFECTIVE_CONF" "$E159_LEGACY_E154_STATE"; do
        test -e "$p" && return 0
    done
    return 1
}

_e159_network_apply() {
    local origin=""
    if _e204_network_owner_present; then
        origin=$(_e204_network_origin 2>/dev/null || true)
        if test -z "$origin" || ! _e204_network_origin_clean "$origin"; then
            error '检测到完整网络所有者，但首次接管前快照缺失、损坏或已经包含E159自身。'
            error '拒绝把当前运行态重新密封成伪基线；请先保留现场并执行 --full-network-status。'
            return 1
        fi
    fi
    _e204_network_apply_base "$@"
}

_e159_network_remove() (
    local confirm="${1:-}" origin requested safety rc=0
    if test "$confirm" != force; then
        warn '将按首次接管前的密封快照恢复完整网络层；恢复成功前不会停用或删除当前所有者。'
        read -rp '输入 REMOVE-E159-NETWORK 确认: ' confirm || true
        test "$confirm" = REMOVE-E159-NETWORK || return 0
    fi
    _e159_prepare || return 1
    exec 154>/run/lock/xray-network-e159.lock
    flock -w 90 154 || { error '另一个完整网络事务占用锁超过90秒。'; return 1; }
    _e204_network_owner_present || { info '完整网络层当前不存在。'; return 0; }
    origin=$(_e204_network_origin 2>/dev/null || true)
    test -n "$origin" && _e204_network_origin_clean "$origin" || {
        error '首次接管前快照不可验证或不是干净基线；未停止服务、未删除文件。'
        return 1
    }
    requested="$E159_EFFECTIVE_CONF"
    if test ! -s "$requested"; then
        requested=$(_e118_mktemp e204-network-remove-spec) || return 1
        _e159_full_spec fq 1 31 "$requested" || return 1
    fi
    safety=$(_e159_network_tx_new) || return 1
    _e159_network_snapshot "$safety" "$requested" || return 1
    _e159_network_tx_verify "$safety" || return 1
    if ! _e159_network_restore "$origin"; then
        error '网络基线恢复未通过，正在恢复移除前的完整网络现场。'
        if ! _e159_network_restore "$safety"; then
            _e204_mark_critical network-remove "$safety" 'origin restore and safety restore both failed' || true
            error "严重：二次恢复也失败；现场快照：$safety"
        fi
        return 1
    fi
    for requested in "$E159_EFFECTIVE_CONF" "$E159_NETWORK_STATE" \
        "$E159_NETWORK_SERVICE" "$E159_NETWORK_TIMER"; do
        test ! -e "$requested" || rc=1
    done
    if test "$rc" -ne 0; then
        error '首次基线读回仍含E159所有者，恢复移除前现场。'
        _e159_network_restore "$safety" || _e204_mark_critical network-remove-readback "$safety" 'safety restore failed' || true
        return 1
    fi
    info "完整网络层已恢复到首次接管前状态；移除前安全快照：$safety"
)

# A node build is one transaction through final URI/QR export.  Any failure
# after the new config was committed restores the previous core, config,
# WARP/IPv6 state and original Xray service state.
if declare -F _e182_install_mode >/dev/null 2>&1; then
    eval "$(declare -f _e182_install_mode | sed '1s/_e182_install_mode/_e204_install_mode_base/')"
fi
_e182_install_mode() {
    local tx rc=0 restore_rc=0
    if test "${E204_INTERNAL_SELF_TEST:-0}" = 1; then
        _e204_install_mode_base "$@"
        return $?
    fi
    tx=$(_e204_new_tx node-build) || return 1
    _e140_system_snapshot "$tx/system" || {
        _e204_tx_close "$tx" || true
        return 1
    }
    _e204_install_mode_base "$@" || rc=$?
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx" || warn "节点已通过最终导出与运行态验证，但事务活动标记未能关闭：$tx"
        return 0
    fi
    error '节点创建/IPv6/WARP/最终导出没有全部通过，恢复建仓前完整状态。'
    _e140_system_restore "$tx/system" || restore_rc=1
    if test "$restore_rc" -eq 0 && test -s "$CONFIG"; then
        test -x "$XRAY_BIN" && "$XRAY_BIN" version >/dev/null 2>&1 || restore_rc=1
        if test "$restore_rc" -eq 0; then
            _e118_xray_test_config "$CONFIG" 1 || restore_rc=1
        fi
        if test "$restore_rc" -eq 0 && systemctl is-active --quiet xray.service 2>/dev/null; then
            _e127_verify_xray_runtime "$CONFIG" 12 || restore_rc=1
        fi
    fi
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical node-build "$tx/system" 'post-commit rollback/readback failed' || true
        error "严重：节点事务回滚未完整通过；快照：$tx/system"
    else
        info "节点事务已恢复旧配置、核心、WARP/IPv6和服务状态；快照：$tx/system"
    fi
    _e204_tx_close "$tx" || true
    return "$rc"
}

# IPv6 default-disable safety also covers console/cron runs on IPv6-only VPS,
# not merely an already-established IPv6 SSH session.
if declare -F _e182_ipv6_apply >/dev/null 2>&1; then
    eval "$(declare -f _e182_ipv6_apply | sed '1s/_e182_ipv6_apply/_e204_ipv6_apply_base/')"
fi
if declare -F _e182_ipv6_hot_verify >/dev/null 2>&1; then
    eval "$(declare -f _e182_ipv6_hot_verify | sed '1s/_e182_ipv6_hot_verify/_e204_ipv6_hot_verify_base/')"
fi

_e204_ipv4_management_viable() {
    local src
    ip -4 route show default 2>/dev/null | grep -q . || return 1
    src=$(ip -4 route get 1.1.1.1 2>/dev/null | awk '{for(i=1;i<=NF;i++) if($i=="src"){print $(i+1);exit}}')
    test -n "$src" || return 1
    awk -F. 'NF==4{for(i=1;i<=4;i++)if($i!~/^[0-9]+$/||$i>255)exit 1;exit 0}{exit 1}' <<<"$src"
}

_e204_ipv6_pending_write() {
    # Older E182 call sites intentionally passed no reason when an IPv6 SSH
    # session was detected.  Keep that ABI and never trip `set -u` here.
    local reason="${1:-live-ipv6-ssh-session}" tmp
    tmp=$(_e182_secure_state_temp "$E182_IPV6_PENDING") || return 1
    {
        echo 'desired_disable_ipv6=1'
        echo "reason=$reason"
        echo "ssh_connection=${SSH_CONNECTION:-none}"
        echo "checked_at=$(date -Is 2>/dev/null || date)"
    } >"$tmp" || { rm -f -- "$tmp"; return 1; }
    _e182_commit_state "$tmp" "$E182_IPV6_PENDING"
}

_e182_ipv6_apply() {
    local desired="$1" source="${2:-menu}" hot="${3:-0}" override="${4:-}" token=""
    if test "$desired" = 1 && ! _e204_ipv4_management_viable; then
        case "$source" in
            hot-update|install|node-install)
                _e204_ipv6_pending_write no-viable-ipv4-management || return 1
                warn '主机没有可验证的IPv4管理路径；默认关闭IPv6已暂缓，避免IPv6-only VPS失联。'
                return 0
                ;;
            menu)
                warn '主机没有可验证的IPv4默认路由/源地址；关闭IPv6可能令VPS完全失联。'
                read -rp '若已有VNC/串口控制台，输入 DISABLE-IPV6-WITHOUT-IPV4 继续: ' token || true
                test "$token" = DISABLE-IPV6-WITHOUT-IPV4 || return 2
                ;;
            *)
                if test "$override" != DISABLE-IPV6-WITHOUT-IPV4 \
                  && test "${XRAY_E204_ALLOW_IPV6_ONLY_DISABLE:-0}" != 1; then
                    error '拒绝在无IPv4管理路径时关闭IPv6；请从菜单25二次确认或传入安全覆盖令牌。'
                    return 2
                fi
                ;;
        esac
    fi
    _e204_ipv6_apply_base "$desired" "$source" "$hot"
}

_e182_ipv6_hot_verify() {
    if grep -qx 'reason=no-viable-ipv4-management' "$E182_IPV6_PENDING" 2>/dev/null; then
        grep -qx 'desired_disable_ipv6=1' "$E182_IPV6_PENDING" \
            && ! _e204_ipv4_management_viable
        return
    fi
    _e204_ipv6_hot_verify_base "$@"
}

# WARP activation owns Xray config plus service states.  A successful-looking
# xray-wg configuration must also prove real Cloudflare egress.
# Cloudflare One Client may expose both IPv4 and IPv6 loopback listeners.  Xray
# is configured to dial 127.0.0.1, so an IPv4 loopback listener is mandatory;
# an additional [::1] listener is safe, while wildcard/public listeners remain
# fail-closed.  The older exact-single-address test rejected this valid dual
# listener layout and caused the observed port-40000 false failure.
_e186_listener_set_safe() {
    local lines="${1:-}" line addr count=0 have_v4=0
    test -n "$lines" || return 1
    while IFS= read -r line; do
        test -n "$line" || continue
        addr=$(awk '{print $4}' <<<"$line")
        case "$addr" in
            "127.0.0.1:$E138_WARP_PORT") have_v4=1 ;;
            "[::1]:$E138_WARP_PORT") : ;;
            *) return 1 ;;
        esac
        count=$((count+1))
    done <<<"$lines"
    test "$count" -gt 0 && test "$have_v4" -eq 1
}

_e186_warp_port_preflight() {
    local lines trace
    lines=$(_e186_warp_listener_lines 2>/dev/null || true)
    test -z "$lines" && return 0
    if ! _e186_listener_set_safe "$lines"; then
        error "TCP端口$E138_WARP_PORT存在非回环监听，或缺少Xray所需的127.0.0.1监听；拒绝配置Local proxy。"
        sed 's/^/    /' <<<"$lines"
        return 1
    fi
    trace=$(_e186_warp_trace 2>/dev/null || true)
    if _e186_warp_trace_ok "$trace" || _e186_warp_listener_owner_ok "$lines"; then
        return 0
    fi
    error "TCP端口$E138_WARP_PORT仅在回环监听，但无法确认属于warp-svc；拒绝覆盖。"
    sed 's/^/    /' <<<"$lines"
    return 1
}
_e183_warp_port_preflight() { _e186_warp_port_preflight "$@"; }

if declare -F _e186_warp_enable >/dev/null 2>&1; then
    eval "$(declare -f _e186_warp_enable | sed '1s/_e186_warp_enable/_e204_warp_enable_base/')"
fi
if declare -F _e185_warp_health_check >/dev/null 2>&1; then
    eval "$(declare -f _e185_warp_health_check | sed '1s/_e185_warp_health_check/_e204_warp_health_base/')"
fi

_e185_warp_health_check() {
    local enabled backend mode profile family endpoint
    enabled=$(_e138_state_get route_enabled 0)
    test "$enabled" = 1 || return 0
    backend=$(_e138_state_get backend disabled)
    mode=$(_e138_state_get route_mode disabled)
    profile=$(_e138_state_get profile disabled)
    family=$(_e138_state_get family ipv4)
    if test "$backend" = xray-wg; then
        endpoint=$(_e185_state_endpoint)
        test -n "$endpoint" \
            && systemctl is-active --quiet xray.service \
            && _e138_warp_config_integrity "$mode" "$profile" "$family" "$backend" \
            && _e185_wg_probe_endpoint "$endpoint" "$family" || {
                echo "[$(date -Is)] FAIL backend=xray-wg functional-egress" >>"$E138_WARP_LOG"
                return 1
            }
        echo "[$(date -Is)] OK backend=xray-wg functional-egress family=$family" >>"$E138_WARP_LOG"
        return 0
    fi
    _e204_warp_health_base "$@"
}

_e204_warp_package_snapshot() {
    local out="$1" pkg dir base
    : >"$out" || return 1
    for pkg in ca-certificates curl gnupg lsb-release cloudflare-warp; do
        if command -v dpkg-query >/dev/null 2>&1 \
          && dpkg-query -W -f='${Status}' "$pkg" 2>/dev/null \
                | grep -q 'install ok installed'; then
            printf '%s|1\n' "$pkg" >>"$out" || return 1
        else
            printf '%s|0\n' "$pkg" >>"$out" || return 1
        fi
    done
    chmod 0600 "$out" || return 1
    dir=$(dirname -- "$out") || return 1
    base=$(basename -- "$out") || return 1
    (cd "$dir" && sha256sum -- "$base" >"$base.sha256") || return 1
    chmod 0600 "$out.sha256" || return 1
}

_e204_warp_package_restore() {
    local before="$1" pkg was rc=0 dir base
    local -a added=()
    test -s "$before" || return 1
    test -s "$before.sha256" || return 1
    dir=$(dirname -- "$before") || return 1
    base=$(basename -- "$before") || return 1
    (cd "$dir" && sha256sum -c "$base.sha256" >/dev/null 2>&1) || return 1
    while IFS='|' read -r pkg was; do
        case "$pkg" in ca-certificates|curl|gnupg|lsb-release|cloudflare-warp) ;; *) return 1 ;; esac
        test "$was" = 0 || continue
        dpkg-query -W -f='${Status}' "$pkg" 2>/dev/null \
            | grep -q 'install ok installed' && added=("$pkg" "${added[@]}") || true
    done <"$before"
    test "${#added[@]}" -eq 0 \
        || DEBIAN_FRONTEND=noninteractive apt-get purge -y "${added[@]}" \
            >/dev/null 2>&1 || rc=1
    return "$rc"
}

_e185_warp_enable() {
    local tx rc=0 restore_rc=0
    _e204_prepare || return 1
    tx=$(_e204_new_tx warp-enable) || return 1
    _e140_system_snapshot "$tx/system" || { _e204_tx_close "$tx" || true; return 1; }
    _e204_warp_package_snapshot "$tx/warp-packages.before" \
        || { _e204_tx_close "$tx" || true; return 1; }
    _e204_warp_enable_base "$@" || rc=$?
    if test "$rc" -eq 0 && test "$(_e138_state_get route_enabled 0)" = 1; then
        _e185_warp_health_check || rc=1
    fi
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx"
        return $?
    fi
    error 'E204 WARP外层事务未通过，恢复配置、凭据、期望状态和原服务启停状态。'
    _e204_warp_package_restore "$tx/warp-packages.before" || restore_rc=1
    _e140_system_restore "$tx/system" || restore_rc=1
    if systemctl is-active --quiet xray.service 2>/dev/null; then
        systemctl restart xray.service >/dev/null 2>&1 || restore_rc=1
        test ! -s "$CONFIG" || _e127_verify_xray_runtime "$CONFIG" 12 || restore_rc=1
    fi
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical warp-enable "$tx/system" 'outer WARP rollback/readback failed' || true
        error "严重：WARP回滚未完整通过；快照：$tx/system"
    fi
    _e204_tx_close "$tx" || true
    return 1
}
_e186_warp_enable() { _e185_warp_enable "$@"; }

# The inherited E159 full-tunnel commit wrapper treated a user cancellation as
# a successful enable and could then select the newest *old* transaction.  A
# cancellation must be a strict no-op, and a committed full tunnel must point
# to a transaction created by this invocation only.
_e159_warp_full_enable_base() {
    local before after tx rc=0
    before=$(_e118_mktemp warp-full-before-e204) || return 1
    find "$E142_TX_ROOT" "$E140_TX_ROOT" -mindepth 1 -maxdepth 1 -type d \
        -name 'warp-full-enable-*' -print 2>/dev/null | LC_ALL=C sort >"$before" || true

    _e152_warp_full_enable_impl "$@" || rc=$?
    test "$rc" -eq 0 || return "$rc"

    # _e152_warp_full_enable_impl deliberately returns success when the user
    # declines the first confirmation.  No host-full state means no commit.
    _e140_full_mode_active || return 0

    after=$(_e118_mktemp warp-full-after-e204) || return 1
    find "$E142_TX_ROOT" "$E140_TX_ROOT" -mindepth 1 -maxdepth 1 -type d \
        -name 'warp-full-enable-*' -print 2>/dev/null | LC_ALL=C sort >"$after" || true
    tx=$(comm -13 "$before" "$after" | tail -n1)
    test -n "$tx" || {
        error '全隧道显示已启用，但本次调用没有产生独立事务；拒绝借用旧快照。'
        return 1
    }
    _e142_full_snapshot_verify "$tx" || {
        error '全隧道已连接但本次提交快照不可验证，立即回滚。'
        _e140_full_rollback_tx "$tx" || true
        return 1
    }
    _e139_state_set_fields full_commit_tx "$tx" \
        full_committed_at "$(date -Is 2>/dev/null || date)" managed_by e204 || {
        _e140_full_rollback_tx "$tx" || true
        return 1
    }
    info "已记录E204全隧道提交快照：$tx"
}

if declare -F _e140_warp_full_disable >/dev/null 2>&1; then
    eval "$(declare -f _e140_warp_full_disable | sed '1s/_e140_warp_full_disable/_e204_warp_full_disable_base/')"
fi
if declare -F _e140_warp_full_reconcile >/dev/null 2>&1; then
    eval "$(declare -f _e140_warp_full_reconcile | sed '1s/_e140_warp_full_reconcile/_e204_warp_full_reconcile_base/')"
fi
if declare -F _e185_warp_disable >/dev/null 2>&1; then
    eval "$(declare -f _e185_warp_disable | sed '1s/_e185_warp_disable/_e204_warp_disable_base/')"
fi
if declare -F _e185_warp_reconcile >/dev/null 2>&1; then
    eval "$(declare -f _e185_warp_reconcile | sed '1s/_e185_warp_reconcile/_e204_warp_reconcile_base/')"
fi

_e204_xray_runtime_readback() {
    test -s "$CONFIG" || return 0
    _e118_xray_test_config "$CONFIG" 1 || return 1
    if systemctl is-active --quiet xray.service 2>/dev/null; then
        _e127_verify_xray_runtime "$CONFIG" 12 || return 1
    fi
}

_e204_warp_outer_restore() {
    local snapshot="$1" restore_mode="${2:-disabled}" rc=0
    _e140_full_route_cleanup
    _e140_system_restore "$snapshot" || rc=1
    if test "$rc" -eq 0; then
        case "$restore_mode" in
            host-full) _e204_warp_full_reconcile_base || rc=1 ;;
            selective|global) _e204_warp_reconcile_base || rc=1 ;;
        esac
    fi
    test "$rc" -ne 0 || _e204_xray_runtime_readback || rc=1
    return "$rc"
}

# Full-tunnel enable already has an SSH confirmation timer.  E204 adds a
# second, sealed system transaction so package/repository/service/Xray state is
# restored even when an inherited rollback path itself fails.
_e140_warp_full_enable() {
    local tx old_mode rc=0 restore_rc=0
    old_mode=$(_e138_state_get route_mode disabled)
    tx=$(_e204_new_tx warp-full-enable-outer) || return 1
    _e140_system_snapshot "$tx/system" || { _e204_tx_close "$tx" || true; return 1; }
    _e204_warp_package_snapshot "$tx/warp-packages.before" \
        || { _e204_tx_close "$tx" || true; return 1; }

    _e159_warp_full_enable_base "$@" || rc=$?
    if test "$rc" -eq 0; then
        # A declined confirmation is a clean no-op.  A real commit is accepted
        # only after one more route/service/egress readback.
        if ! _e140_full_mode_active; then
            _e204_tx_close "$tx"
            return $?
        fi
        _e140_full_verify \
            "$(_e138_state_get full_service_mode traffic-only)" \
            "$(_e138_state_get full_protocol MASQUE)" || rc=1
    fi
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx"
        return $?
    fi

    error 'E204系统全隧道启用事务失败，恢复启用前完整系统状态。'
    _e140_warp_cli disconnect >/dev/null 2>&1 || true
    _e140_full_route_cleanup
    _e204_warp_package_restore "$tx/warp-packages.before" || restore_rc=1
    _e204_warp_outer_restore "$tx/system" "$old_mode" || restore_rc=1
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical warp-full-enable "$tx/system" \
            'full-tunnel outer rollback/readback failed' || true
        error "严重：系统全隧道回滚未完整通过；快照：$tx/system"
    fi
    _e204_tx_close "$tx" || true
    return 1
}

_e140_warp_full_disable() {
    local internal="${1:-}" token="" tx old_mode rc=0 restore_rc=0
    if test "$internal" != force; then
        read -rp '输入 DISABLE-CLOUDFLARE-FULL-TUNNEL 确认: ' token || true
        test "$token" = DISABLE-CLOUDFLARE-FULL-TUNNEL || return 0
    fi
    _e140_full_mode_active || {
        info 'Cloudflare系统全隧道当前未启用；未改动WARP或宿主机网络。'
        return 0
    }
    old_mode=$(_e138_state_get route_mode host-full)
    tx=$(_e204_new_tx warp-full-disable) || return 1
    _e140_system_snapshot "$tx/system" || { _e204_tx_close "$tx" || true; return 1; }
    _e204_warp_full_disable_base force || rc=1
    test "$rc" -ne 0 || ! _e140_full_mode_active || rc=1
    test "$rc" -ne 0 || ! ip -4 rule show 2>/dev/null \
        | grep -Eq "^${E140_FULL_RULE_PRIORITY}:" || rc=1
    test "$rc" -ne 0 || ! ip -4 route show table "$E140_FULL_TABLE" \
        2>/dev/null | grep -q . || rc=1
    test "$rc" -ne 0 || _e138_warp_config_integrity disabled disabled disabled disabled || rc=1
    test "$rc" -ne 0 || _e204_xray_runtime_readback || rc=1
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx"
        return $?
    fi

    error 'E204系统全隧道关闭未通过读回，恢复关闭前状态。'
    _e204_warp_outer_restore "$tx/system" "$old_mode" || restore_rc=1
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical warp-full-disable "$tx/system" \
            'full-tunnel disable rollback/readback failed' || true
        error "严重：系统全隧道关闭回滚未完整通过；快照：$tx/system"
    fi
    _e204_tx_close "$tx" || true
    return 1
}

_e140_warp_full_reconcile() {
    local tx old_mode rc=0 restore_rc=0
    _e140_full_mode_active || return 0
    old_mode=$(_e138_state_get route_mode host-full)
    tx=$(_e204_new_tx warp-full-reconcile) || return 1
    _e140_system_snapshot "$tx/system" || { _e204_tx_close "$tx" || true; return 1; }
    _e204_warp_full_reconcile_base || rc=1
    test "$rc" -ne 0 || _e140_full_verify \
        "$(_e138_state_get full_service_mode traffic-only)" \
        "$(_e138_state_get full_protocol MASQUE)" || rc=1
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx"
        return $?
    fi
    error 'E204系统全隧道修复失败，恢复修复前状态。'
    _e204_warp_outer_restore "$tx/system" "$old_mode" || restore_rc=1
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical warp-full-reconcile "$tx/system" \
            'full-tunnel reconcile rollback/readback failed' || true
        error "严重：系统全隧道修复回滚未完整通过；快照：$tx/system"
    fi
    _e204_tx_close "$tx" || true
    return 1
}

_e185_warp_disable() {
    local tx old_mode rc=0 restore_rc=0
    old_mode=$(_e138_state_get route_mode disabled)
    test "$old_mode" != host-full || { _e140_warp_full_disable force; return $?; }
    tx=$(_e204_new_tx warp-local-disable) || return 1
    _e140_system_snapshot "$tx/system" || { _e204_tx_close "$tx" || true; return 1; }
    _e204_warp_disable_base || rc=1
    test "$rc" -ne 0 || test "$(_e138_state_get route_enabled 0)" = 0 || rc=1
    test "$rc" -ne 0 || _e138_warp_config_integrity disabled disabled disabled disabled || rc=1
    test "$rc" -ne 0 || _e204_xray_runtime_readback || rc=1
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx"
        return $?
    fi
    error 'E204 Xray层WARP关闭未通过读回，恢复关闭前状态。'
    _e204_warp_outer_restore "$tx/system" "$old_mode" || restore_rc=1
    test "$restore_rc" -eq 0 || {
        _e204_mark_critical warp-local-disable "$tx/system" \
            'local WARP disable rollback/readback failed' || true
        error "严重：Xray层WARP关闭回滚未完整通过；快照：$tx/system"
    }
    _e204_tx_close "$tx" || true
    return 1
}

_e185_warp_reconcile() {
    local tx old_mode rc=0 restore_rc=0
    old_mode=$(_e138_state_get route_mode disabled)
    test "$old_mode" != host-full || { _e140_warp_full_reconcile; return $?; }
    tx=$(_e204_new_tx warp-local-reconcile) || return 1
    _e140_system_snapshot "$tx/system" || { _e204_tx_close "$tx" || true; return 1; }
    _e204_warp_package_snapshot "$tx/warp-packages.before" \
        || { _e204_tx_close "$tx" || true; return 1; }
    _e204_warp_reconcile_base || rc=1
    if test "$rc" -eq 0 && test "$(_e138_state_get route_enabled 0)" = 1; then
        _e185_warp_health_check || rc=1
    fi
    test "$rc" -ne 0 || _e204_xray_runtime_readback || rc=1
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx"
        return $?
    fi
    error 'E204 Xray层WARP修复失败，恢复修复前状态。'
    _e204_warp_package_restore "$tx/warp-packages.before" || restore_rc=1
    _e204_warp_outer_restore "$tx/system" "$old_mode" || restore_rc=1
    test "$restore_rc" -eq 0 || {
        _e204_mark_critical warp-local-reconcile "$tx/system" \
            'local WARP reconcile rollback/readback failed' || true
        error "严重：Xray层WARP修复回滚未完整通过；快照：$tx/system"
    }
    _e204_tx_close "$tx" || true
    return 1
}

# DAT pair commit: if either download or either file commit fails, neither new
# resource is retained.  This patch is installed before the updater's first
# immediate execution.
_e204_patch_dat_pair() {
    local tmp
    test -x "$UPDATE_DAT_SCRIPT" || return 1
    grep -q 'E204 atomic geoip/geosite pair v1' "$UPDATE_DAT_SCRIPT" 2>/dev/null && return 0
    tmp=$(_e118_mktemp update-dat-e204.sh) || return 1
    awk '
      /^rollback_dat\(\)[[:space:]]*\{/ && !download_gate {
        print "# E204 atomic geoip/geosite pair v1"
        print "if test \"$ok\" -ne 0 || test ! -s \"$TMP/geoip.dat\" || test ! -s \"$TMP/geosite.dat\"; then"
        print "    log \"WARN DAT资源未成对下载完成；本次不提交任何文件\""
        print "    exit 1"
        print "fi"
        download_gate=1
      }
      /^changed=0$/ {in_commit=1}
      in_commit && /^done$/ && !commit_gate {
        print
        print "if test \"$ok\" -ne 0; then"
        print "    log \"ERROR DAT成对提交失败，恢复两份旧资源\""
        print "    if ! rollback_dat; then log \"CRITICAL DAT成对回滚失败\"; fi"
        print "    exit 1"
        print "fi"
        commit_gate=1
        next
      }
      {print}
      END {if(!download_gate || !commit_gate) exit 42}
    ' "$UPDATE_DAT_SCRIPT" >"$tmp" || return 1
    bash -n "$tmp" || return 1
    E204_DAT_PATCHING=1 _e204_atomic_install_base "$tmp" "$UPDATE_DAT_SCRIPT" 0755
}

if declare -F _e118_atomic_install >/dev/null 2>&1; then
    eval "$(declare -f _e118_atomic_install | sed '1s/_e118_atomic_install/_e204_atomic_install_base/')"
fi
_e118_atomic_install() {
    local src="$1" dst="$2" mode="${3:-0644}"
    _e204_atomic_install_base "$src" "$dst" "$mode" || return 1
    if test "$dst" = "$UPDATE_DAT_SCRIPT" && test "${E204_DAT_PATCHING:-0}" != 1; then
        E204_DAT_PATCHING=1 _e142_patch_dat_updater || return 1
        E204_DAT_PATCHING=1 _e204_patch_dat_pair || return 1
    fi
}

_e204_dat_existing_pair_usable() {
    local probe geoip_size geosite_size
    test -x "$UPDATE_DAT_SCRIPT" && bash -n "$UPDATE_DAT_SCRIPT" || return 1
    test -x "$XRAY_BIN" || return 1
    test -r "$DAT_DIR/geoip.dat" && test -r "$DAT_DIR/geosite.dat" || return 1
    geoip_size=$(stat -c '%s' "$DAT_DIR/geoip.dat" 2>/dev/null || true)
    geosite_size=$(stat -c '%s' "$DAT_DIR/geosite.dat" 2>/dev/null || true)
    [[ "$geoip_size" =~ ^[0-9]+$ && "$geosite_size" =~ ^[0-9]+$ ]] || return 1
    test "$geoip_size" -gt 1024 && test "$geosite_size" -gt 1024 || return 1
    systemctl is-enabled --quiet xray-dat-update.timer 2>/dev/null || return 1
    systemctl is-active --quiet xray-dat-update.timer 2>/dev/null || return 1
    probe=$(_e118_mktemp e204-dat-existing-probe.json) || return 1
    cat >"$probe" <<'EOF_E204_DAT_EXISTING_PROBE'
{"log":{"loglevel":"none"},"inbounds":[],"outbounds":[{"protocol":"freedom","tag":"direct"}],"routing":{"domainStrategy":"AsIs","rules":[{"ip":["geoip:private"],"outboundTag":"direct"},{"domain":["geosite:category-ads-all"],"outboundTag":"direct"}]}}
EOF_E204_DAT_EXISTING_PROBE
    "$XRAY_BIN" run -test -config "$probe" >/dev/null 2>&1 || return 1
    test ! -s "$CONFIG" || _e118_xray_test_config "$CONFIG" 1
}

install_update_dat() {
    local rc=0
    _e118_impl_install_update_dat "$@" || rc=$?
    test "$rc" -eq 0 && return 0
    if _e204_dat_existing_pair_usable; then
        warn '本次联网DAT下载失败；现有geoip/geosite成对可用且定时器正常，保留旧资源并降级继续。'
        return 0
    fi
    error 'DAT安装/即时更新失败，且现有成对资源无法通过Xray探针。'
    return "$rc"
}

# Separate micro-menu handlers.  Every mutation still passes the inherited
# Xray candidate test and runtime rollback gate.
_e204_action_socket_keepalive() {
    _safe_jq_write '
      (.outbounds[]? | select(.protocol=="freedom" or .protocol=="vless" or .protocol=="shadowsocks")) |= (
        .streamSettings = (.streamSettings // {}) |
        .streamSettings.sockopt = (.streamSettings.sockopt // {}) |
        .streamSettings.sockopt.tcpKeepAliveIdle = 30 |
        .streamSettings.sockopt.tcpKeepAliveInterval = 15
      )'
}
_e204_action_metadata_only() {
    _safe_jq_write '(.inbounds[]? | select(.protocol=="vless")) |= (.sniffing=(.sniffing//{}) | .sniffing.enabled=true | .sniffing.metadataOnly=true)'
}
_e204_action_route_only() {
    _safe_jq_write '(.inbounds[]? | select(.protocol=="vless")) |= (.sniffing=(.sniffing//{}) | .sniffing.enabled=true | .sniffing.routeOnly=true)'
}
_e204_remove_xray_env_buffer() {
    local f tmp mode owner changed=0
    while IFS= read -r -d '' f; do
        grep -Fq 'XRAY_RAY_BUFFER_SIZE' "$f" 2>/dev/null || continue
        if test -L "$f" || test ! -f "$f"; then
            error "Xray环境文件不是可安全改写的普通文件：$f"
            return 1
        fi
        owner=$(stat -c '%u' "$f" 2>/dev/null || echo -1)
        mode=$(stat -c '%a' "$f" 2>/dev/null || echo 777)
        test "$owner" = 0 && [[ "$mode" =~ ^[0-7]{3,4}$ ]] \
          && test $((8#$mode & 0022)) -eq 0 || {
            error "Xray环境文件所有者/权限不安全：$f"
            return 1
        }
        tmp=$(_e118_mktemp e204-xray-env-buffer) || return 1
        awk 'index($0,"XRAY_RAY_BUFFER_SIZE")==0{print}' "$f" >"$tmp" || return 1
        _e118_atomic_install "$tmp" "$f" "$mode" || return 1
        ! grep -Fq 'XRAY_RAY_BUFFER_SIZE' "$f" || return 1
        changed=1
    done < <(
        {
            test ! -e /etc/systemd/system/xray.service \
                || printf '%s\0' /etc/systemd/system/xray.service
            test ! -d /etc/systemd/system/xray.service.d \
                || find -P /etc/systemd/system/xray.service.d -maxdepth 2 \
                    \( -type f -o -type l \) -print0 2>/dev/null
        }
    )
    test "$changed" -eq 0 || systemctl daemon-reload >/dev/null 2>&1
}

_e204_action_buffer_128() {
    local tx rc=0 restore_rc=0
    tx=$(_e204_new_tx xray-buffer-128) || return 1
    _e140_system_snapshot "$tx/system" || { _e204_tx_close "$tx" || true; return 1; }
    _safe_jq_write '.policy=(.policy//{}) | .policy.levels=(.policy.levels//{}) | .policy.levels["0"]=((.policy.levels["0"]//{})+{bufferSize:128})' \
        || rc=1
    test "$rc" -ne 0 || _e204_remove_xray_env_buffer || rc=1
    if test "$rc" -eq 0 && systemctl is-active --quiet xray.service 2>/dev/null; then
        systemctl restart xray.service >/dev/null 2>&1 || rc=1
        test "$rc" -ne 0 || _e127_verify_xray_runtime "$CONFIG" 12 || rc=1
    fi
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx"
        return $?
    fi
    error 'Xray 128KB缓冲事务未通过，恢复配置、systemd环境和运行状态。'
    _e140_system_restore "$tx/system" || restore_rc=1
    if test "$restore_rc" -eq 0 && systemctl is-active --quiet xray.service 2>/dev/null; then
        systemctl restart xray.service >/dev/null 2>&1 || restore_rc=1
        test "$restore_rc" -ne 0 || _e127_verify_xray_runtime "$CONFIG" 12 || restore_rc=1
    fi
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical xray-buffer-128 "$tx/system" 'buffer rollback/readback failed' || true
        error "严重：Xray 128KB缓冲回滚未完整通过；快照：$tx/system"
    fi
    _e204_tx_close "$tx" || true
    return 1
}
_e204_action_dns_ipv4() {
    _safe_jq_write '.dns=(.dns//{}) | .dns.queryStrategy="UseIPv4"'
}

# Dnsmasq changes the host resolver and two resolver services, so an Xray-only
# snapshot is insufficient.  Preserve the resolv.conf symlink and immutable bit.
if declare -F enable_dnsmasq_cache_safely >/dev/null 2>&1; then
    eval "$(declare -f enable_dnsmasq_cache_safely | sed '1s/enable_dnsmasq_cache_safely/_e204_dnsmasq_base/')"
fi
enable_dnsmasq_cache_safely() {
    local tx target snap rc=0 restore_rc=0 immutable=0 preinstalled=0
    local -a files=(/etc/resolv.conf /etc/dnsmasq.conf "${E67_DNS_MODE_FILE:-$CONFIG_DIR/dns_mode.txt}")
    local -a units=(dnsmasq.service systemd-resolved.service resolvconf.service)
    tx=$(_e204_new_tx dnsmasq) || return 1
    : >"$tx/services.before" || { _e204_tx_close "$tx" || true; return 1; }
    lsattr -d /etc/resolv.conf 2>/dev/null | awk '{print $1}' | grep -q i && immutable=1 || true
    for target in "${files[@]}"; do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
        _e135_snapshot_file "$target" "$snap" || {
            _e204_tx_close "$tx" || true
            return 1
        }
    done
    for target in "${units[@]}"; do
        _e204_service_snapshot "$target" >>"$tx/services.before" || {
            _e204_tx_close "$tx" || true
            return 1
        }
    done
    dpkg-query -W -f='${Status}' dnsmasq 2>/dev/null | grep -q 'install ok installed' && preinstalled=1 || true
    _e204_dnsmasq_base || rc=$?
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx"
        return $?
    fi
    chattr -i /etc/resolv.conf >/dev/null 2>&1 || true
    # Purging after restoring /etc/dnsmasq.conf can delete the restored user
    # file.  Remove a package introduced by this transaction first, then put
    # every file, symlink and service state back exactly as snapshotted.
    if test "$preinstalled" -eq 0 \
      && dpkg-query -W -f='${Status}' dnsmasq 2>/dev/null | grep -q 'install ok installed'; then
        DEBIAN_FRONTEND=noninteractive apt-get purge -y dnsmasq >/dev/null 2>&1 || restore_rc=1
    fi
    for target in "${files[@]}"; do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
        _e135_restore_file "$target" "$snap" || restore_rc=1
    done
    _e204_services_restore_file "$tx/services.before" || restore_rc=1
    test "$immutable" -eq 0 || chattr +i /etc/resolv.conf >/dev/null 2>&1 || restore_rc=1
    test "$restore_rc" -eq 0 || _e204_mark_critical dnsmasq "$tx" 'resolver rollback failed' || true
    _e204_tx_close "$tx" || true
    return 1
}

# Non-destructive ZRAM/swap transaction: prove the replacement first and never
# disable an existing user swap merely to satisfy a cosmetic 1-GiB cap.
_e204_swap_state_value() {
    local key="$1" default="${2:-}" value
    value=$(awk -F= -v k="$key" '$1==k{print substr($0,index($0,"=")+1);exit}' \
        "$E204_ZRAM_STATE" 2>/dev/null || true)
    printf '%s\n' "${value:-$default}"
}

_e204_swap_owned() {
    local want_kind="$1" want_device="$2" kind device
    grep -qx 'owned_by=e204' "$E204_ZRAM_STATE" 2>/dev/null || return 1
    kind=$(_e204_swap_state_value kind '')
    device=$(_e204_swap_state_value device '')
    # E204早期ZRAM状态没有kind；只对精确/dev/zram0做向后兼容。
    if test -z "$kind"; then
        test "$device" = /dev/zram0 || return 1
        kind=zram
    fi
    test "$kind" = "$want_kind" && test "$device" = "$want_device"
}

_e204_swap_state_write() {
    local kind="$1" device="$2" tmp
    case "$kind:$device" in
        zram:/dev/zram0|swapfile:"$E204_SWAPFILE") ;;
        *) return 1 ;;
    esac
    tmp=$(_e118_mktemp e204-swap-owner) || return 1
    {
        echo 'owned_by=e204'
        echo "kind=$kind"
        echo "device=$device"
        echo "created_at=$(date -Is 2>/dev/null || date)"
    } >"$tmp" || return 1
    _e118_atomic_install "$tmp" "$E204_ZRAM_STATE" 0600
}

_e204_legacy_swapfile_owned() {
    test -f "$E204_SWAPFILE" && test ! -L "$E204_SWAPFILE" || return 1
    test "$(stat -c '%u:%a' "$E204_SWAPFILE" 2>/dev/null || true)" = 0:600 || return 1
    awk -v p="$E204_SWAPFILE" '$1==p && $3=="swap"{found=1} END{exit !found}' /etc/fstab 2>/dev/null
}

_e204_swapfile_activate() {
    local free_mb tmpfstab tmpfile created=0 active=0
    swapon --show=NAME --noheadings 2>/dev/null | awk '{$1=$1}1' \
        | grep -Fxq "$E204_SWAPFILE" && active=1 || true
    if test "$active" -eq 1 && ! _e204_swap_owned swapfile "$E204_SWAPFILE" \
      && ! _e204_legacy_swapfile_owned; then
        error "检测到活动的$E204_SWAPFILE，但没有E204所有权证据；拒绝接管。"
        return 1
    fi
    if swapon --show=NAME --noheadings 2>/dev/null | grep -q .; then
        if test "$active" -ne 1; then
            warn '检测到现有Swap；E204不会关闭或替换用户Swap。'
            return 0
        fi
    fi
    if test -e "$E204_SWAPFILE" && test "$active" -ne 1 \
      && ! _e204_swap_owned swapfile "$E204_SWAPFILE" \
      && ! _e204_legacy_swapfile_owned; then
        error "发现同名但不属于E204的文件，拒绝覆盖：$E204_SWAPFILE"
        return 1
    fi
    if test ! -e "$E204_SWAPFILE"; then
        free_mb=$(df -Pm / 2>/dev/null | awk 'NR==2{print int($4)}')
        [[ "$free_mb" =~ ^[0-9]+$ ]] && test "$free_mb" -ge 1300 \
            || { error '空间不足，未创建1GiB swapfile。'; return 1; }
        tmpfile="${E204_SWAPFILE}.new.$$"
        test ! -e "$tmpfile" || { error "临时Swap文件已存在：$tmpfile"; return 1; }
        if command -v fallocate >/dev/null 2>&1; then
            fallocate -l 1024M "$tmpfile" || { rm -f -- "$tmpfile"; return 1; }
        else
            dd if=/dev/zero of="$tmpfile" bs=1M count=1024 status=none || { rm -f -- "$tmpfile"; return 1; }
        fi
        chmod 0600 "$tmpfile" || { rm -f -- "$tmpfile"; return 1; }
        mkswap "$tmpfile" >/dev/null 2>&1 || { rm -f -- "$tmpfile"; return 1; }
        mv -f -- "$tmpfile" "$E204_SWAPFILE" || { rm -f -- "$tmpfile"; return 1; }
        created=1
    else
        test -f "$E204_SWAPFILE" && test ! -L "$E204_SWAPFILE" \
            && test "$(stat -c '%u:%a' "$E204_SWAPFILE" 2>/dev/null || true)" = 0:600 \
            || { error 'E204 Swap文件属性不安全。'; return 1; }
    fi
    if test "$active" -ne 1; then
        swapon -p 10 "$E204_SWAPFILE" >/dev/null 2>&1 || {
            test "$created" -eq 0 || rm -f -- "$E204_SWAPFILE"
            return 1
        }
    fi
    swapon --show=NAME --noheadings | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE" || {
        test "$created" -eq 0 || rm -f -- "$E204_SWAPFILE"
        return 1
    }
    tmpfstab=$(_e118_mktemp e204-fstab) || return 1
    awk -v p="$E204_SWAPFILE" '$1!=p{print}' /etc/fstab >"$tmpfstab" || return 1
    printf '%s none swap sw,nofail 0 0\n' "$E204_SWAPFILE" >>"$tmpfstab"
    _e118_atomic_install "$tmpfstab" /etc/fstab 0644 || return 1
    _e204_swap_state_write swapfile "$E204_SWAPFILE"
}

_e204_zram_activate() {
    local script_tmp unit_tmp state_tmp disksize=0
    if swapon --show=NAME --noheadings 2>/dev/null | awk '{$1=$1}1' | grep -E '^/dev/zram' | grep -Fvx /dev/zram0 | grep -q .; then
        error '检测到非E204的活动ZRAM设备；拒绝重置用户ZRAM。'
        return 1
    fi
    if swapon --show=NAME --noheadings 2>/dev/null | awk '{$1=$1}1' | grep -Fxq /dev/zram0 \
      && ! _e204_swap_owned zram /dev/zram0; then
        warn '检测到用户已有/dev/zram0；E204不接管、不覆盖，也不写入伪所有权。'
        return 0
    fi
    if test -r /sys/block/zram0/disksize && ! _e204_swap_owned zram /dev/zram0; then
        disksize=$(cat /sys/block/zram0/disksize 2>/dev/null || echo 0)
        [[ "$disksize" =~ ^[0-9]+$ ]] || disksize=0
        if test "$disksize" -gt 0; then
            warn '检测到未激活但已配置的用户/dev/zram0；E204不重置该设备。'
            return 0
        fi
    fi
    script_tmp=$(_e118_mktemp e204-zram.sh) || return 1
    unit_tmp=$(_e118_mktemp e204-zram.service) || return 1
    cat >"$script_tmp" <<'EOF_E204_ZRAM_SCRIPT'
#!/usr/bin/env bash
set -euo pipefail
modprobe zram num_devices=1
if swapon --show=NAME --noheadings | awk '{$1=$1}1' | grep -Fxq /dev/zram0; then exit 0; fi
test -e /sys/block/zram0/disksize
echo lz4 > /sys/block/zram0/comp_algorithm 2>/dev/null || true
echo 1024M > /sys/block/zram0/disksize
mkswap /dev/zram0 >/dev/null
swapon -p 100 /dev/zram0
swapon --show=NAME --noheadings | awk '{$1=$1}1' | grep -Fxq /dev/zram0
EOF_E204_ZRAM_SCRIPT
    cat >"$unit_tmp" <<EOF_E204_ZRAM_UNIT
[Unit]
Description=Xray E204 non-destructive 1GiB ZRAM
After=local-fs.target
[Service]
Type=oneshot
ExecStart=$E204_ZRAM_SCRIPT
RemainAfterExit=yes
[Install]
WantedBy=multi-user.target
EOF_E204_ZRAM_UNIT
    bash -n "$script_tmp" || return 1
    _e118_atomic_install "$script_tmp" "$E204_ZRAM_SCRIPT" 0755 || return 1
    _e118_atomic_install "$unit_tmp" "$E204_ZRAM_SERVICE" 0644 || return 1
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    systemctl enable --now "$E204_ZRAM_UNIT" >/dev/null 2>&1 || return 1
    swapon --show=NAME --noheadings | awk '{$1=$1}1' | grep -Fxq /dev/zram0 || return 1
    state_tmp=$(_e118_mktemp e204-zram-owner) || return 1
    {
        echo 'owned_by=e204'
        echo 'kind=zram'
        echo 'device=/dev/zram0'
        echo "created_at=$(date -Is 2>/dev/null || date)"
    } >"$state_tmp" || return 1
    _e118_atomic_install "$state_tmp" "$E204_ZRAM_STATE" 0600
}

enable_zram_default() {
    local tx rc=0 restore_rc=0 was_zram=0 was_swap=0 had_swapfile=0
    tx=$(_e204_new_tx swap-zram) || return 1
    _e135_snapshot_file /etc/fstab "$tx/fstab" \
        || { _e204_tx_close "$tx" || true; return 1; }
    _e135_snapshot_file /etc/sysctl.d/98-xray-swap.conf "$tx/sysctl" \
        || { _e204_tx_close "$tx" || true; return 1; }
    _e135_snapshot_file "$E204_ZRAM_SCRIPT" "$tx/zram-script" \
        || { _e204_tx_close "$tx" || true; return 1; }
    _e135_snapshot_file "$E204_ZRAM_SERVICE" "$tx/zram-service" \
        || { _e204_tx_close "$tx" || true; return 1; }
    _e135_snapshot_file "$E204_ZRAM_STATE" "$tx/zram-state" \
        || { _e204_tx_close "$tx" || true; return 1; }
    _e204_service_snapshot "$E204_ZRAM_UNIT" >"$tx/service.before" \
        || { _e204_tx_close "$tx" || true; return 1; }
    swapon --show=NAME --noheadings 2>/dev/null | awk '{$1=$1}1' | grep -Fxq /dev/zram0 && was_zram=1 || true
    swapon --show=NAME --noheadings 2>/dev/null | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE" && was_swap=1 || true
    test -e "$E204_SWAPFILE" && had_swapfile=1 || true
    if _zram_supported; then _e204_zram_activate || rc=1; else _e204_swapfile_activate || rc=1; fi
    if test "$rc" -eq 0 \
      && ! swapon --show=NAME --noheadings 2>/dev/null | grep -q '[^[:space:]]'; then
        error 'ZRAM/Swap入口返回成功，但系统没有任何活动Swap；拒绝假成功。'
        rc=1
    fi
    test "$rc" -ne 0 || _write_swap_sysctl_e52 || rc=1
    if test "$rc" -eq 0; then
        info 'ZRAM/Swap事务通过；原有用户Swap未被关闭或删除。'
        _e204_tx_close "$tx"
        return $?
    fi
    if test "$was_zram" -eq 0; then
        swapoff /dev/zram0 >/dev/null 2>&1 || true
        command -v zramctl >/dev/null 2>&1 && zramctl --reset /dev/zram0 >/dev/null 2>&1 || true
    fi
    if test "$was_swap" -eq 0 \
      && swapon --show=NAME --noheadings 2>/dev/null | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE"; then
        swapoff "$E204_SWAPFILE" >/dev/null 2>&1 || restore_rc=1
    fi
    if test "$had_swapfile" -eq 0 && test -e "$E204_SWAPFILE"; then
        rm -f -- "$E204_SWAPFILE" || restore_rc=1
    fi
    _e135_restore_file /etc/fstab "$tx/fstab" || restore_rc=1
    _e135_restore_file /etc/sysctl.d/98-xray-swap.conf "$tx/sysctl" || restore_rc=1
    _e135_restore_file "$E204_ZRAM_SCRIPT" "$tx/zram-script" || restore_rc=1
    _e135_restore_file "$E204_ZRAM_SERVICE" "$tx/zram-service" || restore_rc=1
    _e135_restore_file "$E204_ZRAM_STATE" "$tx/zram-state" || restore_rc=1
    _e204_services_restore_file "$tx/service.before" || restore_rc=1
    if test "$was_swap" -eq 1 \
      && ! swapon --show=NAME --noheadings 2>/dev/null | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE"; then
        swapon -p 10 "$E204_SWAPFILE" >/dev/null 2>&1 || restore_rc=1
    fi
    test "$restore_rc" -eq 0 || _e204_mark_critical swap-zram "$tx" 'swap rollback failed' || true
    _e204_tx_close "$tx" || true
    return 1
}

# Route all visible TC entries to the newest transactional implementation.  If
# an unmanaged root qdisc cannot be reconstructed safely, refuse mutation.
if declare -F _e168_tc_tx_begin >/dev/null 2>&1; then
    eval "$(declare -f _e168_tc_tx_begin | sed '1s/_e168_tc_tx_begin/_e204_tc_tx_begin_base/')"
fi
_e204_tc_conf_secure() {
    local owner mode
    test -e "$E95_TC_CONF" || return 0
    test -f "$E95_TC_CONF" && test ! -L "$E95_TC_CONF" || return 1
    owner=$(stat -c '%u' "$E95_TC_CONF" 2>/dev/null || echo -1)
    mode=$(stat -c '%a' "$E95_TC_CONF" 2>/dev/null || echo 777)
    test "$owner" = 0 || return 1
    [[ "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
    test $((8#$mode & 0022)) -eq 0 || return 1
    awk '
      /^[[:space:]]*($|#)/ {next}
      /^TC_ENABLE=[01]$/ {next}
      /^TC_IFACE="[A-Za-z0-9_.:-]{1,32}"$/ {next}
      /^TC_EGRESS_MBIT="[0-9]*"$/ {next}
      /^TC_LEAF_QDISC="(fq|fq_codel)"$/ {next}
      /^TC_RESTORE_QDISC="(fq|fq_codel|pfifo_fast|cake)"$/ {next}
      /^TC_MODE="egress-htb-fq"$/ {next}
      {bad=1}
      END {exit bad?1:0}
    ' "$E95_TC_CONF"
}

# Merely opening menu 20 used to rewrite the TC script/unit before any TC
# transaction existed.  Wrap component generation itself so a syntax,
# ownership or daemon-reload failure restores the prior component verbatim.
if declare -F _e95_install_tc_component >/dev/null 2>&1; then
    eval "$(declare -f _e95_install_tc_component | sed '1s/_e95_install_tc_component/_e204_tc_install_base/')"
fi
_e95_install_tc_component() {
    local tx target snap unit load enabled active rc=0 restore_rc=0
    # An intact component is already a committed state.  Do not rewrite its
    # script/unit/config merely because a caller wants to display the menu.
    if _e168_tc_component_ready && _e204_tc_conf_secure \
      && grep -Fqx "ExecStart=$E95_TC_SCRIPT apply" "$E95_TC_SERVICE" \
      && grep -Fqx "ExecStop=$E95_TC_SCRIPT stop" "$E95_TC_SERVICE"; then
        return 0
    fi
    tx=$(_e204_new_tx tc-component) || return 1
    for target in "$E95_TC_SCRIPT" "$E95_TC_SERVICE" "$E95_TC_CONF"; do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
        _e135_snapshot_file "$target" "$snap" || {
            _e204_tx_close "$tx" || true
            return 1
        }
    done
    _e204_service_snapshot xray-tc-limit-e95.service >"$tx/service.before" \
        || { _e204_tx_close "$tx" || true; return 1; }
    _e204_tc_install_base || rc=1
    test "$rc" -ne 0 || _e168_tc_component_ready || rc=1
    test "$rc" -ne 0 || _e204_tc_conf_secure || rc=1
    test "$rc" -ne 0 || grep -Fqx "ExecStart=$E95_TC_SCRIPT apply" "$E95_TC_SERVICE" || rc=1
    test "$rc" -ne 0 || grep -Fqx "ExecStop=$E95_TC_SCRIPT stop" "$E95_TC_SERVICE" || rc=1
    if test "$rc" -eq 0 && command -v systemd-analyze >/dev/null 2>&1; then
        systemd-analyze verify "$E95_TC_SERVICE" >/dev/null 2>&1 || rc=1
    fi
    test "$rc" -ne 0 || systemctl daemon-reload >/dev/null 2>&1 || rc=1
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx"
        return $?
    fi
    error 'TC组件生成/读回失败，恢复进入菜单前的脚本、配置和服务状态。'
    for target in "$E95_TC_SCRIPT" "$E95_TC_SERVICE" "$E95_TC_CONF"; do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
        _e135_restore_file "$target" "$snap" || restore_rc=1
    done
    _e204_services_restore_file "$tx/service.before" || restore_rc=1
    test "$restore_rc" -eq 0 || _e204_mark_critical tc-component "$tx" 'component rollback failed' || true
    _e204_tx_close "$tx" || true
    return 1
}

_e168_tc_tx_begin() {
    local purpose="$1" iface line kind active=0 tx
    _e204_tc_conf_secure || {
        error "TC配置不是root只写的已知格式，拒绝source/应用：$E95_TC_CONF"
        return 1
    }
    iface=$(_e95_default_iface 2>/dev/null || true)
    test -n "$iface" || { error '未发现默认出口网卡，拒绝TC事务。'; return 1; }
    line=$(_e95_root_qdisc_line "$iface")
    kind=$(awk '{print $2;exit}' <<<"$line")
    systemctl is-active --quiet xray-tc-limit-e95.service 2>/dev/null && active=1 || true
    if test "$active" -eq 0; then
        case "$kind" in fq|fq_codel|cake|pfifo_fast|noqueue|mq|'') ;;
            *) error "当前root qdisc由其它工具管理且无法无损重建：${line:-unknown}"; return 1 ;;
        esac
    fi
    tx=$(_e204_tc_tx_begin_base "$purpose") || return 1
    {
        echo "iface=$iface"
        echo "root_before=$line"
        tc -j qdisc show dev "$iface" 2>/dev/null || true
        tc -j class show dev "$iface" 2>/dev/null || true
        tc -j filter show dev "$iface" 2>/dev/null || true
    } >"$tx/tc-before.json" 2>/dev/null || true
    printf '%s\n' "$tx"
}
_e204_tc_readonly_status() {
    local iface line
    iface=$(_e95_default_iface 2>/dev/null || true)
    line=$(_e95_root_qdisc_line "$iface")
    echo "  默认出口网卡: ${iface:-未知}"
    echo "  当前 root qdisc: ${line:-未读取}"
    echo "  E95组件: 未安装或完整性/权限未通过"
    if test -n "$iface" && command -v tc >/dev/null 2>&1; then
        tc -s qdisc show dev "$iface" 2>/dev/null || true
    fi
}

_e204_tc_menu() {
    local opt=""
    # Once present, the inherited full menu is safe: the E204 installer above
    # now takes a read-only fast path and performs no rewrite on menu entry.
    if _e168_tc_component_ready && _e204_tc_conf_secure; then
        _e182_tc_menu "$@"
        return
    fi
    while true; do
        clear
        title 'V199e230：TC 带宽控制（未初始化 / 只读入口）'
        _e204_tc_readonly_status
        hr
        echo '  1) 只读查看当前TC/qdisc状态'
        echo '  2) 事务安装/修复E95组件并进入完整控制中心'
        echo ' 11) 查看TC/BBR/fq说明'
        echo '  0) 返回（不创建任何文件）'
        read -rp '操作: ' opt || true
        case "$opt" in
            1) _e204_tc_readonly_status; _e116_pause ;;
            2)
                if _e95_install_tc_component; then
                    info 'TC组件已事务安装并通过完整性读回。'
                    _e182_tc_menu "$@"
                    return
                fi
                error 'TC组件安装/修复失败；原状态已恢复。'
                _e116_pause
                ;;
            11)
                echo 'TC用于限制出口总带宽，不是提速器；HTB负责上限，fq/fq_codel作为叶子队列。'
                echo '建议上限设为晚高峰稳定速度的85%-95%，以减少排队和丢包。'
                _e116_pause
                ;;
            0) return 0 ;;
            *) warn '无效操作。'; sleep 1 ;;
        esac
    done
}

# Direct log-retention installs now have their own system rollback point.
if declare -F _e121_install_log_retention >/dev/null 2>&1; then
    eval "$(declare -f _e121_install_log_retention | sed '1s/_e121_install_log_retention/_e204_log_retention_base/')"
fi
_e121_install_log_retention() {
    local tx before_count=${#E135_NEW_PACKAGES[@]} rc=0 restore_rc=0
    tx=$(_e204_new_tx log-retention) || return 1
    _e140_system_snapshot "$tx/system" || { _e204_tx_close "$tx" || true; return 1; }
    _e204_log_retention_base "$@" || rc=$?
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx"
        return $?
    fi
    _e172_remove_packages_since "$before_count" || restore_rc=1
    _e140_system_restore "$tx/system" || restore_rc=1
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical log-retention "$tx/system" 'rollback failed' || true
        error "日志保留事务回滚未完整通过；快照：$tx/system"
    fi
    _e204_tx_close "$tx" || true
    return 1
}

# Menu 18 can run outside the global hot-update transaction.  The inherited
# SSH guard has its own rollback, but older layers intentionally ignored a
# failed restore.  Add one final sealed boundary and make rollback failure
# visible instead of leaving a half-applied sshd/fail2ban/firewall state.
if declare -F _e141_install_ssh_guard >/dev/null 2>&1; then
    eval "$(declare -f _e141_install_ssh_guard | sed \
        '1s/_e141_install_ssh_guard/_e204_ssh_guard_install_base/')"
fi
_e141_install_ssh_guard() {
    local tx rc=0 restore_rc=0 before_count=${#E135_NEW_PACKAGES[@]}
    tx=$(_e204_new_tx ssh-guard) || return 1
    _e140_system_snapshot "$tx/system" || { _e204_tx_close "$tx" || true; return 1; }
    _e204_ssh_guard_install_base "$@" || rc=$?
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx"
        return $?
    fi
    error 'SSH/Fail2ban事务未通过，恢复操作前的配置、服务和防火墙状态。'
    _e172_remove_packages_since "$before_count" || restore_rc=1
    _e140_system_restore "$tx/system" || restore_rc=1
    if command -v sshd >/dev/null 2>&1; then
        sshd -t >/dev/null 2>&1 || restore_rc=1
        _e182_sshd_reload_safe >/dev/null 2>&1 || restore_rc=1
    fi
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical ssh-guard "$tx/system" 'outer SSH rollback/readback failed' || true
        error "严重：SSH/Fail2ban外层回滚未完整通过；快照：$tx/system"
    else
        info "SSH/Fail2ban已恢复到操作前状态；快照：$tx/system"
    fi
    _e204_tx_close "$tx" || true
    return 1
}

# A oneshot can be enabled while its last execution failed.  Do not report
# small BBR healthy solely from state/sysctl files.
if declare -F _e202_small_bbr_status >/dev/null 2>&1; then
    eval "$(declare -f _e202_small_bbr_status | sed '1s/_e202_small_bbr_status/_e204_small_bbr_status_base/')"
fi
_e202_small_bbr_status() {
    local rc=0 result status load
    _e204_small_bbr_status_base "$@" || rc=$?
    if _e202_small_bbr_active; then
        result=$(systemctl show "$E202_SMALL_UNIT" -p Result --value 2>/dev/null || true)
        status=$(systemctl show "$E202_SMALL_UNIT" -p ExecMainStatus --value 2>/dev/null || true)
        load=$(systemctl show "$E202_SMALL_UNIT" -p LoadState --value 2>/dev/null || true)
        echo "  最近开机复检: load=${load:-unknown} result=${result:-unknown} exit=${status:-unknown}"
        test "$load" = loaded && test "$result" = success && test "${status:-1}" = 0 || {
            error '小BBR开机oneshot最近一次执行未成功。'
            rc=1
        }
    fi
    return "$rc"
}

_e204_legacy_small_bbr_owner() {
    local v
    for v in 200 198 196 194 192 190; do
        if "_e202_legacy_e${v}_active" 2>/dev/null; then
            printf 'e%s\n' "$v"
            return 0
        fi
    done
    return 1
}

if declare -F _e202_hot_update >/dev/null 2>&1; then
    eval "$(declare -f _e202_hot_update | sed '1s/_e202_hot_update/_e204_hot_update_base/')"
fi

_e204_hot_update_preflight() {
    local owner="" fn
    bash -n "$SCRIPT_PATH" || return 1
    test "$SCRIPT_VERSION" = 199e204 && test "$E204_VERSION" = 199e204 || return 1
    for fn in _e204_install_self _e140_system_snapshot _e140_system_restore \
        _e182_install_mode _e159_network_apply _e159_network_remove \
        _e185_warp_health_check _e204_structure_audit; do
        declare -F "$fn" >/dev/null 2>&1 || {
            error "E204热更新缺少最终函数：$fn"
            return 1
        }
    done
    _e204_structure_audit >/dev/null || {
        error 'E204发布结构/参数不变量门禁失败；热更新尚未开始。'
        return 1
    }
    _e202_hot_update_preflight || return 1
    owner=$(_e204_legacy_small_bbr_owner 2>/dev/null || true)
    if test -n "$owner"; then
        error "检测到旧小BBR所有者：$owner。E204不会猜测旧版快照并代替旧版退出。"
        error '请先执行对应旧版脚本的 --small-bbr-disable，确认恢复成功后再运行E204热更新。'
        return 1
    fi
}

_e204_hot_verify() {
    local target
    for target in "$SYMLINK" "$E204_SELF_PATH" "$E204_LATEST_PATH" "$E202_SELF_PATH"; do
        test -x "$target" && bash -n "$target" && cmp -s "$SCRIPT_PATH" "$target" || {
            error "E204入口安装读回失败：$target"
            return 1
        }
    done
    test "$(cat "$SCRIPT_VERSION_FILE" 2>/dev/null || true)" = "$E204_VERSION" || {
        error '脚本版本文件没有读回199e204。'
        return 1
    }
    if test -s "$CONFIG"; then
        _e118_xray_test_config "$CONFIG" 1 || return 1
        if systemctl is-active --quiet xray.service 2>/dev/null; then
            _e127_verify_xray_runtime "$CONFIG" 12 || return 1
        fi
    fi
    if test "$(_e138_state_get route_enabled 0)" = 1; then
        _e185_warp_health_check || return 1
    fi
    _e182_ipv6_hot_verify || return 1
    if _e202_small_bbr_active; then _e202_small_bbr_status >/dev/null || return 1; fi
}

_e204_hot_update() (
    local tx rc=0 restore_rc=0 hot_log="$E204_HOT_LOG" lock_path=/run/lock/xray-e204-hot-update.lock
    _e204_prepare || return 1
    if test "${E204_INTERNAL_SELF_TEST:-0}" = 1; then
        if test -n "${E204_INTERNAL_SELF_TEST_TMP:-}"; then
            install -d -m 0700 "$E204_INTERNAL_SELF_TEST_TMP" || return 1
            hot_log="$E204_INTERNAL_SELF_TEST_TMP/hot.log"
        else
            hot_log=$(mktemp /tmp/xray-e204-hot-selftest.XXXXXX.log) || return 1
        fi
        lock_path="${hot_log}.lock"
    fi
    exec 204>"$lock_path"
    flock -n 204 || { error '已有E204热更新事务正在运行。'; return 1; }
    tx=$(_e204_new_tx hot-update-outer) || return 1
    : >"$hot_log" || { _e204_tx_close "$tx" || true; return 1; }
    _e159_phase_log "$hot_log" outer-snapshot begin
    _e140_system_snapshot "$tx/system" || { _e204_tx_close "$tx" || true; return 1; }
    _e159_phase_log "$hot_log" outer-snapshot ok
    _e204_hot_update_base || rc=$?
    test "$rc" -ne 0 || _e204_install_self || rc=1
    test "$rc" -ne 0 || _e204_write_version || rc=1
    test "$rc" -ne 0 || _e204_hot_verify || rc=1
    if test "$rc" -eq 0; then
        _e159_phase_log "$hot_log" final-readback ok
        info 'V199e204热更新完成：核心、节点、网络、SSH、WARP、IPv6与脚本入口均已读回。'
        info "外层回滚快照：$tx/system"
        _e204_tx_close "$tx"
        return $?
    fi
    _e159_phase_log "$hot_log" final-readback fail
    error 'E204热更新未完整通过，开始恢复热更新前完整系统状态。'
    _e140_system_restore "$tx/system" || restore_rc=1
    if test "$restore_rc" -eq 0 && test -s "$CONFIG" && test -x "$XRAY_BIN"; then
        _e118_xray_test_config "$CONFIG" 1 || restore_rc=1
        if systemctl is-active --quiet xray.service 2>/dev/null; then
            _e127_verify_xray_runtime "$CONFIG" 12 || restore_rc=1
        fi
    fi
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical hot-update "$tx/system" 'outer rollback/readback failed' || true
        error "严重：E204总回滚未完全通过；必须保留快照：$tx/system"
    else
        info "已恢复热更新前状态；快照：$tx/system"
    fi
    _e204_tx_close "$tx" || true
    return 1
)

hot_update_from_legacy() { _e204_hot_update_preflight && _e204_hot_update; }

_e204_ssh_port_listening() {
    local p="$1" suffix
    [[ "$p" =~ ^[0-9]+$ ]] && test "$p" -ge 1 && test "$p" -le 65535 || return 1
    suffix=":$p"
    ss -H -lnt 2>/dev/null | awk -v s="$suffix" '
      {a=$4; if(length(a)>=length(s) && substr(a,length(a)-length(s)+1)==s){found=1; exit}}
      END{exit !found}'
}

_e204_ssh_access_preflight() {
    local ports p policy nft_policy zones zone
    ports=$(_e121_detect_ssh_ports 2>/dev/null || true)
    test -n "$ports" || { error '卸载前无法识别SSH监听端口。'; return 1; }
    for p in $ports; do
        _e204_ssh_port_listening "$p" || {
            error "SSH端口$p没有监听；拒绝改变SSH防护层。"
            return 1
        }
    done
    if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -qi '^Status: active'; then
        for p in $ports; do ufw allow "$p/tcp" >/dev/null || return 1; done
        return 0
    fi
    if command -v firewall-cmd >/dev/null 2>&1 && systemctl is-active --quiet firewalld.service; then
        zones=$(firewall-cmd --get-active-zones 2>/dev/null \
            | awk 'NF && $1!="interfaces:" && $1!="sources:"{print $1}' | sort -u)
        test -n "$zones" || zones=$(firewall-cmd --get-default-zone 2>/dev/null || true)
        test -n "$zones" || { error 'firewalld活动/default zone无法识别。'; return 1; }
        for zone in $zones; do
            for p in $ports; do
                firewall-cmd --permanent --zone="$zone" --add-port="${p}/tcp" >/dev/null || return 1
            done
        done
        firewall-cmd --reload >/dev/null || return 1
        for zone in $zones; do
            for p in $ports; do
                firewall-cmd --zone="$zone" --query-port="${p}/tcp" >/dev/null || return 1
            done
        done
        return 0
    fi
    if command -v iptables >/dev/null 2>&1 && iptables -S INPUT >/dev/null 2>&1; then
        policy=$(iptables -S INPUT 2>/dev/null | awk '$1=="-P"&&$2=="INPUT"{print $3;exit}')
        test "$policy" != DROP && test "$policy" != REJECT && return 0
        command -v netfilter-persistent >/dev/null 2>&1 || {
            error 'INPUT默认策略为DROP且没有可验证的持久防火墙管理器；拒绝卸载SSH守护层。'
            return 1
        }
        for p in $ports; do
            iptables -C INPUT -p tcp --dport "$p" -j ACCEPT >/dev/null 2>&1 \
                || iptables -I INPUT 1 -p tcp --dport "$p" -j ACCEPT || return 1
        done
        netfilter-persistent save >/dev/null || return 1
        return 0
    fi
    if command -v nft >/dev/null 2>&1 && nft list ruleset >/dev/null 2>&1; then
        nft_policy=$(nft -nn list ruleset 2>/dev/null | awk '
          /hook input/ {seen=1}
          seen && /policy (accept|drop|reject)/ {
            for(i=1;i<=NF;i++)if($i=="policy"){gsub(/;/,"",$(i+1));print $(i+1);exit}
          }')
        test -z "$nft_policy" || test "$nft_policy" = accept || {
            error '原生nftables INPUT策略不是accept且无法证明有持久SSH放行；拒绝卸载SSH守护层。'
            return 1
        }
    fi
}

_e204_legacy_optimizer_owned() {
    local unit="$1"
    case "$unit" in
        nic-optimize.service)
            grep -Fqx 'ExecStart=/usr/local/bin/nic-optimize.sh' /etc/systemd/system/nic-optimize.service 2>/dev/null \
                && grep -q 'rx-gro-hw' /usr/local/bin/nic-optimize.sh 2>/dev/null
            ;;
        rps-optimize.service)
            grep -Fqx 'ExecStart=/usr/local/bin/rps-optimize.sh' /etc/systemd/system/rps-optimize.service 2>/dev/null \
                && grep -q 'rps_sock_flow_entries=131072' /usr/local/bin/rps-optimize.sh 2>/dev/null
            ;;
        txqueue.service)
            grep -Fqx 'Description=Set TX Queue Length for Low Latency' /etc/systemd/system/txqueue.service 2>/dev/null \
                && grep -Eq '^ExecStart=.*/ip([[:space:]]+|$).*txqueuelen[[:space:]]+3000$' /etc/systemd/system/txqueue.service 2>/dev/null
            ;;
        *) return 1 ;;
    esac
}

_e204_uninstall_owned_units() {
    local p unit
    while IFS= read -r p; do
        case "$p" in
            /etc/systemd/system/xray*.service|/etc/systemd/system/xray*.timer)
                unit=$(basename -- "$p")
                test "$unit" = xray.service && continue
                printf '%s\n' "$unit"
                ;;
        esac
    done < <(_e138_system_paths | sort -u)
    for unit in nic-optimize.service rps-optimize.service txqueue.service; do
        _e204_legacy_optimizer_owned "$unit" && printf '%s\n' "$unit" || true
    done
}

_e204_uninstall_stop_owned_units() {
    local unit
    while IFS= read -r unit; do
        test -n "$unit" || continue
        systemctl stop "$unit" >/dev/null 2>&1 || true
        systemctl disable "$unit" >/dev/null 2>&1 || true
    done < <(_e204_uninstall_owned_units | sort -u)
}

_e204_uninstall_remove_owned_files() {
    local p unit rc=0
    while IFS= read -r p; do
        case "$p" in
            /etc/systemd/system/xray*.service|/etc/systemd/system/xray*.timer|/etc/systemd/system/xray.service.d|\
            /usr/local/bin/xray-*.sh|/usr/local/libexec/xray-*|\
            /etc/fail2ban/*/*xray*|/etc/rsyslog.d/*xray*|/etc/logrotate.d/xray*|\
            /etc/systemd/journald.conf.d/*xray*|/etc/sysctl.d/*xray*|\
            /etc/modules-load.d/xray*|/etc/ssh/sshd_config.d/*xray*)
                rm -rf -- "$p" || rc=1
                ;;
        esac
    done < <(_e138_system_paths | sort -u)
    for unit in nic-optimize.service rps-optimize.service txqueue.service; do
        if _e204_legacy_optimizer_owned "$unit"; then
            case "$unit" in
                nic-optimize.service) rm -f -- /etc/systemd/system/nic-optimize.service /usr/local/bin/nic-optimize.sh || rc=1 ;;
                rps-optimize.service) rm -f -- /etc/systemd/system/rps-optimize.service /usr/local/bin/rps-optimize.sh || rc=1 ;;
                txqueue.service) rm -f -- /etc/systemd/system/txqueue.service /usr/local/bin/txqueue.sh || rc=1 ;;
            esac
        elif test -e "/etc/systemd/system/$unit"; then
            warn "保留无法证明由本脚本创建的同名服务：/etc/systemd/system/$unit"
        fi
    done
    return "$rc"
}

_e204_uninstall_managed_swap() {
    local tmp
    E204_UNINSTALL_SWAP_KIND=none
    if _e204_swap_owned zram /dev/zram0; then
        E204_UNINSTALL_SWAP_KIND=zram
        systemctl disable --now "$E204_ZRAM_UNIT" >/dev/null 2>&1 || true
        if swapon --show=NAME --noheadings 2>/dev/null | awk '{$1=$1}1' | grep -Fxq /dev/zram0; then
            swapoff /dev/zram0 || return 1
            command -v zramctl >/dev/null 2>&1 && zramctl --reset /dev/zram0 >/dev/null 2>&1 || true
        fi
        return 0
    fi
    if _e204_swap_owned swapfile "$E204_SWAPFILE" || _e204_legacy_swapfile_owned; then
        E204_UNINSTALL_SWAP_KIND=swapfile
        if swapon --show=NAME --noheadings 2>/dev/null | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE"; then
            swapoff "$E204_SWAPFILE" || return 1
        fi
        tmp=$(_e118_mktemp e204-uninstall-fstab) || return 1
        awk -v p="$E204_SWAPFILE" '$1!=p{print}' /etc/fstab >"$tmp" || return 1
        _e118_atomic_install "$tmp" /etc/fstab 0644 || return 1
        # 文件保留到所有卸载验证完成；这样后续失败仍能无损swapon回滚，
        # 同时避免每个系统快照复制整个1GiB文件。
        return 0
    fi
    if test -e "$E204_SWAPFILE" \
      || swapon --show=NAME --noheadings 2>/dev/null | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE"; then
        warn "保留没有E204所有权证据的同名Swap：$E204_SWAPFILE"
    fi
}

_e204_restore_managed_swap_runtime() {
    local kind="${1:-none}"
    case "$kind" in
        swapfile)
            test -e "$E204_SWAPFILE" || return 1
            if ! swapon --show=NAME --noheadings 2>/dev/null | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE"; then
                swapon -p 10 "$E204_SWAPFILE" >/dev/null 2>&1 || return 1
            fi
            ;;
        zram)
            if _e204_swap_owned zram /dev/zram0; then
                systemctl start "$E204_ZRAM_UNIT" >/dev/null 2>&1 || return 1
                swapon --show=NAME --noheadings 2>/dev/null | awk '{$1=$1}1' | grep -Fxq /dev/zram0 || return 1
            fi
            ;;
    esac
}

do_uninstall() (
    local confirm="" tx archive="" rc=0 restore_rc=0 E204_UNINSTALL_SWAP_KIND=none
    title 'V199e204：受控卸载 Xray 环境'
    warn '将恢复小BBR/完整网络/IPv6/WARP，再删除明确属于本脚本的Xray文件；Cloudflare WARP、dnsmasq和用户Swap软件包保留。'
    read -rp '请输入 DELETE-XRAY 确认: ' confirm || true
    test "$confirm" = DELETE-XRAY || { info '已取消，系统未修改。'; return 0; }
    if _e204_legacy_small_bbr_owner >/dev/null 2>&1; then
        error '检测到旧版小BBR；请先用对应旧版脚本退出档位，验证恢复后再卸载。'
        return 1
    fi
    _e220_mss_preflight_readonly || {
        error '存在未恢复的MSS事务；受控卸载不会删除其恢复证据。请先运行 --mss-recover。'
        return 1
    }
    tx=$(_e204_new_tx uninstall) || return 1
    _e140_system_snapshot "$tx/system" || { _e204_tx_close "$tx" || true; return 1; }
    _e204_service_snapshot fail2ban.service >"$tx/fail2ban.before" \
        || { _e204_tx_close "$tx" || true; return 1; }
    if ! _e204_ssh_access_preflight; then
        error 'SSH防自锁预检失败，恢复预检可能产生的防火墙变更。'
        if ! _e140_system_restore "$tx/system"; then
            _e204_mark_critical uninstall-preflight "$tx/system" 'SSH preflight rollback failed' || true
            error "严重：SSH预检回滚失败；快照：$tx/system"
        fi
        _e204_tx_close "$tx" || true
        return 1
    fi
    archive="/root/xray-before-uninstall-e204-$(date +%Y%m%d_%H%M%S)-$$.tgz"
    if test -d "$CONFIG_DIR"; then
        _e142_create_uninstall_archive "$archive" || {
            error '卸载前归档未通过读回；未执行删除。'
            _e204_tx_close "$tx" || true
            return 1
        }
    fi
    if _e202_small_bbr_active; then _e202_small_bbr_disable force || rc=1; fi
    test "$rc" -ne 0 || _e142_restore_network_baseline || rc=1
    test "$rc" -ne 0 || _e140_warp_full_disable force || rc=1
    if test "$rc" -eq 0 && test "$(_e138_state_get route_enabled 0)" = 1; then
        _e138_warp_disable || rc=1
    fi
    test "$rc" -ne 0 || _e182_ipv6_uninstall_restore || rc=1
    test "$rc" -ne 0 || _e182_remove_native_ssh_config || rc=1
    test "$rc" -ne 0 || _e204_uninstall_managed_swap || rc=1
    if test "$rc" -eq 0 && test -x "$E95_TC_SCRIPT"; then "$E95_TC_SCRIPT" stop >/dev/null 2>&1 || rc=1; fi
    test "$rc" -ne 0 || _e204_uninstall_stop_owned_units || rc=1
    if test "$rc" -eq 0; then
        systemctl stop xray.service >/dev/null 2>&1 || true
        systemctl is-active --quiet xray.service 2>/dev/null && rc=1 || true
        systemctl disable xray.service >/dev/null 2>&1 || true
    fi
    if test "$rc" -eq 0; then systemctl stop fail2ban.service >/dev/null 2>&1 || true; fi
    test "$rc" -ne 0 || _e204_uninstall_remove_owned_files || rc=1
    if test "$rc" -eq 0; then
        rm -f -- "$SYMLINK" "$XRAY_BIN" /etc/systemd/system/xray.service || rc=1
        rm -rf -- "$CONFIG_DIR" "$DAT_DIR" "$SCRIPT_DIR" "$LOG_DIR" || rc=1
    fi
    test "$rc" -ne 0 || systemctl daemon-reload >/dev/null 2>&1 || rc=1
    if test "$rc" -eq 0 && command -v fail2ban-client >/dev/null 2>&1; then fail2ban-client -t >/dev/null 2>&1 || rc=1; fi
    if test "$rc" -eq 0; then _e204_services_restore_file "$tx/fail2ban.before" || rc=1; fi
    if test "$rc" -eq 0 && command -v sshd >/dev/null 2>&1; then sshd -t >/dev/null 2>&1 || rc=1; fi
    test "$rc" -ne 0 || { test ! -e "$XRAY_BIN" && test ! -e "$CONFIG"; } || rc=1
    test "$rc" -ne 0 || ! systemctl is-active --quiet xray.service 2>/dev/null || rc=1
    if test "$rc" -eq 0 && test "$E204_UNINSTALL_SWAP_KIND" = swapfile; then
        rm -f -- "$E204_SWAPFILE" || rc=1
    fi
    if test "$rc" -eq 0; then
        sysctl --system >/dev/null 2>&1 || warn '其它发行版sysctl文件存在错误；卸载恢复事务本身已完成。'
        info "Xray环境已受控卸载；可读回归档：${archive:-未创建}"
        info "事务快照保留：$tx/system"
        _e204_tx_close "$tx"
        return $?
    fi
    error 'E204卸载任一阶段未通过，恢复卸载前完整状态。'
    _e140_system_restore "$tx/system" || restore_rc=1
    _e204_services_restore_file "$tx/fail2ban.before" || restore_rc=1
    _e204_restore_managed_swap_runtime "$E204_UNINSTALL_SWAP_KIND" || restore_rc=1
    if test -s "$CONFIG" && test -x "$XRAY_BIN"; then
        _e118_xray_test_config "$CONFIG" 1 || restore_rc=1
        if systemctl is-active --quiet xray.service 2>/dev/null; then _e127_verify_xray_runtime "$CONFIG" 12 || restore_rc=1; fi
    fi
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical uninstall "$tx/system" 'uninstall rollback/readback failed' || true
        error "严重：卸载回滚未完整通过；快照：$tx/system"
    else
        info "卸载已取消并恢复到原状态；快照：$tx/system"
    fi
    _e204_tx_close "$tx" || true
    return 1
)

_e204_micro_control_menu() {
    local opt="" qdisc="" confirm=""
    while true; do
        clear; title 'V199e230：完整28项应用层 / 系统微操中心（E204稳定事务底座）'
