            16) _e170_ring_action || error 'Ring事务失败。'; _e52_pause ;;
            17)
                read -rp 'qdisc [fq/fq_codel/cake]: ' qdisc || true; qdisc=${qdisc:-fq}
                _e159_network_apply "$qdisc" 1 31 || true; _e52_pause ;;
            18|19|20) warn 'CAKE子项必须作用于实际TC root qdisc，转入TC事务中心。'; _e204_tc_menu || true ;;
            21) _e182_offload_action || true; _e52_pause ;;
            22) _e182_rps_action || true; _e52_pause ;;
            23)
                warn '只创建E204自有ZRAM/Swap；检测到用户Swap时不接管。'
                read -rp '输入 APPLY-ZRAM-1G 确认: ' confirm || true
                test "$confirm" = APPLY-ZRAM-1G && enable_zram_default || true; _e52_pause ;;
            24) _e121_install_log_retention || error '3天日志策略安装失败。'; _e52_pause ;;
            25) _e159_xray_action_tx xray-limits apply_process_priority_default || true; _e52_pause ;;
            26) _e159_xray_action_tx app-1-to-11 _turn_on_app || true; _e52_pause ;;
            27) apply_safe_turbo_defaults || error '安全系统微操失败。'; _e52_pause ;;
            28) _e159_apply_micro_28 || true; _e52_pause ;;
            0) return 0 ;;
            *) warn '无效操作。'; sleep 1 ;;
        esac
    done
}
