_e204_main_menu() {
    local num=""
    while true; do
        clear; SERVER_IP=$(_get_ip)
        echo -e "${magenta}======================================================================${none}"
        echo -e "  ${cyan}Xray System Advanced Management V199e204 - 事务稳态版${none}"
        echo -e "  ${green}引擎:${none} $(systemctl is-active xray 2>/dev/null || echo unknown) | ${cyan}快捷指令:${none} xrv | ${cyan}公网IP:${none} ${SERVER_IP:-unknown}"
        echo -e "${magenta}======================================================================${none}"
        echo '  1) 安装 / 重装节点（Reality / Reality+SS2022 / VLESSENC / SS2022）'
        echo '  2) Reality 用户、UUID、SNI、端口与密钥管理'
        echo '  3) 节点链接与参数输出'
        echo '  4) 立即更新 geoip/geosite DAT'
        echo '  5) Xray Core 手动更新/修复'
        echo '  6) 修改 Reality SNI 矩阵'
        echo '  7) 系统防火墙策略配置'
        echo '  8) Reality Fallback 分析器'
        echo '  9) 网络连接审计与流量记账'
        echo ' 10) 内核 / 网络 / 应用层高级控制板'
        echo -e "  ${green}11) 从现有 ex198e/ex199e 环境热更新到 V199e204${none}"
        echo ' 12) 安全清理空间 / 3天日志与快照收敛'
        echo ' 13) 网络参数（默认 initcwnd/initrwnd=30）'
        echo ' 14) TCP 重传 / 单连接诊断'
        echo ' 15) 检查配置并重新输出节点'
        echo ' 16) 状态隔离与 VLESSENC 能力检查'
        echo ' 17) BBR 本体替换 / 自定义编译中心'
        echo ' 18) 安全审计 / SSH 防爆破'
        echo ' 19) Xray 跨境链路速度诊断'
        echo ' 20) TC 带宽控制'
        echo -e "  ${cyan}21) 跨境代理网络参数集合（逐项默认值 / 档位 / 开机复检）${none}"
        echo -e "  ${cyan}22) WARP定向分流（Google/Meta）${none}"
        echo -e "  ${cyan}23) WARP全局分流（仅Xray层，不改VPS路由）${none}"
        echo -e "  ${cyan}24) Cloudflare系统全隧道（SSH自动回滚）${none}"
        echo -e "  ${cyan}25) IPv6永久开关（默认关闭）${none}"
        echo -e "  ${cyan}26) 小BBR（八档切换 / 14、25或26项 / 默认模式2）${none}"
        echo -e "  ${red}88) 受控卸载 Xray 环境${none}"
        echo '  0) 退出'; hr
        read -rp '请输入操作代码: ' num || true
        case "$num" in
            1) do_install ;; 2) do_user_manager ;; 3) do_summary; _e116_pause ;;
            4) _e131_dat_update_now; _e116_pause ;; 5) do_update_core; _e116_pause ;;
            6) if choose_sni; then _update_matrix && do_summary; fi; _e116_pause ;;
            7) _global_block_rules || true ;; 8) do_fallback_probe || true; _e116_pause ;;
            9) _e182_traffic_monitor || true ;; 10) _e204_advanced_menu || true ;;
            11) hot_update_from_legacy || true ;; 12) do_space_cleanup_menu || true ;;
            13) _e182_network_params_menu ;; 14) do_tcp_diag_menu_e63 || true ;;
            15) _e182_check_reexport || true; _e116_pause ;; 16) e77_audit_runtime_state || true; _e116_pause ;;
            17) _e182_bbr_kernel_menu || true ;; 18) _e182_security_center ;;
            19) if declare -F do_xray_speed_diag_menu_e95 >/dev/null 2>&1; then do_xray_speed_diag_menu_e95 || true; elif declare -F do_xray_speed_diag_menu_e94 >/dev/null 2>&1; then do_xray_speed_diag_menu_e94 || true; else warn '跨境链路诊断模块缺失。'; fi ;;
            20) _e204_tc_menu || true ;; 21) _e159_network_menu ;;
            22) _e136_warp_preflight && _e138_warp_selective_menu || true ;;
            23) _e136_warp_preflight && _e138_warp_global_menu || true ;;
            24) _e136_warp_preflight && _e140_warp_full_menu || true ;;
            25) _e182_ipv6_menu || true ;; 26) _e202_small_bbr_menu ;; 88) do_uninstall ;;
            0) return 0 ;; *) warn '无效操作。'; sleep 1 ;;
        esac
    done
}
main_menu() { _e204_main_menu "$@"; }

_e204_help() {
    cat <<'EOF_E204_HELP'
V199e204:
  --hot-update                         事务热更新到E204
  --summary                            导出节点URI、一次终端QR及PNG/SVG
  --network-audit                      只读网络参数/重复定义审计
  --full-network-apply                 事务应用完整127条请求
  --small-bbr-menu                     八个精确14/25/26项档位菜单
  --small-bbr-enable|status|disable    启用、读回或恢复小BBR
  --ipv6-disable|enable|status         IPv6永久策略（无IPv4时默认拒绝关闭）
  --warp-menu|--warp-global-menu       Xray层定向/全局WARP
  --warp-full-menu                     Cloudflare系统全隧道
  --micro-menu                         完整28项微操中心
  --structure-audit                    E204最终绑定与不变量审计
  --self-test                          E204离线发行门禁
  --uninstall                          受控卸载（先恢复各事务基线）

升级注意：若旧版小BBR仍处于活动档，先用对应旧版脚本执行
--small-bbr-disable并确认恢复通过，再运行E204热更新。
EOF_E204_HELP
}

_e204_structure_audit() {
    local rc=0 size lines dispatchers menu micro kernel hot uninstall network node warp dat
    local snapshot services service_list paths ssh sshguard dns tc tc_menu prune cleanup summary metadata
    local warp_enable warp_base warp_full warp_full_commit warp_disable warp_reconcile
    local buffer advanced_tx action_body d conf id count purge_line restore_line
    echo 'V199e204 structure audit:'
    size=$(wc -c <"$SCRIPT_PATH" | tr -d ' '); lines=$(wc -l <"$SCRIPT_PATH" | tr -d ' ')
    dispatchers=$(grep -c '^# V199e204 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true)
    menu=$(declare -f _e204_main_menu 2>/dev/null || true)
    micro=$(declare -f _e204_micro_control_menu 2>/dev/null || true)
    kernel=$(declare -f _execute_compilation 2>/dev/null || true)
    hot=$(declare -f _e204_hot_update 2>/dev/null || true)
    uninstall=$(declare -f do_uninstall 2>/dev/null || true)
    network=$(declare -f _e159_network_remove 2>/dev/null || true)
    node=$(declare -f _e182_install_mode 2>/dev/null || true)
    warp=$(declare -f _e185_warp_health_check 2>/dev/null || true)
    warp_enable=$(declare -f _e185_warp_enable 2>/dev/null || true)
    warp_base=$(declare -f _e204_warp_enable_base 2>/dev/null || true)
    warp_full=$(declare -f _e140_warp_full_enable 2>/dev/null || true)
    warp_full_commit=$(declare -f _e159_warp_full_enable_base 2>/dev/null || true)
    warp_disable=$(declare -f _e185_warp_disable 2>/dev/null || true)
    warp_reconcile=$(declare -f _e185_warp_reconcile 2>/dev/null || true)
    dat=$(declare -f _e204_patch_dat_pair 2>/dev/null || true)
    snapshot=$(declare -f _e140_system_snapshot 2>/dev/null || true)
    services=$(declare -f _e204_service_candidates 2>/dev/null || true)
    service_list=$(_e204_service_candidates 2>/dev/null | LC_ALL=C sort -u)
    paths=$(_e138_system_paths 2>/dev/null || true)
    ssh=$(declare -f _e204_ssh_access_preflight 2>/dev/null || true)
    sshguard=$(declare -f _e141_install_ssh_guard 2>/dev/null || true)
    dns=$(declare -f enable_dnsmasq_cache_safely 2>/dev/null || true)
    tc=$(declare -f _e95_install_tc_component 2>/dev/null || true)
    tc_menu=$(declare -f _e182_tc_menu 2>/dev/null || true)
    prune=$(declare -f _e204_prune_transactions 2>/dev/null || true)
    cleanup=$(declare -f check_and_clean_space 2>/dev/null || true)
    summary=$(declare -f _e159_summary_impl 2>/dev/null || true)
    metadata=$(declare -f _e204_write_generated_metadata_impl 2>/dev/null || true)
    buffer=$(declare -f _e204_action_buffer_128 2>/dev/null || true)
    advanced_tx=$(declare -f _e204_advanced_action_tx 2>/dev/null || true)
    echo "  file_bytes=$size lines=$lines final_dispatchers=$dispatchers"
    test "$size" -gt 2500000 && test "$lines" -gt 50000 || rc=1
    test "$dispatchers" -eq 1 || rc=1
    test "$SCRIPT_VERSION" = 199e204 && test "$E204_VERSION" = 199e204 || rc=1
    ! LC_ALL=C grep -q $'\r' "$SCRIPT_PATH" || rc=1
    ! grep -q 'E204_''SELF_TEST_MODE' "$SCRIPT_PATH" || rc=1
    grep -q '^E204_INTERNAL_SELF_TEST=0$' "$SCRIPT_PATH" || rc=1
    grep -q '^E159_DEFER_HOST_FULL_VERIFY=0$' "$SCRIPT_PATH" || rc=1
    grep -q '^E188_SUMMARY_SUPPRESS=0$' "$SCRIPT_PATH" || rc=1
    grep -q '热更新到 V199e204' <<<"$menu" || rc=1
    for id in _e204_tc_menu _e138_warp_selective_menu _e138_warp_global_menu \
        _e140_warp_full_menu _e182_ipv6_menu _e202_small_bbr_menu; do
        grep -q "$id" <<<"$menu" || rc=1
    done
    for id in socket-keepalive metadata-only route-only buffer-128 dns-ipv4; do grep -q "$id" <<<"$micro" || rc=1; done
    ! grep -q '_e159_action_2_to_6' <<<"$micro" || rc=1
    grep -q '_e90_kernel_patch_before_compile || return 1' <<<"$kernel" || rc=1
    ! grep -q '_e90_kernel_patch_before_compile || true' <<<"$kernel" || rc=1
    grep -q '_e140_system_snapshot' <<<"$hot" || rc=1
    grep -q '_e140_system_restore' <<<"$hot" || rc=1
    grep -q '_e202_small_bbr_disable force' <<<"$uninstall" || rc=1
    ! grep -q '_e202_uninstall_base' <<<"$uninstall" || rc=1
    ! grep -Eq 'rm .*/etc/systemd/system/xray\*|list-unit-files.*xray\*|exit 0' <<<"$uninstall" || rc=1
    grep -q '_e204_network_origin_clean' <<<"$network" || rc=1
    grep -q '_e159_network_snapshot' <<<"$network" || rc=1
    grep -q '_e140_system_snapshot' <<<"$node" || rc=1
    grep -q '_e140_system_restore' <<<"$node" || rc=1
    grep -q '_e185_wg_probe_endpoint' <<<"$warp" || rc=1
    grep -q '_e204_warp_enable_base' <<<"$warp_enable" || rc=1
    grep -q '_e140_system_snapshot' <<<"$warp_enable" || rc=1
    grep -q '_e138_xray_apply_warp' <<<"$warp_base" || rc=1
    ! grep -Eq '^[[:space:]]*_e18(5|6)_warp_enable[[:space:]]+"\$@"' <<<"$warp_base" || rc=1
    grep -q '_e159_warp_full_enable_base' <<<"$warp_full" || rc=1
    grep -q '_e140_system_snapshot' <<<"$warp_full" || rc=1
    grep -q '_e204_warp_package_restore' <<<"$warp_full" || rc=1
    grep -q 'comm -13' <<<"$warp_full_commit" || rc=1
    ! grep -q "printf '%T@" <<<"$warp_full_commit" || rc=1
    grep -q '_e140_system_snapshot' <<<"$warp_disable" || rc=1
    grep -q '_e204_warp_outer_restore' <<<"$(declare -f _e140_warp_full_disable 2>/dev/null || true)" || rc=1
    grep -q '_e204_warp_package_restore' <<<"$warp_reconcile" || rc=1
    grep -q 'DAT资源未成对下载完成' <<<"$dat" || rc=1
    grep -q 'DAT成对提交失败' <<<"$dat" || rc=1
    grep -q 'e204-services.env' <<<"$snapshot" || rc=1
    grep -q '_e204_service_candidates' <<<"$snapshot" || rc=1
    grep -q '_e138_system_paths' <<<"$services" || rc=1
    grep -q 'list-unit-files' <<<"$services" || rc=1
    for id in xray.service fail2ban.service ssh.socket warp-svc.service \
        nftables.service systemd-journald.service; do
        grep -Fxq "$id" <<<"$service_list" || rc=1
    done
    ! grep -Fxq "$E204_SWAPFILE" <<<"$paths" || rc=1
    grep -q '_e204_ssh_port_listening' <<<"$ssh" || rc=1
    grep -q '_e140_system_snapshot' <<<"$sshguard" || rc=1
    grep -q '_e140_system_restore' <<<"$sshguard" || rc=1
    grep -q '_e204_tc_install_base' <<<"$tc" || rc=1
    test "$(grep -o '_e168_tc_verify_stopped' <<<"$tc_menu" | wc -l)" -ge 4 || rc=1
    grep -q 'E204_CRITICAL_MARKER' <<<"$prune" || rc=1
    grep -q 'XRAY_E204_TX_KEEP' <<<"$prune" || rc=1
    grep -q '\.active\.env' <<<"$prune" || rc=1
    grep -q 'keep >= 12' <<<"$prune" || rc=1
    grep -q '_e204_prune_transactions' <<<"$cleanup" || rc=1
    grep -q '_e204_remove_xray_env_buffer' <<<"$buffer" || rc=1
    grep -q '_e140_system_snapshot' <<<"$buffer" || rc=1
    grep -q '_e140_system_snapshot' <<<"$advanced_tx" || rc=1
    grep -q '_e140_system_restore' <<<"$advanced_tx" || rc=1
    grep -q '_e204_mark_critical' <<<"$advanced_tx" || rc=1
    for id in _e159_xray_action_tx \
        _e168_apply_init30_tx _e168_offload_action _e168_rps_action \
        _e168_mss_action _e168_txq_action _e168_ring_action \
        _e168_disable_legacy_tx _e159_apply_micro_28; do
        action_body=$(declare -f "$id" 2>/dev/null || true)
        grep -q '_e204_advanced_action_tx' <<<"$action_body" || rc=1
    done
    # Every E204 transaction opened directly by a final mutator must retire
    # its liveness marker.  The snapshot itself remains available for manual
    # rollback and the critical marker independently protects failed restores.
    for id in _e204_install_self _e182_install_mode _e185_warp_enable \
        _e140_warp_full_enable _e140_warp_full_disable \
        _e140_warp_full_reconcile _e185_warp_disable _e185_warp_reconcile \
        _e204_action_buffer_128 enable_dnsmasq_cache_safely \
        enable_zram_default _e95_install_tc_component \
        _e121_install_log_retention _e141_install_ssh_guard _e204_hot_update \
        do_uninstall; do
        action_body=$(declare -f "$id" 2>/dev/null || true)
        grep -q '_e204_tx_close' <<<"$action_body" || rc=1
    done
    grep -q '_e170_ring_action' <<<"$micro" || rc=1
    ! grep -q 'apply_ring_max_adaptive_default' <<<"$micro" || rc=1
    grep -Fq '_e118_user_sid "$uuid" "$idx" "$inbound"' <<<"$summary" || rc=1
    grep -q 'E204_VERSION' <<<"$metadata" || rc=1
    ! grep -q 'E182_VERSION' <<<"$metadata" || rc=1
    purge_line=$(grep -n 'apt-get purge -y dnsmasq' <<<"$dns" | head -n1 | cut -d: -f1)
    restore_line=$(grep -n '_e135_restore_file' <<<"$dns" | head -n1 | cut -d: -f1)
    [[ "$purge_line" =~ ^[0-9]+$ && "$restore_line" =~ ^[0-9]+$ ]] \
        && test "$purge_line" -lt "$restore_line" || rc=1
    d=$(mktemp -d /tmp/xray-e204-profile-audit.XXXXXX) || return 1; conf="$d/profile.conf"
    for id in mode1 mode2 mode3 mode1f mode2f mode3f mode3f2 modeb1; do
        "_e202_small_bbr_${id}" >"$conf" || rc=1
        _e202_small_bbr_validate_file "$conf" || rc=1
        count=$(_e202_small_bbr_assignment_count "$conf")
        case "$id" in
            mode1|mode2|mode3) test "$count" -eq 14 || rc=1 ;;
            mode3f2) test "$count" -eq 26 || rc=1 ;;
            *) test "$count" -eq 25 || rc=1 ;;
        esac
        grep -Fqx 'net.ipv4.tcp_adv_win_scale = 1' "$conf" || rc=1
        ! grep -q '^net.ipv4.tcp_tw_reuse_delay[[:space:]]*=' "$conf" || rc=1
        case "$id" in
            mode1f|mode2f|mode3f|mode3f2|modeb1)
                grep -Fqx 'net.ipv4.tcp_max_reordering = 300' "$conf" || rc=1
                grep -Fqx 'net.ipv4.tcp_tw_reuse = 2' "$conf" || rc=1
                grep -Fqx 'net.ipv4.tcp_recovery = 1' "$conf" || rc=1 ;;
        esac
    done
    rm -rf -- "$d"
    if test "$rc" -eq 0; then echo '  result=PASS'; else echo '  result=FAIL'; fi
    return "$rc"
}

_e204_hot_rollback_self_test() (
    local d result=0
    d=$(mktemp -d /tmp/xray-e204-hot-rollback.XXXXXX) || return 1
    : >"$d/order"
    _e204_prepare() { :; }
    _e204_new_tx() { install -d -m 0700 "$d/tx/system"; printf '%s\n' "$d/tx"; }
    _e159_phase_log() { :; }
    _e140_system_snapshot() { echo snapshot >>"$d/order"; }
    _e204_hot_update_base() { echo mutate-fail >>"$d/order"; return 1; }
    _e140_system_restore() { echo restore >>"$d/order"; return 0; }
    _e204_mark_critical() { echo critical >>"$d/order"; return 0; }
    ! E204_INTERNAL_SELF_TEST=1 E204_INTERNAL_SELF_TEST_TMP="$d" _e204_hot_update >/dev/null 2>&1 || result=1
    test "$(tr '\n' ' ' <"$d/order")" = 'snapshot mutate-fail restore ' || result=1
    rm -rf -- "$d"
    return "$result"
)

_e204_advanced_tx_self_test() (
    local d result=0 restore_fail=0
    d=$(mktemp -d /tmp/xray-e204-advanced-tx.XXXXXX) || return 1
    : >"$d/order"
    _e204_new_tx() {
        install -d -m 0700 "$d/tx/system" || return 1
        : >"$d/tx/.active.env"
        printf '%s\n' "$d/tx"
    }
    _e140_system_snapshot() { echo snapshot >>"$d/order"; }
    _e140_system_restore() {
        echo restore >>"$d/order"
        test "$restore_fail" -eq 0
    }
    _e204_mark_critical() { echo critical >>"$d/order"; }
    _e204_test_failed_handler() { echo handler-37 >>"$d/order"; return 37; }
    ! _e204_advanced_action_tx test _e204_test_failed_handler >/dev/null 2>&1 || result=1
    test "$(tr '\n' ' ' <"$d/order")" = 'snapshot handler-37 restore ' || result=1
    test ! -e "$d/tx/.active.env" || result=1
    : >"$d/order"; restore_fail=1
    ! _e204_advanced_action_tx test _e204_test_failed_handler >/dev/null 2>&1 || result=1
    test "$(tr '\n' ' ' <"$d/order")" = 'snapshot handler-37 restore critical ' || result=1
    rm -rf -- "$d"
    return "$result"
)

_e204_tc_menu_readonly_self_test() (
