_e204_ssh_listener_self_test() (
    ss() {
        printf '%s\n' \
            'LISTEN 0 128 0.0.0.0:22 0.0.0.0:*' \
            'LISTEN 0 128 [::]:2222 [::]:*'
    }
    _e204_ssh_port_listening 22 \
        && _e204_ssh_port_listening 2222 \
        && ! _e204_ssh_port_listening 2 \
        && ! _e204_ssh_port_listening '22|2222'
)

_e204_service_restore_self_test() (
    local enabled_state=disabled active_state=inactive load_state=loaded freeze_enabled=0 freeze_active=0
    systemctl() {
        local cmd="${1:-}"; shift || true
        case "$cmd" in
            daemon-reload) return 0 ;;
            unmask) load_state=loaded; enabled_state=disabled; return 0 ;;
            mask)
                if test "${1:-}" = --runtime; then enabled_state=masked-runtime; else enabled_state=masked; fi
                load_state=masked; return 0 ;;
            enable)
                test "$freeze_enabled" -eq 1 && return 0
                if test "${1:-}" = --runtime; then enabled_state=enabled-runtime; else enabled_state=enabled; fi
                return 0 ;;
            disable) test "$freeze_enabled" -eq 1 || enabled_state=disabled; return 0 ;;
            start) active_state=active; return 0 ;;
            stop) test "$freeze_active" -eq 1 || active_state=inactive; return 0 ;;
            is-active) printf '%s\n' "$active_state"; test "$active_state" = active ;;
            is-enabled) printf '%s\n' "$enabled_state"; test "$enabled_state" != disabled ;;
            show) printf '%s\n' "$load_state"; return 0 ;;
            *) return 1 ;;
        esac
    }
    _e204_service_restore_line demo.service loaded enabled active || return 1
    test "$enabled_state:$active_state:$load_state" = enabled:active:loaded || return 1
    _e204_service_restore_line demo.service masked masked-runtime inactive || return 1
    test "$enabled_state:$active_state:$load_state" = masked-runtime:inactive:masked || return 1
    load_state=loaded; enabled_state=disabled; active_state=inactive; freeze_enabled=1
    ! _e204_service_restore_line demo.service loaded enabled inactive || return 1
    freeze_enabled=0; freeze_active=1; load_state=loaded; enabled_state=disabled; active_state=failed
    ! _e204_service_restore_line demo.service loaded disabled inactive || return 1
    freeze_active=0; load_state=not-found; enabled_state=disabled; active_state=inactive
    _e204_service_restore_line missing.service not-found disabled inactive
)

