_e204_ipv6_pending_abi_self_test() (
    local d captured=""
    d=$(mktemp -d /tmp/xray-e204-ipv6-pending.XXXXXX) || return 1
    _e182_secure_state_temp() { mktemp "$d/pending.XXXXXX"; }
    _e182_commit_state() {
        captured=$(cat "$1")
        return 0
    }
    _e204_ipv6_pending_write || { rm -rf -- "$d"; return 1; }
    grep -qx 'reason=live-ipv6-ssh-session' <<<"$captured" || {
        rm -rf -- "$d"
        return 1
    }
    rm -rf -- "$d"
)

_e204_warp_full_commit_self_test() (
    local d touched=0 committed=""
    d=$(mktemp -d /tmp/xray-e204-warp-commit.XXXXXX) || return 1
    _e118_mktemp() { mktemp "$d/tmp.XXXXXX"; }
    _e152_warp_full_enable_impl() { return 0; }
    _e140_full_rollback_tx() { touched=1; return 1; }

    # Cancellation is a strict no-op: it must not verify, roll back or stamp an
    # older transaction merely because one already exists on disk.
    _e140_full_mode_active() { return 1; }
    _e142_full_snapshot_verify() { touched=1; return 1; }
    _e139_state_set_fields() { touched=1; return 1; }
    _e159_warp_full_enable_base || { rm -rf -- "$d"; return 1; }
    test "$touched" -eq 0 || { rm -rf -- "$d"; return 1; }

    # A real commit may bind only the transaction which appears between this
    # invocation's before/after inventories.
    : >"$d/find-second"
    rm -f -- "$d/find-second"
    find() {
        if test -e "$d/find-second"; then
            printf '%s\n' /tx/old /tx/new
        else
            : >"$d/find-second"
            printf '%s\n' /tx/old
        fi
    }
    _e140_full_mode_active() { return 0; }
    _e142_full_snapshot_verify() { test "$1" = /tx/new; }
    _e139_state_set_fields() { committed="$2"; return 0; }
    _e159_warp_full_enable_base >/dev/null || { rm -rf -- "$d"; return 1; }
    test "$committed" = /tx/new || { rm -rf -- "$d"; return 1; }
    rm -rf -- "$d"
)

_e204_warp_listener_self_test() {
    local v4 dual v6only wildcard
    v4='LISTEN 0 4096 127.0.0.1:40000 0.0.0.0:* users:(("warp-svc",pid=1,fd=1))'
    dual="$v4"$'\n''LISTEN 0 4096 [::1]:40000 [::]:* users:(("warp-svc",pid=1,fd=2))'
    v6only='LISTEN 0 4096 [::1]:40000 [::]:* users:(("warp-svc",pid=1,fd=2))'
    wildcard='LISTEN 0 4096 0.0.0.0:40000 0.0.0.0:* users:(("warp-svc",pid=1,fd=1))'
    _e186_listener_set_safe "$v4" \
        && _e186_listener_set_safe "$dual" \
        && ! _e186_listener_set_safe "$v6only" \
        && ! _e186_listener_set_safe "$wildcard"
}

_e204_self_test() {
    local rc=0
    echo 'V199e204 offline release gate:'
    bash -n "$SCRIPT_PATH" && echo '  [PASS] bash syntax' || { echo '  [FAIL] bash syntax'; rc=1; }
    E204_INTERNAL_SELF_TEST=1 _e188_summary_transaction_self_test >/dev/null && echo '  [PASS] one-summary/one-QR transaction' || { echo '  [FAIL] one-summary/one-QR transaction'; rc=1; }
    _e202_inherited_core_self_test >/dev/null && echo '  [PASS] inherited Xray/WARP behavior' || { echo '  [FAIL] inherited Xray/WARP behavior'; rc=1; }
    _e202_small_bbr_self_test >/dev/null && echo '  [PASS] eight exact 14/25/26-item small-BBR profiles' || { echo '  [FAIL] small-BBR invariant'; rc=1; }
    _e204_hot_rollback_self_test && echo '  [PASS] outer hot-update failure restores sealed snapshot' || { echo '  [FAIL] hot-update outer rollback'; rc=1; }
    _e204_advanced_tx_self_test && echo '  [PASS] menu-10 outer transaction detects rollback failure' || { echo '  [FAIL] menu-10 outer transaction'; rc=1; }
    _e204_tc_menu_readonly_self_test && echo '  [PASS] opening/leaving TC menu is read-only' || { echo '  [FAIL] TC menu entry mutates'; rc=1; }
    _e204_ssh_listener_self_test && echo '  [PASS] IPv4/IPv6 SSH listener parsing' || { echo '  [FAIL] SSH listener parser'; rc=1; }
    _e204_service_restore_self_test && echo '  [PASS] service rollback reads back load/enabled/active state' || { echo '  [FAIL] service rollback readback'; rc=1; }
    _e204_reality_sid_self_test && echo '  [PASS] Reality ShortId stays bound to its current inbound' || { echo '  [FAIL] Reality ShortId inbound binding'; rc=1; }
    _e204_ipv6_pending_abi_self_test && echo '  [PASS] IPv6 deferred-policy legacy call ABI' || { echo '  [FAIL] IPv6 deferred-policy ABI'; rc=1; }
    _e204_warp_listener_self_test && echo '  [PASS] WARP dual-loopback listener safety' || { echo '  [FAIL] WARP listener safety'; rc=1; }
    _e204_warp_full_commit_self_test && echo '  [PASS] WARP full-tunnel cancel/new-transaction binding' || { echo '  [FAIL] WARP full-tunnel transaction binding'; rc=1; }
    _e204_structure_audit >/dev/null && echo '  [PASS] E204 final bindings/rollback gates' || { echo '  [FAIL] E204 structure binding'; rc=1; }
    if test "$rc" -eq 0; then echo 'V199e204 result: PASS'; else echo 'V199e204 result: FAIL'; fi
    return "$rc"
}

_e204_optimization_menu_audit() {
    local rc=0 body micro f
    echo 'V199e204 optimization-menu audit:'
    body=$(declare -f _e204_advanced_menu 2>/dev/null || true)
    micro=$(declare -f _e204_micro_control_menu 2>/dev/null || true)
    for f in _e170_network_menu _e159_xray_action_tx _e170_apply_init30_tx \
        _e170_offload_action _e170_rps_action _e204_micro_control_menu \
        _e170_mss_action _e170_txq_action _e204_tc_menu _e170_bbr_kernel_menu \
        _e170_disable_legacy_tx _e170_show_optimization_status _e170_ring_action \
        _e159_apply_micro_28 _e138_warp_selective_menu _e138_warp_global_menu \
        _e140_warp_full_menu; do
        grep -q "$f" <<<"$body" || { echo "  [FAIL] 高级入口缺失：$f"; rc=1; }
    done
    for f in _e204_action_socket_keepalive _e204_action_metadata_only \
        _e204_action_route_only _e204_action_buffer_128 _e204_action_dns_ipv4 \
        _e204_tc_menu enable_zram_default _e121_install_log_retention \
        _e159_apply_micro_28; do
        grep -q "$f" <<<"$micro" || { echo "  [FAIL] 微操处理器缺失：$f"; rc=1; }
    done
    ! grep -q '_e159_action_2_to_6' <<<"$micro" || { echo '  [FAIL] 2-6仍被错误合并'; rc=1; }
    if test "$rc" -eq 0; then
        echo '  [PASS] 菜单10的17项与完整28项均绑定E204最终处理器'
    fi
    return "$rc"
}
_e188_optimization_menu_audit() { _e204_optimization_menu_audit "$@"; }

#==============================================================================
# V199e214 FINAL TRANSACTION / EIGHT-PROFILE SMALL-BBR LAYER
#==============================================================================
readonly E214_VERSION="199e230"
readonly E214_DIR="$CONFIG_DIR/e214"
readonly E214_SELF_PATH="$SCRIPT_DIR/ex199e214.sh"
readonly E214_LATEST_PATH="$SCRIPT_DIR/ex199e_latest.sh"
readonly E214_TX_ROOT="/var/backups/xray-e214"
readonly E214_HOT_LOG="$LOG_DIR/e214/hot-update-last.log"
readonly E214_CRITICAL_MARKER="$E214_DIR/CRITICAL_RECOVERY_REQUIRED.env"
readonly E214_LEGACY_E212_DIR="$CONFIG_DIR/e212"
readonly E214_LEGACY_E212_SELF_PATH="$SCRIPT_DIR/ex199e212.sh"
readonly E214_LEGACY_E212_TX_ROOT="/var/backups/xray-e212"
readonly E214_LEGACY_E212_CRITICAL_MARKER="$E214_LEGACY_E212_DIR/CRITICAL_RECOVERY_REQUIRED.env"
readonly E214_LEGACY_E210_DIR="$CONFIG_DIR/e210"
readonly E214_LEGACY_E210_SELF_PATH="$SCRIPT_DIR/ex199e210.sh"
readonly E214_LEGACY_E210_TX_ROOT="/var/backups/xray-e210"
readonly E214_LEGACY_E210_CRITICAL_MARKER="$E214_LEGACY_E210_DIR/CRITICAL_RECOVERY_REQUIRED.env"
readonly E214_LEGACY_E208_DIR="$CONFIG_DIR/e208"
readonly E214_LEGACY_E208_SELF_PATH="$SCRIPT_DIR/ex199e208.sh"
readonly E214_LEGACY_E208_TX_ROOT="/var/backups/xray-e208"
readonly E214_LEGACY_E208_CRITICAL_MARKER="$E214_LEGACY_E208_DIR/CRITICAL_RECOVERY_REQUIRED.env"
readonly E214_LEGACY_E206_DIR="$CONFIG_DIR/e206"
readonly E214_LEGACY_E206_SELF_PATH="$SCRIPT_DIR/ex199e206.sh"
readonly E214_LEGACY_E206_TX_ROOT="/var/backups/xray-e206"
readonly E214_LEGACY_E206_CRITICAL_MARKER="$E214_LEGACY_E206_DIR/CRITICAL_RECOVERY_REQUIRED.env"
readonly E214_MTU_STATE="$E214_DIR/mtu-policy.env"
readonly E214_MTU_BASELINE="$E214_DIR/mtu-baseline.tsv"
readonly E214_MTU_LOG="$LOG_DIR/e214/mtu-last.log"
readonly E214_MTU_SERVICE="/etc/systemd/system/xray-mtu-e214.service"
readonly E214_MTU_TIMER="/etc/systemd/system/xray-mtu-e214.timer"
readonly E214_MTU_UNIT="xray-mtu-e214.service"
readonly E214_MTU_TIMER_UNIT="xray-mtu-e214.timer"
E214_INTERNAL_SELF_TEST=0
E214_INTERNAL_SELF_TEST_TMP=""

# Never run `install -d -m` against an existing shared/system directory: GNU
# install applies the requested mode even when the directory already exists.
# In particular, changing /run/lock from 1777 to 0755 can break unrelated
# package managers and daemons.  Existing directories are therefore validated
# but never chmod'ed; only a genuinely missing directory receives create_mode.
_e214_ensure_directory() {
    local dir="${1:-}" create_mode="${2:-0755}"
    test -n "$dir" || return 1
    if test -e "$dir" || test -L "$dir"; then
        test -d "$dir" && test -x "$dir" || {
            error "目录路径存在但不可作为目录使用：$dir"
            return 1
        }
        return 0
    fi
    install -d -m "$create_mode" -- "$dir" || return 1
    test -d "$dir" && test ! -L "$dir"
}

_e214_ensure_run_lock() {
    _e214_ensure_directory /run/lock 0755
}

_e214_ensure_parent_dir() {
    local target="${1:-}" parent
    test -n "$target" || return 1
    parent=$(dirname -- "$target") || return 1
    _e214_ensure_directory "$parent" 0755
}

_e214_proc_start_time() {
    local pid="${1:-}"
    [[ "$pid" =~ ^[1-9][0-9]*$ ]] || return 1
    awk '{
      s=$0
      sub(/^.*\) /,"",s)
      n=split(s,a," ")
      if(n>=20 && a[20] ~ /^[0-9]+$/) print a[20]
    }' "/proc/$pid/stat" 2>/dev/null
}

_e214_prepare_tx() {
    # E214的外层快照必须先于E204状态目录的创建；否则从更老版本升级失败时，
    # “完整回滚”仍会遗留一个升级前不存在的E204目录。这里只准备E214自身
    # 的事务/日志根与标准运行锁目录，E204层由外层快照之后的基座事务准备。
    _e214_ensure_run_lock || return 1
    install -d -m 0700 "$E214_TX_ROOT" \
        "$(dirname -- "$E214_HOT_LOG")" || return 1
}

_e214_prepare() {
    _e214_prepare_tx || return 1
    install -d -m 0700 "$E214_DIR" || return 1
}

_e214_prune_root() {
    local requested_root="$1" marker="${2:-}" keep="${XRAY_E214_TX_KEEP:-12}"
    local root real row pid expected actual backup child rc=0 marker_refs=0
    local marker_lines=0 marker_bad=0
    local protected=' '
    [[ "$keep" =~ ^[0-9]+$ ]] && ((keep >= 12 && keep <= 100)) || keep=12
    root=$(readlink -f -- "$requested_root" 2>/dev/null || true)
    test -n "$root" && test -d "$root" || return 0
    if test -n "$marker" && { test -e "$marker" || test -L "$marker"; }; then
        test -f "$marker" && test ! -L "$marker" && test -r "$marker" && test -s "$marker" \
          || { warn "恢复标记异常，停止清理整个事务根：$marker" >&2; return 1; }
        while IFS= read -r backup; do
            marker_lines=$((marker_lines + 1))
            real=$(readlink -f -- "$backup" 2>/dev/null || true)
            case "$real" in
                "$root"/*)
                    child=${real#"$root"/}; child=${child%%/*}
                    if test -n "$child"; then
                        protected+="$root/$child "
                        marker_refs=$((marker_refs + 1))
                    else
                        marker_bad=1
                    fi ;;
                *) marker_bad=1 ;;
            esac
        done < <(sed -n 's/^backup=//p' "$marker" 2>/dev/null)
        test "$marker_lines" -gt 0 && test "$marker_bad" -eq 0 \
          && test "$marker_refs" -eq "$marker_lines" \
          || { warn "恢复标记含有空、越界或无效快照路径，停止清理：$marker" >&2; return 1; }
    fi
    while IFS=$'\t' read -r _ row; do
        test -n "$row" || continue
        real=$(readlink -f -- "$row" 2>/dev/null || true)
        case "$real" in "$root"/*) ;; *) rc=1; continue ;; esac
        [[ "$protected" == *" $real "* ]] && continue
        if test -e "$real/.preserve.env" || test -L "$real/.preserve.env"; then
            if ! test -f "$real/.preserve.env" || test -L "$real/.preserve.env" \
              || ! test -r "$real/.preserve.env" || ! test -s "$real/.preserve.env"; then
                warn "事务保护标记异常，保守保留快照：$real/.preserve.env" >&2
                rc=1
            fi
            continue
        fi
        if test -e "$real/.active.env" || test -L "$real/.active.env"; then
            if ! test -f "$real/.active.env" || test -L "$real/.active.env" \
              || ! test -r "$real/.active.env" || ! test -s "$real/.active.env"; then
                warn "活动事务标记异常，保守保留快照：$real/.active.env" >&2
                rc=1
                continue
            fi
            pid=$(awk -F= '$1=="pid"{print substr($0,index($0,"=")+1); exit}' \
                "$real/.active.env" 2>/dev/null || true)
            expected=$(awk -F= '$1=="start"{print substr($0,index($0,"=")+1); exit}' \
                "$real/.active.env" 2>/dev/null || true)
            if [[ ! "$pid" =~ ^[1-9][0-9]*$ || ! "$expected" =~ ^[0-9]+$ ]]; then
                warn "活动事务标记字段无效，保守保留快照：$real/.active.env" >&2
                rc=1
                continue
            fi
            if kill -0 "$pid" 2>/dev/null; then
                actual=$(_e214_proc_start_time "$pid" || true)
                if [[ ! "$actual" =~ ^[0-9]+$ ]]; then
                    warn "无法确认活动事务进程起始时间，保守保留快照：$real" >&2
                    rc=1
                    continue
                fi
                test "$actual" != "$expected" || continue
            fi
        fi
        rm -rf -- "${real:?}" 2>/dev/null || rc=1
    done < <(find "$root" -mindepth 1 -maxdepth 1 -type d -printf '%T@\t%p\n' 2>/dev/null \
        | LC_ALL=C sort -nr | awk -F '\t' -v keep="$keep" 'NR>keep{print $1 "\t" $2}')
    return "$rc"
}

_e214_prune_transactions() {
    local rc=0
    _e214_prune_root "$E214_TX_ROOT" "$E214_CRITICAL_MARKER" || rc=1
    _e214_prune_root "$E214_LEGACY_E212_TX_ROOT" "$E214_LEGACY_E212_CRITICAL_MARKER" || rc=1
    _e214_prune_root "$E214_LEGACY_E210_TX_ROOT" "$E214_LEGACY_E210_CRITICAL_MARKER" || rc=1
    _e214_prune_root "$E214_LEGACY_E208_TX_ROOT" "$E214_LEGACY_E208_CRITICAL_MARKER" || rc=1
    _e214_prune_root "$E214_LEGACY_E206_TX_ROOT" "$E214_LEGACY_E206_CRITICAL_MARKER" || rc=1
    return "$rc"
}

# E204 is still the rollback engine, but its older cleanup routine treated an
# empty/malformed activity marker as disposable.  Bind it to the same fail-
# closed implementation so no inherited cleanup path can delete uncertain
# recovery evidence.
_e204_prune_transactions() {
    local saved_keep="${XRAY_E214_TX_KEEP-}" rc=0
    XRAY_E214_TX_KEEP="${XRAY_E204_TX_KEEP:-12}"
    _e214_prune_root "$E204_TX_ROOT" "$E204_CRITICAL_MARKER" || rc=1
    if test -n "$saved_keep"; then XRAY_E214_TX_KEEP="$saved_keep"; else unset XRAY_E214_TX_KEEP; fi
    return "$rc"
}

_e214_new_tx() {
    local purpose="${1:-transaction}" d start owner_pid=""
    owner_pid=$(_e230_tx_owner_pid) || return 1
    _e214_prepare_tx || return 1
    purpose=$(printf '%s' "$purpose" | tr -cd 'A-Za-z0-9._-' | cut -c1-48)
    test -n "$purpose" || purpose=transaction
    d="$E214_TX_ROOT/${purpose}-$(date +%Y%m%d_%H%M%S)-${owner_pid}-$RANDOM"
    install -d -m 0700 "$d" || return 1
    start=$(_e214_proc_start_time "$owner_pid" || true)
    [[ "$start" =~ ^[0-9]+$ ]] || { rmdir -- "$d" 2>/dev/null || true; return 1; }
    printf 'pid=%s\nstart=%s\n' "$owner_pid" "$start" >"$d/.active.env" || return 1
    chmod 0600 "$d/.active.env" || return 1
    _e214_prune_transactions || warn 'E214旧事务快照未能完全收敛。' >&2
    printf '%s\n' "$d"
}

_e214_tx_close() {
    local tx="${1:-}" root real
    test -n "$tx" || return 0
    root=$(readlink -f -- "$E214_TX_ROOT" 2>/dev/null || true)
    real=$(readlink -f -- "$tx" 2>/dev/null || true)
    test -n "$root" && test -d "$root" && test -n "$real" || return 1
    case "$real" in
        "$root"/*) rm -f -- "$real/.active.env" ;;
        *) error "拒绝关闭E214事务根目录外的标记：$tx"; return 1 ;;
    esac
}

_e214_preserve_tx() {
    local backup="$1" reason="${2:-unspecified}" root real child tx tmp
    root=$(readlink -f -- "$E214_TX_ROOT" 2>/dev/null || true)
    real=$(readlink -f -- "$backup" 2>/dev/null || true)
    test -n "$root" && test -d "$root" && test -n "$real" || return 1
    case "$real" in
        "$root"/*)
            child=${real#"$root"/}; child=${child%%/*}; test -n "$child" || return 1
            tx="$root/$child" ;;
        *) return 1 ;;
    esac
    tmp="$tx/.preserve.env.new.$$"
    {
        printf 'time=%s\n' "$(date '+%F %T %z')"
        printf 'reason=%s\n' "$(printf '%s' "$reason" | tr '\r\n' '  ')"
    } >"$tmp" || return 1
    chmod 0600 "$tmp" || { rm -f -- "$tmp"; return 1; }
    mv -f -- "$tmp" "$tx/.preserve.env"
}

_e214_mark_critical() {
    local operation="$1" backup="$2" reason="$3" tmp preserved=0 marked=0
    _e214_preserve_tx "$backup" "$operation: $reason" && preserved=1 || true
    _e214_prepare || return 1
    tmp=$(_e118_mktemp e214-critical) || return 1
    {
        printf 'version=%s\n' "$E214_VERSION"
        printf 'time=%s\n' "$(date '+%F %T %z')"
        printf 'operation=%s\n' "$operation"
        printf 'backup=%s\n' "$backup"
        printf 'reason=%s\n' "$(printf '%s' "$reason" | tr '\r\n' '  ')"
    } >"$tmp" || return 1
    _e118_atomic_install "$tmp" "$E214_CRITICAL_MARKER" 0600 && marked=1 || true
    ((preserved == 1 || marked == 1))
}

# Include the E214 executable/state in inherited system snapshots without
# recursively snapshotting the backup tree itself.
if declare -F _e138_system_paths >/dev/null 2>&1; then
    eval "$(declare -f _e138_system_paths | sed '1s/_e138_system_paths/_e214_system_paths_base/')"
fi
_e138_system_paths() {
    _e214_system_paths_base "$@"
    printf '%s\n' "$E214_LEGACY_E206_DIR" "$E214_LEGACY_E206_SELF_PATH" \
        "$E214_LEGACY_E208_DIR" "$E214_LEGACY_E208_SELF_PATH" \
        "$E214_LEGACY_E210_DIR" "$E214_LEGACY_E210_SELF_PATH" \
        "$E214_LEGACY_E212_DIR" "$E214_LEGACY_E212_SELF_PATH" \
        "$E214_DIR" "$E214_SELF_PATH" "$E214_LATEST_PATH" \
        "$E216_DIR" "$E216_SELF_PATH" "$E216_MSS_BACKEND_STATE" \
        "$E218_DIR" "$E218_SELF_PATH" "$E218_MSS_OWNER_STATE" "$E218_MSS_AUDIT" \
        "$E214_MTU_STATE" "$E214_MTU_BASELINE" \
        "$E214_MTU_SERVICE" "$E214_MTU_TIMER"
}

# E212 and every retained network owner only set TCP/queueing sysctls.  They do
# not change a host link's MTU.  E214 keeps link MTU in a separate owner so a
# full-network transaction, small-BBR switch, WARP repair, or hot update cannot
# silently absorb or overwrite it.  WARP/tun/wg virtual devices are deliberately
# excluded; their protocol MTU (for example WireGuard MTU=1280) remains owned by
# the WARP layer.
_e214_mtu_sysroot() { printf '%s\n' "${E214_MTU_SYSFS_ROOT:-/sys/class/net}"; }

_e214_mtu_iface_valid() {
    local iface="${1:-}"
    test -n "$iface" && test "${#iface}" -le 15 \
      && [[ "$iface" =~ ^[A-Za-z0-9_.:-]+$ ]]
}

_e214_mtu_iface_candidate() {
    local iface="${1:-}" root
    _e214_mtu_iface_valid "$iface" || return 1
    case "$iface" in
        lo|docker*|br-*|virbr*|veth*|cni*|flannel*|cali*|kube*|podman*|\
        vnet*|vmnet*|ifb*|dummy*|tun*|tap*|wg*|warp*|CloudflareWARP*|\
        tailscale*|zt*|ip6tnl*|sit*|gre*|gretap*|erspan*|vxlan*|geneve*|pf-wg*)
            return 1 ;;
    esac
    root=$(_e214_mtu_sysroot) || return 1
    test -r "$root/$iface/mtu"
}

_e214_mtu_value_valid() {
    local value="${1:-}"
    [[ "$value" =~ ^[0-9]+$ ]] && ((value >= 1280 && value <= 9000))
}

_e214_mtu_original_value_valid() {
    local value="${1:-}"
    [[ "$value" =~ ^[0-9]+$ ]] && ((value >= 68 && value <= 65535))
}

_e214_mtu_current() {
    local iface="${1:-}" root value
    _e214_mtu_iface_valid "$iface" || return 1
    root=$(_e214_mtu_sysroot) || return 1
    value=$(tr -d '[:space:]' <"$root/$iface/mtu" 2>/dev/null || true)
    _e214_mtu_original_value_valid "$value" || return 1
    printf '%s\n' "$value"
}

_e214_mtu_candidates() {
    local root p iface
    root=$(_e214_mtu_sysroot) || return 1
    for p in "$root"/*; do
        test -e "$p" || continue
        iface=${p##*/}
        _e214_mtu_iface_candidate "$iface" && printf '%s\n' "$iface"
    done | LC_ALL=C sort -u
}

_e214_mtu_default_iface() {
    local iface
    while IFS= read -r iface; do
        iface=${iface%%@*}
        if _e214_mtu_iface_candidate "$iface"; then
            printf '%s\n' "$iface"
            return 0
        fi
    done < <(
        {
            ip -4 route get 1.1.1.1 2>/dev/null || true
            ip -4 route show default 2>/dev/null || true
            ip -6 route get 2606:4700:4700::1111 2>/dev/null || true
            ip -6 route show default 2>/dev/null || true
        } | awk '{for(i=1;i<=NF;i++)if($i=="dev" && (i+1)<=NF){print $(i+1);break}}'
    )
    return 1
}

_e214_mtu_baseline_validate() {
    local file="${1:-}" line iface value count=0
    local -A seen=()
    test -f "$file" && test ! -L "$file" && test -r "$file" && test -s "$file" || return 1
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([A-Za-z0-9_.:-]+)\|([0-9]+)$ ]] || return 1
        iface=${BASH_REMATCH[1]}; value=${BASH_REMATCH[2]}
        _e214_mtu_iface_valid "$iface" || return 1
        _e214_mtu_original_value_valid "$value" || return 1
        test -z "${seen[$iface]+x}" || return 1
        seen[$iface]=1; count=$((count + 1))
    done <"$file"
    test "$count" -ge 1 && test "$count" -le 64
}

_e214_mtu_state_get_file() {
    local file="${1:-}" key="${2:-}"
    awk -F= -v wanted="$key" '
      $1==wanted {n++; value=substr($0,index($0,"=")+1)}
      END {if(n==1)print value; else exit 1}
    ' "$file" 2>/dev/null
}

_e214_mtu_state_validate() {
    local state="${1:-$E214_MTU_STATE}" baseline="${2:-$E214_MTU_BASELINE}"
    local line key value count=0 version active selector configured target last hash epoch actual
    local -A seen=()
    test -f "$state" && test ! -L "$state" && test -r "$state" && test -s "$state" || return 1
    _e214_mtu_baseline_validate "$baseline" || return 1
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([A-Za-z_][A-Za-z0-9_]*)=([A-Za-z0-9_.:-]+)$ ]] || return 1
        key=${BASH_REMATCH[1]}; value=${BASH_REMATCH[2]}
        case "$key" in
            version|active|selector|configured_iface|target_mtu|last_iface|baseline_sha256|updated_epoch) ;;
            *) return 1 ;;
        esac
        test -z "${seen[$key]+x}" || return 1
        seen[$key]=1; count=$((count + 1))
    done <"$state"
    test "$count" -eq 8 || return 1
    for key in version active selector configured_iface target_mtu last_iface baseline_sha256 updated_epoch; do
        test -n "${seen[$key]+x}" || return 1
    done
    version=$(_e214_mtu_state_get_file "$state" version) || return 1
    active=$(_e214_mtu_state_get_file "$state" active) || return 1
    selector=$(_e214_mtu_state_get_file "$state" selector) || return 1
    configured=$(_e214_mtu_state_get_file "$state" configured_iface) || return 1
    target=$(_e214_mtu_state_get_file "$state" target_mtu) || return 1
    last=$(_e214_mtu_state_get_file "$state" last_iface) || return 1
    hash=$(_e214_mtu_state_get_file "$state" baseline_sha256) || return 1
    epoch=$(_e214_mtu_state_get_file "$state" updated_epoch) || return 1
    test "$version" = 199e214 && test "$active" = 1 || return 1
    case "$selector" in
        auto) test "$configured" = - || return 1 ;;
        iface) _e214_mtu_iface_valid "$configured" && test "$configured" = "$last" || return 1 ;;
        *) return 1 ;;
    esac
    _e214_mtu_value_valid "$target" || return 1
    _e214_mtu_iface_valid "$last" || return 1
    [[ "$hash" =~ ^[0-9a-f]{64}$ ]] || return 1
    [[ "$epoch" =~ ^[0-9]{1,20}$ ]] || return 1
    actual=$(sha256sum "$baseline" 2>/dev/null | awk '{print $1}') || return 1
    test "$actual" = "$hash" || return 1
    awk -F'|' -v wanted="$last" '$1==wanted{n++}END{exit(n==1?0:1)}' "$baseline"
}

_e214_mtu_any_state() {
    test -e "$E214_MTU_STATE" || test -L "$E214_MTU_STATE" \
      || test -e "$E214_MTU_BASELINE" || test -L "$E214_MTU_BASELINE" \
      || test -e "$E214_MTU_SERVICE" || test -L "$E214_MTU_SERVICE" \
      || test -e "$E214_MTU_TIMER" || test -L "$E214_MTU_TIMER" \
      || { test -d /run/systemd/system \
        && { systemctl is-enabled --quiet "$E214_MTU_UNIT" 2>/dev/null \
          || systemctl is-enabled --quiet "$E214_MTU_TIMER_UNIT" 2>/dev/null \
          || systemctl is-active --quiet "$E214_MTU_TIMER_UNIT" 2>/dev/null; }; }
}

_e214_mtu_active() { _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE"; }

_e214_mtu_persistence_validate() {
    local selector target last actual resolved
    _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE" || return 1
    test -f "$E214_SELF_PATH" && test ! -L "$E214_SELF_PATH" \
      && test -x "$E214_SELF_PATH" && bash -n "$E214_SELF_PATH" || return 1
    test -f "$E214_MTU_SERVICE" && test ! -L "$E214_MTU_SERVICE" \
      && test -f "$E214_MTU_TIMER" && test ! -L "$E214_MTU_TIMER" || return 1
    grep -Fqx 'Type=oneshot' "$E214_MTU_SERVICE" || return 1
    grep -Fqx "ExecStart=/bin/bash $E214_SELF_PATH --mtu-reconcile" "$E214_MTU_SERVICE" || return 1
    grep -Fqx 'WantedBy=multi-user.target' "$E214_MTU_SERVICE" || return 1
    ! grep -q 'RemainAfterExit' "$E214_MTU_SERVICE" || return 1
    grep -Fqx 'OnUnitActiveSec=5min' "$E214_MTU_TIMER" || return 1
    systemctl is-enabled --quiet "$E214_MTU_UNIT" 2>/dev/null || return 1
    systemctl is-enabled --quiet "$E214_MTU_TIMER_UNIT" 2>/dev/null || return 1
    systemctl is-active --quiet "$E214_MTU_TIMER_UNIT" 2>/dev/null || return 1
    selector=$(_e214_mtu_state_get_file "$E214_MTU_STATE" selector) || return 1
    target=$(_e214_mtu_state_get_file "$E214_MTU_STATE" target_mtu) || return 1
    last=$(_e214_mtu_state_get_file "$E214_MTU_STATE" last_iface) || return 1
    actual=$(_e214_mtu_current "$last" 2>/dev/null || true)
    test "$actual" = "$target" || return 1
    if test "$selector" = auto; then
        resolved=$(_e214_mtu_default_iface 2>/dev/null || true)
        test "$resolved" = "$last" || return 1
    fi
    _e214_mtu_route_health "$last" "$selector"
}

# Extend every whole-system snapshot with the runtime MTU of stable host-link
# candidates and the exact service state of the E214 MTU owner.  This is what
# makes menu 28, full-network, small-BBR and hot-update rollback preserve an
# independently selected MTU.
if declare -F _e140_system_snapshot >/dev/null 2>&1; then
    eval "$(declare -f _e140_system_snapshot | sed '1s/_e140_system_snapshot/_e214_system_snapshot_base/')"
fi
if declare -F _e140_system_restore >/dev/null 2>&1; then
    eval "$(declare -f _e140_system_restore | sed '1s/_e140_system_restore/_e214_system_restore_base/')"
fi
_e140_system_snapshot() {
    local b="$1" iface mtu unit
    _e214_system_snapshot_base "$b" || return 1
    : >"$b/e214-link-mtu.tsv" || return 1
    while IFS= read -r iface; do
        test -n "$iface" || continue
        mtu=$(_e214_mtu_current "$iface") || return 1
        printf '%s|%s\n' "$iface" "$mtu" >>"$b/e214-link-mtu.tsv" || return 1
    done < <(_e214_mtu_candidates)
    : >"$b/e214-mtu-services.env" || return 1
    for unit in "$E214_MTU_UNIT" "$E214_MTU_TIMER_UNIT"; do
        _e204_service_snapshot "$unit" >>"$b/e214-mtu-services.env" || return 1
    done
    (cd "$b" && sha256sum e214-link-mtu.tsv e214-mtu-services.env >e214-mtu-runtime.sha256) || return 1
}

_e140_system_restore() {
    local b="$1" iface mtu now rc=0
    if test -e "$b/e214-mtu-runtime.sha256" || test -e "$b/e214-link-mtu.tsv" \
      || test -e "$b/e214-mtu-services.env"; then
        test -f "$b/e214-mtu-runtime.sha256" && test ! -L "$b/e214-mtu-runtime.sha256" \
          && test -f "$b/e214-link-mtu.tsv" && test ! -L "$b/e214-link-mtu.tsv" \
          && test -f "$b/e214-mtu-services.env" && test ! -L "$b/e214-mtu-services.env" \
          && (cd "$b" && sha256sum -c e214-mtu-runtime.sha256 >/dev/null 2>&1) || {
            error "E214网卡MTU/服务运行态快照损坏：$b"
            return 1
        }
    fi
    _e214_system_restore_base "$b" || rc=1
    if test -f "$b/e214-link-mtu.tsv"; then
        while IFS='|' read -r iface mtu; do
            test -n "$iface" || continue
            _e214_mtu_iface_valid "$iface" && _e214_mtu_original_value_valid "$mtu" || { rc=1; continue; }
            if _e214_mtu_iface_candidate "$iface"; then
                ip link set dev "$iface" mtu "$mtu" >/dev/null 2>&1 || { rc=1; continue; }
                now=$(_e214_mtu_current "$iface" 2>/dev/null || true)
                test "$now" = "$mtu" || rc=1
            fi
        done <"$b/e214-link-mtu.tsv"
    fi
    test ! -s "$b/e214-mtu-services.env" \
      || _e204_services_restore_file "$b/e214-mtu-services.env" || rc=1
    return "$rc"
}

_e214_mtu_baseline_has() {
    local file="${1:-}" iface="${2:-}"
    awk -F'|' -v wanted="$iface" '$1==wanted{n++}END{exit(n==1?0:1)}' "$file" 2>/dev/null
}

_e214_mtu_baseline_add() {
    local file="${1:-}" iface="${2:-}" value tmp
    _e214_mtu_iface_candidate "$iface" || return 1
    if _e214_mtu_baseline_has "$file" "$iface"; then return 0; fi
    value=$(_e214_mtu_current "$iface") || return 1
    printf '%s|%s\n' "$iface" "$value" >>"$file" || return 1
    tmp="${file}.sort.$$"
    LC_ALL=C sort -t'|' -k1,1 "$file" >"$tmp" || { rm -f -- "$tmp"; return 1; }
    mv -f -- "$tmp" "$file" || { rm -f -- "$tmp"; return 1; }
    _e214_mtu_baseline_validate "$file"
}

_e214_mtu_restore_baseline_except() {
    local file="${1:-}" keep="${2:-}" iface value now rc=0
    _e214_mtu_baseline_validate "$file" || return 1
    while IFS='|' read -r iface value; do
        test -n "$iface" || continue
        test "$iface" = "$keep" && continue
        if ! _e214_mtu_iface_candidate "$iface"; then
            warn "MTU基线中的旧网卡当前不存在，跳过运行态恢复：$iface"
            continue
        fi
        ip link set dev "$iface" mtu "$value" >/dev/null 2>&1 || { rc=1; continue; }
        now=$(_e214_mtu_current "$iface" 2>/dev/null || true)
        test "$now" = "$value" || rc=1
    done <"$file"
    return "$rc"
}

_e214_mtu_apply_runtime() {
    local iface="${1:-}" value="${2:-}" now
    _e214_mtu_iface_candidate "$iface" || { error "拒绝修改虚拟、隧道或不存在的网卡：$iface"; return 1; }
    _e214_mtu_value_valid "$value" || { error 'MTU必须是1280-9000之间的整数。'; return 1; }
    ip link set dev "$iface" mtu "$value" >/dev/null 2>&1 || return 1
    now=$(_e214_mtu_current "$iface" 2>/dev/null || true)
    test "$now" = "$value" || {
        error "网卡MTU读回不一致：iface=$iface expected=$value actual=${now:-unreadable}"
        return 1
    }
}

_e214_mtu_route_health() {
    local iface="${1:-}" selector="${2:-iface}" resolved client route
    _e214_mtu_iface_candidate "$iface" || return 1
    if test "$selector" = auto; then
        resolved=$(_e214_mtu_default_iface 2>/dev/null || true)
        test "$resolved" = "$iface" || return 1
    fi
    client=${SSH_CONNECTION%% *}
    if test -n "$client" && test "$client" != "$SSH_CONNECTION"; then
        if [[ "$client" == *:* ]]; then
            [[ "$client" =~ ^[0-9A-Fa-f:.]+$ ]] || return 1
            route=$(ip -6 route get "$client" 2>/dev/null || true)
        else
            [[ "$client" =~ ^[0-9.]+$ ]] || return 1
            route=$(ip -4 route get "$client" 2>/dev/null || true)
        fi
        test -n "$route" || return 1
    fi
    return 0
}

_e214_mtu_write_state_candidate() {
    local out="$1" baseline="$2" selector="$3" configured="$4" target="$5" last="$6" hash
    _e214_mtu_baseline_validate "$baseline" || return 1
    case "$selector" in
        auto) test "$configured" = - || return 1 ;;
        iface) _e214_mtu_iface_valid "$configured" && test "$configured" = "$last" || return 1 ;;
        *) return 1 ;;
    esac
    _e214_mtu_value_valid "$target" && _e214_mtu_iface_valid "$last" || return 1
    hash=$(sha256sum "$baseline" | awk '{print $1}') || return 1
    {
        printf 'version=199e214\n'
        printf 'active=1\n'
        printf 'selector=%s\n' "$selector"
        printf 'configured_iface=%s\n' "$configured"
        printf 'target_mtu=%s\n' "$target"
        printf 'last_iface=%s\n' "$last"
        printf 'baseline_sha256=%s\n' "$hash"
        printf 'updated_epoch=%s\n' "$(date +%s)"
    } >"$out" || return 1
    chmod 0600 "$out" || return 1
    _e214_mtu_state_validate "$out" "$baseline"
}

_e214_mtu_write_unit_candidates() {
    local service="$1" timer="$2"
    cat >"$service" <<EOF_E214_MTU_SERVICE
[Unit]
Description=Xray E214 host NIC MTU reconcile
Wants=network-online.target
After=network-online.target
Before=xray.service
ConditionPathExists=$E214_MTU_STATE

[Service]
Type=oneshot
ExecStart=/bin/bash $E214_SELF_PATH --mtu-reconcile

[Install]
WantedBy=multi-user.target
EOF_E214_MTU_SERVICE
    cat >"$timer" <<EOF_E214_MTU_TIMER
[Unit]
Description=Periodic Xray E214 host NIC MTU drift check

[Timer]
OnActiveSec=5min
OnUnitActiveSec=5min
AccuracySec=30s
Unit=$E214_MTU_UNIT

[Install]
WantedBy=timers.target
EOF_E214_MTU_TIMER
    chmod 0644 "$service" "$timer" || return 1
    grep -Fqx 'Type=oneshot' "$service" \
      && grep -Fqx "ExecStart=/bin/bash $E214_SELF_PATH --mtu-reconcile" "$service" \
      && grep -Fqx 'WantedBy=multi-user.target' "$service" \
      && ! grep -q 'RemainAfterExit' "$service" \
      && grep -Fqx 'OnUnitActiveSec=5min' "$timer"
}

_e214_mtu_commit() {
    local work="$1" baseline="$2" selector="$3" configured="$4" target="$5" iface="$6"
    local state_c="$work/mtu-policy.env" service_c="$work/xray-mtu-e214.service"
    local timer_c="$work/xray-mtu-e214.timer"
    _e214_prepare || return 1
    _e214_mtu_write_state_candidate "$state_c" "$baseline" "$selector" "$configured" "$target" "$iface" || return 1
    _e214_mtu_write_unit_candidates "$service_c" "$timer_c" || return 1
    _e118_atomic_install "$baseline" "$E214_MTU_BASELINE" 0600 || return 1
    _e118_atomic_install "$state_c" "$E214_MTU_STATE" 0600 || return 1
    _e118_atomic_install "$service_c" "$E214_MTU_SERVICE" 0644 || return 1
    _e118_atomic_install "$timer_c" "$E214_MTU_TIMER" 0644 || return 1
    _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE" || return 1
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    systemctl enable "$E214_MTU_UNIT" "$E214_MTU_TIMER_UNIT" >/dev/null 2>&1 || return 1
    systemctl start "$E214_MTU_UNIT" >/dev/null 2>&1 || return 1
    systemctl start "$E214_MTU_TIMER_UNIT" >/dev/null 2>&1 || return 1
    systemctl is-enabled --quiet "$E214_MTU_UNIT" 2>/dev/null || return 1
    systemctl is-enabled --quiet "$E214_MTU_TIMER_UNIT" 2>/dev/null || return 1
    systemctl is-active --quiet "$E214_MTU_TIMER_UNIT" 2>/dev/null || return 1
    test "$(systemctl show "$E214_MTU_UNIT" -p Result --value 2>/dev/null || true)" = success || return 1
    _e214_mtu_persistence_validate
}

_e214_mtu_log_line() {
    install -d -m 0750 "$(dirname -- "$E214_MTU_LOG")" 2>/dev/null || return 0
    printf '%s %s\n' "$(date '+%F %T %z')" "$*" >>"$E214_MTU_LOG" 2>/dev/null || true
}

_e214_mtu_reconcile() {
    local selector configured target last iface current
    _e214_ensure_run_lock || return 1
    exec 207>/run/lock/xray-mtu-e214.lock
    flock -n 207 || { _e214_mtu_log_line 'skip=busy'; return 0; }
    if ! _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE"; then
        _e214_mtu_log_line 'result=failed reason=invalid-state-or-baseline'
        return 1
    fi
    selector=$(_e214_mtu_state_get_file "$E214_MTU_STATE" selector) || return 1
    configured=$(_e214_mtu_state_get_file "$E214_MTU_STATE" configured_iface) || return 1
    target=$(_e214_mtu_state_get_file "$E214_MTU_STATE" target_mtu) || return 1
    last=$(_e214_mtu_state_get_file "$E214_MTU_STATE" last_iface) || return 1
    if test "$selector" = auto; then
        iface=$(_e214_mtu_default_iface 2>/dev/null || true)
        if test -z "$iface" || test "$iface" != "$last"; then
            _e214_mtu_log_line "result=degraded reason=default-route-changed expected=$last actual=${iface:-none} action=manual-reconfirm"
            return 0
        fi
    else
        iface=$configured
        test "$iface" = "$last" || return 1
    fi
    _e214_mtu_apply_runtime "$iface" "$target" || {
        _e214_mtu_log_line "result=failed iface=$iface target=$target reason=write-or-readback"
        return 1
    }
    _e214_mtu_route_health "$iface" "$selector" || {
        _e214_mtu_log_line "result=failed iface=$iface target=$target reason=route-readback"
        return 1
    }
    current=$(_e214_mtu_current "$iface") || return 1
    _e214_mtu_log_line "result=ok selector=$selector iface=$iface target=$target actual=$current"
}

_e214_mtu_status() {
    local default_iface iface mtu oper marker selector configured target last original actual resolved
    title 'V199e230：宿主机网卡 MTU 状态（E214稳定所有权，只读）'
    default_iface=$(_e214_mtu_default_iface 2>/dev/null || true)
    echo '  E220行为: 第28项、完整127请求和小BBR均不设置宿主机网卡MTU。'
    echo '  E220策略: 沿用E214稳定所有权，只管理明确确认的宿主机出口；不管理wg/tun/WARP/Docker虚拟接口。'
    echo "  tcp_mtu_probing: $(sysctl -n net.ipv4.tcp_mtu_probing 2>/dev/null || echo unsupported)（不会改变网卡MTU）"
    hr
    if _e214_mtu_any_state; then
        if _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE"; then
            selector=$(_e214_mtu_state_get_file "$E214_MTU_STATE" selector)
            configured=$(_e214_mtu_state_get_file "$E214_MTU_STATE" configured_iface)
            target=$(_e214_mtu_state_get_file "$E214_MTU_STATE" target_mtu)
            last=$(_e214_mtu_state_get_file "$E214_MTU_STATE" last_iface)
            actual=$(_e214_mtu_current "$last" 2>/dev/null || echo unavailable)
            original=$(awk -F'|' -v wanted="$last" '$1==wanted{print $2;exit}' "$E214_MTU_BASELINE")
            resolved=$(_e214_mtu_default_iface 2>/dev/null || true)
            echo "  owner: active  selector=$selector  configured=$configured"
            echo "  managed_iface=$last  target=$target  actual=$actual  original=$original"
            if test "$actual" != "$target"; then
                warn '运行态MTU与目标不一致；可执行菜单27→4立即复检。'
            fi
            if _e214_mtu_persistence_validate; then
                echo '  persistence: service=enabled timer=enabled/active readback=ok'
            else
                warn '持久服务/定时器不完整；请用菜单27重新应用同一MTU修复。'
            fi
            if test "$selector" = auto && test "$resolved" != "$last"; then
                warn "默认出口已变化：当前=${resolved:-none}，为防误改新网卡，自动复检不会接管；请重新确认应用。"
            fi
        else
            error 'E214 MTU状态或基线损坏/不一致；拒绝自动写网卡。'
        fi
    else
        echo '  owner: disabled（实际MTU由云平台/发行版/networkd/NetworkManager决定）'
    fi
    hr
    printf '  %-15s %-8s %-10s\n' 'interface' 'mtu' 'state/default'
    while IFS= read -r iface; do
        mtu=$(_e214_mtu_current "$iface" 2>/dev/null || echo '?')
        oper=$(tr -d '[:space:]' <"$(_e214_mtu_sysroot)/$iface/operstate" 2>/dev/null || echo '?')
        marker="$oper"; test "$iface" != "$default_iface" || marker="$oper/default"
        printf '  %-15s %-8s %-10s\n' "$iface" "$mtu" "$marker"
    done < <(_e214_mtu_candidates)
    test -n "$default_iface" && echo "  当前自动识别出口：$default_iface" || warn '未能识别稳定的IPv4/IPv6默认出口。'
}

_e214_mtu_guard_confirm() {
    local guard="${1:-}" tmp
    test -n "$guard" || return 1
    tmp="${guard}.new.$$"
    printf 'confirmed=1\ntime=%s\n' "$(date +%s)" >"$tmp" || return 1
    chmod 0600 "$tmp" || { rm -f -- "$tmp"; return 1; }
    mv -f -- "$tmp" "$guard"
}

_e214_mtu_guard_is_confirmed() {
    local guard="${1:-}"
    test -f "$guard" && test ! -L "$guard" \
      && grep -Fqx 'confirmed=1' "$guard" 2>/dev/null
}

_e214_mtu_transient_stop() {
    local unit="${1:-}"
    test -n "$unit" || return 0
    systemctl stop "$unit.timer" "$unit.service" >/dev/null 2>&1 || true
    systemctl reset-failed "$unit.timer" "$unit.service" >/dev/null 2>&1 || true
}

_e214_mtu_rollback_snapshot() {
    local snapshot="${1:-}" guard="${2:-}" root real tx lock guard_parent rc=0
    root=$(readlink -f -- "$E214_TX_ROOT" 2>/dev/null || true)
    real=$(readlink -f -- "$snapshot" 2>/dev/null || true)
    test -n "$root" && test -d "$root" && test -n "$real" && test -d "$real" || return 1
    case "$real" in "$root"/*/system) ;; *) return 1 ;; esac
    tx=${real%/system}
    test "${guard##*/}" = mtu-confirmed || return 1
    guard_parent=$(readlink -f -- "$(dirname -- "$guard")" 2>/dev/null || true)
    test "$guard_parent" = "$tx" || return 1
    guard="$tx/mtu-confirmed"
    lock="$tx/mtu-rollback.lock"
    exec 208>"$lock"
    flock 208 || return 1
    _e214_mtu_guard_is_confirmed "$guard" && return 0
    _e140_system_restore "$real" || rc=1
    if test "$rc" -eq 0; then
        _e214_mtu_log_line "result=rolled-back snapshot=$real reason=confirmation-timeout-or-session-loss"
        _e214_tx_close "$tx" || true
        return 0
    fi
    _e214_mark_critical mtu-timeout "$real" 'automatic MTU rollback/readback failed' || true
    _e214_mtu_log_line "result=critical snapshot=$real reason=automatic-rollback-failed"
    return 1
}

_e214_mtu_schedule_rollback() {
    local unit="$1" runner="$2" snapshot="$3" guard="$4"
    command -v systemd-run >/dev/null 2>&1 || return 1
    systemd-run --quiet --collect --unit="$unit" --on-active=120s \
      --timer-property=AccuracySec=1s --property=Type=oneshot \
      /bin/bash "$runner" --mtu-rollback-snapshot "$snapshot" "$guard" >/dev/null
}

_e214_mtu_restore_guarded() {
    local tx="$1" unit="$2" guard="$3" rc=0
    exec 208>"$tx/mtu-rollback.lock"
    flock 208 || return 1
    _e140_system_restore "$tx/system" || rc=1
    if test "$rc" -eq 0; then
        _e214_mtu_guard_confirm "$guard" || rc=1
    fi
    flock -u 208 || true
    if test "$rc" -eq 0; then
        _e214_mtu_transient_stop "$unit"
        _e214_tx_close "$tx" || true
        return 0
    fi
    _e214_mark_critical mtu-apply "$tx/system" 'interactive MTU rollback/readback failed' || true
    return 1
}

_e214_mtu_set_interactive() (
    local selector="${1:-auto}" configured="${2:--}" target="${3:-}" iface tx="" unit="" guard=""
    local runner baseline_work answer token snapshot_ready=0 finished=0 rc=0
    _e214_mtu_exit_guard() {
        local status="${1:-1}"
        trap - EXIT HUP INT TERM
        if test "$snapshot_ready" -eq 1 && test "$finished" -eq 0 && test -n "$tx"; then
            error 'MTU事务被中断，立即恢复操作前网卡、文件与服务状态。'
            _e214_mtu_restore_guarded "$tx" "$unit" "$guard" || true
            test "$status" -ne 0 || status=1
        elif test -n "$tx"; then
            _e214_tx_close "$tx" || true
        fi
        [[ "$status" =~ ^[0-9]+$ ]] || status=1
        exit "$status"
    }
    trap '_e214_mtu_exit_guard $?' EXIT
    trap 'exit 129' HUP; trap 'exit 130' INT; trap 'exit 143' TERM
    case "$selector" in
        auto) configured=-; iface=$(_e214_mtu_default_iface 2>/dev/null || true) ;;
        iface) iface=$configured ;;
        *) error 'MTU selector无效。'; return 1 ;;
    esac
    _e214_mtu_iface_candidate "$iface" || { error "无法把网卡作为宿主机MTU目标：${iface:-none}"; return 1; }
    _e214_mtu_value_valid "$target" || { error 'MTU必须是1280-9000之间的整数。'; return 1; }
    token="APPLY-MTU-$target"
    warn "将修改宿主机网卡 $iface 的MTU为 $target；错误值可能使当前SSH断线。"
    echo '  WARP/wg/tun虚拟接口不会被修改。操作后仍需第二次限时确认。'
    read -rp "输入 $token 开始安全事务: " answer || true
    test "$answer" = "$token" || { info '已取消，系统未修改。'; return 0; }
    _e214_prepare || return 1
    _e214_ensure_run_lock || return 1
    exec 207>/run/lock/xray-mtu-e214.lock
    flock -n 207 || { error '已有MTU应用/复检事务正在运行。'; return 1; }
    if _e214_mtu_any_state; then
        _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE" || {
            error '现有MTU所有权状态不完整；拒绝覆盖，先查看菜单27状态。'
            return 1
        }
    fi
    tx=$(_e214_new_tx mtu-apply) || return 1
    _e140_system_snapshot "$tx/system" || { _e214_tx_close "$tx" || true; return 1; }
    snapshot_ready=1
    runner="$tx/mtu-rollback-runner.sh"; guard="$tx/mtu-confirmed"
    install -m 0700 "$SCRIPT_PATH" "$runner" && bash -n "$runner" || return 1
    unit="xray-mtu-e214-rollback-$$-$RANDOM"
    _e214_mtu_schedule_rollback "$unit" "$runner" "$tx/system" "$guard" || {
        error '无法创建独立断线回滚定时器；未修改MTU。'
        return 1
    }
    baseline_work="$tx/mtu-baseline.work"
    if _e214_mtu_active; then
        install -m 0600 "$E214_MTU_BASELINE" "$baseline_work" || return 1
        _e214_mtu_restore_baseline_except "$baseline_work" "$iface" || return 1
    else
        : >"$baseline_work" || return 1
        chmod 0600 "$baseline_work" || return 1
    fi
    _e214_mtu_baseline_add "$baseline_work" "$iface" || return 1
    _e214_mtu_apply_runtime "$iface" "$target" || return 1
    _e214_mtu_route_health "$iface" "$selector" || {
        error '修改后路由/SSH回程只读复检失败。'
        return 1
    }
    echo
    info "临时MTU已读回：$iface=$target"
    warn '请在90秒内确认当前SSH/代理仍正常；不确认会恢复完整快照。'
    read -r -t 90 -p '输入 KEEP-MTU 确认永久生效: ' answer || answer=""
    echo
    if test "$answer" != KEEP-MTU; then
        warn '未收到KEEP-MTU，恢复操作前MTU与全部持久状态。'
        _e214_mtu_restore_guarded "$tx" "$unit" "$guard" || return 1
        finished=1
        trap - EXIT HUP INT TERM
        return 1
    fi
    # Hold the rollback lock while committing.  If this shell is killed, the
    # independent timer acquires the released lock and restores the snapshot.
    exec 208>"$tx/mtu-rollback.lock"; flock 208 || return 1
    _e214_install_self || rc=1
    test "$rc" -ne 0 || _e214_mtu_commit "$tx" "$baseline_work" "$selector" "$configured" "$target" "$iface" || rc=1
    test "$rc" -ne 0 || _e214_mtu_apply_runtime "$iface" "$target" || rc=1
    test "$rc" -ne 0 || _e214_mtu_route_health "$iface" "$selector" || rc=1
    test "$rc" -ne 0 || _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE" || rc=1
    if test "$rc" -eq 0; then _e214_mtu_guard_confirm "$guard" || rc=1; fi
    flock -u 208 || true
    if test "$rc" -ne 0; then
        error 'MTU持久化或最终读回失败，恢复操作前完整状态。'
        _e214_mtu_restore_guarded "$tx" "$unit" "$guard" || return 1
        finished=1
        trap - EXIT HUP INT TERM
        return 1
    fi
    _e214_mtu_transient_stop "$unit"
    _e214_tx_close "$tx" || warn "MTU已提交，但事务活动标记未关闭：$tx"
    finished=1
    trap - EXIT HUP INT TERM
    info "宿主机MTU策略已提交：selector=$selector iface=$iface mtu=$target"
    info '开机服务与每5分钟漂移复检已启用；默认出口改变时不会盲目接管新网卡。'
)

_e214_mtu_disable() {
    local force="${1:-}" answer="" tx removed rc=0 restore_rc=0
    if ! _e214_mtu_any_state; then info 'E214宿主机MTU策略未启用。'; return 0; fi
    if test "$force" != force; then
        warn '将恢复脚本首次接管每张网卡前记录的MTU，并移除开机/5分钟复检。'
        read -rp '输入 RESTORE-MTU 确认: ' answer || true
        test "$answer" = RESTORE-MTU || { info '已取消。'; return 0; }
    fi
    if test -e "$E214_MTU_BASELINE" || test -L "$E214_MTU_BASELINE"; then
        _e214_mtu_baseline_validate "$E214_MTU_BASELINE" || {
            error 'MTU基线损坏；拒绝猜测原值。'
            return 1
        }
    fi
    if test -e "$E214_MTU_STATE" || test -L "$E214_MTU_STATE"; then
        _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE" || {
            error 'MTU状态/基线校验失败；拒绝破坏恢复证据。'
            return 1
        }
    fi
    tx=$(_e214_new_tx mtu-disable) || return 1
    _e140_system_snapshot "$tx/system" || { _e214_tx_close "$tx" || true; return 1; }
    systemctl disable --now "$E214_MTU_TIMER_UNIT" "$E214_MTU_UNIT" >/dev/null 2>&1 || true
    test ! -s "$E214_MTU_BASELINE" || _e214_mtu_restore_baseline_except "$E214_MTU_BASELINE" "" || rc=1
    if test "$rc" -eq 0; then
        rm -f -- "$E214_MTU_STATE" "$E214_MTU_BASELINE" "$E214_MTU_SERVICE" "$E214_MTU_TIMER" || rc=1
        systemctl daemon-reload >/dev/null 2>&1 || rc=1
        systemctl is-active --quiet "$E214_MTU_UNIT" 2>/dev/null && rc=1 || true
        systemctl is-active --quiet "$E214_MTU_TIMER_UNIT" 2>/dev/null && rc=1 || true
        systemctl is-enabled --quiet "$E214_MTU_UNIT" 2>/dev/null && rc=1 || true
        systemctl is-enabled --quiet "$E214_MTU_TIMER_UNIT" 2>/dev/null && rc=1 || true
        for removed in "$E214_MTU_STATE" "$E214_MTU_BASELINE" "$E214_MTU_SERVICE" "$E214_MTU_TIMER"; do
            test ! -e "$removed" && test ! -L "$removed" || rc=1
        done
    fi
    if test "$rc" -eq 0; then
        info "E214宿主机MTU策略已退出并恢复基线；快照：$tx/system"
        _e214_tx_close "$tx" || true
        return 0
    fi
    error 'MTU退出未通过，恢复退出前完整状态。'
    _e140_system_restore "$tx/system" || restore_rc=1
    if test "$restore_rc" -ne 0; then
        _e214_mark_critical mtu-disable "$tx/system" 'MTU disable rollback/readback failed' || true
        error "严重：MTU退出回滚不完整；快照：$tx/system"
    fi
    _e214_tx_close "$tx" || true
    return 1
}

_e214_mtu_menu() {
    local opt="" iface="" value="" current=""
    while true; do
        clear; title 'V199e230：宿主机网卡 MTU 手动设置中心'
        echo '  1) 只读查看实际MTU、默认出口与E214稳定所有权'
        echo '  2) 自动识别当前默认出口并手动输入MTU（推荐）'
        echo '  3) 指定宿主机网卡并手动输入MTU'
        echo '  4) 立即执行一次开机/漂移复检'
        echo '  5) 退出E214 MTU策略并恢复首次接管前数值'
        echo '  6) 查看MTU、tcp_mtu_probing与WARP虚拟MTU边界'
        echo -e "  ${cyan}7) 默认出口快捷设置 MTU=1350（同样执行断线回滚与二次确认）${none}"
        echo '  0) 返回'; hr
        read -rp '操作: ' opt || true
        case "$opt" in
            1) _e214_mtu_status; _e116_pause ;;
            2)
                iface=$(_e214_mtu_default_iface 2>/dev/null || true)
                if test -z "$iface"; then error '未识别到稳定默认出口。'; _e116_pause; continue; fi
                current=$(_e214_mtu_current "$iface" 2>/dev/null || true)
                read -rp "目标MTU [1280-9000，当前$current]: " value || true
                value=${value:-$current}
                _e214_mtu_set_interactive auto - "$value" || true
                _e116_pause ;;
            3)
                _e214_mtu_status
                read -rp '宿主机网卡名: ' iface || true
                if ! _e214_mtu_iface_candidate "$iface"; then error '网卡不存在或属于虚拟/隧道排除列表。'; _e116_pause; continue; fi
                current=$(_e214_mtu_current "$iface" 2>/dev/null || true)
                read -rp "目标MTU [1280-9000，当前$current]: " value || true
                value=${value:-$current}
                _e214_mtu_set_interactive iface "$iface" "$value" || true
                _e116_pause ;;
            4) _e214_mtu_reconcile || error 'MTU复检失败；查看状态与日志。'; _e214_mtu_status; _e116_pause ;;
            5) _e214_mtu_disable || true; _e116_pause ;;
            6)
                title 'MTU边界说明'
                echo '  - E212/28项/完整127请求/小BBR都不设置物理网卡MTU。'
                echo '  - tcp_mtu_probing=1只在TCP路径MTU黑洞时探测，不改ip link MTU。'
                echo '  - WARP/WireGuard的MTU=1280属于虚拟隧道，不等于ens3/eth0 MTU。'
                echo '  - E214允许1280-9000；过大需整条链路支持，错误值会丢包或卡顿。'
                echo '  - 自动出口变化时E214停止盲目写入，必须回到本菜单重新确认。'
                _e116_pause ;;
            7)
                iface=$(_e214_mtu_default_iface 2>/dev/null || true)
                if test -z "$iface"; then error '未识别到稳定默认出口。'; _e116_pause; continue; fi
                current=$(_e214_mtu_current "$iface" 2>/dev/null || true)
                warn "快捷档只把宿主机默认出口 $iface 从 ${current:-unknown} 改为1350；不改WARP/tun/wg虚拟MTU。"
                warn 'MTU=1350是高防清洗/动态路由隐藏隧道的保守兼容档，可减少分片与PMTU黑洞；它不是DDoS或暴力攻击防护。'
                _e214_mtu_set_interactive auto - 1350 || true
                _e116_pause ;;
            0) return 0 ;;
            *) warn '无效操作。'; sleep 1 ;;
        esac
    done
}


if declare -F check_and_clean_space >/dev/null 2>&1; then
    eval "$(declare -f check_and_clean_space | sed '1s/check_and_clean_space/_e214_clean_space_base/')"
fi
check_and_clean_space() {
    _e214_clean_space_base "$@" || return 1
    _e214_prune_transactions \
        || warn 'E206/E208/E210/E212/E214部分旧事务因活动状态、保护标志或文件系统错误未能收敛。'
}

_e214_snapshot_matches() {
    local target="$1" snap="$2" smode tmode suid tuid sgid tgid
    if test -L "$snap.present"; then
        test -L "$target" \
          && test "$(readlink -- "$target")" = "$(readlink -- "$snap.present")"
    elif test -f "$snap.present"; then
        test -f "$target" && test ! -L "$target" && cmp -s "$snap.present" "$target" || return 1
        smode=$(stat -c '%a' "$snap.present" 2>/dev/null || true)
        tmode=$(stat -c '%a' "$target" 2>/dev/null || true)
        suid=$(stat -c '%u' "$snap.present" 2>/dev/null || true)
        tuid=$(stat -c '%u' "$target" 2>/dev/null || true)
        sgid=$(stat -c '%g' "$snap.present" 2>/dev/null || true)
        tgid=$(stat -c '%g' "$target" 2>/dev/null || true)
        test "$smode:$suid:$sgid" = "$tmode:$tuid:$tgid"
    elif test -e "$snap.absent"; then
        test ! -e "$target" && test ! -L "$target"
    else
        return 1
    fi
}

_e214_install_self() {
    local tx target snap tmp parent name failed=0 restore_failed=0
    local -a targets=("$SYMLINK" "$E230_SELF_PATH" "$E230_LEGACY_E228_SELF_PATH" \
        "$E230_LEGACY_E226_SELF_PATH" \
        "$E230_LEGACY_E224_SELF_PATH" \
        "$E230_LEGACY_E222_SELF_PATH" \
        "$E220_SELF_PATH" "$E218_SELF_PATH" "$E216_SELF_PATH" "$E214_SELF_PATH" "$E214_LEGACY_E212_SELF_PATH" \
        "$E214_LEGACY_E210_SELF_PATH" \
        "$E214_LEGACY_E208_SELF_PATH" \
        "$E214_LEGACY_E206_SELF_PATH" "$E214_LATEST_PATH" \
        "$E204_SELF_PATH" "$E202_SELF_PATH")
    test -r "$SCRIPT_PATH" || return 1
    for target in "${targets[@]}"; do
        if test -e "$target" || test -L "$target"; then
            test -f "$target" || test -L "$target" || {
                error "E214脚本入口不是普通文件或符号链接，拒绝覆盖：$target"
                return 1
            }
        fi
    done
    _e214_prepare || return 1
    tx=$(_e214_new_tx self-install) || return 1
    for target in "${targets[@]}"; do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
        _e135_snapshot_file "$target" "$snap" || { _e214_tx_close "$tx" || true; return 1; }
    done
    for target in "${targets[@]}"; do
        _e214_ensure_parent_dir "$target" || { failed=1; break; }
        parent=$(dirname -- "$target") || { failed=1; break; }
        name=${target##*/}
        tmp=$(mktemp --tmpdir="$parent" ".${name}.e214-new.XXXXXX") \
            || { failed=1; break; }
        install -o 0 -g 0 -m 0755 "$SCRIPT_PATH" "$tmp" \
            || { rm -f -- "$tmp"; failed=1; break; }
        bash -n "$tmp" || { rm -f -- "$tmp"; failed=1; break; }
        mv -f -- "$tmp" "$target" || { rm -f -- "$tmp"; failed=1; break; }
        test -f "$target" && test ! -L "$target" && test -x "$target" \
          && test "$(stat -c '%a:%u:%g' "$target" 2>/dev/null || true)" = 755:0:0 \
          && cmp -s "$SCRIPT_PATH" "$target" || { failed=1; break; }
    done
    if test "$failed" -ne 0; then
        for target in "${targets[@]}"; do
            snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')"
            _e135_restore_file "$target" "$snap" || restore_failed=1
            _e214_snapshot_matches "$target" "$snap" || restore_failed=1
        done
        if test "$restore_failed" -ne 0; then
            _e214_mark_critical self-install "$tx" 'one or more script entry restores failed' || true
            error "严重：E214脚本入口安装失败且旧入口未全部恢复；必须保留快照：$tx"
        else
            error "E214脚本入口原子安装失败，已恢复并读回全部旧入口；快照：$tx"
        fi
        _e214_tx_close "$tx" || true
        return 1
    fi
    hash -r 2>/dev/null || true
    _e214_tx_close "$tx" || warn "E214脚本入口已读回，但事务活动标记未能关闭：$tx"
    return 0
}

_e214_write_version() {
    local tmp
    _e214_prepare || return 1
    tmp=$(_e118_mktemp e214-version) || return 1
    printf '%s\n' "$E214_VERSION" >"$tmp" || return 1
    _e118_atomic_install "$tmp" "$SCRIPT_VERSION_FILE" 0600
}

