        -e 's/E204卸载任一阶段/E220卸载任一阶段/g' \
        -e 's/将恢复小BBR\/完整网络\/IPv6\/WARP/将独立恢复MTU\/MSS\/小BBR\/完整网络\/IPv6\/WARP/g' \
        -e 's/if test -s "$CONFIG" && test -x "$XRAY_BIN"; then/if test -s "$CONFIG"; then test -x "$XRAY_BIN" \&\& "$XRAY_BIN" version >\/dev\/null 2>\&1 || restore_rc=1;/')"
fi
if declare -F do_uninstall >/dev/null 2>&1; then
    # MTU and MSS are independent owners.  Exit both after DELETE-XRAY and the
    # outer snapshot, but before testing whether small-BBR happens to be active.
    # The old /a injection accidentally nested MTU under the small-BBR branch;
    # that could delete the MTU baseline without restoring the interface.
    eval "$(declare -f do_uninstall | sed \
        '/^[[:space:]]*if _e202_small_bbr_active;/i\
    if _e214_mtu_any_state; then _e214_mtu_disable force || rc=1; fi;\
    test "$rc" -ne 0 || ! _e218_mss_any_evidence || _e218_mss_disable || rc=1;')"
fi
if declare -F _e204_optimization_menu_audit >/dev/null 2>&1; then
    eval "$(declare -f _e204_optimization_menu_audit | sed \
        -e 's/V199e204 optimization-menu audit/V199e230 optimization-menu audit/g' \
        -e 's/绑定E204最终处理器/绑定E220最终入口（E204事务底座）/g')"
fi

#--------------------------- E214 release binding -----------------------------
_e214_recovery_markers() {
    printf '%s\t%s\n' E204 "$E204_CRITICAL_MARKER"
    printf '%s\t%s\n' E206 "$E214_LEGACY_E206_CRITICAL_MARKER"
    printf '%s\t%s\n' E208 "$E214_LEGACY_E208_CRITICAL_MARKER"
    printf '%s\t%s\n' E210 "$E214_LEGACY_E210_CRITICAL_MARKER"
    printf '%s\t%s\n' E212 "$E214_LEGACY_E212_CRITICAL_MARKER"
    printf '%s\t%s\n' E214 "$E214_CRITICAL_MARKER"
}

_e214_recovery_status() {
    local label marker found=0 count=0
    title 'V199e230：严重恢复标记 / 受保护事务状态（只读）'
    while IFS=$'\t' read -r label marker; do
        test -n "$marker" || continue
        if test -e "$marker" || test -L "$marker"; then
            found=1
            echo "  [$label] $marker"
            if test -f "$marker" && test ! -L "$marker" && test -r "$marker" && test -s "$marker"; then
                sed -n '1,20s/^/      /p' "$marker" 2>/dev/null || true
            else
                warn '该恢复标记为空、不可读、类型异常或为符号链接；按严重状态处理。'
            fi
        fi
    done < <(_e214_recovery_markers)
    for marker in "$E204_TX_ROOT" "$E214_LEGACY_E206_TX_ROOT" \
        "$E214_LEGACY_E208_TX_ROOT" "$E214_LEGACY_E210_TX_ROOT" \
        "$E214_LEGACY_E212_TX_ROOT" "$E214_TX_ROOT" \
        "$(_e220_mss_tx_root 2>/dev/null || true)"; do
        test -d "$marker" || continue
        count=$(find "$marker" -mindepth 2 -maxdepth 2 -name .preserve.env \
            -printf . 2>/dev/null | wc -c | tr -d ' ')
        test "${count:-0}" -eq 0 || echo "  [PRESERVE] $marker：${count}个事务被禁止自动清理"
    done
    if ! _e220_mss_unresolved_report >/dev/null 2>&1; then
        found=1
        echo '  [E220-MSS] 未关闭、失效或受保护的持久事务：'
        _e220_mss_unresolved_report || true
    fi
    if test "$found" -eq 0; then info '未发现E204/E206/E208/E210/E212/E214/E220-MSS严重恢复标记。'; fi
}

_e214_critical_preflight() {
    local label marker
    while IFS=$'\t' read -r label marker; do
        if test ! -e "$marker" && test ! -L "$marker"; then continue; fi
        error "检测到${label}严重恢复标记，拒绝用新热更新覆盖未确认状态：$marker"
        if test -f "$marker" && test ! -L "$marker" && test -r "$marker" && test -s "$marker"; then
            sed -n '1,20s/^/    /p' "$marker" 2>/dev/null || true
        else
            error '恢复标记为空、不可读、类型异常或为符号链接；不能证明系统已恢复。'
        fi
        error '请先依据标记中的backup完成恢复与读回，确认后再移走该标记。'
        return 1
    done < <(_e214_recovery_markers)
}

_e214_hot_update_preflight() {
    local owner="" fn c
    test "$EUID" -eq 0 || { error 'E220热更新必须使用root。'; return 1; }
    test -d /run/systemd/system || { error 'systemd未运行。'; return 1; }
    for c in bash systemctl jq curl ip ss tar install sha256sum cp awk sed grep \
        dirname mkdir mv cmp find sort readlink base64 paste tr chmod chown stat \
        sysctl mktemp flock xargs cat cut date head kill rm rmdir tail touch wc; do
        command -v "$c" >/dev/null 2>&1 || {
            error "E220只读预检缺少命令：$c"
            return 1
        }
    done
    test -r "$SCRIPT_PATH" || { error "当前脚本不可读：$SCRIPT_PATH"; return 1; }
    bash -n "$SCRIPT_PATH" || return 1
    test "$SCRIPT_VERSION" = 199e230 && test "$E214_VERSION" = 199e230 || return 1
    _e214_critical_preflight || return 1
    _e220_mss_preflight_readonly || return 1
    for fn in _e214_install_self _e140_system_snapshot _e140_system_restore \
        _e182_install_mode _e159_network_apply _e159_network_remove \
        _e185_warp_health_check _e214_structure_audit _e220_structure_audit \
        _e218_mss_consistency; do
        declare -F "$fn" >/dev/null 2>&1 || { error "E220热更新缺少最终函数：$fn"; return 1; }
    done
    _e220_structure_audit >/dev/null || {
        error 'E220发布结构/参数不变量门禁失败；热更新尚未开始。'
        return 1
    }
    owner=$(_e204_legacy_small_bbr_owner 2>/dev/null || true)
    if test -n "$owner"; then
        error "检测到旧小BBR所有者：$owner。E220不会猜测旧版快照并代替旧版退出。"
        error '请先由对应旧版脚本执行 --small-bbr-disable并确认恢复，再运行E220热更新。'
        return 1
    fi
    if _e202_small_bbr_active; then
        error '检测到当前E202兼容小BBR仍处于active。E220不会在唯一恢复快照之上覆盖热更新入口。'
        error '请先用当前已安装的旧脚本执行：xrv --small-bbr-disable，确认恢复后再热更新。'
        return 1
    fi
    if _e214_mtu_any_state; then
        _e214_mtu_persistence_validate || {
            error 'E214 MTU状态/基线/持久服务不完整；为避免热更新覆盖恢复证据，拒绝继续。'
            error '请先在菜单27重新应用当前MTU或安全退出MTU策略。'
            return 1
        }
    fi
    if _e218_mss_any_evidence; then
        _e218_mss_consistency || {
            error 'MSS Clamp在热更新前已存在状态/规则/服务漂移；拒绝覆盖恢复证据。'
            error '请先用旧脚本的菜单10→7显式修复或关闭MSS Clamp。'
            return 1
        }
    fi
}

_e214_hot_verify() {
    local target
    for target in "$SYMLINK" "$E230_SELF_PATH" "$E230_LEGACY_E228_SELF_PATH" \
        "$E230_LEGACY_E226_SELF_PATH" \
        "$E230_LEGACY_E224_SELF_PATH" \
        "$E230_LEGACY_E222_SELF_PATH" "$E220_SELF_PATH" "$E218_SELF_PATH" \
        "$E216_SELF_PATH" "$E214_SELF_PATH" "$E214_LEGACY_E212_SELF_PATH" \
        "$E214_LEGACY_E210_SELF_PATH" \
        "$E214_LEGACY_E208_SELF_PATH" \
        "$E214_LEGACY_E206_SELF_PATH" "$E214_LATEST_PATH" \
        "$E204_SELF_PATH" "$E202_SELF_PATH"; do
        test -f "$target" && test ! -L "$target" && test -x "$target" \
          && test "$(stat -c '%a:%u:%g' "$target" 2>/dev/null || true)" = 755:0:0 \
          && bash -n "$target" && cmp -s "$SCRIPT_PATH" "$target" || {
            error "E220入口安装读回失败：$target"; return 1
        }
    done
    test "$(cat "$SCRIPT_VERSION_FILE" 2>/dev/null || true)" = "$E214_VERSION" || {
        error '脚本版本文件没有读回199e230。'; return 1
    }
    if test -s "$CONFIG"; then
        _e118_xray_test_config "$CONFIG" 1 || return 1
        if systemctl is-active --quiet xray.service 2>/dev/null; then
            _e127_verify_xray_runtime "$CONFIG" 12 || return 1
        fi
    fi
    if test "$(_e138_state_get route_enabled 0)" = 1; then
        _e185_warp_health_check || return 1
    fi
    _e182_ipv6_hot_verify || return 1
    if _e202_small_bbr_active; then _e202_small_bbr_status >/dev/null || return 1; fi
    if _e214_mtu_any_state; then
        _e214_mtu_persistence_validate || return 1
    fi
    _e218_mss_consistency || return 1
}

_e214_hot_restore_readback() {
    local backup="${1:-}" rc=0
    test -n "$backup" || return 1
    _e140_system_restore "$backup" || rc=1
    if test "$rc" -eq 0 && test -s "$CONFIG"; then
        test -x "$XRAY_BIN" && "$XRAY_BIN" version >/dev/null 2>&1 || rc=1
        if test "$rc" -eq 0; then
            _e118_xray_test_config "$CONFIG" 1 || rc=1
        fi
        if test "$rc" -eq 0 && systemctl is-active --quiet xray.service 2>/dev/null; then
            _e127_verify_xray_runtime "$CONFIG" 12 || rc=1
        fi
    fi
    return "$rc"
}

_e214_hot_update() (
    local tx="" rc=0 restore_rc=0 hot_log="$E214_HOT_LOG"
    local lock_path=/run/lock/xray-e214-hot-update.lock snapshot_ready=0 finished=0
    _e214_hot_exit_guard() {
        local status="${1:-1}" emergency_rc=0
        trap - EXIT HUP INT TERM
        if test "$snapshot_ready" -eq 1 && test "$finished" -eq 0 \
          && test -n "$tx" && test -d "$tx/system"; then
            error 'E220热更新被信号或意外退出中断，执行外层快照紧急恢复。'
            _e214_hot_restore_readback "$tx/system" || emergency_rc=1
            if test "$emergency_rc" -ne 0; then
                _e214_mark_critical hot-update-interrupted "$tx/system" \
                    'signal/unexpected-exit rollback or readback failed' || true
                error "严重：E214中断回滚未完整通过；必须保留快照：$tx/system"
            else
                info "E214中断事务已恢复到热更新前状态；快照：$tx/system"
            fi
            _e214_tx_close "$tx" || true
        elif test -n "$tx"; then
            # Before snapshot_ready no managed system mutation has begun; only
            # close the activity marker so an interrupted snapshot can age out.
            _e214_tx_close "$tx" || true
        fi
        [[ "$status" =~ ^[0-9]+$ ]] || status=1
        test "$status" -ne 0 || status=1
        exit "$status"
    }
    trap '_e214_hot_exit_guard $?' EXIT
    trap 'exit 129' HUP
    trap 'exit 130' INT
    trap 'exit 143' TERM
    _e214_prepare_tx || return 1
    if test "${E214_INTERNAL_SELF_TEST:-0}" = 1; then
        if test -n "${E214_INTERNAL_SELF_TEST_TMP:-}"; then
            install -d -m 0700 "$E214_INTERNAL_SELF_TEST_TMP" || return 1
            hot_log="$E214_INTERNAL_SELF_TEST_TMP/hot.log"
        else
            hot_log=$(mktemp /tmp/xray-e214-hot-selftest.XXXXXX.log) || return 1
        fi
        lock_path="${hot_log}.lock"
    fi
    exec 206>"$lock_path"
    flock -n 206 || { error '已有E220热更新事务正在运行。'; return 1; }
    tx=$(_e214_new_tx hot-update-outer) || return 1
    : >"$hot_log" || { _e214_tx_close "$tx" || true; return 1; }
    _e159_phase_log "$hot_log" outer-snapshot begin
    _e140_system_snapshot "$tx/system" || { _e214_tx_close "$tx" || true; return 1; }
    snapshot_ready=1
    _e159_phase_log "$hot_log" outer-snapshot ok
    _e159_phase_log "$hot_log" legacy-preflight begin
    if _e202_hot_update_preflight; then
        _e159_phase_log "$hot_log" legacy-preflight ok
    else
        rc=1
        _e159_phase_log "$hot_log" legacy-preflight fail
        error 'E214旧层预检未通过；其准备动作将由外层快照恢复。'
    fi
    test "$rc" -ne 0 || _e204_hot_update_base || rc=$?
    test "$rc" -ne 0 || _e214_hot_verify || rc=1
    if test "$rc" -eq 0; then
        _e159_phase_log "$hot_log" final-readback ok
        info 'V199e230热更新完成：核心、节点、网络、SSH、WARP、IPv6、小BBR八档、MTU、MSS与脚本入口均已读回。'
        info "外层回滚快照：$tx/system"
        finished=1
        _e214_tx_close "$tx" || warn "E220热更新已读回，但事务活动标记未能关闭：$tx"
        trap - EXIT HUP INT TERM
        return 0
    fi
    _e159_phase_log "$hot_log" final-readback fail
    error 'E220热更新未完整通过，开始恢复热更新前完整系统状态。'
    _e214_hot_restore_readback "$tx/system" || restore_rc=1
    if test "$restore_rc" -ne 0; then
        _e214_mark_critical hot-update "$tx/system" 'outer rollback/readback failed' || true
        error "严重：E214总回滚未完全通过；必须保留快照：$tx/system"
    else
        info "已恢复热更新前状态；快照：$tx/system"
    fi
    finished=1
    _e214_tx_close "$tx" || true
    trap - EXIT HUP INT TERM
    return 1
)

hot_update_from_legacy() { _e214_hot_update_preflight && _e214_hot_update; }

