            25) _e182_ipv6_menu || true ;; 26) _e202_small_bbr_menu ;;
            27) _e214_mtu_menu || true ;;
            88) do_uninstall ;;
            0) return 0 ;; *) warn '无效操作。'; sleep 1 ;;
        esac
    done
}
