_e214_structure_audit() {
    local rc=0 size lines dispatchers raw_lock_count prune_calls id count
    local menu hot hot_restore installer metadata preflight paths recovery
    local legacy_hot install_alias version_alias uninstaller node_tx prune cleanup
    local mtu_menu mtu_status mtu_apply mtu_snapshot mtu_restore mtu_reconcile
    local d conf all_keys profile_id retired_feature=tcpfit retired_upper=TCPFIT
    local retired_tf retired_iperf
    retired_tf=E214_''TF_
    retired_iperf=E214_''IPERF_
    echo 'V199e214 structure audit:'
    size=$(wc -c <"$SCRIPT_PATH" | tr -d ' ')
    lines=$(wc -l <"$SCRIPT_PATH" | tr -d ' ')
    dispatchers=$(grep -c '^# V199e214 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true)
    menu=$(declare -f _e214_main_menu 2>/dev/null || true)
    hot=$(declare -f _e214_hot_update 2>/dev/null || true)
    hot_restore=$(declare -f _e214_hot_restore_readback 2>/dev/null || true)
    installer=$(declare -f _e214_install_self 2>/dev/null || true)
    metadata=$(declare -f _e214_write_generated_metadata_impl 2>/dev/null || true)
    preflight=$(declare -f _e214_hot_update_preflight 2>/dev/null || true)
    # E220 intentionally wraps the stable E214 path enumerator so that the
    # outer hot-update snapshot cannot erase E220's independent MSS recovery
    # evidence.  Audit the wrapper and its captured base together; inspecting
    # only the one-line wrapper would falsely report every E214 path missing.
    paths="$(declare -f _e138_system_paths 2>/dev/null || true)$(declare -f _e220_system_paths_base 2>/dev/null || true)"
    recovery="$(declare -f _e214_recovery_status 2>/dev/null || true)$(declare -f _e214_critical_preflight 2>/dev/null || true)"
    legacy_hot=$(declare -f _e202_hot_update_base 2>/dev/null || true)
    install_alias=$(declare -f _e202_install_self 2>/dev/null || true)
    version_alias=$(declare -f _e202_write_version 2>/dev/null || true)
    uninstaller=$(declare -f do_uninstall 2>/dev/null || true)
    node_tx="$(declare -f _e182_install_mode 2>/dev/null || true)$(declare -f _e230_install_mode_base 2>/dev/null || true)"
    prune="$(declare -f _e214_prune_transactions 2>/dev/null || true)$(declare -f _e214_prune_root 2>/dev/null || true)"
    cleanup=$(declare -f check_and_clean_space 2>/dev/null || true)
    mtu_menu=$(declare -f _e214_mtu_menu 2>/dev/null || true)
    mtu_status=$(declare -f _e214_mtu_status 2>/dev/null || true)
    mtu_apply=$(declare -f _e214_mtu_set_interactive 2>/dev/null || true)
    mtu_snapshot=$(declare -f _e140_system_snapshot 2>/dev/null || true)
    mtu_restore=$(declare -f _e140_system_restore 2>/dev/null || true)
    mtu_reconcile=$(declare -f _e214_mtu_reconcile 2>/dev/null || true)

    echo "  file_bytes=$size lines=$lines final_dispatchers=$dispatchers"
    test "$size" -gt 2500000 && test "$lines" -gt 50000 || rc=1
    test "$dispatchers" -eq 1 || rc=1
    test "$SCRIPT_VERSION" = 199e230 && test "$E214_VERSION" = 199e230 || rc=1
    test -f "$SCRIPT_PATH" && test -r "$SCRIPT_PATH" || rc=1
    ! LC_ALL=C grep -q $'\r' "$SCRIPT_PATH" || rc=1
    raw_lock_count=$(grep -c '^[[:space:]]*install -d -m 0755 /run/lock' "$SCRIPT_PATH" || true)
    test "$raw_lock_count" -eq 2 || rc=1
    grep -q '^_e214_ensure_run_lock()' "$SCRIPT_PATH" || rc=1
    grep -q '^E214_INTERNAL_SELF_TEST=0$' "$SCRIPT_PATH" || rc=1

    grep -q '热更新到 V199e230' <<<"$menu" || rc=1
    grep -q '26) 小BBR（八档切换 / 14、25或26项 / 默认模式2）' <<<"$menu" || rc=1
    grep -q '27) 宿主机网卡 MTU' <<<"$menu" || rc=1
    grep -q '_e214_mtu_menu' <<<"$menu" || rc=1
    ! grep -Eq 'TCPFit|tcpfit|_e214_tcpfit' <<<"$menu" || rc=1
    for id in _e204_tc_menu _e138_warp_selective_menu _e138_warp_global_menu \
        _e140_warp_full_menu _e182_ipv6_menu _e202_small_bbr_menu; do
        grep -q "$id" <<<"$menu" || rc=1
    done
    ! grep -Eq -- "--${retired_feature}|^_e[0-9]+_${retired_feature}_|E214_${retired_upper}_REPORT|${retired_tf}|${retired_iperf}" "$SCRIPT_PATH" || rc=1

    for id in _e214_install_self _e214_hot_verify _e214_structure_audit \
        _e182_install_mode _e185_warp_health_check _e202_small_bbr_mode3f2 \
        _e214_mtu_menu _e214_mtu_status _e214_mtu_set_interactive \
        _e214_mtu_reconcile _e214_mtu_disable _e214_mtu_rollback_snapshot; do
        declare -F "$id" >/dev/null 2>&1 || rc=1
    done
    grep -q '_e140_system_snapshot' <<<"$hot" || rc=1
    grep -q '_e214_hot_restore_readback' <<<"$hot" || rc=1
    grep -q '_e140_system_restore' <<<"$hot_restore" || rc=1
    grep -q 'test -x.*XRAY_BIN' <<<"$hot_restore" || rc=1
    grep -q 'XRAY_BIN.*version' <<<"$hot_restore" || rc=1
    grep -q '_e214_hot_exit_guard' <<<"$hot" || rc=1
    grep -q "trap '_e214_hot_exit_guard" <<<"$hot" || rc=1
    grep -q '_e214_prepare_tx' <<<"$hot" || rc=1
    ! grep -q '_e204_prepare' <<<"$(declare -f _e214_prepare_tx 2>/dev/null || true)" || rc=1
    grep -q '_e204_hot_update_base' <<<"$hot" || rc=1
    ! grep -Eq 'test .*_e214_(install_self|write_version)' <<<"$hot" || rc=1
    grep -q '_e202_hot_step self-install _e202_install_self' <<<"$legacy_hot" || rc=1
    grep -q '_e202_hot_step version-write _e202_write_version' <<<"$legacy_hot" || rc=1
    grep -q '_e214_install_self' <<<"$install_alias" || rc=1
    grep -q '_e214_write_version' <<<"$version_alias" || rc=1
    grep -q 'E214_VERSION' <<<"$metadata" || rc=1
    ! grep -q 'E204_VERSION' <<<"$metadata" || rc=1

    grep -q '\.preserve\.env' <<<"$prune" || rc=1
    for id in E214_LEGACY_E206_TX_ROOT E214_LEGACY_E208_TX_ROOT \
        E214_LEGACY_E210_TX_ROOT E214_LEGACY_E212_TX_ROOT; do
        grep -q "$id" <<<"$prune" || rc=1
    done
    grep -q 'test -e.*\.active\.env.*test -L' <<<"$prune" || rc=1
    grep -q 'test -e.*\.preserve\.env.*test -L' <<<"$prune" || rc=1
    grep -q 'marker_bad' <<<"$prune" || rc=1
    grep -q '_e214_prune_transactions' <<<"$cleanup" || rc=1
    prune_calls=$(declare -f _e214_new_tx | grep -c '^[[:space:]]*_e214_prune_transactions' || true)
    test "$prune_calls" -eq 1 || rc=1

    for id in E214_LEGACY_E206_SELF_PATH E214_LEGACY_E208_SELF_PATH \
        E214_LEGACY_E210_SELF_PATH E214_LEGACY_E212_SELF_PATH; do
        grep -q "$id" <<<"$installer" || rc=1
    done
    grep -q '不是普通文件或符号链接' <<<"$installer" || rc=1
    grep -q '_e214_ensure_parent_dir' <<<"$installer" || rc=1
    grep -q 'mktemp --tmpdir=' <<<"$installer" || rc=1
    grep -q 'install -o 0 -g 0 -m 0755' <<<"$installer" || rc=1
    grep -q '755:0:0' <<<"$installer" || rc=1
    ! grep -q 'e214-new\.\$\$' <<<"$installer" || rc=1
    ! grep -q 'install -d -m 0755.*dirname' <<<"$installer" || rc=1
    grep -q '_e214_snapshot_matches' <<<"$installer" || rc=1
    grep -q '_e214_mark_critical' <<<"$installer" || rc=1
    grep -q 'V199e230：受控卸载' <<<"$uninstaller" || rc=1
    grep -q 'test -x.*XRAY_BIN.*version' <<<"$uninstaller" || rc=1
    grep -q '_e214_mtu_disable force' <<<"$uninstaller" || rc=1
    grep -q '节点创建/IPv6/WARP/最终导出' <<<"$node_tx" || rc=1
    grep -q 'test -x.*XRAY_BIN.*version' <<<"$node_tx" || rc=1
    grep -q '_e214_critical_preflight' <<<"$preflight" || rc=1
    grep -q '_e202_small_bbr_active' <<<"$preflight" || rc=1
    ! grep -q '_e202_hot_update_preflight' <<<"$preflight" || rc=1
    grep -q '_e202_hot_update_preflight' <<<"$hot" || rc=1
    for id in E214_LEGACY_E206_DIR E214_LEGACY_E208_DIR E214_LEGACY_E210_DIR \
        E214_LEGACY_E212_DIR E214_MTU_STATE E214_MTU_BASELINE E214_MTU_SERVICE E214_MTU_TIMER; do
        grep -q "$id" <<<"$paths" || rc=1
    done
    grep -q 'E212' <<<"$recovery" || rc=1
    grep -Fq -- '--e208-summary|--e210-summary|--e212-summary|--e214-summary)' "$SCRIPT_PATH" || rc=1
    grep -Fq -- '--recovery-status)' "$SCRIPT_PATH" || rc=1
    grep -Fq -- '--mtu-status)' "$SCRIPT_PATH" || rc=1
    grep -Fq -- '--mtu-rollback-snapshot)' "$SCRIPT_PATH" || rc=1

    # Host MTU is a separate, fail-closed owner.  Both the full-system
    # transaction and remote apply must preserve runtime values and offer an
    # independent rollback even when the SSH process disappears.
    grep -q 'e214-link-mtu.tsv' <<<"$mtu_snapshot" || rc=1
    grep -q 'e214-mtu-services.env' <<<"$mtu_snapshot" || rc=1
    grep -q 'ip link set dev.*mtu' <<<"$mtu_restore" || rc=1
    grep -q '_e214_mtu_schedule_rollback' <<<"$mtu_apply" || rc=1
    grep -q 'read -r -t 90' <<<"$mtu_apply" || rc=1
    grep -q 'KEEP-MTU' <<<"$mtu_apply" || rc=1
    grep -q '_e214_mtu_guard_confirm' <<<"$mtu_apply" || rc=1
    grep -q '_e214_mtu_route_health' <<<"$mtu_apply" || rc=1
    grep -q '_e214_mtu_default_iface' <<<"$mtu_reconcile" || rc=1
    grep -q 'manual-reconfirm' <<<"$mtu_reconcile" || rc=1
    grep -q 'tcp_mtu_probing' <<<"$mtu_status" || rc=1
    grep -q 'WARP' <<<"$mtu_status" || rc=1
    ! grep -Eq 'wg\*.*ip link set|warp\*.*ip link set' <<<"$mtu_apply" || rc=1

    d=$(mktemp -d /tmp/xray-e214-profile-audit.XXXXXX) || return 1
    conf="$d/profile.conf"
    all_keys=$(_e202_small_bbr_all_keys)
    grep -Fqx 'net.ipv4.tcp_max_tw_buckets' <<<"$all_keys" || rc=1
    test "$(grep -Fxc 'net.ipv4.tcp_max_tw_buckets' <<<"$all_keys")" -eq 1 || rc=1
    for id in mode1 mode2 mode3 mode1f mode2f mode3f mode3f2 modeb1; do
        "_e202_small_bbr_${id}" >"$conf" || rc=1
        _e202_small_bbr_validate_file "$conf" || rc=1
        profile_id=$(_e202_small_bbr_profile_id_file "$conf" 2>/dev/null || true)
        test "$profile_id" = "$id" || rc=1
        count=$(_e202_small_bbr_assignment_count "$conf")
        case "$id" in
            mode1|mode2|mode3) test "$count" -eq 14 || rc=1 ;;
            mode3f2) test "$count" -eq 26 || rc=1 ;;
            *) test "$count" -eq 25 || rc=1 ;;
        esac
        grep -Fqx 'net.ipv4.tcp_adv_win_scale = 1' "$conf" || rc=1
        ! grep -q '^net.ipv4.tcp_tw_reuse_delay[[:space:]]*=' "$conf" || rc=1
        case "$id" in
            mode1f|mode2f|mode3f|mode3f2|modeb1)
                grep -Fqx 'net.ipv4.tcp_max_reordering = 300' "$conf" || rc=1
                grep -Fqx 'net.ipv4.tcp_tw_reuse = 2' "$conf" || rc=1
                grep -Fqx 'net.ipv4.tcp_recovery = 1' "$conf" || rc=1 ;;
        esac
        if test "$id" = mode3f2; then
            grep -Fqx 'net.core.rmem_default = 96695' "$conf" || rc=1
            grep -Fqx 'net.core.wmem_default = 26215' "$conf" || rc=1
            grep -Fqx 'net.core.rmem_max = 19977218' "$conf" || rc=1
            grep -Fqx 'net.core.wmem_max = 19977218' "$conf" || rc=1
            grep -Fqx 'net.ipv4.tcp_rmem = 4096 96695 19977218' "$conf" || rc=1
            grep -Fqx 'net.ipv4.tcp_wmem = 4096 26215 19977218' "$conf" || rc=1
            grep -Fqx 'net.ipv4.tcp_fin_timeout = 10' "$conf" || rc=1
            grep -Fqx 'net.ipv4.tcp_max_tw_buckets = 8192' "$conf" || rc=1
        else
            ! grep -q '^net.ipv4.tcp_max_tw_buckets[[:space:]]*=' "$conf" || rc=1
        fi
    done
    rm -rf -- "$d"
    _e204_optimization_menu_audit >/dev/null || rc=1
    if test "$rc" -eq 0; then echo '  result=PASS'; else echo '  result=FAIL'; fi
    return "$rc"
}

_e214_prune_self_test() (
    local d marker i count start
    d=$(mktemp -d /tmp/xray-e214-prune.XXXXXX) || return 1
    marker="$d/critical.env"
    for i in $(seq -w 1 13); do
        mkdir -p "$d/tx$i/system" || return 1
        touch -d "@$((10#$i))" "$d/tx$i" || return 1
    done
    : >"$marker" || return 1
    ! XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "$marker" >/dev/null 2>&1 || return 1
    count=$(find "$d" -mindepth 1 -maxdepth 1 -type d | wc -l | tr -d ' ')
    test "$count" -eq 13 || return 1
    printf 'backup=%s\nbackup=%s\n' "$d/tx01/system" "/tmp/outside-e214-snapshot" >"$marker" || return 1
    ! XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "$marker" >/dev/null 2>&1 || return 1
    count=$(find "$d" -mindepth 1 -maxdepth 1 -type d | wc -l | tr -d ' ')
    test "$count" -eq 13 || return 1
    printf 'backup=%s\n' "$d/tx01/system" >"$marker" || return 1
    XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "$marker" || return 1
    test -d "$d/tx01" || return 1
    count=$(find "$d" -mindepth 1 -maxdepth 1 -type d | wc -l | tr -d ' ')
    test "$count" -eq 13 || return 1
    rm -f -- "$marker"
    XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" || return 1
    count=$(find "$d" -mindepth 1 -maxdepth 1 -type d | wc -l | tr -d ' ')
    test "$count" -eq 12 || return 1
    mkdir -p "$d/tx00" || return 1
    printf 'reason=test\n' >"$d/tx00/.preserve.env" || return 1
    touch -d '@0' "$d/tx00" || return 1
    XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" || return 1
    test -d "$d/tx00" || return 1
    rm -f -- "$d/tx00/.preserve.env"
    touch -d '@0' "$d/tx00" || return 1
    XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" || return 1
    test ! -d "$d/tx00" || return 1

    # Empty/symlink preserve markers and malformed active markers are recovery
    # evidence, not permission to delete.  The cleaner must return non-zero and
    # leave the transaction intact so an operator can inspect it.
    mkdir -p "$d/tx00" || return 1
    : >"$d/tx00/.preserve.env" || return 1
    touch -d '@0' "$d/tx00" || return 1
    ! XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" >/dev/null 2>&1 || return 1
    test -d "$d/tx00" || return 1
    rm -f -- "$d/tx00/.preserve.env"
    ln -s /dev/null "$d/tx00/.preserve.env" || return 1
    touch -d '@0' "$d/tx00" || return 1
    ! XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" >/dev/null 2>&1 || return 1
    test -d "$d/tx00" || return 1
    rm -f -- "$d/tx00/.preserve.env"
    printf 'pid=bad\nstart=bad\n' >"$d/tx00/.active.env" || return 1
    touch -d '@0' "$d/tx00" || return 1
    ! XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" >/dev/null 2>&1 || return 1
    test -d "$d/tx00" || return 1

    # A well-formed marker for a dead PID is stale and may be collected; a
    # marker matching this live shell must remain protected.
    printf 'pid=2147483647\nstart=1\n' >"$d/tx00/.active.env" || return 1
    XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" || return 1
    test ! -d "$d/tx00" || return 1
    mkdir -p "$d/tx00" || return 1
    start=$(_e214_proc_start_time 1 || true)
    [[ "$start" =~ ^[0-9]+$ ]] && kill -0 1 2>/dev/null || return 1
    printf 'pid=1\nstart=%s\n' "$start" >"$d/tx00/.active.env" || return 1
    touch -d '@0' "$d/tx00" || return 1
    XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" || return 1
    test -d "$d/tx00" || return 1
    rm -rf -- "$d"
)

_e214_directory_mode_self_test() (
    local d parent target before after
    d=$(mktemp -d /tmp/xray-e214-dir-mode.XXXXXX) || return 1
    trap 'rm -rf -- "${d:-}"' EXIT
    chmod 1777 "$d" || return 1
    before=$(stat -c '%a' "$d" 2>/dev/null || true)
    _e214_ensure_directory "$d" 0755 || return 1
    after=$(stat -c '%a' "$d" 2>/dev/null || true)
    test "$before:$after" = 1777:1777 || return 1

    parent="$d/existing-parent"; target="$parent/entry"
    mkdir "$parent" || return 1
    chmod 0711 "$parent" || return 1
    _e214_ensure_parent_dir "$target" || return 1
    test "$(stat -c '%a' "$parent" 2>/dev/null || true)" = 711 || return 1

    _e214_ensure_parent_dir "$d/new-parent/entry" || return 1
    test "$(stat -c '%a' "$d/new-parent" 2>/dev/null || true)" = 755 || return 1

    : >"$d/not-a-directory" || return 1
    ! _e214_ensure_directory "$d/not-a-directory" 0755 >/dev/null 2>&1 || return 1
    rm -rf -- "$d"
    trap - EXIT
)

_e214_snapshot_match_self_test() (
    local d target snap
    d=$(mktemp -d /tmp/xray-e214-snapshot.XXXXXX) || return 1
    target="$d/entry"; snap="$d/snap/entry"
    printf 'old\n' >"$target" || return 1
    chmod 0755 "$target" || return 1
    _e135_snapshot_file "$target" "$snap" || return 1
    printf 'new\n' >"$target" || return 1
    _e135_restore_file "$target" "$snap" || return 1
    _e214_snapshot_matches "$target" "$snap" || return 1
    rm -rf -- "$d"
)

_e214_mtu_self_test() (
    local d baseline state service timer actual rc=0
    d=$(mktemp -d /tmp/xray-e214-mtu-selftest.XXXXXX) || return 1
    trap 'rm -rf -- "${d:-}"' EXIT
    mkdir -p "$d/sys/ens3" "$d/sys/ens4" "$d/sys/wgcf" || return 1
    printf '1500\n' >"$d/sys/ens3/mtu"; printf 'up\n' >"$d/sys/ens3/operstate"
    printf '1450\n' >"$d/sys/ens4/mtu"; printf 'down\n' >"$d/sys/ens4/operstate"
    printf '1280\n' >"$d/sys/wgcf/mtu"; printf 'unknown\n' >"$d/sys/wgcf/operstate"
    E214_MTU_SYSFS_ROOT="$d/sys"
    SSH_CONNECTION=""
    ip() {
        if test "${1:-}" = link && test "${2:-}" = set && test "${3:-}" = dev \
          && test "${5:-}" = mtu; then
            test -f "$E214_MTU_SYSFS_ROOT/${4:-}/mtu" || return 1
            printf '%s\n' "${6:-}" >"$E214_MTU_SYSFS_ROOT/${4:-}/mtu"
            return 0
        fi
        if test "${1:-}" = -4 && test "${2:-}" = route && test "${3:-}" = get; then
            echo '1.1.1.1 via 192.0.2.1 dev ens3 src 192.0.2.2'
            return 0
        fi
        if test "${1:-}" = -4 && test "${2:-}" = route && test "${3:-}" = show; then
            echo 'default via 192.0.2.1 dev ens3'
            return 0
        fi
        return 1
    }
    _e214_mtu_iface_candidate ens3 || rc=1
    ! _e214_mtu_iface_candidate wgcf || rc=1
    test "$(_e214_mtu_default_iface)" = ens3 || rc=1
    _e214_mtu_value_valid 1280 && _e214_mtu_value_valid 1350 \
      && _e214_mtu_value_valid 9000 || rc=1
    ! _e214_mtu_value_valid 1279 && ! _e214_mtu_value_valid 9001 || rc=1
    baseline="$d/baseline.tsv"; state="$d/state.env"
    printf 'ens3|1500\n' >"$baseline"; chmod 0600 "$baseline"
    _e214_mtu_baseline_validate "$baseline" || rc=1
    _e214_mtu_baseline_add "$baseline" ens4 || rc=1
    test "$(wc -l <"$baseline" | tr -d ' ')" -eq 2 || rc=1
    _e214_mtu_write_state_candidate "$state" "$baseline" auto - 1420 ens3 || rc=1
    _e214_mtu_state_validate "$state" "$baseline" || rc=1
    ! _e214_mtu_write_state_candidate "$d/bad-state" "$baseline" iface ens4 1420 ens3 >/dev/null 2>&1 || rc=1
    printf 'tamper\n' >>"$baseline"
    ! _e214_mtu_state_validate "$state" "$baseline" || rc=1
    sed -i '$d' "$baseline"
    _e214_mtu_write_state_candidate "$state" "$baseline" auto - 1420 ens3 || rc=1
    _e214_mtu_apply_runtime ens3 1420 || rc=1
    actual=$(_e214_mtu_current ens3 2>/dev/null || true)
    test "$actual" = 1420 || rc=1
    _e214_mtu_route_health ens3 auto || rc=1
    _e214_mtu_restore_baseline_except "$baseline" "" || rc=1
    test "$(_e214_mtu_current ens3)" = 1500 || rc=1
    test "$(_e214_mtu_current ens4)" = 1450 || rc=1
    service="$d/service"; timer="$d/timer"
    _e214_mtu_write_unit_candidates "$service" "$timer" || rc=1
    grep -Fqx 'Type=oneshot' "$service" || rc=1
    grep -Fqx 'WantedBy=multi-user.target' "$service" || rc=1
    ! grep -q 'RemainAfterExit' "$service" || rc=1
    grep -Fqx 'OnActiveSec=5min' "$timer" || rc=1
    rm -rf -- "$d"; trap - EXIT
    return "$rc"
)

_e214_mtu_snapshot_self_test() (
    local d rc=0
    d=$(mktemp -d /tmp/xray-e214-mtu-snapshot.XXXXXX) || return 1
    trap 'rm -rf -- "${d:-}"' EXIT
    mkdir -p "$d/sys/ens3" || return 1
    printf '1500\n' >"$d/sys/ens3/mtu"; printf 'up\n' >"$d/sys/ens3/operstate"
    E214_MTU_SYSFS_ROOT="$d/sys"
    _e214_system_snapshot_base() { install -d -m 0700 "$1"; }
    _e214_system_restore_base() { :; }
    _e204_service_snapshot() { printf '%s|not-found|disabled|inactive\n' "$1"; }
    _e204_services_restore_file() { test -s "$1"; }
    ip() {
        test "${1:-} ${2:-} ${3:-} ${5:-}" = 'link set dev mtu' || return 1
        test -f "$E214_MTU_SYSFS_ROOT/${4:-}/mtu" || return 1
        printf '%s\n' "${6:-}" >"$E214_MTU_SYSFS_ROOT/${4:-}/mtu"
    }
    _e140_system_snapshot "$d/snapshot" || rc=1
    printf '1300\n' >"$d/sys/ens3/mtu"
    _e140_system_restore "$d/snapshot" || rc=1
    test "$(_e214_mtu_current ens3)" = 1500 || rc=1
    printf 'ens3|1400\n' >"$d/snapshot/e214-link-mtu.tsv"
    ! _e140_system_restore "$d/snapshot" >/dev/null 2>&1 || rc=1
    rm -rf -- "$d"; trap - EXIT
    return "$rc"
)

_e214_hot_rollback_self_test() (
    local d result=0 restore_fail=0 legacy_fail=0 unexpected=0 status=0 base_fail=1
    d=$(mktemp -d /tmp/xray-e214-hot-rollback.XXXXXX) || return 1
    : >"$d/order"
    _e214_prepare_tx() { :; }
    _e214_new_tx() { install -d -m 0700 "$d/tx/system"; printf '%s\n' "$d/tx"; }
    _e214_tx_close() { :; }
    _e159_phase_log() { :; }
    _e140_system_snapshot() { echo snapshot >>"$d/order"; }
    _e202_hot_update_preflight() {
        echo legacy-preflight >>"$d/order"
        test "$unexpected" -eq 0 || exit 77
        test "$legacy_fail" -eq 0
    }
    _e204_hot_update_base() {
        if test "$base_fail" -eq 1; then echo mutate-fail >>"$d/order"; return 1; fi
        echo mutate-ok >>"$d/order"
    }
    _e214_hot_verify() { echo verify >>"$d/order"; }
    _e214_install_self() { echo duplicate-install >>"$d/order"; return 1; }
    _e214_write_version() { echo duplicate-version >>"$d/order"; return 1; }
    _e140_system_restore() { echo restore >>"$d/order"; test "$restore_fail" -eq 0; }
    _e214_mark_critical() { echo critical >>"$d/order"; return 0; }
    ! E214_INTERNAL_SELF_TEST=1 E214_INTERNAL_SELF_TEST_TMP="$d" _e214_hot_update >/dev/null 2>&1 || result=1
    test "$(tr '\n' ' ' <"$d/order")" = 'snapshot legacy-preflight mutate-fail restore ' || result=1
    : >"$d/order"; restore_fail=1
    ! E214_INTERNAL_SELF_TEST=1 E214_INTERNAL_SELF_TEST_TMP="$d" _e214_hot_update >/dev/null 2>&1 || result=1
    test "$(tr '\n' ' ' <"$d/order")" = 'snapshot legacy-preflight mutate-fail restore critical ' || result=1
    : >"$d/order"; restore_fail=0; legacy_fail=1
    ! E214_INTERNAL_SELF_TEST=1 E214_INTERNAL_SELF_TEST_TMP="$d" _e214_hot_update >/dev/null 2>&1 || result=1
    test "$(tr '\n' ' ' <"$d/order")" = 'snapshot legacy-preflight restore ' || result=1
    : >"$d/order"; legacy_fail=0; unexpected=1
    if E214_INTERNAL_SELF_TEST=1 E214_INTERNAL_SELF_TEST_TMP="$d" \
      _e214_hot_update >/dev/null 2>&1; then status=0; else status=$?; fi
    test "$status" -eq 77 || result=1
    test "$(tr '\n' ' ' <"$d/order")" = 'snapshot legacy-preflight restore ' || result=1
    : >"$d/order"; restore_fail=1
    if E214_INTERNAL_SELF_TEST=1 E214_INTERNAL_SELF_TEST_TMP="$d" \
      _e214_hot_update >/dev/null 2>&1; then status=0; else status=$?; fi
    test "$status" -eq 77 || result=1
    test "$(tr '\n' ' ' <"$d/order")" = 'snapshot legacy-preflight restore critical ' || result=1
    : >"$d/order"; restore_fail=0; unexpected=0; base_fail=0
    E214_INTERNAL_SELF_TEST=1 E214_INTERNAL_SELF_TEST_TMP="$d" \
      _e214_hot_update >/dev/null 2>&1 || result=1
    test "$(tr '\n' ' ' <"$d/order")" = 'snapshot legacy-preflight mutate-ok verify ' || result=1
    rm -rf -- "$d"
    return "$result"
)

_e214_self_test() {
    local rc=0 d spec total unique
    echo 'V199e214 offline release gate:'
    bash -n "$SCRIPT_PATH" && echo '  [PASS] bash syntax' || { echo '  [FAIL] bash syntax'; rc=1; }
    _e214_prune_self_test && echo '  [PASS] E206/E208/E210/E212/E214 fail-closed transaction retention' || { echo '  [FAIL] E214 transaction pruning'; rc=1; }
    _e214_directory_mode_self_test && echo '  [PASS] shared/existing directory modes remain unchanged' || { echo '  [FAIL] directory-mode preservation'; rc=1; }
    _e214_snapshot_match_self_test && echo '  [PASS] script-entry snapshot restore readback' || { echo '  [FAIL] E214 script-entry snapshot readback'; rc=1; }
    _e214_mtu_self_test && echo '  [PASS] host-MTU selector/state/baseline/runtime/unit invariants' || { echo '  [FAIL] host-MTU invariant'; rc=1; }
    _e214_mtu_snapshot_self_test && echo '  [PASS] host-MTU full-system snapshot/restore checksum boundary' || { echo '  [FAIL] host-MTU snapshot boundary'; rc=1; }
    _e202_small_bbr_self_test >/dev/null && echo '  [PASS] eight exact 14/25/26-item small-BBR profiles' || { echo '  [FAIL] small-BBR invariant'; rc=1; }
    _e202_inherited_core_self_test >/dev/null && echo '  [PASS] inherited Xray/WARP/QR behavior' || { echo '  [FAIL] inherited core behavior'; rc=1; }
    E204_INTERNAL_SELF_TEST=1 _e188_summary_transaction_self_test >/dev/null && echo '  [PASS] one-summary/one-QR transaction' || { echo '  [FAIL] one-summary/one-QR transaction'; rc=1; }
    _e204_advanced_tx_self_test && echo '  [PASS] menu-10 outer transaction rollback' || { echo '  [FAIL] menu-10 transaction'; rc=1; }
    _e204_tc_menu_readonly_self_test && echo '  [PASS] TC menu enter/exit is read-only' || { echo '  [FAIL] TC menu entry'; rc=1; }
    _e214_hot_rollback_self_test && echo '  [PASS] E214 hot-update rollback + single-commit path' || { echo '  [FAIL] E214 hot rollback/commit'; rc=1; }
    d=$(mktemp -d /tmp/xray-e214-full-spec.XXXXXX) || return 1; spec="$d/spec.conf"
    _e159_full_spec fq 1 31 "$spec" || rc=1
    total=$(awk -F= '/^[[:space:]]*[A-Za-z0-9_.]+[[:space:]]*=/{n++}END{print n+0}' "$spec")
    unique=$(awk -F= '/^[[:space:]]*[A-Za-z0-9_.]+[[:space:]]*=/{k=$1;gsub(/[[:space:]]/,"",k);a[k]=1}END{for(k in a)n++;print n+0}' "$spec")
    test "$total" -eq 125 && test "$unique" -eq 125 \
      && grep -Fq 'Requested entries: 127 = 125 persistent controls + 1 write trigger + 1 semantic alias' "$spec" \
      && grep -Eq '^net\.ipv4\.route\.flush[[:space:]]*=[[:space:]]*1$' "$spec" \
      && echo '  [PASS] full-network spec 127 logical / 125 unique assignments' \
      || { echo "  [FAIL] full-network spec assignments=$total unique=$unique"; rc=1; }
    rm -rf -- "$d"
    _e214_structure_audit >/dev/null && echo '  [PASS] E214 final bindings/ownership gates' || { echo '  [FAIL] E214 structure binding'; rc=1; }
    if test "$rc" -eq 0; then echo 'V199e214 result: PASS'; else echo 'V199e214 result: FAIL'; fi
    return "$rc"
}

#==============================================================================
# V199e216 FINAL MTU-1350 / MSS CLAMP CORRECTION LAYER
#
# E214 remains the stable owner of host-link MTU state so an in-place upgrade
# preserves an already confirmed MTU and its original baseline.  E216 adds a
# 1350 shortcut and repairs the independent IPv4 MSS Clamp transaction.
#==============================================================================
readonly E216_VERSION="199e216"
readonly E216_DIR="$CONFIG_DIR/e216"
readonly E216_SELF_PATH="$SCRIPT_DIR/ex199e216.sh"
readonly E216_MSS_BACKEND_STATE="$E216_DIR/mss-backend.env"
readonly E216_MSS_SCRIPT="/usr/local/bin/xray-mss-clamp-e88.sh"
readonly E216_MSS_SERVICE="/etc/systemd/system/xray-mss-clamp-e88.service"
readonly E216_MSS_TIMER="/etc/systemd/system/xray-mss-clamp-e137.timer"
readonly E216_MSS_SERVICE_UNIT="xray-mss-clamp-e88.service"
readonly E216_MSS_TIMER_UNIT="xray-mss-clamp-e137.timer"
readonly E216_MSS_CHAIN="XRAY_MSS_CLAMP"

_e216_prepare() {
    _e214_prepare || return 1
    test ! -L "$E216_DIR" || { error "拒绝使用符号链接目录：$E216_DIR"; return 1; }
    _e214_ensure_directory "$E216_DIR" 0700 || return 1
}

_e216_mss_backend_valid() {
    case "${1:-}" in iptables|iptables-nft|iptables-legacy) return 0 ;; esac
    return 1
}

_e216_mss_tool_path() {
    local name="${1:-}" path
    _e216_mss_backend_valid "$name" || return 1
    path=$(command -v "$name" 2>/dev/null || true)
    case "$path" in /*) test -x "$path" || return 1 ;; *) return 1 ;; esac
    test "${path##*/}" = "$name" || return 1
    printf '%s\n' "$path"
}

_e216_mss_save_restore_paths() {
    local backend="${1:-}" save restore
    _e216_mss_backend_valid "$backend" || return 1
    case "$backend" in
        iptables) save=iptables-save; restore=iptables-restore ;;
        iptables-nft) save=iptables-nft-save; restore=iptables-nft-restore ;;
        iptables-legacy) save=iptables-legacy-save; restore=iptables-legacy-restore ;;
    esac
    save=$(command -v "$save" 2>/dev/null || true)
    restore=$(command -v "$restore" 2>/dev/null || true)
    case "$save:$restore" in /*:/*) test -x "$save" && test -x "$restore" || return 1 ;; *) return 1 ;; esac
    printf '%s|%s\n' "$save" "$restore"
}

_e216_mss_state_value() {
    local file="${1:-}" key="${2:-}"
    awk -F= -v wanted="$key" '$1==wanted{n++;v=substr($0,index($0,"=")+1)}END{if(n==1)print v;else exit 1}' "$file" 2>/dev/null
}

_e216_mss_backend_state_validate() {
    local file="${1:-$E216_MSS_BACKEND_STATE}" line key value count=0 version backend family mode epoch
    local -A seen=()
    test -f "$file" && test ! -L "$file" && test -s "$file" || return 1
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([a-z_]+)=([A-Za-z0-9_.:-]+)$ ]] || return 1
        key=${BASH_REMATCH[1]}; value=${BASH_REMATCH[2]}
        case "$key" in version|backend|family|mode|updated_epoch) ;; *) return 1 ;; esac
        test -z "${seen[$key]+x}" || return 1
        seen[$key]=1; count=$((count + 1))
    done <"$file"
    test "$count" -eq 5 || return 1
    for key in version backend family mode updated_epoch; do test -n "${seen[$key]+x}" || return 1; done
    version=$(_e216_mss_state_value "$file" version) || return 1
    backend=$(_e216_mss_state_value "$file" backend) || return 1
    family=$(_e216_mss_state_value "$file" family) || return 1
    mode=$(_e216_mss_state_value "$file" mode) || return 1
    epoch=$(_e216_mss_state_value "$file" updated_epoch) || return 1
    test "$version" = 199e216 && _e216_mss_backend_valid "$backend" \
      && test "$family" = ipv4 && test "$mode" = clamp-to-pmtu \
      && [[ "$epoch" =~ ^[0-9]{1,20}$ ]]
}

_e216_mss_write_backend_state() {
    local backend="${1:-}" tmp
    _e216_mss_backend_valid "$backend" || return 1
    _e216_prepare || return 1
    tmp=$(_e118_mktemp e216-mss-backend) || return 1
    {
        printf 'version=199e216\n'
        printf 'backend=%s\n' "$backend"
        printf 'family=ipv4\n'
        printf 'mode=clamp-to-pmtu\n'
        printf 'updated_epoch=%s\n' "$(date +%s)"
    } >"$tmp" || return 1
    chmod 0600 "$tmp" || return 1
    _e216_mss_backend_state_validate "$tmp" || return 1
    _e118_atomic_install "$tmp" "$E216_MSS_BACKEND_STATE" 0600
}

_e216_mss_write_legacy_state() {
    local value="${1:-}" tmp
    case "$value" in ON|OFF) ;; *) return 1 ;; esac
    _e216_prepare || return 1
    tmp=$(_e118_mktemp e216-mss-state) || return 1
    printf '%s\n' "$value" >"$tmp" || return 1
    chmod 0600 "$tmp" || return 1
    _e118_atomic_install "$tmp" "$E88_MSS_STATE_FILE" 0600
}

_e216_mss_backend_readable() {
    local tool
    tool=$(_e216_mss_tool_path "${1:-}") || return 1
    "$tool" -w 5 -t mangle -S >/dev/null 2>&1
}

_e216_mss_candidate_order() {
    local tool version=""
    tool=$(command -v iptables 2>/dev/null || true)
    if test -n "$tool"; then version=$("$tool" -V 2>/dev/null || true); fi
    {
        case "$version" in
            *nf_tables*) echo iptables-nft ;;
            *legacy*) echo iptables-legacy ;;
        esac
        echo iptables
        echo iptables-nft
        echo iptables-legacy
    } | awk 'NF&&!seen[$0]++'
}

_e216_mss_discover_backend() {
    local candidate tool
    while IFS= read -r candidate; do
        tool=$(_e216_mss_tool_path "$candidate" 2>/dev/null || true)
        test -n "$tool" || continue
        if "$tool" -w 5 -t mangle -C POSTROUTING -j "$E216_MSS_CHAIN" >/dev/null 2>&1 \
          && "$tool" -w 5 -t mangle -C "$E216_MSS_CHAIN" -p tcp -m tcp \
              --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1; then
            printf '%s\n' "$candidate"; return 0
        fi
        # E68/E88以前曾把同一条动态TCPMSS规则直接写进POSTROUTING。
        # 只识别这个完整、精确的旧签名，不碰用户自己的固定MSS或其它规则。
        if "$tool" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp \
          --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1; then
            printf '%s\n' "$candidate"; return 0
        fi
    done < <(_e216_mss_candidate_order)
    return 1
}

_e216_mss_cleanup_backend() {
    local backend="${1:-}" tool line rc=0
    tool=$(_e216_mss_tool_path "$backend") || return 1
    "$tool" -w 5 -t mangle -S >/dev/null 2>&1 || return 1
    while "$tool" -w 5 -t mangle -D POSTROUTING -p tcp -m tcp \
      --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1; do :; done
    while "$tool" -w 5 -t mangle -D POSTROUTING -j "$E216_MSS_CHAIN" >/dev/null 2>&1; do :; done
    "$tool" -w 5 -t mangle -F "$E216_MSS_CHAIN" >/dev/null 2>&1 || true
    "$tool" -w 5 -t mangle -X "$E216_MSS_CHAIN" >/dev/null 2>&1 || true
    while IFS= read -r line; do
        [[ "$line" == *"-j $E216_MSS_CHAIN"* ]] && rc=1
    done < <("$tool" -w 5 -t mangle -S POSTROUTING 2>/dev/null || true)
    "$tool" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp \
      --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1 && rc=1 || true
    "$tool" -w 5 -t mangle -S "$E216_MSS_CHAIN" >/dev/null 2>&1 && rc=1 || true
    return "$rc"
}

_e216_mss_apply_backend() {
    local backend="${1:-}" tool jumps rules
    tool=$(_e216_mss_tool_path "$backend") || return 1
    # Never build a second rule set on top of a chain that could not be
    # removed.  E216 ignored this failure and could leave duplicate/partial
    # ownership; E218 fails so its caller can restore the backend snapshot.
    _e216_mss_cleanup_backend "$backend" || return 1
    modprobe iptable_mangle >/dev/null 2>&1 || true
    modprobe xt_TCPMSS >/dev/null 2>&1 || true
    "$tool" -w 5 -t mangle -N "$E216_MSS_CHAIN" >/dev/null 2>&1 || return 1
    "$tool" -w 5 -t mangle -A "$E216_MSS_CHAIN" -p tcp -m tcp \
        --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1 || return 1
    "$tool" -w 5 -t mangle -I POSTROUTING 1 -j "$E216_MSS_CHAIN" >/dev/null 2>&1 || return 1
    "$tool" -w 5 -t mangle -C POSTROUTING -j "$E216_MSS_CHAIN" >/dev/null 2>&1 || return 1
    "$tool" -w 5 -t mangle -C "$E216_MSS_CHAIN" -p tcp -m tcp \
        --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1 || return 1
    jumps=$("$tool" -w 5 -t mangle -S POSTROUTING 2>/dev/null \
        | grep -Ec -- "^-A POSTROUTING( .*)? -j $E216_MSS_CHAIN$" || true)
    rules=$("$tool" -w 5 -t mangle -S "$E216_MSS_CHAIN" 2>/dev/null \
        | grep -Ec -- "^-A $E216_MSS_CHAIN .* -j TCPMSS --clamp-mss-to-pmtu$" || true)
    test "$jumps" -eq 1 && test "$rules" -eq 1
}

_e216_mss_build_script() {
    local tool="${1:-}" out="${2:-}"
    case "$tool" in /*) test -x "$tool" || return 1 ;; *) return 1 ;; esac
    test -n "$out" || return 1
    cat >"$out" <<EOF_E216_MSS_SCRIPT
#!/usr/bin/env bash
set -Eeuo pipefail
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
IPT=$(printf '%q' "$tool")
CHAIN=$E216_MSS_CHAIN
modprobe iptable_mangle >/dev/null 2>&1 || true
modprobe xt_TCPMSS >/dev/null 2>&1 || true
while "\$IPT" -w 5 -t mangle -D POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1; do :; done
while "\$IPT" -w 5 -t mangle -D POSTROUTING -j "\$CHAIN" >/dev/null 2>&1; do :; done
"\$IPT" -w 5 -t mangle -F "\$CHAIN" >/dev/null 2>&1 || true
"\$IPT" -w 5 -t mangle -X "\$CHAIN" >/dev/null 2>&1 || true
"\$IPT" -w 5 -t mangle -N "\$CHAIN"
"\$IPT" -w 5 -t mangle -A "\$CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu
"\$IPT" -w 5 -t mangle -I POSTROUTING 1 -j "\$CHAIN"
"\$IPT" -w 5 -t mangle -C POSTROUTING -j "\$CHAIN"
"\$IPT" -w 5 -t mangle -C "\$CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu
! "\$IPT" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1
EOF_E216_MSS_SCRIPT
    chmod 0755 "$out" || return 1
    bash -n "$out"
}

_e216_mss_build_units() {
    local service="${1:-}" timer="${2:-}"
    test -n "$service" && test -n "$timer" || return 1
    cat >"$service" <<EOF_E216_MSS_SERVICE
[Unit]
Description=Xray E216 verified IPv4 MSS Clamp restore
Wants=network-online.target
After=network-online.target

[Service]
Type=oneshot
ExecStart=$E216_MSS_SCRIPT

[Install]
WantedBy=multi-user.target
EOF_E216_MSS_SERVICE
    cat >"$timer" <<EOF_E216_MSS_TIMER
[Unit]
Description=Periodic Xray E216 IPv4 MSS Clamp reconciliation

[Timer]
OnBootSec=1min
OnUnitInactiveSec=5min
AccuracySec=30s
Persistent=true
Unit=$E216_MSS_SERVICE_UNIT

[Install]
WantedBy=timers.target
EOF_E216_MSS_TIMER
    chmod 0644 "$service" "$timer" || return 1
    grep -Fqx 'Type=oneshot' "$service" \
      && grep -Fqx "ExecStart=$E216_MSS_SCRIPT" "$service" \
      && ! grep -q 'RemainAfterExit' "$service" \
      && grep -Fqx 'OnUnitInactiveSec=5min' "$timer"
}

_e216_mss_verify_on() {
    local backend tool jumps rules direct
    test "$(cat "$E88_MSS_STATE_FILE" 2>/dev/null || true)" = ON || return 1
    _e216_mss_backend_state_validate "$E216_MSS_BACKEND_STATE" || return 1
    backend=$(_e216_mss_state_value "$E216_MSS_BACKEND_STATE" backend) || return 1
    tool=$(_e216_mss_tool_path "$backend") || return 1
    test -f "$E216_MSS_SCRIPT" && test ! -L "$E216_MSS_SCRIPT" && bash -n "$E216_MSS_SCRIPT" || return 1
    test -f "$E216_MSS_SERVICE" && test ! -L "$E216_MSS_SERVICE" \
      && test -f "$E216_MSS_TIMER" && test ! -L "$E216_MSS_TIMER" || return 1
    grep -Fqx "IPT=$(printf '%q' "$tool")" "$E216_MSS_SCRIPT" || return 1
    systemctl is-enabled --quiet "$E216_MSS_SERVICE_UNIT" 2>/dev/null || return 1
    systemctl is-enabled --quiet "$E216_MSS_TIMER_UNIT" 2>/dev/null || return 1
    systemctl is-active --quiet "$E216_MSS_TIMER_UNIT" 2>/dev/null || return 1
    test "$(systemctl show "$E216_MSS_SERVICE_UNIT" -p Result --value 2>/dev/null || true)" = success || return 1
    "$tool" -w 5 -t mangle -C POSTROUTING -j "$E216_MSS_CHAIN" >/dev/null 2>&1 || return 1
    "$tool" -w 5 -t mangle -C "$E216_MSS_CHAIN" -p tcp -m tcp \
        --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1 || return 1
    jumps=$("$tool" -w 5 -t mangle -S POSTROUTING 2>/dev/null \
        | grep -Ec -- "^-A POSTROUTING( .*)? -j $E216_MSS_CHAIN$" || true)
    rules=$("$tool" -w 5 -t mangle -S "$E216_MSS_CHAIN" 2>/dev/null \
        | grep -Ec -- "^-A $E216_MSS_CHAIN .* -j TCPMSS --clamp-mss-to-pmtu$" || true)
    direct=$("$tool" -w 5 -t mangle -S POSTROUTING 2>/dev/null \
        | grep -Ec -- '^-A POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu$' || true)
    test "$jumps" -eq 1 && test "$rules" -eq 1 && test "$direct" -eq 0
}

_e216_mss_enable() (
    local d backend="" candidate tool pair save restore snapshot state_c service_c timer_c rc=0
    _e216_prepare || return 1
    test -d /run/systemd/system || { error 'systemd未运行，不能安全持久化MSS Clamp。'; return 1; }
    d=$(mktemp -d /tmp/xray-e216-mss.XXXXXX) || return 1
    trap 'rm -rf -- "${d:-}"' EXIT
    while IFS= read -r candidate; do
        _e216_mss_backend_readable "$candidate" || continue
        pair=$(_e216_mss_save_restore_paths "$candidate" 2>/dev/null || true)
        test -n "$pair" || continue
        save=${pair%%|*}; restore=${pair#*|}; snapshot="$d/$candidate.rules"
        "$save" >"$snapshot" 2>/dev/null || continue
        if _e216_mss_apply_backend "$candidate"; then backend=$candidate; break; fi
        "$restore" <"$snapshot" >/dev/null 2>&1 || {
            error "MSS后端试写失败且规则恢复失败：$candidate"
            return 1
        }
    done < <(_e216_mss_candidate_order)
    test -n "$backend" || {
        error '没有同时具备可读、可写、可快照/恢复能力的IPv4 xtables后端；MSS Clamp未修改。'
        return 1
    }
    tool=$(_e216_mss_tool_path "$backend") || return 1
    pair=$(_e216_mss_save_restore_paths "$backend") || return 1
    restore=${pair#*|}; snapshot="$d/$backend.rules"
    test -s "$snapshot" || return 1
    service_c="$d/service"; timer_c="$d/timer"; state_c="$d/state"
    _e216_mss_build_script "$tool" "$d/script" || rc=1
    test "$rc" -ne 0 || _e216_mss_build_units "$service_c" "$timer_c" || rc=1
    if test "$rc" -eq 0; then
        _e118_atomic_install "$d/script" "$E216_MSS_SCRIPT" 0755 || rc=1
        test "$rc" -ne 0 || _e118_atomic_install "$service_c" "$E216_MSS_SERVICE" 0644 || rc=1
        test "$rc" -ne 0 || _e118_atomic_install "$timer_c" "$E216_MSS_TIMER" 0644 || rc=1
        test "$rc" -ne 0 || _e216_mss_write_backend_state "$backend" || rc=1
        test "$rc" -ne 0 || _e216_mss_write_legacy_state ON || rc=1
    fi
    test "$rc" -ne 0 || systemctl daemon-reload >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || systemctl enable "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT" >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || systemctl start "$E216_MSS_SERVICE_UNIT" >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || systemctl start "$E216_MSS_TIMER_UNIT" >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || _e216_mss_verify_on || rc=1
    if test "$rc" -ne 0; then
        "$restore" <"$snapshot" >/dev/null 2>&1 || error "MSS失败后防火墙快照恢复失败：$snapshot"
        error 'MSS Clamp应用、服务或运行态读回失败；外围事务将恢复全部文件与服务。'
        return 1
    fi
    info "IPv4 MSS Clamp已验证：backend=$backend，单一POSTROUTING跳转，动态clamp-to-pmtu，5分钟复检。"
)

_e216_mss_disable() {
    local backend="" candidate selected_ok=0 readable=0 rc=0
    if _e216_mss_backend_state_validate "$E216_MSS_BACKEND_STATE"; then
        backend=$(_e216_mss_state_value "$E216_MSS_BACKEND_STATE" backend) || return 1
    elif test "$(cat "$E88_MSS_STATE_FILE" 2>/dev/null || true)" = ON; then
        backend=$(_e216_mss_discover_backend 2>/dev/null || true)
        test -n "$backend" || {
            error '历史MSS状态为ON，但未找到可验证的真实规则后端；拒绝声称已完整关闭。'
            return 1
        }
        warn "检测到历史MSS规则，按真实运行态接管后关闭：backend=$backend"
    fi
    systemctl disable --now "$E216_MSS_TIMER_UNIT" "$E216_MSS_SERVICE_UNIT" >/dev/null 2>&1 || true
    for candidate in iptables iptables-nft iptables-legacy; do
        _e216_mss_backend_readable "$candidate" || continue
        readable=$((readable + 1))
        if _e216_mss_cleanup_backend "$candidate"; then
            test "$candidate" != "$backend" || selected_ok=1
        else
            rc=1
        fi
    done
    if test -n "$backend" && test "$selected_ok" -ne 1; then
        error "无法在记录后端 $backend 证明MSS规则已删除。"
        rc=1
    fi
    if test "$rc" -ne 0; then return 1; fi
    rm -f -- "$E216_MSS_SERVICE" "$E216_MSS_TIMER" "$E216_MSS_SCRIPT" \
        "$E216_MSS_BACKEND_STATE" 2>/dev/null || return 1
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    _e216_mss_write_legacy_state OFF || return 1
    systemctl is-enabled --quiet "$E216_MSS_TIMER_UNIT" 2>/dev/null && return 1 || true
    info "IPv4 MSS Clamp已关闭并清理可读xtables后端（checked=$readable）。"
}

_e216_mss_status() {
    local default_iface mtu mss4 mss6 state backend="" candidate tool jump rule direct readable=0
    title 'V199e216：MSS Clamp / MTU 关系与运行态（只读）'
    default_iface=$(_e214_mtu_default_iface 2>/dev/null || true)
    mtu=$(_e214_mtu_current "$default_iface" 2>/dev/null || true)
    if [[ "$mtu" =~ ^[0-9]+$ ]] && ((mtu >= 1280)); then
        mss4=$((mtu - 40)); mss6=$((mtu - 60))
        echo "  默认出口=${default_iface:-unknown}  MTU=$mtu  名义IPv4 MSS=$mss4  名义IPv6 MSS=$mss6"
    else
        echo "  默认出口=${default_iface:-unknown}  MTU=${mtu:-unknown}"
    fi
    echo '  Clamp方式：仅改TCP SYN内的MSS通告，使用路径MTU动态计算；不改网卡MTU。'
    echo '  范围：E216独立管理IPv4 POSTROUTING；IPv6、WARP虚拟MTU与宿主MTU由各自模块管理。'
    echo '  第28项和小BBR不会自动开关MSS Clamp。'
    hr
    state=$(cat "$E88_MSS_STATE_FILE" 2>/dev/null || echo UNSET)
    if _e216_mss_backend_state_validate "$E216_MSS_BACKEND_STATE"; then
        backend=$(_e216_mss_state_value "$E216_MSS_BACKEND_STATE" backend)
    fi
    echo "  owner_state=$state  recorded_backend=${backend:-none}"
    for candidate in iptables iptables-nft iptables-legacy; do
        tool=$(_e216_mss_tool_path "$candidate" 2>/dev/null || true)
        test -n "$tool" || continue
        if ! "$tool" -w 5 -t mangle -S >/dev/null 2>&1; then
            printf '  %-17s %s\n' "$candidate" 'unreadable/no-CAP_NET_ADMIN'
            continue
        fi
        readable=$((readable + 1)); jump=0; rule=0; direct=0
        "$tool" -w 5 -t mangle -C POSTROUTING -j "$E216_MSS_CHAIN" >/dev/null 2>&1 && jump=1 || true
        "$tool" -w 5 -t mangle -C "$E216_MSS_CHAIN" -p tcp -m tcp \
            --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1 && rule=1 || true
        "$tool" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp \
            --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1 && direct=1 || true
        printf '  %-17s jump=%s rule=%s legacy_direct=%s%s\n' "$candidate" "$jump" "$rule" "$direct" \
            "$(test "$candidate" = "$backend" && echo ' [owner]' || true)"
    done
    test "$readable" -gt 0 || warn '没有可读xtables后端；不能把状态文件当作规则已生效的证明。'
    if test "$state" = ON; then
        if _e216_mss_verify_on; then info 'MSS Clamp状态、后端、规则、服务与定时器一致。'
        else error 'MSS Clamp存在状态/规则/服务脱节；请从菜单10→7重新启用或关闭。'; fi
    fi
}

# Bind every retained menu alias to the repaired E216 MSS implementation.
_e88_mss_clamp_on() { _e216_mss_enable; }
_e88_mss_clamp_off() { title '关闭 MSS Clamp（E216验证事务）'; _e216_mss_disable; }
_e168_mss_verify_on() { _e216_mss_verify_on; }
_e168_mss_finalize_off() { _e216_mss_disable; }

_e216_mss_self_test() (
    local d state script service timer rc=0
    d=$(mktemp -d /tmp/xray-e216-mss-selftest.XXXXXX) || return 1
    trap 'rm -rf -- "${d:-}"' EXIT
    mkdir -p "$d/e216" || return 1
    state="$d/e216/mss-backend.env"
    {
        echo version=199e216; echo backend=iptables-nft; echo family=ipv4
        echo mode=clamp-to-pmtu; echo updated_epoch=1780000000
    } >"$state"
    _e216_mss_backend_state_validate "$state" || rc=1
    sed -i 's/backend=iptables-nft/backend=bad/' "$state"
    ! _e216_mss_backend_state_validate "$state" || rc=1
    script="$d/script"; service="$d/service"; timer="$d/timer"
    _e216_mss_build_script /bin/true "$script" || rc=1
    _e216_mss_build_units "$service" "$timer" || rc=1
    bash -n "$script" || rc=1
    grep -Fq -- '--clamp-mss-to-pmtu' "$script" || rc=1
    grep -Fq -- '-I POSTROUTING 1' "$script" || rc=1
    grep -Fq -- '-D POSTROUTING -p tcp' "$script" || rc=1
    grep -Fq -- '! "$IPT" -w 5 -t mangle -C POSTROUTING -p tcp' "$script" || rc=1
    ! grep -Fq -- '--set-mss' "$script" || rc=1
    grep -Fqx 'OnUnitInactiveSec=5min' "$timer" || rc=1
    ! grep -q 'RemainAfterExit' "$service" || rc=1
    return "$rc"
)

_e216_structure_audit() {
    local rc=0 menu mtu_menu installer paths
    _e214_structure_audit >/dev/null || rc=1
    menu=$(declare -f _e214_main_menu 2>/dev/null || true)
    mtu_menu=$(declare -f _e214_mtu_menu 2>/dev/null || true)
    installer=$(declare -f _e214_install_self 2>/dev/null || true)
    paths=$(declare -f _e138_system_paths 2>/dev/null || true)
    echo 'V199e216 structure audit:'
    test "$SCRIPT_VERSION" = 199e216 && test "$E216_VERSION" = 199e216 || rc=1
    grep -q 'V199e216 - 事务稳态版' <<<"$menu" || rc=1
    grep -q 'MTU=1350' <<<"$mtu_menu" || rc=1
    grep -q '_e214_mtu_set_interactive auto - 1350' <<<"$mtu_menu" || rc=1
    grep -q 'E216_SELF_PATH' <<<"$installer" || rc=1
    grep -q 'E216_MSS_BACKEND_STATE' <<<"$paths" || rc=1
    for f in _e216_mss_enable _e216_mss_disable _e216_mss_status \
        _e216_mss_verify_on _e216_mss_build_script _e216_mss_backend_state_validate; do
        declare -F "$f" >/dev/null 2>&1 || rc=1
    done
    grep -Fq -- '--mss-status)' "$SCRIPT_PATH" || rc=1
    grep -Fq -- '--e216-summary)' "$SCRIPT_PATH" || rc=1
    if test "$rc" -eq 0; then echo '  result=PASS'; else echo '  result=FAIL'; fi
    return "$rc"
}

_e216_self_test() {
    local rc=0
    _e214_self_test || rc=1
    _e216_mss_self_test && echo '  [PASS] E216 MSS backend/state/script/unit invariants' \
      || { echo '  [FAIL] E216 MSS invariant'; rc=1; }
    _e216_structure_audit >/dev/null && echo '  [PASS] E216 identity/MTU1350/MSS final bindings' \
      || { echo '  [FAIL] E216 final binding'; rc=1; }
    if test "$rc" -eq 0; then echo 'V199e216 result: PASS'; else echo 'V199e216 result: FAIL'; fi
    return "$rc"
}

_e216_help() {
    cat <<'EOF_E216_HELP'
V199e216:
  --hot-update                         事务热更新到E216
  --summary                            导出节点URI、一次终端QR及PNG/SVG
  --network-audit                      只读网络参数/重复定义审计
  --full-network-apply                 事务应用完整127条请求
  --small-bbr-menu                     八个精确14/25/26项档位菜单
  --small-bbr-enable|status|disable    启用、读回或恢复小BBR
  --mtu-menu|--mtu-status              宿主机MTU事务；菜单内含1350快捷档
  --mtu-reconcile|--mtu-disable        立即复检/恢复首次接管前MTU
  --mss-status                         只读核对MSS、MTU、后端、规则和持久服务
  --mss-enable|--mss-disable           菜单10→7同一套IPv4动态MSS事务
  --ipv6-disable|enable|status         IPv6永久策略（无IPv4时默认拒绝关闭）
  --warp-menu|--warp-global-menu       Xray层定向/全局WARP
  --warp-full-menu                     Cloudflare系统全隧道
  --micro-menu                         完整28项微操中心
  --structure-audit|--self-test        E216最终绑定审计/离线发行门禁
  --uninstall                          受控卸载（先恢复各事务基线）

升级顺序：先用当前旧脚本 --small-bbr-disable 并确认恢复，再下载/执行E216
热更新，完成后再启用小BBR。E216会拒绝覆盖仍处于active的旧小BBR。

MTU与MSS：菜单27的1350快捷档只改宿主默认出口，并有断线回滚、开机与
5分钟复检。MSS Clamp只缩小TCP SYN中的MSS通告，不会修改网卡MTU；
第28项和小BBR都不会自动开关MSS。WARP虚拟MTU仍由WARP模块独立管理。
EOF_E216_HELP
}

#==============================================================================
# V199e218 FINAL MTU / MSS FAILURE-CLOSED CORRECTION LAYER
#
# Host MTU deliberately keeps E214's stable state/baseline ABI.  MSS keeps the
# E216 compatibility state, while E218 adds a pinned backend identity, its own
# snapshots, exclusive-backend verification and complete OFF-state readback.
#==============================================================================
readonly E218_VERSION="199e218"
readonly E218_DIR="$CONFIG_DIR/e218"
readonly E218_SELF_PATH="$SCRIPT_DIR/ex199e218.sh"
readonly E218_MSS_OWNER_STATE="$E218_DIR/mss-owner.env"
readonly E218_MSS_LOCK="/run/lock/xray-mss-clamp-e218.lock"
readonly E218_MSS_AUDIT="$LOG_DIR/e218/mss-last.log"

_e218_prepare() {
    _e216_prepare || return 1
    test ! -L "$E218_DIR" || { error "拒绝使用符号链接目录：$E218_DIR"; return 1; }
    _e214_ensure_directory "$E218_DIR" 0700 || return 1
}

_e218_mss_log() {
    install -d -m 0750 "$(dirname -- "$E218_MSS_AUDIT")" 2>/dev/null || return 0
    printf '%s %s\n' "$(date '+%F %T %z')" "$*" >>"$E218_MSS_AUDIT" 2>/dev/null || true
}

_e218_mss_owner_state_value() {
    local file="${1:-}" key="${2:-}"
    awk -F= -v wanted="$key" '$1==wanted{n++;v=substr($0,index($0,"=")+1)}END{if(n==1)print v;else exit 1}' \
        "$file" 2>/dev/null
}

_e218_mss_owner_state_validate() {
    local file="${1:-$E218_MSS_OWNER_STATE}" line key value count=0
    local version backend tool_path tool_identity family mode epoch actual expected_path
    local -A seen=()
    test -f "$file" && test ! -L "$file" && test -s "$file" || return 1
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([a-z_]+)=(.*)$ ]] || return 1
        key=${BASH_REMATCH[1]}; value=${BASH_REMATCH[2]}
        case "$key" in version|backend|tool_path|tool_identity|family|mode|updated_epoch) ;; *) return 1 ;; esac
        test -z "${seen[$key]+x}" || return 1
        test -n "$value" || return 1
        seen[$key]=1; count=$((count + 1))
    done <"$file"
    test "$count" -eq 7 || return 1
    for key in version backend tool_path tool_identity family mode updated_epoch; do
        test -n "${seen[$key]+x}" || return 1
    done
    version=$(_e218_mss_owner_state_value "$file" version) || return 1
    backend=$(_e218_mss_owner_state_value "$file" backend) || return 1
    tool_path=$(_e218_mss_owner_state_value "$file" tool_path) || return 1
    tool_identity=$(_e218_mss_owner_state_value "$file" tool_identity) || return 1
    family=$(_e218_mss_owner_state_value "$file" family) || return 1
    mode=$(_e218_mss_owner_state_value "$file" mode) || return 1
    epoch=$(_e218_mss_owner_state_value "$file" updated_epoch) || return 1
    test "$version" = 199e218 && _e216_mss_backend_valid "$backend" || return 1
    [[ "$tool_path" =~ ^/[A-Za-z0-9_./+-]+$ ]] || return 1
    [[ "$tool_identity" =~ ^/[A-Za-z0-9_./+-]+$ ]] || return 1
    test -x "$tool_path" || return 1
    expected_path=$(_e216_mss_tool_path "$backend" 2>/dev/null || true)
    test -n "$expected_path" && test "$tool_path" = "$expected_path" || return 1
    test -x "$tool_identity" && test ! -L "$tool_identity" || return 1
    actual=$(readlink -f -- "$tool_path" 2>/dev/null || true)
    test "$actual" = "$tool_identity" || return 1
    test "$family" = ipv4 && test "$mode" = clamp-to-pmtu || return 1
    [[ "$epoch" =~ ^[0-9]{1,20}$ ]]
}

_e218_mss_backend_identity() {
    local tool actual
    tool=$(_e216_mss_tool_path "${1:-}") || return 1
    actual=$(readlink -f -- "$tool" 2>/dev/null || true)
    case "$actual" in /*) test -x "$actual" && test ! -L "$actual" || return 1 ;; *) return 1 ;; esac
    printf '%s\n' "$actual"
}

_e218_mss_path_identity() {
    local path="${1:-}" actual
    case "$path" in /*) test -x "$path" || return 1 ;; *) return 1 ;; esac
    actual=$(readlink -f -- "$path" 2>/dev/null || true)
    case "$actual" in /*) test -x "$actual" && test ! -L "$actual" || return 1 ;; *) return 1 ;; esac
    printf '%s\n' "$actual"
}

_e218_mss_backend_identity_matches() {
    local backend="${1:-}" expected="${2:-}" actual
    [[ "$expected" =~ ^/[A-Za-z0-9_./+-]+$ ]] || return 1
    actual=$(_e218_mss_backend_identity "$backend" 2>/dev/null || true)
    test -n "$actual" && test "$actual" = "$expected"
}

_e218_mss_write_owner_state() {
    local backend="${1:-}" tool_path="${2:-}" tool_identity="${3:-}" tmp actual
    _e216_mss_backend_valid "$backend" || return 1
    [[ "$tool_path" =~ ^/[A-Za-z0-9_./+-]+$ ]] && test -x "$tool_path" || return 1
    [[ "$tool_identity" =~ ^/[A-Za-z0-9_./+-]+$ ]] \
      && test -x "$tool_identity" && test ! -L "$tool_identity" || return 1
    actual=$(readlink -f -- "$tool_path" 2>/dev/null || true)
    test "$actual" = "$tool_identity" || return 1
    _e218_prepare || return 1
    tmp=$(_e118_mktemp e218-mss-owner) || return 1
    {
        printf 'version=199e218\n'
        printf 'backend=%s\n' "$backend"
        printf 'tool_path=%s\n' "$tool_path"
        printf 'tool_identity=%s\n' "$tool_identity"
        printf 'family=ipv4\n'
        printf 'mode=clamp-to-pmtu\n'
        printf 'updated_epoch=%s\n' "$(date +%s)"
    } >"$tmp" || return 1
    chmod 0600 "$tmp" || return 1
    _e218_mss_owner_state_validate "$tmp" || return 1
    _e118_atomic_install "$tmp" "$E218_MSS_OWNER_STATE" 0600
}

_e218_mss_owner_state() {
    local value
    if test ! -e "$E88_MSS_STATE_FILE" && test ! -L "$E88_MSS_STATE_FILE"; then
        echo UNSET; return 0
    fi
    test -f "$E88_MSS_STATE_FILE" && test ! -L "$E88_MSS_STATE_FILE" || { echo INVALID; return 1; }
    value=$(awk 'NF{n++;v=$0}END{if(n==1)print v;else exit 1}' "$E88_MSS_STATE_FILE" 2>/dev/null || true)
    case "$value" in ON|OFF) echo "$value"; return 0 ;; *) echo INVALID; return 1 ;; esac
}

_e218_mss_backend_has_owned() {
    local backend="${1:-}" tool rules
    tool=$(_e216_mss_tool_path "$backend") || return 2
    rules=$("$tool" -w 5 -t mangle -S 2>/dev/null) || return 2
    grep -Eq -- "(^-N $E216_MSS_CHAIN$|^-A [^ ]+( .*)? -j $E216_MSS_CHAIN$|^-A POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu$)" \
        <<<"$rules"
}

_e218_mss_static_evidence() {
    local state path unit
    state=$(_e218_mss_owner_state 2>/dev/null || echo INVALID)
    case "$state" in ON|INVALID) return 0 ;; esac
    for path in "$E216_MSS_BACKEND_STATE" "$E218_MSS_OWNER_STATE" \
        "$E216_MSS_SCRIPT" "$E216_MSS_SERVICE" "$E216_MSS_TIMER"; do
        test ! -e "$path" && test ! -L "$path" || return 0
    done
    if test -d /run/systemd/system; then
        for unit in "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT"; do
            systemctl is-enabled --quiet "$unit" 2>/dev/null && return 0 || true
            systemctl is-active --quiet "$unit" 2>/dev/null && return 0 || true
        done
    fi
    return 1
}

_e218_mss_runtime_evidence() {
    local candidate identity rc
    local -A seen=()
    while IFS= read -r candidate; do
        identity=$(_e218_mss_backend_identity "$candidate" 2>/dev/null || true)
        test -n "$identity" && test -z "${seen[$identity]+x}" || continue
        seen[$identity]=1
        _e218_mss_backend_has_owned "$candidate"; rc=$?
        test "$rc" -eq 0 && return 0
    done < <(_e216_mss_candidate_order)
    return 1
}

_e218_mss_any_evidence() {
    _e218_mss_static_evidence || _e218_mss_runtime_evidence
}

_e218_mss_capture_control() {
    local d="${1:-}" path snap unit
    test -n "$d" || return 1
    install -d -m 0700 "$d/control" || return 1
    : >"$d/control/manifest" || return 1
    for path in "$E88_MSS_STATE_FILE" "$E216_MSS_BACKEND_STATE" "$E218_MSS_OWNER_STATE" \
        "$E216_MSS_SCRIPT" "$E216_MSS_SERVICE" "$E216_MSS_TIMER"; do
        snap="$d/control/$(printf '%s' "$path" | sha256sum | awk '{print $1}')"
        _e135_snapshot_file "$path" "$snap" || return 1
        printf '%s|%s\n' "$path" "$snap" >>"$d/control/manifest" || return 1
    done
    : >"$d/control/services.env" || return 1
    for unit in "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT"; do
        _e204_service_snapshot "$unit" >>"$d/control/services.env" || return 1
    done
    (cd "$d/control" && sha256sum manifest services.env >control.sha256) || return 1
}

_e218_mss_restore_control() {
    local d="${1:-}" path snap rc=0
    test -s "$d/control/control.sha256" \
      && (cd "$d/control" && sha256sum -c control.sha256 >/dev/null 2>&1) || return 1
    while IFS='|' read -r path snap; do
        test -n "$path" && test -n "$snap" || continue
        _e135_restore_file "$path" "$snap" || rc=1
    done <"$d/control/manifest"
    systemctl daemon-reload >/dev/null 2>&1 || rc=1
    _e204_services_restore_file "$d/control/services.env" || rc=1
    return "$rc"
}

_e218_mss_capture_backends() {
    local d="${1:-}" list="${2:-}" candidate identity pair save save_identity restore restore_identity snapshot idx=0 owned_rc
    local -A seen=()
    test -n "$d" && test -n "$list" || return 1
    : >"$list" || return 1
    while IFS= read -r candidate; do
        _e216_mss_backend_readable "$candidate" || continue
        identity=$(_e218_mss_backend_identity "$candidate" 2>/dev/null || true)
        test -n "$identity" && test -z "${seen[$identity]+x}" || continue
        seen[$identity]=1
        pair=$(_e216_mss_save_restore_paths "$candidate" 2>/dev/null || true)
        if test -z "$pair"; then
            _e218_mss_backend_has_owned "$candidate"; owned_rc=$?
            case "$owned_rc" in
                0) error "后端 $candidate 存在MSS规则，但缺少配套save/restore；拒绝无快照修改。"; return 1 ;;
                1) continue ;;
                *) error "后端 $candidate 在快照前失去可读性。"; return 1 ;;
            esac
        fi
        save=${pair%%|*}; restore=${pair#*|}
        save_identity=$(_e218_mss_path_identity "$save" 2>/dev/null || true)
        restore_identity=$(_e218_mss_path_identity "$restore" 2>/dev/null || true)
        if test -z "$save_identity" || test -z "$restore_identity"; then
            error "后端 $candidate 的save/restore实体不可固定；拒绝无身份快照。"
            return 1
        fi
        idx=$((idx + 1))
        snapshot="$d/firewall-$idx.rules"
        if ! "$save" >"$snapshot" 2>/dev/null; then
            _e218_mss_backend_has_owned "$candidate"; owned_rc=$?
            case "$owned_rc" in
                0) error "后端 $candidate 存在MSS规则，但快照失败；拒绝修改。"; return 1 ;;
                1) rm -f -- "$snapshot"; continue ;;
                *) error "后端 $candidate 在快照失败后无法读回。"; return 1 ;;
            esac
        fi
        test "$(_e218_mss_path_identity "$save" 2>/dev/null || true)" = "$save_identity" || return 1
        test "$(_e218_mss_path_identity "$restore" 2>/dev/null || true)" = "$restore_identity" || return 1
        printf '%s|%s|%s|%s|%s|%s|%s\n' \
            "$candidate" "$identity" "$save" "$save_identity" \
            "$restore" "$restore_identity" "$snapshot" >>"$list" || return 1
    done < <(_e216_mss_candidate_order)
    test -s "$list"
}

_e218_mss_restore_backends() {
    local list="${1:-}" i backend identity save save_identity restore restore_identity snapshot rc=0
    local -a rows=()
    test -s "$list" || return 1
    mapfile -t rows <"$list" || return 1
    for ((i=${#rows[@]}-1; i>=0; i--)); do
        IFS='|' read -r backend identity save save_identity restore restore_identity snapshot <<<"${rows[$i]}"
        test "$(_e218_mss_path_identity "$restore" 2>/dev/null || true)" = "$restore_identity" \
          && test -s "$snapshot" && "$restore" <"$snapshot" >/dev/null 2>&1 || rc=1
    done
    return "$rc"
}

_e218_mss_cleanup_captured() {
    local list="${1:-}" backend identity save save_identity restore restore_identity snapshot
    test -s "$list" || return 1
    while IFS='|' read -r backend identity save save_identity restore restore_identity snapshot; do
        _e218_mss_backend_identity_matches "$backend" "$identity" || return 1
        _e216_mss_cleanup_backend "$backend" || return 1
    done <"$list"
}

_e218_mss_captured_off() {
    local list="${1:-}" backend identity save save_identity restore restore_identity snapshot rc
    test -s "$list" || return 1
    while IFS='|' read -r backend identity save save_identity restore restore_identity snapshot; do
        _e218_mss_backend_identity_matches "$backend" "$identity" || return 1
        _e216_mss_backend_readable "$backend" || return 1
        _e218_mss_backend_has_owned "$backend"; rc=$?
        test "$rc" -eq 1 || return 1
    done <"$list"
}

_e218_mss_captured_exclusive() {
    local list="${1:-}" selected="${2:-}" backend identity save save_identity restore restore_identity snapshot rc owners=0
    test -s "$list" && _e216_mss_backend_valid "$selected" || return 1
    while IFS='|' read -r backend identity save save_identity restore restore_identity snapshot; do
        _e218_mss_backend_identity_matches "$backend" "$identity" || return 1
        _e216_mss_backend_readable "$backend" || return 1
        _e218_mss_backend_has_owned "$backend"; rc=$?
        if test "$backend" = "$selected"; then
            test "$rc" -eq 0 || return 1
            owners=$((owners + 1))
        else
            test "$rc" -eq 1 || return 1
        fi
    done <"$list"
    test "$owners" -eq 1
}

_e218_mss_stop_triggers() {
    systemctl stop "$E216_MSS_TIMER_UNIT" "$E216_MSS_SERVICE_UNIT" >/dev/null 2>&1 || true
    systemctl is-active --quiet "$E216_MSS_TIMER_UNIT" 2>/dev/null && return 1 || true
    systemctl is-active --quiet "$E216_MSS_SERVICE_UNIT" 2>/dev/null && return 1 || true
}

_e230_mss_disable_units_idempotent() {
    local unit
    for unit in "$E216_MSS_TIMER_UNIT" "$E216_MSS_SERVICE_UNIT"; do
        systemctl stop "$unit" >/dev/null 2>&1 || true
        systemctl disable "$unit" >/dev/null 2>&1 || true
    done
    return 0
}

_e218_mss_rollback() {
    local d="${1:-}" list="${2:-}" rc=0
    _e218_mss_restore_control "$d" || rc=1
    test ! -s "$list" || _e218_mss_restore_backends "$list" || rc=1
    test "$rc" -eq 0 || error "MSS内层回滚未完全通过：$d"
    return "$rc"
}

_e218_mss_build_script() {
    local tool_path="${1:-}" tool_identity="${2:-}" out="${3:-}"
    local actual
    [[ "$tool_path" =~ ^/[A-Za-z0-9_./+-]+$ ]] && test -x "$tool_path" || return 1
    [[ "$tool_identity" =~ ^/[A-Za-z0-9_./+-]+$ ]] \
      && test -x "$tool_identity" && test ! -L "$tool_identity" || return 1
    actual=$(readlink -f -- "$tool_path" 2>/dev/null || true)
    test "$actual" = "$tool_identity" && test -n "$out" || return 1
    cat >"$out" <<EOF_E218_MSS_SCRIPT
#!/usr/bin/env bash
set -Eeuo pipefail
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
IPT=$(printf '%q' "$tool_path")
IDENTITY=$(printf '%q' "$tool_identity")
CHAIN=$E216_MSS_CHAIN
test -x "\$IPT"
test "\$(readlink -f -- "\$IPT" 2>/dev/null || true)" = "\$IDENTITY"
modprobe iptable_mangle >/dev/null 2>&1 || true
modprobe xt_TCPMSS >/dev/null 2>&1 || true
while "\$IPT" -w 5 -t mangle -D POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1; do :; done
while "\$IPT" -w 5 -t mangle -D POSTROUTING -j "\$CHAIN" >/dev/null 2>&1; do :; done
"\$IPT" -w 5 -t mangle -F "\$CHAIN" >/dev/null 2>&1 || true
"\$IPT" -w 5 -t mangle -X "\$CHAIN" >/dev/null 2>&1 || true
"\$IPT" -w 5 -t mangle -N "\$CHAIN"
"\$IPT" -w 5 -t mangle -A "\$CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu
"\$IPT" -w 5 -t mangle -I POSTROUTING 1 -j "\$CHAIN"
"\$IPT" -w 5 -t mangle -C POSTROUTING -j "\$CHAIN"
"\$IPT" -w 5 -t mangle -C "\$CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu
! "\$IPT" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1
EOF_E218_MSS_SCRIPT
    chmod 0755 "$out" || return 1
    bash -n "$out" || return 1
    grep -Fqx "IPT=$(printf '%q' "$tool_path")" "$out" \
      && grep -Fqx "IDENTITY=$(printf '%q' "$tool_identity")" "$out" \
      && grep -Fq 'readlink -f -- "$IPT"' "$out"
}

_e218_mss_verify_on() {
    local backend tool tool_identity expected jumps rules direct candidate identity rc
    local -A seen=()
    test "$(_e218_mss_owner_state 2>/dev/null || true)" = ON || return 1
    if test -e "$E218_MSS_OWNER_STATE" || test -L "$E218_MSS_OWNER_STATE"; then
        _e218_mss_owner_state_validate "$E218_MSS_OWNER_STATE" || return 1
    else
        # An active E216 installation remains valid across the hot update.  It
        # becomes pinned to a real backend the next time the user enables MSS.
        _e216_mss_verify_on
        return $?
    fi
    _e216_mss_backend_state_validate "$E216_MSS_BACKEND_STATE" || return 1
    backend=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" backend) || return 1
    tool=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" tool_path) || return 1
    tool_identity=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" tool_identity) || return 1
    expected=$(_e218_mss_backend_identity "$backend" 2>/dev/null || true)
    test "$expected" = "$tool_identity" || return 1
    test "$(readlink -f -- "$tool" 2>/dev/null || true)" = "$tool_identity" || return 1
    test "$(_e216_mss_state_value "$E216_MSS_BACKEND_STATE" backend)" = "$backend" || return 1
    test -f "$E216_MSS_SCRIPT" && test ! -L "$E216_MSS_SCRIPT" && bash -n "$E216_MSS_SCRIPT" || return 1
    grep -Fqx "IPT=$(printf '%q' "$tool")" "$E216_MSS_SCRIPT" || return 1
    grep -Fqx "IDENTITY=$(printf '%q' "$tool_identity")" "$E216_MSS_SCRIPT" || return 1
    test -f "$E216_MSS_SERVICE" && test ! -L "$E216_MSS_SERVICE" \
      && test -f "$E216_MSS_TIMER" && test ! -L "$E216_MSS_TIMER" || return 1
    systemctl is-enabled --quiet "$E216_MSS_SERVICE_UNIT" 2>/dev/null || return 1
    systemctl is-enabled --quiet "$E216_MSS_TIMER_UNIT" 2>/dev/null || return 1
    systemctl is-active --quiet "$E216_MSS_TIMER_UNIT" 2>/dev/null || return 1
    test "$(systemctl show "$E216_MSS_SERVICE_UNIT" -p Result --value 2>/dev/null || true)" = success || return 1
    "$tool" -w 5 -t mangle -S >/dev/null 2>&1 || return 1
    jumps=$("$tool" -w 5 -t mangle -S POSTROUTING 2>/dev/null \
        | grep -Ec -- "^-A POSTROUTING( .*)? -j $E216_MSS_CHAIN$" || true)
    rules=$("$tool" -w 5 -t mangle -S "$E216_MSS_CHAIN" 2>/dev/null \
        | grep -Ec -- "^-A $E216_MSS_CHAIN .* -j TCPMSS --clamp-mss-to-pmtu$" || true)
    direct=$("$tool" -w 5 -t mangle -S POSTROUTING 2>/dev/null \
        | grep -Ec -- '^-A POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu$' || true)
    test "$jumps" -eq 1 && test "$rules" -eq 1 && test "$direct" -eq 0 || return 1
    while IFS= read -r candidate; do
        identity=$(_e218_mss_backend_identity "$candidate" 2>/dev/null || true)
        test -n "$identity" && test -z "${seen[$identity]+x}" || continue
        seen[$identity]=1
        test "$identity" = "$tool_identity" && continue
        _e218_mss_backend_has_owned "$candidate"; rc=$?
        test "$rc" -eq 1 || return 1
    done < <(_e216_mss_candidate_order)
    # A second administrator-owned direct rule on another xtables backend is
    # also a double-clamp collision, even if our selected backend is perfect.
    _e220_mss_unowned_direct_report >/dev/null 2>&1
}

_e218_mss_consistency() {
    local state
    state=$(_e218_mss_owner_state 2>/dev/null || echo INVALID)
    case "$state" in
        ON) _e218_mss_verify_on ;;
        OFF|UNSET) ! _e218_mss_static_evidence && ! _e218_mss_runtime_evidence ;;
        *) return 1 ;;
    esac
}

_e218_mss_verify_off() {
    local state
    state=$(_e218_mss_owner_state 2>/dev/null || echo INVALID)
    case "$state" in OFF|UNSET) ;; *) return 1 ;; esac
    ! _e218_mss_static_evidence && ! _e218_mss_runtime_evidence
}

_e218_mss_enable() (
    local d list row backend="" candidate identity save save_identity restore restore_identity snapshot tool_path="" tool_identity="" attempt=0
    local service_c timer_c rc=0 rollback_rc=0
    _e218_prepare || return 1
    test -d /run/systemd/system || { error 'systemd未运行，不能安全持久化MSS Clamp。'; return 1; }
    _e214_ensure_run_lock || return 1
    exec 209>"$E218_MSS_LOCK"
    flock -n 209 || { error '已有MSS Clamp事务正在运行。'; return 1; }
    d=$(mktemp -d /tmp/xray-e218-mss-enable.XXXXXX) || return 1
    trap 'rm -rf -- "${d:-}"' EXIT
    list="$d/backends.tsv"
    _e218_mss_capture_control "$d" || return 1
    _e218_mss_stop_triggers || { error '旧MSS定时器/服务未能停止，未修改规则。'; return 1; }
    _e218_mss_capture_backends "$d" "$list" || {
        _e218_mss_restore_control "$d" || true
        error '没有可安全快照与恢复的IPv4 xtables后端。'
        return 1
    }
    while IFS= read -r row; do
        IFS='|' read -r candidate identity save save_identity restore restore_identity snapshot <<<"$row"
        attempt=$((attempt + 1))
        if test "$attempt" -gt 1; then
            _e218_mss_restore_backends "$list" || break
        fi
        _e218_mss_cleanup_captured "$list" || continue
        if _e216_mss_apply_backend "$candidate"; then
            backend=$candidate; tool_identity=$identity
            tool_path=$(_e216_mss_tool_path "$candidate") || break
            break
        fi
    done <"$list"
    if test -z "$backend"; then
        _e218_mss_rollback "$d" "$list" || rollback_rc=1
        error 'MSS所有候选后端试写/读回失败，已恢复快照。'
        return 1
    fi
    service_c="$d/service"; timer_c="$d/timer"
    _e218_mss_build_script "$tool_path" "$tool_identity" "$d/script" || rc=1
    test "$rc" -ne 0 || _e216_mss_build_units "$service_c" "$timer_c" || rc=1
    test "$rc" -ne 0 || _e118_atomic_install "$d/script" "$E216_MSS_SCRIPT" 0755 || rc=1
    test "$rc" -ne 0 || _e118_atomic_install "$service_c" "$E216_MSS_SERVICE" 0644 || rc=1
    test "$rc" -ne 0 || _e118_atomic_install "$timer_c" "$E216_MSS_TIMER" 0644 || rc=1
    test "$rc" -ne 0 || _e216_mss_write_backend_state "$backend" || rc=1
    test "$rc" -ne 0 || _e218_mss_write_owner_state "$backend" "$tool_path" "$tool_identity" || rc=1
    test "$rc" -ne 0 || _e216_mss_write_legacy_state ON || rc=1
    test "$rc" -ne 0 || systemctl daemon-reload >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || systemctl enable "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT" >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || systemctl start "$E216_MSS_SERVICE_UNIT" >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || systemctl start "$E216_MSS_TIMER_UNIT" >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || _e218_mss_verify_on || rc=1
    test "$rc" -ne 0 || _e218_mss_captured_exclusive "$list" "$backend" || rc=1
    if test "$rc" -ne 0; then
        _e218_mss_rollback "$d" "$list" || rollback_rc=1
        _e218_mss_log "action=enable result=failed backend=${backend:-none} rollback=$rollback_rc snapshot=$d"
        error 'MSS规则、固定后端、状态、服务或唯一性读回失败；已执行内层回滚。'
        return 1
    fi
    _e218_mss_log "action=enable result=ok backend=$backend tool=$tool_path identity=$tool_identity"
    info "IPv4 MSS Clamp已验证：backend=$backend（实体已固定），单一POSTROUTING跳转，5分钟复检。"
)

_e218_mss_disable() (
    local d list evidence=0 state rc=0 rollback_rc=0 path unit
    _e218_prepare || return 1
    _e218_mss_any_evidence && evidence=1 || true
    if test "$evidence" -eq 0; then
        info 'IPv4 MSS Clamp未启用，也未发现可读残留。'
        return 0
    fi
    test -d /run/systemd/system || { error 'systemd未运行，拒绝声称已完整关闭MSS。'; return 1; }
    _e214_ensure_run_lock || return 1
    exec 209>"$E218_MSS_LOCK"
    flock -n 209 || { error '已有MSS Clamp事务正在运行。'; return 1; }
    d=$(mktemp -d /tmp/xray-e218-mss-disable.XXXXXX) || return 1
    trap 'rm -rf -- "${d:-}"' EXIT
    list="$d/backends.tsv"
    _e218_mss_capture_control "$d" || return 1
    _e218_mss_stop_triggers || rc=1
    test "$rc" -ne 0 || _e218_mss_capture_backends "$d" "$list" || rc=1
    test "$rc" -ne 0 || _e218_mss_cleanup_captured "$list" || rc=1
    test "$rc" -ne 0 || _e218_mss_captured_off "$list" || rc=1
    # systemctl returns non-zero when an old/partial release has already lost
    # one of these unit files.  That is an idempotent OFF condition, not a
    # failed mutation.  Attempt stop/disable for both names and let the strict
    # active/enabled/file readback below decide success.
    test "$rc" -ne 0 || _e230_mss_disable_units_idempotent || rc=1
    if test "$rc" -eq 0; then
        rm -f -- "$E216_MSS_SERVICE" "$E216_MSS_TIMER" "$E216_MSS_SCRIPT" \
            "$E216_MSS_BACKEND_STATE" "$E218_MSS_OWNER_STATE" || rc=1
    fi
    test "$rc" -ne 0 || systemctl daemon-reload >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || _e216_mss_write_legacy_state OFF || rc=1
    if test "$rc" -eq 0; then
        for unit in "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT"; do
            systemctl is-active --quiet "$unit" 2>/dev/null && rc=1 || true
            systemctl is-enabled --quiet "$unit" 2>/dev/null && rc=1 || true
        done
        for path in "$E216_MSS_SERVICE" "$E216_MSS_TIMER" "$E216_MSS_SCRIPT" \
            "$E216_MSS_BACKEND_STATE" "$E218_MSS_OWNER_STATE"; do
            test ! -e "$path" && test ! -L "$path" || rc=1
        done
        _e218_mss_captured_off "$list" || rc=1
        _e218_mss_consistency || rc=1
    fi
    if test "$rc" -ne 0; then
        _e218_mss_rollback "$d" "$list" || rollback_rc=1
        _e218_mss_log "action=disable result=failed rollback=$rollback_rc snapshot=$d"
        error 'MSS关闭后的规则、状态、文件或systemd读回失败；已执行内层回滚。'
        return 1
    fi
    state=$(_e218_mss_owner_state)
    _e218_mss_log "action=disable result=ok state=$state"
    info 'IPv4 MSS Clamp已关闭：所有可快照后端、服务、定时器、脚本与状态均已双向读回。'
)

_e218_mss_status() {
    local default_iface mtu mss4 mss6 state backend="" tool="" tool_identity="" candidate identity rc readable=0
    local jump rule direct verdict
    local -A seen=()
    title 'V199e230：MSS Clamp / MTU 关系与运行态（只读）'
    default_iface=$(_e214_mtu_default_iface 2>/dev/null || true)
    mtu=$(_e214_mtu_current "$default_iface" 2>/dev/null || true)
    if [[ "$mtu" =~ ^[0-9]+$ ]] && ((mtu >= 1280)); then
        mss4=$((mtu - 40)); mss6=$((mtu - 60))
        echo "  默认出口=${default_iface:-unknown}  MTU=$mtu  无选项头时IPv4 MSS≈$mss4  IPv6 MSS≈$mss6"
    else
        echo "  默认出口=${default_iface:-unknown}  MTU=${mtu:-unknown}"
    fi
    echo '  MTU=1350时：名义IPv4 MSS≈1310，IPv6 MSS≈1290（TCP选项可使实际头部更长）。'
    echo '  Clamp只改新TCP握手SYN/SYN-ACK中的MSS通告，不改网卡MTU，不处理UDP。'
    echo '  Xray是本机进程，所以使用IPv4 POSTROUTING；只改FORWARD会漏掉本机Xray出站。'
    echo '  作用域=宿主机所有经IPv4 POSTROUTING的TCP新握手（包含Xray，不是仅Xray）。'
    echo '  动态clamp只按内核已知的路由PMTU缩小且不会放大MSS；它不能猜出被ICMP屏蔽的未知更小PMTU。'
    echo '  本机TCP通常已会从出口MTU派生MSS；Clamp是转发/路径异常的防御性兜底，不是加速开关。'
    echo '  第28项、小BBR与MTU=1350都不会暗中开关MSS Clamp。'
    hr
    state=$(_e218_mss_owner_state 2>/dev/null || echo INVALID)
    if _e218_mss_owner_state_validate "$E218_MSS_OWNER_STATE"; then
        backend=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" backend)
        tool=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" tool_path)
        tool_identity=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" tool_identity)
    elif test -e "$E218_MSS_OWNER_STATE" || test -L "$E218_MSS_OWNER_STATE"; then
        backend='invalid-e218-state'; tool='invalid'; tool_identity='invalid'
    elif _e216_mss_backend_state_validate "$E216_MSS_BACKEND_STATE"; then
        backend=$(_e216_mss_state_value "$E216_MSS_BACKEND_STATE" backend)
        tool='legacy-unpinned'
    fi
    echo "  owner_state=$state  recorded_backend=${backend:-none}  frontend=${tool:-none}  pinned_identity=${tool_identity:-none}"
    if test "$state" = ON && test "$tool" = legacy-unpinned; then
        warn '检测到兼容保留的E216活动MSS；当前可继续使用，但尚未固定后端实体。可在菜单10→7重新启用以迁移。'
    fi
    while IFS= read -r candidate; do
        identity=$(_e218_mss_backend_identity "$candidate" 2>/dev/null || true)
        test -n "$identity" && test -z "${seen[$identity]+x}" || continue
        seen[$identity]=1
        if ! _e216_mss_backend_readable "$candidate"; then
            printf '  %-17s %s\n' "$candidate" 'unreadable/no-CAP_NET_ADMIN'; continue
        fi
        readable=$((readable + 1)); jump=0; rule=0; direct=0
        # Execute the frontend name, not xtables-*-multi directly: the multi
        # binary selects its personality from argv[0].  The realpath above is
        # only an identity/deduplication guard.
        "$candidate" -w 5 -t mangle -C POSTROUTING -j "$E216_MSS_CHAIN" >/dev/null 2>&1 && jump=1 || true
        "$candidate" -w 5 -t mangle -C "$E216_MSS_CHAIN" -p tcp -m tcp \
            --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1 && rule=1 || true
        "$candidate" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp \
            --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1 && direct=1 || true
        printf '  %-17s jump=%s rule=%s legacy_direct=%s real=%s%s\n' \
            "$candidate" "$jump" "$rule" "$direct" "$identity" \
            "$(test "$candidate" = "$backend" && echo ' [owner]' || true)"
    done < <(_e216_mss_candidate_order)
    if test "$readable" -eq 0; then
        warn '没有可读xtables后端；不能把状态文件当作规则生效或规则已清空的证据。'
        case "$state" in
            OFF|UNSET)
                ! _e218_mss_static_evidence || return 1
                info 'MSS状态结论：无静态所有权证据；运行态不可验证（未宣称OFF-clean）。'
                return 0
                ;;
        esac
    fi
    if _e218_mss_consistency; then
        case "$state" in ON) verdict='ON-consistent' ;; *) verdict='OFF-clean' ;; esac
        info "MSS状态结论：$verdict"
    else
        error 'MSS存在状态/规则/后端/服务漂移；请从菜单10→7显式重新启用或关闭。'
        return 1
    fi
}

# Every retained menu/CLI path must end at the E218 transaction.
_e88_mss_clamp_on() { _e218_mss_enable; }
_e88_mss_clamp_off() { title '关闭 MSS Clamp（E218失败闭合事务）'; _e218_mss_disable; }
_e168_mss_verify_on() { _e218_mss_verify_on; }
_e168_mss_finalize_off() { _e218_mss_verify_off; }

_e218_mss_mock_self_test() (
    local d fake save_fake restore_fake state owner list rc=0
    d=$(mktemp -d /tmp/xray-e218-mss-mock.XXXXXX) || return 1
    trap 'rm -rf -- "${d:-}"' EXIT
    install -d -m 0700 "$d/bin" || return 1
    fake="$d/bin/iptables"; state="$d/mock.state"
    cat >"$fake" <<'EOF_E218_MOCK_IPTABLES'
#!/usr/bin/env bash
set -euo pipefail
state=${E218_MOCK_IPTABLES_STATE:?}
chain=0; jump=0; rule=0; direct=0
test ! -f "$state" || source "$state"
save_state() {
    printf 'chain=%s\njump=%s\nrule=%s\ndirect=%s\n' "$chain" "$jump" "$rule" "$direct" >"$state.tmp"
    mv -f -- "$state.tmp" "$state"
}
while test "$#" -gt 0; do
    case "$1" in -w) shift 2 ;; -t) shift 2 ;; *) break ;; esac
done
cmd=${1:-}; test "$#" -eq 0 || shift
case "$cmd" in
    -S)
        target=${1:-all}
        case "$target" in
            all) test "$chain" = 0 || echo '-N XRAY_MSS_CLAMP'; test "$jump" = 0 || echo '-A POSTROUTING -j XRAY_MSS_CLAMP'; test "$rule" = 0 || echo '-A XRAY_MSS_CLAMP -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu'; test "$direct" = 0 || echo '-A POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu' ;;
            POSTROUTING) test "$jump" = 0 || echo '-A POSTROUTING -j XRAY_MSS_CLAMP'; test "$direct" = 0 || echo '-A POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu' ;;
            XRAY_MSS_CLAMP) test "$chain" = 1 || exit 1; test "$rule" = 0 || echo '-A XRAY_MSS_CLAMP -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu' ;;
            *) exit 1 ;;
        esac ;;
    -C)
        target=${1:-}; shift || true; args=" $* "
        case "$target:$args" in
            'POSTROUTING: -j XRAY_MSS_CLAMP ') test "$jump" = 1 ;;
            XRAY_MSS_CLAMP:*) test "$chain" = 1 && test "$rule" = 1 ;;
            POSTROUTING:*) test "$direct" = 1 ;;
            *) exit 1 ;;
        esac ;;
    -D)
        test "${E218_MOCK_FAIL_DELETE:-0}" = 0 || exit 1
        target=${1:-}; shift || true; args=" $* "
        case "$target:$args" in
            'POSTROUTING: -j XRAY_MSS_CLAMP ') test "$jump" = 1 || exit 1; jump=0 ;;
            POSTROUTING:*) test "$direct" = 1 || exit 1; direct=0 ;;
            *) exit 1 ;;
        esac
        save_state ;;
    -N) test "${1:-}" = XRAY_MSS_CLAMP && test "$chain" = 0; chain=1; save_state ;;
    -A)
        target=${1:-}; test "$#" -eq 0 || shift
        case "$target" in XRAY_MSS_CLAMP) test "$chain" = 1; rule=1 ;; POSTROUTING) direct=1 ;; *) exit 1 ;; esac
        save_state ;;
    -I) test "${1:-}" = POSTROUTING && test "${2:-}" = 1; jump=1; save_state ;;
    -F) test "${E218_MOCK_FAIL_DELETE:-0}" = 0 || exit 1; test "${1:-}" = XRAY_MSS_CLAMP && test "$chain" = 1; rule=0; save_state ;;
    -X) test "${E218_MOCK_FAIL_DELETE:-0}" = 0 || exit 1; test "${1:-}" = XRAY_MSS_CLAMP && test "$chain" = 1 && test "$rule" = 0 && test "$jump" = 0; chain=0; save_state ;;
    *) exit 1 ;;
esac
EOF_E218_MOCK_IPTABLES
    chmod 0755 "$fake" || return 1
    save_fake="$d/bin/iptables-save"
    restore_fake="$d/bin/iptables-restore"
    cat >"$save_fake" <<'EOF_E218_MOCK_SAVE'
#!/usr/bin/env bash
printf '%s\n' '# e218 mock ruleset'
EOF_E218_MOCK_SAVE
    cat >"$restore_fake" <<'EOF_E218_MOCK_RESTORE'
#!/usr/bin/env bash
cat >/dev/null
EOF_E218_MOCK_RESTORE
    chmod 0755 "$save_fake" "$restore_fake" || return 1
    printf 'chain=0\njump=0\nrule=0\ndirect=0\n' >"$state"
    export E218_MOCK_IPTABLES_STATE="$state"
    PATH="$d/bin:$PATH"
    # Isolate ownership decisions from any real host state while proving that
    # an administrator-owned direct rule survives cleanup attempts.
    _e218_mss_owner_state() { echo UNSET; }
    _e216_mss_apply_backend iptables || rc=1
    _e218_mss_backend_has_owned iptables || rc=1
    _e216_mss_cleanup_backend iptables || rc=1
    _e218_mss_backend_has_owned iptables && rc=1 || test "$?" -eq 1 || rc=1
    printf 'chain=0\njump=0\nrule=0\ndirect=1\n' >"$state"
    _e216_mss_cleanup_backend iptables >/dev/null 2>&1 || rc=1
    grep -Fqx 'direct=1' "$state" || rc=1
    _e218_mss_runtime_evidence && rc=1 || true
    printf 'chain=0\njump=0\nrule=0\ndirect=0\n' >"$state"
    list="$d/backends.tsv"
    _e218_mss_capture_backends "$d" "$list" || rc=1
    awk -F'|' 'NF==7{n++} END{exit(n==1?0:1)}' "$list" || rc=1
    _e218_mss_restore_backends "$list" || rc=1
    printf 'chain=1\njump=1\nrule=1\ndirect=0\n' >"$state"
    E218_MOCK_FAIL_DELETE=1 _e216_mss_apply_backend iptables >/dev/null 2>&1 && rc=1 || true
    grep -Fqx 'chain=1' "$state" && grep -Fqx 'jump=1' "$state" || rc=1
    owner="$d/owner.env"
    {
        echo version=199e218; echo backend=iptables; echo "tool_path=$fake"
        echo "tool_identity=$fake"; echo family=ipv4; echo mode=clamp-to-pmtu; echo updated_epoch=1780000000
    } >"$owner"
    _e218_mss_owner_state_validate "$owner" || rc=1
    _e218_mss_build_script "$fake" "$fake" "$d/reconcile.sh" || rc=1
    grep -Fqx "IDENTITY=$(printf '%q' "$fake")" "$d/reconcile.sh" || rc=1
    sed -i 's/family=ipv4/family=ipv6/' "$owner"
    ! _e218_mss_owner_state_validate "$owner" || rc=1
    return "$rc"
)

_e218_structure_audit() {
    local rc=0 menu mtu_menu installer paths preflight hot_verify mtu_persist mtu_commit
    local mss_apply mss_disable uninstaller dispatchers mtu_line mss_line smallbbr_line
    _e214_structure_audit >/dev/null || rc=1
    menu=$(declare -f _e214_main_menu 2>/dev/null || true)
    mtu_menu=$(declare -f _e214_mtu_menu 2>/dev/null || true)
    installer=$(declare -f _e214_install_self 2>/dev/null || true)
    paths=$(declare -f _e138_system_paths 2>/dev/null || true)
    preflight=$(declare -f _e214_hot_update_preflight 2>/dev/null || true)
    hot_verify=$(declare -f _e214_hot_verify 2>/dev/null || true)
    mtu_persist=$(declare -f _e214_mtu_persistence_validate 2>/dev/null || true)
    mtu_commit=$(declare -f _e214_mtu_commit 2>/dev/null || true)
    mss_apply=$(declare -f _e216_mss_apply_backend 2>/dev/null || true)
    mss_disable=$(declare -f _e218_mss_disable 2>/dev/null || true)
    uninstaller=$(declare -f do_uninstall 2>/dev/null || true)
    mtu_line=$(grep -n '_e214_mtu_any_state' <<<"$uninstaller" | head -n 1 | cut -d: -f1 || true)
    mss_line=$(grep -n '_e218_mss_any_evidence' <<<"$uninstaller" | head -n 1 | cut -d: -f1 || true)
    smallbbr_line=$(grep -n '_e202_small_bbr_active' <<<"$uninstaller" | head -n 1 | cut -d: -f1 || true)
    dispatchers=$(grep -c '^# V199e218 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true)
    echo 'V199e218 structure audit:'
    test "$SCRIPT_VERSION" = 199e218 && test "$E218_VERSION" = 199e218 || rc=1
    test "$E216_VERSION" = 199e216 || rc=1
    test "$dispatchers" -eq 1 || rc=1
    ! LC_ALL=C grep -q $'\r' "$SCRIPT_PATH" || rc=1
    grep -q 'V199e218 - 事务稳态版' <<<"$menu" || rc=1
    grep -q '热更新到 V199e218' <<<"$menu" || rc=1
    grep -q '27) 宿主机网卡 MTU' <<<"$menu" || rc=1
    grep -q 'MTU=1350' <<<"$mtu_menu" || rc=1
    grep -q '_e214_mtu_set_interactive auto - 1350' <<<"$mtu_menu" || rc=1
    grep -q 'E218_SELF_PATH' <<<"$installer" || rc=1
    grep -q 'E218_MSS_OWNER_STATE' <<<"$paths" || rc=1
    grep -q '_e218_structure_audit' <<<"$preflight" || rc=1
    grep -q '_e218_mss_consistency' <<<"$preflight" || rc=1
    grep -q '_e218_mss_consistency' <<<"$hot_verify" || rc=1
    grep -q 'E214_SELF_PATH' <<<"$mtu_persist" || rc=1
    grep -q '_e214_mtu_current' <<<"$mtu_persist" || rc=1
    grep -q 'systemctl start.*E214_MTU_UNIT' <<<"$mtu_commit" || rc=1
    grep -q '_e216_mss_cleanup_backend.*|| return 1' <<<"$mss_apply" || rc=1
    grep -q '_e218_mss_capture_control' <<<"$mss_disable" || rc=1
    grep -q '_e218_mss_capture_backends' <<<"$mss_disable" || rc=1
    grep -q '_e218_mss_rollback' <<<"$mss_disable" || rc=1
    grep -q '_e218_mss_consistency' <<<"$mss_disable" || rc=1
    [[ "$mtu_line" =~ ^[0-9]+$ && "$mss_line" =~ ^[0-9]+$ && "$smallbbr_line" =~ ^[0-9]+$ ]] || rc=1
    if [[ "$mtu_line" =~ ^[0-9]+$ && "$mss_line" =~ ^[0-9]+$ && "$smallbbr_line" =~ ^[0-9]+$ ]]; then
        ((mtu_line < smallbbr_line && mss_line < smallbbr_line)) || rc=1
    fi
    grep -q 'xray-before-uninstall-e218-' <<<"$uninstaller" || rc=1
    grep -q 'E218卸载任一阶段' <<<"$uninstaller" || rc=1
    for f in _e218_mss_enable _e218_mss_disable _e218_mss_status \
        _e218_mss_build_script _e218_mss_verify_on _e218_mss_verify_off _e218_mss_consistency \
        _e218_mss_mock_self_test; do
        declare -F "$f" >/dev/null 2>&1 || rc=1
    done
    grep -Fq -- '--e218-summary)' "$SCRIPT_PATH" || rc=1
    grep -Fq -- '--mss-status)' "$SCRIPT_PATH" || rc=1
    if test "$rc" -eq 0; then echo '  result=PASS'; else echo '  result=FAIL'; fi
    return "$rc"
}

_e218_self_test() {
    local rc=0
    _e214_self_test || rc=1
    _e216_mss_self_test && echo '  [PASS] E216 compatibility state/script/unit invariants' \
      || { echo '  [FAIL] E216 compatibility MSS invariant'; rc=1; }
    _e218_mss_mock_self_test && echo '  [PASS] E218 strict cleanup/apply/backend-pin mock transaction' \
      || { echo '  [FAIL] E218 MSS mock transaction'; rc=1; }
    _e218_structure_audit >/dev/null && echo '  [PASS] E218 MTU1350/MSS/hot-update final bindings' \
      || { echo '  [FAIL] E218 final binding'; rc=1; }
    if test "$rc" -eq 0; then echo 'V199e218 result: PASS'; else echo 'V199e218 result: FAIL'; fi
    return "$rc"
}

_e218_help() {
    cat <<'EOF_E218_HELP'
V199e218:
  --hot-update                         事务热更新到E218
  --summary                            导出节点URI、一次终端QR及PNG/SVG
  --network-audit                      只读网络参数/重复定义审计
  --full-network-apply                 事务应用完整127条请求
  --small-bbr-menu                     八个精确14/25/26项档位菜单
  --small-bbr-enable|status|disable    启用、读回或恢复小BBR
  --mtu-menu|--mtu-status              宿主机MTU事务；菜单内含1350快捷档
  --mtu-reconcile|--mtu-disable        立即复检/恢复首次接管前MTU
  --mss-status                         只读核对MSS、MTU、后端、规则和持久服务
  --mss-enable|--mss-disable           菜单10→7同一套IPv4动态MSS事务
  --ipv6-disable|enable|status         IPv6永久策略（无IPv4时默认拒绝关闭）
  --warp-menu|--warp-global-menu       Xray层定向/全局WARP
  --warp-full-menu                     Cloudflare系统全隧道
  --micro-menu                         完整28项微操中心
  --structure-audit|--self-test        E218最终绑定审计/离线发布门禁
  --uninstall                          受控卸载（先恢复各事务基线）

推荐工作流：
  新装：安装/新建节点 -> 菜单10→6→第28项 -> 重启 -> 小BBR。
  升级：必须先用当前旧脚本 --small-bbr-disable 并读回恢复，
        再下载/热更新E218，最后重新启用小BBR。新版不猜旧快照。
  MTU：仅在确认有隧道封装、PMTU黑洞或大包卡顿时使用菜单27的1350档；
       1350不是DDoS/暴力破解防护。

MTU与MSS：MTU=1350时无选项头的名义IPv4 MSS约1310。MSS Clamp只改
新TCP握手中的MSS通告，不改网卡MTU，不影响UDP；第28项和小BBR不会
暗中开关MSS。E218对MSS做固定后端、规则快照、失败回滚和OFF残留读回。
EOF_E218_HELP
}

#==============================================================================
# V199e230 FINAL CORRECTION LAYER
#
# E214 remains the stable host-MTU ABI and E216/E218 remain the compatible MSS
# state/unit ABI.  E220 adds durable MSS transaction evidence, ordered rollback,
# a recovery entry, an MTU-disable lock, and the final release bindings.
#==============================================================================
readonly E220_VERSION="199e230"
readonly E220_DIR="$CONFIG_DIR/e220"
readonly E220_SELF_PATH="$SCRIPT_DIR/ex199e220.sh"
readonly E220_MSS_TX_ROOT="/var/backups/xray-mss-e220"
readonly E220_MSS_CRITICAL_MARKER="$E220_DIR/MSS_CRITICAL_RECOVERY_REQUIRED.env"
readonly E220_MSS_AUDIT="$LOG_DIR/e220/mss-last.log"
E220_INTERNAL_SELF_TEST=0
E220_INTERNAL_SELF_TEST_TMP=""

_e220_secure_private_dir() {
    local dir="${1:-}"
    test -n "$dir" || return 1
    if test -e "$dir" || test -L "$dir"; then
        test -d "$dir" && test ! -L "$dir" || {
            error "拒绝使用非目录或符号链接：$dir"
            return 1
        }
        test "$(stat -c '%u' "$dir" 2>/dev/null || true)" = 0 || {
            error "专用事务目录不属于root：$dir"
            return 1
        }
        chmod 0700 "$dir" || return 1
    else
        install -d -o 0 -g 0 -m 0700 -- "$dir" || return 1
    fi
    test -d "$dir" && test ! -L "$dir" \
      && test "$(stat -c '%a:%u:%g' "$dir" 2>/dev/null || true)" = 700:0:0
}

_e220_mss_tx_root() {
    if test "${E220_INTERNAL_SELF_TEST:-0}" = 1 \
      && test -n "${E220_INTERNAL_SELF_TEST_TMP:-}"; then
        printf '%s\n' "$E220_INTERNAL_SELF_TEST_TMP/tx"
    else
        printf '%s\n' "$E220_MSS_TX_ROOT"
    fi
}

_e220_prepare() {
    local root
    if test "${E220_INTERNAL_SELF_TEST:-0}" != 1; then
        _e218_prepare || return 1
        _e220_secure_private_dir "$E220_DIR" || return 1
    fi
    root=$(_e220_mss_tx_root) || return 1
    _e220_secure_private_dir "$root"
}

_e218_mss_log() {
    local log="$E220_MSS_AUDIT"
    if test "${E220_INTERNAL_SELF_TEST:-0}" = 1 \
      && test -n "${E220_INTERNAL_SELF_TEST_TMP:-}"; then
        log="$E220_INTERNAL_SELF_TEST_TMP/mss-last.log"
    fi
    install -d -m 0750 "$(dirname -- "$log")" 2>/dev/null || return 0
    printf '%s %s\n' "$(date '+%F %T %z')" "$*" >>"$log" 2>/dev/null || true
}

_e220_mss_tx_real() {
    local requested="${1:-}" root_path root real parent
    test -n "$requested" || return 1
    root_path=$(_e220_mss_tx_root) || return 1
    test -d "$root_path" && test ! -L "$root_path" || return 1
    test -d "$requested" && test ! -L "$requested" || return 1
    root=$(readlink -f -- "$root_path" 2>/dev/null || true)
    real=$(readlink -f -- "$requested" 2>/dev/null || true)
    test -n "$root" && test -d "$root" && test ! -L "$root" \
      && test -n "$real" && test -d "$real" && test ! -L "$real" || return 1
    parent=$(dirname -- "$real") || return 1
    test "$parent" = "$root" || return 1
    printf '%s\n' "$real"
}

_e220_mss_new_tx() {
    local purpose="${1:-mss}" root d start owner_pid=""
    owner_pid=$(_e230_tx_owner_pid) || return 1
    _e220_prepare || return 1
    root=$(_e220_mss_tx_root) || return 1
    purpose=$(printf '%s' "$purpose" | tr -cd 'A-Za-z0-9._-' | cut -c1-40)
    test -n "$purpose" || purpose=mss
    d="$root/${purpose}-$(date +%Y%m%d_%H%M%S)-${owner_pid}-$RANDOM"
    install -d -o 0 -g 0 -m 0700 -- "$d" || return 1
    start=$(_e214_proc_start_time "$owner_pid" 2>/dev/null || true)
    [[ "$start" =~ ^[0-9]+$ ]] || { rmdir -- "$d" 2>/dev/null || true; return 1; }
    {
        printf 'version=%s\n' "$E220_VERSION"
        printf 'pid=%s\n' "$owner_pid"
        printf 'start=%s\n' "$start"
        printf 'purpose=%s\n' "$purpose"
        printf 'created_epoch=%s\n' "$(date +%s)"
    } >"$d/.active.env" || return 1
    chmod 0600 "$d/.active.env" || return 1
    printf 'created\n' >"$d/.phase" || return 1
    chmod 0600 "$d/.phase" || return 1
    _e214_prune_root "$root" "$E220_MSS_CRITICAL_MARKER" \
      || warn 'E220 MSS旧事务未能全部收敛；当前事务仍保守继续。' 1>&2
    printf '%s\n' "$d"
}

_e220_mss_set_phase() {
    local d phase="${2:-}" real tmp
    real=$(_e220_mss_tx_real "${1:-}") || return 1
    case "$phase" in
        created|control-ready|triggers-stopped|backends-ready|mutation-started|committed|rolled-back) ;;
        *) return 1 ;;
    esac
    tmp="$real/.phase.tmp.$$"
    printf '%s\n' "$phase" >"$tmp" && chmod 0600 "$tmp" \
      && mv -f -- "$tmp" "$real/.phase"
}

_e220_mss_tx_close() {
    local real result="${2:-closed}" tmp
    real=$(_e220_mss_tx_real "${1:-}") || return 1
    result=$(printf '%s' "$result" | tr -cd 'A-Za-z0-9._-' | cut -c1-48)
    test -n "$result" || result=closed
    tmp="$real/.closed.env.tmp.$$"
    {
        printf 'version=%s\n' "$E220_VERSION"
        printf 'result=%s\n' "$result"
        printf 'closed_epoch=%s\n' "$(date +%s)"
    } >"$tmp" && chmod 0600 "$tmp" && mv -f -- "$tmp" "$real/.closed.env" \
      && rm -f -- "$real/.active.env"
}

_e220_mss_preserve_tx() {
    local real reason="${2:-manual-recovery-required}" tmp
    real=$(_e220_mss_tx_real "${1:-}") || return 1
    reason=$(printf '%s' "$reason" | tr '\r\n' '  ')
    tmp="$real/.preserve.env.tmp.$$"
    {
        printf 'version=%s\n' "$E220_VERSION"
        printf 'time=%s\n' "$(date '+%F %T %z')"
        printf 'reason=%s\n' "$reason"
    } >"$tmp" && chmod 0600 "$tmp" && mv -f -- "$tmp" "$real/.preserve.env"
}

_e220_mss_mark_critical() {
    local d="${1:-}" reason="${2:-MSS rollback/readback failed}" real tmp phase
    real=$(_e220_mss_tx_real "$d") || return 1
    phase=$(cat "$real/.phase" 2>/dev/null || echo unknown)
    reason=$(printf '%s' "$reason" | tr '\r\n' '  ')
    _e220_mss_preserve_tx "$real" "$reason" || true
    _e220_prepare || return 1
    test ! -L "$E220_MSS_CRITICAL_MARKER" || return 1
    tmp=$(mktemp --tmpdir="$E220_DIR" .mss-critical.XXXXXX) || return 1
    {
        printf 'version=%s\n' "$E220_VERSION"
        printf 'time=%s\n' "$(date '+%F %T %z')"
        printf 'operation=mss-transaction\n'
        printf 'backup=%s\n' "$real"
        printf 'phase=%s\n' "$phase"
        printf 'reason=%s\n' "$reason"
    } >"$tmp" && chmod 0600 "$tmp" \
      && mv -f -- "$tmp" "$E220_MSS_CRITICAL_MARKER"
}

_e220_mss_tx_live() {
    local d="${1:-}" pid expected actual version pid_count start_count
    test -f "$d/.active.env" && test ! -L "$d/.active.env" || return 1
    pid_count=$(grep -c '^pid=' "$d/.active.env" 2>/dev/null || true)
    start_count=$(grep -c '^start=' "$d/.active.env" 2>/dev/null || true)
    test "$pid_count" -eq 1 && test "$start_count" -eq 1 || return 1
    version=$(sed -n 's/^version=//p' "$d/.active.env")
    pid=$(sed -n 's/^pid=//p' "$d/.active.env")
    expected=$(sed -n 's/^start=//p' "$d/.active.env")
    test "$version" = "$E220_VERSION" || return 1
    [[ "$pid" =~ ^[1-9][0-9]*$ && "$expected" =~ ^[0-9]+$ ]] || return 1
    kill -0 "$pid" 2>/dev/null || return 1
    actual=$(_e214_proc_start_time "$pid" 2>/dev/null || true)
    test -n "$actual" && test "$actual" = "$expected"
}

_e220_mss_unresolved_report() {
    local root path found=0 state active preserve
    root=$(_e220_mss_tx_root) || return 1
    if test -e "$E220_MSS_CRITICAL_MARKER" || test -L "$E220_MSS_CRITICAL_MARKER"; then
        found=1
        echo "  [critical] $E220_MSS_CRITICAL_MARKER"
        if test -f "$E220_MSS_CRITICAL_MARKER" && test ! -L "$E220_MSS_CRITICAL_MARKER"; then
            sed -n '1,20s/^/      /p' "$E220_MSS_CRITICAL_MARKER" 2>/dev/null || true
        else
            echo '      marker=invalid-or-symlink'
        fi
    fi
    if test -e "$root" || test -L "$root"; then
        if ! test -d "$root" || test -L "$root"; then
            echo "  [invalid-root] $root"
            return 1
        fi
    else
        test "$found" -eq 0
        return
    fi
    while IFS= read -r -d '' path; do
        test -n "$path" || continue
        if test -L "$path"; then
            found=1
            echo "  [invalid-transaction-link] $path"
            continue
        fi
        active="$path/.active.env"; preserve="$path/.preserve.env"
        if test -e "$active" || test -L "$active"; then
            found=1; state=invalid
            if test -f "$active" && test ! -L "$active"; then
                state=stale
                _e220_mss_tx_live "$path" && state=live || true
            fi
            echo "  [${state}-active] $path"
        fi
        if test -e "$preserve" || test -L "$preserve"; then
            found=1
            if test -f "$preserve" && test ! -L "$preserve" && test -s "$preserve"; then
                echo "  [preserved] $path"
            else
                echo "  [invalid-preserve] $path"
            fi
        fi
    done < <(find "$root" -mindepth 1 -maxdepth 1 \( -type d -o -type l \) -print0 2>/dev/null | LC_ALL=C sort -z)
    test "$found" -eq 0
}

_e220_mss_preflight_readonly() {
    if _e220_mss_unresolved_report >/dev/null 2>&1; then
        return 0
    fi
    error 'E220检测到未关闭或受保护的MSS事务；拒绝覆盖恢复证据。'
    _e220_mss_unresolved_report 1>&2 || true
    error '请先运行 --mss-recover，或依据 --recovery-status 中的快照人工恢复。'
    return 1
}

# Keep the final script path in outer hot-update snapshots.  The E220 critical
# marker and MSS transaction root are deliberately outside this list so an
# outer rollback cannot erase evidence from a failed inner rollback.
if declare -F _e138_system_paths >/dev/null 2>&1; then
    eval "$(declare -f _e138_system_paths | sed '1s/_e138_system_paths/_e220_system_paths_base/')"
fi
_e138_system_paths() {
    _e220_system_paths_base "$@"
    printf '%s\n' "$E220_SELF_PATH"
}

_e214_recovery_markers() {
    printf '%s\t%s\n' E204 "$E204_CRITICAL_MARKER"
    printf '%s\t%s\n' E206 "$E214_LEGACY_E206_CRITICAL_MARKER"
    printf '%s\t%s\n' E208 "$E214_LEGACY_E208_CRITICAL_MARKER"
    printf '%s\t%s\n' E210 "$E214_LEGACY_E210_CRITICAL_MARKER"
    printf '%s\t%s\n' E212 "$E214_LEGACY_E212_CRITICAL_MARKER"
    printf '%s\t%s\n' E214 "$E214_CRITICAL_MARKER"
    printf '%s\t%s\n' E220-MSS "$E220_MSS_CRITICAL_MARKER"
}

_e214_prune_transactions() {
    local rc=0
    _e214_prune_root "$E214_TX_ROOT" "$E214_CRITICAL_MARKER" || rc=1
    _e214_prune_root "$E214_LEGACY_E212_TX_ROOT" "$E214_LEGACY_E212_CRITICAL_MARKER" || rc=1
    _e214_prune_root "$E214_LEGACY_E210_TX_ROOT" "$E214_LEGACY_E210_CRITICAL_MARKER" || rc=1
    _e214_prune_root "$E214_LEGACY_E208_TX_ROOT" "$E214_LEGACY_E208_CRITICAL_MARKER" || rc=1
    _e214_prune_root "$E214_LEGACY_E206_TX_ROOT" "$E214_LEGACY_E206_CRITICAL_MARKER" || rc=1
    _e214_prune_root "$(_e220_mss_tx_root)" "$E220_MSS_CRITICAL_MARKER" || rc=1
    return "$rc"
}

# E218 omitted the same lock used by MTU apply/reconcile from MTU disable.
# Run the inherited body inside a subshell so fd 207 is always closed.
if declare -F _e214_mtu_disable >/dev/null 2>&1; then
    eval "$(declare -f _e214_mtu_disable | sed '1s/_e214_mtu_disable/_e220_mtu_disable_unlocked/')"
fi
_e214_mtu_disable() (
    _e214_ensure_run_lock || return 1
    exec 207>/run/lock/xray-mtu-e214.lock || return 1
    flock -n 207 || { error '已有MTU应用/复检/退出事务正在运行。'; return 1; }
    _e220_mtu_disable_unlocked "$@"
)

# Historical E159 wrapped the same action selector twice under the identical
# "_e159_choose_banaction_base" name.  The second capture therefore called
# itself forever for every non-nft backend.  Keep one non-recursive final
# selector for nft, iptables, UFW and firewalld and bind all compatibility
# names to it.
_e220_choose_banaction_for_backend() {
    local backend="${1:-}" action_dir="${2:-/etc/fail2ban/action.d}" a
    test -d "$action_dir" && test ! -L "$action_dir" || return 1
    case "$backend" in
        nft)
            command -v nft >/dev/null 2>&1 || return 1
            test -f "$action_dir/nftables.conf" && test ! -L "$action_dir/nftables.conf" || return 1
            printf '%s\n' "$E165_F2B_ACTION_ID"
            ;;
        iptables)
            test -f "$action_dir/iptables-multiport.conf" \
              && test ! -L "$action_dir/iptables-multiport.conf" || return 1
            printf '%s\n' iptables-multiport
            ;;
        ufw)
            if test -f "$action_dir/ufw.conf" && test ! -L "$action_dir/ufw.conf"; then
                printf '%s\n' ufw
            elif command -v nft >/dev/null 2>&1 \
              && test -f "$action_dir/nftables.conf" && test ! -L "$action_dir/nftables.conf"; then
                printf '%s\n' "$E165_F2B_ACTION_ID"
            elif test -f "$action_dir/iptables-multiport.conf" \
              && test ! -L "$action_dir/iptables-multiport.conf"; then
                printf '%s\n' iptables-multiport
            else
                return 1
            fi
            ;;
        firewalld)
            for a in firewallcmd-rich-rules firewallcmd-multiport firewallcmd-allports; do
                if test -f "$action_dir/$a.conf" && test ! -L "$action_dir/$a.conf"; then
                    printf '%s\n' "$a"
                    return 0
                fi
            done
            if command -v nft >/dev/null 2>&1 \
              && test -f "$action_dir/nftables.conf" && test ! -L "$action_dir/nftables.conf"; then
                printf '%s\n' "$E165_F2B_ACTION_ID"
            else
                return 1
            fi
            ;;
        *) return 1 ;;
    esac
}
_e152_choose_banaction_for_backend() { _e220_choose_banaction_for_backend "$@"; }
_e159_choose_banaction_base() { _e220_choose_banaction_for_backend "$@"; }
_e165_choose_banaction_base() { _e220_choose_banaction_for_backend "$@"; }

_e220_fail2ban_action_self_test() (
    local d actions actual rc=0
    d=$(mktemp -d /tmp/xray-e220-f2b-action.XXXXXX) || return 1
    trap 'rm -rf -- "${d:-}"' EXIT
    actions="$d/actions"
    mkdir -p "$actions" "$d/bin" || return 1
    : >"$actions/iptables-multiport.conf"
    : >"$actions/ufw.conf"
    : >"$actions/firewallcmd-rich-rules.conf"
    : >"$actions/nftables.conf"
    printf '#!/usr/bin/env bash\nexit 0\n' >"$d/bin/nft"
    chmod 0755 "$d/bin/nft"
    PATH="$d/bin:$PATH"
    actual=$(_e152_choose_banaction_for_backend iptables "$actions" 2>/dev/null || true)
    test "$actual" = iptables-multiport || rc=1
    actual=$(_e152_choose_banaction_for_backend ufw "$actions" 2>/dev/null || true)
    test "$actual" = ufw || rc=1
    actual=$(_e152_choose_banaction_for_backend firewalld "$actions" 2>/dev/null || true)
    test "$actual" = firewallcmd-rich-rules || rc=1
    actual=$(_e152_choose_banaction_for_backend nft "$actions" 2>/dev/null || true)
    test "$actual" = "$E165_F2B_ACTION_ID" || rc=1
    ! _e152_choose_banaction_for_backend none "$actions" >/dev/null 2>&1 || rc=1
    return "$rc"
)

# A bare, exact TCPMSS rule is not automatically ours.  Older E68/E88 builds
# used that signature directly in POSTROUTING, but an administrator can create
# the same rule independently.  Only migrate it when the old ON state is the
# sole ownership evidence, there is no modern owner file/chain, and exactly
# one xtables ruleset contains the direct rule.  Otherwise leave it untouched.
_e220_mss_backend_has_managed() {
    local backend="${1:-}" tool rules
    tool=$(_e216_mss_tool_path "$backend") || return 2
    rules=$("$tool" -w 5 -t mangle -S 2>/dev/null) || return 2
    grep -Eq -- "(^-N $E216_MSS_CHAIN$|^-A [^ ]+( .*)? -j $E216_MSS_CHAIN$)" <<<"$rules"
}

_e220_mss_backend_has_direct() {
    local backend="${1:-}" tool
    tool=$(_e216_mss_tool_path "$backend") || return 2
    "$tool" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp \
      --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1
}

_e220_mss_legacy_direct_is_owned() {
    local requested="${1:-}" requested_identity candidate identity found="" rc
    local -A seen=()
    test "$(_e218_mss_owner_state 2>/dev/null || true)" = ON || return 1
    test ! -e "$E216_MSS_BACKEND_STATE" && test ! -L "$E216_MSS_BACKEND_STATE" || return 1
    test ! -e "$E218_MSS_OWNER_STATE" && test ! -L "$E218_MSS_OWNER_STATE" || return 1
    requested_identity=$(_e218_mss_backend_identity "$requested" 2>/dev/null || true)
    test -n "$requested_identity" || return 1
    while IFS= read -r candidate; do
        identity=$(_e218_mss_backend_identity "$candidate" 2>/dev/null || true)
        test -n "$identity" && test -z "${seen[$identity]+x}" || continue
        seen[$identity]=1
        _e220_mss_backend_has_managed "$candidate"; rc=$?
        test "$rc" -eq 1 || return 1
        _e220_mss_backend_has_direct "$candidate"; rc=$?
        case "$rc" in
            0)
                test -z "$found" || return 1
                found=$identity
                ;;
            1) ;;
            *) return 1 ;;
        esac
    done < <(_e216_mss_candidate_order)
    test -n "$found" && test "$found" = "$requested_identity"
}

# Final ownership predicate: our named chain is always managed; the historical
# direct rule is managed only under the uniquely provable migration case above.
_e218_mss_backend_has_owned() {
    local backend="${1:-}" rc
    _e220_mss_backend_has_managed "$backend"; rc=$?
    case "$rc" in 0) return 0 ;; 1) ;; *) return 2 ;; esac
    _e220_mss_backend_has_direct "$backend"; rc=$?
    case "$rc" in
        0) _e220_mss_legacy_direct_is_owned "$backend" && return 0 || return 1 ;;
        1) return 1 ;;
        *) return 2 ;;
    esac
}

# Runtime evidence must not claim an administrator's identical direct rule.
# Static ON state still makes a genuinely old E68/E88 rule discoverable.
_e218_mss_runtime_evidence() {
    local candidate identity rc
    local -A seen=()
    while IFS= read -r candidate; do
        identity=$(_e218_mss_backend_identity "$candidate" 2>/dev/null || true)
        test -n "$identity" && test -z "${seen[$identity]+x}" || continue
        seen[$identity]=1
        _e220_mss_backend_has_managed "$candidate"; rc=$?
        test "$rc" -eq 0 && return 0
    done < <(_e216_mss_candidate_order)
    return 1
}

# Remove only our named chain.  A bare direct rule is removed solely when the
# unique legacy-ownership proof succeeds; an unowned collision aborts before
# any mutation so the surrounding transaction can remain non-destructive.
_e216_mss_cleanup_backend() {
    local backend="${1:-}" tool line rc=0 direct_rc allow_direct=0
    tool=$(_e216_mss_tool_path "$backend") || return 1
    "$tool" -w 5 -t mangle -S >/dev/null 2>&1 || return 1
    _e220_mss_backend_has_direct "$backend"; direct_rc=$?
    case "$direct_rc" in
        0)
            if _e220_mss_legacy_direct_is_owned "$backend"; then
                allow_direct=1
            else
                error "后端 $backend 存在无E220所有权证据的裸TCPMSS规则；拒绝删除或覆盖。"
                return 1
            fi
            ;;
        1) ;;
        *) return 1 ;;
    esac
    if test "$allow_direct" -eq 1; then
        while "$tool" -w 5 -t mangle -D POSTROUTING -p tcp -m tcp \
          --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1; do :; done
    fi
    while "$tool" -w 5 -t mangle -D POSTROUTING -j "$E216_MSS_CHAIN" >/dev/null 2>&1; do :; done
    "$tool" -w 5 -t mangle -F "$E216_MSS_CHAIN" >/dev/null 2>&1 || true
    "$tool" -w 5 -t mangle -X "$E216_MSS_CHAIN" >/dev/null 2>&1 || true
    while IFS= read -r line; do
        [[ "$line" == *"-j $E216_MSS_CHAIN"* ]] && rc=1
    done < <("$tool" -w 5 -t mangle -S POSTROUTING 2>/dev/null || true)
    "$tool" -w 5 -t mangle -S "$E216_MSS_CHAIN" >/dev/null 2>&1 && rc=1 || true
    if test "$allow_direct" -eq 1; then
        _e220_mss_backend_has_direct "$backend" && rc=1 || test "$?" -eq 1 || rc=1
    fi
    return "$rc"
}

# The periodic reconciler must never erase an external direct TCPMSS rule.  It
# fails closed on a collision and lets status/health checks expose the drift.
_e218_mss_build_script() {
    local tool_path="${1:-}" tool_identity="${2:-}" out="${3:-}" actual
    [[ "$tool_path" =~ ^/[A-Za-z0-9_./+-]+$ ]] && test -x "$tool_path" || return 1
    [[ "$tool_identity" =~ ^/[A-Za-z0-9_./+-]+$ ]] \
      && test -x "$tool_identity" && test ! -L "$tool_identity" || return 1
    actual=$(readlink -f -- "$tool_path" 2>/dev/null || true)
    test "$actual" = "$tool_identity" && test -n "$out" && test ! -L "$out" || return 1
    cat >"$out" <<EOF_E220_MSS_SCRIPT
#!/usr/bin/env bash
set -Eeuo pipefail
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
IPT=$(printf '%q' "$tool_path")
IDENTITY=$(printf '%q' "$tool_identity")
CHAIN=$E216_MSS_CHAIN
test -x "\$IPT"
test "\$(readlink -f -- "\$IPT" 2>/dev/null || true)" = "\$IDENTITY"
modprobe iptable_mangle >/dev/null 2>&1 || true
modprobe xt_TCPMSS >/dev/null 2>&1 || true
if "\$IPT" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1; then
    echo 'unowned direct TCPMSS rule collision; refusing destructive reconcile' >&2
    exit 73
fi
while "\$IPT" -w 5 -t mangle -D POSTROUTING -j "\$CHAIN" >/dev/null 2>&1; do :; done
"\$IPT" -w 5 -t mangle -F "\$CHAIN" >/dev/null 2>&1 || true
"\$IPT" -w 5 -t mangle -X "\$CHAIN" >/dev/null 2>&1 || true
"\$IPT" -w 5 -t mangle -N "\$CHAIN"
"\$IPT" -w 5 -t mangle -A "\$CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu
"\$IPT" -w 5 -t mangle -I POSTROUTING 1 -j "\$CHAIN"
"\$IPT" -w 5 -t mangle -C POSTROUTING -j "\$CHAIN"
"\$IPT" -w 5 -t mangle -C "\$CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu
! "\$IPT" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1
EOF_E220_MSS_SCRIPT
    chmod 0755 "$out" || return 1
    bash -n "$out" || return 1
    grep -Fqx "IPT=$(printf '%q' "$tool_path")" "$out" \
      && grep -Fqx "IDENTITY=$(printf '%q' "$tool_identity")" "$out" \
      && grep -Fq 'exit 73' "$out" \
      && ! grep -Fq -- '-D POSTROUTING -p tcp' "$out"
}

_e220_mss_unowned_direct_report() {
    local candidate identity rc found=0
    local -A seen=()
    while IFS= read -r candidate; do
        identity=$(_e218_mss_backend_identity "$candidate" 2>/dev/null || true)
        test -n "$identity" && test -z "${seen[$identity]+x}" || continue
        seen[$identity]=1
        _e220_mss_backend_has_direct "$candidate"; rc=$?
        if test "$rc" -eq 0 && ! _e220_mss_legacy_direct_is_owned "$candidate"; then
            warn "检测到外部裸TCPMSS规则，E220未接管也不会删除：backend=$candidate real=$identity"
            found=1
        fi
    done < <(_e216_mss_candidate_order)
    return "$found"
}

_e220_mss_capture_control() {
    local d="${1:-}" path snap unit
    test -n "$d" && test -d "$d" && test ! -L "$d" || return 1
    install -d -m 0700 "$d/control" || return 1
    : >"$d/control/manifest" || return 1
    chmod 0600 "$d/control/manifest" || return 1
    for path in "$E88_MSS_STATE_FILE" "$E216_MSS_BACKEND_STATE" "$E218_MSS_OWNER_STATE" \
        "$E216_MSS_SCRIPT" "$E216_MSS_SERVICE" "$E216_MSS_TIMER"; do
        if test -e "$path" || test -L "$path"; then
            test -f "$path" && test ! -L "$path" || {
                error "MSS控制文件类型异常，拒绝快照：$path"
                return 1
            }
        fi
        snap="$d/control/$(printf '%s' "$path" | sha256sum | awk '{print $1}')"
        _e135_snapshot_file "$path" "$snap" || return 1
        printf '%s|%s\n' "$path" "$snap" >>"$d/control/manifest" || return 1
    done
    : >"$d/control/services.env" || return 1
    chmod 0600 "$d/control/services.env" || return 1
    for unit in "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT"; do
        _e204_service_snapshot "$unit" >>"$d/control/services.env" || return 1
    done
    (
        cd "$d/control" || exit 1
        find . -maxdepth 1 -type f ! -name control.sha256 -print0 \
          | LC_ALL=C sort -z | xargs -0 sha256sum >control.sha256
        test -s control.sha256 && chmod 0600 control.sha256
    )
}

_e220_mss_control_validate() {
    local d="${1:-}" path snap expected count=0 unit load enabled active
    local -A seen=()
    test -d "$d/control" && test ! -L "$d/control" \
      && test -f "$d/control/control.sha256" && test ! -L "$d/control/control.sha256" \
      && test -s "$d/control/control.sha256" || return 1
    test -z "$(find "$d/control" -mindepth 1 -maxdepth 1 -type l -print -quit 2>/dev/null)" || return 1
    (cd "$d/control" && sha256sum -c control.sha256 >/dev/null 2>&1) || return 1
    while IFS='|' read -r path snap; do
        case "$path" in
            "$E88_MSS_STATE_FILE"|"$E216_MSS_BACKEND_STATE"|"$E218_MSS_OWNER_STATE"|\
            "$E216_MSS_SCRIPT"|"$E216_MSS_SERVICE"|"$E216_MSS_TIMER") ;;
            *) return 1 ;;
        esac
        test -z "${seen[$path]+x}" || return 1
        seen[$path]=1; count=$((count + 1))
        expected="$d/control/$(printf '%s' "$path" | sha256sum | awk '{print $1}')"
        test "$snap" = "$expected" || return 1
        if test -f "$snap.present" && test ! -L "$snap.present"; then
            test ! -e "$snap.absent" && test ! -L "$snap.absent" || return 1
        elif test -f "$snap.absent" && test ! -L "$snap.absent"; then
            test ! -e "$snap.present" && test ! -L "$snap.present" || return 1
        else
            return 1
        fi
    done <"$d/control/manifest"
    test "$count" -eq 6 || return 1
    count=0; unset seen; declare -A seen=()
    while IFS='|' read -r unit load enabled active; do
        case "$unit" in "$E216_MSS_SERVICE_UNIT"|"$E216_MSS_TIMER_UNIT") ;; *) return 1 ;; esac
        test -z "${seen[$unit]+x}" || return 1
        seen[$unit]=1; count=$((count + 1))
        test -n "$load" && test -n "$enabled" && test -n "$active" || return 1
    done <"$d/control/services.env"
    test "$count" -eq 2
}

_e220_mss_restore_control_files() {
    local d="${1:-}" path snap rc=0
    _e220_mss_control_validate "$d" || return 1
    while IFS='|' read -r path snap; do
        _e135_restore_file "$path" "$snap" || rc=1
    done <"$d/control/manifest"
    systemctl daemon-reload >/dev/null 2>&1 || rc=1
    return "$rc"
}

_e220_mss_restore_control_services() {
    local d="${1:-}"
    _e220_mss_control_validate "$d" || return 1
    _e204_services_restore_file "$d/control/services.env"
}

_e220_mss_control_matches() {
    local d="${1:-}" path snap rc=0
    _e220_mss_control_validate "$d" || return 1
    while IFS='|' read -r path snap; do
        _e214_snapshot_matches "$path" "$snap" || rc=1
    done <"$d/control/manifest"
    return "$rc"
}

_e220_mss_signature() {
    local backend="${1:-}" tool
    tool=$(_e216_mss_tool_path "$backend") || return 1
    "$tool" -w 5 -t mangle -S 2>/dev/null \
      | awk -v chain="$E216_MSS_CHAIN" '
          $0 == "-N " chain || index($0,"-A " chain " ")==1 ||
          index($0," -j " chain) ||
          $0 == "-A POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu" {print}
        ' | LC_ALL=C sort
}

# E220/E222/E224/E226 snapshots omitted the rule *inside* XRAY_MSS_CLAMP
# from their compact signature.  Recovery must remain compatible with those
# durable snapshots, while newly created E230 snapshots cover the chain body.
_e230_mss_signature_legacy() {
    local backend="${1:-}" tool
    tool=$(_e216_mss_tool_path "$backend") || return 1
    "$tool" -w 5 -t mangle -S 2>/dev/null \
      | awk -v chain="$E216_MSS_CHAIN" '
          $0 == "-N " chain || index($0," -j " chain) ||
          $0 == "-A POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu" {print}
        ' | LC_ALL=C sort
}

_e220_mss_normalize_rules() {
    local file="${1:-}"
    test -f "$file" && test ! -L "$file" || return 1
    # iptables-save emits wall-clock comments which necessarily differ after
    # restore.  Everything else, including table and rule order, is retained.
    sed -e '/^# Generated by .* on /d' -e '/^# Completed on /d' "$file"
}

_e220_mss_capture_backends() {
    local d="${1:-}" list="${2:-}" backend identity save save_identity
    local restore restore_identity snapshot sig normalized tmp
    _e218_mss_capture_backends "$d" "$list" || return 1
    chmod 0600 "$list" || return 1
    while IFS='|' read -r backend identity save save_identity restore restore_identity snapshot; do
        sig="$snapshot.mss"
        normalized="$snapshot.normalized"
        _e220_mss_signature "$backend" >"$sig" || return 1
        _e220_mss_normalize_rules "$snapshot" >"$normalized" || return 1
        chmod 0600 "$snapshot" "$sig" "$normalized" || return 1
    done <"$list"
    tmp="$d/backends.sha256.tmp.$$"
    {
        sha256sum "$list" || exit 1
        while IFS='|' read -r backend identity save save_identity restore restore_identity snapshot; do
            sha256sum "$snapshot" "$snapshot.mss" "$snapshot.normalized" || exit 1
        done <"$list"
    } >"$tmp" || { rm -f -- "$tmp"; return 1; }
    chmod 0600 "$tmp" && mv -f -- "$tmp" "$d/backends.sha256"
}

_e220_mss_backends_validate() {
    local d="${1:-}" list="${2:-}" backend identity save save_identity
    local restore restore_identity snapshot count=0 real sig normalized
    local -A seen=()
    test "$list" = "$d/backends.tsv" && test -f "$list" && test ! -L "$list" \
      && test -s "$list" && test -f "$d/backends.sha256" \
      && test ! -L "$d/backends.sha256" && test -s "$d/backends.sha256" || return 1
    sha256sum -c "$d/backends.sha256" >/dev/null 2>&1 || return 1
    while IFS='|' read -r backend identity save save_identity restore restore_identity snapshot; do
        _e216_mss_backend_valid "$backend" || return 1
        test -z "${seen[$identity]+x}" || return 1
        seen[$identity]=1; count=$((count + 1))
        case "$snapshot" in "$d"/firewall-[0-9]*.rules) ;; *) return 1 ;; esac
        real=$(readlink -f -- "$snapshot" 2>/dev/null || true)
        case "$real" in "$d"/firewall-[0-9]*.rules) ;; *) return 1 ;; esac
        sig="$snapshot.mss"
        normalized="$snapshot.normalized"
        test -f "$snapshot" && test ! -L "$snapshot" && test -s "$snapshot" \
          && test -f "$sig" && test ! -L "$sig" \
          && test -f "$normalized" && test ! -L "$normalized" || return 1
        _e218_mss_backend_identity_matches "$backend" "$identity" || return 1
        test "$(_e218_mss_path_identity "$save" 2>/dev/null || true)" = "$save_identity" || return 1
        test "$(_e218_mss_path_identity "$restore" 2>/dev/null || true)" = "$restore_identity" || return 1
    done <"$list"
    test "$count" -gt 0
}

_e220_mss_restore_backends() {
    local d="${1:-}" list="${2:-}" i backend identity save save_identity
    local restore restore_identity snapshot rc=0 current current_rules current_normalized
    local -a rows=()
    _e220_mss_backends_validate "$d" "$list" || return 1
    mapfile -t rows <"$list" || return 1
    for ((i=${#rows[@]}-1; i>=0; i--)); do
        IFS='|' read -r backend identity save save_identity restore restore_identity snapshot <<<"${rows[$i]}"
        _e218_mss_backend_identity_matches "$backend" "$identity" \
          && test "$(_e218_mss_path_identity "$save" 2>/dev/null || true)" = "$save_identity" \
          && test "$(_e218_mss_path_identity "$restore" 2>/dev/null || true)" = "$restore_identity" \
          && "$restore" <"$snapshot" >/dev/null 2>&1 || rc=1
    done
    _e220_mss_backends_match "$d" "$list"
}

_e220_mss_backends_match() {
    local d="${1:-}" list="${2:-}" i backend identity save save_identity
    local restore restore_identity snapshot rc=0 current
    local -a rows=()
    # Full normalized snapshots remain integrity-sealed recovery payloads, but
    # equality is intentionally scoped to MSS-owned objects so unrelated
    # fail2ban/Docker/firewall churn cannot create a false critical rollback.
    declare -F _e220_mss_normalize_rules >/dev/null 2>&1 || return 1
    _e220_mss_backends_validate "$d" "$list" || return 1
    mapfile -t rows <"$list" || return 1
    for ((i=0; i<${#rows[@]}; i++)); do
        IFS='|' read -r backend identity save save_identity restore restore_identity snapshot <<<"${rows[$i]}"
        current="$d/.mss-signature-$i.tmp"
        if grep -Fq -- "-A $E216_MSS_CHAIN " "$snapshot.mss" 2>/dev/null; then
            _e220_mss_signature "$backend" >"$current" 2>/dev/null || rc=1
        else
            _e230_mss_signature_legacy "$backend" >"$current" 2>/dev/null || rc=1
        fi
        test "$rc" -ne 0 || cmp -s "$snapshot.mss" "$current" || rc=1
        rm -f -- "$current"
    done
    return "$rc"
}

_e220_mss_rollback() {
    local d="${1:-}" list="${2:-}" phase="${3:-unknown}" rc=0
    case "$phase" in
        created)
            # The phase is advanced before triggers are stopped or rules are
            # touched.  A crash in snapshot construction therefore requires
            # no system rollback and must not create a false critical alarm.
            _e220_mss_set_phase "$d" rolled-back
            return
            ;;
        control-ready|triggers-stopped|backends-ready|mutation-started|committed) ;;
        *) return 1 ;;
    esac
    _e218_mss_stop_triggers || rc=1
    _e220_mss_restore_control_files "$d" || rc=1
    case "$phase" in
        backends-ready|mutation-started|committed)
            _e220_mss_restore_backends "$d" "$list" || rc=1
            ;;
    esac
    _e220_mss_restore_control_services "$d" || rc=1
    case "$phase" in
        backends-ready|mutation-started|committed)
            # Starting a restored timer/service can immediately touch the
            # ruleset.  Read it back again after service-state restoration.
            _e220_mss_backends_match "$d" "$list" || rc=1
            ;;
    esac
    _e220_mss_control_matches "$d" || rc=1
    if test "$rc" -eq 0; then
        _e220_mss_set_phase "$d" rolled-back || rc=1
    fi
    test "$rc" -eq 0 || error "MSS持久事务回滚未完全通过：$d"
    return "$rc"
}

_e218_mss_enable() (
    local d="" list="" row backend="" candidate identity save save_identity
    local restore restore_identity snapshot tool_path="" tool_identity="" attempt=0
    local service_c timer_c rc=0 snapshot_ready=0 finished=0 phase=created
    _e220_mss_exit_guard() {
        local status="${1:-1}" rollback_rc=0
        trap - EXIT HUP INT TERM
        if test "$finished" -eq 0 && test "$snapshot_ready" -eq 1 && test -n "$d"; then
            phase=$(cat "$d/.phase" 2>/dev/null || echo unknown)
            if _e220_mss_rollback "$d" "$list" "$phase"; then
                _e218_mss_log "action=enable result=failed rollback=ok snapshot=$d phase=$phase"
                info "MSS启用失败已恢复操作前控制文件、规则与服务；快照：$d"
                _e220_mss_tx_close "$d" rolled-back || rollback_rc=1
            else
                rollback_rc=1
            fi
            if test "$rollback_rc" -ne 0; then
                _e220_mss_mark_critical "$d" 'MSS enable rollback/readback failed' || true
                _e220_mss_tx_close "$d" critical >/dev/null 2>&1 || true
                _e218_mss_log "action=enable result=critical snapshot=$d phase=$phase"
                error "严重：MSS启用回滚未完整通过；已保留持久快照：$d"
            fi
        elif test "$finished" -eq 0 && test -n "$d"; then
            _e220_mss_tx_close "$d" no-mutation >/dev/null 2>&1 || true
        fi
        [[ "$status" =~ ^[0-9]+$ ]] || status=1
        test "$status" -ne 0 || status=1
        exit "$status"
    }
    trap '_e220_mss_exit_guard $?' EXIT
    trap 'exit 129' HUP
    trap 'exit 130' INT
    trap 'exit 143' TERM
    _e220_mss_preflight_readonly || return 1
    _e220_prepare || return 1
    test -d /run/systemd/system || { error 'systemd未运行，不能安全持久化MSS Clamp。'; return 1; }
    _e214_ensure_run_lock || return 1
    exec 209>"$E218_MSS_LOCK" || return 1
    flock -n 209 || { error '已有MSS Clamp事务正在运行。'; return 1; }
    _e220_mss_preflight_readonly || return 1
    d=$(_e220_mss_new_tx enable) || return 1
    list="$d/backends.tsv"
    _e220_mss_capture_control "$d" || return 1
    snapshot_ready=1; phase=control-ready
    _e220_mss_set_phase "$d" "$phase" || return 1
    _e218_mss_stop_triggers || { error '旧MSS定时器/服务未能停止。'; return 1; }
    phase=triggers-stopped; _e220_mss_set_phase "$d" "$phase" || return 1
    _e220_mss_capture_backends "$d" "$list" || {
        error '没有可安全快照、固定实体并恢复的IPv4 xtables后端。'
        return 1
    }
    phase=backends-ready; _e220_mss_set_phase "$d" "$phase" || return 1
    phase=mutation-started; _e220_mss_set_phase "$d" "$phase" || return 1
    while IFS= read -r row; do
        IFS='|' read -r candidate identity save save_identity restore restore_identity snapshot <<<"$row"
        attempt=$((attempt + 1))
        if test "$attempt" -gt 1; then
            _e220_mss_restore_backends "$d" "$list" || break
        fi
        _e218_mss_cleanup_captured "$list" || continue
        if _e216_mss_apply_backend "$candidate"; then
            backend=$candidate; tool_identity=$identity
            tool_path=$(_e216_mss_tool_path "$candidate") || break
            break
        fi
    done <"$list"
    test -n "$backend" && test -n "$tool_path" || {
        error 'MSS所有候选后端试写/读回失败。'
        return 1
    }
    service_c="$d/service"; timer_c="$d/timer"
    _e218_mss_build_script "$tool_path" "$tool_identity" "$d/script" || rc=1
    test "$rc" -ne 0 || _e216_mss_build_units "$service_c" "$timer_c" || rc=1
    test "$rc" -ne 0 || _e118_atomic_install "$d/script" "$E216_MSS_SCRIPT" 0755 || rc=1
    test "$rc" -ne 0 || _e118_atomic_install "$service_c" "$E216_MSS_SERVICE" 0644 || rc=1
    test "$rc" -ne 0 || _e118_atomic_install "$timer_c" "$E216_MSS_TIMER" 0644 || rc=1
    test "$rc" -ne 0 || _e216_mss_write_backend_state "$backend" || rc=1
    test "$rc" -ne 0 || _e218_mss_write_owner_state "$backend" "$tool_path" "$tool_identity" || rc=1
    test "$rc" -ne 0 || _e216_mss_write_legacy_state ON || rc=1
    test "$rc" -ne 0 || systemctl daemon-reload >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || systemctl enable "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT" >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || systemctl start "$E216_MSS_SERVICE_UNIT" >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || systemctl start "$E216_MSS_TIMER_UNIT" >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || _e218_mss_verify_on || rc=1
    test "$rc" -ne 0 || _e218_mss_captured_exclusive "$list" "$backend" || rc=1
    test "$rc" -eq 0 || {
        error 'MSS规则、固定后端、状态、服务或唯一性读回失败。'
        return 1
    }
    phase=committed; _e220_mss_set_phase "$d" "$phase" || return 1
    _e220_mss_tx_close "$d" committed || return 1
    finished=1
    trap - EXIT HUP INT TERM
    _e218_mss_log "action=enable result=ok backend=$backend tool=$tool_path identity=$tool_identity snapshot=$d"
    info "IPv4 MSS Clamp已验证：backend=$backend（实体已固定），5分钟复检，快照=$d"
    warn '作用域是宿主机全部IPv4 TCP新握手（包含Xray和转发流量），不是仅Xray；UDP/IPv6不受影响。'
)

_e218_mss_disable() (
    local d="" list="" evidence=0 state rc=0 path unit
    local snapshot_ready=0 finished=0 phase=created
    _e220_mss_exit_guard() {
        local status="${1:-1}" rollback_rc=0
        trap - EXIT HUP INT TERM
        if test "$finished" -eq 0 && test "$snapshot_ready" -eq 1 && test -n "$d"; then
            phase=$(cat "$d/.phase" 2>/dev/null || echo unknown)
            if _e220_mss_rollback "$d" "$list" "$phase"; then
                _e218_mss_log "action=disable result=failed rollback=ok snapshot=$d phase=$phase"
                info "MSS关闭失败已恢复操作前控制文件、规则与服务；快照：$d"
                _e220_mss_tx_close "$d" rolled-back || rollback_rc=1
            else
                rollback_rc=1
            fi
            if test "$rollback_rc" -ne 0; then
                _e220_mss_mark_critical "$d" 'MSS disable rollback/readback failed' || true
                _e220_mss_tx_close "$d" critical >/dev/null 2>&1 || true
                _e218_mss_log "action=disable result=critical snapshot=$d phase=$phase"
                error "严重：MSS关闭回滚未完整通过；已保留持久快照：$d"
            fi
        elif test "$finished" -eq 0 && test -n "$d"; then
            _e220_mss_tx_close "$d" no-mutation >/dev/null 2>&1 || true
        fi
        [[ "$status" =~ ^[0-9]+$ ]] || status=1
        test "$status" -ne 0 || status=1
        exit "$status"
    }
    trap '_e220_mss_exit_guard $?' EXIT
    trap 'exit 129' HUP
    trap 'exit 130' INT
    trap 'exit 143' TERM
    _e220_mss_preflight_readonly || return 1
    _e220_prepare || return 1
    _e218_mss_any_evidence && evidence=1 || true
    if test "$evidence" -eq 0; then
        finished=1; trap - EXIT HUP INT TERM
        info 'IPv4 MSS Clamp未启用，也未发现可读残留。'
        return 0
    fi
    test -d /run/systemd/system || { error 'systemd未运行，拒绝声称已完整关闭MSS。'; return 1; }
    _e214_ensure_run_lock || return 1
    exec 209>"$E218_MSS_LOCK" || return 1
    flock -n 209 || { error '已有MSS Clamp事务正在运行。'; return 1; }
    _e220_mss_preflight_readonly || return 1
    d=$(_e220_mss_new_tx disable) || return 1
    list="$d/backends.tsv"
    _e220_mss_capture_control "$d" || return 1
    snapshot_ready=1; phase=control-ready
    _e220_mss_set_phase "$d" "$phase" || return 1
    _e218_mss_stop_triggers || return 1
    phase=triggers-stopped; _e220_mss_set_phase "$d" "$phase" || return 1
    _e220_mss_capture_backends "$d" "$list" || return 1
    phase=backends-ready; _e220_mss_set_phase "$d" "$phase" || return 1
    phase=mutation-started; _e220_mss_set_phase "$d" "$phase" || return 1
    _e218_mss_cleanup_captured "$list" || rc=1
    test "$rc" -ne 0 || _e218_mss_captured_off "$list" || rc=1
    # Older E212/E220 installations can legitimately have already-lost unit
    # files.  systemctl then returns non-zero although the desired state is
    # already OFF.  Make stop/disable idempotent and let the strict enabled,
    # active, file and rules readback below be the only success criterion.
    test "$rc" -ne 0 || _e230_mss_disable_units_idempotent || rc=1
    if test "$rc" -eq 0; then
        rm -f -- "$E216_MSS_SERVICE" "$E216_MSS_TIMER" "$E216_MSS_SCRIPT" \
            "$E216_MSS_BACKEND_STATE" "$E218_MSS_OWNER_STATE" || rc=1
    fi
    test "$rc" -ne 0 || systemctl daemon-reload >/dev/null 2>&1 || rc=1
    test "$rc" -ne 0 || _e216_mss_write_legacy_state OFF || rc=1
    if test "$rc" -eq 0; then
        for unit in "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT"; do
            systemctl is-active --quiet "$unit" 2>/dev/null && rc=1 || true
            systemctl is-enabled --quiet "$unit" 2>/dev/null && rc=1 || true
        done
        for path in "$E216_MSS_SERVICE" "$E216_MSS_TIMER" "$E216_MSS_SCRIPT" \
            "$E216_MSS_BACKEND_STATE" "$E218_MSS_OWNER_STATE"; do
            test ! -e "$path" && test ! -L "$path" || rc=1
        done
        _e218_mss_captured_off "$list" || rc=1
        _e218_mss_consistency || rc=1
    fi
    test "$rc" -eq 0 || {
        error 'MSS关闭后的脚本自有规则、状态、文件或systemd读回失败。'
        for unit in "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT"; do
            printf '    unit=%s load=%s enabled=%s active=%s\n' "$unit" \
                "$(systemctl show "$unit" -p LoadState --value 2>/dev/null || echo unknown)" \
                "$(systemctl is-enabled "$unit" 2>/dev/null || true)" \
                "$(systemctl is-active "$unit" 2>/dev/null || true)" >&2
        done
        return 1
    }
    state=$(_e218_mss_owner_state) || return 1
    phase=committed; _e220_mss_set_phase "$d" "$phase" || return 1
    _e220_mss_tx_close "$d" committed || return 1
    finished=1
    trap - EXIT HUP INT TERM
    _e218_mss_log "action=disable result=ok state=$state snapshot=$d"
    info "IPv4 MSS Clamp已关闭：所有快照后端、服务、定时器、脚本与状态均已读回；快照=$d"
)

_e220_mss_select_recovery_tx() {
    local root backup="" marker="$E220_MSS_CRITICAL_MARKER"
    root=$(_e220_mss_tx_root) || return 1
    if test -e "$marker" || test -L "$marker"; then
        test -f "$marker" && test ! -L "$marker" && test -r "$marker" && test -s "$marker" || return 1
        backup=$(awk -F= '$1=="backup"{n++;v=substr($0,index($0,"=")+1)}END{if(n==1)print v;else exit 1}' "$marker") || return 1
        _e220_mss_tx_real "$backup"
        return
    fi
    test -d "$root" && test ! -L "$root" || return 1
    backup=$(find "$root" -mindepth 1 -maxdepth 1 -type d \
        \( -exec test -f '{}/.active.env' \; -o -exec test -f '{}/.preserve.env' \; \) \
        -printf '%T@\t%p\n' 2>/dev/null | LC_ALL=C sort -nr | head -n1 | cut -f2-)
    test -n "$backup" || return 1
    _e220_mss_tx_real "$backup"
}

_e220_mss_recover() (
    local force="${1:-}" d locked phase list answer rc=0
    if _e220_mss_unresolved_report >/dev/null 2>&1; then
        info '没有可恢复的E220 MSS事务。'
        return 0
    fi
    d=$(_e220_mss_select_recovery_tx 2>/dev/null || true)
    test -n "$d" || {
        error '存在MSS恢复证据，但事务路径或关键标记无效；拒绝声称没有快照。'
        _e220_mss_unresolved_report 1>&2 || true
        return 1
    }
    if _e220_mss_tx_live "$d"; then
        error "MSS事务进程仍存活，拒绝并发恢复：$d"
        return 1
    fi
    phase=$(cat "$d/.phase" 2>/dev/null || echo unknown)
    list="$d/backends.tsv"
    if test "$force" != force; then
        warn "将从持久快照恢复MSS控制文件、所有已快照xtables后端和systemd状态：$d"
        read -rp '输入 RECOVER-MSS 确认: ' answer || true
        test "$answer" = RECOVER-MSS || { info '已取消。'; return 0; }
    fi
    _e214_ensure_run_lock || return 1
    exec 209>"$E218_MSS_LOCK" || return 1
    flock -n 209 || { error '已有MSS Clamp事务正在运行。'; return 1; }
    # Close the select/lock race: another recovery may have completed or a
    # different critical marker may now own the recovery decision.
    locked=$(_e220_mss_select_recovery_tx 2>/dev/null || true)
    if test -z "$locked"; then
        info 'MSS事务已由另一进程恢复。'
        return 0
    fi
    test "$locked" = "$d" || {
        error "MSS恢复目标在加锁前发生变化：before=$d after=$locked"
        return 1
    }
    if _e220_mss_tx_live "$d"; then
        error "MSS事务进程仍存活，拒绝并发恢复：$d"
        return 1
    fi
    phase=$(cat "$d/.phase" 2>/dev/null || echo unknown)
    list="$d/backends.tsv"
    if test "$phase" = created; then
        _e220_mss_tx_close "$d" no-mutation-recovered || return 1
        rm -f -- "$d/.preserve.env"
        if test -f "$E220_MSS_CRITICAL_MARKER" && test ! -L "$E220_MSS_CRITICAL_MARKER"; then
            rm -f -- "$E220_MSS_CRITICAL_MARKER"
        fi
        info "未发生系统修改的中断MSS事务已关闭：$d"
        return 0
    fi
    _e220_mss_rollback "$d" "$list" "$phase" || rc=1
    if test "$rc" -eq 0; then
        _e220_mss_tx_close "$d" manual-recovery || rc=1
        rm -f -- "$d/.preserve.env" || rc=1
        if test -e "$E220_MSS_CRITICAL_MARKER" || test -L "$E220_MSS_CRITICAL_MARKER"; then
            test -f "$E220_MSS_CRITICAL_MARKER" && test ! -L "$E220_MSS_CRITICAL_MARKER" \
              && rm -f -- "$E220_MSS_CRITICAL_MARKER" || rc=1
        fi
    fi
    if test "$rc" -ne 0; then
        _e220_mss_mark_critical "$d" 'manual MSS recovery/readback failed' || true
        error "MSS手动恢复未完整通过；快照仍受保护：$d"
        return 1
    fi
    _e218_mss_log "action=recover result=ok snapshot=$d"
    info "MSS已从持久快照恢复并读回：$d"
)

if declare -F _e218_mss_status >/dev/null 2>&1; then
    eval "$(declare -f _e218_mss_status | sed '1s/_e218_mss_status/_e220_mss_status_base/')"
fi
_e218_mss_status() {
    local rc=0 unresolved=0
    if ! _e220_mss_unresolved_report >/dev/null 2>&1; then
        unresolved=1
        title 'V199e230：MSS未完成事务 / 恢复证据'
        _e220_mss_unresolved_report || true
        warn '存在未完成事务；请运行 --mss-recover，未恢复前不会覆盖快照。'
    fi
    _e220_mss_status_base "$@" || rc=$?
    _e220_mss_unowned_direct_report || true
    test "$unresolved" -eq 0 || rc=1
    return "$rc"
}

_e220_mss_menu_action() {
    local opt="" token=""
    while true; do
        clear
        title 'V199e230：IPv4 MSS Clamp 独立控制中心'
        echo '  1) 只读查看MTU、名义MSS、规则后端、持久服务与恢复证据'
        echo '  2) 启用动态 --clamp-mss-to-pmtu（宿主机全部IPv4 TCP握手）'
        echo '  3) 关闭并验证清理本脚本拥有的MSS规则/服务'
        echo '  4) 从E220持久快照恢复被中断的MSS事务'
        echo '  0) 返回'
        echo
        echo '  边界：不改网卡MTU，不处理UDP/IPv6，不只作用于Xray，也不能猜未知PMTU黑洞。'
        hr
        read -rp '操作: ' opt || true
        case "$opt" in
            1)
                _e218_mss_status || true
                _e116_pause
                ;;
            2)
                warn '该规则位于IPv4 POSTROUTING，会影响宿主机全部IPv4 TCP新握手。'
                read -rp '输入 APPLY-MSS-CLAMP 确认: ' token || true
                test "$token" = APPLY-MSS-CLAMP && _e218_mss_enable || true
                _e116_pause
                ;;
            3)
                read -rp '输入 DISABLE-MSS-CLAMP 确认: ' token || true
                test "$token" = DISABLE-MSS-CLAMP && _e218_mss_disable || true
                _e116_pause
                ;;
            4)
                _e220_mss_recover || true
                _e116_pause
                ;;
            0) return 0 ;;
            *) warn '无效操作。'; sleep 1 ;;
        esac
    done
}

# Retained historical menu entries use the same safe E220 center instead of
# the old ambiguous "1=ON, 0=OFF" prompt.
_e88_manual_mss_clamp() { _e220_mss_menu_action "$@"; }

# Remove two older outer MSS wrappers.  The E220 inner transaction already
# snapshots every owned control file and every readable backend, and keeping an
# outer snapshot could erase E220's critical marker after an inner rollback
# failure.
_e168_mss_action() { _e220_mss_menu_action "$@"; }
_e170_mss_action() { _e220_mss_menu_action "$@"; }

_e220_mss_tx_self_test() (
    local d tx order list rules normalized link script true_identity rc=0
    d=$(mktemp -d /tmp/xray-e220-mss-selftest.XXXXXX) || return 1
    trap 'rm -rf -- "${d:-}"' EXIT
    E220_INTERNAL_SELF_TEST=1
    E220_INTERNAL_SELF_TEST_TMP="$d"
    tx=$(_e220_mss_new_tx selftest) || return 1
    case "$tx" in "$d/tx/"*) ;; *) rc=1 ;; esac
    test -s "$tx/.active.env" && test "$(cat "$tx/.phase")" = created || rc=1
    ! _e220_mss_preflight_readonly >/dev/null 2>&1 || rc=1
    _e220_mss_tx_close "$tx" selftest || rc=1
    test ! -e "$tx/.active.env" && test -s "$tx/.closed.env" || rc=1
    _e220_mss_preflight_readonly >/dev/null 2>&1 || rc=1

    # A created phase precedes every system mutation.  It must be safely
    # closable even if snapshot construction was interrupted halfway.
    tx=$(_e220_mss_new_tx created-only) || return 1
    list="$tx/backends.tsv"
    _e220_mss_rollback "$tx" "$list" created || rc=1
    test "$(cat "$tx/.phase")" = rolled-back || rc=1
    _e220_mss_tx_close "$tx" created-selftest || rc=1

    # Only direct, real children of the private transaction root are valid.
    mkdir "$tx/nested" || rc=1
    ! _e220_mss_tx_real "$tx/nested" >/dev/null 2>&1 || rc=1
    link="$d/tx/transaction-link"
    ln -s "$tx" "$link" || rc=1
    ! _e220_mss_tx_real "$link" >/dev/null 2>&1 || rc=1
    rm -f -- "$link"

    rules="$d/rules.save"; normalized="$d/rules.normalized"
    {
        echo '# Generated by iptables-save v1.8.9 on Fri Aug 21 00:00:00 2026'
        echo '*filter'; echo ':INPUT ACCEPT [0:0]'; echo COMMIT
        echo '# Completed on Fri Aug 21 00:00:00 2026'
    } >"$rules"
    _e220_mss_normalize_rules "$rules" >"$normalized" || rc=1
    test "$(paste -sd, "$normalized")" = '*filter,:INPUT ACCEPT [0:0],COMMIT' || rc=1

    script="$d/reconcile.sh"
    true_identity=$(_e218_mss_path_identity /bin/true 2>/dev/null || true)
    test -n "$true_identity" \
      && _e218_mss_build_script /bin/true "$true_identity" "$script" || rc=1
    grep -Fq 'unowned direct TCPMSS rule collision' "$script" || rc=1
    grep -Fq 'exit 73' "$script" || rc=1
    ! grep -Fq -- '-D POSTROUTING -p tcp' "$script" || rc=1

    mkdir "$d/tx/invalid-marker" || rc=1
    ln -s /dev/null "$d/tx/invalid-marker/.active.env" || rc=1
    ! _e220_mss_preflight_readonly >/dev/null 2>&1 || rc=1
    rm -f -- "$d/tx/invalid-marker/.active.env"
    rmdir -- "$d/tx/invalid-marker" || rc=1
    _e220_mss_preflight_readonly >/dev/null 2>&1 || rc=1

    tx=$(_e220_mss_new_tx rollback-order) || return 1
    list="$tx/backends.tsv"; : >"$list"; chmod 0600 "$list"
    order="$d/order"; : >"$order"
    _e218_mss_stop_triggers() { echo stop >>"$order"; }
    _e220_mss_restore_control_files() { echo files >>"$order"; }
    _e220_mss_restore_backends() { echo backends >>"$order"; }
    _e220_mss_restore_control_services() { echo services >>"$order"; }
    _e220_mss_backends_match() { echo backend-match >>"$order"; }
    _e220_mss_control_matches() { echo matches >>"$order"; }
    _e220_mss_rollback "$tx" "$list" mutation-started || rc=1
    test "$(paste -sd, "$order")" = stop,files,backends,services,backend-match,matches || rc=1
    test "$(cat "$tx/.phase")" = rolled-back || rc=1
    _e220_mss_tx_close "$tx" rollback-selftest || rc=1
    case "$E220_MSS_TX_ROOT" in /var/backups/*) ;; *) rc=1 ;; esac
    return "$rc"
)

_e220_structure_audit() {
    local rc=0 menu help installer hot_pre hot_verify mtu_disable small_enable
    local mss_enable mss_disable mss_rollback mss_status mss_menu legacy_mss uninstaller dispatchers
    local mss_builder mss_cleanup stop_line files_line backends_line services_line post_match_line
    _e214_structure_audit >/dev/null || rc=1
    menu=$(declare -f _e214_main_menu 2>/dev/null || true)
    help=$(declare -f _e220_help 2>/dev/null || true)
    installer=$(declare -f _e214_install_self 2>/dev/null || true)
    hot_pre=$(declare -f _e214_hot_update_preflight 2>/dev/null || true)
    hot_verify=$(declare -f _e214_hot_verify 2>/dev/null || true)
    mtu_disable=$(declare -f _e214_mtu_disable 2>/dev/null || true)
    small_enable=$(declare -f _e202_small_bbr_enable 2>/dev/null || true)
    mss_enable=$(declare -f _e218_mss_enable 2>/dev/null || true)
    mss_disable=$(declare -f _e218_mss_disable 2>/dev/null || true)
    mss_rollback=$(declare -f _e220_mss_rollback 2>/dev/null || true)
    mss_status=$(declare -f _e218_mss_status 2>/dev/null || true)
    mss_menu=$(declare -f _e220_mss_menu_action 2>/dev/null || true)
    legacy_mss=$(declare -f _e88_manual_mss_clamp 2>/dev/null || true)
    uninstaller=$(declare -f do_uninstall 2>/dev/null || true)
    mss_builder=$(declare -f _e218_mss_build_script 2>/dev/null || true)
    mss_cleanup=$(declare -f _e216_mss_cleanup_backend 2>/dev/null || true)
    dispatchers=$(grep -c '^# V199e230 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true)
    echo 'V199e230 structure audit:'
    test "$SCRIPT_VERSION" = 199e230 && test "$E214_VERSION" = 199e230 \
      && test "$E220_VERSION" = 199e230 || rc=1
    test "$dispatchers" -eq 1 || rc=1
    ! LC_ALL=C grep -q $'\r' "$SCRIPT_PATH" || rc=1
    grep -q 'V199e230 - 事务稳态版' <<<"$menu" || rc=1
    grep -q '热更新到 V199e230' <<<"$menu" || rc=1
    grep -q '27) 宿主机网卡 MTU' <<<"$menu" || rc=1
    grep -q 'E220_SELF_PATH' <<<"$installer" || rc=1
    grep -q 'E220_SELF_PATH' <<<"$hot_verify" || rc=1
    grep -q '_e220_structure_audit' <<<"$hot_pre" || rc=1
    grep -q '_e220_mss_preflight_readonly' <<<"$hot_pre" || rc=1
    grep -q 'xray-mtu-e214.lock' <<<"$mtu_disable" || rc=1
    grep -q '_e220_mtu_disable_unlocked' <<<"$mtu_disable" || rc=1
    grep -q 'assignments.*-ge 25' <<<"$small_enable" || rc=1
    grep -q '26项档还会限制TIME_WAIT桶上限' <<<"$small_enable" || rc=1
    grep -q '_e220_mss_new_tx' <<<"$mss_enable" || rc=1
    grep -q '_e220_mss_new_tx' <<<"$mss_disable" || rc=1
    grep -q '_e230_mss_disable_units_idempotent' <<<"$mss_disable" || rc=1
    ! grep -q 'systemctl disable.*E216_MSS_TIMER_UNIT' <<<"$mss_disable" || rc=1
    ! grep -q 'mktemp -d /tmp/xray-e218-mss' <<<"$mss_enable$mss_disable" || rc=1
    grep -q '作用域是宿主机全部IPv4 TCP' <<<"$mss_enable" || rc=1
    grep -q '_e220_mss_unresolved_report' <<<"$mss_status" || rc=1
    grep -q 'APPLY-MSS-CLAMP' <<<"$mss_menu" || rc=1
    grep -q 'DISABLE-MSS-CLAMP' <<<"$mss_menu" || rc=1
    grep -q '_e220_mss_menu_action' <<<"$legacy_mss" || rc=1
    grep -q '_e220_mss_preflight_readonly' <<<"$uninstaller" || rc=1
    ! grep -q '1=ON.*0=OFF' <<<"$mss_menu$legacy_mss" || rc=1
    grep -q 'unowned direct TCPMSS rule collision' <<<"$mss_builder" || rc=1
    grep -q '_e220_mss_legacy_direct_is_owned' <<<"$mss_cleanup" || rc=1
    stop_line=$(grep -n '_e218_mss_stop_triggers' <<<"$mss_rollback" | head -n1 | cut -d: -f1 || true)
    files_line=$(grep -n '_e220_mss_restore_control_files' <<<"$mss_rollback" | head -n1 | cut -d: -f1 || true)
    backends_line=$(grep -n '_e220_mss_restore_backends' <<<"$mss_rollback" | head -n1 | cut -d: -f1 || true)
    services_line=$(grep -n '_e220_mss_restore_control_services' <<<"$mss_rollback" | head -n1 | cut -d: -f1 || true)
    post_match_line=$(grep -n '_e220_mss_backends_match' <<<"$mss_rollback" | tail -n1 | cut -d: -f1 || true)
    [[ "$stop_line" =~ ^[0-9]+$ && "$files_line" =~ ^[0-9]+$ \
      && "$backends_line" =~ ^[0-9]+$ && "$services_line" =~ ^[0-9]+$ ]] || rc=1
    if [[ "$stop_line" =~ ^[0-9]+$ && "$files_line" =~ ^[0-9]+$ \
      && "$backends_line" =~ ^[0-9]+$ && "$services_line" =~ ^[0-9]+$ \
      && "$post_match_line" =~ ^[0-9]+$ ]]; then
        ((stop_line < files_line && files_line < backends_line \
          && backends_line < services_line && services_line < post_match_line)) || rc=1
    else
        rc=1
    fi
    grep -q '新装：安装/新建节点' <<<"$help" || rc=1
    grep -q '升级：直接运行下载的E230并选择一键升级' <<<"$help" || rc=1
    grep -q '高防清洗/动态路由隐藏隧道' <<<"$help" || rc=1
    grep -Fq -- '--e220-summary)' "$SCRIPT_PATH" || rc=1
    grep -Fq -- '--mss-recover)' "$SCRIPT_PATH" || rc=1
    grep -q '_e220_mss_normalize_rules' <<<"$(declare -f _e220_mss_backends_match 2>/dev/null || true)" || rc=1
    grep -q 'created)' <<<"$(declare -f _e220_mss_rollback 2>/dev/null || true)" || rc=1
    for _e220_f in _e220_choose_banaction_for_backend _e220_fail2ban_action_self_test \
        _e220_mss_capture_control _e220_mss_capture_backends \
        _e220_mss_restore_backends _e220_mss_backends_match \
        _e220_mss_backend_has_managed _e220_mss_backend_has_direct \
        _e220_mss_legacy_direct_is_owned _e220_mss_rollback _e220_mss_recover \
        _e220_mss_normalize_rules _e220_mss_tx_self_test; do
        declare -F "$_e220_f" >/dev/null 2>&1 || rc=1
    done
    ! grep -q '_e159_choose_banaction_base' \
      <<<"$(declare -f _e220_choose_banaction_for_backend 2>/dev/null || true)" || rc=1
    if test "$rc" -eq 0; then echo '  result=PASS'; else echo '  result=FAIL'; fi
    return "$rc"
}

_e220_self_test() {
    local rc=0
    _e214_self_test || rc=1
    _e216_mss_self_test && echo '  [PASS] E216 compatibility MSS ABI' \
      || { echo '  [FAIL] E216 compatibility MSS ABI'; rc=1; }
    _e218_mss_mock_self_test && echo '  [PASS] E218 backend pin/cleanup mock' \
      || { echo '  [FAIL] E218 backend pin/cleanup mock'; rc=1; }
    _e220_fail2ban_action_self_test && echo '  [PASS] E220 non-recursive Fail2ban action selection' \
      || { echo '  [FAIL] E220 Fail2ban action selector'; rc=1; }
    _e220_mss_tx_self_test && echo '  [PASS] E220 durable MSS transaction/rollback order' \
      || { echo '  [FAIL] E220 durable MSS transaction'; rc=1; }
    _e220_structure_audit >/dev/null && echo '  [PASS] E220 final bindings/workflow gates' \
      || { echo '  [FAIL] E220 final binding'; rc=1; }
    if test "$rc" -eq 0; then echo 'V199e230 result: PASS'; else echo 'V199e230 result: FAIL'; fi
    return "$rc"
}

_e220_help() {
    cat <<'EOF_E220_HELP'
V199e230:
  --hot-update                         一键升级到E230（完成后不自动重启）
  --summary                            导出节点URI、一次终端QR及PNG/SVG
  --network-audit                      只读网络参数/重复定义审计
  --full-network-apply                 事务应用完整127条请求
  --small-bbr-menu                     八个精确14/25/26项档位菜单
  --small-bbr-enable|status|disable    启用、读回或恢复小BBR
  --mtu-menu|--mtu-status              宿主机MTU事务；菜单内含1350快捷档
  --mtu-reconcile|--mtu-disable        立即复检/恢复首次接管前MTU
  --mss-status                         只读核对MSS、MTU、后端、规则与恢复证据
  --mss-enable|--mss-disable           启用/关闭IPv4动态MSS Clamp
  --mss-recover                        从E220兼容持久快照恢复中断的MSS事务
  --ipv6-disable|enable|status         IPv6永久策略（无IPv4时默认拒绝关闭）
  --warp-menu|--warp-global-menu       Xray层定向/全局WARP
  --warp-full-menu                     Cloudflare系统全隧道
  --micro-menu                         完整28项微操中心
  --structure-audit|--self-test        E230最终绑定审计/离线发布门禁
  --uninstall                          受控卸载（先恢复各事务基线）

固定工作流：
  新装：安装/新建节点 -> 菜单10→6→第28项 -> 重启 -> 小BBR。
  升级：直接运行下载的E230并选择一键升级；它会调用当前已安装旧脚本
        安全退出活动小BBR，完成热更新/第28项后恢复原活动档位。
        MSS状态一致时原样保留；可验证旧事务自动恢复，脚本自有漂移
        自动事务收敛，不再要求先手工运行--mss-status/--mss-disable。
  MTU：商家因高防清洗/动态路由隐藏隧道而导致大包卡顿时，
       可使用菜单27的1350保守兼容档；它不是DDoS防御本身。

MSS边界：MTU=1350时无TCP选项头的名义IPv4 MSS约1310。
--clamp-mss-to-pmtu只缩小宿主机全部IPv4 POSTROUTING TCP新握手
（包含Xray，不是仅Xray），不改MTU、不处理UDP/IPv6，也不能猜出未知
PMTU黑洞。第28项、小BBR和MTU=1350都不会暗中开关MSS。
EOF_E220_HELP
}

#==============================================================================
# V199e230 ONE-CONFIRM UPGRADE / POST-NODE PROFILE RECONCILIATION LAYER
#==============================================================================
readonly E230_VERSION="199e230"
readonly E230_MAIN_PID="${BASHPID:-$$}"
readonly E230_DIR="$CONFIG_DIR/e230"
readonly E230_SELF_PATH="$SCRIPT_DIR/ex199e230.sh"
readonly E230_LEGACY_E228_SELF_PATH="$SCRIPT_DIR/ex199e228.sh"
readonly E230_LEGACY_E226_SELF_PATH="$SCRIPT_DIR/ex199e226.sh"
readonly E230_LEGACY_E224_SELF_PATH="$SCRIPT_DIR/ex199e224.sh"
readonly E230_LEGACY_E222_SELF_PATH="$SCRIPT_DIR/ex199e222.sh"
readonly E230_WORKFLOW_STATE="$E230_DIR/workflow.env"
readonly E230_AUTO_LOG="$LOG_DIR/e230/auto-upgrade-last.log"
readonly E230_TARGET_MTU="1350"
readonly E230_DEFAULT_SMALL_PROFILE="mode3f2"

_e230_tx_owner_pid() {
    local pid="${E230_MAIN_PID:-$$}"
    # Offline tests may run under an execution wrapper which retires the
    # launcher PID while a nested command substitution is still alive.  PID 1
    # is used only for the isolated /tmp self-test roots; production must bind
    # every activity marker to the real long-lived script process.
    if test "${E214_INTERNAL_SELF_TEST:-0}" = 1 \
      || test "${E220_INTERNAL_SELF_TEST:-0}" = 1 \
      || test "${E204_INTERNAL_SELF_TEST:-0}" = 1 \
      || test "${E230_INTERNAL_SELF_TEST:-0}" = 1; then
        pid=1
    fi
    [[ "$pid" =~ ^[1-9][0-9]*$ ]] && test -r "/proc/$pid/stat" || return 1
    printf '%s\n' "$pid"
}

_e230_prepare() {
    _e214_ensure_run_lock || return 1
    install -d -m 0700 "$E230_DIR" "$(dirname -- "$E230_AUTO_LOG")" || return 1
}

if declare -F _e138_system_paths >/dev/null 2>&1; then
    eval "$(declare -f _e138_system_paths | sed '1s/_e138_system_paths/_e230_system_paths_base/')"
fi
_e138_system_paths() {
    _e230_system_paths_base "$@"
    printf '%s\n' "$E230_DIR" "$E230_SELF_PATH" \
        "$E230_LEGACY_E228_SELF_PATH" "$E230_LEGACY_E226_SELF_PATH" \
        "$E230_LEGACY_E224_SELF_PATH" \
        "$E230_LEGACY_E222_SELF_PATH"
}

_e230_write_workflow_state() {
    local mode="${1:-full28}" tmp
    _e230_prepare || return 1
    tmp=$(_e118_mktemp e230-workflow) || return 1
    {
        echo 'managed=1'
        echo "release=$E230_VERSION"
        echo "profile=$mode"
        echo "updated_epoch=$(date +%s)"
    } >"$tmp" || { rm -f -- "$tmp"; return 1; }
    _e118_atomic_install "$tmp" "$E230_WORKFLOW_STATE" 0600
}

_e230_workflow_managed() {
    test -f "$E230_WORKFLOW_STATE" && test ! -L "$E230_WORKFLOW_STATE" \
      && grep -qx 'managed=1' "$E230_WORKFLOW_STATE" 2>/dev/null
}

# A successful manual menu-10/item-28 commit becomes durable intent.  Node
# rebuilds can then replay only its application half without disturbing the
# independently owned small-BBR, MTU, MSS, IPv6 or WARP layers.
if declare -F _e159_apply_micro_28 >/dev/null 2>&1; then
    eval "$(declare -f _e159_apply_micro_28 | sed '1s/_e159_apply_micro_28/_e230_micro28_base/')"
fi
_e159_apply_micro_28() {
    _e230_micro28_base "$@" || return 1
    _e230_write_workflow_state full28 || {
        error '第28项已生效，但工作流状态写入失败；拒绝宣称后续节点可自动继承。'
        return 1
    }
}
_e152_apply_micro_28() { _e159_apply_micro_28 "$@"; }

_e230_post_config_reconcile() {
    local was_active=0
    test -s "$CONFIG" && test -x "$XRAY_BIN" || return 0
    systemctl is-active --quiet xray.service 2>/dev/null && was_active=1
    _turn_on_app || return 1
    _e118_xray_test_config "$CONFIG" 1 || return 1
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    if test "$was_active" = 1; then
        systemctl restart xray.service >/dev/null 2>&1 || return 1
        _e127_verify_xray_runtime "$CONFIG" 12 || return 1
    elif systemctl is-active --quiet xray.service 2>/dev/null; then
        error '配置继承复检意外启动了原本停止的Xray。'
        return 1
    fi
    if test "$(_e138_state_get route_enabled 0)" = 1; then
        _e185_warp_health_check || return 1
    fi
    _e182_ipv6_hot_verify || return 1
    if _e202_small_bbr_active; then _e202_small_bbr_status >/dev/null || return 1; fi
    if _e214_mtu_any_state; then _e214_mtu_persistence_validate || return 1; fi
    _e218_mss_consistency || return 1
}

_e230_config_sha() {
    if test -f "$CONFIG" && test ! -L "$CONFIG"; then
        sha256sum "$CONFIG" 2>/dev/null | awk '{print $1}'
    else
        printf 'absent\n'
    fi
}

# Keep node/user output behind the final reconciliation gate.  This prevents a
# usable-looking QR from being printed and then invalidated by a later rollback.
if declare -F do_summary >/dev/null 2>&1; then
    eval "$(declare -f do_summary | sed '1s/do_summary/_e230_summary_base/')"
fi
do_summary() {
    if test "${E230_SUMMARY_SUPPRESS:-0}" = 1; then
        E230_SUMMARY_PENDING=1
        E183_SUMMARY_EMITTED=1
        return 0
    fi
    _e230_summary_base "$@"
}

_e230_restore_outer() {
    local snapshot="${1:-}" operation="${2:-operation}" rc=0 exact=""
    test -n "$snapshot" && test -d "$snapshot" || return 1
    _e214_hot_restore_readback "$snapshot" || rc=1
    if test -e "$snapshot/e230-mss-exact" || test -L "$snapshot/e230-mss-exact"; then
        exact="$snapshot/e230-mss-exact"
    elif test -e "$snapshot/e228-mss-exact" || test -L "$snapshot/e228-mss-exact"; then
        exact="$snapshot/e228-mss-exact"
    elif test -e "$snapshot/e226-mss-exact" || test -L "$snapshot/e226-mss-exact"; then
        exact="$snapshot/e226-mss-exact"
    fi
    if test -n "$exact"; then
        _e230_mss_outer_restore "$exact" || rc=1
    fi
    if test "$rc" -ne 0; then
        _e214_mark_critical "e230-$operation" "$snapshot" \
            'E230 outer rollback/readback failed (including exact MSS state)' || true
        error "严重：${operation}回滚未完整通过；必须保留快照：$snapshot"
        return 1
    fi
    info "${operation}失败，已恢复操作前完整状态；快照：$snapshot"
}

# Node creation can rebuild config.json.  If item 28 has ever been committed,
# replay its application settings after the inherited node/WARP/IPv6 gates and
# keep one additional snapshot alive until the final runtime readback.
if declare -F _e182_install_mode >/dev/null 2>&1; then
    eval "$(declare -f _e182_install_mode | sed '1s/_e182_install_mode/_e230_install_mode_base/')"
fi
_e230_install_mode_transaction() (
    local tx="" before="" after="" rc=0 managed=0 snapshot_ready=0 finished=0
    local E230_SUMMARY_SUPPRESS=0 E230_SUMMARY_PENDING=0
    _e230_node_exit_guard() {
        local status="${1:-1}"
        trap - EXIT HUP INT TERM
        if test "$snapshot_ready" -eq 1 && test "$finished" -eq 0 && test -n "$tx"; then
            error '节点事务意外中断，恢复进入节点操作前的完整状态。'
            _e230_restore_outer "$tx/system" node-interrupted || true
            _e214_tx_close "$tx" || true
            test "$status" -ne 0 || status=1
        elif test "$finished" -eq 0 && test -n "$tx"; then
            _e214_tx_close "$tx" || true
        fi
        [[ "$status" =~ ^[0-9]+$ ]] || status=1
        exit "$status"
    }
    trap '_e230_node_exit_guard $?' EXIT
    trap 'exit 129' HUP; trap 'exit 130' INT; trap 'exit 143' TERM
    _e230_workflow_managed && managed=1 || true
    test "$managed" -eq 0 || E230_SUMMARY_SUPPRESS=1
    tx=$(_e214_new_tx node-e230) || return 1
    _e140_system_snapshot "$tx/system" || return 1
    snapshot_ready=1
    before=$(_e230_config_sha)
    _e230_install_mode_base "$@" || rc=$?
    after=$(_e230_config_sha)
    if test "$rc" -eq 0 && test "$managed" -eq 1 && test "$before" != "$after"; then
        _e230_post_config_reconcile || rc=1
    fi
    if test "$rc" -eq 0 && test "$managed" -eq 1 && test "$before" != "$after"; then
        E230_SUMMARY_SUPPRESS=0
        E230_SUMMARY_PENDING=0
        do_summary || rc=1
    fi
    if test "$rc" -eq 0; then
        finished=1
        _e214_tx_close "$tx" || warn "新节点已生效，但事务活动标记未关闭：$tx"
        trap - EXIT HUP INT TERM
        return 0
    fi
    _e230_restore_outer "$tx/system" node-profile-reconcile || true
    finished=1
    _e214_tx_close "$tx" || true
    trap - EXIT HUP INT TERM
    return 1
)

_e182_install_mode() {
    if test "${E204_INTERNAL_SELF_TEST:-0}" = 1 \
      || test "${E214_INTERNAL_SELF_TEST:-0}" = 1; then
        _e230_install_mode_base "$@"
        return $?
    fi
    _e230_install_mode_transaction "$@"
}

# User-manager mutations are targeted jq edits, but a final profile/runtime
# gate prevents a future inherited implementation from silently dropping the
# application part of item 28.
if declare -F do_user_manager >/dev/null 2>&1; then
    eval "$(declare -f do_user_manager | sed '1s/do_user_manager/_e230_user_manager_base/')"
fi
_e230_user_manager_transaction() (
    local tx="" before="" after="" rc=0 managed=0 snapshot_ready=0 finished=0
    local E230_SUMMARY_SUPPRESS=0 E230_SUMMARY_PENDING=0
    _e230_user_exit_guard() {
        local status="${1:-1}"
        trap - EXIT HUP INT TERM
        if test "$snapshot_ready" -eq 1 && test "$finished" -eq 0 && test -n "$tx"; then
            error '用户事务意外中断，恢复进入用户管理前的完整状态。'
            _e230_restore_outer "$tx/system" user-manager-interrupted || true
            _e214_tx_close "$tx" || true
            test "$status" -ne 0 || status=1
        elif test "$finished" -eq 0 && test -n "$tx"; then
            _e214_tx_close "$tx" || true
        fi
        [[ "$status" =~ ^[0-9]+$ ]] || status=1
        exit "$status"
    }
    trap '_e230_user_exit_guard $?' EXIT
    trap 'exit 129' HUP; trap 'exit 130' INT; trap 'exit 143' TERM
    _e230_workflow_managed && managed=1 || true
    test "$managed" -eq 0 || E230_SUMMARY_SUPPRESS=1
    tx=$(_e214_new_tx user-manager-e230) || return 1
    _e140_system_snapshot "$tx/system" || return 1
    snapshot_ready=1
    before=$(_e230_config_sha)
    _e230_user_manager_base "$@" || rc=$?
    after=$(_e230_config_sha)
    if test "$rc" -eq 0 && test "$managed" -eq 1 && test "$before" != "$after"; then
        _e230_post_config_reconcile || rc=1
    fi
    if test "$rc" -eq 0 && test "$managed" -eq 1 && test "$before" != "$after"; then
        E230_SUMMARY_SUPPRESS=0
        E230_SUMMARY_PENDING=0
        do_summary || rc=1
    fi
    if test "$rc" -eq 0; then
        finished=1
        _e214_tx_close "$tx" || warn "用户修改已生效，但事务活动标记未关闭：$tx"
        trap - EXIT HUP INT TERM
        return 0
    fi
    _e230_restore_outer "$tx/system" user-profile-reconcile || true
    finished=1
    _e214_tx_close "$tx" || true
    trap - EXIT HUP INT TERM
    return 1
)

do_user_manager() {
    if test "${E204_INTERNAL_SELF_TEST:-0}" = 1 \
      || test "${E214_INTERNAL_SELF_TEST:-0}" = 1; then
        _e230_user_manager_base "$@"
        return $?
    fi
    _e230_user_manager_transaction "$@"
}

_e230_active_small_owner() {
    if _e202_small_bbr_active; then
        printf 'e202\n'
    else
        _e204_legacy_small_bbr_owner 2>/dev/null || true
    fi
}

_e230_installed_version() {
    local v="" real="" mode="" uid=""
    if test -L "$SYMLINK"; then
        real=$(readlink -f -- "$SYMLINK" 2>/dev/null || true)
        case "$real" in "$SCRIPT_DIR"/*) ;; *) return 1 ;; esac
    else
        real="$SYMLINK"
    fi
    test -f "$real" && test ! -L "$real" && test -x "$real" || return 1
    uid=$(stat -c %u "$real" 2>/dev/null || true)
    mode=$(stat -c %a "$real" 2>/dev/null || true)
    test "$uid" = 0 && [[ "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
    # Refuse a group/world-writable executable before asking it to restore the
    # only small-BBR baseline snapshot.
    (( (8#$mode & 0022) == 0 )) || return 1
    bash -n "$real" >/dev/null 2>&1 || return 1
    v=$("$SYMLINK" --version 2>/dev/null | tail -n1 | tr -d '[:space:]')
    [[ "$v" =~ ^(198|199)e[0-9]+$ ]] || return 1
    printf '%s\n' "$v"
}

# Return the exact root-owned executable which _e230_installed_version has
# already proved safe enough to execute.  Keeping this separate avoids using a
# mutable symlink after the version check (TOCTOU) during the old-owner handoff.
_e230_installed_script_real() {
    local real="" mode="" uid="" v=""
    if test -L "$SYMLINK"; then
        real=$(readlink -f -- "$SYMLINK" 2>/dev/null || true)
        case "$real" in "$SCRIPT_DIR"/*) ;; *) return 1 ;; esac
    else
        real="$SYMLINK"
    fi
    test -f "$real" && test ! -L "$real" && test -x "$real" || return 1
    uid=$(stat -c %u "$real" 2>/dev/null || true)
    mode=$(stat -c %a "$real" 2>/dev/null || true)
    test "$uid" = 0 && [[ "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
    (( (8#$mode & 0022) == 0 )) || return 1
    bash -n "$real" >/dev/null 2>&1 || return 1
    v=$("$real" --version 2>/dev/null | tail -n1 | tr -d '[:space:]')
    [[ "$v" =~ ^(198|199)e[0-9]+$ ]] || return 1
    printf '%s\n' "$real"
}

_e230_capture_active_small_profile() {
    local owner="${1:-}" out="${2:-}" raw=""
    test -n "$owner" && test -n "$out" || return 1
    case "$owner" in
        e202)
            _e202_small_bbr_validate_file "$E202_SMALL_CONF" || return 1
            cp -f -- "$E202_SMALL_CONF" "$out" || return 1
            ;;
        e200)
            raw=$(mktemp /tmp/xray-e230-e200-profile.XXXXXX) || return 1
            if ! _e202_capture_active_config 200 "$E202_LEGACY_E200_STATE" \
                "$E202_LEGACY_E200_CONF" "$raw" \
              || ! _e202_prepare_legacy_profile 200 "$raw" "$out"; then
                rm -f -- "$raw"
                return 1
            fi
            rm -f -- "$raw"
            ;;
        e198)
            raw=$(mktemp /tmp/xray-e230-e198-profile.XXXXXX) || return 1
            if ! _e202_capture_active_config 198 "$E202_LEGACY_E198_STATE" \
                "$E202_LEGACY_E198_CONF" "$raw" \
              || ! _e202_prepare_legacy_profile 198 "$raw" "$out"; then
                rm -f -- "$raw"
                return 1
            fi
            rm -f -- "$raw"
            ;;
        e196)
            raw=$(mktemp /tmp/xray-e230-e196-profile.XXXXXX) || return 1
            if ! _e202_capture_active_config 196 "$E202_LEGACY_E196_STATE" \
                "$E202_LEGACY_E196_CONF" "$raw" \
              || ! _e202_prepare_legacy_profile 196 "$raw" "$out"; then
                rm -f -- "$raw"
                return 1
            fi
            rm -f -- "$raw"
            ;;
        e194)
            _e202_capture_active_config 194 "$E202_LEGACY_E194_STATE" \
                "$E202_LEGACY_E194_CONF" "$out" || return 1
            ;;
        e190|e192)
            # E190/E192 have only 6/13 assignments and cannot be represented
            # losslessly by the current exact 14/25/26-line ABI.  Match the
            # user's established post-upgrade choice instead of silently
            # pretending that a different modern preset was the old profile.
            _e202_small_bbr_mode3f2 >"$out" || return 1
            info "${owner^^}旧档无法无损映射到八档ABI；安全退出旧层后将明确应用模式3F2。"
            ;;
        *) return 1 ;;
    esac
    _e202_small_bbr_validate_file "$out"
}

_e230_old_script_can_exit_owner() {
    local owner="${1:-}" version="${2:-}" generation=""
    generation=${version##*e}
    [[ "$generation" =~ ^[0-9]+$ ]] || return 1
    case "$owner" in
        e202) ((generation >= 202 && generation <= 230)) ;;
        e190|e192|e194|e196|e198|e200) test "$generation" = "${owner#e}" ;;
        *) return 1 ;;
    esac
}

_e230_old_small_bbr_disable() {
    local owner="${1:-}" expected_version="${2:-}" real="" actual_version=""
    local child_tmp="" rc=0
    real=$(_e230_installed_script_real) || {
        error '无法重新固定当前已安装旧脚本；未调用旧小BBR恢复点。'
        return 1
    }
    actual_version=$("$real" --version 2>/dev/null | tail -n1 | tr -d '[:space:]')
    test -n "$expected_version" && test "$actual_version" = "$expected_version" || {
        error "旧脚本在锁定前发生变化：expected=${expected_version:-missing} actual=${actual_version:-missing}"
        return 1
    }
    child_tmp=$(mktemp -d /tmp/xray-e230-old-owner.XXXXXX) || return 1
    chmod 0700 "$child_tmp" || { rm -rf -- "$child_tmp"; return 1; }

    # The downloaded E230 process already owns fd 9 / xrv-transactional.lock.
    # Executing the old CLI normally would make that child reopen fd 9 and
    # falsely diagnose its own parent as another xrv instance.  Source the
    # already validated old executable in a clean child, retain the inherited
    # locked descriptor, and call that release's own forced-disable function.
    # This preserves the essential invariant: only the old release interprets
    # and restores its unique baseline snapshot, while the global lock is never
    # released for a competing menu process.  Carry the already-locked open
    # file description through the child's stdin: Bash may mark descriptors
    # created with `exec 9>` close-on-exec, while fd 0 is guaranteed to cross
    # exec.  The forced restore path is deliberately non-interactive, so an
    # unexpected read sees the empty lock file instead of consuming terminal
    # input.
    bash -c '
        old=$1; tmp=$2; owner=$3
        # Do not probe /proc/.../fd/0 with `test -e`: hardened procfs can
        # deny following the descriptor symlink even though flock(2) works.
        # flock itself is the authoritative inherited-descriptor check.
        flock -n 0 || exit 72
        source "$old" --source-only || exit 73
        E118_TMPDIR=$tmp
        E118_RUNTIME_READY=1
        E118_LOCK_DIR=
        case "$owner" in
            e202) fn=_e202_small_bbr_disable ;;
            e200) fn=_e200_small_bbr_disable ;;
            e198) fn=_e198_small_bbr_disable ;;
            e196) fn=_e196_small_bbr_disable ;;
            e194) fn=_e194_small_bbr_disable ;;
            e192) fn=_e192_small_bbr_disable ;;
            e190) fn=_e190_small_bbr_disable ;;
            *) exit 74 ;;
        esac
        declare -F "$fn" >/dev/null 2>&1 || exit 75
        "$fn" force
    ' e230-old-owner "$real" "$child_tmp" "$owner" <&9 || rc=$?
    if test "$rc" -ne 0; then
        error "旧版小BBR退出失败：owner=${owner:-unknown} old=$real rc=$rc"
    fi
    rm -rf -- "$child_tmp"
    return "$rc"
}

_e230_inactive_small_profile() {
    local out="${1:-}"
    test -n "$out" || return 1
    if test -e "$E202_SMALL_PROFILE" || test -L "$E202_SMALL_PROFILE"; then
        _e202_small_bbr_validate_file "$E202_SMALL_PROFILE" || {
            error "检测到无效的小BBR保存档，拒绝在自动升级中猜测或覆盖：$E202_SMALL_PROFILE"
            return 1
        }
        install -m 0600 "$E202_SMALL_PROFILE" "$out" || return 1
        info "未检测到活动小BBR，将应用现有有效保存档：$(_e202_small_bbr_profile_name "$(_e202_small_bbr_profile_id_file "$out")")"
    else
        case "$E230_DEFAULT_SMALL_PROFILE" in
            mode3f2) _e202_small_bbr_mode3f2 >"$out" || return 1 ;;
            *) error "E230内置默认小BBR档位无效：$E230_DEFAULT_SMALL_PROFILE"; return 1 ;;
        esac
        chmod 0600 "$out" || return 1
        _e202_small_bbr_validate_file "$out" || return 1
        info '未检测到活动或保存的小BBR档位，将按你的固定流程应用模式3F2。'
    fi
}

_e230_mtu_target_verify() {
    local target="${1:-$E230_TARGET_MTU}" iface actual state_target state_selector
    _e214_mtu_persistence_validate || return 1
    state_target=$(_e214_mtu_state_get_file "$E214_MTU_STATE" target_mtu) || return 1
    state_selector=$(_e214_mtu_state_get_file "$E214_MTU_STATE" selector) || return 1
    iface=$(_e214_mtu_state_get_file "$E214_MTU_STATE" last_iface) || return 1
    actual=$(_e214_mtu_current "$iface" 2>/dev/null || true)
    test "$state_target" = "$target" && test "$actual" = "$target" || {
        error "MTU最终读回不一致：iface=${iface:-unknown} expected=$target state=${state_target:-unknown} actual=${actual:-unknown}"
        return 1
    }
    _e214_mtu_route_health "$iface" "$state_selector"
}

# Non-interactive counterpart of menu 27/7.  It is intentionally callable only
# from the already confirmed outer upgrade transaction.  An independent
# systemd timer restores this MTU-local snapshot if the SSH shell disappears
# before persistence and runtime readback finish.
_e230_mtu_set_1350_auto() (
    local selector=auto configured=- target="$E230_TARGET_MTU" iface="" tx="" unit=""
    local runner="" guard="" baseline_work="" rc=0 snapshot_ready=0 finished=0
    local mtu_lock_fd="" rollback_lock_fd=""
    local mtu_lock_path="/run/lock/xray-mtu-e214.lock"
    if test "${E230_INTERNAL_SELF_TEST:-0}" = 1; then
        mtu_lock_path="${E230_MTU_LOCK_PATH:-$mtu_lock_path}"
    fi
    _e230_mtu_auto_exit_guard() {
        local status="${1:-1}"
        trap - EXIT HUP INT TERM
        # An unexpected exit may occur while the persistent-commit lock is
        # still held.  Release that dynamic descriptor before the guarded
        # restore opens the same lock file on its stable rollback descriptor;
        # otherwise the EXIT path can wait on its own still-live lock.
        if [[ "${rollback_lock_fd:-}" =~ ^[0-9]+$ ]]; then
            flock -u "$rollback_lock_fd" >/dev/null 2>&1 || true
        fi
        if test "$snapshot_ready" -eq 1 && test "$finished" -eq 0 && test -n "$tx"; then
            error '自动MTU事务意外中断，恢复MTU操作前的完整状态。'
            _e214_mtu_restore_guarded "$tx" "$unit" "$guard" || true
            test "$status" -ne 0 || status=1
        elif test "$finished" -eq 0 && test -n "$tx"; then
            _e214_tx_close "$tx" || true
        fi
        [[ "$status" =~ ^[0-9]+$ ]] || status=1
        exit "$status"
    }
    trap '_e230_mtu_auto_exit_guard $?' EXIT
    trap 'exit 129' HUP; trap 'exit 130' INT; trap 'exit 143' TERM
    _e214_mtu_value_valid "$target" || return 1
    iface=$(_e214_mtu_default_iface 2>/dev/null || true)
    _e214_mtu_iface_candidate "$iface" || {
        error '自动流程无法识别稳定的宿主机默认出口；未修改MTU。'
        return 1
    }
    _e214_prepare || return 1
    _e214_ensure_run_lock || return 1
    exec {mtu_lock_fd}>"$mtu_lock_path" || return 1
    flock -n "$mtu_lock_fd" || { error '已有MTU应用/复检事务正在运行。'; return 1; }
    if _e214_mtu_any_state; then
        _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE" || {
            error '现有MTU所有权状态不完整；自动流程拒绝覆盖。'
            return 1
        }
    fi
    tx=$(_e214_new_tx mtu-auto-e230) || return 1
    _e140_system_snapshot "$tx/system" || return 1
    snapshot_ready=1
    runner="$tx/mtu-rollback-runner.sh"
    guard="$tx/mtu-confirmed"
    install -m 0700 "$SCRIPT_PATH" "$runner" && bash -n "$runner" || return 1
    unit="xray-mtu-e230-auto-${E230_MAIN_PID}-$RANDOM"
    _e214_mtu_schedule_rollback "$unit" "$runner" "$tx/system" "$guard" || {
        error '无法创建独立MTU断线回滚定时器；未修改MTU。'
        return 1
    }
    baseline_work="$tx/mtu-baseline.work"
    if _e214_mtu_active; then
        install -m 0600 "$E214_MTU_BASELINE" "$baseline_work" || return 1
        _e214_mtu_restore_baseline_except "$baseline_work" "$iface" || return 1
    else
        : >"$baseline_work" || return 1
        chmod 0600 "$baseline_work" || return 1
    fi
    _e214_mtu_baseline_add "$baseline_work" "$iface" || return 1
    _e214_mtu_apply_runtime "$iface" "$target" || return 1
    _e214_mtu_route_health "$iface" "$selector" || return 1
    info "自动MTU临时读回通过：$iface=$target；独立断线回滚仍处于待命状态。"
    sleep 3
    _e214_mtu_apply_runtime "$iface" "$target" || return 1
    _e214_mtu_route_health "$iface" "$selector" || return 1
    if systemctl is-active --quiet xray.service 2>/dev/null; then
        _e127_verify_xray_runtime "$CONFIG" 12 || return 1
    fi
    # Hold the timer lock during the persistent commit.  A killed shell drops
    # this descriptor, allowing the independent rollback unit to restore.
    exec {rollback_lock_fd}>"$tx/mtu-rollback.lock" || return 1
    flock "$rollback_lock_fd" || return 1
    _e214_install_self || rc=1
    test "$rc" -ne 0 || _e214_mtu_commit "$tx" "$baseline_work" \
        "$selector" "$configured" "$target" "$iface" || rc=1
    test "$rc" -ne 0 || _e230_mtu_target_verify "$target" || rc=1
    if test "$rc" -eq 0; then _e214_mtu_guard_confirm "$guard" || rc=1; fi
    flock -u "$rollback_lock_fd" || true
    if test "$rc" -ne 0; then
        error 'MTU=1350持久化或最终读回失败，恢复MTU阶段前状态。'
        _e214_mtu_restore_guarded "$tx" "$unit" "$guard" || return 1
        finished=1
        trap - EXIT HUP INT TERM
        return 1
    fi
    _e214_mtu_transient_stop "$unit"
    _e214_tx_close "$tx" || warn "MTU=1350已提交，但事务活动标记未关闭：$tx"
    finished=1
    trap - EXIT HUP INT TERM
    info "宿主机默认出口MTU=1350已事务提交：iface=$iface；开机与5分钟漂移复检已启用。"
)

# E220/E222/E224 all wrote the durable MSS activity record with their own
# release number.  A newer script must still recognize a genuinely live older
# process; comparing only against the current E220_VERSION can misclassify it
# as stale and race its rollback.
_e230_mss_active_record_validate() {
    local file="${1:-}" line key value count=0
    local version pid start purpose created_epoch
    local -A seen=()
    test -f "$file" && test ! -L "$file" && test -s "$file" || return 1
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([a-z_]+)=(.*)$ ]] || return 1
        key=${BASH_REMATCH[1]}; value=${BASH_REMATCH[2]}
        case "$key" in version|pid|start|purpose|created_epoch) ;; *) return 1 ;; esac
        test -z "${seen[$key]+x}" && test -n "$value" || return 1
        seen[$key]=1; count=$((count + 1))
    done <"$file"
    test "$count" -eq 5 || return 1
    version=$(_e218_mss_owner_state_value "$file" version) || return 1
    pid=$(_e218_mss_owner_state_value "$file" pid) || return 1
    start=$(_e218_mss_owner_state_value "$file" start) || return 1
    purpose=$(_e218_mss_owner_state_value "$file" purpose) || return 1
    created_epoch=$(_e218_mss_owner_state_value "$file" created_epoch) || return 1
    case "$version" in 199e220|199e222|199e224|199e226|199e228|199e230) ;; *) return 1 ;; esac
    [[ "$pid" =~ ^[1-9][0-9]*$ && "$start" =~ ^[0-9]+$ \
      && "$purpose" =~ ^[A-Za-z0-9._-]{1,40}$ \
      && "$created_epoch" =~ ^[0-9]{1,20}$ ]]
}

_e230_mss_tx_live() {
    local d="${1:-}" pid expected actual
    _e230_mss_active_record_validate "$d/.active.env" || return 1
    pid=$(_e218_mss_owner_state_value "$d/.active.env" pid) || return 1
    expected=$(_e218_mss_owner_state_value "$d/.active.env" start) || return 1
    kill -0 "$pid" 2>/dev/null || return 1
    actual=$(_e214_proc_start_time "$pid" 2>/dev/null || true)
    test -n "$actual" && test "$actual" = "$expected"
}

# Bind the durable recovery center to the cross-release liveness check.
_e220_mss_tx_live() { _e230_mss_tx_live "$@"; }

_e230_non_mss_critical_preflight() {
    local label marker
    while IFS=$'\t' read -r label marker; do
        test "$marker" = "$E220_MSS_CRITICAL_MARKER" && continue
        if test ! -e "$marker" && test ! -L "$marker"; then continue; fi
        error "检测到${label}严重恢复标记，拒绝覆盖：$marker" >&2
        if test -f "$marker" && test ! -L "$marker" && test -r "$marker" && test -s "$marker"; then
            sed -n '1,20s/^/    /p' "$marker" >&2 || true
        else
            error '恢复标记为空、不可读、类型异常或为符号链接。' >&2
        fi
        return 1
    done < <(_e214_recovery_markers)
}

# Print exactly one machine-readable value: none or recover|ABSOLUTE_TX_PATH.
# Diagnostics go to stderr so callers can safely use command substitution.
_e230_mss_recovery_candidate() {
    local root selected="" only="" path active preserve phase has count=0
    if _e220_mss_unresolved_report >/dev/null 2>&1; then
        printf 'none\n'; return 0
    fi
    root=$(_e220_mss_tx_root) || return 1
    test -d "$root" && test ! -L "$root" || {
        error "MSS事务根目录无效：$root" >&2; return 1;
    }
    selected=$(_e220_mss_select_recovery_tx 2>/dev/null || true)
    test -n "$selected" || {
        error 'MSS存在恢复证据，但无法唯一解析安全事务。' >&2
        _e220_mss_unresolved_report >&2 || true
        return 1
    }
    while IFS= read -r -d '' path; do
        test ! -L "$path" && test -d "$path" || {
            error "MSS事务目录类型异常：$path" >&2; return 1;
        }
        active="$path/.active.env"; preserve="$path/.preserve.env"; has=0
        if test -e "$active" || test -L "$active"; then
            _e230_mss_active_record_validate "$active" || {
                error "MSS活动记录损坏或版本不受支持：$active" >&2; return 1;
            }
            if _e230_mss_tx_live "$path"; then
                error "旧版MSS事务进程仍在运行，拒绝并发恢复：$path" >&2
                return 1
            fi
            has=1
        fi
        if test -e "$preserve" || test -L "$preserve"; then
            test -f "$preserve" && test ! -L "$preserve" && test -s "$preserve" || {
                error "MSS保留标记损坏：$preserve" >&2; return 1;
            }
            has=1
        fi
        if test "$has" -eq 1; then
            count=$((count + 1)); only="$path"
        fi
    done < <(find "$root" -mindepth 1 -maxdepth 1 \( -type d -o -type l \) -print0 2>/dev/null | LC_ALL=C sort -z)
    test "$count" -eq 1 && test "$selected" = "$only" || {
        error "MSS未完成事务不是唯一目标（count=$count selected=${selected:-none}）。" >&2
        _e220_mss_unresolved_report >&2 || true
        return 1
    }
    phase=$(cat "$selected/.phase" 2>/dev/null || true)
    case "$phase" in
        created|rolled-back) ;;
        control-ready|triggers-stopped)
            _e220_mss_control_validate "$selected" || {
                error "MSS恢复事务控制快照校验失败：$selected" >&2; return 1;
            }
            ;;
        backends-ready|mutation-started|committed)
            _e220_mss_control_validate "$selected" \
              && _e220_mss_backends_validate "$selected" "$selected/backends.tsv" || {
                error "MSS恢复事务规则/控制快照校验失败：$selected" >&2; return 1;
            }
            ;;
        *) error "MSS恢复事务阶段无效：${phase:-missing}" >&2; return 1 ;;
    esac
    printf 'recover|%s\n' "$selected"
}

_e230_mss_recover_force() {
    local requested="${1:-}" candidate phase lock_fd="" marker_backup=""
    test -n "$requested" || return 1
    phase=$(cat "$requested/.phase" 2>/dev/null || true)
    if test "$phase" != rolled-back; then
        _e220_mss_recover force || return 1
    else
        _e214_ensure_run_lock || return 1
        exec {lock_fd}>"$E218_MSS_LOCK" || return 1
        flock -n "$lock_fd" || { error '已有MSS事务正在运行。'; return 1; }
        candidate=$(_e230_mss_recovery_candidate) || return 1
        test "$candidate" = "recover|$requested" || {
            error 'MSS恢复目标在加锁前发生变化。'; return 1;
        }
        _e220_mss_tx_close "$requested" recovered-already-rolled-back || return 1
        rm -f -- "$requested/.preserve.env" || return 1
        if test -e "$E220_MSS_CRITICAL_MARKER" || test -L "$E220_MSS_CRITICAL_MARKER"; then
            test -f "$E220_MSS_CRITICAL_MARKER" && test ! -L "$E220_MSS_CRITICAL_MARKER" || return 1
            marker_backup=$(awk -F= '$1=="backup"{n++;v=substr($0,index($0,"=")+1)}END{if(n==1)print v;else exit 1}' \
                "$E220_MSS_CRITICAL_MARKER") || return 1
            test "$marker_backup" = "$requested" || return 1
            rm -f -- "$E220_MSS_CRITICAL_MARKER" || return 1
        fi
        info "已关闭完成回滚但未关闭活动标记的旧MSS事务：$requested"
    fi
    _e220_mss_unresolved_report >/dev/null 2>&1 || {
        error '旧MSS恢复后仍存在未解决事务；拒绝继续升级。'
        _e220_mss_unresolved_report >&2 || true
        return 1
    }
}

_e230_mss_control_types_safe() {
    local path
    for path in "$E88_MSS_STATE_FILE" "$E216_MSS_BACKEND_STATE" \
        "$E218_MSS_OWNER_STATE" "$E216_MSS_SCRIPT" \
        "$E216_MSS_SERVICE" "$E216_MSS_TIMER"; do
        if test -e "$path" || test -L "$path"; then
            test -f "$path" && test ! -L "$path" || {
                error "MSS控制路径不是可信普通文件：$path" >&2; return 1;
            }
        fi
    done
}

# This is used only when the legacy ON/OFF file is absent.  Infer ON only from
# a complete modern owner/backend/unit/runtime set; partial residue defaults to
# an OFF cleanup plan instead of silently enabling a system-wide clamp.
_e230_mss_complete_on_without_legacy() {
    local backend owner_backend tool identity rc
    _e218_mss_owner_state_validate "$E218_MSS_OWNER_STATE" || return 1
    _e216_mss_backend_state_validate "$E216_MSS_BACKEND_STATE" || return 1
    backend=$(_e216_mss_state_value "$E216_MSS_BACKEND_STATE" backend) || return 1
    owner_backend=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" backend) || return 1
    tool=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" tool_path) || return 1
    identity=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" tool_identity) || return 1
    test "$backend" = "$owner_backend" \
      && test "$(readlink -f -- "$tool" 2>/dev/null || true)" = "$identity" || return 1
    test -f "$E216_MSS_SCRIPT" && test ! -L "$E216_MSS_SCRIPT" \
      && bash -n "$E216_MSS_SCRIPT" || return 1
    test -f "$E216_MSS_SERVICE" && test ! -L "$E216_MSS_SERVICE" \
      && test -f "$E216_MSS_TIMER" && test ! -L "$E216_MSS_TIMER" || return 1
    systemctl is-enabled --quiet "$E216_MSS_SERVICE_UNIT" 2>/dev/null || return 1
    systemctl is-enabled --quiet "$E216_MSS_TIMER_UNIT" 2>/dev/null || return 1
    systemctl is-active --quiet "$E216_MSS_TIMER_UNIT" 2>/dev/null || return 1
    _e220_mss_backend_has_managed "$backend"; rc=$?
    test "$rc" -eq 0
}

# Print exactly one of: steady-on, steady-off, repair-on, repair-off, recover.
_e230_mss_plan_readonly() {
    local recovery state desired direct_rc
    recovery=$(_e230_mss_recovery_candidate) || return 1
    if test "$recovery" != none; then printf 'recover\n'; return 0; fi
    _e230_mss_control_types_safe || return 1
    state=$(_e218_mss_owner_state 2>/dev/null || echo INVALID)
    case "$state" in ON|OFF|UNSET) ;; *)
        error 'MSS ON/OFF状态文件损坏；不能自动猜测用户意图。' >&2; return 1 ;;
    esac
    if _e218_mss_consistency; then
        if test "$state" = ON; then printf 'steady-on\n'; else printf 'steady-off\n'; fi
        return 0
    fi
    case "$state" in
        ON) desired=on ;;
        OFF) desired=off ;;
        UNSET)
            if _e230_mss_complete_on_without_legacy; then desired=on; else desired=off; fi
            ;;
    esac
    if test "$desired" = on; then
        if _e220_mss_unowned_direct_report >&2; then direct_rc=0; else direct_rc=$?; fi
        if test "$direct_rc" -ne 0; then
            error 'MSS计划为ON，但存在外部裸TCPMSS规则；不会覆盖或形成双重Clamp。' >&2
            return 1
        fi
    fi
    test -d /run/systemd/system || test "${E230_INTERNAL_SELF_TEST:-0}" = 1 || {
        error 'MSS漂移需要systemd事务收敛，但当前systemd未运行。' >&2; return 1;
    }
    printf 'repair-%s\n' "$desired"
}

# During OFF cleanup an administrator-owned direct TCPMSS rule is preserved.
# Named xray chains remain removable.  Enabling our own clamp still fails its
# exclusivity readback if that external direct rule exists, so no double clamp
# can be committed.
_e216_mss_cleanup_backend() {
    local backend="${1:-}" tool line rc=0 direct_rc allow_direct=0
    tool=$(_e216_mss_tool_path "$backend") || return 1
    "$tool" -w 5 -t mangle -S >/dev/null 2>&1 || return 1
    _e220_mss_backend_has_direct "$backend"; direct_rc=$?
    case "$direct_rc" in
        0)
            if _e220_mss_legacy_direct_is_owned "$backend"; then
                allow_direct=1
            else
                warn "保留管理员所有的裸TCPMSS规则：backend=$backend"
            fi
            ;;
        1) ;;
        *) return 1 ;;
    esac
    if test "$allow_direct" -eq 1; then
        while "$tool" -w 5 -t mangle -D POSTROUTING -p tcp -m tcp \
          --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1; do :; done
    fi
    while "$tool" -w 5 -t mangle -D POSTROUTING -j "$E216_MSS_CHAIN" >/dev/null 2>&1; do :; done
    "$tool" -w 5 -t mangle -F "$E216_MSS_CHAIN" >/dev/null 2>&1 || true
    "$tool" -w 5 -t mangle -X "$E216_MSS_CHAIN" >/dev/null 2>&1 || true
    while IFS= read -r line; do
        [[ "$line" == *"-j $E216_MSS_CHAIN"* ]] && rc=1
    done < <("$tool" -w 5 -t mangle -S POSTROUTING 2>/dev/null || true)
    "$tool" -w 5 -t mangle -S "$E216_MSS_CHAIN" >/dev/null 2>&1 && rc=1 || true
    if test "$allow_direct" -eq 1; then
        _e220_mss_backend_has_direct "$backend" && rc=1 || test "$?" -eq 1 || rc=1
    fi
    return "$rc"
}

_e230_mss_expected_from_plan() {
    case "${1:-}" in steady-on|repair-on) printf 'on\n' ;; steady-off|repair-off) printf 'off\n' ;; *) return 1 ;; esac
}

_e230_mss_verify_intent() {
    case "${1:-}" in on) _e218_mss_verify_on ;; off) _e218_mss_verify_off ;; *) return 1 ;; esac
}

_e230_mss_reconcile_plan() {
    local plan="${1:-}" expected
    expected=$(_e230_mss_expected_from_plan "$plan") || return 1
    case "$plan" in
        steady-on|steady-off) ;;
        repair-off)
            info '自动收敛MSS漂移：保留外部规则，仅清理脚本自有残留并保持OFF。'
            _e218_mss_disable || return 1
            ;;
        repair-on)
            info '自动收敛MSS漂移：先事务清理旧层，再按唯一后端重建并保持ON。'
            _e218_mss_disable && _e218_mss_enable || return 1
            ;;
        *) return 1 ;;
    esac
    _e230_mss_verify_intent "$expected" || {
        error "MSS自动收敛读回失败：expected=$expected plan=$plan"; return 1;
    }
}

# The old small-BBR owner restores the full baseline captured when that profile
# was first enabled.  MSS may have been enabled or repaired later, so running
# MSS convergence *before* the old-owner exit is not stable: the baseline
# restore can silently undo it.  Preserve the pre-upgrade user intent, exit the
# old network owner first, then converge explicitly to that intent.
_e230_mss_converge_expected() {
    local expected="${1:-}"
    case "$expected" in on|off) ;; *) return 1 ;; esac
    if _e230_mss_verify_intent "$expected"; then return 0; fi
    case "$expected" in
        off)
            info '旧网络基线恢复后收敛MSS：仅清理脚本自有残留并保持OFF。'
            _e218_mss_disable || return 1
            ;;
        on)
            info '旧网络基线恢复后收敛MSS：清理旧层并按唯一后端重建为ON。'
            _e218_mss_disable && _e218_mss_enable || return 1
            ;;
    esac
    _e230_mss_verify_intent "$expected" || {
        error "旧小BBR退出后MSS意图收敛失败：expected=$expected"
        return 1
    }
}

# A legacy small-BBR exit restores the *whole* baseline taken when that old
# profile was enabled.  Nodes/users, WARP credentials and IPv6 intent can have
# changed afterwards, so they need an independent, sealed snapshot which is
# replayed immediately after the old owner has exited.  This snapshot is kept
# inside the outer E230 transaction root; an old baseline restore therefore
# cannot delete it.
_e230_independent_file_target() {
    case "${1:-}" in
        warp_state) printf '%s\n' "$E139_WARP_STATE" ;;
        wg_account) printf '%s\n' "$E185_WG_ACCOUNT" ;;
        wg_profile) printf '%s\n' "$E185_WG_PROFILE" ;;
        wg_endpoint) printf '%s\n' "$E185_WG_ENDPOINT_STATE" ;;
        *) return 1 ;;
    esac
}

_e230_independent_value() {
    local file="${1:-}" key="${2:-}"
    awk -F= -v key="$key" '
      $1==key {n++; v=substr($0,index($0,"=")+1)}
      END {if(n==1 && length(v)>0) print v; else exit 1}
    ' "$file" 2>/dev/null
}

_e230_file_digest() {
    local file="${1:-}"
    if test -e "$file" || test -L "$file"; then
        test -f "$file" && test ! -L "$file" || return 1
        sha256sum -- "$file" 2>/dev/null | awk '{print $1}'
    else
        printf 'absent\n'
    fi
}

_e230_inbounds_digest() {
    local file="${1:-}"
    test -f "$file" && test ! -L "$file" && command -v jq >/dev/null 2>&1 || return 1
    jq -S -c '.inbounds // []' "$file" 2>/dev/null | sha256sum | awk '{print $1}'
}

# `_e127_verify_state_snapshot` deliberately accepts only E118's historical
# backup root.  The one-confirm workflow needs a second sealed copy which the
# old small-BBR baseline cannot delete, so that copy lives below the *current*
# outer transaction.  Keep the old verifier strict and give this copy a narrow
# validator whose trust root is supplied by its already-open outer transaction.
_e230_independent_root_ok() {
    local trust="${1:-}" real="" txroot=""
    test -d "$trust" && test ! -L "$trust" || return 1
    real=$(readlink -f -- "$trust" 2>/dev/null || true)
    test -n "$real" || return 1
    if test "${E230_INTERNAL_SELF_TEST:-0}" = 1; then
        case "$real" in /tmp/xray-e230-independent.*/*|/tmp/xray-e230-independent.*) return 0 ;; esac
        return 1
    fi
    txroot=$(readlink -f -- "$E214_TX_ROOT" 2>/dev/null || true)
    test -n "$txroot" && test -d "$txroot" && test ! -L "$E214_TX_ROOT" || return 1
    case "$real" in "$txroot"/auto-upgrade-e230-*/e230-independent) return 0 ;; esac
    return 1
}

_e230_xray_snapshot_validate() {
    local bdir="${1:-}" trust="${2:-}" real="" trusted="" base="" line=""
    local key="" value="" count=0 allowed=" " seen=" " manifest_count=0
    local active="" enabled="" version=""
    local -A meta_seen=()
    test -n "$bdir" && test -n "$trust" || return 1
    _e230_independent_root_ok "$trust" \
      && test -d "$bdir" && test ! -L "$bdir" || return 1
    trusted=$(readlink -f -- "$trust" 2>/dev/null || true)
    real=$(readlink -f -- "$bdir" 2>/dev/null || true)
    test -n "$trusted" && test -n "$real" || return 1
    case "$real" in "$trusted"/xray) ;; *) return 1 ;; esac
    test "$(stat -c %u "$trusted" 2>/dev/null || true)" = 0 \
      && test "$(stat -c %u "$real" 2>/dev/null || true)" = 0 || return 1
    test -z "$(find "$bdir" -mindepth 1 ! -uid 0 -print -quit 2>/dev/null)" || return 1
    test -z "$(find "$bdir" -mindepth 1 -type l -print -quit 2>/dev/null)" || return 1
    test -z "$(find "$bdir" -mindepth 1 -maxdepth 1 ! -type f -print -quit 2>/dev/null)" || return 1
    test -z "$(find "$bdir" -mindepth 1 -perm /022 -print -quit 2>/dev/null)" || return 1
    for base in files.manifest meta.env files.sha256 snapshot-seal.sha256; do
        test -f "$bdir/$base" && test ! -L "$bdir/$base" || return 1
    done
    test -s "$bdir/meta.env" && test -s "$bdir/snapshot-seal.sha256" || return 1

    while IFS= read -r base; do
        test -n "$base" || continue
        base=$(basename -- "$base")
        [[ "$base" =~ ^[A-Za-z0-9._-]+$ ]] || return 1
        [[ "$allowed" != *" $base "* ]] || return 1
        allowed+="$base "
    done < <(_e118_managed_state_files)
    while IFS= read -r base || test -n "$base"; do
        test -n "$base" || return 1
        [[ "$base" =~ ^[A-Za-z0-9._-]+$ ]] || return 1
        [[ "$allowed" == *" $base "* ]] || return 1
        [[ "$seen" != *" $base "* ]] || return 1
        seen+="$base "; manifest_count=$((manifest_count + 1))
        test -f "$bdir/$base" && test ! -L "$bdir/$base" || return 1
    done <"$bdir/files.manifest"

    # Both checksum files are themselves covered by the independent-state
    # seal.  Reject path-bearing checksum entries before invoking sha256sum.
    count=0; seen=" "
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([0-9a-f]{64})[[:space:]][[:space:]]([A-Za-z0-9._-]+)$ ]] || return 1
        base=${BASH_REMATCH[2]}
        [[ "$allowed" == *" $base "* && "$seen" != *" $base "* ]] || return 1
        seen+="$base "; count=$((count + 1))
    done <"$bdir/files.sha256"
    test "$count" -eq "$manifest_count" || return 1
    if test "$count" -gt 0; then
        (cd "$bdir" && sha256sum -c files.sha256 >/dev/null 2>&1) || return 1
    else
        test ! -s "$bdir/files.sha256" || return 1
    fi
    seen=" "; count=0
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([0-9a-f]{64})[[:space:]][[:space:]]([A-Za-z0-9._-]+)$ ]] || return 1
        base=${BASH_REMATCH[2]}
        test "$base" != snapshot-seal.sha256 && [[ "$seen" != *" $base "* ]] || return 1
        test -f "$bdir/$base" && test ! -L "$bdir/$base" || return 1
        seen+="$base "; count=$((count + 1))
    done <"$bdir/snapshot-seal.sha256"
    while IFS= read -r base; do
        test -n "$base" && [[ "$seen" == *" $base "* ]] || return 1
        count=$((count - 1))
    done < <(find "$bdir" -mindepth 1 -maxdepth 1 -type f \
        ! -name snapshot-seal.sha256 -printf '%f\n' | LC_ALL=C sort)
    test "$count" -eq 0 || return 1
    (cd "$bdir" && sha256sum -c snapshot-seal.sha256 >/dev/null 2>&1) || return 1

    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([a-z_]+)=(.*)$ ]] || return 1
        key=${BASH_REMATCH[1]}; value=${BASH_REMATCH[2]}
        case "$key" in
            created_at|version|tag|xray_was_active|xray_was_enabled|xray_enabled_state) ;;
            *) return 1 ;;
        esac
        test -z "${meta_seen[$key]+x}" && test -n "$value" || return 1
        meta_seen[$key]=1; count=$((count + 1))
    done <"$bdir/meta.env"
    test "${#meta_seen[@]}" -eq 6 || return 1
    version=$(_e230_independent_value "$bdir/meta.env" version) || return 1
    active=$(_e230_independent_value "$bdir/meta.env" xray_was_active) || return 1
    enabled=$(_e230_independent_value "$bdir/meta.env" xray_was_enabled) || return 1
    [[ "$version" =~ ^(198|199)e[0-9]+$ && "$active" =~ ^[01]$ && "$enabled" =~ ^[01]$ ]] || return 1
    if grep -qx config.json "$bdir/files.manifest" 2>/dev/null; then
        test -s "$bdir/config.json" && _e118_xray_test_config "$bdir/config.json" 1 || return 1
    fi
}

_e230_xray_snapshot_restore() {
    local bdir="${1:-}" trust="${2:-}" f="" base="" now=""
    local was_active="" was_enabled="" rc=0
    _e230_xray_snapshot_validate "$bdir" "$trust" || return 1
    was_active=$(_e230_independent_value "$bdir/meta.env" xray_was_active) || return 1
    was_enabled=$(_e230_independent_value "$bdir/meta.env" xray_was_enabled) || return 1
    while IFS= read -r f; do
        test -n "$f" || continue
        base=$(basename -- "$f")
        if grep -qxF "$base" "$bdir/files.manifest" 2>/dev/null; then
            _e118_atomic_install "$bdir/$base" "$f" 0600 || rc=1
        else
            rm -f -- "$f" 2>/dev/null || rc=1
        fi
        test "$rc" -eq 0 || break
    done < <(_e118_managed_state_files)
    test "$rc" -eq 0 && fix_permissions || return 1
    if test "$was_enabled" = 1; then
        systemctl enable xray.service >/dev/null 2>&1 || return 1
    else
        systemctl disable xray.service >/dev/null 2>&1 || return 1
        now=$(systemctl is-enabled xray.service 2>/dev/null || true)
        case "$now" in enabled|enabled-runtime|linked|linked-runtime) return 1 ;; esac
    fi
    if test "$was_active" = 1; then
        systemctl reset-failed xray.service >/dev/null 2>&1 || true
        systemctl restart xray.service >/dev/null 2>&1 || return 1
        _e127_verify_xray_runtime "$CONFIG" 12 || return 1
    else
        systemctl stop xray.service >/dev/null 2>&1 || true
        systemctl is-active --quiet xray.service 2>/dev/null && return 1 || true
    fi
    E118_TX_ACTIVE=0; E118_TX_BACKUP=""; E118_TX_WAS_ACTIVE=0
}

_e230_independent_state_capture() {
    local root="${1:-}" source="" xray="" id="" target="" status=""
    local ipv6="" enabled="" mode="" profile="" family="" backend="" request=""
    local inbounds_sha="" sni_sha="" time_sha="" pub_sha=""
    test -n "$root" && test ! -e "$root" && test ! -L "$root" || return 1
    install -d -o root -g root -m 0700 "$root" "$root/files" "$root/xray" || return 1

    source=$(_e116_backup_state before_e230_old_small_bbr_exit) || return 1
    _e127_verify_state_snapshot "$source" || return 1
    cp -a -- "$source/." "$root/xray/" || return 1
    _e230_xray_snapshot_validate "$root/xray" "$root" || return 1

    ipv6=$(_e182_ipv6_policy_desired) || return 1
    enabled=$(_e138_state_get route_enabled 0)
    mode=$(_e138_state_get route_mode disabled)
    profile=$(_e138_state_get profile disabled)
    family=$(_e138_state_get family ipv4)
    backend=$(_e138_state_get backend disabled)
    request=$(_e138_state_get backend_request "$backend")
    inbounds_sha=$(_e230_inbounds_digest "$CONFIG") || return 1
    sni_sha=$(_e230_file_digest "$USER_SNI_MAP") || return 1
    time_sha=$(_e230_file_digest "$USER_TIME_MAP") || return 1
    pub_sha=$(_e230_file_digest "$PUBKEY_FILE") || return 1
    [[ "$ipv6" =~ ^[01]$ && "$enabled" =~ ^[01]$ ]] || return 1
    for status in "$mode" "$profile" "$family" "$backend" "$request"; do
        [[ "$status" =~ ^[A-Za-z0-9._:+-]{1,80}$ ]] || return 1
    done
    {
        printf 'version=199e230\n'
        printf 'ipv6_desired=%s\n' "$ipv6"
        printf 'warp_enabled=%s\n' "$enabled"
        printf 'warp_mode=%s\n' "$mode"
        printf 'warp_profile=%s\n' "$profile"
        printf 'warp_family=%s\n' "$family"
        printf 'warp_backend=%s\n' "$backend"
        printf 'warp_request=%s\n' "$request"
        printf 'inbounds_sha256=%s\n' "$inbounds_sha"
        printf 'user_sni_sha256=%s\n' "$sni_sha"
        printf 'user_time_sha256=%s\n' "$time_sha"
        printf 'public_key_sha256=%s\n' "$pub_sha"
    } >"$root/intent.env" || return 1
    : >"$root/files.manifest" || return 1
    for id in warp_state wg_account wg_profile wg_endpoint; do
        target=$(_e230_independent_file_target "$id") || return 1
        if test -e "$target" || test -L "$target"; then
            test -f "$target" && test ! -L "$target" || return 1
            install -o root -g root -m 0600 "$target" "$root/files/$id" || return 1
            status=present
        else
            status=absent
        fi
        printf '%s|%s\n' "$id" "$status" >>"$root/files.manifest" || return 1
    done
    find "$root" -type d -exec chmod 0700 {} + || return 1
    find "$root" -type f -exec chmod 0600 {} + || return 1
    (cd "$root" && find . -type f ! -name independent.sha256 -print0 \
        | LC_ALL=C sort -z | xargs -0 sha256sum >independent.sha256) || return 1
    chmod 0600 "$root/independent.sha256" || return 1
    _e230_independent_state_validate "$root"
}

_e230_independent_state_validate() {
    local root="${1:-}" line="" id="" status="" target="" count=0 key="" value=""
    local -A seen=()
    test -d "$root" && test ! -L "$root" \
      && test -f "$root/intent.env" && test ! -L "$root/intent.env" \
      && test -f "$root/files.manifest" && test ! -L "$root/files.manifest" \
      && test -f "$root/independent.sha256" && test ! -L "$root/independent.sha256" \
      && test -d "$root/xray" && test ! -L "$root/xray" || return 1
    (cd "$root" && sha256sum -c independent.sha256 >/dev/null 2>&1) || return 1
    _e230_xray_snapshot_validate "$root/xray" "$root" || return 1
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([a-z0-9_]+)=(.*)$ ]] || return 1
        key=${BASH_REMATCH[1]}; value=${BASH_REMATCH[2]}
        case "$key" in
            version|ipv6_desired|warp_enabled|warp_mode|warp_profile|warp_family|warp_backend|warp_request|inbounds_sha256|user_sni_sha256|user_time_sha256|public_key_sha256) ;;
            *) return 1 ;;
        esac
        test -z "${seen[$key]+x}" && test -n "$value" || return 1
        seen[$key]=1; count=$((count + 1))
    done <"$root/intent.env"
    test "$count" -eq 12 || return 1
    test "$(_e230_independent_value "$root/intent.env" version)" = 199e230 || return 1
    [[ "$(_e230_independent_value "$root/intent.env" ipv6_desired)" =~ ^[01]$ ]] || return 1
    [[ "$(_e230_independent_value "$root/intent.env" warp_enabled)" =~ ^[01]$ ]] || return 1
    for key in warp_mode warp_profile warp_family warp_backend warp_request; do
        value=$(_e230_independent_value "$root/intent.env" "$key") || return 1
        [[ "$value" =~ ^[A-Za-z0-9._:+-]{1,80}$ ]] || return 1
    done
    for key in inbounds_sha256 user_sni_sha256 user_time_sha256 public_key_sha256; do
        value=$(_e230_independent_value "$root/intent.env" "$key") || return 1
        [[ "$value" = absent || "$value" =~ ^[0-9a-f]{64}$ ]] || return 1
    done
    unset seen; declare -A seen=()
    count=0
    while IFS='|' read -r id status; do
        case "$id" in warp_state|wg_account|wg_profile|wg_endpoint) ;; *) return 1 ;; esac
        case "$status" in present|absent) ;; *) return 1 ;; esac
        test -z "${seen[$id]+x}" || return 1
        seen[$id]=1; count=$((count + 1))
        target=$(_e230_independent_file_target "$id") || return 1
        if test "$status" = present; then
            test -f "$root/files/$id" && test ! -L "$root/files/$id" || return 1
        else
            test ! -e "$root/files/$id" && test ! -L "$root/files/$id" || return 1
        fi
        test -n "$target" || return 1
    done <"$root/files.manifest"
    test "$count" -eq 4
}

_e230_ipv6_converge_expected() {
    local desired="${1:-}"
    case "$desired" in 0|1) ;; *) return 1 ;; esac
    if test "$desired" = 1 && _e182_ipv6_live_ssh_session; then
        _e182_ipv6_pending_write || return 1
        warn '保持升级前IPv6关闭意图，但当前是IPv6 SSH会话；已安全暂缓到后续IPv4会话/开机复检。'
    else
        _e182_ipv6_apply "$desired" hot-update 1 || return 1
    fi
    _e182_ipv6_hot_verify
}

_e230_independent_state_restore() {
    local root="${1:-}" id="" status="" target="" desired=""
    _e230_independent_state_validate "$root" || return 1
    _e230_xray_snapshot_restore "$root/xray" "$root" || {
        error '旧小BBR退出后恢复升级前节点/用户状态失败。'; return 1;
    }
    while IFS='|' read -r id status; do
        target=$(_e230_independent_file_target "$id") || return 1
        if test "$status" = present; then
            install -d -o root -g root -m 0700 "$(dirname -- "$target")" || return 1
            install -o root -g root -m 0600 "$root/files/$id" "$target" || return 1
        else
            rm -f -- "$target" || return 1
        fi
    done <"$root/files.manifest"
    _e138_warp_reconcile || {
        error '旧小BBR退出后恢复升级前WARP意图失败。'; return 1;
    }
    desired=$(_e230_independent_value "$root/intent.env" ipv6_desired) || return 1
    _e230_ipv6_converge_expected "$desired" || {
        error '旧小BBR退出后恢复升级前IPv6意图失败。'; return 1;
    }
}

_e230_independent_state_verify() {
    local root="${1:-}" key="" expected="" actual=""
    _e230_independent_state_validate "$root" || return 1
    expected=$(_e230_independent_value "$root/intent.env" inbounds_sha256) || return 1
    actual=$(_e230_inbounds_digest "$CONFIG") || return 1
    test "$actual" = "$expected" || {
        error '升级后Xray入站/节点/用户身份集合与升级前不一致。'; return 1;
    }
    for key in user_sni_sha256 user_time_sha256 public_key_sha256; do
        expected=$(_e230_independent_value "$root/intent.env" "$key") || return 1
        case "$key" in
            user_sni_sha256) actual=$(_e230_file_digest "$USER_SNI_MAP") || return 1 ;;
            user_time_sha256) actual=$(_e230_file_digest "$USER_TIME_MAP") || return 1 ;;
            public_key_sha256) actual=$(_e230_file_digest "$PUBKEY_FILE") || return 1 ;;
        esac
        test "$actual" = "$expected" || {
            error "升级后节点元数据读回不一致：$key"; return 1;
        }
    done
    for key in warp_enabled warp_mode warp_profile warp_family warp_backend warp_request; do
        expected=$(_e230_independent_value "$root/intent.env" "$key") || return 1
        case "$key" in
            warp_enabled) actual=$(_e138_state_get route_enabled 0) ;;
            warp_mode) actual=$(_e138_state_get route_mode disabled) ;;
            warp_profile) actual=$(_e138_state_get profile disabled) ;;
            warp_family) actual=$(_e138_state_get family ipv4) ;;
            warp_backend) actual=$(_e138_state_get backend disabled) ;;
            warp_request) actual=$(_e138_state_get backend_request "$(_e138_state_get backend disabled)") ;;
        esac
        test "$actual" = "$expected" || {
            error "升级后WARP意图读回不一致：$key expected=$expected actual=$actual"; return 1;
        }
    done
    expected=$(_e230_independent_value "$root/intent.env" ipv6_desired) || return 1
    test "$(_e182_ipv6_policy_desired)" = "$expected" && _e182_ipv6_hot_verify || {
        error "升级后IPv6意图读回不一致：expected=$expected"; return 1;
    }
}

_e230_mss_outer_capture() {
    local snapshot="${1:-}" plan="${2:-}" final meta
    test -d "$snapshot" && test ! -L "$snapshot" || return 1
    case "$plan" in steady-on|steady-off|repair-on|repair-off) ;; *) return 1 ;; esac
    final="$snapshot/e230-mss-exact"
    test ! -e "$final" && test ! -L "$final" || return 1
    install -d -m 0700 "$final" || return 1
    _e220_mss_capture_control "$final" \
      && _e220_mss_capture_backends "$final" "$final/backends.tsv" || {
        rm -rf -- "$final"; return 1;
    }
    meta="$final/outer.env"
    {
        printf 'version=199e230\n'
        printf 'plan=%s\n' "$plan"
        printf 'created_epoch=%s\n' "$(date +%s)"
    } >"$meta" && chmod 0600 "$meta" || { rm -rf -- "$final"; return 1; }
    (cd "$final" && sha256sum outer.env >outer.sha256) || { rm -rf -- "$final"; return 1; }
    chmod 0600 "$final/outer.sha256" || { rm -rf -- "$final"; return 1; }
    _e230_mss_outer_validate "$final" || { rm -rf -- "$final"; return 1; }
}

_e230_mss_outer_validate() {
    local d="${1:-}" version plan epoch line key value count=0
    local -A seen=()
    test -d "$d" && test ! -L "$d" \
      && test -f "$d/outer.env" && test ! -L "$d/outer.env" \
      && test -f "$d/outer.sha256" && test ! -L "$d/outer.sha256" || return 1
    (cd "$d" && sha256sum -c outer.sha256 >/dev/null 2>&1) || return 1
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([a-z_]+)=(.*)$ ]] || return 1
        key=${BASH_REMATCH[1]}; value=${BASH_REMATCH[2]}
        case "$key" in version|plan|created_epoch) ;; *) return 1 ;; esac
        test -z "${seen[$key]+x}" && test -n "$value" || return 1
        seen[$key]=1; count=$((count + 1))
    done <"$d/outer.env"
    test "$count" -eq 3 || return 1
    version=$(_e218_mss_owner_state_value "$d/outer.env" version) || return 1
    plan=$(_e218_mss_owner_state_value "$d/outer.env" plan) || return 1
    epoch=$(_e218_mss_owner_state_value "$d/outer.env" created_epoch) || return 1
    case "$version" in 199e226|199e228|199e230) ;; *) return 1 ;; esac
    [[ "$epoch" =~ ^[0-9]{1,20}$ ]] || return 1
    case "$plan" in steady-on|steady-off|repair-on|repair-off) ;; *) return 1 ;; esac
    _e220_mss_control_validate "$d" \
      && _e220_mss_backends_validate "$d" "$d/backends.tsv"
}

_e230_mss_outer_restore() {
    local d="${1:-}" rc=0
    _e230_mss_outer_validate "$d" || return 1
    _e218_mss_stop_triggers || rc=1
    _e220_mss_restore_control_files "$d" || rc=1
    # Restored oneshot units may immediately touch rules; restore every exact
    # xtables snapshot after service state, then read back both domains.
    _e220_mss_restore_control_services "$d" || rc=1
    _e220_mss_restore_backends "$d" "$d/backends.tsv" || rc=1
    _e220_mss_backends_match "$d" "$d/backends.tsv" || rc=1
    _e220_mss_control_matches "$d" || rc=1
    return "$rc"
}

# E222/E224/E226/E228 can leave a critical marker only when their own outer
# rollback/readback did not finish.  Accept the exact known release,
# operation and transaction-directory ABI (including E230 retry), never an
# arbitrary backup path.  Unrelated critical markers still fail closed.
_e230_previous_auto_marker_snapshot() {
    local marker="${1:-$E214_CRITICAL_MARKER}" tx_root="${2:-$E214_TX_ROOT}"
    local line key value count=0
    local version operation backup root real parent pid start actual
    local -A seen=()
    test -f "$marker" && test ! -L "$marker" && test -r "$marker" \
      && test -s "$marker" || return 1
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([a-z_]+)=(.*)$ ]] || return 1
        key=${BASH_REMATCH[1]}; value=${BASH_REMATCH[2]}
        case "$key" in version|time|operation|backup|reason) ;; *) return 1 ;; esac
        test -z "${seen[$key]+x}" && test -n "$value" || return 1
        seen[$key]=1; count=$((count + 1))
    done <"$marker"
    test "$count" -eq 5 || return 1
    version=$(_e218_mss_owner_state_value "$marker" version) || return 1
    operation=$(_e218_mss_owner_state_value "$marker" operation) || return 1
    backup=$(_e218_mss_owner_state_value "$marker" backup) || return 1
    case "$version|$operation" in
        '199e222|e222-auto-upgrade'|'199e222|e222-auto-upgrade-interrupted')
            key=e222 ;;
        '199e224|e224-auto-upgrade'|'199e224|e224-auto-upgrade-unexpected')
            key=e224 ;;
        '199e226|e226-auto-upgrade'|'199e226|e226-auto-upgrade-unexpected')
            key=e226 ;;
        '199e228|e228-auto-upgrade'|'199e228|e228-auto-upgrade-unexpected')
            key=e228 ;;
        '199e230|e230-auto-upgrade'|'199e230|e230-auto-upgrade-unexpected')
            key=e230 ;;
        *) return 1 ;;
    esac
    root=$(readlink -f -- "$tx_root" 2>/dev/null || true)
    real=$(readlink -f -- "$backup" 2>/dev/null || true)
    test -n "$root" && test -d "$root" && test -n "$real" \
      && test -d "$real" && test ! -L "$backup" && test ! -L "$real" || return 1
    case "$real" in "$root"/auto-upgrade-"$key"-*/system) ;; *) return 1 ;; esac
    parent=${real%/system}
    if test -e "$parent/.active.env" || test -L "$parent/.active.env"; then
        test -f "$parent/.active.env" && test ! -L "$parent/.active.env" || return 1
        pid=$(awk -F= '$1=="pid"{n++;v=$2}END{if(n==1)print v;else exit 1}' \
            "$parent/.active.env") || return 1
        start=$(awk -F= '$1=="start"{n++;v=$2}END{if(n==1)print v;else exit 1}' \
            "$parent/.active.env") || return 1
        [[ "$pid" =~ ^[1-9][0-9]*$ && "$start" =~ ^[0-9]+$ ]] || return 1
        if kill -0 "$pid" 2>/dev/null; then
            actual=$(_e214_proc_start_time "$pid" 2>/dev/null || true)
            test -n "$actual" && test "$actual" != "$start" || {
                error "旧${version}自动升级进程仍存活，拒绝并发恢复：pid=$pid" >&2
                return 1
            }
        fi
    fi
    printf '%s|%s|%s\n' "$version" "$operation" "$real"
}

_e230_recover_previous_failed_auto() {
    local record="" prior_version="" prior_operation="" snapshot="" parent=""
    local candidate="" recovery_tx="" shown_version="" shown_operation=""
    local marker="$E214_CRITICAL_MARKER" tx_root="$E214_TX_ROOT"
    if test "${E230_INTERNAL_SELF_TEST:-0}" = 1; then
        marker="${1:-$marker}"; tx_root="${2:-$tx_root}"
    elif test "$#" -ne 0; then
        return 1
    fi
    if test ! -e "$marker" && test ! -L "$marker"; then
        return 0
    fi
    record=$(_e230_previous_auto_marker_snapshot "$marker" "$tx_root") || {
        shown_version=$(sed -n 's/^version=//p' "$marker" 2>/dev/null | tail -n1)
        shown_operation=$(sed -n 's/^operation=//p' "$marker" 2>/dev/null | tail -n1)
        [[ "$shown_version" =~ ^[A-Za-z0-9._-]{1,40}$ ]] || shown_version=invalid
        [[ "$shown_operation" =~ ^[A-Za-z0-9._-]{1,80}$ ]] || shown_operation=invalid
        error "存在严重恢复标记，但不是受支持的一键升级事务：version=$shown_version operation=$shown_operation"
        error '支持自动恢复E222/E224/E226/E228/E230的精确auto-upgrade快照；其他事务拒绝猜测。'
        error '请保留标记与快照，可先运行 --recovery-status 查看只读诊断。'
        return 1
    }
    IFS='|' read -r prior_version prior_operation snapshot <<<"$record"
    [[ "$prior_version" =~ ^199e(222|224|226|228|230)$ ]] \
      && [[ "$prior_operation" =~ ^e(222|224|226|228|230)-auto-upgrade(-interrupted|-unexpected)?$ ]] \
      && test -n "$snapshot" || return 1
    candidate=$(_e230_mss_recovery_candidate) || return 1
    if test "$candidate" != none; then
        case "$candidate" in recover\|/*) recovery_tx=${candidate#recover|} ;; *) return 1 ;; esac
        warn "先恢复${prior_version}失败路径留下的唯一MSS事务：$recovery_tx"
        _e230_mss_recover_force "$recovery_tx" || return 1
    fi
    warn "重新读回${prior_version}一键升级起点快照：$snapshot"
    _e230_restore_outer "$snapshot" "previous-${prior_version}-auto" || return 1
    parent=${snapshot%/system}
    rm -f -- "$marker" "$parent/.preserve.env" "$parent/.active.env" \
      || return 1
    info "${prior_version}失败事务已恢复并关闭严重标记；保留快照供审计：$snapshot"
}

_e230_auto_preflight() {
    local owner="${1:-}" old_version="${2:-}" generation="" iface="" tmp=""
    test "$EUID" -eq 0 || { error 'E230自动升级必须使用root。'; return 1; }
    bash -n "$SCRIPT_PATH" || return 1
    test "$SCRIPT_VERSION" = "$E230_VERSION" || return 1
    if test -n "$old_version"; then
        generation=${old_version##*e}
        [[ "$generation" =~ ^[0-9]+$ ]] || return 1
        ((generation <= 230)) || {
            error "已安装版本$old_version比E230更新，拒绝降级覆盖。"
            return 1
        }
    fi
    _e230_structure_audit >/dev/null || {
        error 'E230发布结构门禁失败，自动升级尚未开始。'; return 1;
    }
    _e230_non_mss_critical_preflight || return 1
    _e230_mss_plan_readonly >/dev/null || return 1
    if _e214_mtu_any_state; then _e214_mtu_persistence_validate || return 1; fi
    command -v systemd-run >/dev/null 2>&1 || {
        error '自动MTU=1350需要systemd-run提供独立断线回滚；当前不可用。'
        return 1
    }
    iface=$(_e214_mtu_default_iface 2>/dev/null || true)
    _e214_mtu_iface_candidate "$iface" || {
        error '未识别到可安全管理的宿主机默认出口；自动升级尚未开始。'
        return 1
    }
    if test -n "$owner"; then
        test -n "$old_version" && _e230_old_script_can_exit_owner "$owner" "$old_version" || {
            error "活动小BBR所有者=$owner，但已安装xrv版本=${old_version:-不可验证}不能证明可安全退出它。"
            error '未修改网络；请保留并使用该小BBR所属旧版脚本退出。'
            return 1
        }
    else
        tmp=$(mktemp /tmp/xray-e230-preflight-profile.XXXXXX) || return 1
        if ! _e230_inactive_small_profile "$tmp"; then
            rm -f -- "$tmp"
            return 1
        fi
        rm -f -- "$tmp"
    fi
}

_e230_auto_verify() {
    local expected_profile="${1:-}" expected_mss="${2:-}" independent="${3:-}"
    _e214_hot_verify || return 1
    _e230_workflow_managed || return 1
    test -n "$expected_profile" && _e202_small_bbr_validate_file "$expected_profile" || return 1
    _e202_small_bbr_active || return 1
    _e202_small_bbr_status >/dev/null || return 1
    cmp -s "$expected_profile" "$E202_SMALL_CONF" || {
        error '自动升级后活动小BBR与计划档位不一致。'
        return 1
    }
    _e230_mtu_target_verify "$E230_TARGET_MTU" || return 1
    _e230_post_config_reconcile || return 1
    test -n "$independent" && _e230_independent_state_verify "$independent" || return 1
    _e230_mss_verify_intent "$expected_mss" || {
        error "自动升级后MSS意图读回失败：expected=${expected_mss:-missing}"
        return 1
    }
}

_e230_auto_upgrade() (
    local reboot_after="${1:-0}" owner="" old_version="" tx="" profile="" pending="" independent=""
    local had_small=0 rc=0 finished=0 restore_rc=0 workflow=full28 snapshot_ready=0
    local auto_lock_fd="" mss_plan="" mss_expected="" recovery="" recovery_tx=""
    local auto_log="$E230_AUTO_LOG"
    # Keep the new outer lock inside the root-only E214 transaction root.  The
    # historical /run/lock directory is commonly 1777 on Debian and must not
    # be used for a new predictable root redirection.  Test overrides are
    # accepted only behind the internal release-gate flag.
    local lock_path="$E214_TX_ROOT/.e230-auto-upgrade.lock"
    if test "${E230_INTERNAL_SELF_TEST:-0}" = 1; then
        lock_path="${E230_AUTO_LOCK_PATH:-$lock_path}"
        auto_log="${E230_AUTO_LOG_PATH:-$auto_log}"
    fi
    _e230_auto_exit_guard() {
        local status="${1:-1}" guard_restore_rc=0
        trap - EXIT HUP INT TERM
        rm -f -- "${profile:-}" "${pending:-}" 2>/dev/null || true
        if test "$snapshot_ready" -eq 1 && test "$finished" -eq 0 && test -n "$tx"; then
            error 'E230自动升级意外退出，执行升级起点总回滚。'
            _e230_restore_outer "$tx/system" auto-upgrade-unexpected || guard_restore_rc=1
            _e214_tx_close "$tx" || true
            test "$status" -ne 0 || status=1
            test "$guard_restore_rc" -eq 0 || status=1
        elif test "$finished" -eq 0 && test -n "$tx"; then
            _e214_tx_close "$tx" || true
        fi
        [[ "$status" =~ ^[0-9]+$ ]] || status=1
        exit "$status"
    }
    trap '_e230_auto_exit_guard $?' EXIT
    trap 'exit 129' HUP; trap 'exit 130' INT; trap 'exit 143' TERM
    test "$EUID" -eq 0 || { error 'E230自动升级必须使用root。'; return 1; }
    _e230_prepare || return 1
    # Direct CLI entry points bypass the interactive `preflight` dispatcher.
    # Acquire (or reuse) the process-wide xrv lock here before any recovery or
    # network mutation so fd 9 is always available for the old-owner handoff.
    _e118_runtime_init || return 1
    if test -e "$auto_log" || test -L "$auto_log"; then
        test -f "$auto_log" && test ! -L "$auto_log" \
          && test "$(stat -c %u "$auto_log" 2>/dev/null || true)" = 0 || {
            error "E230自动升级日志路径不是可信root普通文件：$auto_log"
            return 1
        }
    fi
    (umask 077; : >"$auto_log") && chmod 0600 "$auto_log" || {
        error "无法创建E230自动升级阶段日志：$auto_log"
        return 1
    }
    _e214_prepare_tx || return 1
    exec {auto_lock_fd}>"$lock_path" || return 1
    flock -n "$auto_lock_fd" || { error '已有E230自动升级事务正在运行。'; return 1; }
    _e230_recover_previous_failed_auto || return 1
    owner=$(_e230_active_small_owner)
    old_version=$(_e230_installed_version 2>/dev/null || true)
    _e230_auto_preflight "$owner" "$old_version" || return 1
    mss_plan=$(_e230_mss_plan_readonly) || return 1
    if test "$mss_plan" = recover; then
        recovery=$(_e230_mss_recovery_candidate) || return 1
        case "$recovery" in recover\|/*) recovery_tx=${recovery#recover|} ;; *) return 1 ;; esac
        warn "检测到可验证且进程已结束的旧MSS事务，将先按其持久快照自动恢复：$recovery_tx"
        _e230_mss_recover_force "$recovery_tx" || return 1
        # Recovery is its own durable transaction.  The outer upgrade starts
        # from the recovered stable point and never recreates a stale marker.
        _e214_critical_preflight || return 1
        mss_plan=$(_e230_mss_plan_readonly) || return 1
        test "$mss_plan" != recover || return 1
    fi
    mss_expected=$(_e230_mss_expected_from_plan "$mss_plan") || return 1
    tx=$(_e214_new_tx auto-upgrade-e230) || return 1
    _e140_system_snapshot "$tx/system" || return 1
    # Always seal exact MSS control/rule state.  Even a steady MSS intent can
    # be changed by the old small-BBR baseline restore which follows.
    _e230_mss_outer_capture "$tx/system" "$mss_plan" || rc=1
    independent="$tx/e230-independent"
    test "$rc" -ne 0 || _e230_independent_state_capture "$independent" || rc=1
    snapshot_ready=1
    {
        echo "time=$(date -Is 2>/dev/null || date)"
        echo "installed_version=${old_version:-unknown}"
        echo "small_owner=${owner:-none}"
        echo "target_mtu=$E230_TARGET_MTU"
        echo "mss_plan=$mss_plan"
        echo "mss_expected=$mss_expected"
    } >>"$auto_log" || {
        error "无法追加E230自动升级阶段日志：$auto_log"
        return 1
    }
    profile=$(mktemp /tmp/xray-e230-active-profile.XXXXXX) || rc=1
    if test -n "$owner"; then
        had_small=1
        test "$rc" -ne 0 || _e230_capture_active_small_profile "$owner" "$profile" || rc=1
        if test "$owner" = e202 && _e202_small_bbr_validate_file "$E202_SMALL_PROFILE"; then
            pending=$(mktemp /tmp/xray-e230-pending-profile.XXXXXX) || rc=1
            test "$rc" -ne 0 || cp -f -- "$E202_SMALL_PROFILE" "$pending" || rc=1
        fi
        test "$rc" -ne 0 || _e230_old_small_bbr_disable "$owner" "$old_version" || rc=1
        test "$rc" -ne 0 || test -z "$(_e230_active_small_owner)" || rc=1
    else
        test "$rc" -ne 0 || _e230_inactive_small_profile "$profile" || rc=1
    fi
    test "$rc" -ne 0 || _e230_independent_state_restore "$independent" || rc=1
    test "$rc" -ne 0 || _e230_mss_converge_expected "$mss_expected" || rc=1
    test "$rc" -ne 0 || _e214_hot_update_preflight || rc=1
    test "$rc" -ne 0 || _e214_hot_update || rc=1
    if test "$rc" -eq 0; then
        if _e140_full_mode_active; then
            workflow=app-only-host-full
            warn '检测到Cloudflare系统全隧道：保留其ip_forward/路由所有权，只重放第28项应用层，不写入互斥的完整网络档。'
            _e230_post_config_reconcile || rc=1
            test "$rc" -ne 0 || _e230_write_workflow_state "$workflow" || rc=1
        else
            _e159_apply_micro_28 || rc=1
        fi
    fi
    if test "$rc" -eq 0; then
        _e202_small_bbr_profile_save "$profile" || rc=1
        test "$rc" -ne 0 || _e202_small_bbr_enable force || rc=1
        if test "$rc" -eq 0 && test "$had_small" = 1 && test -n "$pending"; then
            _e202_small_bbr_profile_save "$pending" || rc=1
        fi
    fi
    test "$rc" -ne 0 || _e230_mtu_set_1350_auto || rc=1
    test "$rc" -ne 0 || _e230_auto_verify "$profile" "$mss_expected" "$independent" || rc=1
    if test "$rc" -ne 0; then
        error 'E230一键升级未完整通过，恢复升级开始前的脚本、网络、Xray与所有独立状态。'
        _e230_restore_outer "$tx/system" auto-upgrade || restore_rc=1
        finished=1
        _e214_tx_close "$tx" || true
        rm -f -- "${profile:-}" "${pending:-}" 2>/dev/null || true
        trap - EXIT HUP INT TERM
        return 1
    fi
    finished=1
    _e214_tx_close "$tx" || warn "自动升级已通过，但事务活动标记未关闭：$tx"
    rm -f -- "${profile:-}" "${pending:-}" 2>/dev/null || true
    trap - EXIT HUP INT TERM
    info 'V199e230一键升级完成：旧小BBR已安全退出，第28项、计划小BBR档位和默认出口MTU=1350均已自动提交。'
    info "MSS已按原意图保持并读回：$mss_expected；IPv6、WARP、Xray及节点配置均已通过最终读回。"
    if test "$reboot_after" = 1; then
        info '全部门禁通过，系统即将重启。'
        sync
        systemctl reboot || warn '自动重启命令未被systemd接受；升级已经提交，请人工执行 reboot。'
    else
        warn '本次未自动重启；建议确认当前SSH备用会话后执行 reboot。'
    fi
)

_e230_auto_upgrade_menu() {
    local choice="" token=""
    title 'V199e230：一键稳态升级'
    echo '  1) 旧小BBR安全退出 → 热更新 → 第28项 → 小BBR → MTU=1350 → 复检 → 重启（推荐）'
    echo '  2) 执行相同完整事务，但完成后不重启'
    echo '  0) 返回'
    read -rp '请选择: ' choice || true
    case "$choice" in
        1|2)
            warn 'E194及以后可验证活动档原样迁移；E190/E192旧6/13项档明确迁移到模式3F2。'
            warn '无活动档时应用有效保存档；没有保存档时也应用模式3F2。'
            warn 'MSS保持原意图；可验证旧事务/自有漂移会自动恢复或收敛，外部规则绝不删除。'
            warn '默认出口MTU固定事务设置为1350；任一后续阶段失败恢复升级起点。'
            read -rp '输入 AUTO-UPGRADE-E230 确认: ' token || true
            test "$token" = AUTO-UPGRADE-E230 || { info '已取消。'; return 0; }
            if test "$choice" = 1; then _e230_auto_upgrade 1; else _e230_auto_upgrade 0; fi
            ;;
        0|'') return 0 ;;
        *) warn '无效操作。'; return 1 ;;
    esac
}

_e230_upgrade_available() {
    local installed="" generation=""
    test -s "$CONFIG" || return 1
    installed=$(_e230_installed_version 2>/dev/null || true)
    test -n "$installed" && test "$installed" != "$E230_VERSION" || return 1
    generation=${installed##*e}
    [[ "$generation" =~ ^[0-9]+$ ]] && ((generation < 230))
}

_e230_default_entry() {
    local token="" rc=0
    if _e230_upgrade_available; then
        title 'V199e230：检测到旧环境'
        warn "已安装版本：$(_e230_installed_version)"
        echo '  将自动完成：旧小BBR退出、热更新、第28项、小BBR迁移/模式3F2、MTU=1350、全门禁和重启。'
        echo '  MSS保持原意图并自动收敛可证明漂移；外部规则不动。任一失败安全回滚。'
        read -rp '输入 AUTO-UPGRADE-E230 立即执行；直接回车进入普通菜单: ' token || true
        if test "$token" = AUTO-UPGRADE-E230; then
            _e230_auto_upgrade 1 || rc=$?
            test "$rc" -eq 0 || error '一键升级未完成；已按事务结果回滚或保留严重恢复标记。'
            return "$rc"
        fi
    fi
    main_menu
}

hot_update_from_legacy() { _e230_auto_upgrade_menu; }

_e230_structure_audit() {
    local rc=0 auto node users summary micro installer verify menu menu11 mtu dispatchers
    local mss_outer_line independent_capture_line old_disable_line independent_restore_line
    local mss_converge_line raw_preflight_line
    local independent_validator independent_restore previous_marker upgrade_available
    _e220_structure_audit >/dev/null || rc=1
    auto=$(declare -f _e230_auto_upgrade 2>/dev/null || true)
    node="$(declare -f _e182_install_mode 2>/dev/null || true)
$(declare -f _e230_install_mode_transaction 2>/dev/null || true)"
    users="$(declare -f do_user_manager 2>/dev/null || true)
$(declare -f _e230_user_manager_transaction 2>/dev/null || true)"
    summary=$(declare -f do_summary 2>/dev/null || true)
    micro=$(declare -f _e159_apply_micro_28 2>/dev/null || true)
    installer=$(declare -f _e214_install_self 2>/dev/null || true)
    verify=$(declare -f _e214_hot_verify 2>/dev/null || true)
    menu=$(declare -f _e214_main_menu 2>/dev/null || true)
    menu11=$(awk '
      /^[[:space:]]*11\)/ {capture=1; count=0}
      capture {print; count++}
      capture && count>=4 {exit}
    ' <<<"$menu")
    mtu=$(declare -f _e230_mtu_set_1350_auto 2>/dev/null || true)
    independent_validator=$(declare -f _e230_independent_state_validate 2>/dev/null || true)
    independent_restore=$(declare -f _e230_independent_state_restore 2>/dev/null || true)
    previous_marker=$(declare -f _e230_previous_auto_marker_snapshot 2>/dev/null || true)
    upgrade_available=$(declare -f _e230_upgrade_available 2>/dev/null || true)
    dispatchers=$(grep -c '^# V199e230 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true)
    echo 'V199e230 structure audit:'
    test "$SCRIPT_VERSION" = "$E230_VERSION" && test "$E214_VERSION" = "$E230_VERSION" \
      && test "$E220_VERSION" = "$E230_VERSION" || rc=1
    test "$dispatchers" -eq 1 || rc=1
    ! LC_ALL=C grep -q $'\r' "$SCRIPT_PATH" || rc=1
    grep -q '_e140_system_snapshot' <<<"$auto" || rc=1
    grep -q '_e230_old_small_bbr_disable' <<<"$auto" || rc=1
    grep -q -- '--source-only' <<<"$(declare -f _e230_old_small_bbr_disable 2>/dev/null || true)" || rc=1
    grep -q 'flock -n 0' <<<"$(declare -f _e230_old_small_bbr_disable 2>/dev/null || true)" || rc=1
    grep -q '_e159_apply_micro_28' <<<"$auto" || rc=1
    grep -q '_e202_small_bbr_enable force' <<<"$auto" || rc=1
    grep -q '_e230_mtu_set_1350_auto' <<<"$auto" || rc=1
    grep -q '_e230_mss_plan_readonly' <<<"$auto" || rc=1
    grep -q '_e230_mss_converge_expected' <<<"$auto" || rc=1
    grep -q '_e230_mss_outer_capture' <<<"$auto" || rc=1
    grep -q '_e230_independent_state_capture' <<<"$auto" || rc=1
    grep -q '_e230_independent_state_restore' <<<"$auto" || rc=1
    grep -q '_e230_mss_recover_force' <<<"$auto" || rc=1
    grep -q '_e230_auto_exit_guard' <<<"$auto" || rc=1
    grep -q '_e118_runtime_init' <<<"$auto" || rc=1
    grep -q 'exec {auto_lock_fd}' <<<"$auto" || rc=1
    ! grep -q 'exec 208>' <<<"$auto" || rc=1
    grep -q '_e230_xray_snapshot_validate' <<<"$independent_validator" || rc=1
    grep -q '_e230_xray_snapshot_restore' <<<"$independent_restore" || rc=1
    ! grep -q '_e127_verify_state_snapshot.*root/xray' <<<"$independent_validator$independent_restore" || rc=1
    grep -q '199e222.*e222-auto-upgrade' <<<"$previous_marker" || rc=1
    grep -q '199e228.*e228-auto-upgrade' <<<"$previous_marker" || rc=1
    grep -q 'generation < 230' <<<"$upgrade_available" || rc=1
    mss_outer_line=$(grep -n '_e230_mss_outer_capture' <<<"$auto" | head -n1 | cut -d: -f1 || true)
    independent_capture_line=$(grep -n '_e230_independent_state_capture' <<<"$auto" | head -n1 | cut -d: -f1 || true)
    old_disable_line=$(grep -n '_e230_old_small_bbr_disable' <<<"$auto" | tail -n1 | cut -d: -f1 || true)
    independent_restore_line=$(grep -n '_e230_independent_state_restore' <<<"$auto" | head -n1 | cut -d: -f1 || true)
    mss_converge_line=$(grep -n '_e230_mss_converge_expected' <<<"$auto" | head -n1 | cut -d: -f1 || true)
    raw_preflight_line=$(grep -n '_e214_hot_update_preflight' <<<"$auto" | head -n1 | cut -d: -f1 || true)
    if [[ "$mss_outer_line" =~ ^[0-9]+$ && "$independent_capture_line" =~ ^[0-9]+$ \
      && "$old_disable_line" =~ ^[0-9]+$ && "$independent_restore_line" =~ ^[0-9]+$ \
      && "$mss_converge_line" =~ ^[0-9]+$ && "$raw_preflight_line" =~ ^[0-9]+$ ]]; then
        ((mss_outer_line < independent_capture_line \
          && independent_capture_line < old_disable_line \
          && old_disable_line < independent_restore_line \
          && independent_restore_line < mss_converge_line \
          && mss_converge_line < raw_preflight_line)) || rc=1
    else
        rc=1
    fi
    grep -q '_e230_post_config_reconcile' <<<"$node$users" || rc=1
    grep -q '_e230_node_exit_guard' <<<"$node" || rc=1
    grep -q '_e230_user_exit_guard' <<<"$users" || rc=1
    grep -q 'E230_SUMMARY_SUPPRESS' <<<"$node$users$summary" || rc=1
    grep -q '_e230_summary_base' <<<"$summary" || rc=1
    grep -q '_e230_write_workflow_state' <<<"$micro" || rc=1
    grep -q 'E230_SELF_PATH' <<<"$installer$verify" || rc=1
    grep -q 'E230_LEGACY_E228_SELF_PATH' <<<"$installer$verify" || rc=1
    grep -q 'E230_LEGACY_E226_SELF_PATH' <<<"$installer$verify" || rc=1
    grep -q 'E230_LEGACY_E224_SELF_PATH' <<<"$installer$verify" || rc=1
    grep -q 'E230_LEGACY_E222_SELF_PATH' <<<"$installer" || rc=1
    grep -q '_e214_mtu_schedule_rollback' <<<"$mtu" || rc=1
    grep -q '_e214_mtu_commit' <<<"$mtu" || rc=1
    grep -q '_e230_mtu_target_verify' <<<"$mtu" || rc=1
    ! grep -q 'read -' <<<"$mtu" || rc=1
    grep -q 'V199e230' <<<"$menu" || rc=1
    grep -q 'hot_update_from_legacy || true' <<<"$menu11" || rc=1
    ! grep -Eq '(_e116_pause|read[[:space:]]+-r?p)' <<<"$menu11" || rc=1
    if test "$rc" -eq 0; then echo '  result=PASS'; else echo '  result=FAIL'; fi
    return "$rc"
}

_e230_auto_mock_self_test() (
    local d order bad_log mock_owner=e202 mock_mss_plan=steady-off recovery_pending=0 rc=0
    d=$(mktemp -d /tmp/xray-e230-auto-selftest.XXXXXX) || return 1
    trap 'rm -rf -- "$d"' EXIT
    order="$d/order"; : >"$order"
    E230_INTERNAL_SELF_TEST=1
    E230_AUTO_LOCK_PATH="$d/auto.lock"
    E230_AUTO_LOG_PATH="$d/auto.log"
    _e230_prepare() { echo release-prepare >>"$order"; }
    _e118_runtime_init() { echo global-lock >>"$order"; E118_RUNTIME_READY=1; }
    _e214_prepare_tx() { echo prepare >>"$order"; }
    _e230_recover_previous_failed_auto() { echo prior-recovery >>"$order"; }
    _e230_active_small_owner() { printf '%s\n' "$mock_owner"; }
    _e230_installed_version() { echo 199e220; }
    _e230_auto_preflight() { echo preflight >>"$order"; }
    _e230_mss_plan_readonly() {
        if test "$recovery_pending" -eq 1; then echo recover; else echo "$mock_mss_plan"; fi
    }
    _e230_mss_recovery_candidate() { echo 'recover|/var/backups/xray-mss-e220/mock'; }
    _e230_mss_recover_force() { recovery_pending=0; echo mss-recover >>"$order"; }
    _e214_critical_preflight() { echo critical-preflight >>"$order"; }
    _e230_mss_outer_capture() { echo mss-exact-snapshot >>"$order"; }
    _e230_independent_state_capture() { echo app-state-snapshot >>"$order"; }
    _e230_independent_state_restore() { echo app-state-restore >>"$order"; }
    _e230_mss_converge_expected() { echo "mss-converge-$1" >>"$order"; }
    _e214_new_tx() { install -d -m 0700 "$d/tx/system"; echo "$d/tx"; }
    _e140_system_snapshot() { install -d -m 0700 "$1"; echo snapshot >>"$order"; }
    _e230_capture_active_small_profile() { printf 'mock-profile\n' >"$2"; echo capture >>"$order"; }
    _e202_small_bbr_validate_file() { return 1; }
    _e230_old_small_bbr_disable() { echo disable >>"$order"; mock_owner=''; }
    _e214_hot_update_preflight() { echo raw-preflight >>"$order"; }
    _e214_hot_update() { echo raw-hot >>"$order"; }
    _e140_full_mode_active() { return 1; }
    _e159_apply_micro_28() { echo micro28 >>"$order"; }
    _e202_small_bbr_profile_save() { echo save-profile >>"$order"; }
    _e202_small_bbr_enable() { test "${1:-}" = force; echo enable >>"$order"; }
    _e230_mtu_set_1350_auto() { echo mtu1350 >>"$order"; }
    _e230_auto_verify() { test "$2" = off && test -n "$3"; echo verify >>"$order"; }
    _e214_tx_close() { echo close >>"$order"; }
    _e230_restore_outer() { echo restore >>"$order"; }
    _e230_auto_upgrade 0 >/dev/null 2>&1 || rc=1
    test -f "$d/auto.log" && test ! -L "$d/auto.log" \
      && test "$(stat -c %a "$d/auto.log" 2>/dev/null || true)" = 600 || rc=1
    test "$(paste -sd, "$order")" = \
      release-prepare,global-lock,prepare,prior-recovery,preflight,snapshot,mss-exact-snapshot,app-state-snapshot,capture,disable,app-state-restore,mss-converge-off,raw-preflight,raw-hot,micro28,save-profile,enable,mtu1350,verify,close || rc=1

    : >"$order"; bad_log="$d/bad-auto.log"
    ln -s /dev/null "$bad_log" || rc=1
    E230_AUTO_LOG_PATH="$bad_log"
    _e230_auto_upgrade 0 >/dev/null 2>&1 && rc=1 || true
    test "$(paste -sd, "$order")" = release-prepare,global-lock || rc=1
    E230_AUTO_LOG_PATH="$d/auto.log"

    : >"$order"; mock_owner=e202
    _e214_hot_update() { echo raw-hot-fail >>"$order"; return 1; }
    _e230_auto_upgrade 0 >/dev/null 2>&1 && rc=1 || true
    grep -q '^restore$' "$order" || rc=1
    test "$(grep -c '^close$' "$order")" -eq 1 || rc=1

    : >"$order"; mock_owner=e202
    _e214_hot_update_preflight() { echo raw-preflight-exit >>"$order"; exit 73; }
    _e214_hot_update() { echo raw-hot >>"$order"; }
    _e230_auto_upgrade 0 >/dev/null 2>&1 && rc=1 || true
    test "$(grep -c '^restore$' "$order")" -eq 1 || rc=1
    test "$(grep -c '^close$' "$order")" -eq 1 || rc=1

    : >"$order"; mock_owner=e202; recovery_pending=1; mock_mss_plan=repair-off
    _e214_hot_update_preflight() { echo raw-preflight >>"$order"; }
    _e214_hot_update() { echo raw-hot >>"$order"; }
    _e230_auto_upgrade 0 >/dev/null 2>&1 || rc=1
    test "$(paste -sd, "$order")" = \
      release-prepare,global-lock,prepare,prior-recovery,preflight,mss-recover,critical-preflight,snapshot,mss-exact-snapshot,app-state-snapshot,capture,disable,app-state-restore,mss-converge-off,raw-preflight,raw-hot,micro28,save-profile,enable,mtu1350,verify,close \
      || rc=1
    return "$rc"
)

_e230_mtu_auto_mock_self_test() (
    local d order rc=0 fail_commit=0 exit_commit=0
    d=$(mktemp -d /tmp/xray-e230-mtu-auto-selftest.XXXXXX) || return 1
    trap 'rm -rf -- "$d"' EXIT
    order="$d/order"; : >"$order"
    E230_INTERNAL_SELF_TEST=1
    E230_MTU_LOCK_PATH="$d/mtu-owner.lock"

    _e214_mtu_value_valid() { test "${1:-}" = 1350; }
    _e214_mtu_default_iface() { printf 'eth0\n'; }
    _e214_mtu_iface_candidate() { test "${1:-}" = eth0; }
    _e214_prepare() { echo prepare >>"$order"; }
    _e214_ensure_run_lock() { echo run-lock >>"$order"; }
    _e214_mtu_any_state() { return 1; }
    _e214_new_tx() {
        install -d -m 0700 "$d/tx/system"
        printf '%s\n' "$d/tx"
    }
    _e140_system_snapshot() { install -d -m 0700 "$1"; echo snapshot >>"$order"; }
    _e214_mtu_schedule_rollback() { echo schedule >>"$order"; }
    _e214_mtu_active() { return 1; }
    _e214_mtu_baseline_add() { printf 'eth0|1500\n' >>"$1"; echo baseline >>"$order"; }
    _e214_mtu_apply_runtime() { test "$1:$2" = eth0:1350; echo apply >>"$order"; }
    _e214_mtu_route_health() { test "$1:$2" = eth0:auto; echo route >>"$order"; }
    sleep() { test "${1:-}" = 3; echo wait >>"$order"; }
    systemctl() { return 1; }
    _e214_install_self() { echo install-self >>"$order"; }
    _e214_mtu_commit() {
        echo commit >>"$order"
        test "$exit_commit" -eq 0 || exit 74
        test "$fail_commit" -eq 0
    }
    _e230_mtu_target_verify() { test "${1:-}" = 1350; echo verify >>"$order"; }
    _e214_mtu_guard_confirm() { printf 'confirmed=1\n' >"$1"; echo confirm >>"$order"; }
    _e214_mtu_transient_stop() { echo stop >>"$order"; }
    _e214_tx_close() { echo close >>"$order"; }
    _e214_mtu_restore_guarded() {
        local restore_fd=""
        exec {restore_fd}>"$1/mtu-rollback.lock" || return 1
        flock -n "$restore_fd" || { echo restore-lock-blocked >>"$order"; return 1; }
        echo restore >>"$order"
        _e214_tx_close "$1"
    }

    _e230_mtu_set_1350_auto >/dev/null 2>&1 || rc=1
    test "$(paste -sd, "$order")" = \
      prepare,run-lock,snapshot,schedule,baseline,apply,route,wait,apply,route,install-self,commit,verify,confirm,stop,close \
      || rc=1

    : >"$order"; fail_commit=1
    _e230_mtu_set_1350_auto >/dev/null 2>&1 && rc=1 || true
    test "$(grep -c '^restore$' "$order")" -eq 1 || rc=1
    test "$(grep -c '^close$' "$order")" -eq 1 || rc=1
    grep -q '^commit$' "$order" || rc=1
    ! grep -q '^verify$' "$order" || rc=1

    : >"$order"; fail_commit=0; exit_commit=1
    _e230_mtu_set_1350_auto >/dev/null 2>&1 && rc=1 || true
    test "$(grep -c '^restore$' "$order")" -eq 1 || rc=1
    test "$(grep -c '^close$' "$order")" -eq 1 || rc=1
    ! grep -q '^restore-lock-blocked$' "$order" || rc=1
    return "$rc"
)

_e230_post_config_mock_self_test() (
    local d order config_rev=0 reconcile_fail=0 rc=0
    d=$(mktemp -d /tmp/xray-e230-post-config-selftest.XXXXXX) || return 1
    trap 'rm -rf -- "$d"' EXIT
    order="$d/order"; : >"$order"
    _e230_workflow_managed() { return 0; }
    _e214_new_tx() { install -d -m 0700 "$d/tx/system"; printf '%s\n' "$d/tx"; }
    _e140_system_snapshot() { install -d -m 0700 "$1"; echo snapshot >>"$order"; }
    _e230_config_sha() { printf 'rev-%s\n' "$config_rev"; }
    _e230_install_mode_base() { config_rev=$((config_rev + 1)); echo node-base >>"$order"; }
    _e230_user_manager_base() { config_rev=$((config_rev + 1)); echo user-base >>"$order"; }
    _e230_post_config_reconcile() {
        echo reconcile >>"$order"
        test "$reconcile_fail" -eq 0
    }
    do_summary() { echo summary >>"$order"; }
    _e214_tx_close() { echo close >>"$order"; }
    _e230_restore_outer() { echo restore >>"$order"; }

    _e230_install_mode_transaction 1 mock >/dev/null 2>&1 || rc=1
    test "$(paste -sd, "$order")" = snapshot,node-base,reconcile,summary,close || rc=1

    : >"$order"
    _e230_user_manager_transaction >/dev/null 2>&1 || rc=1
    test "$(paste -sd, "$order")" = snapshot,user-base,reconcile,summary,close || rc=1

    : >"$order"; reconcile_fail=1
    _e230_user_manager_transaction >/dev/null 2>&1 && rc=1 || true
    test "$(paste -sd, "$order")" = snapshot,user-base,reconcile,restore,close || rc=1

    : >"$order"; reconcile_fail=0
    _e230_user_manager_base() { echo user-exit >>"$order"; exit 72; }
    _e230_user_manager_transaction >/dev/null 2>&1 && rc=1 || true
    test "$(paste -sd, "$order")" = snapshot,user-exit,restore,close || rc=1
    return "$rc"
)

_e230_entry_mock_self_test() (
