_e230_mss_auto_mock_self_test() (
    local d live pid start mock_recovery=none mock_state=OFF
    local consistent=1 complete_on=0 verify_fail_once=0 plan order exact snapshot rc=0
    d=$(mktemp -d /tmp/xray-e230-mss-auto-selftest.XXXXXX) || return 1
    trap 'rm -rf -- "$d"' EXIT
    E230_INTERNAL_SELF_TEST=1

    # A live E220 record must remain live when read by E230.
    live="$d/live"; install -d -m 0700 "$live" || return 1
    pid=1; start=$(_e214_proc_start_time "$pid") || return 1
    test -n "$start" || return 1
    {
        echo version=199e220
        echo "pid=$pid"
        echo "start=$start"
        echo purpose=enable
        echo created_epoch=1780000000
    } >"$live/.active.env"
    _e230_mss_active_record_validate "$live/.active.env" || rc=1
    _e230_mss_tx_live "$live" || rc=1
    sed -i 's/version=199e220/version=199e219/' "$live/.active.env"
    ! _e230_mss_active_record_validate "$live/.active.env" || rc=1

    _e230_mss_recovery_candidate() { printf '%s\n' "$mock_recovery"; }
    _e230_mss_control_types_safe() { return 0; }
    _e218_mss_owner_state() { printf '%s\n' "$mock_state"; }
    _e218_mss_consistency() { test "$consistent" -eq 1; }
    _e230_mss_complete_on_without_legacy() { test "$complete_on" -eq 1; }
    _e220_mss_unowned_direct_report() { return 0; }

    plan=$(_e230_mss_plan_readonly) || rc=1
    test "$plan" = steady-off || rc=1
    consistent=0
    plan=$(_e230_mss_plan_readonly) || rc=1
    test "$plan" = repair-off || rc=1
    mock_state=ON
    plan=$(_e230_mss_plan_readonly) || rc=1
    test "$plan" = repair-on || rc=1
    mock_state=UNSET; complete_on=1
    plan=$(_e230_mss_plan_readonly) || rc=1
    test "$plan" = repair-on || rc=1
    mock_recovery='recover|/var/backups/xray-mss-e220/mock'
    plan=$(_e230_mss_plan_readonly) || rc=1
    test "$plan" = recover || rc=1

    order="$d/order"; : >"$order"
    _e218_mss_disable() { echo disable >>"$order"; }
    _e218_mss_enable() { echo enable >>"$order"; }
    _e230_mss_verify_intent() {
        echo "verify-$1" >>"$order"
        if test "$verify_fail_once" -eq 1; then verify_fail_once=0; return 1; fi
        return 0
    }
    _e230_mss_reconcile_plan repair-off >/dev/null 2>&1 || rc=1
    test "$(paste -sd, "$order")" = disable,verify-off || rc=1
    : >"$order"
    _e230_mss_reconcile_plan repair-on >/dev/null 2>&1 || rc=1
    test "$(paste -sd, "$order")" = disable,enable,verify-on || rc=1
    : >"$order"; verify_fail_once=1
    _e230_mss_converge_expected off >/dev/null 2>&1 || rc=1
    test "$(paste -sd, "$order")" = verify-off,disable,verify-off || rc=1
    : >"$order"; verify_fail_once=1
    _e230_mss_converge_expected on >/dev/null 2>&1 || rc=1
    test "$(paste -sd, "$order")" = verify-on,disable,enable,verify-on || rc=1

    # The exact snapshot is generated at its final path so embedded absolute
    # manifest paths remain valid.  Metadata accepts no duplicate/extra key.
    _e220_mss_capture_control() {
        install -d -m 0700 "$1/control"; printf '%s\n' "$1/control/mock" >"$1/control/manifest"
        echo control >>"$order"
    }
    _e220_mss_capture_backends() {
        printf 'iptables|id|save|save-id|restore|restore-id|%s/firewall-1.rules\n' "$1" >"$2"
        echo backends >>"$order"
    }
    _e220_mss_control_validate() { return 0; }
    _e220_mss_backends_validate() { return 0; }
    snapshot="$d/system"; install -d -m 0700 "$snapshot"; : >"$order"
    _e230_mss_outer_capture "$snapshot" repair-off || rc=1
    exact="$snapshot/e230-mss-exact"
    test -d "$exact" && grep -Fq "$exact/control/mock" "$exact/control/manifest" \
      && grep -Fq "$exact/firewall-1.rules" "$exact/backends.tsv" || rc=1
    test -z "$(find "$snapshot" -maxdepth 1 -name '.e230-mss-exact.tmp.*' -print -quit)" || rc=1
    _e230_mss_outer_validate "$exact" || rc=1
    sed -i 's/^plan=repair-off$/plan=steady-off/' "$exact/outer.env"
    (cd "$exact" && sha256sum outer.env >outer.sha256)
    _e230_mss_outer_validate "$exact" || rc=1
    printf 'unexpected=1\n' >>"$exact/outer.env"
    (cd "$exact" && sha256sum outer.env >outer.sha256)
    ! _e230_mss_outer_validate "$exact" || rc=1
    sed -i '/^unexpected=/d' "$exact/outer.env"
    (cd "$exact" && sha256sum outer.env >outer.sha256)

    : >"$order"
    _e218_mss_stop_triggers() { echo stop >>"$order"; }
    _e220_mss_restore_control_files() { echo files >>"$order"; }
    _e220_mss_restore_control_services() { echo services >>"$order"; }
    _e220_mss_restore_backends() { echo backends-restore >>"$order"; }
    _e220_mss_backends_match() { echo backends-match >>"$order"; }
    _e220_mss_control_matches() { echo control-match >>"$order"; }
    _e230_mss_outer_restore "$exact" || rc=1
    test "$(paste -sd, "$order")" = \
      stop,files,services,backends-restore,backends-match,control-match || rc=1
    return "$rc"
)

_e230_old_owner_handoff_mock_self_test() (
    local d fixture marker rc=0
    d=$(mktemp -d /tmp/xray-e230-old-handoff.XXXXXX) || return 1
    trap 'rm -rf -- "$d"' EXIT
    fixture="$d/ex199e220.sh"; marker="$d/disabled"
    {
        printf '%s\n' '#!/usr/bin/env bash'
        printf '%s\n' 'if test "${BASH_SOURCE[0]}" = "$0"; then'
        printf '%s\n' '  test "${1:-}" = --version && { echo 199e220; exit 0; }'
        printf '%s\n' '  exit 2'
        printf '%s\n' 'fi'
        printf '%s\n' 'E118_TMPDIR=""'
        printf '%s\n' 'E118_RUNTIME_READY=0'
        printf '%s\n' '_e202_small_bbr_disable() {'
        printf '%s\n' '  test "${1:-}" = force || return 1'
        printf '%s\n' '  test "$E118_RUNTIME_READY" = 1 || return 1'
        printf '%s\n' '  test -d "$E118_TMPDIR" || return 1'
        printf '%s\n' '  flock -n 0 || return 1'
        printf '%s\n' '  printf disabled >"$E230_HANDOFF_MARKER"'
        printf '%s\n' '}'
    } >"$fixture" || return 1
    chmod 0755 "$fixture" || return 1
    export E230_HANDOFF_MARKER="$marker"
    _e230_installed_script_real() { printf '%s\n' "$fixture"; }
    exec 9>"$d/global.lock" || return 1
    flock -n 9 || return 1
    _e230_old_small_bbr_disable e202 199e220 >/dev/null 2>&1 || rc=1
    test "$(cat "$marker" 2>/dev/null || true)" = disabled || rc=1
    # The parent still owns the very same lock after the child exits.
    flock -n 9 || rc=1
    return "$rc"
)

_e230_mss_scoped_match_mock_self_test() (
    local d list snapshot rc=0 mode=full mismatch=0
    d=$(mktemp -d /tmp/xray-e230-mss-scope.XXXXXX) || return 1
    trap 'rm -rf -- "$d"' EXIT
    snapshot="$d/firewall-1.rules"; list="$d/backends.tsv"
    : >"$snapshot"
    printf 'iptables|id|/bin/false|save-id|/bin/false|restore-id|%s\n' "$snapshot" >"$list"
    _e220_mss_backends_validate() { return 0; }
    _e220_mss_signature() {
        test "$mismatch" -eq 0 || { echo '-N WRONG'; return 0; }
        printf '%s\n' \
          "-A $E216_MSS_CHAIN -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu" \
          '-A POSTROUTING -j XRAY_MSS_CLAMP' \
          '-N XRAY_MSS_CLAMP' | LC_ALL=C sort
    }
    _e230_mss_signature_legacy() {
        printf '%s\n' '-A POSTROUTING -j XRAY_MSS_CLAMP' '-N XRAY_MSS_CLAMP' \
          | LC_ALL=C sort
    }
    _e220_mss_signature iptables >"$snapshot.mss"
    _e220_mss_backends_match "$d" "$list" || rc=1
    _e230_mss_signature_legacy iptables >"$snapshot.mss"
    _e220_mss_backends_match "$d" "$list" || rc=1
    _e220_mss_signature iptables >"$snapshot.mss"
    mismatch=1
    _e220_mss_backends_match "$d" "$list" >/dev/null 2>&1 && rc=1 || true
    return "$rc"
)

_e230_previous_marker_mock_self_test() (
    local d root tx marker pid start got rc=0 version operation suffix spec
    d=$(mktemp -d /tmp/xray-e230-previous-marker.XXXXXX) || return 1
    trap 'rm -rf -- "$d"' EXIT
    root="$d/txroot"; marker="$d/critical.env"
    for spec in \
      '199e222|e222-auto-upgrade|e222' \
      '199e222|e222-auto-upgrade-interrupted|e222' \
      '199e224|e224-auto-upgrade-unexpected|e224' \
      '199e226|e226-auto-upgrade|e226' \
      '199e228|e228-auto-upgrade-unexpected|e228' \
      '199e230|e230-auto-upgrade|e230'; do
        IFS='|' read -r version operation suffix <<<"$spec"
        tx="$root/auto-upgrade-${suffix}-20260821_220000-1-2"
        install -d -m 0700 "$tx/system" || return 1
        {
            echo "version=$version"
            echo 'time=2026-08-21 22:00:00 +0000'
            echo "operation=$operation"
            echo "backup=$tx/system"
            echo 'reason=mock rollback mismatch'
        } >"$marker"
        got=$(_e230_previous_auto_marker_snapshot "$marker" "$root") || rc=1
        test "$got" = "$version|$operation|$tx/system" || rc=1
    done
    # PID 1 is stable inside every supported namespace and lets this gate test
    # a genuinely live owner without depending on an execution wrapper PID.
    pid=1; start=$(_e214_proc_start_time "$pid") || return 1
    printf 'pid=%s\nstart=%s\n' "$pid" "$start" >"$tx/.active.env"
    _e230_previous_auto_marker_snapshot "$marker" "$root" >/dev/null 2>&1 && rc=1 || true
    printf 'pid=%s\nstart=%s\n' "$pid" "$((start + 1))" >"$tx/.active.env"
    _e230_previous_auto_marker_snapshot "$marker" "$root" >/dev/null || rc=1
    sed -i 's/operation=e230-auto-upgrade/operation=unrelated/' "$marker"
    _e230_previous_auto_marker_snapshot "$marker" "$root" >/dev/null 2>&1 && rc=1 || true
    sed -i 's/operation=unrelated/operation=e228-auto-upgrade/' "$marker"
    _e230_previous_auto_marker_snapshot "$marker" "$root" >/dev/null 2>&1 && rc=1 || true
    tx="$root/auto-upgrade-e228-20260821_220000-9-9"
    install -d -m 0700 "$tx/system" || return 1
    {
        echo version=199e228
        echo 'time=2026-08-21 22:00:00 +0000'
        echo operation=e228-auto-upgrade
        echo "backup=$tx/system"
        echo 'reason=mock rollback mismatch'
    } >"$marker"
    : >"$tx/.preserve.env"
    E230_INTERNAL_SELF_TEST=1
    _e230_mss_recovery_candidate() { printf 'none\n'; }
    _e230_restore_outer() { test "$1" = "$tx/system" && printf '%s\n' "$1" >"$d/restored"; }
    _e230_recover_previous_failed_auto "$marker" "$root" >/dev/null || rc=1
    test "$(cat "$d/restored" 2>/dev/null || true)" = "$tx/system" || rc=1
    test ! -e "$marker" && test ! -e "$tx/.preserve.env" || rc=1
    return "$rc"
)

_e230_mss_idempotent_unit_mock_self_test() (
    local calls=0
    systemctl() { calls=$((calls + 1)); return 5; }
    _e230_mss_disable_units_idempotent || return 1
    test "$calls" -eq 4
)

_e230_independent_state_mock_self_test() (
    local d fixture snapshot warp_state wg_account wg_profile wg_endpoint ipv6_live=1 rc=0
    local initial_inbound initial_sni initial_time initial_pub
    local current_inbound current_sni current_time current_pub
    d=$(mktemp -d /tmp/xray-e230-independent.XXXXXX) || return 1
    trap 'rm -rf -- "$d"' EXIT
    E230_INTERNAL_SELF_TEST=1
    warp_state="$d/live/e139/warp-state.env"
    wg_account="$d/live/e185/warp-wgcf/wgcf-account.toml"
    wg_profile="$d/live/e185/warp-wgcf/wgcf-profile.conf"
    wg_endpoint="$d/live/e185/warp-wgcf/endpoint.env"
    fixture="$d/source"; snapshot="$d/independent"
    install -d -m 0700 "$(dirname "$warp_state")" "$(dirname "$wg_account")" "$fixture" || return 1
    initial_inbound=$(printf node-user-set | sha256sum | awk '{print $1}')
    initial_sni=$(printf sni-map | sha256sum | awk '{print $1}')
    initial_time=$(printf time-map | sha256sum | awk '{print $1}')
    initial_pub=$(printf public-key | sha256sum | awk '{print $1}')
    current_inbound=$initial_inbound; current_sni=$initial_sni
    current_time=$initial_time; current_pub=$initial_pub
    {
        echo route_enabled=1
        echo route_mode=global
        echo profile=global
        echo family=ipv4
        echo backend=xray-wg
        echo backend_request=xray-wg
    } >"$warp_state"
    printf 'account\n' >"$wg_account"
    printf 'profile\n' >"$wg_profile"
    printf 'endpoint=162.159.192.1:2408\n' >"$wg_endpoint"
    printf 'mock snapshot\n' >"$fixture/config.json"
    printf 'config.json\n' >"$fixture/files.manifest"
    {
        echo 'created_at=2026-08-22 00:00:00'
        echo 'version=199e230'
        echo 'tag=mock'
        echo 'xray_was_active=0'
        echo 'xray_was_enabled=0'
        echo 'xray_enabled_state=disabled'
    } >"$fixture/meta.env"
    (cd "$fixture" && sha256sum config.json >files.sha256) || return 1
    (cd "$fixture" && find . -maxdepth 1 -type f ! -name snapshot-seal.sha256 \
        -printf '%P\0' | sort -z | xargs -0 sha256sum >snapshot-seal.sha256) || return 1
    chmod 0600 "$fixture"/*
    _e116_backup_state() { printf '%s\n' "$fixture"; }
    _e127_verify_state_snapshot() { test -d "$1" && test -f "$1/config.json"; }
    _e118_managed_state_files() { printf '%s\n' "$d/live/config.json"; }
    _e118_xray_test_config() { return 0; }
    _e118_atomic_install() {
        install -d -m 0700 "$(dirname -- "$2")" || return 1
        install -m "${3:-0600}" "$1" "$2" || return 1
        current_inbound=$initial_inbound; current_sni=$initial_sni
        current_time=$initial_time; current_pub=$initial_pub
    }
    fix_permissions() { return 0; }
    systemctl() {
        case "${1:-}" in
            is-enabled) printf 'disabled\n'; return 1 ;;
            is-active) return 3 ;;
            *) return 0 ;;
        esac
    }
    _e230_independent_file_target() {
        case "$1" in
            warp_state) echo "$warp_state" ;; wg_account) echo "$wg_account" ;;
            wg_profile) echo "$wg_profile" ;; wg_endpoint) echo "$wg_endpoint" ;;
            *) return 1 ;;
        esac
    }
    _e230_inbounds_digest() { printf '%s\n' "$current_inbound"; }
    _e230_file_digest() {
        case "$1" in
            "$USER_SNI_MAP") echo "$current_sni" ;; "$USER_TIME_MAP") echo "$current_time" ;;
            "$PUBKEY_FILE") echo "$current_pub" ;; *) return 1 ;;
        esac
    }
    _e138_state_get() {
        local key="$1" def="${2:-}" value
        value=$(sed -n "s/^${key}=//p" "$warp_state" 2>/dev/null | tail -n1)
        printf '%s\n' "${value:-$def}"
    }
    _e182_ipv6_policy_desired() { printf '%s\n' "$ipv6_live"; }
    _e138_warp_reconcile() { return 0; }
    _e182_ipv6_live_ssh_session() { return 1; }
    _e182_ipv6_apply() { ipv6_live="$1"; }
    _e182_ipv6_hot_verify() { test "$ipv6_live" = 1; }
    _e230_independent_state_capture "$snapshot" || rc=1
    _e230_independent_state_validate "$snapshot" || rc=1
    current_inbound=$(printf wrong-node | sha256sum | awk '{print $1}')
    current_sni=$(printf wrong-sni | sha256sum | awk '{print $1}')
    rm -f -- "$warp_state" "$wg_profile"
    ipv6_live=0
    _e230_independent_state_restore "$snapshot" || rc=1
    _e230_independent_state_verify "$snapshot" || rc=1
    current_inbound=$(printf lost-user | sha256sum | awk '{print $1}')
    _e230_independent_state_verify "$snapshot" >/dev/null 2>&1 && rc=1 || true
    return "$rc"
)

_e230_self_test() {
    local rc=0
    _e220_self_test || rc=1
    _e230_auto_mock_self_test && echo '  [PASS] E230 one-confirm order + MTU1350 + outer rollback' \
      || { echo '  [FAIL] E230 one-confirm transaction'; rc=1; }
    _e230_mtu_auto_mock_self_test && echo '  [PASS] E230 MTU1350 commit + injected-failure rollback' \
      || { echo '  [FAIL] E230 MTU1350 transaction'; rc=1; }
    _e230_post_config_mock_self_test && echo '  [PASS] E230 node/user post-profile gate + rollback' \
      || { echo '  [FAIL] E230 node/user post-profile transaction'; rc=1; }
    _e230_entry_mock_self_test && echo '  [PASS] E230 direct-run one-token upgrade / blank-menu split' \
      || { echo '  [FAIL] E230 direct-run entry'; rc=1; }
    _e230_mss_auto_mock_self_test && echo '  [PASS] E230 MSS drift plan/reconcile/cross-version/outer rollback' \
      || { echo '  [FAIL] E230 MSS automatic convergence'; rc=1; }
    _e230_old_owner_handoff_mock_self_test && echo '  [PASS] E230 old-owner inherited-lock handoff (no self-deadlock)' \
      || { echo '  [FAIL] E230 old-owner lock handoff'; rc=1; }
    _e230_mss_scoped_match_mock_self_test && echo '  [PASS] E230 MSS-owned rollback match + E220-E230 signature compatibility' \
      || { echo '  [FAIL] E230 MSS rollback scope'; rc=1; }
    _e230_previous_marker_mock_self_test && echo '  [PASS] E230 strict E222/E224/E226/E228/E230 failed-auto recovery gate' \
      || { echo '  [FAIL] E230 previous-auto marker gate'; rc=1; }
    _e230_mss_idempotent_unit_mock_self_test && echo '  [PASS] E230 missing legacy MSS units are idempotent OFF' \
      || { echo '  [FAIL] E230 missing-unit MSS cleanup'; rc=1; }
    _e230_independent_state_mock_self_test && echo '  [PASS] E230 preserves post-BBR nodes/users/WARP/IPv6 intent' \
      || { echo '  [FAIL] E230 independent application-state handoff'; rc=1; }
    _e230_structure_audit >/dev/null || rc=1
    if test "$rc" -eq 0; then echo 'V199e230 result: PASS'; else echo 'V199e230 result: FAIL'; fi
    return "$rc"
}

_e230_help() {
    _e220_help
    cat <<'EOF_E230_HELP'

E230新增：
  --auto-upgrade-reboot               一次确认完整升级、小BBR、MTU=1350并重启
  --auto-upgrade-no-reboot            相同完整事务，但不自动重启
  --hot-update-raw                    专家用原始热更新（要求小BBR已退出）

直接运行下载的E230时，如发现已安装旧版，只需输入一次AUTO-UPGRADE-E230。
可验证的E194+活动档由旧脚本安全退出并原样迁移；E190/E192旧6/13项
档明确迁移到模式3F2。无活动档时使用有效保存档，无保存档时也使用
模式3F2。MSS无需预先关闭：一致状态原样保留，可验证的旧中断事务先
恢复，脚本自有ON/OFF漂移在精确快照后自动收敛；外部TCPMSS规则不动。默认出口MTU自动
事务设置为1350。新建节点或修改用户后，第28项应用设置会自动重放，
最后验证Xray/WARP/IPv6/小BBR/MTU/MSS后才输出节点摘要与二维码。
EOF_E230_HELP
}

